	CONSTRAINT uq_user_account_referral_code UNIQUE (referral_code),
	CONSTRAINT ck_user_phone_verification CHECK (phone_verified = (phone_verified_at IS NOT NULL)),
	CONSTRAINT ck_user_anonymised_pii CHECK (anonymised_at IS NULL OR (full_name = '' AND email = '' AND password_hash = '' AND phone_e164 = 'anonymised:' || id::text))
);
