-- ddl-end --
COMMENT ON COLUMN iam.user_account.password_hash IS E'Argon2id';
-- ddl-end --
COMMENT ON COLUMN iam.user_account.phone_verified IS E'THE marketplace activation gate — FR-ACC-02';
