-- object: iam.otp_challenge | type: TABLE --
-- DROP TABLE IF EXISTS iam.otp_challenge CASCADE;
CREATE TABLE iam.otp_challenge (
	id uuid NOT NULL,
	user_id uuid,
	purpose text NOT NULL,
	destination text NOT NULL,
	code_hash text NOT NULL,
	expires_at timestamp with time zone NOT NULL,
	attempts smallint NOT NULL DEFAULT 0,
	superseded_at timestamp with time zone,
	consumed_at timestamp with time zone,
	issued_at timestamp with time zone NOT NULL DEFAULT now(),
	CONSTRAINT otp_challenge_pk PRIMARY KEY (id),
	CONSTRAINT ck_otp_purpose CHECK (purpose IN ('PHONE_VERIFICATION','PASSWORD_RESET','PHONE_CHANGE')),
	CONSTRAINT ck_otp_attempts CHECK (attempts BETWEEN 0 AND 5),
	CONSTRAINT ck_otp_validity CHECK (expires_at = issued_at + interval '5 minutes'),
	CONSTRAINT ck_otp_lifecycle CHECK ((consumed_at IS NULL OR superseded_at IS NULL) AND (consumed_at IS NULL OR (consumed_at >= issued_at AND consumed_at < expires_at)) AND (superseded_at IS NULL OR superseded_at >= issued_at))
);
-- ddl-end --
COMMENT ON TABLE iam.otp_challenge IS E'Rate limiting and audit share one row.\n\nSource/critical constraints:\n- ux_otp_active (destination, purpose)';
-- ddl-end --
COMMENT ON COLUMN iam.otp_challenge.user_id IS E'nullable — a destination may be challenged pre-account';
-- ddl-end --
COMMENT ON COLUMN iam.otp_challenge.purpose IS E'PHONE_VERIFICATION · PASSWORD_RESET · PHONE_CHANGE';
-- ddl-end --
COMMENT ON COLUMN iam.otp_challenge.code_hash IS E'never stored in clear';
-- ddl-end --
COMMENT ON COLUMN iam.otp_challenge.expires_at IS E'issued + 5 min — FR-ACC-04';
-- ddl-end --
COMMENT ON COLUMN iam.otp_challenge.attempts IS E'max 5 — FR-ACC-04';
-- ddl-end --
COMMENT ON COLUMN iam.otp_challenge.superseded_at IS E'a new OTP invalidates the previous';
-- ddl-end --
COMMENT ON COLUMN iam.otp_challenge.issued_at IS E'v1.1.27: send instant; resend after 60 s, max 5 sends/hour/destination, expires_at = issued_at + 5 min — FR-ACC-04';
-- ddl-end --
ALTER TABLE iam.otp_challenge OWNER TO postgres;
-- ddl-end --

