-- object: inventory.resource_reservation | type: TABLE --
-- DROP TABLE IF EXISTS inventory.resource_reservation CASCADE;
CREATE TABLE inventory.resource_reservation (
	id uuid NOT NULL,
	resource_id uuid NOT NULL,
	reservation_type text NOT NULL,
	booking_id uuid,
	tournament_id uuid,
	maintenance_id uuid,
	closure_id uuid,
	planned_start timestamp with time zone NOT NULL,
	planned_end timestamp with time zone NOT NULL,
	planned_range tstzrange NOT NULL,
	actual_reservation_start timestamp with time zone NOT NULL,
	actual_reservation_release_at timestamp with time zone,
	release_reason text,
	active_flag boolean NOT NULL DEFAULT true,
	version bigint NOT NULL DEFAULT 0,
	CONSTRAINT resource_reservation_pk PRIMARY KEY (id),
	CONSTRAINT ck_reservation_period CHECK (planned_end > planned_start),
	CONSTRAINT ck_reservation_active_release CHECK (active_flag = (actual_reservation_release_at IS NULL)),
	CONSTRAINT ck_reservation_release_reason CHECK (((actual_reservation_release_at IS NULL AND release_reason IS NULL) OR (actual_reservation_release_at IS NOT NULL AND release_reason IS NOT NULL))),
	CONSTRAINT ck_reservation_owner_shape CHECK (((reservation_type IN ('BOOKING','LATE_CONFIRM_HOLD') AND booking_id IS NOT NULL AND tournament_id IS NULL AND maintenance_id IS NULL AND closure_id IS NULL) OR (reservation_type IN ('TOURNAMENT_APPROVAL_HOLD','TOURNAMENT_HOLD') AND tournament_id IS NOT NULL AND booking_id IS NULL AND maintenance_id IS NULL AND closure_id IS NULL) OR (reservation_type='MAINTENANCE' AND maintenance_id IS NOT NULL AND booking_id IS NULL AND tournament_id IS NULL AND closure_id IS NULL) OR (reservation_type='CLOSURE' AND closure_id IS NOT NULL AND booking_id IS NULL AND tournament_id IS NULL AND maintenance_id IS NULL))),
	CONSTRAINT ck_reservation_type CHECK (reservation_type IN ('BOOKING','LATE_CONFIRM_HOLD','TOURNAMENT_APPROVAL_HOLD','TOURNAMENT_HOLD','MAINTENANCE','CLOSURE')),
	CONSTRAINT ck_reservation_planned_range CHECK (planned_range = tstzrange(planned_start, planned_end, '[)')),
	CONSTRAINT ck_reservation_release_chronology CHECK (actual_reservation_release_at IS NULL OR actual_reservation_release_at >= actual_reservation_start)
);
-- ddl-end --
COMMENT ON TABLE inventory.resource_reservation IS E'Canonical Resource occupancy ledger. A1 CLOSED: overlapping/back-to-back MAINTENANCE rows on the same Resource are allowed and rolling-48h authorization uses their continuous/unioned time. Cross-class conflicts remain enforced: commitments cannot overlap Maintenance/Closure; new Maintenance cannot overlap Closure or commitments; Closure may overlap existing Maintenance after affected commitments are explicitly resolved. The simple GiST exclusion alone MUST NOT be used to forbid Maintenance↔Maintenance.\n\nSource/critical constraints:\n- ex_no_double_booking: GiST exclusion on active non-MAINTENANCE planned_range rows\n- tr_resource_reservation_cross_class_guard: serializes resource scope and preserves MAINTENANCE↔MAINTENANCE allowance\n- ck_reservation_owner_shape (exactly one owner reference by reservation_type)\n- ck_reservation_planned_range (planned_range = [planned_start,planned_end))\n- ck_reservation_release_chronology';
-- ddl-end --
COMMENT ON COLUMN inventory.resource_reservation.reservation_type IS E'BOOKING · LATE_CONFIRM_HOLD · TOURNAMENT_APPROVAL_HOLD · TOURNAMENT_HOLD · MAINTENANCE · CLOSURE';
-- ddl-end --
COMMENT ON COLUMN inventory.resource_reservation.booking_id IS E'Nullable; owner for BOOKING/LATE_CONFIRM_HOLD.';
-- ddl-end --
COMMENT ON COLUMN inventory.resource_reservation.tournament_id IS E'Nullable; owner for Tournament holds.';
-- ddl-end --
COMMENT ON COLUMN inventory.resource_reservation.maintenance_id IS E'Nullable; owner for MAINTENANCE.';
-- ddl-end --
COMMENT ON COLUMN inventory.resource_reservation.closure_id IS E'Nullable; owner for derived CLOSURE guard row.';
-- ddl-end --
COMMENT ON COLUMN inventory.resource_reservation.planned_start IS E'IMMUTABLE planned start.';
-- ddl-end --
COMMENT ON COLUMN inventory.resource_reservation.planned_end IS E'IMMUTABLE planned end.';
-- ddl-end --
COMMENT ON COLUMN inventory.resource_reservation.planned_range IS E'DERIVED [planned_start,planned_end); trigger-maintained and CHECK-enforced.';
-- ddl-end --
COMMENT ON COLUMN inventory.resource_reservation.actual_reservation_start IS E'Usually creation/hold time.';
-- ddl-end --
COMMENT ON COLUMN inventory.resource_reservation.actual_reservation_release_at IS E'NULL while active.';
-- ddl-end --
COMMENT ON COLUMN inventory.resource_reservation.release_reason IS E'Required when released.';
-- ddl-end --
COMMENT ON COLUMN inventory.resource_reservation.active_flag IS E'Must equal (actual_reservation_release_at IS NULL).';
