	CONSTRAINT ck_emergency_status CHECK (status IN ('ACTIVE','AWAITING_CONFIRMATION','ENDED','CONVERTED')),
	CONSTRAINT ck_emergency_scope_shape CHECK ((scope = 'VENUE' AND resource_id IS NULL) OR (scope = 'RESOURCE' AND resource_id IS NOT NULL)),
	CONSTRAINT ck_emergency_conversion_target CHECK (converted_to IS NULL OR (scope = 'VENUE' AND converted_to IN ('CLOSURE','OPENING_HOURS_CHANGE')) OR (scope = 'RESOURCE' AND converted_to IN ('MAINTENANCE','DISABLED','ARCHIVED'))),
	CONSTRAINT ck_emergency_conversion_shape CHECK ((status = 'CONVERTED' AND converted_to IS NOT NULL) OR (status <> 'CONVERTED' AND converted_to IS NULL)),
	CONSTRAINT ck_emergency_time_order CHECK (expected_end_at > declared_at),
	CONSTRAINT ck_emergency_period_canonical CHECK (declared_period = tstzrange(declared_at, expected_end_at, '[)')),
	CONSTRAINT ck_emergency_reason_nonempty CHECK (length(btrim(reason)) > 0),
	CONSTRAINT ck_emergency_terminal_shape CHECK ((status IN ('ACTIVE','AWAITING_CONFIRMATION') AND ended_at IS NULL) OR (status IN ('ENDED','CONVERTED') AND ended_at IS NOT NULL AND ended_at >= declared_at))
);
