COMMENT ON COLUMN operations.emergency.scope IS E'VENUE · RESOURCE';
-- ddl-end --
COMMENT ON COLUMN operations.emergency.status IS E'ACTIVE · AWAITING_CONFIRMATION · ENDED · CONVERTED';
-- ddl-end --
COMMENT ON COLUMN operations.emergency.declared_at IS E'NOW only, never scheduled — FR-OPS-06';
-- ddl-end --
COMMENT ON COLUMN operations.emergency.expected_end_at IS E'mandatory, within the current session';
-- ddl-end --
COMMENT ON COLUMN operations.emergency.declared_period IS E'the cascade window';
-- ddl-end --
COMMENT ON COLUMN operations.emergency.reason IS E'mandatory';
-- ddl-end --
COMMENT ON COLUMN operations.emergency.converted_to IS E'CLOSURE · OPENING_HOURS_CHANGE · MAINTENANCE · DISABLED · ARCHIVED';
