	version bigint NOT NULL DEFAULT 0,
	CONSTRAINT booking_pk PRIMARY KEY (id),
	CONSTRAINT ck_booking_duration CHECK (nominal_booked_minutes BETWEEN 60 AND 360 AND MOD(nominal_booked_minutes,30)=0),
	CONSTRAINT ck_booking_terminal_reason CHECK (((status IN ('REJECTED','CANCELLED') AND terminal_reason IS NOT NULL) OR (status NOT IN ('REJECTED','CANCELLED') AND terminal_reason IS NULL))),
	CONSTRAINT ck_booking_source_values CHECK (source IN ('ONLINE','MANUAL')),
	CONSTRAINT ck_booking_status_values CHECK (status IN ('PENDING','VENUE_RESPONSE_EXPIRED','AWAITING_CUSTOMER_CONFIRMATION','CONFIRMED','ACTIVE','COMPLETED','REJECTED','CANCELLED','NO_SHOW')),
	CONSTRAINT ck_booking_activity_values CHECK (activity IN ('PLAYSTATION','BILLIARDS','PING_PONG')),
	CONSTRAINT ck_booking_snapshot_dimensions CHECK ((activity = 'PLAYSTATION' AND console_type IS NOT NULL AND play_mode IS NOT NULL AND console_type IN ('PS4','PS5') AND play_mode IN ('SINGLE','MULTIPLAYER')) OR (activity IN ('BILLIARDS','PING_PONG') AND console_type IS NULL AND play_mode IS NULL)),
	CONSTRAINT ck_booking_terminal_reason_values CHECK ((terminal_reason IS NULL OR terminal_reason IN ('CUSTOMER_CANCELLED','CUSTOMER_DECLINED_LATE_CONFIRM','CUSTOMER_RECONFIRM_TIMEOUT','VENUE_REJECTED','REJECTED_AFTER_EXPIRY','VENUE_CANCELLED_CONFIRMED_BOOKING','VENUE_CANCELLED_MANUAL_BOOKING','VENUE_DID_NOT_RESPOND_IN_TIME','VENUE_OPENING_HOURS_CHANGED','VENUE_CLOSURE','VENUE_EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','VENUE_RESPONSE_INTERRUPTED_BY_EMERGENCY','RESOURCE_RESPONSE_INTERRUPTED_BY_EMERGENCY','LATE_CONFIRM_INTERRUPTED_BY_EMERGENCY','RESOURCE_OWNER_REVIEW_REQUIRED','VENUE_ACCOUNT_DISABLED','SYSTEM_RESOURCE_STATE_INTEGRITY_ERROR','USER_BANNED','ADMIN_CANCELLED','ADMIN_CORRECTION','ADMIN_NO_SHOW_REVERSAL'))),
	CONSTRAINT ck_booking_online_customer CHECK (source <> 'ONLINE' OR customer_id IS NOT NULL),
	CONSTRAINT ck_booking_commitment_period_shape CHECK (((source = 'ONLINE' AND customer_id IS NOT NULL AND status IN ('PENDING','AWAITING_CUSTOMER_CONFIRMATION','CONFIRMED','ACTIVE') AND commitment_period IS NOT NULL AND commitment_period = tstzrange(start_at,end_at,'[)')) OR ((source <> 'ONLINE' OR customer_id IS NULL OR status NOT IN ('PENDING','AWAITING_CUSTOMER_CONFIRMATION','CONFIRMED','ACTIVE')) AND commitment_period IS NULL))),
	CONSTRAINT ck_booking_manual_states CHECK (source <> 'MANUAL' OR status IN ('CONFIRMED','ACTIVE','COMPLETED','CANCELLED')),
	CONSTRAINT ck_booking_terminal_at CHECK (((status IN ('COMPLETED','REJECTED','CANCELLED','NO_SHOW') AND terminal_at IS NOT NULL) OR (status NOT IN ('COMPLETED','REJECTED','CANCELLED','NO_SHOW') AND terminal_at IS NULL))),
	CONSTRAINT ck_booking_time_math CHECK (end_at = start_at + make_interval(mins => nominal_booked_minutes)),
	CONSTRAINT ck_booking_money_nonnegative CHECK (hourly_price_snapshot >= 0 AND venue_price_total >= 0 AND booking_fee_snapshot >= 0 AND total_amount >= 0),
	CONSTRAINT ck_booking_venue_price_math CHECK (venue_price_total = ROUND(hourly_price_snapshot * nominal_booked_minutes / 60.0, 2)),
	CONSTRAINT ck_booking_total_math CHECK (total_amount = venue_price_total + booking_fee_snapshot),
	CONSTRAINT ck_booking_fee_treatment_values CHECK (fee_treatment IS NULL OR fee_treatment IN ('FULL_REFUND','CUSTOMER_POLICY','NOT_APPLICABLE')),
	CONSTRAINT ck_booking_fee_treatment_scope CHECK (((status IN ('REJECTED','CANCELLED') AND fee_treatment IS NOT NULL) OR (status NOT IN ('REJECTED','CANCELLED') AND fee_treatment IS NULL))),
	CONSTRAINT ck_booking_manual_fee_zero CHECK (source <> 'MANUAL' OR booking_fee_snapshot = 0),
	CONSTRAINT ck_booking_reject_reason_text CHECK ((terminal_reason IS NOT DISTINCT FROM 'VENUE_REJECTED' AND NULLIF(BTRIM(venue_reject_reason_text),'') IS NOT NULL) OR (terminal_reason IS DISTINCT FROM 'VENUE_REJECTED' AND venue_reject_reason_text IS NULL)),
	CONSTRAINT ck_booking_pause_counters CHECK ((cumulative_emergency_pause_duration IS NULL OR (cumulative_emergency_pause_duration >= interval '0' AND cumulative_emergency_pause_duration <= interval '30 minutes')) AND (cumulative_late_confirm_emergency_pause_duration IS NULL OR (cumulative_late_confirm_emergency_pause_duration >= interval '0' AND cumulative_late_confirm_emergency_pause_duration <= interval '30 minutes'))),
	CONSTRAINT ck_booking_pause_state_scope CHECK ((response_pause_started_at IS NULL OR status = 'PENDING') AND (late_confirm_pause_started_at IS NULL OR status = 'AWAITING_CUSTOMER_CONFIRMATION'))
);
-- ddl-end --
COMMENT ON TABLE booking.booking IS E'Online + Manual share one aggregate. Source never decides inventory blocking; status does. Canonical terminal semantics: REJECTED/CANCELLED carry one closed Booking Reason Code; COMPLETED and NO_SHOW are terminal with NULL Booking Reason Code. NO_SHOW_RECORDED is a Booking Event and ABSENT_NO_SHOW is an Attendance Result; neither is a Booking Reason Code.\n\nSource/critical constraints:\n- ck_booking_terminal_reason + ck_booking_terminal_at\n- ck_booking_duration + ck_booking_time_math\n- ck_booking_manual_states\n- ck_booking_snapshot_dimensions\n- ck_booking_money_nonnegative + price/total arithmetic checks\n- ck_booking_fee_treatment_scope + ck_booking_manual_fee_zero + reason-map trigger\n- ck_booking_pause_counters + ck_booking_pause_state_scope\n- ex_customer_no_overlap EXCLUDE (customer_id =, commitment_period &&)\n- tr_booking_snapshot_integrity + tr_booking_historical_snapshot_immutable';
-- ddl-end --
COMMENT ON COLUMN booking.booking.customer_id IS E'NULL allowed for MANUAL — FR-MAN-01';
-- ddl-end --
COMMENT ON COLUMN booking.booking.source IS E'ONLINE · MANUAL';
-- ddl-end --
COMMENT ON COLUMN booking.booking.status IS E'PENDING · VENUE_RESPONSE_EXPIRED · AWAITING_CUSTOMER_CONFIRMATION · CONFIRMED · ACTIVE · COMPLETED · REJECTED · CANCELLED · NO_SHOW';
-- ddl-end --
COMMENT ON COLUMN booking.booking.activity IS E'historical snapshot.';
-- ddl-end --
COMMENT ON COLUMN booking.booking.console_type IS E'historical snapshot. snapshot — survives a later console change';
-- ddl-end --
COMMENT ON COLUMN booking.booking.play_mode IS E'historical snapshot.';
-- ddl-end --
COMMENT ON COLUMN booking.booking.resource_name_snapshot IS E'historical snapshot.';
-- ddl-end --
COMMENT ON COLUMN booking.booking.end_at IS E'start + nominal minutes, real elapsed';
-- ddl-end --
COMMENT ON COLUMN booking.booking.nominal_booked_minutes IS E'drives PRICE, never DST-adjusted';
-- ddl-end --
COMMENT ON COLUMN booking.booking.hourly_price_snapshot IS E'historical snapshot.';
-- ddl-end --
COMMENT ON COLUMN booking.booking.booking_fee_snapshot IS E'historical snapshot. EGP 0 at launch, snapshot at creation';
-- ddl-end --
COMMENT ON COLUMN booking.booking.fee_treatment IS E'Reason-to-treatment snapshot for REJECTED/CANCELLED outcomes. Values: FULL_REFUND · CUSTOMER_POLICY · NOT_APPLICABLE. COMPLETED/NO_SHOW have no Booking Reason Code and therefore no §34.2 reason treatment.';
-- ddl-end --
COMMENT ON COLUMN booking.booking.business_date IS E'the revenue-day key — ALWAYS present';
-- ddl-end --
COMMENT ON COLUMN booking.booking.operating_day IS E'NULL for manual outside published hours';
-- ddl-end --
COMMENT ON COLUMN booking.booking.operating_session_id IS E'Nullable for Manual Booking outside published Operating Sessions.';
-- ddl-end --
COMMENT ON COLUMN booking.booking.session_local_start IS E'historical snapshot.';
-- ddl-end --
COMMENT ON COLUMN booking.booking.session_local_end IS E'historical snapshot.';
-- ddl-end --
COMMENT ON COLUMN booking.booking.session_timezone IS E'historical snapshot.';
-- ddl-end --
COMMENT ON COLUMN booking.booking.venue_response_expires_at IS E'persisted 10-minute deadline';
-- ddl-end --
COMMENT ON COLUMN booking.booking.cumulative_emergency_pause_duration IS E'30-minute cap';
-- ddl-end --
COMMENT ON COLUMN booking.booking.cumulative_late_confirm_emergency_pause_duration IS E'30-minute cap';
-- ddl-end --
COMMENT ON COLUMN booking.booking.terminal_reason IS E'Required only for REJECTED/CANCELLED; NULL for COMPLETED/NO_SHOW and non-terminal states.';
-- ddl-end --
COMMENT ON COLUMN booking.booking.terminal_at IS E'drives phone retention';
-- ddl-end --
COMMENT ON COLUMN booking.booking.venue_reject_reason_text IS E'MANDATORY free text, separate from the code';
-- ddl-end --
COMMENT ON COLUMN booking.booking.commitment_period IS E'GENERATED — non-null only while counted';
-- ddl-end --
COMMENT ON COLUMN booking.booking.created_at IS E'Used by future 15-minute fee policy.';
-- ddl-end --
COMMENT ON COLUMN booking.booking.version IS E'Optimistic state version.';
-- ddl-end --
ALTER TABLE booking.booking OWNER TO postgres;
-- ddl-end --

-- object: booking.booking_history | type: TABLE --
-- DROP TABLE IF EXISTS booking.booking_history CASCADE;
CREATE TABLE booking.booking_history (
	id uuid NOT NULL,
	booking_id uuid NOT NULL,
	sequence bigint NOT NULL,
	occurred_at timestamp with time zone NOT NULL,
	entry_kind text NOT NULL,
	from_status varchar(80),
	to_status varchar(80),
	terminal_reason varchar(80),
	event_type varchar(80),
	detail_code varchar(80),
	actor_type text,
	actor_id uuid,
	correlation_id uuid NOT NULL,
	CONSTRAINT booking_history_pk PRIMARY KEY (id),
	CONSTRAINT uq_booking_history_seq UNIQUE (booking_id,sequence),
	CONSTRAINT ck_booking_history_entry_kind CHECK (entry_kind IN ('STATUS_TRANSITION','BOOKING_EVENT')),
	CONSTRAINT ck_booking_history_status_values CHECK ((from_status IS NULL OR from_status IN ('PENDING','VENUE_RESPONSE_EXPIRED','AWAITING_CUSTOMER_CONFIRMATION','CONFIRMED','ACTIVE','COMPLETED','REJECTED','CANCELLED','NO_SHOW')) AND (to_status IS NULL OR to_status IN ('PENDING','VENUE_RESPONSE_EXPIRED','AWAITING_CUSTOMER_CONFIRMATION','CONFIRMED','ACTIVE','COMPLETED','REJECTED','CANCELLED','NO_SHOW'))),
	CONSTRAINT ck_booking_history_terminal_reason_values CHECK ((terminal_reason IS NULL OR terminal_reason IN ('CUSTOMER_CANCELLED','CUSTOMER_DECLINED_LATE_CONFIRM','CUSTOMER_RECONFIRM_TIMEOUT','VENUE_REJECTED','REJECTED_AFTER_EXPIRY','VENUE_CANCELLED_CONFIRMED_BOOKING','VENUE_CANCELLED_MANUAL_BOOKING','VENUE_DID_NOT_RESPOND_IN_TIME','VENUE_OPENING_HOURS_CHANGED','VENUE_CLOSURE','VENUE_EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','VENUE_RESPONSE_INTERRUPTED_BY_EMERGENCY','RESOURCE_RESPONSE_INTERRUPTED_BY_EMERGENCY','LATE_CONFIRM_INTERRUPTED_BY_EMERGENCY','RESOURCE_OWNER_REVIEW_REQUIRED','VENUE_ACCOUNT_DISABLED','SYSTEM_RESOURCE_STATE_INTEGRITY_ERROR','USER_BANNED','ADMIN_CANCELLED','ADMIN_CORRECTION','ADMIN_NO_SHOW_REVERSAL'))),
	CONSTRAINT ck_booking_history_event_type_values CHECK ((event_type IS NULL OR event_type IN ('CHECK_IN_RECORDED','CHECK_IN_REVERSED','LATE_PRESENT_RECORDED','LATE_PRESENT_REVERSED','NO_SHOW_RECORDED','NO_SHOW_REVERSED','ATTENDANCE_CORRECTED','LATE_CONFIRM_FAILED_RESOURCE_CONFLICT','LATE_CONFIRM_FAILED_CUSTOMER_CONFLICT','LATE_CONFIRM_FAILED_BOOKING_LIMIT','LATE_CONFIRM_ELIGIBILITY_LOST_RESOURCE_STATE_CHANGED','VENUE_RESPONSE_INTERRUPTED_BY_ACCOUNT_DISABLE'))),
	CONSTRAINT ck_booking_history_entry_shape CHECK ((entry_kind = 'STATUS_TRANSITION' AND to_status IS NOT NULL AND event_type IS NULL AND detail_code IS NULL) OR (entry_kind = 'BOOKING_EVENT' AND event_type IS NOT NULL AND from_status IS NULL AND to_status IS NULL AND terminal_reason IS NULL)),
	CONSTRAINT ck_booking_history_transition_terminal_reason CHECK (entry_kind = 'BOOKING_EVENT' OR ((to_status IN ('REJECTED','CANCELLED') AND terminal_reason IS NOT NULL) OR (to_status NOT IN ('REJECTED','CANCELLED') AND terminal_reason IS NULL))),
	CONSTRAINT ck_booking_history_sequence_positive CHECK (sequence > 0),
	CONSTRAINT ck_booking_history_detail_code_scope CHECK ((event_type = 'LATE_CONFIRM_ELIGIBILITY_LOST_RESOURCE_STATE_CHANGED' AND detail_code IS NOT NULL AND detail_code IN ('RESOURCE_DISABLED','RESOURCE_ARCHIVED','RESOURCE_CONSOLE_CHANGED','RESOURCE_OWNER_REVIEW_REQUIRED')) OR (event_type IS DISTINCT FROM 'LATE_CONFIRM_ELIGIBILITY_LOST_RESOURCE_STATE_CHANGED' AND detail_code IS NULL)),
	CONSTRAINT ck_booking_history_actor_type_values CHECK (actor_type IS NULL OR actor_type IN ('CUSTOMER','VENUE','ADMIN','SYSTEM'))
);
-- ddl-end --
COMMENT ON TABLE booking.booking_history IS E'APPEND-ONLY Booking history; this physical table also stores the Architecture''s booking_event stream via entry_kind=BOOKING_EVENT. Booking Reason Codes, Booking Events and detailCode are separate closed domains.\n\nSource/critical constraints:\n- uq_history_seq\n- ck_entry_shape (status transitions and events never conflate)\n- ck_transition_terminal_reason (NO_SHOW has no Booking Reason Code)\n- ck_detail_code_scope\n- append-only mutation trigger';
-- ddl-end --
COMMENT ON COLUMN booking.booking_history.sequence IS E'monotonic per booking';
-- ddl-end --
COMMENT ON COLUMN booking.booking_history.entry_kind IS E'STATUS_TRANSITION · BOOKING_EVENT';
-- ddl-end --
COMMENT ON COLUMN booking.booking_history.event_type IS E'the 12 canonical booking events';
-- ddl-end --
COMMENT ON COLUMN booking.booking_history.detail_code IS E'REQUIRED with LATE_CONFIRM_ELIGIBILITY_LOST_RESOURCE_STATE_CHANGED; forbidden for all other Booking Events.';
-- ddl-end --
ALTER TABLE booking.booking_history OWNER TO postgres;
-- ddl-end --

-- object: booking.late_confirmation | type: TABLE --
-- DROP TABLE IF EXISTS booking.late_confirmation CASCADE;
CREATE TABLE booking.late_confirmation (
	id uuid NOT NULL,
	booking_id uuid NOT NULL,
	attempt_no smallint NOT NULL,
	initiated_at timestamp with time zone NOT NULL,
	expires_at timestamp with time zone NOT NULL,
	warning_sent_at timestamp with time zone,
	hold_reservation_id uuid NOT NULL,
	customer_response text,
	responded_at timestamp with time zone,
	closed_at timestamp with time zone,
	CONSTRAINT late_confirmation_pk PRIMARY KEY (id),
	CONSTRAINT uq_late_confirm_attempt UNIQUE (booking_id,attempt_no),
	CONSTRAINT uq_late_confirm_hold_reservation UNIQUE (hold_reservation_id),
	CONSTRAINT ck_late_confirmation_customer_response CHECK ((customer_response IS NULL OR customer_response IN ('ACCEPTED','DECLINED','TIMED_OUT'))),
	CONSTRAINT ck_late_confirmation_attempt_positive CHECK (attempt_no > 0),
	CONSTRAINT ck_late_confirmation_window_positive CHECK (expires_at > initiated_at),
	CONSTRAINT ck_late_confirmation_response_shape CHECK ((customer_response IS NULL AND responded_at IS NULL) OR (customer_response IN ('ACCEPTED','DECLINED') AND responded_at IS NOT NULL AND responded_at >= initiated_at AND responded_at < expires_at) OR (customer_response = 'TIMED_OUT' AND responded_at IS NOT NULL AND responded_at >= expires_at)),
	CONSTRAINT ck_late_confirmation_open_closed_shape CHECK ((closed_at IS NULL AND customer_response IS NULL AND responded_at IS NULL) OR (closed_at IS NOT NULL AND closed_at >= initiated_at AND ((customer_response IS NULL AND responded_at IS NULL) OR (customer_response IS NOT NULL AND responded_at IS NOT NULL AND closed_at >= responded_at)))),
	CONSTRAINT ck_late_confirmation_warning_time CHECK (warning_sent_at IS NULL OR (warning_sent_at >= initiated_at AND warning_sent_at < expires_at))
);
-- ddl-end --
COMMENT ON TABLE booking.late_confirmation IS E'Per-booking Late Confirmation state. The same Booking ID is retained. One open attempt per Booking is enforced physically by closed_at IS NULL; Customer response is a separate fact, so operational/system cancellation can close an attempt without inventing a Customer response. Each row owns one canonical LATE_CONFIRM_HOLD reservation for the same Booking/Resource/interval. Emergency pause/resume may move the persisted deadline but never beyond the original Booking startAt.\n\nSource/critical constraints:\n- uq_lc_attempt + uq_lc_hold_reservation\n- ux_lc_open (one closed_at IS NULL attempt per booking)\n- ck_lc_response_shape + ck_lc_open_closed_shape + positive attempt/window checks\n- exact initial five-minute expiry guard\n- deferred cross-surface Late Confirmation integrity against Booking + Inventory';
-- ddl-end --
COMMENT ON COLUMN booking.late_confirmation.booking_id IS E'SAME Booking ID — FR-LCF-08';
-- ddl-end --
COMMENT ON COLUMN booking.late_confirmation.expires_at IS E'MIN(now + 5 min, booking.start_at)';
-- ddl-end --
COMMENT ON COLUMN booking.late_confirmation.warning_sent_at IS E'only when the window > 60 s';
-- ddl-end --
COMMENT ON COLUMN booking.late_confirmation.customer_response IS E'ACCEPTED · DECLINED · TIMED_OUT';
-- ddl-end --
COMMENT ON COLUMN booking.late_confirmation.closed_at IS E'Implementation-only lifecycle marker. NULL means the Late Confirmation attempt is still open; non-NULL closes it for Customer response or any Product-defined operational/system cancellation. Not a Product status or reason.';
-- ddl-end --
ALTER TABLE booking.late_confirmation OWNER TO postgres;
-- ddl-end --

-- object: attendance.attendance_record | type: TABLE --
-- DROP TABLE IF EXISTS attendance.attendance_record CASCADE;
CREATE TABLE attendance.attendance_record (
	id uuid NOT NULL,
	booking_id uuid NOT NULL,
	result varchar(80),
	check_in_at timestamp with time zone,
	check_in_reversed_at timestamp with time zone,
	late_present_at timestamp with time zone,
	late_present_reversed_at timestamp with time zone,
	no_show_at timestamp with time zone,
	no_show_reversed_at timestamp with time zone,
	recorded_by_venue_account_id uuid,
	resolved_at timestamp with time zone,
	protection_applied boolean NOT NULL DEFAULT false,
	CONSTRAINT attendance_record_pk PRIMARY KEY (id),
	CONSTRAINT uq_attendance_booking UNIQUE (booking_id),
	CONSTRAINT ck_attendance_result_values CHECK (result IS NULL OR result IN ('ATTENDED','ATTENDANCE_UNCONFIRMED','ATTENDED_INTERRUPTED','ABSENT_NO_SHOW','NOT_APPLICABLE')),
	CONSTRAINT ck_attendance_resolution_shape CHECK ((result IS NULL AND resolved_at IS NULL) OR (result IS NOT NULL AND resolved_at IS NOT NULL)),
	CONSTRAINT ck_attendance_reversal_chronology CHECK ((check_in_reversed_at IS NULL OR (check_in_at IS NOT NULL AND check_in_reversed_at >= check_in_at)) AND (late_present_reversed_at IS NULL OR (late_present_at IS NOT NULL AND late_present_reversed_at >= late_present_at)) AND (no_show_reversed_at IS NULL OR (no_show_at IS NOT NULL AND no_show_reversed_at >= no_show_at))),
	CONSTRAINT ck_attendance_active_evidence_exclusive CHECK ((CASE WHEN check_in_at IS NOT NULL AND check_in_reversed_at IS NULL THEN 1 ELSE 0 END) + (CASE WHEN late_present_at IS NOT NULL AND late_present_reversed_at IS NULL THEN 1 ELSE 0 END) + (CASE WHEN no_show_at IS NOT NULL AND no_show_reversed_at IS NULL THEN 1 ELSE 0 END) <= 1),
	CONSTRAINT ck_attendance_venue_actor_presence CHECK ((check_in_at IS NULL AND late_present_at IS NULL AND no_show_at IS NULL) OR recorded_by_venue_account_id IS NOT NULL)
);
-- ddl-end --
COMMENT ON TABLE attendance.attendance_record IS E'Attendance evidence/current outcome row. result is NULL until the effective Attendance Result is resolved, then becomes historical Product data subject only to an explicitly audited Admin correction. Original evidence timestamps are one-way; approved reversal timestamps retain the original evidence instead of deleting it. Booking History + Audit Event remain the actor/reason authority for every attendance action/reversal/correction.\n\nHardening:\n- active Check-in / Late Present / No-show evidence is mutually exclusive\n- reversal timestamps require the original evidence and cannot predate it\n- cross-table guards enforce Product time windows, same-Venue actor, No-show atomic final state and audited corrections';
-- ddl-end --
COMMENT ON COLUMN attendance.attendance_record.booking_id IS E'UNIQUE — one Attendance state/evidence row per Booking';
-- ddl-end --
COMMENT ON COLUMN attendance.attendance_record.result IS E'NULL until resolved · ATTENDED · ATTENDANCE_UNCONFIRMED · ATTENDED_INTERRUPTED · ABSENT_NO_SHOW · NOT_APPLICABLE';
-- ddl-end --
COMMENT ON COLUMN attendance.attendance_record.check_in_at IS E'[start, start+15m); immutable once recorded';
-- ddl-end --
COMMENT ON COLUMN attendance.attendance_record.check_in_reversed_at IS E'Platform Admin only; one-way reversal marker; mandatory audited reason';
-- ddl-end --
COMMENT ON COLUMN attendance.attendance_record.late_present_at IS E'[start+15m, end); immutable once recorded';
-- ddl-end --
COMMENT ON COLUMN attendance.attendance_record.late_present_reversed_at IS E'Platform Admin only; one-way reversal marker; mandatory audited reason';
-- ddl-end --
COMMENT ON COLUMN attendance.attendance_record.no_show_at IS E'[start+15m, end); terminal No-show action';
-- ddl-end --
COMMENT ON COLUMN attendance.attendance_record.no_show_reversed_at IS E'Platform Admin only; one-way reversal marker; mandatory audited reason';
-- ddl-end --
COMMENT ON COLUMN attendance.attendance_record.recorded_by_venue_account_id IS E'Venue account for the most recently written original attendance evidence; full per-action actor history is authoritative in Booking History/Audit';
-- ddl-end --
COMMENT ON COLUMN attendance.attendance_record.resolved_at IS E'NULL while unresolved; moves forward only when an audited Admin correction changes result';
-- ddl-end --
COMMENT ON COLUMN attendance.attendance_record.protection_applied IS E'Historical flag: an effective BOOKING_ACCOUNT_DISABLE_ATTENDANCE_PROTECTION Trust event was emitted; never silently cleared';
-- ddl-end --
ALTER TABLE attendance.attendance_record OWNER TO postgres;
-- ddl-end --

-- object: attendance.attendance_protection_candidate | type: TABLE --
-- DROP TABLE IF EXISTS attendance.attendance_protection_candidate CASCADE;
CREATE TABLE attendance.attendance_protection_candidate (
	id uuid NOT NULL,
	booking_id uuid NOT NULL,
	restriction_interval_id uuid NOT NULL,
	recorded_at timestamp with time zone NOT NULL,
	audit_context jsonb NOT NULL,
	CONSTRAINT attendance_protection_candidate_pk PRIMARY KEY (id),
	CONSTRAINT uq_attendance_candidate_interval UNIQUE (booking_id,restriction_interval_id),
	CONSTRAINT ck_attendance_candidate_context_object CHECK (jsonb_typeof(audit_context) = 'object')
);
-- ddl-end --
COMMENT ON TABLE attendance.attendance_protection_candidate IS E'Append-only candidate/audit context recorded when a Venue Account disable interval affects an ACTIVE Online Booking. The effective Trust protection event is created only when Attendance resolves. Several candidates may exist across repeated disable/re-enable cycles; max one effective protection Trust event per Booking.';
-- ddl-end --
COMMENT ON COLUMN attendance.attendance_protection_candidate.restriction_interval_id IS E'Specific Venue Account disable interval that made this Booking a protection candidate.';
-- ddl-end --
COMMENT ON COLUMN attendance.attendance_protection_candidate.recorded_at IS E'Recorded at/after disable time; the effective Trust event comes only at Attendance resolution';
-- ddl-end --
COMMENT ON COLUMN attendance.attendance_protection_candidate.audit_context IS E'Immutable snapshot/audit context; JSON object';
-- ddl-end --
ALTER TABLE attendance.attendance_protection_candidate OWNER TO postgres;
-- ddl-end --

-- object: tournament.tournament | type: TABLE --
-- DROP TABLE IF EXISTS tournament.tournament CASCADE;
CREATE TABLE tournament.tournament (
	id uuid NOT NULL,
	venue_id uuid NOT NULL,
	host_type text NOT NULL,
	creator_user_id uuid,
	creator_participates boolean,
	activity varchar(80) NOT NULL,
	play_mode varchar(80),
	status varchar(80) NOT NULL,
	capacity smallint NOT NULL,
	created_at timestamp with time zone NOT NULL,
	start_at timestamp with time zone NOT NULL,
	end_at timestamp with time zone NOT NULL,
	nominal_minutes integer NOT NULL,
	checkpoint_at timestamp with time zone NOT NULL,
	approval_expires_at timestamp with time zone,
	visibility text NOT NULL,
	invite_code text,
	venue_cost_total numeric(12,2) NOT NULL,
	creation_fee_snapshot numeric(12,2) NOT NULL,
	entry_fee numeric(12,2) NOT NULL,
	prize numeric(12,2) NOT NULL,
	business_date date NOT NULL,
	operating_session_id uuid NOT NULL,
	terminal_reason varchar(80),
	version bigint NOT NULL DEFAULT 0,
	CONSTRAINT tournament_pk PRIMARY KEY (id),
	CONSTRAINT uq_tournament_invite_code UNIQUE (invite_code),
	CONSTRAINT ck_tournament_capacity CHECK (capacity BETWEEN 8 AND 32),
	CONSTRAINT ck_tournament_duration CHECK (nominal_minutes >= 60 AND MOD(nominal_minutes,30)=0),
	CONSTRAINT ck_tournament_terminal_reason CHECK ((status IN ('CANCELLED','REJECTED') AND terminal_reason IS NOT NULL) OR (status NOT IN ('CANCELLED','REJECTED') AND terminal_reason IS NULL)),
	CONSTRAINT ck_tournament_host_type CHECK (host_type IN ('PLAYER','VENUE')),
	CONSTRAINT ck_tournament_activity CHECK (activity IN ('PLAYSTATION','BILLIARDS','PING_PONG')),
	CONSTRAINT ck_tournament_play_mode CHECK ((activity = 'PLAYSTATION' AND play_mode IN ('SINGLE','MULTIPLAYER')) OR (activity IN ('BILLIARDS','PING_PONG') AND play_mode IS NULL)),
	CONSTRAINT ck_tournament_status_values CHECK (status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE','COMPLETED','REJECTED','CANCELLED')),
	CONSTRAINT ck_tournament_visibility CHECK (visibility IN ('PUBLIC','PRIVATE')),
	CONSTRAINT ck_tournament_terminal_reason_values CHECK ((terminal_reason IS NULL OR terminal_reason IN ('CREATOR_CANCELLED','VENUE_CANCELLED','ADMIN_CANCELLED','VENUE_REJECTED_TOURNAMENT','VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME','MINIMUM_PARTICIPANTS_NOT_REACHED','CREATOR_VERIFIED_STATUS_REVOKED','TOURNAMENT_OPERATIONAL_TERMINATION','EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED','VENUE_ACCOUNT_DISABLED'))),
	CONSTRAINT ck_tournament_host_creator_shape CHECK ((host_type = 'PLAYER' AND creator_user_id IS NOT NULL AND creator_participates IS NOT NULL) OR (host_type = 'VENUE' AND creator_user_id IS NULL AND creator_participates IS NULL)),
	CONSTRAINT ck_tournament_time_arithmetic CHECK (end_at = start_at + make_interval(mins => nominal_minutes) AND checkpoint_at = start_at - interval '1 hour' AND created_at <= start_at - interval '2 hours'),
	CONSTRAINT ck_tournament_approval_deadline CHECK ((host_type = 'PLAYER' AND approval_expires_at IS NOT NULL AND approval_expires_at = LEAST(created_at + interval '10 minutes', checkpoint_at)) OR (host_type = 'VENUE' AND approval_expires_at IS NULL AND status <> 'PENDING_VENUE_APPROVAL')),
	CONSTRAINT ck_tournament_money_nonnegative CHECK (venue_cost_total >= 0 AND creation_fee_snapshot >= 0 AND entry_fee >= 0 AND prize >= 0),
	CONSTRAINT ck_tournament_private_invite CHECK (visibility <> 'PRIVATE' OR NULLIF(BTRIM(invite_code),'') IS NOT NULL),
	CONSTRAINT ck_tournament_version_nonnegative CHECK (version >= 0),
	CONSTRAINT ck_tournament_rejected_reason CHECK ((status = 'REJECTED') = (terminal_reason IS NOT DISTINCT FROM 'VENUE_REJECTED_TOURNAMENT'))
);
-- ddl-end --
COMMENT ON TABLE tournament.tournament IS E'Separate aggregate from Booking. v1.1.11: creation/request time is DB-authoritative; interval/checkpoint/approval deadline are derived and immutable; one Player-hosted pending request per Creator is physically unique; 5-minute same-Venue/time retry cooldown is serialized; 1–4 Resources and one Operating Session are commit-time invariants. COMPLETED has no Tournament Reason Code; terminal_reason is required for REJECTED/CANCELLED and NULL otherwise.';
-- ddl-end --
COMMENT ON COLUMN tournament.tournament.host_type IS E'PLAYER · VENUE';
-- ddl-end --
COMMENT ON COLUMN tournament.tournament.creator_user_id IS E'NOT NULL when PLAYER';
-- ddl-end --
COMMENT ON COLUMN tournament.tournament.play_mode IS E'PlayStation only';
-- ddl-end --
COMMENT ON COLUMN tournament.tournament.status IS E'PENDING_VENUE_APPROVAL · WAITING_FOR_PLAYERS · CONFIRMED · ACTIVE · COMPLETED · REJECTED · CANCELLED';
-- ddl-end --
COMMENT ON COLUMN tournament.tournament.capacity IS E'8-32';
-- ddl-end --
COMMENT ON COLUMN tournament.tournament.created_at IS E'DB-authoritative request/creation timestamp; set to transaction_timestamp() on INSERT and immutable.';
-- ddl-end --
COMMENT ON COLUMN tournament.tournament.nominal_minutes IS E'>= 60, /30';
-- ddl-end --
COMMENT ON COLUMN tournament.tournament.checkpoint_at IS E'EXACTLY start - 1h';
-- ddl-end --
COMMENT ON COLUMN tournament.tournament.approval_expires_at IS E'MIN(created + 10m, checkpoint)';
-- ddl-end --
COMMENT ON COLUMN tournament.tournament.visibility IS E'PUBLIC · PRIVATE';
-- ddl-end --
COMMENT ON COLUMN tournament.tournament.invite_code IS E'inactive while PENDING_VENUE_APPROVAL';
-- ddl-end --
COMMENT ON COLUMN tournament.tournament.venue_cost_total IS E'historical snapshot. never changed by resource loss';
-- ddl-end --
COMMENT ON COLUMN tournament.tournament.creation_fee_snapshot IS E'Launch 0; historical snapshot for future activation.';
-- ddl-end --
COMMENT ON COLUMN tournament.tournament.entry_fee IS E'INFORMATIONAL ONLY';
-- ddl-end --
COMMENT ON COLUMN tournament.tournament.prize IS E'INFORMATIONAL ONLY';
-- ddl-end --
COMMENT ON COLUMN tournament.tournament.business_date IS E'revenue only on COMPLETED';
-- ddl-end --
COMMENT ON COLUMN tournament.tournament.operating_session_id IS E'Tournament must fit one Operating Session.';
-- ddl-end --
COMMENT ON COLUMN tournament.tournament.terminal_reason IS E'exactly one of 12';
