COMMENT ON COLUMN tournament.tournament_participant.status IS E'JOINED · LEFT · REMOVED · INELIGIBLE';
-- ddl-end --
COMMENT ON COLUMN tournament.tournament_participant.status_changed_at IS E'Current participant-state transition timestamp; full transition history is retained in append-only audit_event.';
