	actor_id uuid,
	correlation_id uuid NOT NULL,
	CONSTRAINT tournament_history_pk PRIMARY KEY (id),
	CONSTRAINT uq_tournament_history_seq UNIQUE (tournament_id,sequence),
	CONSTRAINT ck_tournament_history_status_values CHECK ((from_status IS NULL OR from_status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE','COMPLETED','REJECTED','CANCELLED')) AND (to_status IS NULL OR to_status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE','COMPLETED','REJECTED','CANCELLED'))),
	CONSTRAINT ck_tournament_history_terminal_reason_values CHECK ((terminal_reason IS NULL OR terminal_reason IN ('CREATOR_CANCELLED','VENUE_CANCELLED','ADMIN_CANCELLED','VENUE_REJECTED_TOURNAMENT','VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME','MINIMUM_PARTICIPANTS_NOT_REACHED','CREATOR_VERIFIED_STATUS_REVOKED','TOURNAMENT_OPERATIONAL_TERMINATION','EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED','VENUE_ACCOUNT_DISABLED'))),
	CONSTRAINT ck_tournament_history_sequence_positive CHECK (sequence > 0),
	CONSTRAINT ck_tournament_history_actor_type CHECK (actor_type IN ('CUSTOMER','VENUE','ADMIN','SYSTEM')),
	CONSTRAINT ck_tournament_history_actor_shape CHECK ((actor_type = 'SYSTEM' AND actor_id IS NULL) OR (actor_type <> 'SYSTEM' AND actor_id IS NOT NULL)),
	CONSTRAINT ck_tournament_history_transition_shape CHECK ((from_status IS NULL OR from_status IS DISTINCT FROM to_status) AND ((to_status IN ('CANCELLED','REJECTED') AND terminal_reason IS NOT NULL) OR (to_status NOT IN ('CANCELLED','REJECTED') AND terminal_reason IS NULL))),
	CONSTRAINT ck_tournament_history_rejected_reason CHECK ((to_status = 'REJECTED') = (terminal_reason IS NOT DISTINCT FROM 'VENUE_REJECTED_TOURNAMENT'))
);
-- ddl-end --
COMMENT ON TABLE tournament.tournament_history IS E'APPEND-ONLY.';
-- ddl-end --
ALTER TABLE tournament.tournament_history OWNER TO postgres;
-- ddl-end --

