	CONSTRAINT ck_points_tx_amounts CHECK (balance_before>=0 AND balance_after>=0 AND balance_after::bigint=balance_before::bigint+amount::bigint AND granted_value_snapshot>=0 AND unrecovered_reversal_amount>=0 AND ((requested_amount>=0 AND amount=requested_amount AND unrecovered_reversal_amount=0) OR (requested_amount<0 AND amount=GREATEST(requested_amount,-balance_before) AND unrecovered_reversal_amount::bigint=amount::bigint-requested_amount::bigint))),
