	CONSTRAINT ck_points_tx_config CHECK ((cause='ADMIN' AND configuration_version_id IS NULL AND configuration_as_of IS NULL) OR (cause<>'ADMIN' AND configuration_version_id IS NOT NULL AND configuration_as_of IS NOT NULL)),
	CONSTRAINT uq_points_tx_operation UNIQUE (operation_key),
	CONSTRAINT uq_points_tx_sequence UNIQUE (ledger_sequence)
);
-- ddl-end --
COMMENT ON TABLE loyalty.points_transaction IS E'APPEND-ONLY physical Points ledger.\n\nSource/critical constraints:\n- ux_points_booking_reward\n- ux_points_referral_reward';
