COMMENT ON COLUMN loyalty.points_transaction.amount IS E'signed';
-- ddl-end --
COMMENT ON COLUMN loyalty.points_transaction.cause IS E'ATTENDED_COMPLETION · REFERRAL_SIGNUP · COMPENSATION · ADMIN';
-- ddl-end --
COMMENT ON COLUMN loyalty.points_transaction.granted_value_snapshot IS E'historical snapshot. the configured value AT the moment';
-- ddl-end --
COMMENT ON COLUMN loyalty.points_transaction.unrecovered_reversal_amount IS E'never debt, never auto-repaid';
-- ddl-end --
