-- object: review.review | type: TABLE --
-- DROP TABLE IF EXISTS review.review CASCADE;
CREATE TABLE review.review (
	id uuid NOT NULL,
	user_id uuid NOT NULL,
	venue_id uuid NOT NULL,
	rating smallint NOT NULL,
	comment text NOT NULL,
	status varchar(80) NOT NULL,
	author_deleted_at timestamp with time zone,
	created_at timestamp with time zone NOT NULL,
	updated_at timestamp with time zone NOT NULL,
	CONSTRAINT review_pk PRIMARY KEY (id),
	CONSTRAINT ck_review_rating CHECK (rating BETWEEN 1 AND 5),
	CONSTRAINT ck_review_comment CHECK (length(trim(comment)) > 0),
	CONSTRAINT ck_review_status CHECK (status IN ('PENDING_MODERATION','ACTIVE','HIDDEN','REMOVED')),
	CONSTRAINT ck_review_timestamps CHECK (updated_at >= created_at AND (author_deleted_at IS NULL OR author_deleted_at >= created_at)),
	CONSTRAINT ck_review_author_deletion CHECK (author_deleted_at IS NULL OR status = 'REMOVED')
);
-- ddl-end --
COMMENT ON TABLE review.review IS E'Phone-verified, non-anonymised registered User may review without a Booking. Rating and non-empty comment are both required. Lifecycle (v1.1.25 guarded): normal create -> ACTIVE; create after an Admin removal (cooldown elapsed) -> PENDING_MODERATION; ACTIVE<->HIDDEN; ACTIVE/HIDDEN/PENDING_MODERATION -> REMOVED (terminal). Only ACTIVE contributes to aggregate rating. Writes only through review.* producers.\n\nSource/critical constraints:\n- ux_review_current (user_id, venue_id) WHERE status <> ''REMOVED''';
-- ddl-end --
COMMENT ON COLUMN review.review.rating IS E'1-5';
-- ddl-end --
COMMENT ON COLUMN review.review.status IS E'PENDING_MODERATION · ACTIVE · HIDDEN · REMOVED (terminal)';
-- ddl-end --
COMMENT ON COLUMN review.review.created_at IS E'Review date shown by Product; immutable';
-- ddl-end --
COMMENT ON COLUMN review.review.updated_at IS E'Last author edit or lifecycle change';
-- ddl-end --
ALTER TABLE review.review OWNER TO postgres;
-- ddl-end --

-- object: review.review_report | type: TABLE --
-- DROP TABLE IF EXISTS review.review_report CASCADE;
CREATE TABLE review.review_report (
	id uuid NOT NULL,
	review_id uuid NOT NULL,
	reporter_user_id uuid NOT NULL,
	reason text NOT NULL,
	details text,
	created_at timestamp with time zone NOT NULL,
	correlation_id uuid NOT NULL,
	resolved_at timestamp with time zone,
	resolved_by_admin_id uuid,
	resolution_note text,
	moderation_event_id uuid,
	CONSTRAINT review_report_pk PRIMARY KEY (id),
	CONSTRAINT ck_review_report_reason CHECK (length(btrim(reason)) > 0),
	CONSTRAINT ck_review_report_resolution CHECK ((resolved_at IS NULL AND resolved_by_admin_id IS NULL AND resolution_note IS NULL AND moderation_event_id IS NULL) OR (resolved_at IS NOT NULL AND resolved_by_admin_id IS NOT NULL AND NULLIF(btrim(resolution_note),'') IS NOT NULL AND resolved_at >= created_at))
);
-- ddl-end --
COMMENT ON TABLE review.review_report IS E'PCR-003 / FR-REV-11. Customer abuse-report signal for an ACTIVE public Review. Reporting itself never mutates Review state or rating. Resolution is one-time and may reference an existing moderation event for the same Review.';
-- ddl-end --
ALTER TABLE review.review_report OWNER TO postgres;
-- ddl-end --

-- object: review.review_moderation_event | type: TABLE --
-- DROP TABLE IF EXISTS review.review_moderation_event CASCADE;
CREATE TABLE review.review_moderation_event (
	id uuid NOT NULL,
	review_id uuid NOT NULL,
	action text NOT NULL,
	previous_status varchar(80) NOT NULL,
	new_status varchar(80) NOT NULL,
	admin_id uuid NOT NULL,
	reason text NOT NULL,
	occurred_at timestamp with time zone NOT NULL,
	correlation_id uuid NOT NULL,
	audit_event_id uuid NOT NULL,
	CONSTRAINT review_moderation_event_pk PRIMARY KEY (id),
	CONSTRAINT ck_review_moderation_action CHECK (action IN ('APPROVE','HIDE','RESTORE','REMOVE')),
	CONSTRAINT ck_review_moderation_status_values CHECK (previous_status IN ('PENDING_MODERATION','ACTIVE','HIDDEN','REMOVED') AND new_status IN ('PENDING_MODERATION','ACTIVE','HIDDEN','REMOVED')),
	CONSTRAINT ck_review_moderation_transition CHECK ((action = 'APPROVE' AND previous_status = 'PENDING_MODERATION' AND new_status = 'ACTIVE') OR (action = 'HIDE' AND previous_status = 'ACTIVE' AND new_status = 'HIDDEN') OR (action = 'RESTORE' AND previous_status = 'HIDDEN' AND new_status = 'ACTIVE') OR (action = 'REMOVE' AND previous_status IN ('ACTIVE','HIDDEN','PENDING_MODERATION') AND new_status = 'REMOVED')),
	CONSTRAINT ck_review_moderation_reason CHECK (length(btrim(reason)) > 0),
	CONSTRAINT uq_review_moderation_audit UNIQUE (audit_event_id)
);
-- ddl-end --
COMMENT ON TABLE review.review_moderation_event IS E'APPEND-ONLY (no UPDATE/DELETE/TRUNCATE). One row per Admin moderation command, written atomically with the Review status, Audit event, rating projection and author Outbox event. action must match the exact transition.';
-- ddl-end --
COMMENT ON COLUMN review.review_moderation_event.action IS E'APPROVE · HIDE · RESTORE · REMOVE';
-- ddl-end --
ALTER TABLE review.review_moderation_event OWNER TO postgres;
-- ddl-end --

-- object: review.review_cooldown | type: TABLE --
