);
-- ddl-end --
COMMENT ON TABLE review.review_cooldown IS E'Created atomically by the Admin REMOVE moderation command only. While now < cooldown_until the same User cannot create a Review for the same Venue; afterwards a new Review starts PENDING_MODERATION.';
-- ddl-end --
COMMENT ON COLUMN review.review_cooldown.cooldown_until IS E'30 days';
-- ddl-end --
COMMENT ON COLUMN review.review_cooldown.review_id IS E'The removed Review';
-- ddl-end --
ALTER TABLE review.review_cooldown OWNER TO postgres;
