	CONSTRAINT ck_rating_stats_average CHECK ((review_count = 0 AND average_rating IS NULL) OR (review_count > 0 AND average_rating IS NOT NULL AND average_rating BETWEEN 1 AND 5))
);
-- ddl-end --
COMMENT ON TABLE review.venue_rating_stats IS E'PROJECTION - rebuildable ONLY by review.refresh_venue_rating() from review.review WHERE status = ACTIVE; a deferred check re-derives it at commit. average_rating is NULL exactly when review_count = 0.';
-- ddl-end --
ALTER TABLE review.venue_rating_stats OWNER TO postgres;
-- ddl-end --

-- object: notification.notification | type: TABLE --
