	CONSTRAINT ck_notification_delivery_attempt CHECK (attempt >= 0 AND (attempt = 0) = (last_attempt_at IS NULL)),
	CONSTRAINT ck_notification_delivery_shape CHECK ((status = 'SENT' AND provider_message_id IS NOT NULL AND last_attempt_at IS NOT NULL AND attempt > 0) OR (status IN ('FAILED','DEAD_LETTER') AND provider_message_id IS NULL AND error_code IS NOT NULL AND last_attempt_at IS NOT NULL AND attempt > 0) OR (status = 'PENDING' AND provider_message_id IS NULL)),
	CONSTRAINT ck_notification_delivery_chronology CHECK (last_attempt_at IS NULL OR last_attempt_at >= created_at)
);
