-- object: notification.notification_catalogue | type: TABLE --
-- DROP TABLE IF EXISTS notification.notification_catalogue CASCADE;
CREATE TABLE notification.notification_catalogue (
	code text NOT NULL,
	reference_type text NOT NULL,
	recipient_types text[] NOT NULL,
	required_channels text[] NOT NULL,
	allowed_channels text[] NOT NULL,
	otp_only boolean NOT NULL DEFAULT false,
	registered_at timestamp with time zone NOT NULL DEFAULT clock_timestamp(),
	source_reference text NOT NULL,
	CONSTRAINT notification_catalogue_pk PRIMARY KEY (code),
	CONSTRAINT ck_notification_catalogue_values CHECK (code ~ '^[A-Z][A-Z0-9_]{1,99}$' AND reference_type IN ('BOOKING','TOURNAMENT','NONE') AND cardinality(recipient_types) > 0 AND recipient_types <@ ARRAY['CUSTOMER','VENUE','ADMIN']::text[] AND cardinality(required_channels) > 0 AND required_channels <@ allowed_channels AND allowed_channels <@ ARRAY['IN_APP','PUSH','EMAIL','SMS']::text[] AND (('SMS' = ANY(allowed_channels)) = otp_only) AND (NOT otp_only OR allowed_channels = ARRAY['SMS']::text[]) AND length(btrim(source_reference)) > 0)
);
-- ddl-end --
COMMENT ON TABLE notification.notification_catalogue IS E'TECHNICAL notification catalogue (not a Product enum). One row per notification code: reference rule, allowed recipient types and the channel policy. Rows are registered by deployment from the FRS notification catalogue and are append-only. SMS is permitted only for OTP-class codes (launch rule: SMS = OTP only).';
