COMMENT ON COLUMN notification.notification_catalogue.reference_type IS E'BOOKING · TOURNAMENT · NONE';
-- ddl-end --
COMMENT ON COLUMN notification.notification_catalogue.source_reference IS E'FRS/PRD identifier the entry was taken from';
-- ddl-end --
ALTER TABLE notification.notification_catalogue OWNER TO postgres;
-- ddl-end --

-- object: audit.audit_event | type: TABLE --
-- DROP TABLE IF EXISTS audit.audit_event CASCADE;
CREATE TABLE audit.audit_event (
	id uuid NOT NULL,
	occurred_at timestamp with time zone NOT NULL,
	actor_type text NOT NULL,
	actor_id uuid,
	action text NOT NULL,
	subject_type text NOT NULL,
	subject_id uuid NOT NULL,
	reason text,
	owner_password_used boolean,
	owner_password_outcome text,
	correlation_id uuid NOT NULL,
	payload jsonb,
	request_id uuid,
	previous_state text,
	new_state text,
	client_ip inet,
	client_user_agent text,
	client_app text,
	context_user_id uuid,
	context_venue_id uuid,
	CONSTRAINT audit_event_pk PRIMARY KEY (id),
	CONSTRAINT ck_audit_actor_type CHECK (actor_type IN ('CUSTOMER','VENUE','ADMIN','SYSTEM')),
	CONSTRAINT ck_audit_owner_password_outcome CHECK ((owner_password_outcome IS NULL OR owner_password_outcome IN ('SUCCESS','FAILURE'))),
	CONSTRAINT ck_audit_owner_password_coherence CHECK ((owner_password_used IS TRUE AND owner_password_outcome IS NOT NULL AND owner_password_outcome IN ('SUCCESS','FAILURE')) OR (owner_password_used IS NOT TRUE AND owner_password_outcome IS NULL)),
	CONSTRAINT ck_audit_structured_trace CHECK ((previous_state IS NULL OR new_state IS NOT NULL) AND (previous_state IS NULL OR length(btrim(previous_state)) BETWEEN 1 AND 80) AND (new_state IS NULL OR length(btrim(new_state)) BETWEEN 1 AND 80) AND (client_user_agent IS NULL OR length(client_user_agent) <= 512) AND (client_app IS NULL OR length(btrim(client_app)) BETWEEN 1 AND 80) AND (payload IS NULL OR jsonb_typeof(payload) = 'object')),
	CONSTRAINT ck_audit_actor_identity CHECK ((actor_type = 'SYSTEM') = (actor_id IS NULL)),
	CONSTRAINT ck_audit_subject_type_format CHECK (subject_type ~ '^[A-Z][A-Z0-9_]{0,63}$')
);
-- ddl-end --
COMMENT ON TABLE audit.audit_event IS E'APPEND-ONLY (no UPDATE/DELETE/TRUNCATE, trigger and privilege level). Actor provenance is validated at INSERT (ADMIN -> active Admin, CUSTOMER -> User, VENUE -> Venue Account, SYSTEM -> no actor id). payload is rejected fail-closed if it contains credential/secret keys at any depth. Structured trace columns replace free-form JSON for request, client and state-transition metadata.';
-- ddl-end --
COMMENT ON COLUMN audit.audit_event.actor_type IS E'CUSTOMER · VENUE · ADMIN · SYSTEM';
-- ddl-end --
COMMENT ON COLUMN audit.audit_event.reason IS E'mandatory where the action requires one';
-- ddl-end --
COMMENT ON COLUMN audit.audit_event.owner_password_outcome IS E'SUCCESS · FAILURE — both audited';
-- ddl-end --
COMMENT ON COLUMN audit.audit_event.correlation_id IS E'traces a whole cascade';
-- ddl-end --
COMMENT ON COLUMN audit.audit_event.payload IS E'redaction-allowlisted — NEVER a secret';
-- ddl-end --
COMMENT ON COLUMN audit.audit_event.request_id IS E'Inbound request identity where the action originated from an API request';
-- ddl-end --
ALTER TABLE audit.audit_event OWNER TO postgres;
-- ddl-end --

-- object: admin.admin_alert | type: TABLE --
