-- object: technical.outbox_event | type: TABLE --
-- DROP TABLE IF EXISTS technical.outbox_event CASCADE;
CREATE TABLE technical.outbox_event (
	id bigint NOT NULL,
	event_type text NOT NULL,
	aggregate_type text NOT NULL,
	aggregate_id uuid NOT NULL,
	payload jsonb NOT NULL,
	correlation_id uuid NOT NULL,
	state text NOT NULL,
	attempt smallint NOT NULL,
	next_attempt_at timestamp with time zone,
	dispatched_at timestamp with time zone,
	created_at timestamp with time zone NOT NULL DEFAULT clock_timestamp(),
	last_error text,
	CONSTRAINT outbox_event_pk PRIMARY KEY (id),
	CONSTRAINT ck_outbox_state CHECK (state IN ('PENDING','DISPATCHED','DEAD_LETTER')),
	CONSTRAINT ck_outbox_lifecycle_shape CHECK (attempt >= 0 AND (state = 'DISPATCHED') = (dispatched_at IS NOT NULL) AND (state <> 'PENDING' OR next_attempt_at IS NOT NULL) AND (state <> 'DEAD_LETTER' OR (last_error IS NOT NULL AND length(btrim(last_error)) > 0)) AND (dispatched_at IS NULL OR dispatched_at >= created_at)),
	CONSTRAINT ck_outbox_event_names CHECK (event_type ~ '^[A-Za-z][A-Za-z0-9_]{0,127}$' AND aggregate_type ~ '^[A-Z][A-Z0-9_]{0,63}$')
);
-- ddl-end --
COMMENT ON TABLE technical.outbox_event IS E'Written in the business transaction. Notifications dispatch ONLY after commit. INSERT: PENDING, attempt 0. Envelope (id, event_type, aggregate, payload, correlation, created_at) immutable. Delivery fields change only through technical.outbox_* worker functions: PENDING -> PENDING (retry) | DISPATCHED | DEAD_LETTER; DISPATCHED and DEAD_LETTER are terminal. No DELETE/TRUNCATE (retention purge requires an explicit future path).';
-- ddl-end --
COMMENT ON COLUMN technical.outbox_event.state IS E'PENDING · DISPATCHED · DEAD_LETTER';
-- ddl-end --
ALTER TABLE technical.outbox_event OWNER TO postgres;
-- ddl-end --

-- object: technical.idempotency_record | type: TABLE --
-- DROP TABLE IF EXISTS technical.idempotency_record CASCADE;
CREATE TABLE technical.idempotency_record (
	principal_type text NOT NULL,
	principal_id uuid NOT NULL,
	endpoint text NOT NULL,
	idempotency_key text NOT NULL,
	request_fingerprint text NOT NULL,
	state text NOT NULL,
	response_status smallint,
	response_body jsonb,
	result_aggregate_type text,
	result_aggregate_id uuid,
	correlation_id uuid NOT NULL,
	created_at timestamp with time zone NOT NULL,
	completed_at timestamp with time zone,
	expires_at timestamp with time zone NOT NULL,
	CONSTRAINT idempotency_record_pk PRIMARY KEY (principal_type,principal_id,endpoint,idempotency_key),
	CONSTRAINT ck_idempotency_values CHECK (principal_type IN ('CUSTOMER','VENUE','ADMIN','SYSTEM') AND length(btrim(endpoint)) BETWEEN 1 AND 200 AND length(idempotency_key) BETWEEN 1 AND 255 AND request_fingerprint ~ '^[0-9a-f]{64}$' AND expires_at > created_at),
	CONSTRAINT ck_idempotency_state CHECK ((state = 'IN_PROGRESS' AND completed_at IS NULL AND response_status IS NULL AND response_body IS NULL) OR (state = 'COMPLETED' AND completed_at IS NOT NULL AND completed_at >= created_at AND response_status IS NOT NULL AND response_status BETWEEN 100 AND 599 AND (result_aggregate_type IS NULL) = (result_aggregate_id IS NULL) AND (response_body IS NULL OR jsonb_typeof(response_body) = 'object')))
);
-- ddl-end --
COMMENT ON TABLE technical.idempotency_record IS E'Persistent request idempotency (Architecture). Identity = (principal_type, principal_id, endpoint, idempotency_key). Same key + same request_fingerprint returns the stored logical result; same key + different fingerprint is rejected. Rows are created and completed only through technical.idempotency_begin/complete inside the business transaction, so an IN_PROGRESS row never survives a rolled-back command. Expired rows may be replaced only by technical.idempotency_begin.';
-- ddl-end --
COMMENT ON COLUMN technical.idempotency_record.principal_type IS E'CUSTOMER · VENUE · ADMIN · SYSTEM';
-- ddl-end --
COMMENT ON COLUMN technical.idempotency_record.principal_id IS E'User / Venue Account / Admin id; for SYSTEM the registered system principal uuid';
-- ddl-end --
COMMENT ON COLUMN technical.idempotency_record.endpoint IS E'API endpoint or command name';
-- ddl-end --
COMMENT ON COLUMN technical.idempotency_record.request_fingerprint IS E'lower-case hex SHA-256 of the canonical request';
-- ddl-end --
COMMENT ON COLUMN technical.idempotency_record.state IS E'IN_PROGRESS · COMPLETED';
-- ddl-end --
COMMENT ON COLUMN technical.idempotency_record.response_body IS E'Redacted response summary (never a secret)';
-- ddl-end --
ALTER TABLE technical.idempotency_record OWNER TO postgres;
-- ddl-end --

-- object: venue.operating_session | type: TABLE --
-- DROP TABLE IF EXISTS venue.operating_session CASCADE;
CREATE TABLE venue.operating_session (
	id uuid NOT NULL,
	venue_id uuid NOT NULL,
	opening_template_id uuid NOT NULL,
	operating_day date NOT NULL,
	local_start timestamp NOT NULL,
	local_end timestamp NOT NULL,
	session_period tstzrange NOT NULL,
	timezone text NOT NULL,
	generated_from_version bigint NOT NULL,
	generated_at timestamp with time zone NOT NULL,
	CONSTRAINT operating_session_pk PRIMARY KEY (id),
	CONSTRAINT uq_operating_session_day UNIQUE (venue_id,operating_day),
	CONSTRAINT ck_session_len CHECK (NOT isempty(session_period) AND lower(session_period) IS NOT NULL AND upper(session_period) IS NOT NULL AND lower(session_period) < upper(session_period) AND local_end > local_start AND local_end <= local_start + interval '24 hours')
);
-- ddl-end --
COMMENT ON TABLE venue.operating_session IS E'Materialized Operating Session. A2 CLOSED: rolling 120-day materialization horizon accepted as an Architecture setting, not a Product booking limit. DST is resolved to absolute instants once. DO NOT enforce <=24h on absolute duration; 24h is a local-wall-clock template rule and may be 23/25h across DST.\n\nSource/critical constraints:\n- uq_session_day (venue_id, operating_day)\n- ck_session_len (positive absolute range; <= 24h in local wall-clock timestamps)\n- ex_session_no_overlap EXCLUDE (venue_id =, session_period &&)';
-- ddl-end --
COMMENT ON COLUMN venue.operating_session.opening_template_id IS E'Source template identity; historical Booking snapshots remain independent.';
-- ddl-end --
COMMENT ON COLUMN venue.operating_session.operating_day IS E'the canonical operating-day key';
-- ddl-end --
COMMENT ON COLUMN venue.operating_session.local_start IS E'wall clock, for snapshots';
-- ddl-end --
COMMENT ON COLUMN venue.operating_session.session_period IS E'ABSOLUTE instants — the inventory authority';
-- ddl-end --
ALTER TABLE venue.operating_session OWNER TO postgres;
-- ddl-end --

-- object: operations.booking_timer_pause_history | type: TABLE --
-- DROP TABLE IF EXISTS operations.booking_timer_pause_history CASCADE;
CREATE TABLE operations.booking_timer_pause_history (
	id uuid NOT NULL,
	booking_id uuid NOT NULL,
	sequence smallint NOT NULL,
	pause_kind text NOT NULL,
	pause_started_at timestamp with time zone NOT NULL,
	pause_ended_at timestamp with time zone,
	pause_cause text NOT NULL,
	accumulated_duration interval,
	CONSTRAINT booking_timer_pause_history_pk PRIMARY KEY (id),
	CONSTRAINT uq_pause_history_seq UNIQUE (booking_id,pause_kind,sequence),
	CONSTRAINT ck_booking_timer_pause_kind CHECK (pause_kind IN ('VENUE_RESPONSE','LATE_CONFIRM')),
	CONSTRAINT ck_pause_history_sequence_positive CHECK (sequence > 0),
	CONSTRAINT ck_pause_history_cause_nonempty CHECK (length(btrim(pause_cause)) > 0),
	CONSTRAINT ck_pause_history_lifecycle CHECK ((pause_ended_at IS NULL AND (accumulated_duration IS NULL OR accumulated_duration >= interval '0')) OR (pause_ended_at IS NOT NULL AND pause_ended_at >= pause_started_at AND accumulated_duration IS NOT NULL AND accumulated_duration >= (pause_ended_at - pause_started_at) AND accumulated_duration <= interval '30 minutes'))
);
-- ddl-end --
COMMENT ON TABLE operations.booking_timer_pause_history IS E'Immutable timer-pause history with one physical close mutation: an open row may be closed once by setting pause_ended_at and accumulated_duration; after that it is immutable. Repeated emergency pauses accumulate and never reset the separate 30-minute caps.';
-- ddl-end --
COMMENT ON COLUMN operations.booking_timer_pause_history.sequence IS E'Monotonic within Booking + pause kind.';
-- ddl-end --
COMMENT ON COLUMN operations.booking_timer_pause_history.pause_kind IS E'VENUE_RESPONSE · LATE_CONFIRM';
-- ddl-end --
ALTER TABLE operations.booking_timer_pause_history OWNER TO postgres;
-- ddl-end --

-- object: iam.venue_account_restriction_interval | type: TABLE --
-- DROP TABLE IF EXISTS iam.venue_account_restriction_interval CASCADE;
CREATE TABLE iam.venue_account_restriction_interval (
	id uuid NOT NULL,
	venue_id uuid NOT NULL,
	disabled_at timestamp with time zone NOT NULL,
	reenabled_at timestamp with time zone,
	source text NOT NULL,
	admin_id uuid,
	reason text NOT NULL,
	correlation_id uuid NOT NULL,
	CONSTRAINT venue_account_restriction_interval_pk PRIMARY KEY (id),
	CONSTRAINT uq_venue_restriction_start UNIQUE (venue_id,disabled_at),
	CONSTRAINT ck_restriction_source CHECK (source IN ('ADMIN','SYSTEM')),
	CONSTRAINT ck_restriction_period CHECK (reenabled_at IS NULL OR reenabled_at >= disabled_at),
	CONSTRAINT ck_restriction_source_admin CHECK ((source = 'ADMIN' AND admin_id IS NOT NULL) OR (source = 'SYSTEM' AND admin_id IS NULL)),
	CONSTRAINT ck_restriction_interval_reason CHECK (length(btrim(reason)) > 0)
);
-- ddl-end --
COMMENT ON TABLE iam.venue_account_restriction_interval IS E'IMMUTABLE venue-scoped account-access restriction history used by Attendance Protection. A Booking may overlap several intervals. Physical lifecycle permits exactly one close mutation: reenabled_at NULL -> timestamp; all other updates/deletes are rejected by v1.1.5 integrity guards.';
-- ddl-end --
COMMENT ON COLUMN iam.venue_account_restriction_interval.venue_id IS E'Venue whose Dashboard access was disabled.';
-- ddl-end --
COMMENT ON COLUMN iam.venue_account_restriction_interval.reenabled_at IS E'NULL while restriction remains active.';
-- ddl-end --
COMMENT ON COLUMN iam.venue_account_restriction_interval.source IS E'ADMIN · SYSTEM';
-- ddl-end --
COMMENT ON COLUMN iam.venue_account_restriction_interval.admin_id IS E'Nullable for system source.';
-- ddl-end --
ALTER TABLE iam.venue_account_restriction_interval OWNER TO postgres;
-- ddl-end --

-- object: trust.trust_projection | type: TABLE --
-- DROP TABLE IF EXISTS trust.trust_projection CASCADE;
CREATE TABLE trust.trust_projection (
	user_id uuid NOT NULL,
	last_effective_at timestamp with time zone,
	consecutive_no_shows integer,
	penalty_stage smallint,
	current_threshold smallint,
	completed_attended_count integer,
	vp_qualification varchar(80),
	vp_operational_status varchar(80),
	last_event_sequence bigint,
	recomputed_at timestamp with time zone,
	active_ban_instance_id uuid,
	projection_version bigint NOT NULL DEFAULT 0,
	CONSTRAINT trust_projection_pk PRIMARY KEY (user_id),
	CONSTRAINT ck_trust_projection_vp_qualification CHECK ((vp_qualification IS NULL OR vp_qualification IN ('NOT_QUALIFIED','QUALIFIED'))),
	CONSTRAINT ck_trust_projection_vp_operational_status CHECK ((vp_operational_status IS NULL OR vp_operational_status IN ('NOT_VERIFIED','VERIFIED','SUSPENDED','REVOKED'))),
	CONSTRAINT ck_trust_projection_watermark_pair CHECK ((last_effective_at IS NULL) = (last_event_sequence IS NULL)),
	CONSTRAINT ck_trust_projection_nonnegative CHECK ((consecutive_no_shows IS NULL OR consecutive_no_shows >= 0) AND (penalty_stage IS NULL OR penalty_stage >= 0) AND (completed_attended_count IS NULL OR completed_attended_count >= 0) AND projection_version >= 0),
	CONSTRAINT ck_trust_projection_threshold CHECK (current_threshold IS NULL OR current_threshold IN (2,3)),
	CONSTRAINT ck_trust_projection_stage_threshold CHECK (penalty_stage IS NULL OR current_threshold IS NULL OR current_threshold = CASE WHEN penalty_stage = 0 THEN 3 WHEN penalty_stage IN (1,2) THEN 2 ELSE 3 END),
	CONSTRAINT ck_trust_projection_counter_below_threshold CHECK (consecutive_no_shows IS NULL OR current_threshold IS NULL OR consecutive_no_shows < current_threshold),
	CONSTRAINT ck_trust_projection_vp_progress_qualification CHECK (completed_attended_count IS NULL OR vp_qualification IS NULL OR (vp_qualification = 'QUALIFIED') = (completed_attended_count >= 10))
);
-- ddl-end --
COMMENT ON TABLE trust.trust_projection IS E'REBUILDABLE projection, never source of truth. Watermark is COMPOSITE (last_effective_at,last_event_sequence); sequence alone is invalid for retroactive corrections.';
-- ddl-end --
COMMENT ON COLUMN trust.trust_projection.last_effective_at IS E'Composite replay watermark part 1.';
-- ddl-end --
COMMENT ON COLUMN trust.trust_projection.completed_attended_count IS E'Verified Player progress';
-- ddl-end --
COMMENT ON COLUMN trust.trust_projection.vp_qualification IS E'NOT_QUALIFIED · QUALIFIED';
-- ddl-end --
COMMENT ON COLUMN trust.trust_projection.vp_operational_status IS E'NOT_VERIFIED · VERIFIED · SUSPENDED · REVOKED';
-- ddl-end --
COMMENT ON COLUMN trust.trust_projection.active_ban_instance_id IS E'Derived pointer only; Ban Instance remains operational authority.';
-- ddl-end --
ALTER TABLE trust.trust_projection OWNER TO postgres;
-- ddl-end --

-- object: trust.trust_event | type: TABLE --
-- DROP TABLE IF EXISTS trust.trust_event CASCADE;
CREATE TABLE trust.trust_event (
	id uuid NOT NULL,
	event_type varchar(80) NOT NULL,
	subject_user_id uuid NOT NULL,
	occurred_at timestamp with time zone NOT NULL,
	effective_at timestamp with time zone NOT NULL,
	event_sequence bigint NOT NULL,
	booking_id uuid,
	original_outcome_event_id uuid,
	superseded_correction_event_id uuid,
	corrected_outcome varchar(80),
	payload jsonb NOT NULL DEFAULT '{}'::jsonb,
	CONSTRAINT trust_event_pk PRIMARY KEY (id),
	CONSTRAINT uq_trust_event_sequence UNIQUE (event_sequence),
	CONSTRAINT ck_trust_event_type CHECK (event_type IN ('BOOKING_ATTENDED','BOOKING_ATTENDANCE_UNCONFIRMED','BOOKING_ATTENDED_INTERRUPTED','BOOKING_NO_SHOW','NO_SHOW_REVERSED','ATTENDANCE_CORRECTED','ADMIN_TRUST_ADJUSTMENT','VERIFIED_PLAYER_SUSPENDED','VERIFIED_PLAYER_REVOKED','VERIFIED_PLAYER_RESTORED','BOOKING_ACCOUNT_DISABLE_ATTENDANCE_PROTECTION')),
	CONSTRAINT ck_trust_event_corrected_outcome CHECK ((event_type = 'ATTENDANCE_CORRECTED' AND corrected_outcome IN ('ATTENDED','ATTENDED_INTERRUPTED','ATTENDANCE_UNCONFIRMED','ABSENT_NO_SHOW') AND original_outcome_event_id IS NOT NULL) OR (event_type = 'NO_SHOW_REVERSED' AND corrected_outcome IS NULL AND original_outcome_event_id IS NOT NULL AND superseded_correction_event_id IS NULL) OR (event_type NOT IN ('ATTENDANCE_CORRECTED','NO_SHOW_REVERSED') AND corrected_outcome IS NULL AND original_outcome_event_id IS NULL AND superseded_correction_event_id IS NULL)),
	CONSTRAINT ck_trust_protection_booking_ref CHECK (event_type <> 'BOOKING_ACCOUNT_DISABLE_ATTENDANCE_PROTECTION' OR booking_id IS NOT NULL),
	CONSTRAINT ck_trust_correction_booking_ref CHECK (event_type NOT IN ('ATTENDANCE_CORRECTED','NO_SHOW_REVERSED') OR booking_id IS NOT NULL),
	CONSTRAINT ck_trust_booking_outcome_booking_ref CHECK (event_type NOT IN ('BOOKING_ATTENDED','BOOKING_ATTENDANCE_UNCONFIRMED','BOOKING_ATTENDED_INTERRUPTED','BOOKING_NO_SHOW') OR booking_id IS NOT NULL),
	CONSTRAINT ck_trust_event_time_order CHECK (occurred_at >= effective_at),
	CONSTRAINT ck_trust_event_payload_object CHECK (jsonb_typeof(payload) = 'object')
);
-- ddl-end --
COMMENT ON TABLE trust.trust_event IS E'APPEND-ONLY source of truth. Canonical replay order is (effective_at,event_sequence). Attendance corrections keep both original outcome and superseded correction references; latest non-superseded correction by event_sequence is authoritative.\n\nSource/critical constraints:\n- uq_trust_seq\n- ck_corrected_outcome\n- ux_one_protection_per_booking\n- ux_trust_booking_original_attendance_outcome\n- ux_trust_booking_no_show_reversed\n- ux_trust_correction_superseded_once\n- tr_trust_attendance_correction_validate (single-leaf correction chain)\n- ix_trust_replay (subject, effective_at, event_sequence)';
-- ddl-end --
COMMENT ON COLUMN trust.trust_event.event_type IS E'11 closed members — FR-TRS-02';
-- ddl-end --
COMMENT ON COLUMN trust.trust_event.effective_at IS E'closed rules — booking.startAt, or the corrected event''s';
-- ddl-end --
COMMENT ON COLUMN trust.trust_event.event_sequence IS E'database-generated global monotonic';
-- ddl-end --
COMMENT ON COLUMN trust.trust_event.original_outcome_event_id IS E'Correction target/original canonical Booking Trust outcome. Required for ATTENDANCE_CORRECTED; v1.1.10 write guard also requires it for new NO_SHOW_REVERSED events.';
-- ddl-end --
COMMENT ON COLUMN trust.trust_event.superseded_correction_event_id IS E'Optional prior correction superseded by this correction; may be referenced at most once.';
-- ddl-end --
COMMENT ON COLUMN trust.trust_event.corrected_outcome IS E'mandatory on ATTENDANCE_CORRECTED. ADMIN_TRUST_ADJUSTMENT v1 is an exact five-key absolute payload: schemaVersion, counterAfter, penaltyStageAfter, adminId, correlationId.';
-- ddl-end --
ALTER TABLE trust.trust_event OWNER TO postgres;
-- ddl-end --

-- object: technical.scheduled_job | type: TABLE --
-- DROP TABLE IF EXISTS technical.scheduled_job CASCADE;
CREATE TABLE technical.scheduled_job (
	id uuid NOT NULL,
	type text NOT NULL,
	subject_id uuid NOT NULL,
	due_at timestamp with time zone NOT NULL,
	status text NOT NULL,
	attempt smallint NOT NULL DEFAULT 0,
	leased_until timestamp with time zone,
	leased_by text,
	idempotency_key text NOT NULL,
	last_error text,
	subject_type text NOT NULL,
	created_at timestamp with time zone NOT NULL DEFAULT clock_timestamp(),
	leased_at timestamp with time zone,
	completed_at timestamp with time zone,
	CONSTRAINT scheduled_job_pk PRIMARY KEY (id),
	CONSTRAINT uq_scheduled_job_idempotency_key UNIQUE (idempotency_key),
	CONSTRAINT ck_scheduled_job_status CHECK (status IN ('PENDING','PAUSED','LEASED','DONE','SUPERSEDED','FAILED')),
	CONSTRAINT ck_scheduled_job_lifecycle_shape CHECK (attempt >= 0 AND length(btrim(subject_type)) > 0 AND ((status = 'LEASED') = (leased_at IS NOT NULL AND leased_until IS NOT NULL AND leased_by IS NOT NULL AND length(btrim(leased_by)) > 0)) AND (status = 'LEASED' OR (leased_at IS NULL AND leased_until IS NULL AND leased_by IS NULL)) AND ((status IN ('DONE','SUPERSEDED','FAILED')) = (completed_at IS NOT NULL)) AND (status <> 'FAILED' OR (last_error IS NOT NULL AND length(btrim(last_error)) > 0)) AND (leased_until IS NULL OR leased_until > leased_at) AND (completed_at IS NULL OR completed_at >= created_at)),
	CONSTRAINT ck_scheduled_job_type_format CHECK (type ~ '^[A-Z][A-Z0-9_]{0,63}$')
);
-- ddl-end --
COMMENT ON TABLE technical.scheduled_job IS E'Durable PostgreSQL scheduler. now < deadline permits; now >= deadline means expiry owns the state. Late workers revalidate and cannot change Product outcome. v1.1.25 generic lifecycle for every job type: PENDING -> LEASED | PAUSED | DONE | SUPERSEDED; PAUSED -> PENDING (explicit re-arm, the only path that may move due_at) | SUPERSEDED; LEASED -> DONE | FAILED | PENDING (release) | SUPERSEDED; FAILED -> PENDING (explicit re-arm) | SUPERSEDED; DONE and SUPERSEDED are terminal. type/subject/idempotency_key are immutable.';
-- ddl-end --
COMMENT ON COLUMN technical.scheduled_job.type IS E'VENUE_RESPONSE_EXPIRY · LATE_CONFIRM_EXPIRY · BOOKING_START · ...';
-- ddl-end --
COMMENT ON COLUMN technical.scheduled_job.due_at IS E'persisted — never computed at read time';
-- ddl-end --
COMMENT ON COLUMN technical.scheduled_job.status IS E'PENDING · PAUSED · LEASED · DONE · SUPERSEDED · FAILED';
-- ddl-end --
COMMENT ON COLUMN technical.scheduled_job.subject_type IS E'Aggregate type of subject_id (e.g. BOOKING, TOURNAMENT)';
-- ddl-end --
ALTER TABLE technical.scheduled_job OWNER TO postgres;
-- ddl-end --

