-- object: config.configuration_version | type: TABLE --
-- DROP TABLE IF EXISTS config.configuration_version CASCADE;
CREATE TABLE config.configuration_version (
	id uuid NOT NULL,
	key text NOT NULL,
	old_value jsonb,
	new_value jsonb NOT NULL,
	effective_from timestamp with time zone NOT NULL,
	admin_id uuid,
	reason text,
	changed_at timestamp with time zone NOT NULL DEFAULT clock_timestamp(),
	correlation_id uuid NOT NULL DEFAULT gen_random_uuid(),
	version_position bigint NOT NULL GENERATED ALWAYS AS IDENTITY ,
	CONSTRAINT configuration_version_pk PRIMARY KEY (id),
	CONSTRAINT ck_config_future_only CHECK (effective_from = changed_at OR (effective_from = '-infinity'::timestamptz AND admin_id IS NULL)),
	CONSTRAINT ck_config_reason CHECK (reason IS NOT NULL AND length(btrim(reason)) > 0),
	CONSTRAINT uq_config_version_position UNIQUE (version_position)
);
-- ddl-end --
COMMENT ON TABLE config.configuration_version IS E'APPEND-ONLY version history (no UPDATE/DELETE/TRUNCATE). Written only by config.change_configuration / loyalty.configure inside a trusted Admin command. version_position is DB-generated and totally orders history; (key, effective_from) is unique. Future-only: effective_from = changed_at = server command time; the single exception is the initial technical bootstrap (effective_from = -infinity, no Admin).';
-- ddl-end --
COMMENT ON COLUMN config.configuration_version.effective_from IS E'FUTURE EVENTS ONLY';
-- ddl-end --
ALTER TABLE config.configuration_version OWNER TO postgres;
-- ddl-end --

-- object: config.configuration_key | type: TABLE --
-- DROP TABLE IF EXISTS config.configuration_key CASCADE;
CREATE TABLE config.configuration_key (
	key text NOT NULL,
	value_type text NOT NULL,
	min_value numeric,
	max_value numeric,
	units text,
	allowed_values jsonb,
	owner_module text NOT NULL,
	source_reference text NOT NULL,
	registered_at timestamp with time zone NOT NULL DEFAULT clock_timestamp(),
	CONSTRAINT configuration_key_pk PRIMARY KEY (key),
	CONSTRAINT ck_configuration_key_values CHECK (key ~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)*$' AND value_type IN ('INTEGER','NUMERIC','BOOLEAN','TEXT') AND (min_value IS NULL OR max_value IS NULL OR min_value <= max_value) AND (value_type IN ('INTEGER','NUMERIC') OR (min_value IS NULL AND max_value IS NULL)) AND (allowed_values IS NULL OR (jsonb_typeof(allowed_values) = 'array' AND jsonb_array_length(allowed_values) > 0)) AND length(btrim(owner_module)) > 0 AND length(btrim(source_reference)) > 0)
);
-- ddl-end --
COMMENT ON TABLE config.configuration_key IS E'TECHNICAL configuration registry: type, range, units and allowed values per key. Registration is a deployment operation (append-only). Every configuration_version / system_configuration value must validate against its key''s registry row; unregistered keys are rejected. No Product rule is introduced here - entries restate documented values/ranges only.';
-- ddl-end --
COMMENT ON COLUMN config.configuration_key.value_type IS E'INTEGER · NUMERIC · BOOLEAN · TEXT';
-- ddl-end --
COMMENT ON COLUMN config.configuration_key.allowed_values IS E'JSON array of permitted values, or NULL';
-- ddl-end --
COMMENT ON COLUMN config.configuration_key.owner_module IS E'Module whose producer writes the key (e.g. loyalty, platform)';
-- ddl-end --
ALTER TABLE config.configuration_key OWNER TO postgres;
-- ddl-end --

