-- object: iam.security_rate_limit_counter | type: TABLE --
-- DROP TABLE IF EXISTS iam.security_rate_limit_counter CASCADE;
CREATE TABLE iam.security_rate_limit_counter (
	id uuid NOT NULL,
	limiter_type text NOT NULL,
	subject_key_hash text NOT NULL,
	action_class text,
	window_started_at timestamp with time zone NOT NULL,
	window_seconds integer NOT NULL,
	counter integer NOT NULL DEFAULT 0,
	cooldown_until timestamp with time zone,
	version bigint NOT NULL DEFAULT 0,
	updated_at timestamp with time zone NOT NULL,
	CONSTRAINT security_rate_limit_counter_pk PRIMARY KEY (id),
	CONSTRAINT uq_security_rate_limit_key UNIQUE NULLS NOT DISTINCT (limiter_type,subject_key_hash,action_class),
	CONSTRAINT ck_rate_limit_limiter_type CHECK (limiter_type IN ('OTP_SEND','OTP_ATTEMPT','OWNER_PASSWORD','LOGIN'))
);
