COMMENT ON TABLE iam.security_rate_limit_counter IS E'PostgreSQL authoritative fallback for mandatory security rate limits when Redis is unavailable. Never permits OTP, Owner Password or login limits to fail open. LOGIN rows: subject_key_hash = hash(login identifier + client IP), action_class = CUSTOMER / VENUE / ADMIN.';
-- ddl-end --
COMMENT ON COLUMN iam.security_rate_limit_counter.limiter_type IS E'OTP_SEND · OTP_ATTEMPT · OWNER_PASSWORD · LOGIN';
-- ddl-end --
COMMENT ON COLUMN iam.security_rate_limit_counter.subject_key_hash IS E'Hash of destination/account+IP key; avoid raw PII in limiter keys.';
-- ddl-end --
COMMENT ON COLUMN iam.security_rate_limit_counter.action_class IS E'Protected command class; NULL for OTP.';
-- ddl-end --
COMMENT ON COLUMN iam.security_rate_limit_counter.window_seconds IS E'Architecture/security setting, not a Product enum.';
-- ddl-end --
COMMENT ON COLUMN iam.security_rate_limit_counter.cooldown_until IS E'Optional escalation for Owner Password.';
-- ddl-end --
ALTER TABLE iam.security_rate_limit_counter OWNER TO postgres;
-- ddl-end --

-- object: trust.trust_projection_checkpoint | type: TABLE --
-- DROP TABLE IF EXISTS trust.trust_projection_checkpoint CASCADE;
CREATE TABLE trust.trust_projection_checkpoint (
	id uuid NOT NULL,
	user_id uuid NOT NULL,
	checkpoint_effective_at timestamp with time zone NOT NULL,
	checkpoint_event_sequence bigint NOT NULL,
	state_snapshot jsonb NOT NULL,
	snapshot_version bigint NOT NULL DEFAULT 1,
	created_at timestamp with time zone NOT NULL,
	CONSTRAINT trust_projection_checkpoint_pk PRIMARY KEY (id),
	CONSTRAINT uq_trust_checkpoint_position UNIQUE (user_id,checkpoint_effective_at,checkpoint_event_sequence),
	CONSTRAINT ck_trust_checkpoint_snapshot CHECK (jsonb_typeof(state_snapshot) = 'object' AND snapshot_version >= 1)
);
-- ddl-end --
COMMENT ON TABLE trust.trust_projection_checkpoint IS E'Periodic rebuild checkpoint at a COMPOSITE Trust position. A retroactive correction replays from the newest checkpoint at or before its (effective_at,event_sequence) position.';
-- ddl-end --
COMMENT ON COLUMN trust.trust_projection_checkpoint.checkpoint_effective_at IS E'Composite position part 1.';
-- ddl-end --
COMMENT ON COLUMN trust.trust_projection_checkpoint.checkpoint_event_sequence IS E'Composite position part 2.';
-- ddl-end --
COMMENT ON COLUMN trust.trust_projection_checkpoint.state_snapshot IS E'Deterministic fold snapshot only; rebuildable.';
-- ddl-end --
COMMENT ON COLUMN trust.trust_projection_checkpoint.snapshot_version IS E'Version of the replay-fold snapshot schema.';
-- ddl-end --
ALTER TABLE trust.trust_projection_checkpoint OWNER TO postgres;
-- ddl-end --

-- object: trust.cascade_execution | type: TABLE --
-- DROP TABLE IF EXISTS trust.cascade_execution CASCADE;
CREATE TABLE trust.cascade_execution (
	id uuid NOT NULL,
	cascade_type text NOT NULL,
	cascade_key text NOT NULL,
	subject_user_id uuid,
	source_id uuid,
	executed_at timestamp with time zone NOT NULL,
	correlation_id uuid NOT NULL,
	CONSTRAINT cascade_execution_pk PRIMARY KEY (id),
	CONSTRAINT uq_cascade_execution_key UNIQUE (cascade_type,cascade_key),
	CONSTRAINT ck_cascade_execution_type CHECK (cascade_type IN ('BAN','VERIFIED_PLAYER','OWNER_REVIEW','ACCOUNT_DISABLE','OTHER')),
	CONSTRAINT ck_cascade_execution_source_shape CHECK (cascade_type NOT IN ('BAN','VERIFIED_PLAYER') OR (subject_user_id IS NOT NULL AND source_id IS NOT NULL))
);
-- ddl-end --
COMMENT ON TABLE trust.cascade_execution IS E'Once-only side-effect guard. Prevents the same Ban/Verified Player/operational cascade from cancelling or releasing the same external commitments twice.';
-- ddl-end --
COMMENT ON COLUMN trust.cascade_execution.cascade_type IS E'BAN · VERIFIED_PLAYER · OWNER_REVIEW · ACCOUNT_DISABLE · OTHER';
-- ddl-end --
COMMENT ON COLUMN trust.cascade_execution.cascade_key IS E'Stable idempotency key, e.g. BAN_CASCADE:{banInstanceId}.';
-- ddl-end --
COMMENT ON COLUMN trust.cascade_execution.subject_user_id IS E'Nullable for non-user cascades.';
-- ddl-end --
COMMENT ON COLUMN trust.cascade_execution.source_id IS E'Ban instance / transition / operational aggregate.';
-- ddl-end --
ALTER TABLE trust.cascade_execution OWNER TO postgres;
-- ddl-end --

-- object: trust.ban_qualification_consumption | type: TABLE --
-- DROP TABLE IF EXISTS trust.ban_qualification_consumption CASCADE;
CREATE TABLE trust.ban_qualification_consumption (
	qualification_id uuid NOT NULL,
	ban_instance_id uuid NOT NULL,
	consequence_type varchar(80) NOT NULL,
	consumed_at timestamp with time zone NOT NULL,
	correlation_id uuid NOT NULL,
	CONSTRAINT ban_qualification_consumption_pk PRIMARY KEY (qualification_id),
	CONSTRAINT ck_ban_qualification_consumption_type CHECK (consequence_type IN ('CREATE','EXTEND'))
);
-- ddl-end --
COMMENT ON TABLE trust.ban_qualification_consumption IS E'APPEND-ONLY exactly-once operational consumption of a replay-valid Ban Qualification. CREATE consumes the initial qualification; EXTEND consumes a later qualification without rewriting the Ban''s initial provenance.';
-- ddl-end --
ALTER TABLE trust.ban_qualification_consumption OWNER TO postgres;
-- ddl-end --

-- object: trust.ban_cascade_booking_target | type: TABLE --
-- DROP TABLE IF EXISTS trust.ban_cascade_booking_target CASCADE;
CREATE TABLE trust.ban_cascade_booking_target (
	ban_instance_id uuid NOT NULL,
	booking_id uuid NOT NULL,
	from_status varchar(80) NOT NULL,
	registered_at timestamp with time zone NOT NULL,
	correlation_id uuid NOT NULL,
	CONSTRAINT ban_cascade_booking_target_pk PRIMARY KEY (ban_instance_id,booking_id),
	CONSTRAINT ck_ban_cascade_booking_target_status CHECK (from_status IN ('PENDING','AWAITING_CUSTOMER_CONFIRMATION','CONFIRMED'))
);
-- ddl-end --
COMMENT ON TABLE trust.ban_cascade_booking_target IS E'APPEND-ONLY exact Booking target set captured after the User lock and before the Ban cancellation cascade.';
-- ddl-end --
ALTER TABLE trust.ban_cascade_booking_target OWNER TO postgres;
-- ddl-end --

-- object: trust.ban_cascade_reservation_target | type: TABLE --
-- DROP TABLE IF EXISTS trust.ban_cascade_reservation_target CASCADE;
CREATE TABLE trust.ban_cascade_reservation_target (
