	reservation_id uuid NOT NULL,
	booking_id uuid NOT NULL,
	registered_at timestamp with time zone NOT NULL,
	CONSTRAINT ban_cascade_reservation_target_pk PRIMARY KEY (ban_instance_id,reservation_id)
);
-- ddl-end --
COMMENT ON TABLE trust.ban_cascade_reservation_target IS E'APPEND-ONLY exact Resource reservation/Hold release set captured with its parent Ban Booking target set.';
-- ddl-end --
ALTER TABLE trust.ban_cascade_reservation_target OWNER TO postgres;
-- ddl-end --

-- object: loyalty.reward_application | type: TABLE --
-- DROP TABLE IF EXISTS loyalty.reward_application CASCADE;
CREATE TABLE loyalty.reward_application (
	id uuid NOT NULL,
	application_sequence bigint NOT NULL,
	source_kind text NOT NULL,
	booking_id uuid,
	referral_id uuid,
	source_event_id uuid,
	user_id uuid NOT NULL,
	operation_key text NOT NULL,
	previous_application_id uuid,
	entitlement_before integer NOT NULL,
	entitlement_after integer NOT NULL,
	reward_value integer NOT NULL,
	configuration_as_of timestamp with time zone NOT NULL,
	configuration_version_id uuid NOT NULL,
	points_transaction_id uuid,
	applied_at timestamp with time zone NOT NULL,
	correlation_id uuid NOT NULL,
	CONSTRAINT reward_application_pk PRIMARY KEY (id),
	CONSTRAINT ck_reward_application_source CHECK ((source_kind='BOOKING' AND booking_id IS NOT NULL AND referral_id IS NULL AND source_event_id IS NOT NULL) OR (source_kind='REFERRAL' AND referral_id IS NOT NULL AND booking_id IS NULL AND source_event_id IS NULL)),
	CONSTRAINT ck_reward_application_entitlement CHECK (reward_value>=0 AND entitlement_before IN (0,reward_value) AND entitlement_after IN (0,reward_value)),
	CONSTRAINT uq_reward_app_operation UNIQUE (operation_key),
	CONSTRAINT uq_reward_app_sequence UNIQUE (application_sequence),
	CONSTRAINT uq_reward_app_tx UNIQUE (points_transaction_id),
	CONSTRAINT uq_reward_app_predecessor UNIQUE (previous_application_id)
);
-- ddl-end --
COMMENT ON TABLE loyalty.reward_application IS E'Append-only reward reconciliation. One canonical source effect, one application. Zero-effect source changes are retained without inventing a monetary movement. The latest application is validated against current source eligibility.';
-- ddl-end --
ALTER TABLE loyalty.reward_application OWNER TO postgres;
-- ddl-end --

-- object: loyalty.booking_fee_receipt | type: TABLE --
-- DROP TABLE IF EXISTS loyalty.booking_fee_receipt CASCADE;
CREATE TABLE loyalty.booking_fee_receipt (
	id uuid NOT NULL,
	booking_id uuid NOT NULL,
	user_id uuid NOT NULL,
	amount numeric(12,2) NOT NULL,
	currency text NOT NULL DEFAULT 'EGP',
	provider text NOT NULL,
	provider_reference text NOT NULL,
	provider_occurred_at timestamp with time zone NOT NULL,
	received_at timestamp with time zone NOT NULL,
	correlation_id uuid NOT NULL,
	audit_event_id uuid NOT NULL,
	CONSTRAINT booking_fee_receipt_pk PRIMARY KEY (id),
	CONSTRAINT ck_fee_receipt_amount CHECK (amount>0 AND amount<>'NaN'::numeric AND currency='EGP' AND NULLIF(btrim(provider),'') IS NOT NULL AND NULLIF(btrim(provider_reference),'') IS NOT NULL AND provider_occurred_at<=received_at),
	CONSTRAINT uq_fee_receipt_booking UNIQUE (booking_id),
	CONSTRAINT uq_fee_receipt_provider UNIQUE (provider,provider_reference)
);
-- ddl-end --
COMMENT ON TABLE loyalty.booking_fee_receipt IS E'Immutable confirmation of collected E7GZ Booking Fee from a trusted payment adapter. A fee snapshot is not proof of collection. No provider or customer funding integration is activated by this schema.';
-- ddl-end --
ALTER TABLE loyalty.booking_fee_receipt OWNER TO postgres;
-- ddl-end --

