CREATE OR REPLACE FUNCTION resource.reject_resource_state_change_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    RAISE EXCEPTION 'resource.resource_state_change is append-only';
END;
$function$;

CREATE TRIGGER tr_resource_state_change_append_only
BEFORE UPDATE OR DELETE ON resource.resource_state_change
FOR EACH ROW EXECUTE FUNCTION resource.reject_resource_state_change_mutation();

CREATE OR REPLACE FUNCTION pricing.validate_resource_price_override()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_activity varchar(80);
    v_console_type varchar(80);
BEGIN
    SELECT activity, console_type
      INTO v_activity, v_console_type
      FROM resource.resource
     WHERE id = NEW.resource_id
     FOR KEY SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Resource % does not exist', NEW.resource_id;
    END IF;
    IF v_activity <> 'PLAYSTATION' THEN
        RAISE EXCEPTION 'Resource price overrides are allowed only for PLAYSTATION resources';
    END IF;
    IF NEW.console_type IS DISTINCT FROM v_console_type THEN
        RAISE EXCEPTION 'Override console % does not match resource console %', NEW.console_type, v_console_type;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_validate_resource_price_override
BEFORE INSERT OR UPDATE ON pricing.resource_price_override
FOR EACH ROW EXECUTE FUNCTION pricing.validate_resource_price_override();

CREATE OR REPLACE FUNCTION pricing.clear_resource_price_overrides_on_console_change()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    DELETE FROM pricing.resource_price_override WHERE resource_id = OLD.id;
    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_clear_resource_price_overrides_on_console_change
BEFORE UPDATE OF activity, console_type ON resource.resource
FOR EACH ROW
WHEN (OLD.activity IS DISTINCT FROM NEW.activity OR OLD.console_type IS DISTINCT FROM NEW.console_type)
EXECUTE FUNCTION pricing.clear_resource_price_overrides_on_console_change();


-- v1.1.5 inventory-checkpoint integrity hardening. These guards are load-bearing and MUST be carried into Flyway/production DDL.

-- Derive the canonical planned range and preserve immutable reservation identity/plan fields.
CREATE OR REPLACE FUNCTION inventory.prepare_resource_reservation()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.planned_range := tstzrange(NEW.planned_start, NEW.planned_end, '[)');
        RETURN NEW;
    END IF;

    IF NEW.resource_id IS DISTINCT FROM OLD.resource_id
       OR NEW.reservation_type IS DISTINCT FROM OLD.reservation_type
       OR NEW.booking_id IS DISTINCT FROM OLD.booking_id
       OR NEW.tournament_id IS DISTINCT FROM OLD.tournament_id
       OR NEW.maintenance_id IS DISTINCT FROM OLD.maintenance_id
       OR NEW.closure_id IS DISTINCT FROM OLD.closure_id
       OR NEW.planned_start IS DISTINCT FROM OLD.planned_start
       OR NEW.planned_end IS DISTINCT FROM OLD.planned_end
       OR NEW.planned_range IS DISTINCT FROM OLD.planned_range THEN
        RAISE EXCEPTION 'resource_reservation owner and planned interval are immutable after insert';
    END IF;

    IF OLD.active_flag = false AND NEW.active_flag = true THEN
        RAISE EXCEPTION 'released resource_reservation cannot be reactivated';
    END IF;

    IF OLD.actual_reservation_release_at IS NOT NULL AND
       (NEW.actual_reservation_release_at IS DISTINCT FROM OLD.actual_reservation_release_at
        OR NEW.release_reason IS DISTINCT FROM OLD.release_reason
        OR NEW.active_flag IS DISTINCT FROM OLD.active_flag) THEN
        RAISE EXCEPTION 'resource_reservation release facts are immutable once recorded';
    END IF;

    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_00_prepare_resource_reservation
BEFORE INSERT OR UPDATE ON inventory.resource_reservation
FOR EACH ROW EXECUTE FUNCTION inventory.prepare_resource_reservation();

-- I1 final GiST defence for mutually-exclusive active rows. MAINTENANCE is intentionally excluded;
-- cross-class conflicts involving Maintenance are enforced by the serialized trigger below.
ALTER TABLE inventory.resource_reservation
    ADD CONSTRAINT ex_no_double_booking
    EXCLUDE USING gist (
        resource_id WITH =,
        planned_range WITH &&
    )
    WHERE (active_flag = true AND reservation_type <> 'MAINTENANCE');

CREATE OR REPLACE FUNCTION inventory.guard_resource_reservation_cross_class()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_conflict boolean;
BEGIN
    IF NOT NEW.active_flag THEN
        RETURN NEW;
    END IF;

    -- Serialize all cross-class decisions for the Resource.
    PERFORM 1 FROM resource.resource WHERE id = NEW.resource_id FOR UPDATE;

    IF NEW.reservation_type = 'MAINTENANCE' THEN
        -- New Maintenance may overlap Maintenance only; it may not overlap Closure or commitments.
        SELECT EXISTS (
            SELECT 1
              FROM inventory.resource_reservation r
             WHERE r.resource_id = NEW.resource_id
               AND r.id IS DISTINCT FROM NEW.id
               AND r.active_flag
               AND r.planned_range && NEW.planned_range
               AND r.reservation_type <> 'MAINTENANCE'
        ) INTO v_conflict;
    ELSIF NEW.reservation_type = 'CLOSURE' THEN
        -- Closure may overlap existing Maintenance, but never commitments or another active Closure.
        SELECT EXISTS (
            SELECT 1
              FROM inventory.resource_reservation r
             WHERE r.resource_id = NEW.resource_id
               AND r.id IS DISTINCT FROM NEW.id
               AND r.active_flag
               AND r.planned_range && NEW.planned_range
               AND r.reservation_type <> 'MAINTENANCE'
        ) INTO v_conflict;
    ELSE
        -- Booking / Late Confirm / Tournament commitments may overlap nothing active, including Maintenance.
        SELECT EXISTS (
            SELECT 1
              FROM inventory.resource_reservation r
             WHERE r.resource_id = NEW.resource_id
               AND r.id IS DISTINCT FROM NEW.id
               AND r.active_flag
               AND r.planned_range && NEW.planned_range
        ) INTO v_conflict;
    END IF;

    IF v_conflict THEN
        RAISE EXCEPTION 'resource reservation conflict for resource % in interval %', NEW.resource_id, NEW.planned_range;
    END IF;

    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_10_resource_reservation_cross_class_guard
BEFORE INSERT OR UPDATE OF active_flag ON inventory.resource_reservation
FOR EACH ROW EXECUTE FUNCTION inventory.guard_resource_reservation_cross_class();

-- I2: commitment_period is derived from the Product's counted Online states.
CREATE OR REPLACE FUNCTION booking.derive_commitment_period()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.source = 'ONLINE'
       AND NEW.customer_id IS NOT NULL
       AND NEW.status IN ('PENDING','AWAITING_CUSTOMER_CONFIRMATION','CONFIRMED','ACTIVE') THEN
        NEW.commitment_period := tstzrange(NEW.start_at, NEW.end_at, '[)');
    ELSE
        NEW.commitment_period := NULL;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_00_booking_commitment_period
BEFORE INSERT OR UPDATE OF source, status, customer_id, start_at, end_at ON booking.booking
FOR EACH ROW EXECUTE FUNCTION booking.derive_commitment_period();

ALTER TABLE booking.booking
    ADD CONSTRAINT ex_customer_no_overlap
    EXCLUDE USING gist (
        customer_id WITH =,
        commitment_period WITH &&
    )
    WHERE (commitment_period IS NOT NULL);

-- Common append-only guard for physical history/ledger stores.
CREATE OR REPLACE FUNCTION technical.reject_append_only_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    RAISE EXCEPTION '%.% is append-only', TG_TABLE_SCHEMA, TG_TABLE_NAME;
END;
$function$;

CREATE TRIGGER tr_booking_history_append_only
BEFORE UPDATE OR DELETE ON booking.booking_history
FOR EACH ROW EXECUTE FUNCTION technical.reject_append_only_mutation();

CREATE TRIGGER tr_tournament_history_append_only
BEFORE UPDATE OR DELETE ON tournament.tournament_history
