-- Physical reconciliation of the architecture's immutable restriction history:
-- the row may be closed exactly once by setting reenabled_at; no other mutation or delete is allowed.
CREATE OR REPLACE FUNCTION iam.guard_venue_restriction_interval_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'iam.venue_account_restriction_interval is immutable history';
    END IF;

    IF OLD.reenabled_at IS NULL
       AND NEW.reenabled_at IS NOT NULL
       AND NEW.id IS NOT DISTINCT FROM OLD.id
       AND NEW.venue_id IS NOT DISTINCT FROM OLD.venue_id
       AND NEW.disabled_at IS NOT DISTINCT FROM OLD.disabled_at
       AND NEW.source IS NOT DISTINCT FROM OLD.source
       AND NEW.admin_id IS NOT DISTINCT FROM OLD.admin_id
       AND NEW.reason IS NOT DISTINCT FROM OLD.reason
       AND NEW.correlation_id IS NOT DISTINCT FROM OLD.correlation_id THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'venue restriction history permits only the one-time reenabled_at close';
END;
$function$;

CREATE TRIGGER tr_venue_restriction_interval_immutable
BEFORE UPDATE OR DELETE ON iam.venue_account_restriction_interval
FOR EACH ROW EXECUTE FUNCTION iam.guard_venue_restriction_interval_mutation();

-- Physical-model mapping note:
-- booking_event is represented by booking.booking_history rows with entry_kind='BOOKING_EVENT'.
-- points_ledger / wallet_ledger map to loyalty.points_transaction / loyalty.wallet_transaction.
-- attendance evidence is represented inside attendance.attendance_record in this 68-table ERD and therefore
-- is not blanket-blocked from UPDATE because reversal timestamps are part of its approved physical lifecycle.


-- v1.1.6 Operations hardening. These guards are load-bearing and MUST be carried into Flyway/production DDL.
-- They preserve the Product v5.0 / PRD v1.1 / FRS v1.1 / Technical Architecture v1.2 behavior without adding Product-visible states or reason codes.

-- -----------------------------------------------------------------------------
-- O1. Physical close lifecycle for booking timer-pause history.
-- Product history is immutable after completion, while Architecture v1.2 requires
-- the open row to be closed once on resume/cap resolution.
-- -----------------------------------------------------------------------------
DROP TRIGGER IF EXISTS tr_booking_timer_pause_history_append_only ON operations.booking_timer_pause_history;

CREATE OR REPLACE FUNCTION operations.guard_booking_timer_pause_history_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'operations.booking_timer_pause_history is immutable history';
    END IF;

    IF OLD.pause_ended_at IS NULL
       AND NEW.pause_ended_at IS NOT NULL
       AND NEW.id IS NOT DISTINCT FROM OLD.id
       AND NEW.booking_id IS NOT DISTINCT FROM OLD.booking_id
       AND NEW.sequence IS NOT DISTINCT FROM OLD.sequence
       AND NEW.pause_kind IS NOT DISTINCT FROM OLD.pause_kind
       AND NEW.pause_started_at IS NOT DISTINCT FROM OLD.pause_started_at
       AND NEW.pause_cause IS NOT DISTINCT FROM OLD.pause_cause
       AND NEW.accumulated_duration IS NOT NULL
       AND NEW.accumulated_duration >= COALESCE(OLD.accumulated_duration, interval '0') THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'timer-pause history permits only the one-time pause close';
END;
$function$;

CREATE TRIGGER tr_booking_timer_pause_history_immutable_close
BEFORE UPDATE OR DELETE ON operations.booking_timer_pause_history
FOR EACH ROW EXECUTE FUNCTION operations.guard_booking_timer_pause_history_mutation();

-- -----------------------------------------------------------------------------
-- O2. OWNER_REVIEW_REQUIRED row lifecycle: one open review per Resource and a
-- one-time Owner-authorized close. Final-state prerequisites are asserted at commit.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION operations.guard_owner_review_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'operations.owner_review is immutable operational history';
    END IF;

    IF OLD.resolved_at IS NULL
       AND OLD.resolution IS NULL
       AND OLD.owner_password_used = false
       AND NEW.resolved_at IS NOT NULL
       AND NEW.resolution IS NOT NULL
       AND NEW.owner_password_used = true
       AND NEW.id IS NOT DISTINCT FROM OLD.id
       AND NEW.resource_id IS NOT DISTINCT FROM OLD.resource_id
       AND NEW.entered_at IS NOT DISTINCT FROM OLD.entered_at
       AND NEW.entry_cause IS NOT DISTINCT FROM OLD.entry_cause
       AND NEW.correlation_id IS NOT DISTINCT FROM OLD.correlation_id THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'owner_review permits only the one-time Owner-authorized resolution close';
END;
$function$;

CREATE TRIGGER tr_owner_review_immutable_close
BEFORE UPDATE OR DELETE ON operations.owner_review
FOR EACH ROW EXECUTE FUNCTION operations.guard_owner_review_mutation();

CREATE OR REPLACE FUNCTION operations.assert_owner_review_resolution()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_base varchar(80);
    v_restriction varchar(80);
    v_blocked boolean;
    v_maintenance boolean;
BEGIN
    -- Query final state at deferred execution time rather than trusting the row image.
    SELECT r.base_state, r.operational_restriction
      INTO v_base, v_restriction
      FROM resource.resource r
     WHERE r.id = NEW.resource_id;

    IF NEW.resolved_at IS NULL THEN
        RETURN NULL;
    END IF;

    IF v_restriction <> 'NONE' THEN
        RAISE EXCEPTION 'resolved owner review requires operational_restriction=NONE for resource %', NEW.resource_id;
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM resource.resource_selling_block b
        WHERE b.resource_id = NEW.resource_id AND b.active
    ) INTO v_blocked;

    IF NEW.resolution = 'RETURN_TO_SERVICE' THEN
        IF v_base <> 'ACTIVE' OR v_blocked THEN
            RAISE EXCEPTION 'RETURN_TO_SERVICE requires ACTIVE base state and no active resource selling block';
        END IF;
        SELECT EXISTS (
            SELECT 1 FROM operations.maintenance_window m
            WHERE m.resource_id = NEW.resource_id AND m.period @> NEW.resolved_at
        ) INTO v_maintenance;
        IF v_maintenance THEN
            RAISE EXCEPTION 'RETURN_TO_SERVICE is blocked by Maintenance active at resolution time';
        END IF;
    ELSIF NEW.resolution = 'DISABLE' THEN
        IF v_base <> 'DISABLED' THEN
            RAISE EXCEPTION 'DISABLE owner-review resolution requires resource base_state=DISABLED';
        END IF;
    ELSIF NEW.resolution = 'ARCHIVE' THEN
        IF v_base <> 'ARCHIVED' THEN
            RAISE EXCEPTION 'ARCHIVE owner-review resolution requires resource base_state=ARCHIVED';
        END IF;
    ELSIF NEW.resolution = 'EXTEND_MAINTENANCE' THEN
        SELECT EXISTS (
            SELECT 1 FROM operations.maintenance_window m
            WHERE m.resource_id = NEW.resource_id
              AND lower(m.period) <= NEW.resolved_at
              AND upper(m.period) > NEW.resolved_at
        ) INTO v_maintenance;
        IF NOT v_maintenance THEN
            RAISE EXCEPTION 'EXTEND_MAINTENANCE resolution requires Maintenance covering the resolution instant';
        END IF;
    END IF;

    RETURN NULL;
END;
$function$;

CREATE CONSTRAINT TRIGGER tr_owner_review_resolution_final_state
AFTER UPDATE OF resolved_at, resolution ON operations.owner_review
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION operations.assert_owner_review_resolution();

-- -----------------------------------------------------------------------------
-- O3. Canonical unioned Maintenance minutes and rolling-48h Owner authorization.
-- Back-to-back intervals are one island; overlaps are counted once.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION operations.maintenance_union_minutes_in_window(
    p_resource_id uuid,
    p_window_start timestamptz,
    p_window_end timestamptz,
    p_candidate tstzrange DEFAULT NULL,
    p_exclude_id uuid DEFAULT NULL
)
RETURNS numeric
LANGUAGE sql
STABLE
AS $function$
WITH raw_segments AS (
    SELECT GREATEST(lower(m.period), p_window_start) AS s,
           LEAST(upper(m.period), p_window_end) AS e
      FROM operations.maintenance_window m
     WHERE m.resource_id = p_resource_id
       AND (p_exclude_id IS NULL OR m.id <> p_exclude_id)
       AND m.period && tstzrange(p_window_start, p_window_end, '[)')
    UNION ALL
    SELECT GREATEST(lower(p_candidate), p_window_start),
           LEAST(upper(p_candidate), p_window_end)
     WHERE p_candidate IS NOT NULL
       AND p_candidate && tstzrange(p_window_start, p_window_end, '[)')
), segments AS (
    SELECT s, e FROM raw_segments WHERE s < e
), ordered AS (
    SELECT s, e,
           max(e) OVER (ORDER BY s, e ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) AS previous_max_end
      FROM segments
), marked AS (
    SELECT s, e,
           CASE WHEN previous_max_end IS NULL OR s > previous_max_end THEN 1 ELSE 0 END AS island_start
      FROM ordered
), grouped AS (
    SELECT s, e,
           sum(island_start) OVER (ORDER BY s, e ROWS UNBOUNDED PRECEDING) AS island_id
      FROM marked
), merged AS (
    SELECT min(s) AS s, max(e) AS e FROM grouped GROUP BY island_id
)
SELECT COALESCE(sum(EXTRACT(epoch FROM (e - s)) / 60.0), 0)::numeric
  FROM merged;
$function$;

CREATE OR REPLACE FUNCTION operations.maintenance_candidate_max_rolling_minutes(
    p_resource_id uuid,
    p_candidate tstzrange,
    p_exclude_id uuid DEFAULT NULL
)
RETURNS numeric
LANGUAGE sql
STABLE
AS $function$
WITH relevant AS (
    SELECT m.period
      FROM operations.maintenance_window m
     WHERE m.resource_id = p_resource_id
       AND (p_exclude_id IS NULL OR m.id <> p_exclude_id)
       AND m.period && tstzrange(lower(p_candidate) - interval '48 hours',
                                 upper(p_candidate) + interval '48 hours', '[)')
    UNION ALL
    SELECT p_candidate
), points AS (
    SELECT lower(period) AS p FROM relevant
    UNION
    SELECT upper(period) - interval '48 hours' FROM relevant
), windows AS (
    SELECT p AS window_start, p + interval '48 hours' AS window_end
      FROM points
     WHERE p < upper(p_candidate)
       AND p + interval '48 hours' > lower(p_candidate)
), totals AS (
    SELECT operations.maintenance_union_minutes_in_window(
               p_resource_id, window_start, window_end, p_candidate, p_exclude_id
           ) AS minutes
      FROM windows
)
SELECT COALESCE(max(minutes), 0)::numeric FROM totals;
$function$;

CREATE OR REPLACE FUNCTION operations.guard_maintenance_window()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_max_minutes numeric;
    v_scope varchar(80);
    v_emergency_resource uuid;
    v_conflict boolean;
    v_venue_id uuid;
BEGIN
    -- Resource row is the serialization point for Maintenance versus commitments.
    SELECT r.venue_id INTO v_venue_id
      FROM resource.resource r
     WHERE r.id = NEW.resource_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Resource % does not exist', NEW.resource_id;
    END IF;

    IF TG_OP = 'UPDATE' AND (
       NEW.resource_id IS DISTINCT FROM OLD.resource_id OR
       NEW.created_from_emergency_id IS DISTINCT FROM OLD.created_from_emergency_id) THEN
        RAISE EXCEPTION 'Maintenance Resource/source identity is immutable';
    END IF;

    IF NEW.created_from_emergency_id IS NOT NULL THEN
        SELECT e.scope, e.resource_id
          INTO v_scope, v_emergency_resource
          FROM operations.emergency e
         WHERE e.id = NEW.created_from_emergency_id;
        IF NOT FOUND OR v_scope <> 'RESOURCE' OR v_emergency_resource IS DISTINCT FROM NEW.resource_id THEN
            RAISE EXCEPTION 'Emergency-generated Maintenance must reference a RESOURCE Emergency for the same Resource';
        END IF;
    END IF;

    -- Revalidate conflicts/threshold only when a new interval is created or the interval changes.
    -- A later Venue Closure is allowed to overlap pre-existing Maintenance, so a reason-only edit
    -- must not be rejected merely because that Closure now exists.
    IF TG_OP = 'INSERT' OR NEW.period IS DISTINCT FROM OLD.period THEN
        -- Authoritative conflict check even when a technical MAINTENANCE reservation row is not materialized.
        SELECT EXISTS (
            SELECT 1
              FROM inventory.resource_reservation rr
             WHERE rr.resource_id = NEW.resource_id
               AND rr.active_flag
               AND rr.reservation_type <> 'MAINTENANCE'
               AND rr.planned_range && NEW.period
        ) INTO v_conflict;
        IF v_conflict THEN
            RAISE EXCEPTION 'Maintenance may not overlap an active Booking/Tournament/Closure commitment';
        END IF;

        SELECT EXISTS (
            SELECT 1 FROM operations.venue_closure c
            WHERE c.venue_id = v_venue_id AND c.period && NEW.period
        ) INTO v_conflict;
        IF v_conflict THEN
            RAISE EXCEPTION 'New/extended Maintenance may not overlap an existing Venue Closure';
        END IF;

        v_max_minutes := operations.maintenance_candidate_max_rolling_minutes(
            NEW.resource_id,
            NEW.period,
            CASE WHEN TG_OP = 'UPDATE' THEN OLD.id ELSE NULL END
        );

        -- Genuine emergency declaration remains unprotected. Emergency-generated Maintenance is counted,
        -- but the emergency itself is not blocked by Owner Password. A manual/non-emergency Maintenance
        -- that pushes any rolling 48h total above 24h is protected.
        IF TG_OP = 'INSERT' AND NEW.created_from_emergency_id IS NULL
           AND v_max_minutes > 1440 AND NEW.owner_password_used = false THEN
            RAISE EXCEPTION 'Owner Password is required: Maintenance exceeds 24 hours in a rolling 48-hour window';
        END IF;

        -- Any edit that extends the resulting rolling total beyond the threshold is protected.
        IF TG_OP = 'UPDATE' AND NEW.period IS DISTINCT FROM OLD.period
           AND v_max_minutes > 1440 AND NEW.owner_password_used = false THEN
            RAISE EXCEPTION 'Owner Password is required for a Maintenance edit exceeding the rolling threshold';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_guard_maintenance_window
BEFORE INSERT OR UPDATE ON operations.maintenance_window
FOR EACH ROW EXECUTE FUNCTION operations.guard_maintenance_window();

-- -----------------------------------------------------------------------------
-- O4. Normal Closure serialization and commit-time affected-set integrity.
-- Closure may overlap Maintenance; unresolved commitments/Tournaments may not remain.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION operations.lock_venue_closure_scope()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    PERFORM 1 FROM venue.venue v WHERE v.id = NEW.venue_id FOR UPDATE;
    PERFORM 1 FROM resource.resource r WHERE r.venue_id = NEW.venue_id ORDER BY r.id FOR UPDATE;
    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_lock_venue_closure_scope
BEFORE INSERT OR UPDATE ON operations.venue_closure
FOR EACH ROW EXECUTE FUNCTION operations.lock_venue_closure_scope();

CREATE OR REPLACE FUNCTION operations.assert_venue_closure_affected_set_resolved()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_venue uuid;
    v_period tstzrange;
BEGIN
    SELECT c.venue_id, c.period INTO v_venue, v_period
      FROM operations.venue_closure c WHERE c.id = NEW.id;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    IF EXISTS (
        SELECT 1 FROM booking.booking b
        WHERE b.venue_id = v_venue
          AND b.status IN ('PENDING','AWAITING_CUSTOMER_CONFIRMATION','CONFIRMED','ACTIVE')
          AND tstzrange(b.start_at,b.end_at,'[)') && v_period
    ) THEN
        RAISE EXCEPTION 'Venue Closure cannot commit with unresolved Booking/Manual commitments in its interval';
    END IF;

    IF EXISTS (
        SELECT 1 FROM tournament.tournament t
        WHERE t.venue_id = v_venue
          AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE')
          AND tstzrange(t.start_at,t.end_at,'[)') && v_period
    ) THEN
        RAISE EXCEPTION 'Venue Closure cannot commit while a conflicting Tournament remains unresolved';
    END IF;

    RETURN NULL;
END;
$function$;

CREATE CONSTRAINT TRIGGER tr_venue_closure_affected_set_resolved
AFTER INSERT OR UPDATE ON operations.venue_closure
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION operations.assert_venue_closure_affected_set_resolved();

-- -----------------------------------------------------------------------------
-- O5. Emergency command guard: NOW declaration, Venue->Resource lock order,
-- same-Venue Resource scope, current Operating Session horizon, canonical range,
-- immutable declaration identity and canonical state transitions.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION operations.guard_emergency_lifecycle()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_resource_venue uuid;
    v_session_end timestamptz;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'ACTIVE' THEN
            RAISE EXCEPTION 'Emergency must be declared in ACTIVE status';
        END IF;
        NEW.declared_at := statement_timestamp();
        NEW.ended_at := NULL;
        NEW.converted_to := NULL;
    ELSE
        IF NEW.id IS DISTINCT FROM OLD.id
           OR NEW.scope IS DISTINCT FROM OLD.scope
           OR NEW.venue_id IS DISTINCT FROM OLD.venue_id
           OR NEW.resource_id IS DISTINCT FROM OLD.resource_id
           OR NEW.declared_at IS DISTINCT FROM OLD.declared_at
           OR NEW.reason IS DISTINCT FROM OLD.reason THEN
            RAISE EXCEPTION 'Emergency declaration identity/scope/reason are immutable after declaration';
        END IF;

        IF OLD.status IN ('ENDED','CONVERTED') THEN
            RAISE EXCEPTION 'Terminal Emergency state is immutable';
        END IF;

        IF OLD.status = 'ACTIVE' AND NEW.status NOT IN ('ACTIVE','AWAITING_CONFIRMATION','ENDED','CONVERTED') THEN
            RAISE EXCEPTION 'Invalid Emergency transition from ACTIVE to %', NEW.status;
        ELSIF OLD.status = 'AWAITING_CONFIRMATION' AND NEW.status NOT IN ('ACTIVE','AWAITING_CONFIRMATION','ENDED','CONVERTED') THEN
            RAISE EXCEPTION 'Invalid Emergency transition from AWAITING_CONFIRMATION to %', NEW.status;
        END IF;

        -- Canonical meaning: AWAITING_CONFIRMATION exists only after the current Expected End.
        IF NEW.status = 'AWAITING_CONFIRMATION' AND statement_timestamp() < NEW.expected_end_at THEN
            RAISE EXCEPTION 'AWAITING_CONFIRMATION requires Expected End to have been reached';
        END IF;

        -- Product §42.4 permits Extend after Expected End. That action may return AWAITING -> ACTIVE
        -- only by moving Expected End forward beyond NOW; it never clears the Selling Block.
        IF OLD.status = 'AWAITING_CONFIRMATION' AND NEW.status = 'ACTIVE' THEN
            IF NEW.expected_end_at <= OLD.expected_end_at OR NEW.expected_end_at <= statement_timestamp() THEN
                RAISE EXCEPTION 'AWAITING_CONFIRMATION may return to ACTIVE only through a valid Emergency extension';
            END IF;
        END IF;

        IF OLD.status IN ('ACTIVE','AWAITING_CONFIRMATION')
           AND NEW.status IN ('ENDED','CONVERTED')
           AND NEW.ended_at IS NULL THEN
            NEW.ended_at := statement_timestamp();
        END IF;
    END IF;

    -- Global lock order: Venue first, then Resource(s).
    PERFORM 1 FROM venue.venue v WHERE v.id = NEW.venue_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Venue % does not exist', NEW.venue_id;
    END IF;

    IF NEW.scope = 'RESOURCE' THEN
        SELECT r.venue_id INTO v_resource_venue
          FROM resource.resource r
         WHERE r.id = NEW.resource_id
         FOR UPDATE;
        IF NOT FOUND OR v_resource_venue IS DISTINCT FROM NEW.venue_id THEN
            RAISE EXCEPTION 'RESOURCE Emergency must reference a Resource belonging to the same Venue';
        END IF;
    ELSE
        -- Venue-wide cascades serialize all affected Resources in deterministic UUID order.
        PERFORM 1 FROM resource.resource r
         WHERE r.venue_id = NEW.venue_id
         ORDER BY r.id
         FOR UPDATE;
    END IF;

    SELECT upper(s.session_period) INTO v_session_end
      FROM venue.operating_session s
     WHERE s.venue_id = NEW.venue_id
       AND NEW.declared_at <@ s.session_period
     ORDER BY lower(s.session_period)
     LIMIT 1;
    IF v_session_end IS NULL THEN
        RAISE EXCEPTION 'Emergency declaration must occur inside a materialized Operating Session';
    END IF;
    IF NEW.expected_end_at > v_session_end THEN
        RAISE EXCEPTION 'Emergency expected end may not exceed the current Operating Session end';
    END IF;

    NEW.declared_period := tstzrange(NEW.declared_at, NEW.expected_end_at, '[)');
    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_00_guard_emergency_lifecycle
BEFORE INSERT OR UPDATE ON operations.emergency
FOR EACH ROW EXECUTE FUNCTION operations.guard_emergency_lifecycle();

-- Expected-End progression remains a durable-worker command, but every write is forced through
-- the lifecycle/locking/cascade guards above; no state-only helper is exposed that could bypass the atomic cascade.

-- -----------------------------------------------------------------------------
-- O6. Emergency-linked Selling Blocks: exact scope/subject, one row per Emergency,
-- one close only, no reactivation. Final Emergency<->Block state is deferred so
-- declaration/conversion/end can be one atomic transaction in either statement order.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION operations.guard_emergency_selling_block()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_scope varchar(80);
    v_venue uuid;
    v_resource uuid;
    v_declared_at timestamptz;
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF OLD.emergency_id IS NOT NULL THEN
            RAISE EXCEPTION 'Emergency selling-block history may not be deleted';
        END IF;
        RETURN OLD;
    END IF;

    IF NEW.emergency_id IS NOT NULL THEN
        SELECT e.scope, e.venue_id, e.resource_id, e.declared_at
          INTO v_scope, v_venue, v_resource, v_declared_at
          FROM operations.emergency e
         WHERE e.id = NEW.emergency_id;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Emergency % does not exist', NEW.emergency_id;
        END IF;

        IF TG_TABLE_SCHEMA = 'venue' THEN
            IF v_scope <> 'VENUE' OR NEW.venue_id IS DISTINCT FROM v_venue THEN
                RAISE EXCEPTION 'Venue selling block must reference a VENUE Emergency for the same Venue';
            END IF;
        ELSE
            IF v_scope <> 'RESOURCE' OR NEW.resource_id IS DISTINCT FROM v_resource THEN
                RAISE EXCEPTION 'Resource selling block must reference a RESOURCE Emergency for the same Resource';
            END IF;
        END IF;

        IF TG_OP = 'INSERT' THEN
            NEW.started_at := v_declared_at;
            NEW.active := true;
            NEW.ended_at := NULL;
        ELSE
            IF NEW.emergency_id IS DISTINCT FROM OLD.emergency_id
               OR NEW.started_at IS DISTINCT FROM OLD.started_at
               OR NEW.cause IS DISTINCT FROM OLD.cause THEN
                RAISE EXCEPTION 'Emergency selling-block identity/start/cause are immutable';
            END IF;
            IF TG_TABLE_SCHEMA = 'venue' AND NEW.venue_id IS DISTINCT FROM OLD.venue_id THEN
                RAISE EXCEPTION 'Venue selling-block subject is immutable';
            END IF;
            IF TG_TABLE_SCHEMA = 'resource' AND NEW.resource_id IS DISTINCT FROM OLD.resource_id THEN
                RAISE EXCEPTION 'Resource selling-block subject is immutable';
            END IF;
            IF OLD.active = false AND (NEW.active OR NEW.ended_at IS DISTINCT FROM OLD.ended_at) THEN
                RAISE EXCEPTION 'Closed Emergency selling block cannot be reactivated or rewritten';
            END IF;
            IF OLD.active = true AND NEW.active = true AND NEW.ended_at IS NOT NULL THEN
                RAISE EXCEPTION 'Active selling block cannot have ended_at';
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_guard_venue_emergency_selling_block
BEFORE INSERT OR UPDATE OR DELETE ON venue.venue_selling_block
FOR EACH ROW EXECUTE FUNCTION operations.guard_emergency_selling_block();

CREATE TRIGGER tr_guard_resource_emergency_selling_block
BEFORE INSERT OR UPDATE OR DELETE ON resource.resource_selling_block
FOR EACH ROW EXECUTE FUNCTION operations.guard_emergency_selling_block();

CREATE OR REPLACE FUNCTION operations.assert_emergency_block_consistency()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_emergency_id uuid;
    e record;
    v_total integer;
    v_active integer;
    v_matching_closed integer;
BEGIN
    IF TG_TABLE_NAME = 'emergency' THEN
        v_emergency_id := NEW.id;
    ELSIF TG_OP = 'DELETE' THEN
        v_emergency_id := OLD.emergency_id;
        IF v_emergency_id IS NULL THEN RETURN NULL; END IF;
    ELSE
        v_emergency_id := NEW.emergency_id;
        IF v_emergency_id IS NULL THEN RETURN NULL; END IF;
    END IF;

    SELECT * INTO e FROM operations.emergency WHERE id = v_emergency_id;
    IF NOT FOUND THEN RETURN NULL; END IF;

    IF e.scope = 'VENUE' THEN
        SELECT count(*), count(*) FILTER (WHERE active),
               count(*) FILTER (WHERE NOT active AND ended_at = e.ended_at)
          INTO v_total, v_active, v_matching_closed
          FROM venue.venue_selling_block
         WHERE emergency_id = e.id AND venue_id = e.venue_id;
    ELSE
        SELECT count(*), count(*) FILTER (WHERE active),
               count(*) FILTER (WHERE NOT active AND ended_at = e.ended_at)
          INTO v_total, v_active, v_matching_closed
          FROM resource.resource_selling_block
         WHERE emergency_id = e.id AND resource_id = e.resource_id;
    END IF;

    IF e.status IN ('ACTIVE','AWAITING_CONFIRMATION') THEN
        IF v_total <> 1 OR v_active <> 1 THEN
            RAISE EXCEPTION 'ACTIVE/AWAITING Emergency % requires exactly one matching active selling block', e.id;
        END IF;
    ELSE
        IF v_total <> 1 OR v_active <> 0 OR v_matching_closed <> 1 THEN
            RAISE EXCEPTION 'ENDED/CONVERTED Emergency % requires its matching selling block closed at the same resolution timestamp', e.id;
        END IF;
    END IF;

    RETURN NULL;
END;
$function$;

CREATE CONSTRAINT TRIGGER tr_emergency_block_consistency_from_emergency
AFTER INSERT OR UPDATE ON operations.emergency
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION operations.assert_emergency_block_consistency();

CREATE CONSTRAINT TRIGGER tr_emergency_block_consistency_from_venue_block
AFTER INSERT OR UPDATE OR DELETE ON venue.venue_selling_block
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION operations.assert_emergency_block_consistency();

CREATE CONSTRAINT TRIGGER tr_emergency_block_consistency_from_resource_block
AFTER INSERT OR UPDATE OR DELETE ON resource.resource_selling_block
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION operations.assert_emergency_block_consistency();

-- -----------------------------------------------------------------------------
-- O7. Emergency cascade and timer-pause commit assertions.
-- The database does not duplicate the Booking/Tournament state machine; instead it
-- rejects a commit if the Operations command left an affected commitment unresolved.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION operations.assert_emergency_cascade_complete()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    e record;
BEGIN
    SELECT * INTO e FROM operations.emergency WHERE id = NEW.id;
    IF NOT FOUND THEN RETURN NULL; END IF;

    IF e.scope = 'VENUE' THEN
        IF EXISTS (
            SELECT 1 FROM booking.booking b
            WHERE b.venue_id = e.venue_id
              AND b.status IN ('PENDING','AWAITING_CUSTOMER_CONFIRMATION','CONFIRMED','ACTIVE')
              AND tstzrange(b.start_at,b.end_at,'[)') && e.declared_period
        ) THEN
            RAISE EXCEPTION 'Venue Emergency cascade left an overlapping live Booking/Manual commitment unresolved';
        END IF;

        IF EXISTS (
            SELECT 1 FROM tournament.tournament t
            WHERE t.venue_id = e.venue_id
              AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE')
              AND tstzrange(t.start_at,t.end_at,'[)') && e.declared_period
        ) THEN
            RAISE EXCEPTION 'Venue Emergency cascade left an overlapping Tournament unresolved';
        END IF;

        IF EXISTS (
            SELECT 1 FROM inventory.resource_reservation rr
            JOIN resource.resource r ON r.id = rr.resource_id
            WHERE r.venue_id = e.venue_id
              AND rr.active_flag
              AND rr.reservation_type IN ('BOOKING','LATE_CONFIRM_HOLD','TOURNAMENT_APPROVAL_HOLD','TOURNAMENT_HOLD')
              AND rr.planned_range && e.declared_period
        ) THEN
            RAISE EXCEPTION 'Venue Emergency cascade left an affected reservation/hold active';
        END IF;

        -- PENDING/AWAITING commitments outside the declared cascade interval stay alive only with paused timers
        -- while this Emergency remains operationally unresolved. Terminal resolution may legitimately resume later.
        IF e.status IN ('ACTIVE','AWAITING_CONFIRMATION') THEN
            IF EXISTS (
                SELECT 1 FROM booking.booking b
                WHERE b.venue_id = e.venue_id
                  AND b.status = 'PENDING'
                  AND b.source = 'ONLINE'
                  AND NOT (tstzrange(b.start_at,b.end_at,'[)') && e.declared_period)
                  AND (b.response_pause_started_at IS NULL OR NOT EXISTS (
                      SELECT 1 FROM operations.booking_timer_pause_history ph
                      WHERE ph.booking_id = b.id AND ph.pause_kind = 'VENUE_RESPONSE'
                        AND ph.pause_ended_at IS NULL
                  ))
            ) THEN
                RAISE EXCEPTION 'Venue Emergency requires the response timer of remaining PENDING bookings to be paused with open pause history';
            END IF;
            IF EXISTS (
                SELECT 1 FROM booking.booking b
                WHERE b.venue_id = e.venue_id
                  AND b.status = 'AWAITING_CUSTOMER_CONFIRMATION'
                  AND b.source = 'ONLINE'
                  AND NOT (tstzrange(b.start_at,b.end_at,'[)') && e.declared_period)
                  AND (b.late_confirm_pause_started_at IS NULL OR NOT EXISTS (
                      SELECT 1 FROM operations.booking_timer_pause_history ph
                      WHERE ph.booking_id = b.id AND ph.pause_kind = 'LATE_CONFIRM'
                        AND ph.pause_ended_at IS NULL
                  ))
            ) THEN
                RAISE EXCEPTION 'Venue Emergency requires remaining Late Confirm countdowns to be paused with open pause history';
            END IF;
        END IF;
    ELSE
        IF EXISTS (
            SELECT 1 FROM booking.booking b
            WHERE b.resource_id = e.resource_id
              AND b.status IN ('PENDING','AWAITING_CUSTOMER_CONFIRMATION','CONFIRMED','ACTIVE')
              AND tstzrange(b.start_at,b.end_at,'[)') && e.declared_period
        ) THEN
            RAISE EXCEPTION 'Resource Emergency cascade left an overlapping live Booking/Manual commitment unresolved';
        END IF;

        IF EXISTS (
            SELECT 1
              FROM tournament.tournament t
              JOIN tournament.tournament_resource tr ON tr.tournament_id = t.id
             WHERE tr.resource_id = e.resource_id
               AND tr.removed_at IS NULL
               AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED')
               AND tstzrange(t.start_at,t.end_at,'[)') && e.declared_period
        ) THEN
            RAISE EXCEPTION 'Resource Emergency cascade left a pre-start Tournament using the failed Resource';
        END IF;

        IF EXISTS (
            SELECT 1
              FROM tournament.tournament t
              JOIN tournament.tournament_resource tr ON tr.tournament_id = t.id
             WHERE tr.resource_id = e.resource_id
               AND tr.removed_at IS NULL
               AND t.status = 'ACTIVE'
               AND tstzrange(t.start_at,t.end_at,'[)') && e.declared_period
        ) THEN
            RAISE EXCEPTION 'Resource Emergency must remove the failed Resource from an ACTIVE Tournament';
        END IF;

        IF EXISTS (
            SELECT 1
              FROM tournament.tournament t
             WHERE t.status = 'ACTIVE'
               AND EXISTS (
                   SELECT 1 FROM tournament.tournament_resource tr0
                   WHERE tr0.tournament_id = t.id AND tr0.resource_id = e.resource_id
               )
               AND NOT EXISTS (
                   SELECT 1
                     FROM tournament.tournament_resource tr1
                     JOIN resource.resource r1 ON r1.id = tr1.resource_id
                    WHERE tr1.tournament_id = t.id
                      AND tr1.removed_at IS NULL
                      AND r1.base_state = 'ACTIVE'
                      AND r1.operational_restriction = 'NONE'
                      AND NOT EXISTS (
                          SELECT 1 FROM resource.resource_selling_block sb1
                          WHERE sb1.resource_id = r1.id AND sb1.active
                      )
               )
        ) THEN
            RAISE EXCEPTION 'ACTIVE Tournament with no remaining operational Resource must be cancelled';
        END IF;

        IF EXISTS (
            SELECT 1 FROM inventory.resource_reservation rr
            WHERE rr.resource_id = e.resource_id
              AND rr.active_flag
              AND rr.reservation_type IN ('BOOKING','LATE_CONFIRM_HOLD','TOURNAMENT_APPROVAL_HOLD','TOURNAMENT_HOLD')
              AND rr.planned_range && e.declared_period
        ) THEN
            RAISE EXCEPTION 'Resource Emergency cascade left an affected reservation/hold active';
        END IF;

        IF e.status IN ('ACTIVE','AWAITING_CONFIRMATION') THEN
            IF EXISTS (
                SELECT 1 FROM booking.booking b
                WHERE b.resource_id = e.resource_id
                  AND b.status = 'PENDING'
                  AND b.source = 'ONLINE'
                  AND NOT (tstzrange(b.start_at,b.end_at,'[)') && e.declared_period)
                  AND (b.response_pause_started_at IS NULL OR NOT EXISTS (
                      SELECT 1 FROM operations.booking_timer_pause_history ph
                      WHERE ph.booking_id = b.id AND ph.pause_kind = 'VENUE_RESPONSE'
                        AND ph.pause_ended_at IS NULL
                  ))
            ) THEN
                RAISE EXCEPTION 'Resource Emergency requires the response timer of remaining affected PENDING bookings to be paused with open pause history';
            END IF;
            IF EXISTS (
                SELECT 1 FROM booking.booking b
                WHERE b.resource_id = e.resource_id
                  AND b.status = 'AWAITING_CUSTOMER_CONFIRMATION'
                  AND b.source = 'ONLINE'
                  AND NOT (tstzrange(b.start_at,b.end_at,'[)') && e.declared_period)
                  AND (b.late_confirm_pause_started_at IS NULL OR NOT EXISTS (
                      SELECT 1 FROM operations.booking_timer_pause_history ph
                      WHERE ph.booking_id = b.id AND ph.pause_kind = 'LATE_CONFIRM'
                        AND ph.pause_ended_at IS NULL
                  ))
            ) THEN
                RAISE EXCEPTION 'Resource Emergency requires remaining affected Late Confirm countdowns to be paused with open pause history';
            END IF;
        END IF;
    END IF;

    RETURN NULL;
END;
$function$;

CREATE CONSTRAINT TRIGGER tr_emergency_cascade_complete
AFTER INSERT OR UPDATE OF expected_end_at, status ON operations.emergency
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION operations.assert_emergency_cascade_complete();

-- -----------------------------------------------------------------------------
-- O8. Rolling threshold at Resource Emergency expected/actual end.
-- If over threshold, restriction entry occurs before availability can return.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION operations.apply_owner_review_threshold_on_emergency_boundary()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_boundary timestamptz;
    v_minutes numeric;
    v_previous_restriction varchar(80);
    v_review_id uuid;
BEGIN
    IF NEW.scope <> 'RESOURCE' THEN RETURN NEW; END IF;

    IF NEW.status = 'AWAITING_CONFIRMATION' AND OLD.status = 'ACTIVE' THEN
        v_boundary := NEW.expected_end_at;
    ELSIF NEW.status = 'ENDED' AND OLD.status IN ('ACTIVE','AWAITING_CONFIRMATION') THEN
        v_boundary := NEW.ended_at;
    ELSE
        RETURN NEW;
    END IF;

    v_minutes := operations.maintenance_union_minutes_in_window(
        NEW.resource_id, v_boundary - interval '48 hours', v_boundary, NULL, NULL
    );

    IF v_minutes > 1440 THEN
        SELECT operational_restriction INTO v_previous_restriction
          FROM resource.resource WHERE id = NEW.resource_id FOR UPDATE;

        IF v_previous_restriction <> 'OWNER_REVIEW_REQUIRED' THEN
            UPDATE resource.resource
               SET operational_restriction = 'OWNER_REVIEW_REQUIRED'
             WHERE id = NEW.resource_id;

            INSERT INTO resource.resource_state_change(
                id, resource_id, from_restriction, to_restriction,
                owner_password_used, actor_type, reason, correlation_id, changed_at
            ) VALUES (
                md5(NEW.id::text || ':owner-review-state')::uuid,
                NEW.resource_id, v_previous_restriction, 'OWNER_REVIEW_REQUIRED',
                false, 'SYSTEM', 'MAINTENANCE_THRESHOLD_EXCEEDED_24H_IN_ROLLING_48H',
                NEW.id, v_boundary
            ) ON CONFLICT (id) DO NOTHING;
        END IF;

        SELECT r.id INTO v_review_id
          FROM operations.owner_review r
         WHERE r.resource_id = NEW.resource_id AND r.resolved_at IS NULL
         LIMIT 1;

        IF v_review_id IS NULL THEN
            v_review_id := md5(NEW.id::text || ':owner-review')::uuid;
            INSERT INTO operations.owner_review(
                id, resource_id, entered_at, entry_cause,
                owner_password_used, correlation_id
            ) VALUES (
                v_review_id, NEW.resource_id, v_boundary,
                'MAINTENANCE_THRESHOLD_EXCEEDED_24H_IN_ROLLING_48H',
                false, NEW.id
            );
        END IF;
    END IF;

    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_20_apply_owner_review_threshold
AFTER UPDATE OF status ON operations.emergency
FOR EACH ROW EXECUTE FUNCTION operations.apply_owner_review_threshold_on_emergency_boundary();

CREATE OR REPLACE FUNCTION operations.assert_owner_review_cascade_complete()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_resource_id uuid;
    v_current_restriction varchar(80);
    v_review record;
BEGIN
    IF TG_TABLE_SCHEMA = 'resource' THEN
        v_resource_id := NEW.id;
    ELSE
        v_resource_id := NEW.resource_id;
    END IF;
    SELECT operational_restriction INTO v_current_restriction
      FROM resource.resource WHERE id = v_resource_id;
    IF v_current_restriction <> 'OWNER_REVIEW_REQUIRED' THEN RETURN NULL; END IF;

    SELECT * INTO v_review
      FROM operations.owner_review
     WHERE resource_id = v_resource_id AND resolved_at IS NULL
     LIMIT 1;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'OWNER_REVIEW_REQUIRED Resource % requires one open owner_review row', v_resource_id;
    END IF;

    IF EXISTS (
        SELECT 1 FROM booking.booking b
        WHERE b.resource_id = v_resource_id
          AND b.status IN ('PENDING','AWAITING_CUSTOMER_CONFIRMATION','CONFIRMED','ACTIVE')
    ) THEN
        RAISE EXCEPTION 'OWNER_REVIEW_REQUIRED cascade left a Booking/Manual commitment live';
    END IF;

    IF EXISTS (
        SELECT 1 FROM inventory.resource_reservation rr
        WHERE rr.resource_id = v_resource_id
          AND rr.active_flag
          AND rr.reservation_type IN ('BOOKING','LATE_CONFIRM_HOLD','TOURNAMENT_APPROVAL_HOLD','TOURNAMENT_HOLD')
    ) THEN
        RAISE EXCEPTION 'OWNER_REVIEW_REQUIRED cascade left a reservation/hold active';
    END IF;

    IF EXISTS (
        SELECT 1 FROM tournament.tournament t
        JOIN tournament.tournament_resource tr ON tr.tournament_id = t.id
        WHERE tr.resource_id = v_resource_id
          AND tr.removed_at IS NULL
          AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE')
    ) THEN
        RAISE EXCEPTION 'OWNER_REVIEW_REQUIRED cascade left the restricted Resource assigned to a live Tournament';
    END IF;

    IF EXISTS (
        SELECT 1 FROM tournament.tournament t
        WHERE t.status = 'ACTIVE'
          AND EXISTS (
              SELECT 1 FROM tournament.tournament_resource tr0
              WHERE tr0.tournament_id = t.id AND tr0.resource_id = v_resource_id
          )
          AND NOT EXISTS (
              SELECT 1
                FROM tournament.tournament_resource tr1
                JOIN resource.resource r1 ON r1.id = tr1.resource_id
               WHERE tr1.tournament_id = t.id
                 AND tr1.removed_at IS NULL
                 AND r1.base_state = 'ACTIVE'
                 AND r1.operational_restriction = 'NONE'
                 AND NOT EXISTS (
                     SELECT 1 FROM resource.resource_selling_block sb1
                     WHERE sb1.resource_id = r1.id AND sb1.active
                 )
          )
    ) THEN
        RAISE EXCEPTION 'OWNER_REVIEW_REQUIRED left an ACTIVE Tournament with no operational Resource';
    END IF;

    -- Mark the once-only cascade guard only after the final write set is valid.
    INSERT INTO trust.cascade_execution(
        id, cascade_type, cascade_key, source_id, executed_at, correlation_id
    ) VALUES (
        md5(v_review.id::text || ':owner-review-cascade')::uuid,
        'OWNER_REVIEW', v_review.id::text, v_review.id, clock_timestamp(), v_review.correlation_id
    ) ON CONFLICT (cascade_type, cascade_key) DO NOTHING;

    RETURN NULL;
END;
$function$;

CREATE CONSTRAINT TRIGGER tr_owner_review_cascade_complete
AFTER UPDATE OF operational_restriction ON resource.resource
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW
WHEN (NEW.operational_restriction = 'OWNER_REVIEW_REQUIRED')
EXECUTE FUNCTION operations.assert_owner_review_cascade_complete();

CREATE CONSTRAINT TRIGGER tr_owner_review_insert_cascade_complete
AFTER INSERT ON operations.owner_review
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION operations.assert_owner_review_cascade_complete();

CREATE OR REPLACE FUNCTION operations.assert_owner_review_restriction_clear()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    IF EXISTS (
        SELECT 1 FROM operations.owner_review r
        WHERE r.resource_id = NEW.id AND r.resolved_at IS NULL
    ) THEN
        RAISE EXCEPTION 'Cannot clear OWNER_REVIEW_REQUIRED while an owner_review remains open';
    END IF;
    RETURN NULL;
END;
$function$;

CREATE CONSTRAINT TRIGGER tr_owner_review_restriction_clear
AFTER UPDATE OF operational_restriction ON resource.resource
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW
WHEN (OLD.operational_restriction = 'OWNER_REVIEW_REQUIRED' AND NEW.operational_restriction = 'NONE')
EXECUTE FUNCTION operations.assert_owner_review_restriction_clear();

-- -----------------------------------------------------------------------------
-- O9. Derived MAINTENANCE/CLOSURE reservation rows must exactly match their
-- authoritative Operations owner while active. Released rows remain historical snapshots.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION inventory.validate_operational_reservation_owner()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_resource uuid;
    v_period tstzrange;
    v_venue uuid;
BEGIN
    IF NOT NEW.active_flag OR NEW.reservation_type NOT IN ('MAINTENANCE','CLOSURE') THEN
        RETURN NEW;
    END IF;

    IF NEW.reservation_type = 'MAINTENANCE' THEN
        SELECT m.resource_id, m.period INTO v_resource, v_period
          FROM operations.maintenance_window m WHERE m.id = NEW.maintenance_id;
        IF NOT FOUND OR v_resource IS DISTINCT FROM NEW.resource_id
           OR lower(v_period) IS DISTINCT FROM NEW.planned_start
           OR upper(v_period) IS DISTINCT FROM NEW.planned_end THEN
            RAISE EXCEPTION 'Active MAINTENANCE reservation must exactly match its Maintenance owner';
        END IF;
    ELSE
        SELECT c.venue_id, c.period INTO v_venue, v_period
          FROM operations.venue_closure c WHERE c.id = NEW.closure_id;
        SELECT r.venue_id INTO v_resource FROM resource.resource r WHERE r.id = NEW.resource_id;
        IF NOT FOUND OR v_resource IS DISTINCT FROM v_venue
           OR lower(v_period) IS DISTINCT FROM NEW.planned_start
           OR upper(v_period) IS DISTINCT FROM NEW.planned_end THEN
            RAISE EXCEPTION 'Active CLOSURE guard reservation must match the Closure interval and a Resource in that Venue';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_05_validate_operational_reservation_owner
BEFORE INSERT OR UPDATE OF active_flag ON inventory.resource_reservation
FOR EACH ROW EXECUTE FUNCTION inventory.validate_operational_reservation_owner();

-- If an Operations owner is edited after guard materialization, any still-active
-- technical guard must be replaced in the same transaction rather than silently going stale.
CREATE OR REPLACE FUNCTION operations.assert_operational_guard_rows_match_owner()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_TABLE_NAME = 'maintenance_window' THEN
        IF EXISTS (
            SELECT 1 FROM inventory.resource_reservation rr
            WHERE rr.active_flag
              AND rr.reservation_type = 'MAINTENANCE'
              AND rr.maintenance_id = NEW.id
              AND (rr.resource_id IS DISTINCT FROM NEW.resource_id
                   OR rr.planned_start IS DISTINCT FROM lower(NEW.period)
                   OR rr.planned_end IS DISTINCT FROM upper(NEW.period))
        ) THEN
            RAISE EXCEPTION 'Active MAINTENANCE guard row is stale; release it and insert the guard for the edited interval in the same transaction';
        END IF;
    ELSE
        IF EXISTS (
            SELECT 1
              FROM inventory.resource_reservation rr
              JOIN resource.resource r ON r.id = rr.resource_id
             WHERE rr.active_flag
               AND rr.reservation_type = 'CLOSURE'
               AND rr.closure_id = NEW.id
               AND (r.venue_id IS DISTINCT FROM NEW.venue_id
                    OR rr.planned_start IS DISTINCT FROM lower(NEW.period)
                    OR rr.planned_end IS DISTINCT FROM upper(NEW.period))
        ) THEN
            RAISE EXCEPTION 'Active CLOSURE guard row is stale; replace it for the edited Closure interval in the same transaction';
        END IF;
    END IF;
    RETURN NULL;
END;
$function$;

CREATE CONSTRAINT TRIGGER tr_maintenance_guard_rows_match_owner
AFTER INSERT OR UPDATE OF period ON operations.maintenance_window
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION operations.assert_operational_guard_rows_match_owner();

CREATE CONSTRAINT TRIGGER tr_closure_guard_rows_match_owner
AFTER INSERT OR UPDATE OF period ON operations.venue_closure
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION operations.assert_operational_guard_rows_match_owner();

-- -----------------------------------------------------------------------------
-- O10. Operational interruption history: polymorphic subject validation and
-- true append-only enforcement. `cause` is intentionally not a new closed Product enum;
-- terminal Booking/Tournament reason domains remain owned by their aggregates.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION operations.validate_operational_interruption_subject()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_source varchar(80);
BEGIN
    IF NEW.subject_type IN ('BOOKING','MANUAL_BOOKING') THEN
        SELECT b.source INTO v_source FROM booking.booking b WHERE b.id = NEW.subject_id;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Operational interruption Booking subject % does not exist', NEW.subject_id;
        END IF;
        IF NEW.subject_type = 'BOOKING' AND v_source <> 'ONLINE' THEN
            RAISE EXCEPTION 'BOOKING interruption subject must reference an ONLINE Booking';
        END IF;
        IF NEW.subject_type = 'MANUAL_BOOKING' AND v_source <> 'MANUAL' THEN
            RAISE EXCEPTION 'MANUAL_BOOKING interruption subject must reference a MANUAL Booking';
        END IF;
    ELSE
        PERFORM 1 FROM tournament.tournament t WHERE t.id = NEW.subject_id;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Operational interruption Tournament subject % does not exist', NEW.subject_id;
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_validate_operational_interruption_subject
BEFORE INSERT ON operations.operational_interruption_record
FOR EACH ROW EXECUTE FUNCTION operations.validate_operational_interruption_subject();

CREATE TRIGGER tr_operational_interruption_append_only
BEFORE UPDATE OR DELETE ON operations.operational_interruption_record
FOR EACH ROW EXECUTE FUNCTION technical.reject_append_only_mutation();

-- -----------------------------------------------------------------------------
-- O11. Resource-Emergency Tournament cancellation abuse signal.
-- Threshold crossing (2 -> 3 distinct cancellations within rolling 30d) creates an
-- investigative admin alert only; it never mutates Venue/Trust/Booking state.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION operations.raise_resource_emergency_tournament_abuse_alert()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_venue_id uuid;
    v_count integer;
    v_when timestamptz;
BEGIN
    IF NEW.to_status IS DISTINCT FROM 'CANCELLED'
       OR NEW.terminal_reason IS DISTINCT FROM 'RESOURCE_EMERGENCY_OUTAGE' THEN
        RETURN NEW;
    END IF;
    IF NEW.tournament_id IS NULL OR NEW.occurred_at IS NULL THEN
        RAISE EXCEPTION 'Resource-emergency Tournament cancellation history requires tournament_id and occurred_at';
    END IF;

    SELECT t.venue_id INTO v_venue_id
      FROM tournament.tournament t WHERE t.id = NEW.tournament_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Tournament % does not exist', NEW.tournament_id;
    END IF;

    -- Serialize threshold crossing per Venue so concurrent cancellations cannot miss 2 -> 3.
    PERFORM 1 FROM venue.venue v WHERE v.id = v_venue_id FOR UPDATE;
    v_when := NEW.occurred_at;

    SELECT count(DISTINCT h.tournament_id) INTO v_count
      FROM tournament.tournament_history h
      JOIN tournament.tournament t ON t.id = h.tournament_id
     WHERE t.venue_id = v_venue_id
       AND h.to_status = 'CANCELLED'
       AND h.terminal_reason = 'RESOURCE_EMERGENCY_OUTAGE'
       AND h.occurred_at > v_when - interval '30 days'
       AND h.occurred_at <= v_when;

    IF v_count = 3 THEN
        INSERT INTO admin.admin_alert(
            id, kind, severity, subject_type, subject_id, payload, correlation_id
        ) VALUES (
            md5(NEW.id::text || ':resource-emergency-abuse-alert')::uuid,
            'TOURNAMENT_CANCELLATION_ABUSE',
            'RISK',
            'VENUE',
            v_venue_id,
            jsonb_build_object(
                'source','RESOURCE_EMERGENCY_OUTAGE',
                'cancellation_count_30d',v_count,
                'threshold',3,
                'detected_at',v_when,
                'triggering_tournament_id',NEW.tournament_id
            ),
            COALESCE(NEW.correlation_id, NEW.id)
        ) ON CONFLICT (id) DO NOTHING;
    END IF;

    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_resource_emergency_tournament_abuse_alert
AFTER INSERT ON tournament.tournament_history
FOR EACH ROW EXECUTE FUNCTION operations.raise_resource_emergency_tournament_abuse_alert();

-- -----------------------------------------------------------------------------
-- O12. Emergency conversion target assertions that are physically representable.
-- OPENING_HOURS_CHANGE remains the normal Opening-Hours transaction (template/version +
-- affected-set commit); this model deliberately does not invent a new polymorphic target FK.
-- The Emergency<->Selling-Block deferred constraint still prevents any sellable gap.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION operations.assert_emergency_conversion_target_exists()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    e record;
BEGIN
    SELECT * INTO e FROM operations.emergency WHERE id = NEW.id;
    IF NOT FOUND OR e.status <> 'CONVERTED' THEN RETURN NULL; END IF;

    IF e.converted_to = 'MAINTENANCE' THEN
        IF NOT EXISTS (
            SELECT 1 FROM operations.maintenance_window m
            WHERE m.created_from_emergency_id = e.id
              AND m.resource_id = e.resource_id
              AND lower(m.period) <= e.ended_at
              AND upper(m.period) > e.ended_at
        ) THEN
            RAISE EXCEPTION 'MAINTENANCE conversion requires matching Maintenance for the same Resource at conversion time';
        END IF;
    ELSIF e.converted_to = 'CLOSURE' THEN
        IF NOT EXISTS (
            SELECT 1 FROM operations.venue_closure c
            WHERE c.venue_id = e.venue_id AND c.period @> e.ended_at
        ) THEN
            RAISE EXCEPTION 'CLOSURE conversion requires a matching Venue Closure covering conversion time';
        END IF;
    ELSIF e.converted_to = 'DISABLED' THEN
        IF NOT EXISTS (
            SELECT 1 FROM resource.resource r
            WHERE r.id = e.resource_id AND r.base_state = 'DISABLED'
        ) THEN
            RAISE EXCEPTION 'DISABLED conversion requires Resource base_state=DISABLED';
        END IF;
    ELSIF e.converted_to = 'ARCHIVED' THEN
        IF NOT EXISTS (
            SELECT 1 FROM resource.resource r
            WHERE r.id = e.resource_id AND r.base_state = 'ARCHIVED'
        ) THEN
            RAISE EXCEPTION 'ARCHIVED conversion requires Resource base_state=ARCHIVED';
        END IF;
    ELSIF e.converted_to = 'OPENING_HOURS_CHANGE' THEN
        -- The target is the existing Venue opening template/version. Require that the template
        -- was updated no earlier than the conversion resolution instant; affected-set behavior
        -- remains governed by the normal Opening Hours transaction.
        IF NOT EXISTS (
            SELECT 1 FROM venue.venue_opening_template t
            WHERE t.venue_id = e.venue_id AND t.updated_at >= transaction_timestamp()
        ) THEN
            RAISE EXCEPTION 'OPENING_HOURS_CHANGE conversion requires a committed Venue opening-template update';
        END IF;
    END IF;

    RETURN NULL;
END;
$function$;

CREATE CONSTRAINT TRIGGER tr_emergency_conversion_target_exists
AFTER INSERT OR UPDATE OF status, converted_to ON operations.emergency
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION operations.assert_emergency_conversion_target_exists();


-- v1.1.7 Booking hardening. These guards are load-bearing and MUST be carried into Flyway/production DDL.
-- They preserve Product v5.0 / PRD v1.1 / FRS v1.1 / Technical Architecture v1.2 without inventing
-- a Product-visible state, reason, event or authorization rule.

-- -----------------------------------------------------------------------------
-- B1. Booking creation snapshot integrity.
-- Validate current authoritative Resource/Venue and Operating Session once at insert;
-- the historical snapshot is then protected from silent rewrites by B2.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION booking.validate_booking_insert_snapshot()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    r resource.resource%ROWTYPE;
    os venue.operating_session%ROWTYPE;
BEGIN
    SELECT * INTO r FROM resource.resource WHERE id = NEW.resource_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'booking resource does not exist';
    END IF;

    IF r.venue_id <> NEW.venue_id THEN
        RAISE EXCEPTION 'booking venue_id must match the Resource venue';
    END IF;
    IF r.activity <> NEW.activity THEN
        RAISE EXCEPTION 'booking activity snapshot must match the Resource activity at creation';
    END IF;
    IF r.console_type IS DISTINCT FROM NEW.console_type THEN
        RAISE EXCEPTION 'booking console snapshot must match the Resource console at creation';
    END IF;
    IF r.name IS DISTINCT FROM NEW.resource_name_snapshot THEN
        RAISE EXCEPTION 'booking resource_name_snapshot must match the Resource name at creation';
    END IF;

    IF NEW.operating_session_id IS NOT NULL THEN
        SELECT * INTO os FROM venue.operating_session WHERE id = NEW.operating_session_id;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'booking operating_session_id does not exist';
        END IF;
        IF os.venue_id <> NEW.venue_id THEN
            RAISE EXCEPTION 'booking Operating Session must belong to the Booking venue';
        END IF;
        IF NOT (os.session_period @> tstzrange(NEW.start_at, NEW.end_at, '[)')) THEN
            RAISE EXCEPTION 'booking interval must fit fully inside the snapshotted Operating Session';
        END IF;
        IF NEW.operating_day IS DISTINCT FROM os.operating_day
           OR NEW.session_local_start IS DISTINCT FROM os.local_start
           OR NEW.session_local_end IS DISTINCT FROM os.local_end
           OR NEW.session_timezone IS DISTINCT FROM os.timezone THEN
            RAISE EXCEPTION 'booking Operating Session snapshot does not match the authoritative session at creation';
        END IF;
        IF NEW.business_date IS DISTINCT FROM os.operating_day THEN
            RAISE EXCEPTION 'booking business_date must equal operating_day when an Operating Session is snapshotted';
        END IF;
    ELSE
        IF NEW.source <> 'MANUAL' THEN
            RAISE EXCEPTION 'Online Booking requires an Operating Session snapshot';
        END IF;
        IF NEW.operating_day IS NOT NULL
           OR NEW.session_local_start IS NOT NULL
           OR NEW.session_local_end IS NOT NULL THEN
            RAISE EXCEPTION 'out-of-hours Manual Booking must not fabricate Operating Session fields';
        END IF;
        IF NEW.session_timezone IS DISTINCT FROM 'Africa/Cairo' THEN
            RAISE EXCEPTION 'out-of-hours Manual Booking must snapshot Africa/Cairo timezone';
        END IF;
        IF NEW.business_date IS DISTINCT FROM (NEW.start_at AT TIME ZONE 'Africa/Cairo')::date THEN
            RAISE EXCEPTION 'out-of-hours Manual Booking business_date must be the local start date';
        END IF;
        IF EXISTS (
            SELECT 1
            FROM venue.operating_session s
            WHERE s.venue_id = NEW.venue_id
              AND s.session_period @> tstzrange(NEW.start_at, NEW.end_at, '[)')
        ) THEN
            RAISE EXCEPTION 'Manual Booking inside a published Operating Session must store the normal session snapshot';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_20_booking_snapshot_integrity
BEFORE INSERT ON booking.booking
FOR EACH ROW EXECUTE FUNCTION booking.validate_booking_insert_snapshot();

-- -----------------------------------------------------------------------------
-- B2. Historical Booking snapshots are immutable after insert.
-- Lifecycle fields (status/timers/terminal outcome/fee treatment/version) remain mutable
-- only through the semantic application commands and their atomic transactions.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION booking.guard_booking_historical_snapshot_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.venue_id IS DISTINCT FROM OLD.venue_id
       OR NEW.resource_id IS DISTINCT FROM OLD.resource_id
       OR NEW.customer_id IS DISTINCT FROM OLD.customer_id
       OR NEW.source IS DISTINCT FROM OLD.source
       OR NEW.activity IS DISTINCT FROM OLD.activity
       OR NEW.console_type IS DISTINCT FROM OLD.console_type
       OR NEW.play_mode IS DISTINCT FROM OLD.play_mode
       OR NEW.resource_name_snapshot IS DISTINCT FROM OLD.resource_name_snapshot
       OR NEW.start_at IS DISTINCT FROM OLD.start_at
       OR NEW.end_at IS DISTINCT FROM OLD.end_at
       OR NEW.nominal_booked_minutes IS DISTINCT FROM OLD.nominal_booked_minutes
       OR NEW.hourly_price_snapshot IS DISTINCT FROM OLD.hourly_price_snapshot
       OR NEW.venue_price_total IS DISTINCT FROM OLD.venue_price_total
       OR NEW.booking_fee_snapshot IS DISTINCT FROM OLD.booking_fee_snapshot
       OR NEW.total_amount IS DISTINCT FROM OLD.total_amount
       OR NEW.business_date IS DISTINCT FROM OLD.business_date
       OR NEW.operating_day IS DISTINCT FROM OLD.operating_day
       OR NEW.operating_session_id IS DISTINCT FROM OLD.operating_session_id
       OR NEW.session_local_start IS DISTINCT FROM OLD.session_local_start
       OR NEW.session_local_end IS DISTINCT FROM OLD.session_local_end
       OR NEW.session_timezone IS DISTINCT FROM OLD.session_timezone
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION 'Booking identity/timing/pricing/session snapshots are immutable after creation';
    END IF;

    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_10_booking_historical_snapshot_immutable
BEFORE UPDATE ON booking.booking
FOR EACH ROW EXECUTE FUNCTION booking.guard_booking_historical_snapshot_mutation();

-- -----------------------------------------------------------------------------
-- B3. Late Confirmation row lifecycle.
-- Identity/hold ownership is immutable; response and warning facts are one-way writes.
-- expires_at may only move later while the attempt is still open, because emergency
-- pause/resume preserves remaining duration and schedules a fresh deadline.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION booking.guard_late_confirmation_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.booking_id IS DISTINCT FROM OLD.booking_id
       OR NEW.attempt_no IS DISTINCT FROM OLD.attempt_no
       OR NEW.initiated_at IS DISTINCT FROM OLD.initiated_at
       OR NEW.hold_reservation_id IS DISTINCT FROM OLD.hold_reservation_id THEN
        RAISE EXCEPTION 'Late Confirmation identity and hold ownership are immutable';
    END IF;

    IF OLD.customer_response IS NOT NULL
       AND (NEW.customer_response IS DISTINCT FROM OLD.customer_response
            OR NEW.responded_at IS DISTINCT FROM OLD.responded_at
            OR NEW.expires_at IS DISTINCT FROM OLD.expires_at) THEN
        RAISE EXCEPTION 'resolved Late Confirmation response/deadline is immutable';
    END IF;

    IF OLD.warning_sent_at IS NOT NULL AND NEW.warning_sent_at IS DISTINCT FROM OLD.warning_sent_at THEN
        RAISE EXCEPTION 'Late Confirmation warning_sent_at is immutable once recorded';
    END IF;

    IF OLD.customer_response IS NULL AND NEW.customer_response IS NULL
       AND NEW.expires_at < OLD.expires_at THEN
        RAISE EXCEPTION 'open Late Confirmation deadline may not move earlier';
    END IF;

    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_late_confirmation_immutable_lifecycle
BEFORE UPDATE ON booking.late_confirmation
FOR EACH ROW EXECUTE FUNCTION booking.guard_late_confirmation_mutation();

-- -----------------------------------------------------------------------------
-- B4. Deferred Late Confirmation <-> Booking <-> Inventory final-state invariant.
-- This is deferred so the application can update Booking, release/create reservations and
-- resolve the Late Confirmation in any statement order inside one transaction.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION booking.assert_late_confirmation_integrity()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    b booking.booking%ROWTYPE;
    h inventory.resource_reservation%ROWTYPE;
BEGIN
    SELECT * INTO b FROM booking.booking WHERE id = NEW.booking_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Late Confirmation Booking does not exist';
    END IF;
    IF b.source <> 'ONLINE' OR b.customer_id IS NULL THEN
        RAISE EXCEPTION 'Late Confirmation is valid only for an Online customer Booking';
    END IF;

    SELECT * INTO h FROM inventory.resource_reservation WHERE id = NEW.hold_reservation_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Late Confirmation hold reservation does not exist';
    END IF;
    IF h.reservation_type <> 'LATE_CONFIRM_HOLD'
       OR h.booking_id IS DISTINCT FROM NEW.booking_id
       OR h.resource_id IS DISTINCT FROM b.resource_id
       OR h.planned_start IS DISTINCT FROM b.start_at
       OR h.planned_end IS DISTINCT FROM b.end_at THEN
        RAISE EXCEPTION 'Late Confirmation must own a matching LATE_CONFIRM_HOLD for the same Booking/Resource/interval';
    END IF;

    IF NEW.expires_at > b.start_at THEN
        RAISE EXCEPTION 'Late Confirmation deadline may never exceed the original Booking startAt';
    END IF;

    IF NEW.customer_response IS NULL THEN
        IF b.status <> 'AWAITING_CUSTOMER_CONFIRMATION' OR NOT h.active_flag THEN
            RAISE EXCEPTION 'open Late Confirmation requires AWAITING_CUSTOMER_CONFIRMATION and an active hold';
        END IF;
    ELSIF NEW.customer_response = 'ACCEPTED' THEN
        IF b.status <> 'CONFIRMED' OR h.active_flag THEN
            RAISE EXCEPTION 'accepted Late Confirmation requires CONFIRMED Booking and released temporary hold';
        END IF;
        IF NOT EXISTS (
            SELECT 1
            FROM inventory.resource_reservation r
            WHERE r.booking_id = b.id
              AND r.resource_id = b.resource_id
              AND r.reservation_type = 'BOOKING'
              AND r.active_flag = true
              AND r.planned_start = b.start_at
              AND r.planned_end = b.end_at
        ) THEN
            RAISE EXCEPTION 'accepted Late Confirmation requires an active canonical BOOKING reservation';
        END IF;
    ELSIF NEW.customer_response = 'DECLINED' THEN
        IF b.status <> 'CANCELLED'
           OR b.terminal_reason <> 'CUSTOMER_DECLINED_LATE_CONFIRM'
           OR h.active_flag THEN
            RAISE EXCEPTION 'declined Late Confirmation requires matching CANCELLED outcome and released hold';
        END IF;
    ELSIF NEW.customer_response = 'TIMED_OUT' THEN
        IF b.status <> 'CANCELLED'
           OR b.terminal_reason <> 'CUSTOMER_RECONFIRM_TIMEOUT'
           OR h.active_flag THEN
            RAISE EXCEPTION 'timed-out Late Confirmation requires matching CANCELLED outcome and released hold';
        END IF;
    END IF;

    RETURN NULL;
END;
$function$;

CREATE CONSTRAINT TRIGGER tr_late_confirmation_integrity
AFTER INSERT OR UPDATE
ON booking.late_confirmation
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION booking.assert_late_confirmation_integrity();

-- -----------------------------------------------------------------------------
-- B5. Booking transactional delivery contract (application + DB boundary).
-- The database model deliberately does not invent a generic status setter or a giant
-- actor-aware CHECK. Production services MUST implement these Architecture v1.2 contracts:
--   * semantic commands only (Create/Accept/Reject/Expire/InitiateLateConfirm/...)
--   * counted Online commitment strengthening under iam.user_commitment_guard with max-4 re-count
--   * deterministic terminal-reason priority through one domain call path
--   * one transaction for Booking + reservation/hold + history + durable scheduled job + outbox
--   * boundary rule: now < deadline may act; now >= deadline is owned by expiry
-- These are launch requirements, not deferred work.
-- -----------------------------------------------------------------------------


-- v1.1.8 Booking acceptance fixes. These guards are load-bearing and MUST be carried into Flyway/production DDL.
-- They close the v1.1.7 acceptance-review findings without inventing Product-visible states, reasons or permissions.

-- -----------------------------------------------------------------------------
-- A1. Frozen Booking Fee reason -> treatment map.
-- Product v5.0/PRD v1.1 define 22 closed Booking Reason Codes and three treatments.
-- COMPLETED and NO_SHOW have no Booking Reason Code and are therefore outside this reason map.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION booking.expected_fee_treatment(p_terminal_reason text)
RETURNS text
LANGUAGE sql
IMMUTABLE
STRICT
AS $function$
SELECT CASE
    WHEN p_terminal_reason IN ('CUSTOMER_CANCELLED','USER_BANNED') THEN 'CUSTOMER_POLICY'
    WHEN p_terminal_reason = 'VENUE_CANCELLED_MANUAL_BOOKING' THEN 'NOT_APPLICABLE'
    WHEN p_terminal_reason IN (
        'CUSTOMER_DECLINED_LATE_CONFIRM',
        'CUSTOMER_RECONFIRM_TIMEOUT',
        'VENUE_REJECTED',
        'REJECTED_AFTER_EXPIRY',
        'VENUE_CANCELLED_CONFIRMED_BOOKING',
        'VENUE_DID_NOT_RESPOND_IN_TIME',
        'VENUE_OPENING_HOURS_CHANGED',
        'VENUE_CLOSURE',
        'VENUE_EMERGENCY_CLOSURE',
        'RESOURCE_EMERGENCY_OUTAGE',
        'VENUE_RESPONSE_INTERRUPTED_BY_EMERGENCY',
        'RESOURCE_RESPONSE_INTERRUPTED_BY_EMERGENCY',
        'LATE_CONFIRM_INTERRUPTED_BY_EMERGENCY',
        'RESOURCE_OWNER_REVIEW_REQUIRED',
        'VENUE_ACCOUNT_DISABLED',
        'SYSTEM_RESOURCE_STATE_INTEGRITY_ERROR',
        'ADMIN_CANCELLED',
        'ADMIN_CORRECTION',
        'ADMIN_NO_SHOW_REVERSAL'
    ) THEN 'FULL_REFUND'
    ELSE NULL
END;
$function$;

CREATE OR REPLACE FUNCTION booking.validate_booking_fee_treatment()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_expected text;
BEGIN
    IF NEW.source = 'MANUAL' AND NEW.booking_fee_snapshot <> 0 THEN
        RAISE EXCEPTION 'Manual Booking booking_fee_snapshot must be zero';
    END IF;

    IF NEW.status IN ('REJECTED','CANCELLED') THEN
        v_expected := booking.expected_fee_treatment(NEW.terminal_reason);
        IF v_expected IS NULL THEN
            RAISE EXCEPTION 'terminal Booking reason % has no frozen fee-treatment mapping', NEW.terminal_reason;
        END IF;
        IF NEW.fee_treatment IS DISTINCT FROM v_expected THEN
            RAISE EXCEPTION 'Booking fee_treatment % does not match expected % for terminal reason %', NEW.fee_treatment, v_expected, NEW.terminal_reason;
        END IF;
    ELSIF NEW.fee_treatment IS NOT NULL THEN
        RAISE EXCEPTION 'fee_treatment is only stored for REJECTED/CANCELLED reason-coded outcomes';
    END IF;

    RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS tr_booking_fee_treatment_integrity ON booking.booking;
CREATE TRIGGER tr_booking_fee_treatment_integrity
BEFORE INSERT OR UPDATE ON booking.booking
FOR EACH ROW EXECUTE FUNCTION booking.validate_booking_fee_treatment();

-- -----------------------------------------------------------------------------
-- A2. Late Confirmation lifecycle mutation guard.
-- closed_at is implementation-only: Customer response and attempt closure are distinct facts.
-- Open attempts may extend expires_at only because emergency pause/resume preserves remaining duration.
-- Closing an attempt cannot rewrite its deadline or warning history in the same statement.
-- -----------------------------------------------------------------------------
DROP TRIGGER IF EXISTS tr_late_confirmation_immutable_lifecycle ON booking.late_confirmation;

CREATE OR REPLACE FUNCTION booking.guard_late_confirmation_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.booking_id IS DISTINCT FROM OLD.booking_id
       OR NEW.attempt_no IS DISTINCT FROM OLD.attempt_no
       OR NEW.initiated_at IS DISTINCT FROM OLD.initiated_at
       OR NEW.hold_reservation_id IS DISTINCT FROM OLD.hold_reservation_id THEN
        RAISE EXCEPTION 'Late Confirmation identity and hold ownership are immutable';
    END IF;

    IF OLD.closed_at IS NOT NULL THEN
        IF NEW.expires_at IS DISTINCT FROM OLD.expires_at
           OR NEW.warning_sent_at IS DISTINCT FROM OLD.warning_sent_at
           OR NEW.customer_response IS DISTINCT FROM OLD.customer_response
           OR NEW.responded_at IS DISTINCT FROM OLD.responded_at
           OR NEW.closed_at IS DISTINCT FROM OLD.closed_at THEN
            RAISE EXCEPTION 'closed Late Confirmation lifecycle facts are immutable';
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.warning_sent_at IS NOT NULL AND NEW.warning_sent_at IS DISTINCT FROM OLD.warning_sent_at THEN
        RAISE EXCEPTION 'Late Confirmation warning_sent_at is immutable once recorded';
    END IF;

    IF NEW.closed_at IS NULL THEN
        IF NEW.customer_response IS NOT NULL OR NEW.responded_at IS NOT NULL THEN
            RAISE EXCEPTION 'Customer response closes the Late Confirmation attempt in the same write';
        END IF;
        IF NEW.expires_at < OLD.expires_at THEN
            RAISE EXCEPTION 'open Late Confirmation deadline may not move earlier';
        END IF;
    ELSE
        IF NEW.expires_at IS DISTINCT FROM OLD.expires_at
           OR NEW.warning_sent_at IS DISTINCT FROM OLD.warning_sent_at THEN
            RAISE EXCEPTION 'closing Late Confirmation may not rewrite deadline or warning history';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_late_confirmation_immutable_lifecycle
BEFORE UPDATE ON booking.late_confirmation
FOR EACH ROW EXECUTE FUNCTION booking.guard_late_confirmation_mutation();

-- -----------------------------------------------------------------------------
-- A3. Reusable final-state assertion for one Late Confirmation attempt.
-- This assertion is called from Late Confirmation, Booking and Inventory mutation surfaces.
-- It therefore cannot be bypassed by changing only booking.status or reservation.active_flag.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION booking.assert_late_confirmation_row(p_late_confirmation_id uuid)
RETURNS void
LANGUAGE plpgsql
AS $function$
DECLARE
    lc booking.late_confirmation%ROWTYPE;
    b booking.booking%ROWTYPE;
    h inventory.resource_reservation%ROWTYPE;
    v_booking_reservation_exists boolean;
    v_booking_reservation_active boolean;
BEGIN
    SELECT * INTO lc FROM booking.late_confirmation WHERE id = p_late_confirmation_id;
    IF NOT FOUND THEN
        RETURN;
    END IF;

    SELECT * INTO b FROM booking.booking WHERE id = lc.booking_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Late Confirmation Booking does not exist';
    END IF;
    IF b.source <> 'ONLINE' OR b.customer_id IS NULL THEN
        RAISE EXCEPTION 'Late Confirmation is valid only for an Online customer Booking';
    END IF;

    SELECT * INTO h FROM inventory.resource_reservation WHERE id = lc.hold_reservation_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Late Confirmation hold reservation does not exist';
    END IF;
    IF h.reservation_type <> 'LATE_CONFIRM_HOLD'
       OR h.booking_id IS DISTINCT FROM lc.booking_id
       OR h.resource_id IS DISTINCT FROM b.resource_id
       OR h.planned_start IS DISTINCT FROM b.start_at
       OR h.planned_end IS DISTINCT FROM b.end_at THEN
        RAISE EXCEPTION 'Late Confirmation must own a matching LATE_CONFIRM_HOLD for the same Booking/Resource/interval';
    END IF;

    IF lc.expires_at > b.start_at THEN
        RAISE EXCEPTION 'Late Confirmation deadline may never exceed the original Booking startAt';
    END IF;

    SELECT EXISTS (
        SELECT 1
          FROM inventory.resource_reservation r
         WHERE r.booking_id = b.id
           AND r.resource_id = b.resource_id
           AND r.reservation_type = 'BOOKING'
           AND r.planned_start = b.start_at
           AND r.planned_end = b.end_at
    ), EXISTS (
        SELECT 1
          FROM inventory.resource_reservation r
         WHERE r.booking_id = b.id
           AND r.resource_id = b.resource_id
           AND r.reservation_type = 'BOOKING'
           AND r.active_flag = true
           AND r.planned_start = b.start_at
           AND r.planned_end = b.end_at
    )
      INTO v_booking_reservation_exists, v_booking_reservation_active;

    IF lc.closed_at IS NULL THEN
        IF lc.customer_response IS NOT NULL OR lc.responded_at IS NOT NULL THEN
            RAISE EXCEPTION 'open Late Confirmation cannot already contain a Customer response';
        END IF;
        IF b.status <> 'AWAITING_CUSTOMER_CONFIRMATION' OR NOT h.active_flag THEN
            RAISE EXCEPTION 'open Late Confirmation requires AWAITING_CUSTOMER_CONFIRMATION and an active hold';
        END IF;
        RETURN;
    END IF;

    IF h.active_flag THEN
        RAISE EXCEPTION 'closed Late Confirmation requires its temporary hold to be released';
    END IF;

    IF lc.customer_response = 'ACCEPTED' THEN
        IF b.status NOT IN ('CONFIRMED','ACTIVE','COMPLETED','CANCELLED','NO_SHOW') THEN
            RAISE EXCEPTION 'accepted Late Confirmation has an invalid current Booking state %', b.status;
        END IF;
        IF NOT v_booking_reservation_exists THEN
            RAISE EXCEPTION 'accepted Late Confirmation requires a historical canonical BOOKING reservation';
        END IF;
        IF b.status IN ('CONFIRMED','ACTIVE') AND NOT v_booking_reservation_active THEN
            RAISE EXCEPTION 'accepted Late Confirmation with a live Booking requires an active canonical BOOKING reservation';
        END IF;
    ELSIF lc.customer_response = 'DECLINED' THEN
        IF b.status <> 'CANCELLED' OR b.terminal_reason <> 'CUSTOMER_DECLINED_LATE_CONFIRM' THEN
            RAISE EXCEPTION 'declined Late Confirmation requires matching CANCELLED outcome';
        END IF;
    ELSIF lc.customer_response = 'TIMED_OUT' THEN
        IF b.status <> 'CANCELLED' OR b.terminal_reason <> 'CUSTOMER_RECONFIRM_TIMEOUT' THEN
            RAISE EXCEPTION 'timed-out Late Confirmation requires matching CANCELLED outcome';
        END IF;
    ELSE
        IF b.status <> 'CANCELLED'
           OR b.terminal_reason NOT IN (
                'VENUE_ACCOUNT_DISABLED',
                'USER_BANNED',
                'VENUE_OPENING_HOURS_CHANGED',
                'VENUE_CLOSURE',
                'VENUE_EMERGENCY_CLOSURE',
                'RESOURCE_EMERGENCY_OUTAGE',
                'RESOURCE_OWNER_REVIEW_REQUIRED',
                'LATE_CONFIRM_INTERRUPTED_BY_EMERGENCY',
                'ADMIN_CANCELLED',
                'ADMIN_CORRECTION'
           ) THEN
            RAISE EXCEPTION 'Late Confirmation closed without Customer response requires a Product-defined AWAITING cancellation outcome';
        END IF;
    END IF;
END;
$function$;

-- -----------------------------------------------------------------------------
-- A4. Late Confirmation trigger surface.
-- Initial insert must use exactly MIN(initiated_at + 5 minutes, booking.start_at).
-- The final assertion is deferred so Booking/Hold/history writes may occur in any statement order in one transaction.
-- -----------------------------------------------------------------------------
DROP TRIGGER IF EXISTS tr_late_confirmation_integrity ON booking.late_confirmation;

CREATE OR REPLACE FUNCTION booking.assert_late_confirmation_integrity()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_start_at timestamptz;
BEGIN
    IF TG_OP = 'INSERT' THEN
        SELECT start_at INTO v_start_at FROM booking.booking WHERE id = NEW.booking_id;
        IF v_start_at IS NULL THEN
            RAISE EXCEPTION 'Late Confirmation Booking does not exist';
        END IF;
        IF NEW.expires_at IS DISTINCT FROM LEAST(NEW.initiated_at + interval '5 minutes', v_start_at) THEN
            RAISE EXCEPTION 'initial Late Confirmation expiry must equal MIN(initiated_at + 5 minutes, booking.start_at)';
        END IF;
    END IF;

    PERFORM booking.assert_late_confirmation_row(NEW.id);
    RETURN NULL;
END;
$function$;

CREATE CONSTRAINT TRIGGER tr_late_confirmation_integrity
AFTER INSERT OR UPDATE
ON booking.late_confirmation
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION booking.assert_late_confirmation_integrity();

-- -----------------------------------------------------------------------------
-- A5. Booking mutation surface: changing Booking state alone must not bypass Late Confirmation invariants.
-- -----------------------------------------------------------------------------
DROP TRIGGER IF EXISTS tr_lc_integrity_from_booking ON booking.booking;

CREATE OR REPLACE FUNCTION booking.assert_late_confirmation_from_booking()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_lc_id uuid;
BEGIN
    FOR v_lc_id IN
        SELECT id FROM booking.late_confirmation WHERE booking_id = NEW.id
    LOOP
        PERFORM booking.assert_late_confirmation_row(v_lc_id);
    END LOOP;
    RETURN NULL;
END;
$function$;

CREATE CONSTRAINT TRIGGER tr_lc_integrity_from_booking
AFTER INSERT OR UPDATE
ON booking.booking
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION booking.assert_late_confirmation_from_booking();

-- -----------------------------------------------------------------------------
-- A6. Inventory mutation surface: Hold or canonical BOOKING reservation changes must not bypass the same invariant.
-- -----------------------------------------------------------------------------
DROP TRIGGER IF EXISTS tr_lc_integrity_from_reservation ON inventory.resource_reservation;

CREATE OR REPLACE FUNCTION booking.assert_late_confirmation_from_reservation()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_reservation_id uuid;
    v_booking_id uuid;
    v_lc_id uuid;
BEGIN
    IF TG_OP = 'DELETE' THEN
        v_reservation_id := OLD.id;
        v_booking_id := OLD.booking_id;
    ELSE
        v_reservation_id := NEW.id;
        v_booking_id := NEW.booking_id;
    END IF;

    FOR v_lc_id IN
        SELECT lc.id
          FROM booking.late_confirmation lc
         WHERE lc.hold_reservation_id = v_reservation_id
            OR (v_booking_id IS NOT NULL AND lc.booking_id = v_booking_id)
    LOOP
        PERFORM booking.assert_late_confirmation_row(v_lc_id);
    END LOOP;
    RETURN NULL;
END;
$function$;

CREATE CONSTRAINT TRIGGER tr_lc_integrity_from_reservation
AFTER INSERT OR UPDATE OR DELETE
ON inventory.resource_reservation
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION booking.assert_late_confirmation_from_reservation();

-- -----------------------------------------------------------------------------
-- A7. Booking transactional delivery contract remains unchanged and mandatory.
-- Every counted Online-commitment strengthening path locks iam.user_commitment_guard,
-- re-counts max-4, revalidates overlap, uses semantic commands, resolves the deterministic
-- terminal reason through one domain path, and commits Booking/reservation/history/job/outbox atomically.
-- -----------------------------------------------------------------------------


-- ============================================================================
-- E7GZ PS v1.1.9 ATTENDANCE HARDENING GUARDS
-- PostgreSQL 15+
-- ============================================================================

-- A1. Attendance row lifecycle: evidence/reversal facts are one-way; result is
-- unresolved (NULL) until resolution and may later change only through an audited
-- Admin Attendance Correction. The historical protection flag never silently clears.
CREATE OR REPLACE FUNCTION attendance.guard_attendance_record_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_original_added boolean;
BEGIN
    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.booking_id IS DISTINCT FROM OLD.booking_id THEN
        RAISE EXCEPTION 'Attendance record identity/Booking ownership is immutable';
    END IF;

    IF OLD.check_in_at IS NOT NULL AND NEW.check_in_at IS DISTINCT FROM OLD.check_in_at THEN
        RAISE EXCEPTION 'check_in_at is immutable once recorded';
    END IF;
    IF OLD.late_present_at IS NOT NULL AND NEW.late_present_at IS DISTINCT FROM OLD.late_present_at THEN
        RAISE EXCEPTION 'late_present_at is immutable once recorded';
    END IF;
    IF OLD.no_show_at IS NOT NULL AND NEW.no_show_at IS DISTINCT FROM OLD.no_show_at THEN
        RAISE EXCEPTION 'no_show_at is immutable once recorded';
    END IF;

    IF OLD.check_in_reversed_at IS NOT NULL AND NEW.check_in_reversed_at IS DISTINCT FROM OLD.check_in_reversed_at THEN
        RAISE EXCEPTION 'check_in_reversed_at is immutable once recorded';
    END IF;
    IF OLD.late_present_reversed_at IS NOT NULL AND NEW.late_present_reversed_at IS DISTINCT FROM OLD.late_present_reversed_at THEN
        RAISE EXCEPTION 'late_present_reversed_at is immutable once recorded';
    END IF;
    IF OLD.no_show_reversed_at IS NOT NULL AND NEW.no_show_reversed_at IS DISTINCT FROM OLD.no_show_reversed_at THEN
        RAISE EXCEPTION 'no_show_reversed_at is immutable once recorded';
    END IF;

    v_original_added :=
        (OLD.check_in_at IS NULL AND NEW.check_in_at IS NOT NULL)
        OR (OLD.late_present_at IS NULL AND NEW.late_present_at IS NOT NULL)
        OR (OLD.no_show_at IS NULL AND NEW.no_show_at IS NOT NULL);

    IF NEW.recorded_by_venue_account_id IS DISTINCT FROM OLD.recorded_by_venue_account_id
       AND NOT v_original_added THEN
        RAISE EXCEPTION 'recorded_by_venue_account_id may change only with a new original Venue attendance action';
    END IF;

    IF OLD.result IS NULL THEN
        IF NEW.result IS NULL THEN
            IF NEW.resolved_at IS NOT NULL THEN
                RAISE EXCEPTION 'unresolved Attendance cannot have resolved_at';
            END IF;
        ELSE
            IF NEW.resolved_at IS NULL THEN
                RAISE EXCEPTION 'resolving Attendance requires resolved_at';
            END IF;
        END IF;
    ELSE
        IF NEW.result IS NULL THEN
            RAISE EXCEPTION 'resolved Attendance Result cannot return to NULL';
        END IF;
        IF NEW.result IS DISTINCT FROM OLD.result THEN
            IF NEW.resolved_at IS NULL OR OLD.resolved_at IS NULL OR NEW.resolved_at <= OLD.resolved_at THEN
                RAISE EXCEPTION 'Admin Attendance Correction must move resolved_at forward';
            END IF;
        ELSIF NEW.resolved_at IS DISTINCT FROM OLD.resolved_at THEN
            RAISE EXCEPTION 'resolved_at may change only with an Attendance Result correction';
        END IF;
    END IF;

    IF OLD.protection_applied AND NOT NEW.protection_applied THEN
        RAISE EXCEPTION 'historical protection_applied may not be cleared';
    END IF;

    RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS tr_attendance_record_mutation_guard ON attendance.attendance_record;
CREATE TRIGGER tr_attendance_record_mutation_guard
BEFORE UPDATE ON attendance.attendance_record
FOR EACH ROW EXECUTE FUNCTION attendance.guard_attendance_record_mutation();

CREATE OR REPLACE FUNCTION attendance.reject_attendance_record_delete()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    RAISE EXCEPTION 'attendance_record is historical state/evidence and may not be deleted';
END;
$function$;

DROP TRIGGER IF EXISTS tr_attendance_record_reject_delete ON attendance.attendance_record;
CREATE TRIGGER tr_attendance_record_reject_delete
BEFORE DELETE ON attendance.attendance_record
FOR EACH ROW EXECUTE FUNCTION attendance.reject_attendance_record_delete();

-- A2. Product windows + same-Venue Venue actor + Account-disable access restriction.
CREATE OR REPLACE FUNCTION attendance.validate_attendance_action_write()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    b booking.booking%ROWTYPE;
    v_check_added boolean;
    v_late_added boolean;
    v_no_show_added boolean;
    v_action_at timestamptz;
    v_actor_venue uuid;
BEGIN
    SELECT * INTO b FROM booking.booking WHERE id = NEW.booking_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Attendance Booking does not exist';
    END IF;

    IF TG_OP = 'INSERT' THEN
        v_check_added := NEW.check_in_at IS NOT NULL;
        v_late_added := NEW.late_present_at IS NOT NULL;
        v_no_show_added := NEW.no_show_at IS NOT NULL;
    ELSE
        v_check_added := NEW.check_in_at IS NOT NULL AND OLD.check_in_at IS NULL;
        v_late_added := NEW.late_present_at IS NOT NULL AND OLD.late_present_at IS NULL;
        v_no_show_added := NEW.no_show_at IS NOT NULL AND OLD.no_show_at IS NULL;
    END IF;

    IF b.source = 'MANUAL' THEN
        IF NEW.check_in_at IS NOT NULL OR NEW.late_present_at IS NOT NULL OR NEW.no_show_at IS NOT NULL THEN
            RAISE EXCEPTION 'Manual Booking does not use Product Attendance evidence';
        END IF;
        IF NEW.result IS NOT NULL AND NEW.result <> 'NOT_APPLICABLE' THEN
            RAISE EXCEPTION 'Manual Booking Attendance Result must be NOT_APPLICABLE';
        END IF;
    END IF;

    IF v_check_added OR v_late_added OR v_no_show_added THEN
        IF b.source <> 'ONLINE' OR b.customer_id IS NULL THEN
            RAISE EXCEPTION 'Venue attendance actions require an Online customer Booking';
        END IF;
        IF NEW.recorded_by_venue_account_id IS NULL THEN
            RAISE EXCEPTION 'Venue attendance action requires recorded_by_venue_account_id';
        END IF;
        SELECT venue_id INTO v_actor_venue
          FROM iam.venue_account
         WHERE id = NEW.recorded_by_venue_account_id;
        IF NOT FOUND OR v_actor_venue IS DISTINCT FROM b.venue_id THEN
            RAISE EXCEPTION 'Attendance Venue Account must belong to the Booking Venue';
        END IF;
    END IF;

    IF v_check_added THEN
        v_action_at := NEW.check_in_at;
        IF NOT (v_action_at >= b.start_at AND v_action_at < b.start_at + interval '15 minutes') THEN
            RAISE EXCEPTION 'Check-in must be within [startAt, startAt + 15 minutes)';
        END IF;
        IF EXISTS (
            SELECT 1 FROM iam.venue_account_restriction_interval r
             WHERE r.venue_id = b.venue_id
               AND r.disabled_at <= v_action_at
               AND (r.reenabled_at IS NULL OR v_action_at < r.reenabled_at)
        ) THEN
            RAISE EXCEPTION 'Check-in may not be recorded during a Venue Account disable interval';
        END IF;
    END IF;

    IF v_late_added THEN
        v_action_at := NEW.late_present_at;
        IF NOT (v_action_at >= b.start_at + interval '15 minutes' AND v_action_at < b.end_at) THEN
            RAISE EXCEPTION 'Late Present must be within [startAt + 15 minutes, endAt)';
        END IF;
        IF EXISTS (
            SELECT 1 FROM iam.venue_account_restriction_interval r
             WHERE r.venue_id = b.venue_id
               AND r.disabled_at <= v_action_at
               AND (r.reenabled_at IS NULL OR v_action_at < r.reenabled_at)
        ) THEN
            RAISE EXCEPTION 'Late Present may not be recorded during a Venue Account disable interval';
        END IF;
    END IF;

    IF v_no_show_added THEN
        v_action_at := NEW.no_show_at;
        IF NOT (v_action_at >= b.start_at + interval '15 minutes' AND v_action_at < b.end_at) THEN
            RAISE EXCEPTION 'No-show must be within [startAt + 15 minutes, endAt)';
        END IF;
        IF EXISTS (
            SELECT 1 FROM iam.venue_account_restriction_interval r
             WHERE r.venue_id = b.venue_id
               AND r.disabled_at <= v_action_at
               AND (r.reenabled_at IS NULL OR v_action_at < r.reenabled_at)
        ) THEN
            RAISE EXCEPTION 'No-show may not be recorded during a Venue Account disable interval';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS tr_attendance_action_write_guard ON attendance.attendance_record;
CREATE TRIGGER tr_attendance_action_write_guard
BEFORE INSERT OR UPDATE ON attendance.attendance_record
FOR EACH ROW EXECUTE FUNCTION attendance.validate_attendance_action_write();

-- A3. Per-action history/audit gate. Reversals are Platform Admin only and need a
-- mandatory reason; normal evidence is Venue-authored and audited.
CREATE OR REPLACE FUNCTION attendance.assert_attendance_action_audit()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    cur attendance.attendance_record%ROWTYPE;
    b booking.booking%ROWTYPE;
    v_event text;
    v_at timestamptz;
    v_is_admin boolean;
    v_check_added boolean;
    v_late_added boolean;
    v_no_show_added boolean;
    v_check_reversed_added boolean;
    v_late_reversed_added boolean;
    v_no_show_reversed_added boolean;
BEGIN
    SELECT * INTO cur FROM attendance.attendance_record WHERE id = NEW.id;
    IF NOT FOUND THEN RETURN NULL; END IF;
    SELECT * INTO b FROM booking.booking WHERE id = cur.booking_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Attendance Booking does not exist'; END IF;

    IF TG_OP = 'INSERT' THEN
        v_check_added := NEW.check_in_at IS NOT NULL;
        v_late_added := NEW.late_present_at IS NOT NULL;
        v_no_show_added := NEW.no_show_at IS NOT NULL;
        v_check_reversed_added := NEW.check_in_reversed_at IS NOT NULL;
        v_late_reversed_added := NEW.late_present_reversed_at IS NOT NULL;
        v_no_show_reversed_added := NEW.no_show_reversed_at IS NOT NULL;
    ELSE
        v_check_added := NEW.check_in_at IS NOT NULL AND OLD.check_in_at IS NULL;
        v_late_added := NEW.late_present_at IS NOT NULL AND OLD.late_present_at IS NULL;
        v_no_show_added := NEW.no_show_at IS NOT NULL AND OLD.no_show_at IS NULL;
        v_check_reversed_added := NEW.check_in_reversed_at IS NOT NULL AND OLD.check_in_reversed_at IS NULL;
        v_late_reversed_added := NEW.late_present_reversed_at IS NOT NULL AND OLD.late_present_reversed_at IS NULL;
        v_no_show_reversed_added := NEW.no_show_reversed_at IS NOT NULL AND OLD.no_show_reversed_at IS NULL;
    END IF;

    FOR v_event, v_at, v_is_admin IN
        SELECT 'CHECK_IN_RECORDED', NEW.check_in_at, false
         WHERE v_check_added
        UNION ALL
        SELECT 'LATE_PRESENT_RECORDED', NEW.late_present_at, false
         WHERE v_late_added
        UNION ALL
        SELECT 'NO_SHOW_RECORDED', NEW.no_show_at, false
         WHERE v_no_show_added
        UNION ALL
        SELECT 'CHECK_IN_REVERSED', NEW.check_in_reversed_at, true
         WHERE v_check_reversed_added
        UNION ALL
        SELECT 'LATE_PRESENT_REVERSED', NEW.late_present_reversed_at, true
         WHERE v_late_reversed_added
        UNION ALL
        SELECT 'NO_SHOW_REVERSED', NEW.no_show_reversed_at, true
         WHERE v_no_show_reversed_added
    LOOP
        IF v_is_admin THEN
            IF NOT EXISTS (
                SELECT 1
                  FROM booking.booking_history bh
                  JOIN audit.audit_event ae
                    ON ae.subject_type = 'BOOKING'
                   AND ae.subject_id = cur.booking_id
                   AND ae.action = v_event
                   AND ae.actor_type = 'ADMIN'
                   AND ae.actor_id = bh.actor_id
                   AND ae.occurred_at = v_at
                   AND NULLIF(BTRIM(ae.reason),'') IS NOT NULL
                 WHERE bh.booking_id = cur.booking_id
                   AND bh.entry_kind = 'BOOKING_EVENT'
                   AND bh.event_type = v_event
                   AND bh.actor_type = 'ADMIN'
                   AND bh.actor_id IS NOT NULL
                   AND bh.occurred_at = v_at
            ) THEN
                RAISE EXCEPTION '% requires matching Admin Booking History + Audit reason', v_event;
            END IF;
        ELSE
            IF NOT EXISTS (
                SELECT 1
                  FROM booking.booking_history bh
                  JOIN iam.venue_account va ON va.id = bh.actor_id AND va.venue_id = b.venue_id
                  JOIN audit.audit_event ae
                    ON ae.subject_type = 'BOOKING'
                   AND ae.subject_id = cur.booking_id
                   AND ae.action = v_event
                   AND ae.actor_type = 'VENUE'
                   AND ae.actor_id = bh.actor_id
                   AND ae.occurred_at = v_at
                 WHERE bh.booking_id = cur.booking_id
                   AND bh.entry_kind = 'BOOKING_EVENT'
                   AND bh.event_type = v_event
                   AND bh.actor_type = 'VENUE'
                   AND bh.actor_id IS NOT NULL
                   AND bh.occurred_at = v_at
            ) THEN
                RAISE EXCEPTION '% requires matching Venue Booking History + Audit event', v_event;
            END IF;
        END IF;
    END LOOP;

    IF TG_OP = 'UPDATE' THEN
      IF OLD.result IS NOT NULL AND NEW.result IS DISTINCT FROM OLD.result THEN
        IF NOT EXISTS (
            SELECT 1
              FROM booking.booking_history bh
              JOIN audit.audit_event ae
                ON ae.subject_type = 'BOOKING'
               AND ae.subject_id = cur.booking_id
               AND ae.action = 'ATTENDANCE_CORRECTED'
               AND ae.actor_type = 'ADMIN'
               AND ae.actor_id = bh.actor_id
               AND ae.occurred_at = cur.resolved_at
               AND NULLIF(BTRIM(ae.reason),'') IS NOT NULL
             WHERE bh.booking_id = cur.booking_id
               AND bh.entry_kind = 'BOOKING_EVENT'
               AND bh.event_type = 'ATTENDANCE_CORRECTED'
               AND bh.actor_type = 'ADMIN'
               AND bh.actor_id IS NOT NULL
               AND bh.occurred_at = cur.resolved_at
        ) THEN
            RAISE EXCEPTION 'Attendance Result correction requires matching Admin Booking History + Audit reason';
        END IF;
        IF NOT EXISTS (
            SELECT 1 FROM trust.trust_event te
             WHERE te.booking_id = cur.booking_id
               AND te.event_type = 'ATTENDANCE_CORRECTED'
               AND te.corrected_outcome = cur.result
               AND te.occurred_at = cur.resolved_at
        ) THEN
            RAISE EXCEPTION 'Attendance Result correction requires matching ATTENDANCE_CORRECTED Trust event';
        END IF;
      END IF;
    END IF;

    RETURN NULL;
END;
$function$;

DROP TRIGGER IF EXISTS tr_attendance_action_audit ON attendance.attendance_record;
CREATE CONSTRAINT TRIGGER tr_attendance_action_audit
AFTER INSERT OR UPDATE ON attendance.attendance_record
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION attendance.assert_attendance_action_audit();

-- A4. Canonical final-state assertion for Attendance.
CREATE OR REPLACE FUNCTION attendance.assert_attendance_row(p_attendance_id uuid)
RETURNS void
LANGUAGE plpgsql
AS $function$
DECLARE
    a attendance.attendance_record%ROWTYPE;
    b booking.booking%ROWTYPE;
    v_active_check boolean;
    v_active_late boolean;
    v_active_no_show boolean;
    v_latest_correction text;
    v_protection_count integer;
BEGIN
    SELECT * INTO a FROM attendance.attendance_record WHERE id = p_attendance_id;
    IF NOT FOUND THEN RETURN; END IF;
    SELECT * INTO b FROM booking.booking WHERE id = a.booking_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Attendance Booking does not exist'; END IF;

    v_active_check := a.check_in_at IS NOT NULL AND a.check_in_reversed_at IS NULL;
    v_active_late := a.late_present_at IS NOT NULL AND a.late_present_reversed_at IS NULL;
    v_active_no_show := a.no_show_at IS NOT NULL AND a.no_show_reversed_at IS NULL;

    SELECT te.corrected_outcome INTO v_latest_correction
      FROM trust.trust_event te
     WHERE te.booking_id = a.booking_id
       AND te.event_type = 'ATTENDANCE_CORRECTED'
     ORDER BY te.event_sequence DESC
     LIMIT 1;

    IF a.result IS NOT NULL AND v_latest_correction IS NULL THEN
        IF b.source = 'MANUAL' THEN
            IF a.result <> 'NOT_APPLICABLE' THEN
                RAISE EXCEPTION 'Manual Booking Attendance must resolve to NOT_APPLICABLE';
            END IF;
        ELSIF v_active_no_show OR b.status = 'NO_SHOW' THEN
            IF NOT v_active_no_show OR b.status <> 'NO_SHOW' OR a.result <> 'ABSENT_NO_SHOW' THEN
                RAISE EXCEPTION 'unreversed No-show requires Booking NO_SHOW and ABSENT_NO_SHOW';
            END IF;
        ELSIF b.status = 'COMPLETED' THEN
            IF v_active_check AND a.result <> 'ATTENDED' THEN
                RAISE EXCEPTION 'normal completion with qualifying Check-in requires ATTENDED';
            ELSIF NOT v_active_check AND a.result <> 'ATTENDANCE_UNCONFIRMED' THEN
                RAISE EXCEPTION 'normal completion without qualifying Check-in requires ATTENDANCE_UNCONFIRMED';
            END IF;
        ELSIF b.status = 'CANCELLED'
              AND b.terminal_reason IN ('RESOURCE_EMERGENCY_OUTAGE','VENUE_EMERGENCY_CLOSURE','RESOURCE_OWNER_REVIEW_REQUIRED') THEN
            IF v_active_check AND a.result <> 'ATTENDED_INTERRUPTED' THEN
                RAISE EXCEPTION 'operational interruption after Check-in requires ATTENDED_INTERRUPTED';
            ELSIF v_active_late AND a.result <> 'ATTENDANCE_UNCONFIRMED' THEN
                RAISE EXCEPTION 'operational interruption with Late Present only requires ATTENDANCE_UNCONFIRMED';
            ELSIF NOT v_active_check AND NOT v_active_late AND a.result <> 'NOT_APPLICABLE' THEN
                RAISE EXCEPTION 'operational interruption without attendance evidence requires NOT_APPLICABLE';
            END IF;
        ELSIF b.status IN ('CANCELLED','REJECTED')
              AND a.check_in_at IS NULL AND a.late_present_at IS NULL AND a.no_show_at IS NULL
              AND a.result <> 'NOT_APPLICABLE' THEN
            RAISE EXCEPTION 'cancelled/rejected Booking before any attendance evidence requires NOT_APPLICABLE';
        END IF;
    ELSIF a.result IS NOT NULL AND v_latest_correction IS NOT NULL AND a.result IS DISTINCT FROM v_latest_correction THEN
        RAISE EXCEPTION 'stored Attendance Result must match the latest ATTENDANCE_CORRECTED outcome';
    END IF;

    IF v_active_no_show THEN
        IF NOT EXISTS (
            SELECT 1 FROM booking.booking_history bh
             WHERE bh.booking_id = a.booking_id
               AND bh.entry_kind = 'BOOKING_EVENT'
               AND bh.event_type = 'NO_SHOW_RECORDED'
               AND bh.occurred_at = a.no_show_at
        ) THEN
            RAISE EXCEPTION 'No-show requires NO_SHOW_RECORDED Booking Event';
        END IF;
        IF EXISTS (
            SELECT 1 FROM inventory.resource_reservation rr
             WHERE rr.booking_id = a.booking_id
               AND rr.reservation_type IN ('BOOKING','LATE_CONFIRM_HOLD')
               AND rr.active_flag = true
        ) THEN
            RAISE EXCEPTION 'No-show must release all active Booking/Late-Confirm resource commitments';
        END IF;
    END IF;

    SELECT COUNT(*) INTO v_protection_count
      FROM trust.trust_event te
     WHERE te.booking_id = a.booking_id
       AND te.event_type = 'BOOKING_ACCOUNT_DISABLE_ATTENDANCE_PROTECTION';

    IF a.protection_applied THEN
        IF v_protection_count <> 1 THEN
            RAISE EXCEPTION 'protection_applied requires exactly one protection Trust event';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM attendance.attendance_protection_candidate c WHERE c.booking_id = a.booking_id) THEN
            RAISE EXCEPTION 'protection_applied requires at least one Attendance Protection candidate';
        END IF;
        IF v_latest_correction IS NULL AND a.result NOT IN ('ATTENDANCE_UNCONFIRMED','NOT_APPLICABLE') THEN
            RAISE EXCEPTION 'initial Attendance Protection may apply only to ATTENDANCE_UNCONFIRMED or eligible NOT_APPLICABLE';
        END IF;
    ELSIF v_protection_count <> 0 THEN
        RAISE EXCEPTION 'protection Trust event requires attendance_record.protection_applied = true';
    END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION attendance.assert_attendance_row_trigger()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    PERFORM attendance.assert_attendance_row(NEW.id);
    RETURN NULL;
END;
$function$;

DROP TRIGGER IF EXISTS tr_attendance_final_state ON attendance.attendance_record;
CREATE CONSTRAINT TRIGGER tr_attendance_final_state
AFTER INSERT OR UPDATE ON attendance.attendance_record
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION attendance.assert_attendance_row_trigger();

-- A5. Cross-surface assertions: Booking, Inventory and Trust mutations cannot bypass
-- Attendance/No-show/Protection final-state invariants.
CREATE OR REPLACE FUNCTION attendance.assert_attendance_from_booking()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE v_id uuid;
BEGIN
    SELECT id INTO v_id FROM attendance.attendance_record WHERE booking_id = NEW.id;
    IF FOUND THEN PERFORM attendance.assert_attendance_row(v_id); END IF;
    RETURN NULL;
END;
$function$;

DROP TRIGGER IF EXISTS tr_attendance_integrity_from_booking ON booking.booking;
CREATE CONSTRAINT TRIGGER tr_attendance_integrity_from_booking
AFTER INSERT OR UPDATE ON booking.booking
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION attendance.assert_attendance_from_booking();

CREATE OR REPLACE FUNCTION attendance.assert_attendance_from_reservation()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_booking_id uuid;
    v_id uuid;
BEGIN
    v_booking_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.booking_id ELSE NEW.booking_id END;
    IF v_booking_id IS NULL THEN RETURN NULL; END IF;
    SELECT id INTO v_id FROM attendance.attendance_record WHERE booking_id = v_booking_id;
    IF FOUND THEN PERFORM attendance.assert_attendance_row(v_id); END IF;
    RETURN NULL;
END;
$function$;

DROP TRIGGER IF EXISTS tr_attendance_integrity_from_reservation ON inventory.resource_reservation;
CREATE CONSTRAINT TRIGGER tr_attendance_integrity_from_reservation
AFTER INSERT OR UPDATE OR DELETE ON inventory.resource_reservation
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION attendance.assert_attendance_from_reservation();

CREATE OR REPLACE FUNCTION attendance.assert_attendance_from_trust()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE v_id uuid;
BEGIN
    IF NEW.booking_id IS NULL THEN RETURN NULL; END IF;
    SELECT id INTO v_id FROM attendance.attendance_record WHERE booking_id = NEW.booking_id;
    IF FOUND THEN PERFORM attendance.assert_attendance_row(v_id); END IF;
    RETURN NULL;
END;
$function$;

DROP TRIGGER IF EXISTS tr_attendance_integrity_from_trust ON trust.trust_event;
CREATE CONSTRAINT TRIGGER tr_attendance_integrity_from_trust
AFTER INSERT ON trust.trust_event
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION attendance.assert_attendance_from_trust();

-- A6. Attendance Protection candidates are append-only, same-Venue and tied to an
-- ACTIVE Online Booking plus the specific Account-disable interval.
CREATE OR REPLACE FUNCTION attendance.validate_protection_candidate()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    b booking.booking%ROWTYPE;
    r iam.venue_account_restriction_interval%ROWTYPE;
BEGIN
    SELECT * INTO b FROM booking.booking WHERE id = NEW.booking_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Protection candidate Booking does not exist'; END IF;
    IF b.source <> 'ONLINE' OR b.customer_id IS NULL OR b.status <> 'ACTIVE' THEN
        RAISE EXCEPTION 'Protection candidate requires an ACTIVE Online customer Booking';
    END IF;

    SELECT * INTO r FROM iam.venue_account_restriction_interval WHERE id = NEW.restriction_interval_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Protection candidate restriction interval does not exist'; END IF;
    IF r.venue_id IS DISTINCT FROM b.venue_id THEN
        RAISE EXCEPTION 'Protection candidate restriction interval must belong to the Booking Venue';
    END IF;
    IF NOT (r.disabled_at < b.end_at AND (r.reenabled_at IS NULL OR r.reenabled_at > b.start_at)) THEN
        RAISE EXCEPTION 'Protection candidate disable interval must overlap the active Booking session';
    END IF;
    IF NEW.recorded_at < r.disabled_at THEN
        RAISE EXCEPTION 'Protection candidate recorded_at cannot predate Account disable';
    END IF;
    RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS tr_attendance_protection_candidate_validate ON attendance.attendance_protection_candidate;
CREATE TRIGGER tr_attendance_protection_candidate_validate
BEFORE INSERT ON attendance.attendance_protection_candidate
FOR EACH ROW EXECUTE FUNCTION attendance.validate_protection_candidate();

CREATE OR REPLACE FUNCTION attendance.reject_protection_candidate_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    RAISE EXCEPTION 'attendance_protection_candidate is append-only';
END;
$function$;

DROP TRIGGER IF EXISTS tr_attendance_protection_candidate_append_only ON attendance.attendance_protection_candidate;
CREATE TRIGGER tr_attendance_protection_candidate_append_only
BEFORE UPDATE OR DELETE ON attendance.attendance_protection_candidate
FOR EACH ROW EXECUTE FUNCTION attendance.reject_protection_candidate_mutation();

-- A7. Protection Trust event shape: one-per-Booking unique index is native in the
-- model; this deferred assertion ties subject/effective/occurred fields to Booking
-- and Attendance resolution, while preserving later correction/replay semantics.
CREATE OR REPLACE FUNCTION attendance.assert_protection_trust_event()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    b booking.booking%ROWTYPE;
    a attendance.attendance_record%ROWTYPE;
BEGIN
    IF NEW.event_type <> 'BOOKING_ACCOUNT_DISABLE_ATTENDANCE_PROTECTION' THEN
        RETURN NULL;
    END IF;
    IF NEW.booking_id IS NULL THEN
        RAISE EXCEPTION 'Attendance Protection Trust event requires booking_id';
    END IF;
    SELECT * INTO b FROM booking.booking WHERE id = NEW.booking_id;
    IF NOT FOUND OR b.customer_id IS NULL THEN
        RAISE EXCEPTION 'Attendance Protection Trust event requires an Online customer Booking';
    END IF;
    SELECT * INTO a FROM attendance.attendance_record WHERE booking_id = NEW.booking_id;
    IF NOT FOUND OR a.result IS NULL OR a.resolved_at IS NULL THEN
        RAISE EXCEPTION 'Attendance Protection Trust event requires resolved Attendance';
    END IF;
    IF NEW.subject_user_id IS DISTINCT FROM b.customer_id THEN
        RAISE EXCEPTION 'Attendance Protection subject_user_id must equal Booking customer_id';
    END IF;
    IF NEW.effective_at IS DISTINCT FROM b.start_at THEN
        RAISE EXCEPTION 'Attendance Protection effective_at must equal booking.start_at';
    END IF;
    IF NEW.occurred_at IS DISTINCT FROM a.resolved_at THEN
        RAISE EXCEPTION 'Attendance Protection occurred_at must equal Attendance resolution time';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM attendance.attendance_protection_candidate c WHERE c.booking_id = NEW.booking_id) THEN
        RAISE EXCEPTION 'Attendance Protection Trust event requires a recorded protection candidate';
    END IF;
    RETURN NULL;
END;
$function$;

DROP TRIGGER IF EXISTS tr_attendance_protection_trust_event ON trust.trust_event;
CREATE CONSTRAINT TRIGGER tr_attendance_protection_trust_event
AFTER INSERT ON trust.trust_event
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION attendance.assert_protection_trust_event();

-- A8. Booking History attendance events cannot exist without their physical
-- evidence/reversal timestamp (or a matching Attendance correction row/result).
CREATE OR REPLACE FUNCTION attendance.assert_history_attendance_event()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE a attendance.attendance_record%ROWTYPE;
BEGIN
    IF NEW.entry_kind <> 'BOOKING_EVENT' OR NEW.event_type NOT IN (
        'CHECK_IN_RECORDED','CHECK_IN_REVERSED','LATE_PRESENT_RECORDED','LATE_PRESENT_REVERSED',
        'NO_SHOW_RECORDED','NO_SHOW_REVERSED','ATTENDANCE_CORRECTED'
    ) THEN
        RETURN NULL;
    END IF;
    SELECT * INTO a FROM attendance.attendance_record WHERE booking_id = NEW.booking_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Attendance Booking Event requires attendance_record'; END IF;

    IF NEW.event_type = 'CHECK_IN_RECORDED' AND a.check_in_at IS DISTINCT FROM NEW.occurred_at THEN
        RAISE EXCEPTION 'CHECK_IN_RECORDED must match attendance.check_in_at';
    ELSIF NEW.event_type = 'CHECK_IN_REVERSED' AND a.check_in_reversed_at IS DISTINCT FROM NEW.occurred_at THEN
        RAISE EXCEPTION 'CHECK_IN_REVERSED must match attendance.check_in_reversed_at';
    ELSIF NEW.event_type = 'LATE_PRESENT_RECORDED' AND a.late_present_at IS DISTINCT FROM NEW.occurred_at THEN
        RAISE EXCEPTION 'LATE_PRESENT_RECORDED must match attendance.late_present_at';
    ELSIF NEW.event_type = 'LATE_PRESENT_REVERSED' AND a.late_present_reversed_at IS DISTINCT FROM NEW.occurred_at THEN
        RAISE EXCEPTION 'LATE_PRESENT_REVERSED must match attendance.late_present_reversed_at';
    ELSIF NEW.event_type = 'NO_SHOW_RECORDED' AND a.no_show_at IS DISTINCT FROM NEW.occurred_at THEN
        RAISE EXCEPTION 'NO_SHOW_RECORDED must match attendance.no_show_at';
    ELSIF NEW.event_type = 'NO_SHOW_REVERSED' AND a.no_show_reversed_at IS DISTINCT FROM NEW.occurred_at THEN
        RAISE EXCEPTION 'NO_SHOW_REVERSED must match attendance.no_show_reversed_at';
    ELSIF NEW.event_type = 'ATTENDANCE_CORRECTED' AND a.resolved_at IS DISTINCT FROM NEW.occurred_at THEN
        RAISE EXCEPTION 'ATTENDANCE_CORRECTED must match latest Attendance resolution/correction time';
    END IF;
    RETURN NULL;
END;
$function$;

DROP TRIGGER IF EXISTS tr_attendance_integrity_from_history ON booking.booking_history;
CREATE CONSTRAINT TRIGGER tr_attendance_integrity_from_history
AFTER INSERT ON booking.booking_history
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION attendance.assert_history_attendance_event();



-- ============================================================================
-- E7GZ PS v1.1.10 ATTENDANCE ACCEPTANCE FIXES
-- Apply after v1.1.9. PostgreSQL 15+.
-- ============================================================================

-- B1. Attendance result mutation: preserve the ordinary audited-correction rule,
-- but allow the Product-defined post-end No-show reversal default
-- ABSENT_NO_SHOW -> ATTENDANCE_UNCONFIRMED without inventing ATTENDANCE_CORRECTED.
CREATE OR REPLACE FUNCTION attendance.guard_attendance_record_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    b booking.booking%ROWTYPE;
    v_original_added boolean;
    v_post_end_no_show_reversal_default boolean;
BEGIN
    SELECT * INTO b FROM booking.booking WHERE id = NEW.booking_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Attendance Booking does not exist';
    END IF;

    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.booking_id IS DISTINCT FROM OLD.booking_id THEN
        RAISE EXCEPTION 'Attendance record identity/Booking ownership is immutable';
    END IF;

    IF OLD.check_in_at IS NOT NULL AND NEW.check_in_at IS DISTINCT FROM OLD.check_in_at THEN
        RAISE EXCEPTION 'check_in_at is immutable once recorded';
    END IF;
    IF OLD.late_present_at IS NOT NULL AND NEW.late_present_at IS DISTINCT FROM OLD.late_present_at THEN
        RAISE EXCEPTION 'late_present_at is immutable once recorded';
    END IF;
    IF OLD.no_show_at IS NOT NULL AND NEW.no_show_at IS DISTINCT FROM OLD.no_show_at THEN
        RAISE EXCEPTION 'no_show_at is immutable once recorded';
    END IF;

    IF OLD.check_in_reversed_at IS NOT NULL AND NEW.check_in_reversed_at IS DISTINCT FROM OLD.check_in_reversed_at THEN
        RAISE EXCEPTION 'check_in_reversed_at is immutable once recorded';
    END IF;
    IF OLD.late_present_reversed_at IS NOT NULL AND NEW.late_present_reversed_at IS DISTINCT FROM OLD.late_present_reversed_at THEN
        RAISE EXCEPTION 'late_present_reversed_at is immutable once recorded';
    END IF;
    IF OLD.no_show_reversed_at IS NOT NULL AND NEW.no_show_reversed_at IS DISTINCT FROM OLD.no_show_reversed_at THEN
        RAISE EXCEPTION 'no_show_reversed_at is immutable once recorded';
    END IF;

    v_original_added :=
        (OLD.check_in_at IS NULL AND NEW.check_in_at IS NOT NULL)
        OR (OLD.late_present_at IS NULL AND NEW.late_present_at IS NOT NULL)
        OR (OLD.no_show_at IS NULL AND NEW.no_show_at IS NOT NULL);

    IF NEW.recorded_by_venue_account_id IS DISTINCT FROM OLD.recorded_by_venue_account_id
       AND NOT v_original_added THEN
        RAISE EXCEPTION 'recorded_by_venue_account_id may change only with a new original Venue attendance action';
    END IF;

    v_post_end_no_show_reversal_default :=
        OLD.result = 'ABSENT_NO_SHOW'
        AND NEW.result = 'ATTENDANCE_UNCONFIRMED'
        AND OLD.no_show_at IS NOT NULL
        AND OLD.no_show_reversed_at IS NULL
        AND NEW.no_show_reversed_at IS NOT NULL
        AND NEW.no_show_reversed_at >= b.end_at
        AND NEW.resolved_at IS NOT NULL
        AND NEW.resolved_at = NEW.no_show_reversed_at;

    IF OLD.result IS NULL THEN
        IF NEW.result IS NULL THEN
            IF NEW.resolved_at IS NOT NULL THEN
                RAISE EXCEPTION 'unresolved Attendance cannot have resolved_at';
            END IF;
        ELSE
            IF NEW.resolved_at IS NULL THEN
                RAISE EXCEPTION 'resolving Attendance requires resolved_at';
            END IF;
        END IF;
    ELSE
        IF NEW.result IS NULL THEN
            RAISE EXCEPTION 'resolved Attendance Result cannot return to NULL';
        END IF;
        IF NEW.result IS DISTINCT FROM OLD.result THEN
            IF NEW.resolved_at IS NULL OR OLD.resolved_at IS NULL OR NEW.resolved_at <= OLD.resolved_at THEN
                RAISE EXCEPTION 'Attendance result change must move resolved_at forward';
            END IF;
            IF v_post_end_no_show_reversal_default AND NEW.resolved_at IS DISTINCT FROM NEW.no_show_reversed_at THEN
                RAISE EXCEPTION 'post-end No-show reversal default must resolve at no_show_reversed_at';
            END IF;
        ELSIF NEW.resolved_at IS DISTINCT FROM OLD.resolved_at THEN
            RAISE EXCEPTION 'resolved_at may change only with an Attendance Result change';
        END IF;
    END IF;

    IF OLD.protection_applied AND NOT NEW.protection_applied THEN
        RAISE EXCEPTION 'historical protection_applied may not be cleared';
    END IF;

    RETURN NEW;
END;
$function$;

-- B2. Per-action audit: the Venue actor written on attendance_record must be the
-- exact same actor in Booking History/Audit. No-show reversal also requires the
-- canonical NO_SHOW_REVERSED Trust event. The post-end default reversal is not
-- misclassified as ATTENDANCE_CORRECTED.
CREATE OR REPLACE FUNCTION attendance.assert_attendance_action_audit()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    b booking.booking%ROWTYPE;
    v_event text;
    v_at timestamptz;
    v_is_admin boolean;
    v_check_added boolean;
    v_late_added boolean;
    v_no_show_added boolean;
    v_check_reversed_added boolean;
    v_late_reversed_added boolean;
    v_no_show_reversed_added boolean;
    v_post_end_no_show_reversal_default boolean;
BEGIN
    SELECT * INTO b FROM booking.booking WHERE id = NEW.booking_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Attendance Booking does not exist'; END IF;

    IF TG_OP = 'INSERT' THEN
        v_check_added := NEW.check_in_at IS NOT NULL;
        v_late_added := NEW.late_present_at IS NOT NULL;
        v_no_show_added := NEW.no_show_at IS NOT NULL;
        v_check_reversed_added := NEW.check_in_reversed_at IS NOT NULL;
        v_late_reversed_added := NEW.late_present_reversed_at IS NOT NULL;
        v_no_show_reversed_added := NEW.no_show_reversed_at IS NOT NULL;
        v_post_end_no_show_reversal_default := false;
    ELSE
        v_check_added := NEW.check_in_at IS NOT NULL AND OLD.check_in_at IS NULL;
        v_late_added := NEW.late_present_at IS NOT NULL AND OLD.late_present_at IS NULL;
        v_no_show_added := NEW.no_show_at IS NOT NULL AND OLD.no_show_at IS NULL;
        v_check_reversed_added := NEW.check_in_reversed_at IS NOT NULL AND OLD.check_in_reversed_at IS NULL;
        v_late_reversed_added := NEW.late_present_reversed_at IS NOT NULL AND OLD.late_present_reversed_at IS NULL;
        v_no_show_reversed_added := NEW.no_show_reversed_at IS NOT NULL AND OLD.no_show_reversed_at IS NULL;
        v_post_end_no_show_reversal_default :=
            OLD.result = 'ABSENT_NO_SHOW'
            AND NEW.result = 'ATTENDANCE_UNCONFIRMED'
            AND OLD.no_show_at IS NOT NULL
            AND OLD.no_show_reversed_at IS NULL
            AND NEW.no_show_reversed_at IS NOT NULL
            AND NEW.no_show_reversed_at >= b.end_at
            AND NEW.resolved_at = NEW.no_show_reversed_at;
    END IF;

    FOR v_event, v_at, v_is_admin IN
        SELECT 'CHECK_IN_RECORDED', NEW.check_in_at, false WHERE v_check_added
        UNION ALL SELECT 'LATE_PRESENT_RECORDED', NEW.late_present_at, false WHERE v_late_added
        UNION ALL SELECT 'NO_SHOW_RECORDED', NEW.no_show_at, false WHERE v_no_show_added
        UNION ALL SELECT 'CHECK_IN_REVERSED', NEW.check_in_reversed_at, true WHERE v_check_reversed_added
        UNION ALL SELECT 'LATE_PRESENT_REVERSED', NEW.late_present_reversed_at, true WHERE v_late_reversed_added
        UNION ALL SELECT 'NO_SHOW_REVERSED', NEW.no_show_reversed_at, true WHERE v_no_show_reversed_added
    LOOP
        IF v_is_admin THEN
            IF NOT EXISTS (
                SELECT 1
                  FROM booking.booking_history bh
                  JOIN audit.audit_event ae
                    ON ae.subject_type = 'BOOKING'
                   AND ae.subject_id = NEW.booking_id
                   AND ae.action = v_event
                   AND ae.actor_type = 'ADMIN'
                   AND ae.actor_id = bh.actor_id
                   AND ae.occurred_at = v_at
                   AND NULLIF(BTRIM(ae.reason),'') IS NOT NULL
                 WHERE bh.booking_id = NEW.booking_id
                   AND bh.entry_kind = 'BOOKING_EVENT'
                   AND bh.event_type = v_event
                   AND bh.actor_type = 'ADMIN'
                   AND bh.actor_id IS NOT NULL
                   AND bh.occurred_at = v_at
            ) THEN
                RAISE EXCEPTION '% requires matching Admin Booking History + Audit reason', v_event;
            END IF;
        ELSE
            IF NOT EXISTS (
                SELECT 1
                  FROM booking.booking_history bh
                  JOIN iam.venue_account va
                    ON va.id = bh.actor_id
                   AND va.venue_id = b.venue_id
                  JOIN audit.audit_event ae
                    ON ae.subject_type = 'BOOKING'
                   AND ae.subject_id = NEW.booking_id
                   AND ae.action = v_event
                   AND ae.actor_type = 'VENUE'
                   AND ae.actor_id = bh.actor_id
                   AND ae.occurred_at = v_at
                 WHERE bh.booking_id = NEW.booking_id
                   AND bh.entry_kind = 'BOOKING_EVENT'
                   AND bh.event_type = v_event
                   AND bh.actor_type = 'VENUE'
                   AND bh.actor_id = NEW.recorded_by_venue_account_id
                   AND bh.occurred_at = v_at
            ) THEN
                RAISE EXCEPTION '% requires the same Venue Account actor in Attendance, Booking History and Audit', v_event;
            END IF;
        END IF;
    END LOOP;

    IF v_no_show_reversed_added THEN
        IF NOT EXISTS (
            SELECT 1
              FROM trust.trust_event rev
              JOIN trust.trust_event orig ON orig.id = rev.original_outcome_event_id
             WHERE rev.booking_id = NEW.booking_id
               AND rev.event_type = 'NO_SHOW_REVERSED'
               AND rev.subject_user_id = b.customer_id
               AND rev.occurred_at = NEW.no_show_reversed_at
               AND rev.effective_at = b.start_at
               AND orig.booking_id = NEW.booking_id
               AND orig.event_type = 'BOOKING_NO_SHOW'
        ) THEN
            RAISE EXCEPTION 'NO_SHOW_REVERSED attendance action requires matching canonical Trust reversal';
        END IF;
    END IF;

    IF TG_OP = 'UPDATE'
       AND OLD.result IS NOT NULL
       AND NEW.result IS DISTINCT FROM OLD.result
       AND NOT v_post_end_no_show_reversal_default THEN
        IF NOT EXISTS (
            SELECT 1
              FROM booking.booking_history bh
              JOIN audit.audit_event ae
                ON ae.subject_type = 'BOOKING'
               AND ae.subject_id = NEW.booking_id
               AND ae.action = 'ATTENDANCE_CORRECTED'
               AND ae.actor_type = 'ADMIN'
               AND ae.actor_id = bh.actor_id
               AND ae.occurred_at = NEW.resolved_at
               AND NULLIF(BTRIM(ae.reason),'') IS NOT NULL
             WHERE bh.booking_id = NEW.booking_id
               AND bh.entry_kind = 'BOOKING_EVENT'
               AND bh.event_type = 'ATTENDANCE_CORRECTED'
               AND bh.actor_type = 'ADMIN'
               AND bh.actor_id IS NOT NULL
               AND bh.occurred_at = NEW.resolved_at
        ) THEN
            RAISE EXCEPTION 'Attendance Result correction requires matching Admin Booking History + Audit reason';
        END IF;
        IF NOT EXISTS (
            SELECT 1 FROM trust.trust_event te
             WHERE te.booking_id = NEW.booking_id
               AND te.event_type = 'ATTENDANCE_CORRECTED'
               AND te.corrected_outcome = NEW.result
               AND te.occurred_at = NEW.resolved_at
        ) THEN
            RAISE EXCEPTION 'Attendance Result correction requires matching ATTENDANCE_CORRECTED Trust event';
        END IF;
    END IF;

    RETURN NULL;
END;
$function$;

-- B3. Canonical Attendance final-state assertion. No-show is now atomic even if
-- result was previously unresolved; release timing and Trust outcome/reversal are
-- cross-checked. Admin support interruption is detected from ACTIVE->CANCELLED history.
CREATE OR REPLACE FUNCTION attendance.assert_attendance_row(p_attendance_id uuid)
RETURNS void
LANGUAGE plpgsql
AS $function$
DECLARE
    a attendance.attendance_record%ROWTYPE;
    b booking.booking%ROWTYPE;
    v_active_check boolean;
    v_active_late boolean;
    v_active_no_show boolean;
    v_latest_correction text;
    v_leaf_count integer;
    v_protection_count integer;
    v_admin_active_interruption boolean;
    v_original_no_show_id uuid;
    v_original_no_show_count integer;
    v_no_show_reversal_count integer;
BEGIN
    SELECT * INTO a FROM attendance.attendance_record WHERE id = p_attendance_id;
    IF NOT FOUND THEN RETURN; END IF;
    SELECT * INTO b FROM booking.booking WHERE id = a.booking_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Attendance Booking does not exist'; END IF;

    v_active_check := a.check_in_at IS NOT NULL AND a.check_in_reversed_at IS NULL;
    v_active_late := a.late_present_at IS NOT NULL AND a.late_present_reversed_at IS NULL;
    v_active_no_show := a.no_show_at IS NOT NULL AND a.no_show_reversed_at IS NULL;

    SELECT COUNT(*), (ARRAY_AGG(te.corrected_outcome ORDER BY te.event_sequence DESC))[1]
      INTO v_leaf_count, v_latest_correction
      FROM trust.trust_event te
     WHERE te.booking_id = a.booking_id
       AND te.event_type = 'ATTENDANCE_CORRECTED'
       AND NOT EXISTS (
            SELECT 1 FROM trust.trust_event s
             WHERE s.event_type = 'ATTENDANCE_CORRECTED'
               AND s.superseded_correction_event_id = te.id
       );
    IF v_leaf_count > 1 THEN
        RAISE EXCEPTION 'Attendance correction chain has more than one non-superseded leaf';
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM booking.booking_history bh
         WHERE bh.booking_id = a.booking_id
           AND bh.entry_kind = 'STATUS_TRANSITION'
           AND bh.from_status = 'ACTIVE'
           AND bh.to_status = 'CANCELLED'
           AND bh.actor_type = 'ADMIN'
           AND bh.terminal_reason = b.terminal_reason
           AND bh.terminal_reason IN ('ADMIN_CANCELLED','ADMIN_CORRECTION')
    ) INTO v_admin_active_interruption;

    -- Any recorded No-show owns exactly one original canonical BOOKING_NO_SHOW event.
    IF a.no_show_at IS NOT NULL THEN
        SELECT COUNT(*), (ARRAY_AGG(te.id ORDER BY te.event_sequence))[1]
          INTO v_original_no_show_count, v_original_no_show_id
          FROM trust.trust_event te
         WHERE te.booking_id = a.booking_id
           AND te.event_type = 'BOOKING_NO_SHOW'
           AND te.subject_user_id = b.customer_id
           AND te.effective_at = b.start_at
           AND te.occurred_at = a.no_show_at;
        IF v_original_no_show_count <> 1 THEN
            RAISE EXCEPTION 'No-show requires exactly one canonical BOOKING_NO_SHOW Trust event at no_show_at';
        END IF;
    END IF;

    -- Unreversed No-show is one atomic final outcome, including immediate release.
    IF v_active_no_show THEN
        IF v_latest_correction IS NOT NULL THEN
            RAISE EXCEPTION 'Attendance correction requires reversing the committed No-show first';
        END IF;
        IF b.status <> 'NO_SHOW' OR a.result <> 'ABSENT_NO_SHOW' OR a.resolved_at IS DISTINCT FROM a.no_show_at THEN
            RAISE EXCEPTION 'unreversed No-show requires Booking NO_SHOW and resolved ABSENT_NO_SHOW at no_show_at';
        END IF;
        IF NOT EXISTS (
            SELECT 1 FROM booking.booking_history bh
             WHERE bh.booking_id = a.booking_id
               AND bh.entry_kind = 'BOOKING_EVENT'
               AND bh.event_type = 'NO_SHOW_RECORDED'
               AND bh.occurred_at = a.no_show_at
        ) THEN
            RAISE EXCEPTION 'No-show requires NO_SHOW_RECORDED Booking Event';
        END IF;
        IF EXISTS (
            SELECT 1 FROM inventory.resource_reservation rr
             WHERE rr.booking_id = a.booking_id
               AND rr.reservation_type IN ('BOOKING','LATE_CONFIRM_HOLD')
               AND rr.active_flag = true
        ) THEN
            RAISE EXCEPTION 'No-show must release all active Booking/Late-Confirm resource commitments';
        END IF;
        IF NOT EXISTS (
            SELECT 1 FROM inventory.resource_reservation rr
             WHERE rr.booking_id = a.booking_id
               AND rr.reservation_type = 'BOOKING'
               AND rr.planned_start <= a.no_show_at
               AND a.no_show_at < rr.planned_end
               AND rr.active_flag = false
               AND rr.actual_reservation_release_at = a.no_show_at
        ) THEN
            RAISE EXCEPTION 'No-show must release the canonical Booking reservation exactly at no_show_at';
        END IF;
    ELSIF b.status = 'NO_SHOW' THEN
        RAISE EXCEPTION 'Booking NO_SHOW requires unreversed No-show evidence';
    END IF;

    -- No-show reversal lifecycle and canonical Trust reversal.
    IF a.no_show_reversed_at IS NOT NULL THEN
        SELECT COUNT(*) INTO v_no_show_reversal_count
          FROM trust.trust_event te
         WHERE te.booking_id = a.booking_id
           AND te.event_type = 'NO_SHOW_REVERSED'
           AND te.subject_user_id = b.customer_id
           AND te.effective_at = b.start_at
           AND te.occurred_at = a.no_show_reversed_at
           AND te.original_outcome_event_id = v_original_no_show_id;
        IF v_no_show_reversal_count <> 1 THEN
            RAISE EXCEPTION 'No-show reversal requires exactly one canonical NO_SHOW_REVERSED Trust event';
        END IF;

        IF a.no_show_reversed_at < b.end_at THEN
            IF b.status <> 'CANCELLED' OR b.terminal_reason <> 'ADMIN_NO_SHOW_REVERSAL' THEN
                RAISE EXCEPTION 'pre-end No-show reversal requires CANCELLED / ADMIN_NO_SHOW_REVERSAL';
            END IF;
        ELSE
            IF b.status <> 'COMPLETED' THEN
                RAISE EXCEPTION 'post-end No-show reversal requires Booking COMPLETED';
            END IF;
            IF v_latest_correction IS NULL AND a.result <> 'ATTENDANCE_UNCONFIRMED' THEN
                RAISE EXCEPTION 'post-end No-show reversal defaults to ATTENDANCE_UNCONFIRMED unless separately corrected';
            END IF;
        END IF;
    END IF;

    -- Initial/default Attendance result rules apply only when no correction is authoritative.
    IF a.result IS NOT NULL AND v_latest_correction IS NULL THEN
        IF b.source = 'MANUAL' THEN
            IF a.result <> 'NOT_APPLICABLE' THEN
                RAISE EXCEPTION 'Manual Booking Attendance must resolve to NOT_APPLICABLE';
            END IF;
        ELSIF v_active_no_show THEN
            NULL; -- already asserted above
        ELSIF b.status = 'COMPLETED' THEN
            IF a.no_show_reversed_at IS NOT NULL AND a.no_show_reversed_at >= b.end_at THEN
                IF a.result <> 'ATTENDANCE_UNCONFIRMED' THEN
                    RAISE EXCEPTION 'post-end No-show reversal defaults to ATTENDANCE_UNCONFIRMED';
                END IF;
            ELSIF v_active_check AND a.result <> 'ATTENDED' THEN
                RAISE EXCEPTION 'normal completion with qualifying Check-in requires ATTENDED';
            ELSIF NOT v_active_check AND a.result <> 'ATTENDANCE_UNCONFIRMED' THEN
                RAISE EXCEPTION 'normal completion without qualifying Check-in requires ATTENDANCE_UNCONFIRMED';
            END IF;
        ELSIF b.status = 'CANCELLED'
              AND (b.terminal_reason IN ('RESOURCE_EMERGENCY_OUTAGE','VENUE_EMERGENCY_CLOSURE','RESOURCE_OWNER_REVIEW_REQUIRED')
                   OR v_admin_active_interruption) THEN
            IF v_active_check AND a.result <> 'ATTENDED_INTERRUPTED' THEN
                RAISE EXCEPTION 'ACTIVE interruption after Check-in requires ATTENDED_INTERRUPTED';
            ELSIF v_active_late AND a.result <> 'ATTENDANCE_UNCONFIRMED' THEN
                RAISE EXCEPTION 'ACTIVE interruption with Late Present only requires ATTENDANCE_UNCONFIRMED';
            ELSIF NOT v_active_check AND NOT v_active_late AND a.result <> 'NOT_APPLICABLE' THEN
                RAISE EXCEPTION 'ACTIVE interruption without attendance evidence requires NOT_APPLICABLE';
            END IF;
        ELSIF b.status IN ('CANCELLED','REJECTED')
              AND a.check_in_at IS NULL AND a.late_present_at IS NULL AND a.no_show_at IS NULL
              AND a.result <> 'NOT_APPLICABLE' THEN
            RAISE EXCEPTION 'cancelled/rejected Booking before any attendance evidence requires NOT_APPLICABLE';
        END IF;
    ELSIF a.result IS NOT NULL AND v_latest_correction IS NOT NULL AND a.result IS DISTINCT FROM v_latest_correction THEN
        RAISE EXCEPTION 'stored Attendance Result must match the latest non-superseded ATTENDANCE_CORRECTED outcome';
    END IF;

    SELECT COUNT(*) INTO v_protection_count
      FROM trust.trust_event te
     WHERE te.booking_id = a.booking_id
       AND te.event_type = 'BOOKING_ACCOUNT_DISABLE_ATTENDANCE_PROTECTION';

    IF a.protection_applied THEN
        IF v_protection_count <> 1 THEN
            RAISE EXCEPTION 'protection_applied requires exactly one protection Trust event';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM attendance.attendance_protection_candidate c WHERE c.booking_id = a.booking_id) THEN
            RAISE EXCEPTION 'protection_applied requires at least one Attendance Protection candidate';
        END IF;
        IF v_latest_correction IS NULL AND a.result NOT IN ('ATTENDANCE_UNCONFIRMED','NOT_APPLICABLE') THEN
            RAISE EXCEPTION 'initial Attendance Protection may apply only to ATTENDANCE_UNCONFIRMED or eligible NOT_APPLICABLE';
        END IF;
    ELSIF v_protection_count <> 0 THEN
        RAISE EXCEPTION 'protection Trust event requires attendance_record.protection_applied = true';
    END IF;
END;
$function$;

-- B4. Candidate is an at-disable immutable fact, not a later reconstruction.
CREATE OR REPLACE FUNCTION attendance.validate_protection_candidate()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    b booking.booking%ROWTYPE;
    r iam.venue_account_restriction_interval%ROWTYPE;
BEGIN
    SELECT * INTO b FROM booking.booking WHERE id = NEW.booking_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Protection candidate Booking does not exist'; END IF;
    IF b.source <> 'ONLINE' OR b.customer_id IS NULL OR b.status <> 'ACTIVE' THEN
        RAISE EXCEPTION 'Protection candidate requires an ACTIVE Online customer Booking';
    END IF;

    SELECT * INTO r FROM iam.venue_account_restriction_interval WHERE id = NEW.restriction_interval_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Protection candidate restriction interval does not exist'; END IF;
    IF r.venue_id IS DISTINCT FROM b.venue_id THEN
        RAISE EXCEPTION 'Protection candidate restriction interval must belong to the Booking Venue';
    END IF;
    IF NOT (r.disabled_at < b.end_at AND (r.reenabled_at IS NULL OR r.reenabled_at > b.start_at)) THEN
        RAISE EXCEPTION 'Protection candidate disable interval must overlap the active Booking session';
    END IF;
    IF NEW.recorded_at IS DISTINCT FROM r.disabled_at THEN
        RAISE EXCEPTION 'Protection candidate recorded_at must equal the Account disabled_at timestamp';
    END IF;
    RETURN NEW;
END;
$function$;

-- B5. Trust correction-chain integrity. The Booking row lock serializes correction
-- writers. A new Attendance correction must supersede the current single leaf, and
-- every correction in a chain keeps the same original Booking Trust outcome.
CREATE OR REPLACE FUNCTION trust.validate_attendance_correction_event()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    b booking.booking%ROWTYPE;
    orig trust.trust_event%ROWTYPE;
    prev trust.trust_event%ROWTYPE;
    v_leaf_count integer;
    v_leaf_id uuid;
    v_leaf_sequence bigint;
BEGIN
    IF NEW.event_type NOT IN ('ATTENDANCE_CORRECTED','NO_SHOW_REVERSED') THEN
        RETURN NEW;
    END IF;

    IF NEW.booking_id IS NULL THEN
        RAISE EXCEPTION '% requires booking_id', NEW.event_type;
    END IF;

    SELECT * INTO b FROM booking.booking WHERE id = NEW.booking_id FOR UPDATE;
    IF NOT FOUND OR b.source <> 'ONLINE' OR b.customer_id IS NULL THEN
        RAISE EXCEPTION '% requires an Online customer Booking', NEW.event_type;
    END IF;
    IF NEW.subject_user_id IS DISTINCT FROM b.customer_id THEN
        RAISE EXCEPTION '% subject_user_id must equal Booking customer_id', NEW.event_type;
    END IF;
    IF NEW.original_outcome_event_id IS NULL THEN
        RAISE EXCEPTION '% requires original_outcome_event_id', NEW.event_type;
    END IF;

    SELECT * INTO orig FROM trust.trust_event WHERE id = NEW.original_outcome_event_id;
    IF NOT FOUND
       OR orig.event_type NOT IN ('BOOKING_ATTENDED','BOOKING_ATTENDANCE_UNCONFIRMED','BOOKING_ATTENDED_INTERRUPTED','BOOKING_NO_SHOW')
       OR orig.booking_id IS DISTINCT FROM NEW.booking_id
       OR orig.subject_user_id IS DISTINCT FROM NEW.subject_user_id THEN
        RAISE EXCEPTION '% original_outcome_event_id must reference the canonical original Booking attendance outcome', NEW.event_type;
    END IF;
    IF NEW.effective_at IS DISTINCT FROM orig.effective_at OR NEW.effective_at IS DISTINCT FROM b.start_at THEN
        RAISE EXCEPTION '% effective_at must equal the original Booking Trust position / booking.start_at', NEW.event_type;
    END IF;
    IF NEW.event_sequence <= orig.event_sequence THEN
        RAISE EXCEPTION '% event_sequence must be later than the original outcome', NEW.event_type;
    END IF;
    IF NEW.occurred_at < orig.occurred_at THEN
        RAISE EXCEPTION '% occurred_at cannot predate the original outcome', NEW.event_type;
    END IF;

    IF NEW.event_type = 'NO_SHOW_REVERSED' THEN
        IF orig.event_type <> 'BOOKING_NO_SHOW' THEN
            RAISE EXCEPTION 'NO_SHOW_REVERSED must target BOOKING_NO_SHOW';
        END IF;
        IF NEW.superseded_correction_event_id IS NOT NULL THEN
            RAISE EXCEPTION 'NO_SHOW_REVERSED cannot supersede an Attendance correction';
        END IF;
        RETURN NEW;
    END IF;

    SELECT COUNT(*), (ARRAY_AGG(te.id ORDER BY te.event_sequence DESC))[1]
      INTO v_leaf_count, v_leaf_id
      FROM trust.trust_event te
     WHERE te.booking_id = NEW.booking_id
       AND te.event_type = 'ATTENDANCE_CORRECTED'
       AND NOT EXISTS (
            SELECT 1 FROM trust.trust_event s
             WHERE s.event_type = 'ATTENDANCE_CORRECTED'
               AND s.superseded_correction_event_id = te.id
       );

    IF v_leaf_count > 1 THEN
        RAISE EXCEPTION 'existing Attendance correction chain is branched; manual reconciliation required';
    ELSIF v_leaf_count = 0 THEN
        IF NEW.superseded_correction_event_id IS NOT NULL THEN
            RAISE EXCEPTION 'first Attendance correction cannot supersede a non-existent prior correction';
        END IF;
    ELSE
        IF NEW.superseded_correction_event_id IS DISTINCT FROM v_leaf_id THEN
            RAISE EXCEPTION 'new Attendance correction must supersede the current non-superseded correction';
        END IF;
        SELECT event_sequence INTO v_leaf_sequence FROM trust.trust_event WHERE id = v_leaf_id;
        IF NEW.event_sequence <= v_leaf_sequence THEN
            RAISE EXCEPTION 'new Attendance correction event_sequence must be later than the correction it supersedes';
        END IF;
    END IF;

    IF NEW.superseded_correction_event_id IS NOT NULL THEN
        SELECT * INTO prev FROM trust.trust_event WHERE id = NEW.superseded_correction_event_id;
        IF NOT FOUND
           OR prev.event_type <> 'ATTENDANCE_CORRECTED'
           OR prev.booking_id IS DISTINCT FROM NEW.booking_id
           OR prev.original_outcome_event_id IS DISTINCT FROM NEW.original_outcome_event_id
           OR prev.subject_user_id IS DISTINCT FROM NEW.subject_user_id
           OR prev.effective_at IS DISTINCT FROM NEW.effective_at THEN
            RAISE EXCEPTION 'superseded Attendance correction must be the prior correction in the same Booking/original-outcome chain';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS tr_trust_attendance_correction_validate ON trust.trust_event;
CREATE TRIGGER tr_trust_attendance_correction_validate
BEFORE INSERT ON trust.trust_event
FOR EACH ROW EXECUTE FUNCTION trust.validate_attendance_correction_event();

-- B6. Protection creation revalidates the frozen eligibility/material-prevention
-- rules. Existing historical protection may later be neutralised by Admin correction;
-- this guard controls creation-time eligibility only.
CREATE OR REPLACE FUNCTION attendance.assert_protection_trust_event()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    b booking.booking%ROWTYPE;
    a attendance.attendance_record%ROWTYPE;
BEGIN
    IF NEW.event_type <> 'BOOKING_ACCOUNT_DISABLE_ATTENDANCE_PROTECTION' THEN
        RETURN NULL;
    END IF;
    IF NEW.booking_id IS NULL THEN
        RAISE EXCEPTION 'Attendance Protection Trust event requires booking_id';
    END IF;
    SELECT * INTO b FROM booking.booking WHERE id = NEW.booking_id;
    IF NOT FOUND OR b.source <> 'ONLINE' OR b.customer_id IS NULL THEN
        RAISE EXCEPTION 'Attendance Protection Trust event requires an Online customer Booking';
    END IF;
    SELECT * INTO a FROM attendance.attendance_record WHERE booking_id = NEW.booking_id;
    IF NOT FOUND OR a.result IS NULL OR a.resolved_at IS NULL THEN
        RAISE EXCEPTION 'Attendance Protection Trust event requires resolved Attendance';
    END IF;
    IF a.result NOT IN ('ATTENDANCE_UNCONFIRMED','NOT_APPLICABLE') THEN
        RAISE EXCEPTION 'Attendance Protection can be created only for ATTENDANCE_UNCONFIRMED or eligible NOT_APPLICABLE';
    END IF;
    IF NEW.subject_user_id IS DISTINCT FROM b.customer_id THEN
        RAISE EXCEPTION 'Attendance Protection subject_user_id must equal Booking customer_id';
    END IF;
    IF NEW.effective_at IS DISTINCT FROM b.start_at THEN
        RAISE EXCEPTION 'Attendance Protection effective_at must equal booking.start_at';
    END IF;
    IF NEW.occurred_at IS DISTINCT FROM a.resolved_at THEN
        RAISE EXCEPTION 'Attendance Protection occurred_at must equal Attendance resolution time';
    END IF;

    IF NOT EXISTS (
        SELECT 1
          FROM attendance.attendance_protection_candidate c
          JOIN iam.venue_account_restriction_interval r ON r.id = c.restriction_interval_id
         WHERE c.booking_id = NEW.booking_id
           AND r.venue_id = b.venue_id
           AND c.recorded_at = r.disabled_at
           AND r.disabled_at >= b.start_at
           AND r.disabled_at < LEAST(b.end_at, a.resolved_at)
           AND (a.check_in_at IS NULL OR a.check_in_at >= r.disabled_at)
           AND (a.late_present_at IS NULL OR a.late_present_at >= r.disabled_at)
           AND (a.no_show_at IS NULL OR a.no_show_at >= r.disabled_at)
           AND (
                (
                    a.late_present_at IS NOT NULL
                    AND a.late_present_reversed_at IS NULL
                    AND r.disabled_at < LEAST(b.start_at + interval '15 minutes', b.end_at)
                    AND COALESCE(r.reenabled_at, 'infinity'::timestamptz) > b.start_at
                )
                OR
                (
                    NOT (a.late_present_at IS NOT NULL AND a.late_present_reversed_at IS NULL)
                    AND r.disabled_at < LEAST(b.end_at, a.resolved_at)
                    AND COALESCE(r.reenabled_at, 'infinity'::timestamptz) > b.start_at
                )
           )
    ) THEN
        RAISE EXCEPTION 'Attendance Protection requires a qualifying Account-disable interval that materially prevented reliable attendance recording';
    END IF;

    RETURN NULL;
END;
$function$;

-- B7. Validate all pre-existing Attendance rows against the new acceptance invariant.
DO $validate$
DECLARE
    r record;
BEGIN
    FOR r IN SELECT id FROM attendance.attendance_record LOOP
        PERFORM attendance.assert_attendance_row(r.id);
    END LOOP;
END
$validate$;

-- B8. Delivery contract: v1.1.10 adds no Product-visible enum or role. Application
-- commands must write Booking/Attendance/Reservation/History/Audit/Trust in one
-- transaction so all deferred assertions observe the final canonical state.



-- ============================================================================
-- E7GZ PS v1.1.11 TOURNAMENT HARDENING
-- PostgreSQL 15+. Apply after v1.1.10.
-- Product-visible Tournament states/reasons are unchanged.
-- ============================================================================

-- T1. Shared helpers.
CREATE OR REPLACE FUNCTION tournament.active_participant_count(p_tournament_id uuid)
RETURNS integer
LANGUAGE sql
STABLE
AS $function$
SELECT COUNT(*)::integer
  FROM tournament.tournament_participant p
  JOIN iam.user_account u ON u.id = p.user_id
 WHERE p.tournament_id = p_tournament_id
   AND p.status = 'JOINED'
   AND u.anonymised_at IS NULL
   AND NOT EXISTS (
       SELECT 1
         FROM trust.ban_instance b
        WHERE b.user_id = p.user_id
          AND b.status = 'ACTIVE'
          AND b.activated_at <= transaction_timestamp()
          AND b.ends_at > transaction_timestamp()
   );
$function$;

CREATE OR REPLACE FUNCTION tournament.expected_resource_price(
    p_resource_id uuid,
    p_activity text,
    p_play_mode text
)
RETURNS numeric
LANGUAGE plpgsql
STABLE
AS $function$
DECLARE
    r resource.resource%ROWTYPE;
    v_price numeric;
BEGIN
    SELECT * INTO r FROM resource.resource WHERE id = p_resource_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Tournament Resource % does not exist', p_resource_id;
    END IF;
    IF r.activity IS DISTINCT FROM p_activity THEN
        RAISE EXCEPTION 'Tournament Resource activity % does not match Tournament activity %', r.activity, p_activity;
    END IF;

    IF p_activity = 'PLAYSTATION' THEN
        SELECT o.hourly_price INTO v_price
          FROM pricing.resource_price_override o
         WHERE o.resource_id = r.id
           AND o.console_type = r.console_type
           AND o.play_mode = p_play_mode;
        IF v_price IS NULL THEN
            SELECT d.hourly_price INTO v_price
              FROM pricing.venue_default_price d
             WHERE d.venue_id = r.venue_id
               AND d.activity = 'PLAYSTATION'
               AND d.console_type = r.console_type
               AND d.play_mode = p_play_mode;
        END IF;
    ELSE
        SELECT d.hourly_price INTO v_price
          FROM pricing.venue_default_price d
         WHERE d.venue_id = r.venue_id
           AND d.activity = p_activity
           AND d.console_type IS NULL
           AND d.play_mode IS NULL;
    END IF;

    IF v_price IS NULL THEN
        RAISE EXCEPTION 'No effective Tournament price exists for Resource %', p_resource_id;
    END IF;
    RETURN v_price;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.assert_resources_operational(
    p_tournament_id uuid,
    p_expected_hold_type text
)
RETURNS void
LANGUAGE plpgsql
AS $function$
DECLARE
    t tournament.tournament%ROWTYPE;
BEGIN
    SELECT * INTO t FROM tournament.tournament WHERE id = p_tournament_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament % does not exist', p_tournament_id; END IF;

    IF (SELECT COUNT(*) FROM tournament.tournament_resource tr WHERE tr.tournament_id = t.id) NOT BETWEEN 1 AND 4 THEN
        RAISE EXCEPTION 'Tournament requires exactly 1 to 4 Resources';
    END IF;

    IF EXISTS (SELECT 1 FROM venue.venue_selling_block vb WHERE vb.venue_id = t.venue_id AND vb.active) THEN
        RAISE EXCEPTION 'Tournament Venue is under an Operational Selling Block';
    END IF;
    IF EXISTS (
        SELECT 1 FROM operations.venue_closure c
         WHERE c.venue_id = t.venue_id
           AND c.period && tstzrange(t.start_at,t.end_at,'[)')
    ) THEN
        RAISE EXCEPTION 'Tournament interval is covered by a Venue Closure';
    END IF;

    IF EXISTS (
        SELECT 1
          FROM tournament.tournament_resource tr
          JOIN resource.resource r ON r.id = tr.resource_id
          LEFT JOIN inventory.resource_reservation rr ON rr.id = tr.reservation_id
         WHERE tr.tournament_id = t.id
           AND tr.removed_at IS NULL
           AND (
               r.venue_id IS DISTINCT FROM t.venue_id
               OR r.activity IS DISTINCT FROM t.activity
               OR r.base_state <> 'ACTIVE'
               OR r.operational_restriction <> 'NONE'
               OR EXISTS (SELECT 1 FROM resource.resource_selling_block rb WHERE rb.resource_id = r.id AND rb.active)
               OR rr.id IS NULL
               OR rr.tournament_id IS DISTINCT FROM t.id
               OR rr.resource_id IS DISTINCT FROM r.id
               OR rr.reservation_type IS DISTINCT FROM p_expected_hold_type
               OR rr.active_flag IS DISTINCT FROM true
               OR rr.planned_start IS DISTINCT FROM t.start_at
               OR rr.planned_end IS DISTINCT FROM t.end_at
           )
    ) THEN
        RAISE EXCEPTION 'One or more assigned Tournament Resources/Holds are not operationally eligible';
    END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.reason_rank(p_reason text)
RETURNS integer
LANGUAGE sql
IMMUTABLE
AS $function$
SELECT CASE p_reason
    WHEN 'RESOURCE_OWNER_REVIEW_REQUIRED' THEN 1
    WHEN 'RESOURCE_EMERGENCY_OUTAGE' THEN 2
    WHEN 'EMERGENCY_CLOSURE' THEN 3
    WHEN 'VENUE_ACCOUNT_DISABLED' THEN 4
    WHEN 'MINIMUM_PARTICIPANTS_NOT_REACHED' THEN 5
    WHEN 'CREATOR_VERIFIED_STATUS_REVOKED' THEN 6
    ELSE 7
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.highest_current_cancellation_reason(
    p_tournament_id uuid,
    p_from_status text,
    p_at timestamptz
)
RETURNS text
LANGUAGE plpgsql
STABLE
AS $function$
DECLARE
    t tournament.tournament%ROWTYPE;
    v_creator_status text;
    v_has_owner_review boolean;
    v_has_resource_emergency boolean;
    v_has_venue_emergency boolean;
    v_remaining integer;
BEGIN
    SELECT * INTO t FROM tournament.tournament WHERE id = p_tournament_id;
    IF NOT FOUND THEN RETURN NULL; END IF;

    SELECT EXISTS (
        SELECT 1
          FROM tournament.tournament_resource tr
          JOIN operations.owner_review o ON o.resource_id = tr.resource_id
         WHERE tr.tournament_id = t.id
           AND o.entered_at <= p_at
           AND (o.resolved_at IS NULL OR o.resolved_at > p_at)
    ) INTO v_has_owner_review;

    SELECT EXISTS (
        SELECT 1
          FROM tournament.tournament_resource tr
          JOIN operations.emergency e ON e.resource_id = tr.resource_id AND e.scope = 'RESOURCE'
         WHERE tr.tournament_id = t.id
           AND e.declared_at <= p_at
           AND (e.ended_at IS NULL OR e.ended_at > p_at)
           AND tstzrange(t.start_at,t.end_at,'[)') && e.declared_period
    ) INTO v_has_resource_emergency;

    SELECT EXISTS (
        SELECT 1 FROM operations.emergency e
         WHERE e.scope = 'VENUE'
           AND e.venue_id = t.venue_id
           AND e.declared_at <= p_at
           AND (e.ended_at IS NULL OR e.ended_at > p_at)
           AND tstzrange(t.start_at,t.end_at,'[)') && e.declared_period
    ) INTO v_has_venue_emergency;

    IF p_from_status = 'ACTIVE' THEN
        SELECT COUNT(*)::integer INTO v_remaining
          FROM tournament.tournament_resource tr
         WHERE tr.tournament_id = t.id
           AND (tr.removed_at IS NULL OR tr.removed_at > p_at)
           AND NOT EXISTS (
               SELECT 1 FROM operations.owner_review o
                WHERE o.resource_id = tr.resource_id
                  AND o.entered_at <= p_at
                  AND (o.resolved_at IS NULL OR o.resolved_at > p_at)
           )
           AND NOT EXISTS (
               SELECT 1 FROM operations.emergency e
                WHERE e.scope = 'RESOURCE'
                  AND e.resource_id = tr.resource_id
                  AND e.declared_at <= p_at
                  AND (e.ended_at IS NULL OR e.ended_at > p_at)
                  AND tstzrange(t.start_at,t.end_at,'[)') && e.declared_period
           );
        IF v_remaining > 0 THEN
            v_has_owner_review := false;
            v_has_resource_emergency := false;
        END IF;
    END IF;

    IF v_has_owner_review THEN RETURN 'RESOURCE_OWNER_REVIEW_REQUIRED'; END IF;
    IF v_has_resource_emergency THEN RETURN 'RESOURCE_EMERGENCY_OUTAGE'; END IF;
    IF v_has_venue_emergency THEN RETURN 'EMERGENCY_CLOSURE'; END IF;

    IF p_from_status = 'PENDING_VENUE_APPROVAL' AND EXISTS (
        SELECT 1 FROM iam.venue_account_restriction_interval r
         WHERE r.venue_id = t.venue_id
           AND r.disabled_at <= p_at
           AND (r.reenabled_at IS NULL OR r.reenabled_at > p_at)
    ) THEN
        RETURN 'VENUE_ACCOUNT_DISABLED';
    END IF;

    IF p_from_status = 'WAITING_FOR_PLAYERS'
       AND p_at >= t.checkpoint_at
       AND tournament.active_participant_count(t.id) < 8 THEN
        RETURN 'MINIMUM_PARTICIPANTS_NOT_REACHED';
    END IF;

    IF p_from_status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS') AND t.creator_user_id IS NOT NULL THEN
        SELECT v.to_status INTO v_creator_status
          FROM trust.verified_player_transition v
         WHERE v.user_id = t.creator_user_id
           AND v.occurred_at <= p_at
         ORDER BY v.occurred_at DESC, v.id DESC
         LIMIT 1;
        IF v_creator_status = 'REVOKED' THEN
            RETURN 'CREATOR_VERIFIED_STATUS_REVOKED';
        END IF;
    END IF;

    RETURN NULL;
END;
$function$;

-- T2. Tournament creation and immutable aggregate facts.
CREATE OR REPLACE FUNCTION tournament.prepare_tournament_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_marketplace text;
    v_account text;
    v_phone_verified boolean;
    v_anonymised_at timestamptz;
    v_vp_status text;
    v_last_terminal timestamptz;
BEGIN
    NEW.created_at := transaction_timestamp();
    NEW.end_at := NEW.start_at + make_interval(mins => NEW.nominal_minutes);
    NEW.checkpoint_at := NEW.start_at - interval '1 hour';
    NEW.version := 0;

    IF NEW.host_type = 'PLAYER' THEN
        NEW.status := 'PENDING_VENUE_APPROVAL';
        NEW.approval_expires_at := LEAST(NEW.created_at + interval '10 minutes', NEW.checkpoint_at);
    ELSIF NEW.host_type = 'VENUE' THEN
        NEW.status := 'WAITING_FOR_PLAYERS';
        NEW.approval_expires_at := NULL;
    END IF;

    SELECT v.marketplace_status INTO v_marketplace
      FROM venue.venue v WHERE v.id = NEW.venue_id FOR UPDATE;
    IF NOT FOUND OR v_marketplace <> 'ACTIVE' THEN
        RAISE EXCEPTION 'New Tournament creation requires Venue Marketplace ACTIVE';
    END IF;

    SELECT va.account_status INTO v_account
      FROM iam.venue_account va WHERE va.venue_id = NEW.venue_id;
    IF v_account IS DISTINCT FROM 'ENABLED' THEN
        RAISE EXCEPTION 'New Tournament creation requires Venue Account ENABLED';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM venue.venue_activity a WHERE a.venue_id = NEW.venue_id AND a.activity = NEW.activity) THEN
        RAISE EXCEPTION 'Tournament activity is not configured for the selected Venue';
    END IF;
    IF EXISTS (SELECT 1 FROM venue.venue_selling_block b WHERE b.venue_id = NEW.venue_id AND b.active) THEN
        RAISE EXCEPTION 'New Tournament creation is blocked by a Venue Operational Selling Block';
    END IF;

    IF NEW.created_at > NEW.start_at - interval '2 hours' THEN
        RAISE EXCEPTION 'Tournament creation cutoff is startAt - 2 hours';
    END IF;

    IF NEW.host_type = 'PLAYER' THEN
        SELECT u.phone_verified, u.anonymised_at
          INTO v_phone_verified, v_anonymised_at
          FROM iam.user_account u
         WHERE u.id = NEW.creator_user_id
         FOR UPDATE;
        IF NOT FOUND OR NOT v_phone_verified OR v_anonymised_at IS NOT NULL THEN
            RAISE EXCEPTION 'Player-hosted Tournament creator must be an Account-Verified active User';
        END IF;
        SELECT p.vp_operational_status INTO v_vp_status
          FROM trust.trust_projection p WHERE p.user_id = NEW.creator_user_id;
        IF v_vp_status IS DISTINCT FROM 'VERIFIED' THEN
            RAISE EXCEPTION 'Only operational VERIFIED may create a Player-hosted Tournament';
        END IF;
        IF EXISTS (
            SELECT 1 FROM trust.ban_instance b
             WHERE b.user_id = NEW.creator_user_id
               AND b.status = 'ACTIVE'
               AND b.activated_at <= NEW.created_at
               AND b.ends_at > NEW.created_at
        ) THEN
            RAISE EXCEPTION 'Banned User may not create a Tournament';
        END IF;

        SELECT MAX(h.occurred_at) INTO v_last_terminal
          FROM tournament.tournament t0
          JOIN tournament.tournament_history h ON h.tournament_id = t0.id
         WHERE t0.host_type = 'PLAYER'
           AND t0.creator_user_id = NEW.creator_user_id
           AND t0.venue_id = NEW.venue_id
           AND t0.start_at = NEW.start_at
           AND t0.end_at = NEW.end_at
           AND ((h.to_status = 'REJECTED' AND h.terminal_reason = 'VENUE_REJECTED_TOURNAMENT')
                OR (h.to_status = 'CANCELLED' AND h.terminal_reason = 'VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME'));
        IF v_last_terminal IS NOT NULL AND NEW.created_at < v_last_terminal + interval '5 minutes' THEN
            RAISE EXCEPTION 'Creator must wait 5 minutes before re-requesting the same Venue/time interval';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_00_prepare_tournament_insert
BEFORE INSERT ON tournament.tournament
FOR EACH ROW EXECUTE FUNCTION tournament.prepare_tournament_insert();

CREATE OR REPLACE FUNCTION tournament.guard_tournament_update()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_count integer;
BEGIN
    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.venue_id IS DISTINCT FROM OLD.venue_id
       OR NEW.host_type IS DISTINCT FROM OLD.host_type
       OR NEW.creator_user_id IS DISTINCT FROM OLD.creator_user_id
       OR NEW.creator_participates IS DISTINCT FROM OLD.creator_participates
       OR NEW.activity IS DISTINCT FROM OLD.activity
       OR NEW.play_mode IS DISTINCT FROM OLD.play_mode
       OR NEW.capacity IS DISTINCT FROM OLD.capacity
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.start_at IS DISTINCT FROM OLD.start_at
       OR NEW.end_at IS DISTINCT FROM OLD.end_at
       OR NEW.nominal_minutes IS DISTINCT FROM OLD.nominal_minutes
       OR NEW.checkpoint_at IS DISTINCT FROM OLD.checkpoint_at
       OR NEW.approval_expires_at IS DISTINCT FROM OLD.approval_expires_at
       OR NEW.visibility IS DISTINCT FROM OLD.visibility
       OR NEW.invite_code IS DISTINCT FROM OLD.invite_code
       OR NEW.venue_cost_total IS DISTINCT FROM OLD.venue_cost_total
       OR NEW.creation_fee_snapshot IS DISTINCT FROM OLD.creation_fee_snapshot
       OR NEW.entry_fee IS DISTINCT FROM OLD.entry_fee
       OR NEW.prize IS DISTINCT FROM OLD.prize
       OR NEW.business_date IS DISTINCT FROM OLD.business_date
       OR NEW.operating_session_id IS DISTINCT FROM OLD.operating_session_id THEN
        RAISE EXCEPTION 'Tournament creation/commercial/session snapshots are immutable';
    END IF;

    IF OLD.status IN ('COMPLETED','REJECTED','CANCELLED') THEN
        RAISE EXCEPTION 'Terminal Tournament state is immutable';
    END IF;
    IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
        RAISE EXCEPTION 'Tournament UPDATE must be a semantic state transition';
    END IF;
    IF NEW.version <> OLD.version + 1 THEN
        RAISE EXCEPTION 'Tournament state transition must increment version exactly once';
    END IF;

    IF OLD.status = 'PENDING_VENUE_APPROVAL' AND NEW.status NOT IN ('WAITING_FOR_PLAYERS','REJECTED','CANCELLED') THEN
        RAISE EXCEPTION 'Invalid Tournament transition % -> %', OLD.status, NEW.status;
    ELSIF OLD.status = 'WAITING_FOR_PLAYERS' AND NEW.status NOT IN ('CONFIRMED','CANCELLED') THEN
        RAISE EXCEPTION 'Invalid Tournament transition % -> %', OLD.status, NEW.status;
    ELSIF OLD.status = 'CONFIRMED' AND NEW.status NOT IN ('ACTIVE','CANCELLED') THEN
        RAISE EXCEPTION 'Invalid Tournament transition % -> %', OLD.status, NEW.status;
    ELSIF OLD.status = 'ACTIVE' AND NEW.status NOT IN ('COMPLETED','CANCELLED') THEN
        RAISE EXCEPTION 'Invalid Tournament transition % -> %', OLD.status, NEW.status;
    END IF;

    IF OLD.status = 'PENDING_VENUE_APPROVAL' AND NEW.status = 'WAITING_FOR_PLAYERS' THEN
        IF transaction_timestamp() >= OLD.approval_expires_at THEN
            RAISE EXCEPTION 'Venue approval deadline is owned by expiry at now >= approvalExpiresAt';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM iam.venue_account va WHERE va.venue_id = OLD.venue_id AND va.account_status = 'ENABLED') THEN
            RAISE EXCEPTION 'Venue Accept requires Venue Account ENABLED';
        END IF;
        PERFORM tournament.assert_resources_operational(OLD.id, 'TOURNAMENT_APPROVAL_HOLD');
    ELSIF OLD.status = 'PENDING_VENUE_APPROVAL' AND NEW.status = 'REJECTED' THEN
        IF transaction_timestamp() >= OLD.approval_expires_at OR NEW.terminal_reason <> 'VENUE_REJECTED_TOURNAMENT' THEN
            RAISE EXCEPTION 'Venue Reject is valid only before approval expiry with VENUE_REJECTED_TOURNAMENT';
        END IF;
    ELSIF OLD.status = 'PENDING_VENUE_APPROVAL' AND NEW.status = 'CANCELLED' THEN
        IF NEW.terminal_reason = 'VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME'
           AND transaction_timestamp() < OLD.approval_expires_at THEN
            RAISE EXCEPTION 'Approval timeout may not win before approvalExpiresAt';
        END IF;
        IF NEW.terminal_reason = 'CREATOR_CANCELLED' AND transaction_timestamp() >= OLD.checkpoint_at THEN
            RAISE EXCEPTION 'Creator may cancel only before the checkpoint';
        END IF;
    ELSIF OLD.status = 'WAITING_FOR_PLAYERS' AND NEW.status = 'CONFIRMED' THEN
        IF transaction_timestamp() < OLD.checkpoint_at THEN
            RAISE EXCEPTION 'Tournament checkpoint may not confirm before checkpointAt';
        END IF;
        v_count := tournament.active_participant_count(OLD.id);
        IF v_count < 8 THEN
            RAISE EXCEPTION 'Tournament cannot confirm with fewer than 8 Active Participants';
        END IF;
        PERFORM tournament.assert_resources_operational(OLD.id, 'TOURNAMENT_HOLD');
    ELSIF OLD.status = 'WAITING_FOR_PLAYERS' AND NEW.status = 'CANCELLED' THEN
        IF NEW.terminal_reason = 'MINIMUM_PARTICIPANTS_NOT_REACHED' THEN
            IF transaction_timestamp() < OLD.checkpoint_at OR tournament.active_participant_count(OLD.id) >= 8 THEN
                RAISE EXCEPTION 'MINIMUM_PARTICIPANTS_NOT_REACHED requires checkpoint ownership and fewer than 8 Active Participants';
            END IF;
        ELSIF NEW.terminal_reason = 'CREATOR_CANCELLED' AND transaction_timestamp() >= OLD.checkpoint_at THEN
            RAISE EXCEPTION 'Creator may cancel only before the checkpoint';
        END IF;
    ELSIF OLD.status = 'CONFIRMED' AND NEW.status = 'ACTIVE' THEN
        IF transaction_timestamp() < OLD.start_at THEN
            RAISE EXCEPTION 'Tournament may not start before startAt';
        END IF;
        PERFORM tournament.assert_resources_operational(OLD.id, 'TOURNAMENT_HOLD');
    ELSIF OLD.status = 'ACTIVE' AND NEW.status = 'COMPLETED' THEN
        IF transaction_timestamp() < OLD.end_at THEN
            RAISE EXCEPTION 'Tournament may not complete before endAt';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_10_guard_tournament_update
BEFORE UPDATE ON tournament.tournament
FOR EACH ROW EXECUTE FUNCTION tournament.guard_tournament_update();

-- T3. Resource assignment / Hold lifecycle.
CREATE OR REPLACE FUNCTION tournament.guard_tournament_resource()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    t tournament.tournament%ROWTYPE;
    r resource.resource%ROWTYPE;
    rr inventory.resource_reservation%ROWTYPE;
    rr_old inventory.resource_reservation%ROWTYPE;
    v_expected_price numeric;
    v_expected_type text;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Tournament Resource assignments are historical and may not be deleted';
    END IF;

    SELECT * INTO t FROM tournament.tournament WHERE id = NEW.tournament_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament does not exist'; END IF;
    SELECT * INTO r FROM resource.resource WHERE id = NEW.resource_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament Resource does not exist'; END IF;

    IF TG_OP = 'INSERT' THEN
        IF t.created_at IS DISTINCT FROM transaction_timestamp() THEN
            RAISE EXCEPTION 'Tournament Resources may be added only in the Tournament creation transaction';
        END IF;
        IF (SELECT COUNT(*) FROM tournament.tournament_resource x WHERE x.tournament_id = t.id) >= 4 THEN
            RAISE EXCEPTION 'Tournament maximum Resource count is 4';
        END IF;
        IF r.venue_id IS DISTINCT FROM t.venue_id OR r.activity IS DISTINCT FROM t.activity THEN
            RAISE EXCEPTION 'Tournament Resource must belong to the same Venue and Activity';
        END IF;
        IF r.base_state <> 'ACTIVE' OR r.operational_restriction <> 'NONE'
           OR EXISTS (SELECT 1 FROM resource.resource_selling_block b WHERE b.resource_id = r.id AND b.active)
           OR EXISTS (SELECT 1 FROM venue.venue_selling_block b WHERE b.venue_id = t.venue_id AND b.active) THEN
            RAISE EXCEPTION 'Tournament Resource is not operationally eligible at creation';
        END IF;
        IF t.activity = 'PLAYSTATION' THEN
            IF NEW.console_type_snapshot IS DISTINCT FROM r.console_type THEN
                RAISE EXCEPTION 'PlayStation Tournament console snapshot must equal Resource console type';
            END IF;
        ELSIF NEW.console_type_snapshot IS NOT NULL THEN
            RAISE EXCEPTION 'Billiards/Ping Pong Tournament Resource console snapshot must be NULL';
        END IF;
        v_expected_price := tournament.expected_resource_price(r.id, t.activity, t.play_mode);
        IF NEW.hourly_price_snapshot IS DISTINCT FROM v_expected_price THEN
            RAISE EXCEPTION 'Tournament Resource hourly price snapshot % does not equal effective creation price %', NEW.hourly_price_snapshot, v_expected_price;
        END IF;
        v_expected_type := CASE WHEN t.status = 'PENDING_VENUE_APPROVAL' THEN 'TOURNAMENT_APPROVAL_HOLD' ELSE 'TOURNAMENT_HOLD' END;
        SELECT * INTO rr FROM inventory.resource_reservation WHERE id = NEW.reservation_id;
        IF NOT FOUND OR rr.tournament_id IS DISTINCT FROM t.id OR rr.resource_id IS DISTINCT FROM r.id
           OR rr.reservation_type IS DISTINCT FROM v_expected_type OR NOT rr.active_flag
           OR rr.planned_start IS DISTINCT FROM t.start_at OR rr.planned_end IS DISTINCT FROM t.end_at THEN
            RAISE EXCEPTION 'Tournament Resource requires a matching active % reservation', v_expected_type;
        END IF;
        NEW.removed_at := NULL;
        NEW.removal_cause := NULL;
        RETURN NEW;
    END IF;

    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.tournament_id IS DISTINCT FROM OLD.tournament_id
       OR NEW.resource_id IS DISTINCT FROM OLD.resource_id
       OR NEW.console_type_snapshot IS DISTINCT FROM OLD.console_type_snapshot
       OR NEW.hourly_price_snapshot IS DISTINCT FROM OLD.hourly_price_snapshot THEN
        RAISE EXCEPTION 'Tournament Resource identity and historical snapshots are immutable';
    END IF;

    IF OLD.reservation_id IS DISTINCT FROM NEW.reservation_id THEN
        SELECT * INTO rr_old FROM inventory.resource_reservation WHERE id = OLD.reservation_id;
        SELECT * INTO rr FROM inventory.resource_reservation WHERE id = NEW.reservation_id;
        IF NOT FOUND OR rr_old.reservation_type <> 'TOURNAMENT_APPROVAL_HOLD'
           OR rr_old.active_flag OR rr.reservation_type <> 'TOURNAMENT_HOLD' OR NOT rr.active_flag
           OR rr_old.tournament_id IS DISTINCT FROM t.id OR rr.tournament_id IS DISTINCT FROM t.id
           OR rr_old.resource_id IS DISTINCT FROM NEW.resource_id OR rr.resource_id IS DISTINCT FROM NEW.resource_id
           OR rr_old.planned_start IS DISTINCT FROM t.start_at OR rr_old.planned_end IS DISTINCT FROM t.end_at
           OR rr.planned_start IS DISTINCT FROM t.start_at OR rr.planned_end IS DISTINCT FROM t.end_at THEN
            RAISE EXCEPTION 'reservation_id may change once only when an Approval Hold is released and replaced by a standard Tournament Hold';
        END IF;
    END IF;

    IF OLD.removed_at IS NOT NULL THEN
        IF NEW.removed_at IS DISTINCT FROM OLD.removed_at OR NEW.removal_cause IS DISTINCT FROM OLD.removal_cause
           OR NEW.reservation_id IS DISTINCT FROM OLD.reservation_id THEN
            RAISE EXCEPTION 'Removed Tournament Resource history is immutable';
        END IF;
    ELSIF NEW.removed_at IS NOT NULL THEN
        IF t.status <> 'ACTIVE' THEN
            RAISE EXCEPTION 'A Tournament Resource may be removed only while the Tournament is ACTIVE';
        END IF;
        NEW.removed_at := transaction_timestamp();
        IF NEW.removal_cause NOT IN ('RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED') THEN
            RAISE EXCEPTION 'ACTIVE Tournament Resource removal requires a canonical operational cause';
        END IF;
    ELSIF NEW.removal_cause IS NOT NULL THEN
        RAISE EXCEPTION 'removal_cause requires removed_at';
    END IF;

    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_guard_tournament_resource
BEFORE INSERT OR UPDATE OR DELETE ON tournament.tournament_resource
FOR EACH ROW EXECUTE FUNCTION tournament.guard_tournament_resource();

-- T4. Participant lifecycle. status_changed_at is current-state metadata; immutable audit_event rows retain every transition.
CREATE OR REPLACE FUNCTION tournament.guard_tournament_participant()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    t tournament.tournament%ROWTYPE;
    u iam.user_account%ROWTYPE;
    v_active integer;
    v_banned boolean;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Tournament Participant history may not be deleted';
    END IF;

    SELECT * INTO t FROM tournament.tournament WHERE id = NEW.tournament_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament does not exist'; END IF;
    SELECT * INTO u FROM iam.user_account WHERE id = NEW.user_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament Participant User does not exist'; END IF;
    SELECT EXISTS (
        SELECT 1 FROM trust.ban_instance b
         WHERE b.user_id = NEW.user_id AND b.status = 'ACTIVE'
           AND b.activated_at <= transaction_timestamp() AND b.ends_at > transaction_timestamp()
    ) INTO v_banned;

    IF TG_OP = 'INSERT' THEN
        NEW.joined_at := transaction_timestamp();
        NEW.status_changed_at := NEW.joined_at;
        NEW.status := 'JOINED';
        NEW.left_at := NULL;
        NEW.removed_at := NULL;
        NEW.ineligible_reason := NULL;

        IF NOT u.phone_verified OR u.anonymised_at IS NOT NULL OR v_banned THEN
            RAISE EXCEPTION 'Tournament join requires an Account-Verified, non-banned active User';
        END IF;
        IF t.status = 'PENDING_VENUE_APPROVAL' THEN
            IF t.host_type <> 'PLAYER' OR NOT t.creator_participates OR NEW.user_id IS DISTINCT FROM t.creator_user_id
               OR t.created_at IS DISTINCT FROM transaction_timestamp() THEN
                RAISE EXCEPTION 'While PENDING_VENUE_APPROVAL only the participating Player Creator may have a Participant row';
            END IF;
        ELSIF t.status NOT IN ('WAITING_FOR_PLAYERS','CONFIRMED') OR transaction_timestamp() >= t.start_at THEN
            RAISE EXCEPTION 'Users may join only WAITING_FOR_PLAYERS/CONFIRMED before startAt';
        END IF;
        v_active := tournament.active_participant_count(t.id);
        IF v_active >= t.capacity THEN
            RAISE EXCEPTION 'Tournament participant capacity is full';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.tournament_id IS DISTINCT FROM OLD.tournament_id
       OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.joined_at IS DISTINCT FROM OLD.joined_at THEN
        RAISE EXCEPTION 'Tournament Participant identity/join timestamp is immutable';
    END IF;
    IF OLD.left_at IS NOT NULL AND NEW.left_at IS DISTINCT FROM OLD.left_at THEN
        RAISE EXCEPTION 'left_at is immutable once recorded';
    END IF;
    IF OLD.removed_at IS NOT NULL AND NEW.removed_at IS DISTINCT FROM OLD.removed_at THEN
        RAISE EXCEPTION 'removed_at is immutable once recorded';
    END IF;
    IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
        IF NEW.status_changed_at IS DISTINCT FROM OLD.status_changed_at
           OR NEW.left_at IS DISTINCT FROM OLD.left_at OR NEW.removed_at IS DISTINCT FROM OLD.removed_at
           OR NEW.ineligible_reason IS DISTINCT FROM OLD.ineligible_reason THEN
            RAISE EXCEPTION 'Participant lifecycle facts change only with a status transition';
        END IF;
        RETURN NEW;
    END IF;
    IF t.status IN ('COMPLETED','REJECTED','CANCELLED') THEN
        RAISE EXCEPTION 'Participant state cannot change after Tournament terminal state';
    END IF;

    NEW.status_changed_at := transaction_timestamp();
    IF NEW.status = 'JOINED' THEN
        IF t.status NOT IN ('WAITING_FOR_PLAYERS','CONFIRMED') OR transaction_timestamp() >= t.start_at THEN
            RAISE EXCEPTION 'Participant may return/join only before startAt while Tournament accepts participants';
        END IF;
        IF NOT u.phone_verified OR u.anonymised_at IS NOT NULL OR v_banned THEN
            RAISE EXCEPTION 'JOINED participant must be Account-Verified, active and not banned';
        END IF;
        NEW.ineligible_reason := NULL;
        v_active := tournament.active_participant_count(t.id);
        IF OLD.status <> 'JOINED' AND v_active >= t.capacity THEN
            RAISE EXCEPTION 'Tournament participant capacity is full';
        END IF;
    ELSIF NEW.status = 'LEFT' THEN
        IF transaction_timestamp() >= t.start_at THEN
            RAISE EXCEPTION 'Participant may Leave only before startAt';
        END IF;
        IF NEW.left_at IS NULL THEN NEW.left_at := NEW.status_changed_at; END IF;
    ELSIF NEW.status = 'REMOVED' THEN
        IF transaction_timestamp() >= t.start_at THEN
            RAISE EXCEPTION 'Organizer may Remove a Participant only before startAt';
        END IF;
        IF NEW.removed_at IS NULL THEN NEW.removed_at := NEW.status_changed_at; END IF;
    ELSIF NEW.status = 'INELIGIBLE' THEN
        IF v_banned THEN
            NEW.ineligible_reason := 'BAN';
        ELSIF u.anonymised_at IS NOT NULL THEN
            NEW.ineligible_reason := 'ACCOUNT_DELETED';
        ELSIF NULLIF(BTRIM(NEW.ineligible_reason),'') IS NULL THEN
            RAISE EXCEPTION 'INELIGIBLE requires an explicit reason';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_guard_tournament_participant
BEFORE INSERT OR UPDATE OR DELETE ON tournament.tournament_participant
FOR EACH ROW EXECUTE FUNCTION tournament.guard_tournament_participant();

CREATE OR REPLACE FUNCTION tournament.assert_participant_audit()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    t tournament.tournament%ROWTYPE;
    v_action text;
BEGIN
    SELECT * INTO t FROM tournament.tournament WHERE id = NEW.tournament_id;
    IF TG_OP = 'INSERT' THEN
        v_action := 'TOURNAMENT_PARTICIPANT_JOINED';
    ELSIF NEW.status IS NOT DISTINCT FROM OLD.status THEN
        RETURN NULL;
    ELSIF NEW.status = 'JOINED' AND OLD.status = 'INELIGIBLE' THEN
        v_action := 'TOURNAMENT_PARTICIPANT_RESTORED';
    ELSIF NEW.status = 'JOINED' THEN
        v_action := 'TOURNAMENT_PARTICIPANT_JOINED';
    ELSIF NEW.status = 'LEFT' THEN
        v_action := 'TOURNAMENT_PARTICIPANT_LEFT';
    ELSIF NEW.status = 'REMOVED' THEN
        v_action := 'TOURNAMENT_PARTICIPANT_REMOVED';
    ELSE
        v_action := 'TOURNAMENT_PARTICIPANT_INELIGIBLE';
    END IF;

    IF v_action IN ('TOURNAMENT_PARTICIPANT_JOINED','TOURNAMENT_PARTICIPANT_LEFT') THEN
        IF NOT EXISTS (
            SELECT 1 FROM audit.audit_event a
             WHERE a.subject_type = 'TOURNAMENT_PARTICIPANT' AND a.subject_id = NEW.id
               AND a.action = v_action AND a.actor_type = 'CUSTOMER' AND a.actor_id = NEW.user_id
               AND a.occurred_at = NEW.status_changed_at
        ) THEN
            RAISE EXCEPTION '% requires matching Customer audit evidence', v_action;
        END IF;
    ELSIF v_action = 'TOURNAMENT_PARTICIPANT_REMOVED' THEN
        IF t.host_type = 'PLAYER' THEN
            IF NOT EXISTS (
                SELECT 1 FROM audit.audit_event a
                 WHERE a.subject_type='TOURNAMENT_PARTICIPANT' AND a.subject_id=NEW.id
                   AND a.action=v_action AND a.actor_type='CUSTOMER' AND a.actor_id=t.creator_user_id
                   AND a.occurred_at=NEW.status_changed_at
            ) THEN RAISE EXCEPTION 'Player-hosted participant removal requires Creator audit evidence'; END IF;
        ELSE
            IF NOT EXISTS (
                SELECT 1 FROM audit.audit_event a
                JOIN iam.venue_account va ON va.id=a.actor_id AND va.venue_id=t.venue_id
                 WHERE a.subject_type='TOURNAMENT_PARTICIPANT' AND a.subject_id=NEW.id
                   AND a.action=v_action AND a.actor_type='VENUE' AND a.occurred_at=NEW.status_changed_at
            ) THEN RAISE EXCEPTION 'Venue-hosted participant removal requires Venue audit evidence'; END IF;
        END IF;
    ELSE
        IF NOT EXISTS (
            SELECT 1 FROM audit.audit_event a
             WHERE a.subject_type='TOURNAMENT_PARTICIPANT' AND a.subject_id=NEW.id
               AND a.action=v_action AND a.actor_type='SYSTEM' AND a.actor_id IS NULL
               AND a.occurred_at=NEW.status_changed_at
        ) THEN
            RAISE EXCEPTION '% requires matching System audit evidence', v_action;
        END IF;
    END IF;
    RETURN NULL;
END;
$function$;

CREATE CONSTRAINT TRIGGER tr_tournament_participant_audit
AFTER INSERT OR UPDATE ON tournament.tournament_participant
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION tournament.assert_participant_audit();

-- T5. State history is DB-sequenced and append-only; final chain/actor/audit rules are deferred.
CREATE OR REPLACE FUNCTION tournament.prepare_tournament_history()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    t tournament.tournament%ROWTYPE;
    v_seq bigint;
    v_prev_status text;
BEGIN
    SELECT * INTO t FROM tournament.tournament WHERE id = NEW.tournament_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament history requires an existing Tournament'; END IF;

    SELECT h.sequence, h.to_status INTO v_seq, v_prev_status
      FROM tournament.tournament_history h
     WHERE h.tournament_id = NEW.tournament_id
     ORDER BY h.sequence DESC LIMIT 1;

    IF v_seq IS NULL THEN
        NEW.sequence := 1;
        NEW.from_status := NULL;
        NEW.occurred_at := t.created_at;
    ELSE
        NEW.sequence := v_seq + 1;
        NEW.from_status := v_prev_status;
        NEW.occurred_at := transaction_timestamp();
    END IF;
    IF NEW.to_status IS NULL THEN RAISE EXCEPTION 'Tournament history to_status is required'; END IF;
    RETURN NEW;
END;
$function$;

CREATE TRIGGER tr_prepare_tournament_history
BEFORE INSERT ON tournament.tournament_history
FOR EACH ROW EXECUTE FUNCTION tournament.prepare_tournament_history();

CREATE OR REPLACE FUNCTION tournament.assert_tournament_history_chain(p_tournament_id uuid)
RETURNS void
LANGUAGE plpgsql
AS $function$
DECLARE
    t tournament.tournament%ROWTYPE;
    h record;
    a audit.audit_event%ROWTYPE;
    v_prev text := NULL;
    v_expected text;
    v_first boolean := true;
BEGIN
    SELECT * INTO t FROM tournament.tournament WHERE id = p_tournament_id;
    IF NOT FOUND THEN RETURN; END IF;

    FOR h IN SELECT * FROM tournament.tournament_history WHERE tournament_id=t.id ORDER BY sequence LOOP
        IF v_first THEN
            IF h.sequence <> 1 OR h.from_status IS NOT NULL OR h.occurred_at IS DISTINCT FROM t.created_at THEN
                RAISE EXCEPTION 'Tournament first history row must be sequence 1, from_status NULL and occur at created_at';
            END IF;
            IF (t.host_type='PLAYER' AND h.to_status <> 'PENDING_VENUE_APPROVAL')
               OR (t.host_type='VENUE' AND h.to_status <> 'WAITING_FOR_PLAYERS') THEN
                RAISE EXCEPTION 'Tournament first history state does not match host type';
            END IF;
            v_first := false;
        ELSE
            IF h.from_status IS DISTINCT FROM v_prev THEN
                RAISE EXCEPTION 'Tournament history chain is not contiguous at sequence %', h.sequence;
            END IF;
        END IF;

        SELECT * INTO a FROM audit.audit_event ae
         WHERE ae.subject_type='TOURNAMENT' AND ae.subject_id=t.id
           AND ae.action='TOURNAMENT_STATUS_TRANSITION'
           AND ae.occurred_at=h.occurred_at
           AND ae.actor_type=h.actor_type
           AND ae.actor_id IS NOT DISTINCT FROM h.actor_id
           AND ae.correlation_id=h.correlation_id
         LIMIT 1;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Tournament history sequence % requires matching audit_event', h.sequence;
        END IF;

        IF h.actor_type='CUSTOMER' AND h.actor_id IS DISTINCT FROM t.creator_user_id THEN
            RAISE EXCEPTION 'Tournament CUSTOMER state actor must be the Player Creator';
        ELSIF h.actor_type='VENUE' AND NOT EXISTS (
            SELECT 1 FROM iam.venue_account va WHERE va.id=h.actor_id AND va.venue_id=t.venue_id
        ) THEN
            RAISE EXCEPTION 'Tournament VENUE actor must belong to the Tournament Venue';
        ELSIF h.actor_type='ADMIN' AND NOT EXISTS (SELECT 1 FROM iam.admin_account ad WHERE ad.id=h.actor_id) THEN
            RAISE EXCEPTION 'Tournament ADMIN actor does not exist';
        END IF;

        IF h.from_status IS NULL THEN
            IF t.host_type='PLAYER' AND (h.actor_type<>'CUSTOMER' OR h.actor_id IS DISTINCT FROM t.creator_user_id) THEN
                RAISE EXCEPTION 'Player-hosted Tournament creation history requires Creator actor';
            ELSIF t.host_type='VENUE' AND h.actor_type<>'VENUE' THEN
                RAISE EXCEPTION 'Venue-hosted Tournament creation history requires Venue actor';
            END IF;
        ELSIF h.from_status='PENDING_VENUE_APPROVAL' AND h.to_status='WAITING_FOR_PLAYERS' THEN
            IF h.actor_type<>'VENUE' OR h.terminal_reason IS NOT NULL OR h.occurred_at >= t.approval_expires_at THEN
                RAISE EXCEPTION 'Venue Accept transition is invalid';
            END IF;
        ELSIF h.from_status='PENDING_VENUE_APPROVAL' AND h.to_status='REJECTED' THEN
            IF h.actor_type<>'VENUE' OR h.terminal_reason<>'VENUE_REJECTED_TOURNAMENT' OR h.occurred_at >= t.approval_expires_at THEN
                RAISE EXCEPTION 'Venue Reject transition is invalid';
            END IF;
        ELSIF h.from_status='PENDING_VENUE_APPROVAL' AND h.to_status='CANCELLED' THEN
            IF h.terminal_reason='VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME' THEN
                IF h.actor_type<>'SYSTEM' OR h.occurred_at < t.approval_expires_at THEN RAISE EXCEPTION 'Approval-expiry transition is invalid'; END IF;
            ELSIF h.terminal_reason='CREATOR_CANCELLED' THEN
                IF h.actor_type<>'CUSTOMER' OR h.occurred_at >= t.checkpoint_at THEN RAISE EXCEPTION 'Creator cancellation is invalid'; END IF;
            ELSIF h.terminal_reason IN ('VENUE_ACCOUNT_DISABLED','CREATOR_VERIFIED_STATUS_REVOKED','EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED') THEN
                IF h.actor_type<>'SYSTEM' THEN RAISE EXCEPTION 'System Tournament cascade requires SYSTEM actor'; END IF;
            ELSIF h.terminal_reason='ADMIN_CANCELLED' THEN
                IF h.actor_type<>'ADMIN' THEN RAISE EXCEPTION 'Admin cancellation requires ADMIN actor'; END IF;
            ELSE RAISE EXCEPTION 'Invalid PENDING Tournament cancellation reason %', h.terminal_reason; END IF;
        ELSIF h.from_status='WAITING_FOR_PLAYERS' AND h.to_status='CONFIRMED' THEN
            IF h.actor_type<>'SYSTEM' OR h.terminal_reason IS NOT NULL OR h.occurred_at < t.checkpoint_at THEN
                RAISE EXCEPTION 'Tournament checkpoint confirmation transition is invalid';
            END IF;
        ELSIF h.from_status='WAITING_FOR_PLAYERS' AND h.to_status='CANCELLED' THEN
            IF h.terminal_reason='MINIMUM_PARTICIPANTS_NOT_REACHED' THEN
                IF h.actor_type<>'SYSTEM' OR h.occurred_at < t.checkpoint_at THEN RAISE EXCEPTION 'Minimum-participant cancellation is invalid'; END IF;
            ELSIF h.terminal_reason='CREATOR_CANCELLED' THEN
                IF h.actor_type<>'CUSTOMER' OR h.occurred_at >= t.checkpoint_at THEN RAISE EXCEPTION 'Creator cancellation is invalid'; END IF;
            ELSIF h.terminal_reason='VENUE_CANCELLED' THEN
                IF h.actor_type<>'VENUE' THEN RAISE EXCEPTION 'Venue cancellation requires VENUE actor'; END IF;
            ELSIF h.terminal_reason IN ('CREATOR_VERIFIED_STATUS_REVOKED','EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED') THEN
                IF h.actor_type<>'SYSTEM' THEN RAISE EXCEPTION 'System Tournament cascade requires SYSTEM actor'; END IF;
            ELSIF h.terminal_reason='ADMIN_CANCELLED' THEN
                IF h.actor_type<>'ADMIN' THEN RAISE EXCEPTION 'Admin cancellation requires ADMIN actor'; END IF;
            ELSE RAISE EXCEPTION 'Invalid WAITING Tournament cancellation reason %', h.terminal_reason; END IF;
        ELSIF h.from_status='CONFIRMED' AND h.to_status='ACTIVE' THEN
            IF h.actor_type<>'SYSTEM' OR h.terminal_reason IS NOT NULL OR h.occurred_at < t.start_at THEN
                RAISE EXCEPTION 'Tournament start transition is invalid';
            END IF;
        ELSIF h.from_status='CONFIRMED' AND h.to_status='CANCELLED' THEN
            IF h.terminal_reason='VENUE_CANCELLED' THEN
                IF h.actor_type<>'VENUE' OR NOT a.owner_password_used OR a.owner_password_outcome<>'SUCCESS' THEN
                    RAISE EXCEPTION 'Venue cancellation of CONFIRMED Tournament requires successful Owner Password audit';
                END IF;
            ELSIF h.terminal_reason IN ('EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED') THEN
                IF h.actor_type<>'SYSTEM' THEN RAISE EXCEPTION 'Operational cancellation requires SYSTEM actor'; END IF;
            ELSIF h.terminal_reason='ADMIN_CANCELLED' THEN
                IF h.actor_type<>'ADMIN' THEN RAISE EXCEPTION 'Admin cancellation requires ADMIN actor'; END IF;
            ELSE RAISE EXCEPTION 'Invalid CONFIRMED Tournament cancellation reason %', h.terminal_reason; END IF;
        ELSIF h.from_status='ACTIVE' AND h.to_status='COMPLETED' THEN
            IF h.actor_type<>'SYSTEM' OR h.terminal_reason IS NOT NULL OR h.occurred_at < t.end_at THEN
                RAISE EXCEPTION 'Tournament completion transition is invalid';
            END IF;
        ELSIF h.from_status='ACTIVE' AND h.to_status='CANCELLED' THEN
            IF h.terminal_reason IN ('EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED') THEN
                IF h.actor_type<>'SYSTEM' THEN RAISE EXCEPTION 'Operational ACTIVE cancellation requires SYSTEM actor'; END IF;
            ELSIF h.terminal_reason='TOURNAMENT_OPERATIONAL_TERMINATION' THEN
                IF h.actor_type<>'VENUE' OR NOT a.owner_password_used OR a.owner_password_outcome<>'SUCCESS'
                   OR NULLIF(BTRIM(a.reason),'') IS NULL THEN
                    RAISE EXCEPTION 'Tournament Operational Termination requires Venue actor, Owner Password and mandatory reason';
                END IF;
            ELSIF h.terminal_reason='ADMIN_CANCELLED' THEN
                IF h.actor_type<>'ADMIN' THEN RAISE EXCEPTION 'ACTIVE Admin support cancellation requires ADMIN actor'; END IF;
            ELSE RAISE EXCEPTION 'Invalid ACTIVE Tournament cancellation reason %', h.terminal_reason; END IF;
        ELSE
            RAISE EXCEPTION 'Invalid Tournament state transition % -> %', h.from_status, h.to_status;
        END IF;

        IF h.to_status='CANCELLED' THEN
            v_expected := tournament.highest_current_cancellation_reason(t.id,h.from_status,h.occurred_at);
            IF v_expected IS NOT NULL AND h.terminal_reason IS DISTINCT FROM v_expected THEN
                RAISE EXCEPTION 'Tournament terminal reason % violates frozen priority; expected %', h.terminal_reason, v_expected;
            END IF;
        END IF;
        v_prev := h.to_status;
    END LOOP;

    IF v_first THEN RAISE EXCEPTION 'Tournament requires append-only state history'; END IF;
    IF v_prev IS DISTINCT FROM t.status THEN RAISE EXCEPTION 'Tournament current status does not match latest history state'; END IF;
    SELECT h.terminal_reason INTO v_expected FROM tournament.tournament_history h
     WHERE h.tournament_id=t.id ORDER BY h.sequence DESC LIMIT 1;
    IF v_expected IS DISTINCT FROM t.terminal_reason THEN
        RAISE EXCEPTION 'Tournament terminal_reason does not match latest history transition';
    END IF;
END;
$function$;

-- T6. Aggregate final-state invariants: session, 1–4 Resources, cost snapshot, Holds and creator participation.
CREATE OR REPLACE FUNCTION tournament.assert_tournament_aggregate(p_tournament_id uuid)
RETURNS void
LANGUAGE plpgsql
AS $function$
DECLARE
    t tournament.tournament%ROWTYPE;
    s venue.operating_session%ROWTYPE;
    v_resources integer;
    v_unremoved integer;
    v_expected_cost numeric(12,2);
BEGIN
    SELECT * INTO t FROM tournament.tournament WHERE id=p_tournament_id;
    IF NOT FOUND THEN RETURN; END IF;

    SELECT * INTO s FROM venue.operating_session WHERE id=t.operating_session_id;
    IF NOT FOUND OR s.venue_id IS DISTINCT FROM t.venue_id
       OR t.start_at < lower(s.session_period) OR t.end_at > upper(s.session_period)
       OR t.business_date IS DISTINCT FROM s.operating_day THEN
        RAISE EXCEPTION 'Tournament must fit completely inside one matching Venue Operating Session and businessDate';
    END IF;

    SELECT COUNT(*)::integer,
           COALESCE(SUM(ROUND(tr.hourly_price_snapshot * t.nominal_minutes / 60.0,2)),0)::numeric(12,2)
      INTO v_resources, v_expected_cost
      FROM tournament.tournament_resource tr WHERE tr.tournament_id=t.id;
    IF v_resources NOT BETWEEN 1 AND 4 THEN RAISE EXCEPTION 'Tournament requires exactly 1 to 4 Resource rows'; END IF;
    IF t.venue_cost_total IS DISTINCT FROM v_expected_cost THEN
        RAISE EXCEPTION 'Tournament venue_cost_total % does not equal immutable Resource snapshot total %', t.venue_cost_total, v_expected_cost;
    END IF;

    IF t.host_type='PLAYER' AND t.creator_participates AND NOT EXISTS (
        SELECT 1 FROM tournament.tournament_participant p WHERE p.tournament_id=t.id AND p.user_id=t.creator_user_id
    ) THEN
        RAISE EXCEPTION 'Participating Player Creator requires a retained Participant row';
    END IF;

    IF t.status='PENDING_VENUE_APPROVAL' THEN
        IF EXISTS (SELECT 1 FROM tournament.tournament_resource tr WHERE tr.tournament_id=t.id AND tr.removed_at IS NOT NULL) THEN
            RAISE EXCEPTION 'Pre-approval Tournament cannot contain removed Resources';
        END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_resource tr
            LEFT JOIN inventory.resource_reservation rr ON rr.id=tr.reservation_id
            WHERE tr.tournament_id=t.id AND (rr.id IS NULL OR rr.reservation_type<>'TOURNAMENT_APPROVAL_HOLD' OR NOT rr.active_flag
                OR rr.tournament_id IS DISTINCT FROM t.id OR rr.resource_id IS DISTINCT FROM tr.resource_id
                OR rr.planned_start IS DISTINCT FROM t.start_at OR rr.planned_end IS DISTINCT FROM t.end_at)
        ) THEN RAISE EXCEPTION 'PENDING_VENUE_APPROVAL requires active Approval Holds for every Resource'; END IF;
    ELSIF t.status IN ('WAITING_FOR_PLAYERS','CONFIRMED') THEN
        IF EXISTS (SELECT 1 FROM tournament.tournament_resource tr WHERE tr.tournament_id=t.id AND tr.removed_at IS NOT NULL) THEN
            RAISE EXCEPTION 'Pre-start Tournament cannot contain removed Resources';
        END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_resource tr
            LEFT JOIN inventory.resource_reservation rr ON rr.id=tr.reservation_id
            WHERE tr.tournament_id=t.id AND (rr.id IS NULL OR rr.reservation_type<>'TOURNAMENT_HOLD' OR NOT rr.active_flag
                OR rr.tournament_id IS DISTINCT FROM t.id OR rr.resource_id IS DISTINCT FROM tr.resource_id
                OR rr.planned_start IS DISTINCT FROM t.start_at OR rr.planned_end IS DISTINCT FROM t.end_at)
        ) THEN RAISE EXCEPTION 'WAITING/CONFIRMED Tournament requires active standard Holds for every Resource'; END IF;
    ELSIF t.status='ACTIVE' THEN
        SELECT COUNT(*)::integer INTO v_unremoved FROM tournament.tournament_resource tr WHERE tr.tournament_id=t.id AND tr.removed_at IS NULL;
        IF v_unremoved < 1 THEN RAISE EXCEPTION 'ACTIVE Tournament requires at least one remaining Resource'; END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_resource tr
            LEFT JOIN inventory.resource_reservation rr ON rr.id=tr.reservation_id
            WHERE tr.tournament_id=t.id AND tr.removed_at IS NULL
              AND (rr.id IS NULL OR rr.reservation_type<>'TOURNAMENT_HOLD' OR NOT rr.active_flag
                   OR rr.tournament_id IS DISTINCT FROM t.id OR rr.resource_id IS DISTINCT FROM tr.resource_id)
        ) THEN RAISE EXCEPTION 'ACTIVE Tournament requires an active standard Hold for each remaining Resource'; END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_resource tr
            JOIN inventory.resource_reservation rr ON rr.id=tr.reservation_id
            WHERE tr.tournament_id=t.id AND tr.removed_at IS NOT NULL
              AND (rr.active_flag OR rr.actual_reservation_release_at IS DISTINCT FROM tr.removed_at)
        ) THEN RAISE EXCEPTION 'Removed ACTIVE Tournament Resource requires its Hold released at removed_at'; END IF;
    ELSE
        IF EXISTS (SELECT 1 FROM inventory.resource_reservation rr WHERE rr.tournament_id=t.id AND rr.active_flag) THEN
            RAISE EXCEPTION 'Terminal Tournament may not retain active Resource Holds';
        END IF;
    END IF;

    IF t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE') THEN
        IF NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_CHECKPOINT' AND j.due_at=t.checkpoint_at)
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_START' AND j.due_at=t.start_at)
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_END' AND j.due_at=t.end_at) THEN
            RAISE EXCEPTION 'Live Tournament requires durable checkpoint/start/end scheduled jobs';
        END IF;
        IF t.host_type='PLAYER' AND t.status='PENDING_VENUE_APPROVAL' AND NOT EXISTS (
            SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_APPROVAL_EXPIRY' AND j.due_at=t.approval_expires_at
        ) THEN
            RAISE EXCEPTION 'PENDING Player-hosted Tournament requires durable approval-expiry job';
        END IF;
    END IF;

    PERFORM tournament.assert_tournament_history_chain(t.id);
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.assert_tournament_from_row()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    PERFORM tournament.assert_tournament_aggregate(CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END);
    RETURN NULL;
END;
$function$;

CREATE CONSTRAINT TRIGGER tr_tournament_final_state
AFTER INSERT OR UPDATE ON tournament.tournament
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION tournament.assert_tournament_from_row();

CREATE OR REPLACE FUNCTION tournament.assert_tournament_from_resource_row()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    PERFORM tournament.assert_tournament_aggregate(CASE WHEN TG_OP='DELETE' THEN OLD.tournament_id ELSE NEW.tournament_id END);
    RETURN NULL;
END;
$function$;
CREATE CONSTRAINT TRIGGER tr_tournament_resource_final_state
AFTER INSERT OR UPDATE OR DELETE ON tournament.tournament_resource
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION tournament.assert_tournament_from_resource_row();

CREATE OR REPLACE FUNCTION tournament.assert_tournament_from_participant_row()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    PERFORM tournament.assert_tournament_aggregate(CASE WHEN TG_OP='DELETE' THEN OLD.tournament_id ELSE NEW.tournament_id END);
    RETURN NULL;
END;
$function$;
CREATE CONSTRAINT TRIGGER tr_tournament_participant_final_state
AFTER INSERT OR UPDATE OR DELETE ON tournament.tournament_participant
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION tournament.assert_tournament_from_participant_row();

CREATE OR REPLACE FUNCTION tournament.assert_tournament_from_history_row()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    PERFORM tournament.assert_tournament_aggregate(CASE WHEN TG_OP='DELETE' THEN OLD.tournament_id ELSE NEW.tournament_id END);
    RETURN NULL;
END;
$function$;
CREATE CONSTRAINT TRIGGER tr_tournament_history_final_state
AFTER INSERT OR UPDATE OR DELETE ON tournament.tournament_history
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION tournament.assert_tournament_from_history_row();

CREATE OR REPLACE FUNCTION tournament.assert_tournament_from_reservation_row()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE v_tournament_id uuid;
BEGIN
    v_tournament_id := CASE WHEN TG_OP='DELETE' THEN OLD.tournament_id ELSE NEW.tournament_id END;
    IF v_tournament_id IS NOT NULL THEN PERFORM tournament.assert_tournament_aggregate(v_tournament_id); END IF;
    RETURN NULL;
END;
$function$;
CREATE CONSTRAINT TRIGGER tr_tournament_reservation_final_state
AFTER INSERT OR UPDATE OR DELETE ON inventory.resource_reservation
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION tournament.assert_tournament_from_reservation_row();

-- T7. Venue Account Disable during PENDING approval resolves immediately; later states are not cancelled by access disable alone.
CREATE OR REPLACE FUNCTION tournament.assert_account_disable_tournament_cascade()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE v_venue uuid;
BEGIN
    IF TG_TABLE_SCHEMA='iam' AND TG_TABLE_NAME='venue_account' THEN
        IF NEW.account_status <> 'DISABLED' THEN RETURN NULL; END IF;
        v_venue := NEW.venue_id;
    ELSE
        v_venue := NEW.venue_id;
    END IF;
    IF EXISTS (
        SELECT 1 FROM tournament.tournament t
         WHERE t.venue_id=v_venue AND t.status='PENDING_VENUE_APPROVAL'
    ) THEN
        RAISE EXCEPTION 'Venue Account Disable must resolve all PENDING_VENUE_APPROVAL Tournaments in the same transaction';
    END IF;
    RETURN NULL;
END;
$function$;

CREATE CONSTRAINT TRIGGER tr_tournament_account_disable_from_interval
AFTER INSERT ON iam.venue_account_restriction_interval
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION tournament.assert_account_disable_tournament_cascade();

CREATE CONSTRAINT TRIGGER tr_tournament_account_disable_from_account
AFTER UPDATE OF account_status ON iam.venue_account
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION tournament.assert_account_disable_tournament_cascade();

-- T8. Verified Player VERIFIED->REVOKED cascade is once per verifiedPlayerTransitionId.
CREATE OR REPLACE FUNCTION tournament.assert_verified_player_tournament_cascade()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE c trust.cascade_execution%ROWTYPE;
BEGIN
    IF NEW.from_status IS DISTINCT FROM 'VERIFIED' OR NEW.to_status IS DISTINCT FROM 'REVOKED' THEN RETURN NULL; END IF;
    IF EXISTS (
        SELECT 1 FROM tournament.tournament t
         WHERE t.host_type='PLAYER' AND t.creator_user_id=NEW.user_id
           AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS')
    ) THEN
        RAISE EXCEPTION 'Verified Player revocation must cancel pending/waiting Player-hosted Tournaments in the same transaction';
    END IF;
    SELECT * INTO c FROM trust.cascade_execution ce
     WHERE ce.cascade_type='VERIFIED_PLAYER' AND ce.source_id=NEW.id;
    IF NOT FOUND OR c.subject_user_id IS DISTINCT FROM NEW.user_id OR NEW.cascade_executed_at IS NULL
       OR c.executed_at IS DISTINCT FROM NEW.cascade_executed_at THEN
        RAISE EXCEPTION 'Verified Player revocation requires one matching cascade_execution and cascade_executed_at';
    END IF;
    RETURN NULL;
END;
$function$;

CREATE CONSTRAINT TRIGGER tr_verified_player_tournament_cascade
AFTER INSERT OR UPDATE ON trust.verified_player_transition
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION tournament.assert_verified_player_tournament_cascade();

-- T9. Ban/deletion participant consequences: status must be INELIGIBLE while the Tournament is non-terminal.
CREATE OR REPLACE FUNCTION tournament.assert_ban_participant_cascade()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.status='ACTIVE' AND NEW.ends_at > transaction_timestamp() THEN
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_participant p
            JOIN tournament.tournament t ON t.id=p.tournament_id
            WHERE p.user_id=NEW.user_id
              AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE')
              AND p.status='JOINED'
        ) THEN
            RAISE EXCEPTION 'Active Ban must mark Tournament participation INELIGIBLE in the same transaction';
        END IF;
    END IF;
    RETURN NULL;
END;
$function$;
CREATE CONSTRAINT TRIGGER tr_ban_tournament_participant_cascade
AFTER INSERT OR UPDATE OF status, ends_at ON trust.ban_instance
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION tournament.assert_ban_participant_cascade();

CREATE OR REPLACE FUNCTION tournament.assert_deleted_user_participant_cascade()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.anonymised_at IS NOT NULL AND OLD.anonymised_at IS NULL AND EXISTS (
        SELECT 1 FROM tournament.tournament_participant p
        JOIN tournament.tournament t ON t.id=p.tournament_id
        WHERE p.user_id=NEW.id
          AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE')
          AND p.status='JOINED'
    ) THEN
        RAISE EXCEPTION 'Deleted/anonymised User must be removed from active Tournament participant count in the same transaction';
    END IF;
    RETURN NULL;
END;
$function$;
CREATE CONSTRAINT TRIGGER tr_deleted_user_tournament_participant_cascade
AFTER UPDATE OF anonymised_at ON iam.user_account
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION tournament.assert_deleted_user_participant_cascade();

-- T10. Delivery contract not representable as a pure CHECK:
-- * Private invite access is validated by the Join command before the participant INSERT.
-- * Creation/accept/checkpoint/start/cancellation use creator -> Venue -> Resources(sorted UUID) -> Tournament locks.
-- * Tournament + Holds + history + durable scheduled jobs + audit/outbox commit atomically.
-- * Marketplace ACTIVE is required only for new creation; checkpoint/start use Existing-Commitment Operational eligibility.
-- * Resource loss before start cancels the whole Tournament; ACTIVE resource loss removes only failed Resources while >=1 remains.
-- These are launch contracts in this v1.1.11 baseline, not deferred Product work.



-- ============================================================================
-- E7GZ PS v1.1.12 TOURNAMENT ACCEPTANCE FIXES
-- PostgreSQL 15+. Apply after v1.1.11.
-- Product-visible Tournament states/reasons are unchanged.
-- ============================================================================

-- A1. Canonical deadline ownership for Tournament state transitions.
CREATE OR REPLACE FUNCTION tournament.guard_tournament_due_boundary()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    IF OLD.status='PENDING_VENUE_APPROVAL' AND transaction_timestamp() >= OLD.approval_expires_at
       AND NEW.terminal_reason IN ('CREATOR_CANCELLED','VENUE_CANCELLED','ADMIN_CANCELLED') THEN
        RAISE EXCEPTION 'Tournament approval expiry is due; resolve the deadline before actor cancellation';
    END IF;
    IF OLD.status='WAITING_FOR_PLAYERS' AND transaction_timestamp() >= OLD.checkpoint_at
       AND NEW.terminal_reason IN ('CREATOR_CANCELLED','VENUE_CANCELLED','ADMIN_CANCELLED') THEN
        RAISE EXCEPTION 'Tournament checkpoint is due; resolve the checkpoint before actor cancellation';
    END IF;
    IF OLD.status='CONFIRMED' AND transaction_timestamp() >= OLD.start_at
       AND NEW.status='CANCELLED'
       AND NEW.terminal_reason IN ('VENUE_CANCELLED','ADMIN_CANCELLED') THEN
        RAISE EXCEPTION 'Tournament start is due; resolve startAt before actor cancellation';
    END IF;
    IF OLD.status='ACTIVE' AND transaction_timestamp() >= OLD.end_at AND NEW.status <> 'COMPLETED' THEN
        RAISE EXCEPTION 'Tournament completion boundary owns the state at now >= endAt';
    END IF;
    RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_00_tournament_due_boundary ON tournament.tournament;
CREATE TRIGGER tr_00_tournament_due_boundary
BEFORE UPDATE ON tournament.tournament
FOR EACH ROW EXECUTE FUNCTION tournament.guard_tournament_due_boundary();

-- A2. Participant mutations cannot change an overdue checkpoint/start result.
CREATE OR REPLACE FUNCTION tournament.guard_tournament_participant()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    t tournament.tournament%ROWTYPE;
    u iam.user_account%ROWTYPE;
    v_active integer;
    v_banned boolean;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Tournament Participant history may not be deleted';
    END IF;

    SELECT * INTO t FROM tournament.tournament WHERE id = NEW.tournament_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament does not exist'; END IF;
    SELECT * INTO u FROM iam.user_account WHERE id = NEW.user_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament Participant User does not exist'; END IF;
    SELECT EXISTS (
        SELECT 1 FROM trust.ban_instance b
         WHERE b.user_id = NEW.user_id AND b.status = 'ACTIVE'
           AND b.activated_at <= transaction_timestamp() AND b.ends_at > transaction_timestamp()
    ) INTO v_banned;

    IF TG_OP = 'INSERT' THEN
        NEW.joined_at := transaction_timestamp();
        NEW.status_changed_at := NEW.joined_at;
        NEW.status := 'JOINED';
        NEW.left_at := NULL;
        NEW.removed_at := NULL;
        NEW.ineligible_reason := NULL;

        IF NOT u.phone_verified OR u.anonymised_at IS NOT NULL OR v_banned THEN
            RAISE EXCEPTION 'Tournament join requires an Account-Verified, non-banned active User';
        END IF;
        IF t.status = 'PENDING_VENUE_APPROVAL' THEN
            IF t.host_type <> 'PLAYER' OR NOT t.creator_participates OR NEW.user_id IS DISTINCT FROM t.creator_user_id
               OR t.created_at IS DISTINCT FROM transaction_timestamp() THEN
                RAISE EXCEPTION 'While PENDING_VENUE_APPROVAL only the participating Player Creator may have a Participant row';
            END IF;
        ELSIF t.status NOT IN ('WAITING_FOR_PLAYERS','CONFIRMED') OR transaction_timestamp() >= t.start_at THEN
            RAISE EXCEPTION 'Users may join only WAITING_FOR_PLAYERS/CONFIRMED before startAt';
        END IF;
        v_active := tournament.active_participant_count(t.id);
        IF v_active >= t.capacity THEN
            RAISE EXCEPTION 'Tournament participant capacity is full';
        END IF;
        RETURN NEW;
    END IF;

    IF t.status = 'WAITING_FOR_PLAYERS' AND transaction_timestamp() >= t.checkpoint_at THEN
        RAISE EXCEPTION 'Tournament checkpoint is overdue; resolve the checkpoint before participant mutation';
    END IF;
    IF t.status = 'CONFIRMED' AND transaction_timestamp() >= t.start_at THEN
        RAISE EXCEPTION 'Tournament start is due; resolve startAt before participant mutation';
    END IF;

    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.tournament_id IS DISTINCT FROM OLD.tournament_id
       OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.joined_at IS DISTINCT FROM OLD.joined_at THEN
        RAISE EXCEPTION 'Tournament Participant identity/join timestamp is immutable';
    END IF;
    IF OLD.left_at IS NOT NULL AND NEW.left_at IS DISTINCT FROM OLD.left_at THEN
        RAISE EXCEPTION 'left_at is immutable once recorded';
    END IF;
    IF OLD.removed_at IS NOT NULL AND NEW.removed_at IS DISTINCT FROM OLD.removed_at THEN
        RAISE EXCEPTION 'removed_at is immutable once recorded';
    END IF;
    IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
        IF NEW.status_changed_at IS DISTINCT FROM OLD.status_changed_at
           OR NEW.left_at IS DISTINCT FROM OLD.left_at OR NEW.removed_at IS DISTINCT FROM OLD.removed_at
           OR NEW.ineligible_reason IS DISTINCT FROM OLD.ineligible_reason THEN
            RAISE EXCEPTION 'Participant lifecycle facts change only with a status transition';
        END IF;
        RETURN NEW;
    END IF;
    IF t.status IN ('COMPLETED','REJECTED','CANCELLED') THEN
        RAISE EXCEPTION 'Participant state cannot change after Tournament terminal state';
    END IF;

    NEW.status_changed_at := transaction_timestamp();
    IF NEW.status = 'JOINED' THEN
        IF transaction_timestamp() >= t.start_at OR NOT (
               t.status IN ('WAITING_FOR_PLAYERS','CONFIRMED')
               OR (t.status='PENDING_VENUE_APPROVAL' AND t.host_type='PLAYER' AND t.creator_participates AND NEW.user_id=t.creator_user_id)
           ) THEN
            RAISE EXCEPTION 'Participant may return/join only before startAt in an eligible Tournament lifecycle state';
        END IF;
        IF NOT u.phone_verified OR u.anonymised_at IS NOT NULL OR v_banned THEN
            RAISE EXCEPTION 'JOINED participant must be Account-Verified, active and not banned';
        END IF;
        NEW.ineligible_reason := NULL;
        v_active := tournament.active_participant_count(t.id);
        IF OLD.status <> 'JOINED' AND v_active >= t.capacity THEN
            RAISE EXCEPTION 'Tournament participant capacity is full';
        END IF;
    ELSIF NEW.status = 'LEFT' THEN
        IF transaction_timestamp() >= t.start_at THEN
            RAISE EXCEPTION 'Participant may Leave only before startAt';
        END IF;
        IF NEW.left_at IS NULL THEN NEW.left_at := NEW.status_changed_at; END IF;
    ELSIF NEW.status = 'REMOVED' THEN
        IF transaction_timestamp() >= t.start_at THEN
            RAISE EXCEPTION 'Organizer may Remove a Participant only before startAt';
        END IF;
        IF NEW.removed_at IS NULL THEN NEW.removed_at := NEW.status_changed_at; END IF;
    ELSIF NEW.status = 'INELIGIBLE' THEN
        IF v_banned THEN
            NEW.ineligible_reason := 'BAN';
        ELSIF u.anonymised_at IS NOT NULL THEN
            NEW.ineligible_reason := 'ACCOUNT_DELETED';
        ELSIF NULLIF(BTRIM(NEW.ineligible_reason),'') IS NULL THEN
            RAISE EXCEPTION 'INELIGIBLE requires an explicit reason';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

-- A3. Resource loss after endAt cannot beat completion, and every removal cause must have a real operational producer.
CREATE OR REPLACE FUNCTION tournament.guard_resource_due_boundary()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE t tournament.tournament%ROWTYPE;
BEGIN
    IF TG_OP='UPDATE' AND OLD.removed_at IS NULL AND NEW.removed_at IS NOT NULL THEN
        SELECT * INTO t FROM tournament.tournament WHERE id=OLD.tournament_id;
        IF t.status='ACTIVE' AND transaction_timestamp() >= t.end_at THEN
            RAISE EXCEPTION 'Tournament completion boundary owns the state before ACTIVE Resource removal at/after endAt';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_00_tournament_resource_due_boundary ON tournament.tournament_resource;
CREATE TRIGGER tr_00_tournament_resource_due_boundary
BEFORE UPDATE ON tournament.tournament_resource
FOR EACH ROW EXECUTE FUNCTION tournament.guard_resource_due_boundary();

CREATE OR REPLACE FUNCTION tournament.assert_resource_removal_source()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP='UPDATE' AND OLD.removed_at IS NULL AND NEW.removed_at IS NOT NULL THEN
        IF NEW.removal_cause='RESOURCE_EMERGENCY_OUTAGE' AND NOT EXISTS (
            SELECT 1 FROM operations.emergency e
             WHERE e.scope='RESOURCE' AND e.resource_id=NEW.resource_id
               AND e.declared_at <= NEW.removed_at
               AND (e.ended_at IS NULL OR e.ended_at >= NEW.removed_at)
        ) THEN
            RAISE EXCEPTION 'RESOURCE_EMERGENCY_OUTAGE Tournament Resource removal requires matching Resource Emergency evidence';
        ELSIF NEW.removal_cause='RESOURCE_OWNER_REVIEW_REQUIRED' AND NOT EXISTS (
            SELECT 1 FROM operations.owner_review o
             WHERE o.resource_id=NEW.resource_id AND o.entered_at <= NEW.removed_at
               AND (o.resolved_at IS NULL OR o.resolved_at >= NEW.removed_at)
        ) THEN
            RAISE EXCEPTION 'RESOURCE_OWNER_REVIEW_REQUIRED Tournament Resource removal requires matching Owner Review evidence';
        END IF;
    END IF;
    RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_tournament_resource_removal_source ON tournament.tournament_resource;
CREATE CONSTRAINT TRIGGER tr_tournament_resource_removal_source
AFTER UPDATE ON tournament.tournament_resource
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION tournament.assert_resource_removal_source();

-- A4. Condition-driven Tournament terminal reasons fail closed. Actor reasons may not bypass a higher frozen cause.
CREATE OR REPLACE FUNCTION tournament.assert_terminal_reason_provenance()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_expected text;
    t tournament.tournament%ROWTYPE;
BEGIN
    IF NEW.to_status <> 'CANCELLED' THEN RETURN NULL; END IF;
    SELECT * INTO t FROM tournament.tournament WHERE id=NEW.tournament_id;
    v_expected := tournament.highest_current_cancellation_reason(NEW.tournament_id,NEW.from_status,NEW.occurred_at);

    IF NEW.terminal_reason IN ('RESOURCE_OWNER_REVIEW_REQUIRED','RESOURCE_EMERGENCY_OUTAGE','EMERGENCY_CLOSURE','VENUE_ACCOUNT_DISABLED','MINIMUM_PARTICIPANTS_NOT_REACHED','CREATOR_VERIFIED_STATUS_REVOKED') THEN
        IF v_expected IS NULL OR v_expected IS DISTINCT FROM NEW.terminal_reason THEN
            RAISE EXCEPTION 'Condition-driven Tournament reason % lacks matching highest-priority producer (expected %)', NEW.terminal_reason, v_expected;
        END IF;
    ELSIF NEW.terminal_reason='VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME' THEN
        IF NEW.from_status <> 'PENDING_VENUE_APPROVAL' OR NEW.occurred_at < t.approval_expires_at OR v_expected IS NOT NULL THEN
            RAISE EXCEPTION 'Tournament approval-expiry reason requires expired PENDING approval and no higher frozen cancellation cause';
        END IF;
    ELSIF NEW.terminal_reason IN ('CREATOR_CANCELLED','VENUE_CANCELLED','ADMIN_CANCELLED','TOURNAMENT_OPERATIONAL_TERMINATION') THEN
        IF v_expected IS NOT NULL THEN
            RAISE EXCEPTION 'Explicit Tournament cancellation cannot bypass higher frozen reason %', v_expected;
        END IF;
    END IF;
    RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_tournament_terminal_reason_provenance ON tournament.tournament_history;
CREATE CONSTRAINT TRIGGER tr_tournament_terminal_reason_provenance
AFTER INSERT OR UPDATE ON tournament.tournament_history
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION tournament.assert_terminal_reason_provenance();

-- A5. Ban expiry/shortening/lift must restore BAN-only participants before Start when no effective Ban remains.
CREATE OR REPLACE FUNCTION tournament.assert_ban_participant_restore()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM trust.ban_instance b
         WHERE b.user_id=NEW.user_id AND b.status='ACTIVE'
           AND b.activated_at <= transaction_timestamp() AND b.ends_at > transaction_timestamp()
    ) AND EXISTS (
        SELECT 1 FROM tournament.tournament_participant p
        JOIN tournament.tournament t ON t.id=p.tournament_id
        WHERE p.user_id=NEW.user_id AND p.status='INELIGIBLE' AND p.ineligible_reason='BAN'
          AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED')
          AND transaction_timestamp() < t.start_at
    ) THEN
        RAISE EXCEPTION 'Ban expiry/lift requires automatic restoration of BAN-only Tournament Participants before Start';
    END IF;
    RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_ban_tournament_participant_restore ON trust.ban_instance;
CREATE CONSTRAINT TRIGGER tr_ban_tournament_participant_restore
AFTER UPDATE OF status, ends_at ON trust.ban_instance
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION tournament.assert_ban_participant_restore();

-- A6. State-aware scheduler and expired-ban aggregate validation using canonical scheduler token names.
CREATE OR REPLACE FUNCTION tournament.assert_tournament_aggregate(p_tournament_id uuid)
RETURNS void
LANGUAGE plpgsql
AS $function$
DECLARE
    t tournament.tournament%ROWTYPE;
    s venue.operating_session%ROWTYPE;
    v_resources integer;
    v_unremoved integer;
    v_expected_cost numeric(12,2);
BEGIN
    SELECT * INTO t FROM tournament.tournament WHERE id=p_tournament_id;
    IF NOT FOUND THEN RETURN; END IF;

    SELECT * INTO s FROM venue.operating_session WHERE id=t.operating_session_id;
    IF NOT FOUND OR s.venue_id IS DISTINCT FROM t.venue_id
       OR t.start_at < lower(s.session_period) OR t.end_at > upper(s.session_period)
       OR t.business_date IS DISTINCT FROM s.operating_day THEN
        RAISE EXCEPTION 'Tournament must fit completely inside one matching Venue Operating Session and businessDate';
    END IF;

    SELECT COUNT(*)::integer,
           COALESCE(SUM(ROUND(tr.hourly_price_snapshot * t.nominal_minutes / 60.0,2)),0)::numeric(12,2)
      INTO v_resources, v_expected_cost
      FROM tournament.tournament_resource tr WHERE tr.tournament_id=t.id;
    IF v_resources NOT BETWEEN 1 AND 4 THEN RAISE EXCEPTION 'Tournament requires exactly 1 to 4 Resource rows'; END IF;
    IF t.venue_cost_total IS DISTINCT FROM v_expected_cost THEN
        RAISE EXCEPTION 'Tournament venue_cost_total % does not equal immutable Resource snapshot total %', t.venue_cost_total, v_expected_cost;
    END IF;

    IF t.host_type='PLAYER' AND t.creator_participates AND NOT EXISTS (
        SELECT 1 FROM tournament.tournament_participant p WHERE p.tournament_id=t.id AND p.user_id=t.creator_user_id
    ) THEN
        RAISE EXCEPTION 'Participating Player Creator requires a retained Participant row';
    END IF;

    IF t.status='PENDING_VENUE_APPROVAL' THEN
        IF EXISTS (SELECT 1 FROM tournament.tournament_resource tr WHERE tr.tournament_id=t.id AND tr.removed_at IS NOT NULL) THEN
            RAISE EXCEPTION 'Pre-approval Tournament cannot contain removed Resources';
        END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_resource tr
            LEFT JOIN inventory.resource_reservation rr ON rr.id=tr.reservation_id
            WHERE tr.tournament_id=t.id AND (rr.id IS NULL OR rr.reservation_type<>'TOURNAMENT_APPROVAL_HOLD' OR NOT rr.active_flag
                OR rr.tournament_id IS DISTINCT FROM t.id OR rr.resource_id IS DISTINCT FROM tr.resource_id
                OR rr.planned_start IS DISTINCT FROM t.start_at OR rr.planned_end IS DISTINCT FROM t.end_at)
        ) THEN RAISE EXCEPTION 'PENDING_VENUE_APPROVAL requires active Approval Holds for every Resource'; END IF;
    ELSIF t.status IN ('WAITING_FOR_PLAYERS','CONFIRMED') THEN
        IF EXISTS (SELECT 1 FROM tournament.tournament_resource tr WHERE tr.tournament_id=t.id AND tr.removed_at IS NOT NULL) THEN
            RAISE EXCEPTION 'Pre-start Tournament cannot contain removed Resources';
        END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_resource tr
            LEFT JOIN inventory.resource_reservation rr ON rr.id=tr.reservation_id
            WHERE tr.tournament_id=t.id AND (rr.id IS NULL OR rr.reservation_type<>'TOURNAMENT_HOLD' OR NOT rr.active_flag
                OR rr.tournament_id IS DISTINCT FROM t.id OR rr.resource_id IS DISTINCT FROM tr.resource_id
                OR rr.planned_start IS DISTINCT FROM t.start_at OR rr.planned_end IS DISTINCT FROM t.end_at)
        ) THEN RAISE EXCEPTION 'WAITING/CONFIRMED Tournament requires active standard Holds for every Resource'; END IF;
    ELSIF t.status='ACTIVE' THEN
        SELECT COUNT(*)::integer INTO v_unremoved FROM tournament.tournament_resource tr WHERE tr.tournament_id=t.id AND tr.removed_at IS NULL;
        IF v_unremoved < 1 THEN RAISE EXCEPTION 'ACTIVE Tournament requires at least one remaining Resource'; END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_resource tr
            LEFT JOIN inventory.resource_reservation rr ON rr.id=tr.reservation_id
            WHERE tr.tournament_id=t.id AND tr.removed_at IS NULL
              AND (rr.id IS NULL OR rr.reservation_type<>'TOURNAMENT_HOLD' OR NOT rr.active_flag
                   OR rr.tournament_id IS DISTINCT FROM t.id OR rr.resource_id IS DISTINCT FROM tr.resource_id)
        ) THEN RAISE EXCEPTION 'ACTIVE Tournament requires an active standard Hold for each remaining Resource'; END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_resource tr
            JOIN inventory.resource_reservation rr ON rr.id=tr.reservation_id
            WHERE tr.tournament_id=t.id AND tr.removed_at IS NOT NULL
              AND (rr.active_flag OR rr.actual_reservation_release_at IS DISTINCT FROM tr.removed_at)
        ) THEN RAISE EXCEPTION 'Removed ACTIVE Tournament Resource requires its Hold released at removed_at'; END IF;
    ELSE
        IF EXISTS (SELECT 1 FROM inventory.resource_reservation rr WHERE rr.tournament_id=t.id AND rr.active_flag) THEN
            RAISE EXCEPTION 'Terminal Tournament may not retain active Resource Holds';
        END IF;
    END IF;

    -- Ban expiry is effective by ends_at. A qualifying BAN-only INELIGIBLE participant must be restored
    -- before a live pre-start Tournament can commit another state-changing transaction.
    IF t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED') AND transaction_timestamp() < t.start_at
       AND EXISTS (
           SELECT 1 FROM tournament.tournament_participant p
            WHERE p.tournament_id=t.id AND p.status='INELIGIBLE' AND p.ineligible_reason='BAN'
              AND NOT EXISTS (
                  SELECT 1 FROM trust.ban_instance b
                   WHERE b.user_id=p.user_id AND b.status='ACTIVE'
                     AND b.activated_at <= transaction_timestamp() AND b.ends_at > transaction_timestamp()
              )
       ) THEN
        RAISE EXCEPTION 'Expired Ban requires automatic Tournament Participant restoration before commit';
    END IF;

    -- Canonical scheduler contract from Technical Architecture v1.2. Only live jobs count.
    IF t.status='PENDING_VENUE_APPROVAL' THEN
        IF NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_APPROVAL_EXPIRY' AND j.due_at=t.approval_expires_at AND j.status IN ('PENDING','PAUSED','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_CHECKPOINT' AND j.due_at=t.checkpoint_at AND j.status IN ('PENDING','PAUSED','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_START' AND j.due_at=t.start_at AND j.status IN ('PENDING','PAUSED','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_COMPLETION' AND j.due_at=t.end_at AND j.status IN ('PENDING','PAUSED','LEASED')) THEN
            RAISE EXCEPTION 'PENDING Tournament requires live approval/checkpoint/start/completion jobs';
        END IF;
    ELSIF t.status='WAITING_FOR_PLAYERS' THEN
        IF EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_APPROVAL_EXPIRY' AND j.status IN ('PENDING','PAUSED','LEASED')) THEN
            RAISE EXCEPTION 'Approved Tournament may not retain a live approval-expiry job';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_CHECKPOINT' AND j.due_at=t.checkpoint_at AND j.status IN ('PENDING','PAUSED','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_START' AND j.due_at=t.start_at AND j.status IN ('PENDING','PAUSED','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_COMPLETION' AND j.due_at=t.end_at AND j.status IN ('PENDING','PAUSED','LEASED')) THEN
            RAISE EXCEPTION 'WAITING Tournament requires live checkpoint/start/completion jobs';
        END IF;
    ELSIF t.status='CONFIRMED' THEN
        IF EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type IN ('TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT') AND j.status IN ('PENDING','PAUSED','LEASED')) THEN
            RAISE EXCEPTION 'CONFIRMED Tournament may not retain live approval/checkpoint jobs';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_START' AND j.due_at=t.start_at AND j.status IN ('PENDING','PAUSED','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_COMPLETION' AND j.due_at=t.end_at AND j.status IN ('PENDING','PAUSED','LEASED')) THEN
            RAISE EXCEPTION 'CONFIRMED Tournament requires live start/completion jobs';
        END IF;
    ELSIF t.status='ACTIVE' THEN
        IF EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type IN ('TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT','TOURNAMENT_START') AND j.status IN ('PENDING','PAUSED','LEASED')) THEN
            RAISE EXCEPTION 'ACTIVE Tournament may not retain obsolete live approval/checkpoint/start jobs';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_COMPLETION' AND j.due_at=t.end_at AND j.status IN ('PENDING','PAUSED','LEASED')) THEN
            RAISE EXCEPTION 'ACTIVE Tournament requires a live completion job';
        END IF;
    ELSE
        IF EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type IN ('TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT','TOURNAMENT_START','TOURNAMENT_COMPLETION') AND j.status IN ('PENDING','PAUSED','LEASED')) THEN
            RAISE EXCEPTION 'Terminal Tournament may not retain live Tournament scheduler jobs';
        END IF;
    END IF;

    PERFORM tournament.assert_tournament_history_chain(t.id);
END;
$function$;

-- A7. Scheduler mutations affecting a Tournament must revalidate its final aggregate state.
CREATE OR REPLACE FUNCTION tournament.assert_tournament_from_job_row()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE v_id uuid;
BEGIN
    v_id := CASE WHEN TG_OP='DELETE' THEN OLD.subject_id ELSE NEW.subject_id END;
    IF (CASE WHEN TG_OP='DELETE' THEN OLD.type ELSE NEW.type END) IN ('TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT','TOURNAMENT_START','TOURNAMENT_COMPLETION') THEN
        PERFORM tournament.assert_tournament_aggregate(v_id);
    END IF;
    RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_tournament_job_final_state ON technical.scheduled_job;
CREATE CONSTRAINT TRIGGER tr_tournament_job_final_state
AFTER INSERT OR UPDATE OR DELETE ON technical.scheduled_job
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION tournament.assert_tournament_from_job_row();

-- A8. Upgrade acceptance sweep: every existing Tournament must satisfy the full v1.1.12 invariant now.
DO $validate$
DECLARE r record;
BEGIN
    FOR r IN SELECT id FROM tournament.tournament LOOP
        PERFORM tournament.assert_tournament_aggregate(r.id);
    END LOOP;
END
$validate$;

-- A9. Delivery contract.
-- * Application commands resolve overdue approval/checkpoint/start/end boundaries before accepting a competing action.
-- * Ban-expiry handling restores BAN-only Participants in the same transaction when the Product permits restoration.
-- * Tournament Creation Fee remains a mandatory service snapshot of the effective configuration at created_at;
--   the frozen sources do not define a physical configuration key name, so this baseline does not invent one in SQL.
-- * Scheduler canonical column/token names are status and TOURNAMENT_COMPLETION.



-- ============================================================================
-- E7GZ PS v1.1.13 TOURNAMENT FINAL ACCEPTANCE FIXES
-- PostgreSQL 15+. Apply after v1.1.12.
-- Product-visible Tournament states/reasons are unchanged.
-- ============================================================================

-- F1. Deadline-effective cancellation resolver: late workers evaluate the exact Product boundary.
CREATE OR REPLACE FUNCTION tournament.highest_current_cancellation_reason(
    p_tournament_id uuid,
    p_from_status text,
    p_at timestamptz
)
RETURNS text
LANGUAGE plpgsql
STABLE
AS $function$
DECLARE
    t tournament.tournament%ROWTYPE;
    v_creator_status text;
    v_has_owner_review boolean;
    v_has_resource_emergency boolean;
    v_has_venue_emergency boolean;
    v_remaining integer;
    v_eval_at timestamptz;
BEGIN
    SELECT * INTO t FROM tournament.tournament WHERE id = p_tournament_id;
    IF NOT FOUND THEN RETURN NULL; END IF;

    -- A late worker must evaluate the cause set at the Product boundary, not at worker time.
    v_eval_at := p_at;
    IF p_from_status='PENDING_VENUE_APPROVAL' AND p_at >= t.approval_expires_at THEN
        v_eval_at := t.approval_expires_at;
    ELSIF p_from_status='WAITING_FOR_PLAYERS' AND p_at >= t.checkpoint_at THEN
        v_eval_at := t.checkpoint_at;
    ELSIF p_from_status='CONFIRMED' AND p_at >= t.start_at THEN
        v_eval_at := t.start_at;
    ELSIF p_from_status='ACTIVE' AND p_at >= t.end_at THEN
        v_eval_at := t.end_at;
    END IF;

    SELECT EXISTS (
        SELECT 1
          FROM tournament.tournament_resource tr
          JOIN operations.owner_review o ON o.resource_id = tr.resource_id
         WHERE tr.tournament_id = t.id
           AND o.entered_at <= v_eval_at
           AND (o.resolved_at IS NULL OR o.resolved_at > v_eval_at)
    ) INTO v_has_owner_review;

    SELECT EXISTS (
        SELECT 1
          FROM tournament.tournament_resource tr
          JOIN operations.emergency e ON e.resource_id = tr.resource_id AND e.scope = 'RESOURCE'
         WHERE tr.tournament_id = t.id
           AND e.declared_at <= v_eval_at
           AND (e.ended_at IS NULL OR e.ended_at > v_eval_at)
           AND tstzrange(t.start_at,t.end_at,'[)') && e.declared_period
    ) INTO v_has_resource_emergency;

    SELECT EXISTS (
        SELECT 1 FROM operations.emergency e
         WHERE e.scope = 'VENUE'
           AND e.venue_id = t.venue_id
           AND e.declared_at <= v_eval_at
           AND (e.ended_at IS NULL OR e.ended_at > v_eval_at)
           AND tstzrange(t.start_at,t.end_at,'[)') && e.declared_period
    ) INTO v_has_venue_emergency;

    IF p_from_status = 'ACTIVE' THEN
        SELECT COUNT(*)::integer INTO v_remaining
          FROM tournament.tournament_resource tr
         WHERE tr.tournament_id = t.id
           AND (tr.removed_at IS NULL OR tr.removed_at > v_eval_at)
           AND NOT EXISTS (
               SELECT 1 FROM operations.owner_review o
                WHERE o.resource_id = tr.resource_id
                  AND o.entered_at <= v_eval_at
                  AND (o.resolved_at IS NULL OR o.resolved_at > v_eval_at)
           )
           AND NOT EXISTS (
               SELECT 1 FROM operations.emergency e
                WHERE e.scope = 'RESOURCE'
                  AND e.resource_id = tr.resource_id
                  AND e.declared_at <= v_eval_at
                  AND (e.ended_at IS NULL OR e.ended_at > v_eval_at)
                  AND tstzrange(t.start_at,t.end_at,'[)') && e.declared_period
           );
        IF v_remaining > 0 THEN
            v_has_owner_review := false;
            v_has_resource_emergency := false;
        END IF;
    END IF;

    IF v_has_owner_review THEN RETURN 'RESOURCE_OWNER_REVIEW_REQUIRED'; END IF;
    IF v_has_resource_emergency THEN RETURN 'RESOURCE_EMERGENCY_OUTAGE'; END IF;
    IF v_has_venue_emergency THEN RETURN 'EMERGENCY_CLOSURE'; END IF;

    IF p_from_status = 'PENDING_VENUE_APPROVAL' AND EXISTS (
        SELECT 1 FROM iam.venue_account_restriction_interval r
         WHERE r.venue_id = t.venue_id
           AND r.disabled_at <= v_eval_at
           AND (r.reenabled_at IS NULL OR r.reenabled_at > v_eval_at)
    ) THEN
        RETURN 'VENUE_ACCOUNT_DISABLED';
    END IF;

    IF p_from_status = 'WAITING_FOR_PLAYERS'
       AND v_eval_at >= t.checkpoint_at
       AND tournament.active_participant_count(t.id) < 8 THEN
        RETURN 'MINIMUM_PARTICIPANTS_NOT_REACHED';
    END IF;

    IF p_from_status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS') AND t.creator_user_id IS NOT NULL THEN
        SELECT v.to_status INTO v_creator_status
          FROM trust.verified_player_transition v
         WHERE v.user_id = t.creator_user_id
           AND v.occurred_at <= v_eval_at
         ORDER BY v.occurred_at DESC, v.id DESC
         LIMIT 1;
        IF v_creator_status = 'REVOKED' THEN
            RETURN 'CREATOR_VERIFIED_STATUS_REVOKED';
        END IF;
    END IF;

    RETURN NULL;
END;
$function$;

-- F2. Full due-state ownership for approval/checkpoint/start/end, including System cascades.
CREATE OR REPLACE FUNCTION tournament.guard_tournament_due_boundary()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_expected text;
BEGIN
    IF OLD.status='PENDING_VENUE_APPROVAL' AND transaction_timestamp() >= OLD.approval_expires_at THEN
        v_expected := tournament.highest_current_cancellation_reason(OLD.id,'PENDING_VENUE_APPROVAL',OLD.approval_expires_at);
        IF v_expected IS NULL THEN
            v_expected := 'VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME';
        END IF;
        IF NEW.status <> 'CANCELLED' OR NEW.terminal_reason IS DISTINCT FROM v_expected THEN
            RAISE EXCEPTION 'Approval deadline owns the next transition; expected CANCELLED/%', v_expected;
        END IF;

    ELSIF OLD.status='WAITING_FOR_PLAYERS' AND transaction_timestamp() >= OLD.checkpoint_at THEN
        -- A BAN that already expired at checkpoint must be restored first; a later worker cannot make
        -- the participant absent from the exact checkpoint count.
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_participant p
             WHERE p.tournament_id=OLD.id AND p.status='INELIGIBLE' AND p.ineligible_reason='BAN'
               AND NOT EXISTS (
                   SELECT 1 FROM trust.ban_instance b
                    WHERE b.user_id=p.user_id AND b.activated_at <= OLD.checkpoint_at AND b.ends_at > OLD.checkpoint_at
               )
        ) THEN
            RAISE EXCEPTION 'Restore BAN-only Participants whose Ban expired by checkpointAt before resolving the checkpoint';
        END IF;
        v_expected := tournament.highest_current_cancellation_reason(OLD.id,'WAITING_FOR_PLAYERS',OLD.checkpoint_at);
        IF v_expected IS NULL THEN
            IF NEW.status <> 'CONFIRMED' OR NEW.terminal_reason IS NOT NULL THEN
                RAISE EXCEPTION 'Checkpoint owns the next transition; expected CONFIRMED';
            END IF;
        ELSE
            IF NEW.status <> 'CANCELLED' OR NEW.terminal_reason IS DISTINCT FROM v_expected THEN
                RAISE EXCEPTION 'Checkpoint owns the next transition; expected CANCELLED/%', v_expected;
            END IF;
        END IF;

    ELSIF OLD.status='CONFIRMED' AND transaction_timestamp() >= OLD.start_at THEN
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_participant p
             WHERE p.tournament_id=OLD.id AND p.status='INELIGIBLE' AND p.ineligible_reason='BAN'
               AND NOT EXISTS (
                   SELECT 1 FROM trust.ban_instance b
                    WHERE b.user_id=p.user_id AND b.activated_at <= OLD.start_at AND b.ends_at > OLD.start_at
               )
        ) THEN
            RAISE EXCEPTION 'Restore BAN-only Participants whose Ban expired by startAt before resolving Tournament start';
        END IF;
        v_expected := tournament.highest_current_cancellation_reason(OLD.id,'CONFIRMED',OLD.start_at);
        IF v_expected IS NULL THEN
            IF NEW.status <> 'ACTIVE' OR NEW.terminal_reason IS NOT NULL THEN
                RAISE EXCEPTION 'startAt owns the next transition; expected ACTIVE';
            END IF;
        ELSE
            IF NEW.status <> 'CANCELLED' OR NEW.terminal_reason IS DISTINCT FROM v_expected THEN
                RAISE EXCEPTION 'startAt owns the next transition; expected CANCELLED/%', v_expected;
            END IF;
        END IF;

    ELSIF OLD.status='ACTIVE' AND transaction_timestamp() >= OLD.end_at THEN
        IF NEW.status <> 'COMPLETED' OR NEW.terminal_reason IS NOT NULL THEN
            RAISE EXCEPTION 'endAt owns the next transition; expected COMPLETED';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_00_tournament_due_boundary ON tournament.tournament;
CREATE TRIGGER tr_00_tournament_due_boundary
BEFORE UPDATE ON tournament.tournament
FOR EACH ROW EXECUTE FUNCTION tournament.guard_tournament_due_boundary();

-- F3. Participant mutations cannot cross checkpoint/start; only delayed BAN-expiry restoration may catch up.
CREATE OR REPLACE FUNCTION tournament.guard_tournament_participant()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    t tournament.tournament%ROWTYPE;
    u iam.user_account%ROWTYPE;
    v_active integer;
    v_banned boolean;
    v_boundary_restore boolean := false;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Tournament Participant history may not be deleted';
    END IF;

    SELECT * INTO t FROM tournament.tournament WHERE id = NEW.tournament_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament does not exist'; END IF;
    SELECT * INTO u FROM iam.user_account WHERE id = NEW.user_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament Participant User does not exist'; END IF;
    SELECT EXISTS (
        SELECT 1 FROM trust.ban_instance b
         WHERE b.user_id = NEW.user_id AND b.status = 'ACTIVE'
           AND b.activated_at <= transaction_timestamp() AND b.ends_at > transaction_timestamp()
    ) INTO v_banned;

    IF TG_OP='UPDATE' AND OLD.status='INELIGIBLE' AND OLD.ineligible_reason='BAN' AND NEW.status='JOINED' THEN
        IF t.status='WAITING_FOR_PLAYERS' AND transaction_timestamp() >= t.checkpoint_at
           AND NOT EXISTS (
               SELECT 1 FROM trust.ban_instance b
                WHERE b.user_id=NEW.user_id AND b.activated_at <= t.checkpoint_at AND b.ends_at > t.checkpoint_at
           ) THEN
            v_boundary_restore := true;
        ELSIF t.status='CONFIRMED' AND transaction_timestamp() >= t.start_at
           AND NOT EXISTS (
               SELECT 1 FROM trust.ban_instance b
                WHERE b.user_id=NEW.user_id AND b.activated_at <= t.start_at AND b.ends_at > t.start_at
           ) THEN
            v_boundary_restore := true;
        END IF;
    END IF;

    -- Once a due boundary is reached, no participant mutation may change its result.
    -- The only exception is catching up a BAN-only restoration that was already effective at that boundary.
    IF t.status='WAITING_FOR_PLAYERS' AND transaction_timestamp() >= t.checkpoint_at AND NOT v_boundary_restore THEN
        RAISE EXCEPTION 'Tournament checkpoint is overdue; resolve the checkpoint before participant mutation';
    END IF;
    IF t.status='CONFIRMED' AND transaction_timestamp() >= t.start_at AND NOT v_boundary_restore THEN
        RAISE EXCEPTION 'Tournament start is due; resolve startAt before participant mutation';
    END IF;

    IF TG_OP = 'INSERT' THEN
        NEW.joined_at := transaction_timestamp();
        NEW.status_changed_at := NEW.joined_at;
        NEW.status := 'JOINED';
        NEW.left_at := NULL;
        NEW.removed_at := NULL;
        NEW.ineligible_reason := NULL;

        IF NOT u.phone_verified OR u.anonymised_at IS NOT NULL OR v_banned THEN
            RAISE EXCEPTION 'Tournament join requires an Account-Verified, non-banned active User';
        END IF;
        IF t.status = 'PENDING_VENUE_APPROVAL' THEN
            IF t.host_type <> 'PLAYER' OR NOT t.creator_participates OR NEW.user_id IS DISTINCT FROM t.creator_user_id
               OR t.created_at IS DISTINCT FROM transaction_timestamp() THEN
                RAISE EXCEPTION 'While PENDING_VENUE_APPROVAL only the participating Player Creator may have a Participant row';
            END IF;
        ELSIF t.status NOT IN ('WAITING_FOR_PLAYERS','CONFIRMED') OR transaction_timestamp() >= t.start_at THEN
            RAISE EXCEPTION 'Users may join only WAITING_FOR_PLAYERS/CONFIRMED before startAt';
        END IF;
        v_active := tournament.active_participant_count(t.id);
        IF v_active >= t.capacity THEN
            RAISE EXCEPTION 'Tournament participant capacity is full';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.tournament_id IS DISTINCT FROM OLD.tournament_id
       OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.joined_at IS DISTINCT FROM OLD.joined_at THEN
        RAISE EXCEPTION 'Tournament Participant identity/join timestamp is immutable';
    END IF;
    IF OLD.left_at IS NOT NULL AND NEW.left_at IS DISTINCT FROM OLD.left_at THEN
        RAISE EXCEPTION 'left_at is immutable once recorded';
    END IF;
    IF OLD.removed_at IS NOT NULL AND NEW.removed_at IS DISTINCT FROM OLD.removed_at THEN
        RAISE EXCEPTION 'removed_at is immutable once recorded';
    END IF;
    IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
        IF NEW.status_changed_at IS DISTINCT FROM OLD.status_changed_at
           OR NEW.left_at IS DISTINCT FROM OLD.left_at OR NEW.removed_at IS DISTINCT FROM OLD.removed_at
           OR NEW.ineligible_reason IS DISTINCT FROM OLD.ineligible_reason THEN
            RAISE EXCEPTION 'Participant lifecycle facts change only with a status transition';
        END IF;
        RETURN NEW;
    END IF;
    IF t.status IN ('COMPLETED','REJECTED','CANCELLED') THEN
        RAISE EXCEPTION 'Participant state cannot change after Tournament terminal state';
    END IF;

    NEW.status_changed_at := transaction_timestamp();
    IF NEW.status = 'JOINED' THEN
        IF NOT v_boundary_restore AND (transaction_timestamp() >= t.start_at OR NOT (
               t.status IN ('WAITING_FOR_PLAYERS','CONFIRMED')
               OR (t.status='PENDING_VENUE_APPROVAL' AND t.host_type='PLAYER' AND t.creator_participates AND NEW.user_id=t.creator_user_id)
           )) THEN
            RAISE EXCEPTION 'Participant may return/join only before startAt in an eligible Tournament lifecycle state';
        END IF;
        IF NOT u.phone_verified OR u.anonymised_at IS NOT NULL OR v_banned THEN
            RAISE EXCEPTION 'JOINED participant must be Account-Verified, active and not banned';
        END IF;
        NEW.ineligible_reason := NULL;
        v_active := tournament.active_participant_count(t.id);
        IF OLD.status <> 'JOINED' AND v_active >= t.capacity THEN
            RAISE EXCEPTION 'Tournament participant capacity is full';
        END IF;
    ELSIF NEW.status = 'LEFT' THEN
        IF transaction_timestamp() >= t.start_at THEN
            RAISE EXCEPTION 'Participant may Leave only before startAt';
        END IF;
        IF NEW.left_at IS NULL THEN NEW.left_at := NEW.status_changed_at; END IF;
    ELSIF NEW.status = 'REMOVED' THEN
        IF transaction_timestamp() >= t.start_at THEN
            RAISE EXCEPTION 'Organizer may Remove a Participant only before startAt';
        END IF;
        IF NEW.removed_at IS NULL THEN NEW.removed_at := NEW.status_changed_at; END IF;
    ELSIF NEW.status = 'INELIGIBLE' THEN
        IF v_banned THEN
            NEW.ineligible_reason := 'BAN';
        ELSIF u.anonymised_at IS NOT NULL THEN
            NEW.ineligible_reason := 'ACCOUNT_DELETED';
        ELSIF NULLIF(BTRIM(NEW.ineligible_reason),'') IS NULL THEN
            RAISE EXCEPTION 'INELIGIBLE requires an explicit reason';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

-- F4. Aggregate invariant uses boundary-effective Ban restoration and non-pausable Tournament jobs.
CREATE OR REPLACE FUNCTION tournament.assert_tournament_aggregate(p_tournament_id uuid)
RETURNS void
LANGUAGE plpgsql
AS $function$
DECLARE
    t tournament.tournament%ROWTYPE;
    s venue.operating_session%ROWTYPE;
    v_resources integer;
    v_unremoved integer;
    v_expected_cost numeric(12,2);
    v_participant_eval_at timestamptz;
BEGIN
    SELECT * INTO t FROM tournament.tournament WHERE id=p_tournament_id;
    IF NOT FOUND THEN RETURN; END IF;

    SELECT * INTO s FROM venue.operating_session WHERE id=t.operating_session_id;
    IF NOT FOUND OR s.venue_id IS DISTINCT FROM t.venue_id
       OR t.start_at < lower(s.session_period) OR t.end_at > upper(s.session_period)
       OR t.business_date IS DISTINCT FROM s.operating_day THEN
        RAISE EXCEPTION 'Tournament must fit completely inside one matching Venue Operating Session and businessDate';
    END IF;

    SELECT COUNT(*)::integer,
           COALESCE(SUM(ROUND(tr.hourly_price_snapshot * t.nominal_minutes / 60.0,2)),0)::numeric(12,2)
      INTO v_resources, v_expected_cost
      FROM tournament.tournament_resource tr WHERE tr.tournament_id=t.id;
    IF v_resources NOT BETWEEN 1 AND 4 THEN RAISE EXCEPTION 'Tournament requires exactly 1 to 4 Resource rows'; END IF;
    IF t.venue_cost_total IS DISTINCT FROM v_expected_cost THEN
        RAISE EXCEPTION 'Tournament venue_cost_total % does not equal immutable Resource snapshot total %', t.venue_cost_total, v_expected_cost;
    END IF;

    IF t.host_type='PLAYER' AND t.creator_participates AND NOT EXISTS (
        SELECT 1 FROM tournament.tournament_participant p WHERE p.tournament_id=t.id AND p.user_id=t.creator_user_id
    ) THEN
        RAISE EXCEPTION 'Participating Player Creator requires a retained Participant row';
    END IF;

    IF t.status='PENDING_VENUE_APPROVAL' THEN
        IF EXISTS (SELECT 1 FROM tournament.tournament_resource tr WHERE tr.tournament_id=t.id AND tr.removed_at IS NOT NULL) THEN
            RAISE EXCEPTION 'Pre-approval Tournament cannot contain removed Resources';
        END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_resource tr
            LEFT JOIN inventory.resource_reservation rr ON rr.id=tr.reservation_id
            WHERE tr.tournament_id=t.id AND (rr.id IS NULL OR rr.reservation_type<>'TOURNAMENT_APPROVAL_HOLD' OR NOT rr.active_flag
                OR rr.tournament_id IS DISTINCT FROM t.id OR rr.resource_id IS DISTINCT FROM tr.resource_id
                OR rr.planned_start IS DISTINCT FROM t.start_at OR rr.planned_end IS DISTINCT FROM t.end_at)
        ) THEN RAISE EXCEPTION 'PENDING_VENUE_APPROVAL requires active Approval Holds for every Resource'; END IF;
    ELSIF t.status IN ('WAITING_FOR_PLAYERS','CONFIRMED') THEN
        IF EXISTS (SELECT 1 FROM tournament.tournament_resource tr WHERE tr.tournament_id=t.id AND tr.removed_at IS NOT NULL) THEN
            RAISE EXCEPTION 'Pre-start Tournament cannot contain removed Resources';
        END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_resource tr
            LEFT JOIN inventory.resource_reservation rr ON rr.id=tr.reservation_id
            WHERE tr.tournament_id=t.id AND (rr.id IS NULL OR rr.reservation_type<>'TOURNAMENT_HOLD' OR NOT rr.active_flag
                OR rr.tournament_id IS DISTINCT FROM t.id OR rr.resource_id IS DISTINCT FROM tr.resource_id
                OR rr.planned_start IS DISTINCT FROM t.start_at OR rr.planned_end IS DISTINCT FROM t.end_at)
        ) THEN RAISE EXCEPTION 'WAITING/CONFIRMED Tournament requires active standard Holds for every Resource'; END IF;
    ELSIF t.status='ACTIVE' THEN
        SELECT COUNT(*)::integer INTO v_unremoved FROM tournament.tournament_resource tr WHERE tr.tournament_id=t.id AND tr.removed_at IS NULL;
        IF v_unremoved < 1 THEN RAISE EXCEPTION 'ACTIVE Tournament requires at least one remaining Resource'; END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_resource tr
            LEFT JOIN inventory.resource_reservation rr ON rr.id=tr.reservation_id
            WHERE tr.tournament_id=t.id AND tr.removed_at IS NULL
              AND (rr.id IS NULL OR rr.reservation_type<>'TOURNAMENT_HOLD' OR NOT rr.active_flag
                   OR rr.tournament_id IS DISTINCT FROM t.id OR rr.resource_id IS DISTINCT FROM tr.resource_id)
        ) THEN RAISE EXCEPTION 'ACTIVE Tournament requires an active standard Hold for each remaining Resource'; END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_resource tr
            JOIN inventory.resource_reservation rr ON rr.id=tr.reservation_id
            WHERE tr.tournament_id=t.id AND tr.removed_at IS NOT NULL
              AND (rr.active_flag OR rr.actual_reservation_release_at IS DISTINCT FROM tr.removed_at)
        ) THEN RAISE EXCEPTION 'Removed ACTIVE Tournament Resource requires its Hold released at removed_at'; END IF;
    ELSE
        IF EXISTS (SELECT 1 FROM inventory.resource_reservation rr WHERE rr.tournament_id=t.id AND rr.active_flag) THEN
            RAISE EXCEPTION 'Terminal Tournament may not retain active Resource Holds';
        END IF;
    END IF;

    -- Ban expiry is deadline-effective. For an overdue checkpoint/start, evaluate participant
    -- restoration at the boundary itself so a late Ban worker cannot change the Product result.
    IF t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED') THEN
        v_participant_eval_at := transaction_timestamp();
        IF t.status='WAITING_FOR_PLAYERS' AND transaction_timestamp() >= t.checkpoint_at THEN
            v_participant_eval_at := t.checkpoint_at;
        ELSIF t.status='CONFIRMED' AND transaction_timestamp() >= t.start_at THEN
            v_participant_eval_at := t.start_at;
        END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_participant p
             WHERE p.tournament_id=t.id AND p.status='INELIGIBLE' AND p.ineligible_reason='BAN'
               AND NOT EXISTS (
                   SELECT 1 FROM trust.ban_instance b
                    WHERE b.user_id=p.user_id
                      AND b.activated_at <= v_participant_eval_at AND b.ends_at > v_participant_eval_at
               )
        ) THEN
            RAISE EXCEPTION 'Expired Ban requires automatic Tournament Participant restoration before the authoritative boundary can commit';
        END IF;
    END IF;

    -- Canonical scheduler contract from Technical Architecture v1.2. Only live jobs count.
    IF t.status='PENDING_VENUE_APPROVAL' THEN
        IF NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_APPROVAL_EXPIRY' AND j.due_at=t.approval_expires_at AND j.status IN ('PENDING','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_CHECKPOINT' AND j.due_at=t.checkpoint_at AND j.status IN ('PENDING','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_START' AND j.due_at=t.start_at AND j.status IN ('PENDING','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_COMPLETION' AND j.due_at=t.end_at AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'PENDING Tournament requires live approval/checkpoint/start/completion jobs';
        END IF;
    ELSIF t.status='WAITING_FOR_PLAYERS' THEN
        IF EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_APPROVAL_EXPIRY' AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'Approved Tournament may not retain a live approval-expiry job';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_CHECKPOINT' AND j.due_at=t.checkpoint_at AND j.status IN ('PENDING','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_START' AND j.due_at=t.start_at AND j.status IN ('PENDING','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_COMPLETION' AND j.due_at=t.end_at AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'WAITING Tournament requires live checkpoint/start/completion jobs';
        END IF;
    ELSIF t.status='CONFIRMED' THEN
        IF EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type IN ('TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT') AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'CONFIRMED Tournament may not retain live approval/checkpoint jobs';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_START' AND j.due_at=t.start_at AND j.status IN ('PENDING','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_COMPLETION' AND j.due_at=t.end_at AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'CONFIRMED Tournament requires live start/completion jobs';
        END IF;
    ELSIF t.status='ACTIVE' THEN
        IF EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type IN ('TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT','TOURNAMENT_START') AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'ACTIVE Tournament may not retain obsolete live approval/checkpoint/start jobs';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_COMPLETION' AND j.due_at=t.end_at AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'ACTIVE Tournament requires a live completion job';
        END IF;
    ELSE
        IF EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type IN ('TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT','TOURNAMENT_START','TOURNAMENT_COMPLETION') AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'Terminal Tournament may not retain live Tournament scheduler jobs';
        END IF;
    END IF;

    PERFORM tournament.assert_tournament_history_chain(t.id);
END;
$function$;

-- F5. Tournament scheduler rows are non-pausable and their timing identity is immutable.
CREATE OR REPLACE FUNCTION tournament.guard_tournament_scheduled_job()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_types text[] := ARRAY['TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT','TOURNAMENT_START','TOURNAMENT_COMPLETION'];
BEGIN
    IF NEW.type = ANY(v_types) AND NEW.status='PAUSED' THEN
        RAISE EXCEPTION 'Tournament timers have no Product pause state';
    END IF;
    IF TG_OP='UPDATE' AND (OLD.type = ANY(v_types) OR NEW.type = ANY(v_types)) THEN
        IF NEW.type IS DISTINCT FROM OLD.type
           OR NEW.subject_id IS DISTINCT FROM OLD.subject_id
           OR NEW.due_at IS DISTINCT FROM OLD.due_at
           OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key THEN
            RAISE EXCEPTION 'Tournament scheduled-job type/subject/due/idempotency identity is immutable';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_guard_tournament_scheduled_job ON technical.scheduled_job;
CREATE TRIGGER tr_guard_tournament_scheduled_job
BEFORE INSERT OR UPDATE ON technical.scheduled_job
FOR EACH ROW EXECUTE FUNCTION tournament.guard_tournament_scheduled_job();

-- F6. Scheduler changes revalidate both the OLD and NEW Tournament side.
CREATE OR REPLACE FUNCTION tournament.assert_tournament_from_job_row()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_old_is_tournament boolean := false;
    v_new_is_tournament boolean := false;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        v_old_is_tournament := OLD.type IN ('TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT','TOURNAMENT_START','TOURNAMENT_COMPLETION');
    END IF;
    IF TG_OP <> 'DELETE' THEN
        v_new_is_tournament := NEW.type IN ('TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT','TOURNAMENT_START','TOURNAMENT_COMPLETION');
    END IF;

    IF v_old_is_tournament THEN
        PERFORM tournament.assert_tournament_aggregate(OLD.subject_id);
    END IF;
    IF v_new_is_tournament AND (NOT v_old_is_tournament OR NEW.subject_id IS DISTINCT FROM OLD.subject_id) THEN
        PERFORM tournament.assert_tournament_aggregate(NEW.subject_id);
    END IF;
    RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_tournament_job_final_state ON technical.scheduled_job;
CREATE CONSTRAINT TRIGGER tr_tournament_job_final_state
AFTER INSERT OR UPDATE OR DELETE ON technical.scheduled_job
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION tournament.assert_tournament_from_job_row();

-- F7. Upgrade/final acceptance sweep.
DO $validate$
DECLARE r record;
BEGIN
    FOR r IN SELECT id FROM tournament.tournament LOOP
        PERFORM tournament.assert_tournament_aggregate(r.id);
    END LOOP;
END
$validate$;

-- F8. Delivery contract.
-- * At now >= approval/checkpoint/start/end, the due-state transition is resolved before any later competing cause.
-- * Ban expiry before checkpoint/start is effective at that boundary even if the Ban projection worker is late.
-- * Tournament timer jobs never use PAUSED; only PENDING/LEASED count as live execution guarantees.
-- * Manual Booking operating_session_id remains nullable exactly for the Product-approved out-of-hours path.



-- v1.1.16: final Tournament source baseline: server-authoritative command time, 24h approval, acceptance corrections, capacity-safe Ban restoration.
-- Contract: ONE command/cascade per transaction, READ COMMITTED. Begin before
-- business DML. Never accept a client/JVM timestamp or a user-settable GUC.
-- The protected temporary relation is owned by the function owner and disappears
-- at COMMIT/ROLLBACK; it adds no permanent domain table to the pgModeler model.
CREATE OR REPLACE FUNCTION tournament.begin_command(
    p_user_ids uuid[],
    p_venue_ids uuid[],
    p_resource_ids uuid[],
    p_tournament_ids uuid[],
    p_new_tournament_ids uuid[] DEFAULT ARRAY[]::uuid[]
)
RETURNS timestamptz
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_users uuid[];
    v_venues uuid[];
    v_resources uuid[];
    v_tournaments uuid[];
    v_new uuid[];
    v_now timestamptz;
    v_grantee record;
BEGIN
    IF current_setting('transaction_isolation') <> 'read committed' THEN
        RAISE EXCEPTION 'Tournament command requires READ COMMITTED and a post-lock re-read';
    END IF;
    IF to_regclass('pg_temp.e7gz_tournament_command_context') IS NOT NULL THEN
        RAISE EXCEPTION 'Exactly one Tournament command per transaction; commit/rollback before beginning another';
    END IF;
    IF array_position(p_user_ids, NULL) IS NOT NULL
       OR array_position(p_venue_ids, NULL) IS NOT NULL
       OR array_position(p_resource_ids, NULL) IS NOT NULL
       OR array_position(p_tournament_ids, NULL) IS NOT NULL
       OR array_position(p_new_tournament_ids, NULL) IS NOT NULL THEN
        RAISE EXCEPTION 'Command scope arrays must not contain NULL identifiers';
    END IF;

    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[])
      INTO v_tournaments FROM unnest(COALESCE(p_tournament_ids, ARRAY[]::uuid[])) x;
    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[])
      INTO v_new FROM unnest(COALESCE(p_new_tournament_ids, ARRAY[]::uuid[])) x;
    IF v_tournaments && v_new THEN
        RAISE EXCEPTION 'Existing and new Tournament scope must be disjoint';
    END IF;
    IF EXISTS (SELECT 1 FROM tournament.tournament t WHERE t.id = ANY(v_new)) THEN
        RAISE EXCEPTION 'A preallocated new Tournament id already exists';
    END IF;

    -- Discover the lock set, then acquire it in the baseline T10 order:
    -- Users/creators (sorted) -> Venues (sorted) -> Resources (sorted)
    -- -> Tournaments (sorted). Re-read/verify the set BEFORE sampling time.
    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[]) INTO v_users
      FROM (
          SELECT unnest(COALESCE(p_user_ids, ARRAY[]::uuid[])) x
          UNION SELECT t.creator_user_id FROM tournament.tournament t WHERE t.id = ANY(v_tournaments)
          UNION SELECT p.user_id FROM tournament.tournament_participant p WHERE p.tournament_id = ANY(v_tournaments)
      ) q WHERE x IS NOT NULL;
    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[]) INTO v_resources
      FROM (
          SELECT unnest(COALESCE(p_resource_ids, ARRAY[]::uuid[])) x
          UNION SELECT r.resource_id FROM tournament.tournament_resource r WHERE r.tournament_id = ANY(v_tournaments)
      ) q WHERE x IS NOT NULL;
    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[]) INTO v_venues
      FROM (
          SELECT unnest(COALESCE(p_venue_ids, ARRAY[]::uuid[])) x
          UNION SELECT t.venue_id FROM tournament.tournament t WHERE t.id = ANY(v_tournaments)
          UNION SELECT r.venue_id FROM resource.resource r WHERE r.id = ANY(v_resources)
      ) q WHERE x IS NOT NULL;

    PERFORM u.id FROM iam.user_account u WHERE u.id = ANY(v_users) ORDER BY u.id FOR UPDATE;
    PERFORM v.id FROM venue.venue v WHERE v.id = ANY(v_venues) ORDER BY v.id FOR UPDATE;
    PERFORM a.id FROM iam.venue_account a WHERE a.venue_id = ANY(v_venues) ORDER BY a.id FOR UPDATE;
    PERFORM r.id FROM resource.resource r WHERE r.id = ANY(v_resources) ORDER BY r.id FOR UPDATE;
    PERFORM t.id FROM tournament.tournament t WHERE t.id = ANY(v_tournaments) ORDER BY t.id FOR UPDATE;

    IF (SELECT count(*) FROM iam.user_account u WHERE u.id = ANY(v_users)) <> cardinality(v_users)
       OR (SELECT count(*) FROM venue.venue v WHERE v.id = ANY(v_venues)) <> cardinality(v_venues)
       OR (SELECT count(*) FROM resource.resource r WHERE r.id = ANY(v_resources)) <> cardinality(v_resources)
       OR (SELECT count(*) FROM tournament.tournament t WHERE t.id = ANY(v_tournaments)) <> cardinality(v_tournaments) THEN
        RAISE EXCEPTION 'Command scope contains a missing authoritative row';
    END IF;
    IF EXISTS (
        SELECT 1 FROM tournament.tournament t WHERE t.id = ANY(v_tournaments)
          AND (NOT (t.venue_id = ANY(v_venues))
               OR (t.creator_user_id IS NOT NULL AND NOT (t.creator_user_id = ANY(v_users))))
    ) OR EXISTS (
        SELECT 1 FROM tournament.tournament_participant p
         WHERE p.tournament_id = ANY(v_tournaments) AND NOT (p.user_id = ANY(v_users))
    ) OR EXISTS (
        SELECT 1 FROM tournament.tournament_resource r
         WHERE r.tournament_id = ANY(v_tournaments) AND NOT (r.resource_id = ANY(v_resources))
    ) OR EXISTS (
        SELECT 1 FROM resource.resource r
         WHERE r.id = ANY(v_resources) AND NOT (r.venue_id = ANY(v_venues))
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Tournament lock set changed while waiting; retry the whole transaction';
    END IF;

    CREATE TEMPORARY TABLE e7gz_tournament_command_context (
        singleton boolean PRIMARY KEY CHECK (singleton),
        transaction_id xid8 NOT NULL,
        captured_at timestamptz NOT NULL,
        user_ids uuid[] NOT NULL,
        venue_ids uuid[] NOT NULL,
        resource_ids uuid[] NOT NULL,
        tournament_ids uuid[] NOT NULL,
        new_tournament_ids uuid[] NOT NULL,
        created_tournament_ids uuid[] NOT NULL,
        rejection_outbox_event_ids bigint[] NOT NULL
    ) ON COMMIT DROP;
    REVOKE ALL ON TABLE pg_temp.e7gz_tournament_command_context FROM PUBLIC;
    -- Owner default privileges may grant newly-created tables to service/group
    -- roles. Remove those grants as well; PUBLIC-only revocation is insufficient.
    FOR v_grantee IN
        SELECT DISTINCT r.rolname
          FROM pg_catalog.pg_class c
          CROSS JOIN LATERAL pg_catalog.aclexplode(c.relacl) a
          JOIN pg_catalog.pg_roles r ON r.oid=a.grantee
         WHERE c.oid='pg_temp.e7gz_tournament_command_context'::regclass
           AND a.grantee <> c.relowner
    LOOP
        EXECUTE format('REVOKE ALL ON TABLE pg_temp.e7gz_tournament_command_context FROM %I', v_grantee.rolname);
    END LOOP;

    -- The ONLY clock read in the new Tournament command implementation.
    -- All authoritative lock waits above have completed at this point.
    v_now := clock_timestamp();
    INSERT INTO pg_temp.e7gz_tournament_command_context
    VALUES (true, pg_current_xact_id(), v_now, v_users, v_venues, v_resources,
            v_tournaments, v_new, ARRAY[]::uuid[], ARRAY[]::bigint[]);
    RETURN v_now;
END;
$function$;
REVOKE ALL ON FUNCTION tournament.begin_command(uuid[],uuid[],uuid[],uuid[],uuid[]) FROM PUBLIC;

CREATE OR REPLACE FUNCTION tournament.command_now()
RETURNS timestamptz
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE v_now timestamptz;
BEGIN
    -- Reject caller-created / spoofed temp tables before reading a single value.
    IF NOT EXISTS (
        SELECT 1 FROM pg_catalog.pg_class c
         WHERE c.oid = to_regclass('pg_temp.e7gz_tournament_command_context')
           AND c.relnamespace = pg_my_temp_schema()
           AND c.relpersistence = 't'
           AND c.relowner = (SELECT r.oid FROM pg_catalog.pg_roles r WHERE r.rolname = current_user)
    ) THEN
        RAISE EXCEPTION 'Missing trusted Tournament command context; call begin_command before business DML';
    END IF;
    SELECT c.captured_at INTO v_now
      FROM pg_temp.e7gz_tournament_command_context c
     WHERE c.singleton AND c.transaction_id = pg_current_xact_id();
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament command context belongs to another transaction or is incomplete'; END IF;
    RETURN v_now;
END;
$function$;
REVOKE ALL ON FUNCTION tournament.command_now() FROM PUBLIC;

CREATE OR REPLACE FUNCTION tournament.require_command_scope(
    p_tournament_id uuid DEFAULT NULL,
    p_venue_id uuid DEFAULT NULL,
    p_resource_id uuid DEFAULT NULL,
    p_user_id uuid DEFAULT NULL
)
RETURNS timestamptz
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE v_now timestamptz; c record;
BEGIN
    v_now := tournament.command_now();
    SELECT * INTO STRICT c FROM pg_temp.e7gz_tournament_command_context WHERE singleton;
    IF (p_tournament_id IS NOT NULL AND NOT (p_tournament_id = ANY(c.tournament_ids || c.new_tournament_ids)))
       OR (p_venue_id IS NOT NULL AND NOT (p_venue_id = ANY(c.venue_ids)))
       OR (p_resource_id IS NOT NULL AND NOT (p_resource_id = ANY(c.resource_ids)))
       OR (p_user_id IS NOT NULL AND NOT (p_user_id = ANY(c.user_ids))) THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Mutation exceeds the prelocked Tournament command scope; retry with the complete lock set';
    END IF;
    RETURN v_now;
END;
$function$;
REVOKE ALL ON FUNCTION tournament.require_command_scope(uuid,uuid,uuid,uuid) FROM PUBLIC;

CREATE OR REPLACE FUNCTION tournament.mark_created_in_command(p_tournament_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
BEGIN
    PERFORM tournament.command_now();
    IF pg_trigger_depth() = 0 THEN RAISE EXCEPTION 'Creation marker is a private trigger operation'; END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_temp.e7gz_tournament_command_context c
         WHERE c.singleton AND p_tournament_id = ANY(c.new_tournament_ids)
           AND NOT (p_tournament_id = ANY(c.created_tournament_ids))
    ) OR EXISTS (SELECT 1 FROM tournament.tournament t WHERE t.id = p_tournament_id) THEN
        RAISE EXCEPTION 'Tournament creation requires a fresh preallocated id in the current command';
    END IF;
    UPDATE pg_temp.e7gz_tournament_command_context
       SET created_tournament_ids = array_append(created_tournament_ids, p_tournament_id)
     WHERE singleton;
END;
$function$;
REVOKE ALL ON FUNCTION tournament.mark_created_in_command(uuid) FROM PUBLIC;

CREATE OR REPLACE FUNCTION tournament.created_in_command(p_tournament_id uuid)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE v_created boolean;
BEGIN
    PERFORM tournament.command_now();
    SELECT p_tournament_id = ANY(c.created_tournament_ids) INTO v_created
      FROM pg_temp.e7gz_tournament_command_context c WHERE c.singleton;
    RETURN COALESCE(v_created, false);
END;
$function$;
REVOKE ALL ON FUNCTION tournament.created_in_command(uuid) FROM PUBLIC;


CREATE OR REPLACE FUNCTION tournament.active_participant_count(p_tournament_id uuid, p_at timestamptz)
RETURNS integer
LANGUAGE sql
STABLE
AS $function$
SELECT COUNT(*)::integer
  FROM tournament.tournament_participant p
  JOIN iam.user_account u ON u.id = p.user_id
 WHERE p.tournament_id = p_tournament_id
   AND p.status = 'JOINED'
   AND u.anonymised_at IS NULL
   AND NOT EXISTS (
       SELECT 1
         FROM trust.ban_instance b
        WHERE b.user_id = p.user_id
          AND b.status = 'ACTIVE'
          AND b.activated_at <= p_at
          AND b.ends_at > p_at
   );
$function$;

CREATE OR REPLACE FUNCTION tournament.active_participant_count(p_tournament_id uuid)
RETURNS integer
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
BEGIN
    RETURN tournament.active_participant_count(p_tournament_id, tournament.require_command_scope(p_tournament_id));
END;
$function$;


-- Capacity occupancy is intentionally different from Active Participant count.
-- A BAN-only INELIGIBLE participant before Start keeps one capacity slot reserved so
-- automatic Ban expiry/lift restoration cannot overbook or evict another participant.
-- BAN-only INELIGIBLE still does NOT count toward the checkpoint minimum.
CREATE OR REPLACE FUNCTION tournament.capacity_occupied_count(p_tournament_id uuid)
RETURNS integer
LANGUAGE sql
STABLE
AS $function$
SELECT COUNT(*)::integer
  FROM tournament.tournament_participant p
 WHERE p.tournament_id = p_tournament_id
   AND (p.status = 'JOINED' OR (p.status = 'INELIGIBLE' AND p.ineligible_reason = 'BAN'));
$function$;

CREATE OR REPLACE FUNCTION tournament.highest_current_cancellation_reason(
    p_tournament_id uuid,
    p_from_status text,
    p_at timestamptz
)
RETURNS text
LANGUAGE plpgsql
STABLE
AS $function$
DECLARE
    t tournament.tournament%ROWTYPE;
    v_creator_status text;
    v_has_owner_review boolean;
    v_has_resource_emergency boolean;
    v_has_venue_emergency boolean;
    v_remaining integer;
    v_eval_at timestamptz;
BEGIN
    IF p_at IS NULL THEN RAISE EXCEPTION 'Cancellation resolver requires an explicit evaluation instant'; END IF;
    SELECT * INTO t FROM tournament.tournament WHERE id = p_tournament_id;
    IF NOT FOUND THEN RETURN NULL; END IF;

    -- A late worker must evaluate the cause set at the Product boundary, not at worker time.
    v_eval_at := p_at;
    IF p_from_status='PENDING_VENUE_APPROVAL' AND p_at >= t.approval_expires_at THEN
        v_eval_at := t.approval_expires_at;
    ELSIF p_from_status='WAITING_FOR_PLAYERS' AND p_at >= t.checkpoint_at THEN
        v_eval_at := t.checkpoint_at;
    ELSIF p_from_status='CONFIRMED' AND p_at >= t.start_at THEN
        v_eval_at := t.start_at;
    ELSIF p_from_status='ACTIVE' AND p_at >= t.end_at THEN
        v_eval_at := t.end_at;
    END IF;

    SELECT EXISTS (
        SELECT 1
          FROM tournament.tournament_resource tr
          JOIN operations.owner_review o ON o.resource_id = tr.resource_id
         WHERE tr.tournament_id = t.id
           AND o.entered_at <= v_eval_at
           AND (o.resolved_at IS NULL OR o.resolved_at > v_eval_at)
    ) INTO v_has_owner_review;

    SELECT EXISTS (
        SELECT 1
          FROM tournament.tournament_resource tr
          JOIN operations.emergency e ON e.resource_id = tr.resource_id AND e.scope = 'RESOURCE'
         WHERE tr.tournament_id = t.id
           AND e.declared_at <= v_eval_at
           AND (e.ended_at IS NULL OR e.ended_at > v_eval_at)
           AND tstzrange(t.start_at,t.end_at,'[)') && e.declared_period
    ) INTO v_has_resource_emergency;

    SELECT EXISTS (
        SELECT 1 FROM operations.emergency e
         WHERE e.scope = 'VENUE'
           AND e.venue_id = t.venue_id
           AND e.declared_at <= v_eval_at
           AND (e.ended_at IS NULL OR e.ended_at > v_eval_at)
           AND tstzrange(t.start_at,t.end_at,'[)') && e.declared_period
    ) INTO v_has_venue_emergency;

    IF p_from_status = 'ACTIVE' THEN
        SELECT COUNT(*)::integer INTO v_remaining
          FROM tournament.tournament_resource tr
         WHERE tr.tournament_id = t.id
           AND (tr.removed_at IS NULL OR tr.removed_at > v_eval_at)
           AND NOT EXISTS (
               SELECT 1 FROM operations.owner_review o
                WHERE o.resource_id = tr.resource_id
                  AND o.entered_at <= v_eval_at
                  AND (o.resolved_at IS NULL OR o.resolved_at > v_eval_at)
           )
           AND NOT EXISTS (
               SELECT 1 FROM operations.emergency e
                WHERE e.scope = 'RESOURCE'
                  AND e.resource_id = tr.resource_id
                  AND e.declared_at <= v_eval_at
                  AND (e.ended_at IS NULL OR e.ended_at > v_eval_at)
                  AND tstzrange(t.start_at,t.end_at,'[)') && e.declared_period
           );
        IF v_remaining > 0 THEN
            v_has_owner_review := false;
            v_has_resource_emergency := false;
        END IF;
    END IF;

    IF v_has_owner_review THEN RETURN 'RESOURCE_OWNER_REVIEW_REQUIRED'; END IF;
    IF v_has_resource_emergency THEN RETURN 'RESOURCE_EMERGENCY_OUTAGE'; END IF;
    IF v_has_venue_emergency THEN RETURN 'EMERGENCY_CLOSURE'; END IF;

    IF p_from_status = 'PENDING_VENUE_APPROVAL' AND EXISTS (
        SELECT 1 FROM iam.venue_account_restriction_interval r
         WHERE r.venue_id = t.venue_id
           AND r.disabled_at <= v_eval_at
           AND (r.reenabled_at IS NULL OR r.reenabled_at > v_eval_at)
    ) THEN
        RETURN 'VENUE_ACCOUNT_DISABLED';
    END IF;

    IF p_from_status = 'WAITING_FOR_PLAYERS'
       AND v_eval_at >= t.checkpoint_at
       AND tournament.active_participant_count(t.id, v_eval_at) < 8 THEN
        RETURN 'MINIMUM_PARTICIPANTS_NOT_REACHED';
    END IF;

    IF p_from_status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS') AND t.creator_user_id IS NOT NULL THEN
        SELECT v.to_status INTO v_creator_status
          FROM trust.verified_player_transition v
         WHERE v.user_id = t.creator_user_id
           AND v.occurred_at <= v_eval_at
         ORDER BY v.occurred_at DESC, v.id DESC
         LIMIT 1;
        IF v_creator_status = 'REVOKED' THEN
            RETURN 'CREATOR_VERIFIED_STATUS_REVOKED';
        END IF;
    END IF;

    RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.prepare_tournament_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz;
    v_marketplace text;
    v_account text;
    v_phone_verified boolean;
    v_anonymised_at timestamptz;
    v_vp_status text;
    v_last_terminal timestamptz;
BEGIN
    v_now := tournament.require_command_scope(NEW.id, NEW.venue_id, NULL, NEW.creator_user_id);
    PERFORM tournament.mark_created_in_command(NEW.id);
    NEW.created_at := v_now;
    NEW.end_at := NEW.start_at + make_interval(mins => NEW.nominal_minutes);
    NEW.checkpoint_at := NEW.start_at - interval '1 hour';
    NEW.version := 0;

    IF NEW.host_type = 'PLAYER' THEN
        NEW.status := 'PENDING_VENUE_APPROVAL';
        NEW.approval_expires_at := NEW.created_at + interval '24 hours';
    ELSIF NEW.host_type = 'VENUE' THEN
        NEW.status := 'WAITING_FOR_PLAYERS';
        NEW.approval_expires_at := NULL;
    END IF;

    SELECT v.marketplace_status INTO v_marketplace
      FROM venue.venue v WHERE v.id = NEW.venue_id FOR UPDATE;
    IF NOT FOUND OR v_marketplace <> 'ACTIVE' THEN
        RAISE EXCEPTION 'New Tournament creation requires Venue Marketplace ACTIVE';
    END IF;

    SELECT va.account_status INTO v_account
      FROM iam.venue_account va WHERE va.venue_id = NEW.venue_id;
    IF v_account IS DISTINCT FROM 'ENABLED' THEN
        RAISE EXCEPTION 'New Tournament creation requires Venue Account ENABLED';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM venue.venue_activity a WHERE a.venue_id = NEW.venue_id AND a.activity = NEW.activity) THEN
        RAISE EXCEPTION 'Tournament activity is not configured for the selected Venue';
    END IF;
    IF EXISTS (SELECT 1 FROM venue.venue_selling_block b WHERE b.venue_id = NEW.venue_id AND b.active) THEN
        RAISE EXCEPTION 'New Tournament creation is blocked by a Venue Operational Selling Block';
    END IF;

    IF NEW.host_type = 'PLAYER' AND NEW.created_at > NEW.checkpoint_at - interval '24 hours' THEN
        RAISE EXCEPTION 'Player Tournament request requires at least 24 hours before checkpointAt (25 hours before startAt)';
    ELSIF NEW.host_type = 'VENUE' AND NEW.created_at > NEW.start_at - interval '2 hours' THEN
        RAISE EXCEPTION 'Venue-hosted Tournament creation cutoff remains startAt - 2 hours';
    END IF;

    IF NEW.host_type = 'PLAYER' THEN
        SELECT u.phone_verified, u.anonymised_at
          INTO v_phone_verified, v_anonymised_at
          FROM iam.user_account u
         WHERE u.id = NEW.creator_user_id
         FOR UPDATE;
        IF NOT FOUND OR NOT v_phone_verified OR v_anonymised_at IS NOT NULL THEN
            RAISE EXCEPTION 'Player-hosted Tournament creator must be an Account-Verified active User';
        END IF;
        SELECT p.vp_operational_status INTO v_vp_status
          FROM trust.trust_projection p WHERE p.user_id = NEW.creator_user_id;
        IF v_vp_status IS DISTINCT FROM 'VERIFIED' THEN
            RAISE EXCEPTION 'Only operational VERIFIED may create a Player-hosted Tournament';
        END IF;
        IF EXISTS (
            SELECT 1 FROM trust.ban_instance b
             WHERE b.user_id = NEW.creator_user_id
               AND b.status = 'ACTIVE'
               AND b.activated_at <= NEW.created_at
               AND b.ends_at > NEW.created_at
        ) THEN
            RAISE EXCEPTION 'Banned User may not create a Tournament';
        END IF;

        SELECT MAX(h.occurred_at) INTO v_last_terminal
          FROM tournament.tournament t0
          JOIN tournament.tournament_history h ON h.tournament_id = t0.id
         WHERE t0.host_type = 'PLAYER'
           AND t0.creator_user_id = NEW.creator_user_id
           AND t0.venue_id = NEW.venue_id
           AND t0.start_at = NEW.start_at
           AND t0.end_at = NEW.end_at
           AND t0.status = 'REJECTED'
           AND h.to_status = 'REJECTED';
        IF v_last_terminal IS NOT NULL AND NEW.created_at < v_last_terminal + interval '5 minutes' THEN
            RAISE EXCEPTION 'Creator must wait 5 minutes before re-requesting the same Venue/time interval';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.guard_tournament_due_boundary()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz;
    v_expected text;
BEGIN
    v_now := tournament.require_command_scope(OLD.id, OLD.venue_id);
    IF OLD.status='PENDING_VENUE_APPROVAL' AND v_now >= OLD.approval_expires_at THEN
        v_expected := tournament.highest_current_cancellation_reason(OLD.id,'PENDING_VENUE_APPROVAL',OLD.approval_expires_at);
        IF v_expected IS NULL THEN
            IF NEW.status <> 'REJECTED' OR NEW.terminal_reason IS NOT NULL THEN
                RAISE EXCEPTION 'Approval deadline owns the next transition; expected REJECTED with no reason';
            END IF;
        ELSIF NEW.status <> 'CANCELLED' OR NEW.terminal_reason IS DISTINCT FROM v_expected THEN
            RAISE EXCEPTION 'A higher-priority condition at approval expiry requires CANCELLED/%', v_expected;
        END IF;

    ELSIF OLD.status='WAITING_FOR_PLAYERS' AND v_now >= OLD.checkpoint_at THEN
        -- A BAN that already expired at checkpoint must be restored first; a later worker cannot make
        -- the participant absent from the exact checkpoint count.
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_participant p
             WHERE p.tournament_id=OLD.id AND p.status='INELIGIBLE' AND p.ineligible_reason='BAN'
               AND NOT EXISTS (
                   SELECT 1 FROM trust.ban_instance b
                    WHERE b.user_id=p.user_id AND b.activated_at <= OLD.checkpoint_at AND b.ends_at > OLD.checkpoint_at
               )
        ) THEN
            RAISE EXCEPTION 'Restore BAN-only Participants whose Ban expired by checkpointAt before resolving the checkpoint';
        END IF;
        v_expected := tournament.highest_current_cancellation_reason(OLD.id,'WAITING_FOR_PLAYERS',OLD.checkpoint_at);
        IF v_expected IS NULL THEN
            IF NEW.status <> 'CONFIRMED' OR NEW.terminal_reason IS NOT NULL THEN
                RAISE EXCEPTION 'Checkpoint owns the next transition; expected CONFIRMED';
            END IF;
        ELSE
            IF NEW.status <> 'CANCELLED' OR NEW.terminal_reason IS DISTINCT FROM v_expected THEN
                RAISE EXCEPTION 'Checkpoint owns the next transition; expected CANCELLED/%', v_expected;
            END IF;
        END IF;

    ELSIF OLD.status='CONFIRMED' AND v_now >= OLD.start_at THEN
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_participant p
             WHERE p.tournament_id=OLD.id AND p.status='INELIGIBLE' AND p.ineligible_reason='BAN'
               AND NOT EXISTS (
                   SELECT 1 FROM trust.ban_instance b
                    WHERE b.user_id=p.user_id AND b.activated_at <= OLD.start_at AND b.ends_at > OLD.start_at
               )
        ) THEN
            RAISE EXCEPTION 'Restore BAN-only Participants whose Ban expired by startAt before resolving Tournament start';
        END IF;
        v_expected := tournament.highest_current_cancellation_reason(OLD.id,'CONFIRMED',OLD.start_at);
        IF v_expected IS NULL THEN
            IF NEW.status <> 'ACTIVE' OR NEW.terminal_reason IS NOT NULL THEN
                RAISE EXCEPTION 'startAt owns the next transition; expected ACTIVE';
            END IF;
        ELSE
            IF NEW.status <> 'CANCELLED' OR NEW.terminal_reason IS DISTINCT FROM v_expected THEN
                RAISE EXCEPTION 'startAt owns the next transition; expected CANCELLED/%', v_expected;
            END IF;
        END IF;

    ELSIF OLD.status='ACTIVE' AND v_now >= OLD.end_at THEN
        IF NEW.status <> 'COMPLETED' OR NEW.terminal_reason IS NOT NULL THEN
            RAISE EXCEPTION 'endAt owns the next transition; expected COMPLETED';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.guard_tournament_update()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz;
    v_count integer;
BEGIN
    v_now := tournament.require_command_scope(OLD.id, OLD.venue_id);
    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.venue_id IS DISTINCT FROM OLD.venue_id
       OR NEW.host_type IS DISTINCT FROM OLD.host_type
       OR NEW.creator_user_id IS DISTINCT FROM OLD.creator_user_id
       OR NEW.creator_participates IS DISTINCT FROM OLD.creator_participates
       OR NEW.activity IS DISTINCT FROM OLD.activity
       OR NEW.play_mode IS DISTINCT FROM OLD.play_mode
       OR NEW.capacity IS DISTINCT FROM OLD.capacity
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.start_at IS DISTINCT FROM OLD.start_at
       OR NEW.end_at IS DISTINCT FROM OLD.end_at
       OR NEW.nominal_minutes IS DISTINCT FROM OLD.nominal_minutes
       OR NEW.checkpoint_at IS DISTINCT FROM OLD.checkpoint_at
       OR NEW.approval_expires_at IS DISTINCT FROM OLD.approval_expires_at
       OR NEW.visibility IS DISTINCT FROM OLD.visibility
       OR NEW.invite_code IS DISTINCT FROM OLD.invite_code
       OR NEW.venue_cost_total IS DISTINCT FROM OLD.venue_cost_total
       OR NEW.creation_fee_snapshot IS DISTINCT FROM OLD.creation_fee_snapshot
       OR NEW.entry_fee IS DISTINCT FROM OLD.entry_fee
       OR NEW.prize IS DISTINCT FROM OLD.prize
       OR NEW.business_date IS DISTINCT FROM OLD.business_date
       OR NEW.operating_session_id IS DISTINCT FROM OLD.operating_session_id THEN
        RAISE EXCEPTION 'Tournament creation/commercial/session snapshots are immutable';
    END IF;

    IF OLD.status IN ('COMPLETED','REJECTED','CANCELLED') THEN
        RAISE EXCEPTION 'Terminal Tournament state is immutable';
    END IF;
    IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
        RAISE EXCEPTION 'Tournament UPDATE must be a semantic state transition';
    END IF;
    IF NEW.version <> OLD.version + 1 THEN
        RAISE EXCEPTION 'Tournament state transition must increment version exactly once';
    END IF;

    IF OLD.status = 'PENDING_VENUE_APPROVAL' AND NEW.status NOT IN ('WAITING_FOR_PLAYERS','REJECTED','CANCELLED') THEN
        RAISE EXCEPTION 'Invalid Tournament transition % -> %', OLD.status, NEW.status;
    ELSIF OLD.status = 'WAITING_FOR_PLAYERS' AND NEW.status NOT IN ('CONFIRMED','CANCELLED') THEN
        RAISE EXCEPTION 'Invalid Tournament transition % -> %', OLD.status, NEW.status;
    ELSIF OLD.status = 'CONFIRMED' AND NEW.status NOT IN ('ACTIVE','CANCELLED') THEN
        RAISE EXCEPTION 'Invalid Tournament transition % -> %', OLD.status, NEW.status;
    ELSIF OLD.status = 'ACTIVE' AND NEW.status NOT IN ('COMPLETED','CANCELLED') THEN
        RAISE EXCEPTION 'Invalid Tournament transition % -> %', OLD.status, NEW.status;
    END IF;

    IF OLD.status = 'PENDING_VENUE_APPROVAL' AND NEW.status = 'WAITING_FOR_PLAYERS' THEN
        IF v_now >= OLD.approval_expires_at THEN
            RAISE EXCEPTION 'Venue approval deadline is owned by expiry at now >= approvalExpiresAt';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM iam.venue_account va WHERE va.venue_id = OLD.venue_id AND va.account_status = 'ENABLED') THEN
            RAISE EXCEPTION 'Venue Accept requires Venue Account ENABLED';
        END IF;
        PERFORM tournament.assert_resources_operational(OLD.id, 'TOURNAMENT_APPROVAL_HOLD');
    ELSIF OLD.status = 'PENDING_VENUE_APPROVAL' AND NEW.status = 'REJECTED' THEN
        IF NEW.terminal_reason IS NOT NULL THEN
            RAISE EXCEPTION 'Tournament request rejection carries no reason';
        END IF;
        -- Venue before deadline; SYSTEM at/after deadline. Actor/timing is checked
        -- against the append-only history and matching audit in this transaction.
    ELSIF OLD.status = 'PENDING_VENUE_APPROVAL' AND NEW.status = 'CANCELLED' THEN
        IF NEW.terminal_reason IN ('VENUE_REJECTED_TOURNAMENT','VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME') THEN
            RAISE EXCEPTION 'Venue rejection and normal approval timeout use REJECTED without a reason';
        END IF;
        IF NEW.terminal_reason = 'CREATOR_CANCELLED' AND v_now >= OLD.checkpoint_at THEN
            RAISE EXCEPTION 'Creator may cancel only before the checkpoint';
        END IF;
    ELSIF OLD.status = 'WAITING_FOR_PLAYERS' AND NEW.status = 'CONFIRMED' THEN
        IF v_now < OLD.checkpoint_at THEN
            RAISE EXCEPTION 'Tournament checkpoint may not confirm before checkpointAt';
        END IF;
        v_count := tournament.active_participant_count(OLD.id, OLD.checkpoint_at);
        IF v_count < 8 THEN
            RAISE EXCEPTION 'Tournament cannot confirm with fewer than 8 Active Participants';
        END IF;
        PERFORM tournament.assert_resources_operational(OLD.id, 'TOURNAMENT_HOLD');
    ELSIF OLD.status = 'WAITING_FOR_PLAYERS' AND NEW.status = 'CANCELLED' THEN
        IF NEW.terminal_reason = 'MINIMUM_PARTICIPANTS_NOT_REACHED' THEN
            IF v_now < OLD.checkpoint_at OR tournament.active_participant_count(OLD.id, OLD.checkpoint_at) >= 8 THEN
                RAISE EXCEPTION 'MINIMUM_PARTICIPANTS_NOT_REACHED requires checkpoint ownership and fewer than 8 Active Participants';
            END IF;
        ELSIF NEW.terminal_reason = 'CREATOR_CANCELLED' AND v_now >= OLD.checkpoint_at THEN
            RAISE EXCEPTION 'Creator may cancel only before the checkpoint';
        END IF;
    ELSIF OLD.status = 'CONFIRMED' AND NEW.status = 'ACTIVE' THEN
        IF v_now < OLD.start_at THEN
            RAISE EXCEPTION 'Tournament may not start before startAt';
        END IF;
        PERFORM tournament.assert_resources_operational(OLD.id, 'TOURNAMENT_HOLD');
    ELSIF OLD.status = 'ACTIVE' AND NEW.status = 'COMPLETED' THEN
        IF v_now < OLD.end_at THEN
            RAISE EXCEPTION 'Tournament may not complete before endAt';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.guard_tournament_resource()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz;
    t tournament.tournament%ROWTYPE;
    r resource.resource%ROWTYPE;
    rr inventory.resource_reservation%ROWTYPE;
    rr_old inventory.resource_reservation%ROWTYPE;
    v_expected_price numeric;
    v_expected_type text;
BEGIN
    v_now := tournament.require_command_scope(COALESCE(NEW.tournament_id, OLD.tournament_id), NULL, COALESCE(NEW.resource_id, OLD.resource_id));
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Tournament Resource assignments are historical and may not be deleted';
    END IF;

    SELECT * INTO t FROM tournament.tournament WHERE id = NEW.tournament_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament does not exist'; END IF;
    SELECT * INTO r FROM resource.resource WHERE id = NEW.resource_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament Resource does not exist'; END IF;

    IF TG_OP = 'INSERT' THEN
        IF NOT tournament.created_in_command(t.id) THEN
            RAISE EXCEPTION 'Tournament Resources may be added only in the Tournament creation transaction';
        END IF;
        IF (SELECT COUNT(*) FROM tournament.tournament_resource x WHERE x.tournament_id = t.id) >= 4 THEN
            RAISE EXCEPTION 'Tournament maximum Resource count is 4';
        END IF;
        IF r.venue_id IS DISTINCT FROM t.venue_id OR r.activity IS DISTINCT FROM t.activity THEN
            RAISE EXCEPTION 'Tournament Resource must belong to the same Venue and Activity';
        END IF;
        IF r.base_state <> 'ACTIVE' OR r.operational_restriction <> 'NONE'
           OR EXISTS (SELECT 1 FROM resource.resource_selling_block b WHERE b.resource_id = r.id AND b.active)
           OR EXISTS (SELECT 1 FROM venue.venue_selling_block b WHERE b.venue_id = t.venue_id AND b.active) THEN
            RAISE EXCEPTION 'Tournament Resource is not operationally eligible at creation';
        END IF;
        IF t.activity = 'PLAYSTATION' THEN
            IF NEW.console_type_snapshot IS DISTINCT FROM r.console_type THEN
                RAISE EXCEPTION 'PlayStation Tournament console snapshot must equal Resource console type';
            END IF;
        ELSIF NEW.console_type_snapshot IS NOT NULL THEN
            RAISE EXCEPTION 'Billiards/Ping Pong Tournament Resource console snapshot must be NULL';
        END IF;
        v_expected_price := tournament.expected_resource_price(r.id, t.activity, t.play_mode);
        IF NEW.hourly_price_snapshot IS DISTINCT FROM v_expected_price THEN
            RAISE EXCEPTION 'Tournament Resource hourly price snapshot % does not equal effective creation price %', NEW.hourly_price_snapshot, v_expected_price;
        END IF;
        v_expected_type := CASE WHEN t.status = 'PENDING_VENUE_APPROVAL' THEN 'TOURNAMENT_APPROVAL_HOLD' ELSE 'TOURNAMENT_HOLD' END;
        SELECT * INTO rr FROM inventory.resource_reservation WHERE id = NEW.reservation_id;
        IF NOT FOUND OR rr.tournament_id IS DISTINCT FROM t.id OR rr.resource_id IS DISTINCT FROM r.id
           OR rr.reservation_type IS DISTINCT FROM v_expected_type OR NOT rr.active_flag
           OR rr.planned_start IS DISTINCT FROM t.start_at OR rr.planned_end IS DISTINCT FROM t.end_at THEN
            RAISE EXCEPTION 'Tournament Resource requires a matching active % reservation', v_expected_type;
        END IF;
        NEW.removed_at := NULL;
        NEW.removal_cause := NULL;
        RETURN NEW;
    END IF;

    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.tournament_id IS DISTINCT FROM OLD.tournament_id
       OR NEW.resource_id IS DISTINCT FROM OLD.resource_id
       OR NEW.console_type_snapshot IS DISTINCT FROM OLD.console_type_snapshot
       OR NEW.hourly_price_snapshot IS DISTINCT FROM OLD.hourly_price_snapshot THEN
        RAISE EXCEPTION 'Tournament Resource identity and historical snapshots are immutable';
    END IF;

    IF OLD.reservation_id IS DISTINCT FROM NEW.reservation_id THEN
        SELECT * INTO rr_old FROM inventory.resource_reservation WHERE id = OLD.reservation_id;
        SELECT * INTO rr FROM inventory.resource_reservation WHERE id = NEW.reservation_id;
        IF NOT FOUND OR rr_old.reservation_type <> 'TOURNAMENT_APPROVAL_HOLD'
           OR rr_old.active_flag OR rr.reservation_type <> 'TOURNAMENT_HOLD' OR NOT rr.active_flag
           OR rr_old.tournament_id IS DISTINCT FROM t.id OR rr.tournament_id IS DISTINCT FROM t.id
           OR rr_old.resource_id IS DISTINCT FROM NEW.resource_id OR rr.resource_id IS DISTINCT FROM NEW.resource_id
           OR rr_old.planned_start IS DISTINCT FROM t.start_at OR rr_old.planned_end IS DISTINCT FROM t.end_at
           OR rr.planned_start IS DISTINCT FROM t.start_at OR rr.planned_end IS DISTINCT FROM t.end_at THEN
            RAISE EXCEPTION 'reservation_id may change once only when an Approval Hold is released and replaced by a standard Tournament Hold';
        END IF;
    END IF;

    IF OLD.removed_at IS NOT NULL THEN
        IF NEW.removed_at IS DISTINCT FROM OLD.removed_at OR NEW.removal_cause IS DISTINCT FROM OLD.removal_cause
           OR NEW.reservation_id IS DISTINCT FROM OLD.reservation_id THEN
            RAISE EXCEPTION 'Removed Tournament Resource history is immutable';
        END IF;
    ELSIF NEW.removed_at IS NOT NULL THEN
        IF t.status <> 'ACTIVE' THEN
            RAISE EXCEPTION 'A Tournament Resource may be removed only while the Tournament is ACTIVE';
        END IF;
        NEW.removed_at := v_now;
        IF NEW.removal_cause NOT IN ('RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED') THEN
            RAISE EXCEPTION 'ACTIVE Tournament Resource removal requires a canonical operational cause';
        END IF;
    ELSIF NEW.removal_cause IS NOT NULL THEN
        RAISE EXCEPTION 'removal_cause requires removed_at';
    END IF;

    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.guard_resource_due_boundary()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz; t tournament.tournament%ROWTYPE;
BEGIN
    v_now := tournament.require_command_scope(OLD.tournament_id, NULL, OLD.resource_id);
    IF TG_OP='UPDATE' AND OLD.removed_at IS NULL AND NEW.removed_at IS NOT NULL THEN
        SELECT * INTO t FROM tournament.tournament WHERE id=OLD.tournament_id;
        IF t.status='ACTIVE' AND v_now >= t.end_at THEN
            RAISE EXCEPTION 'Tournament completion boundary owns the state before ACTIVE Resource removal at/after endAt';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.guard_tournament_participant()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz;
    t tournament.tournament%ROWTYPE;
    u iam.user_account%ROWTYPE;
    v_active integer;
    v_occupied integer;
    v_banned boolean;
    v_boundary_restore boolean := false;
BEGIN
    v_now := tournament.require_command_scope(COALESCE(NEW.tournament_id, OLD.tournament_id), NULL, NULL, COALESCE(NEW.user_id, OLD.user_id));
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Tournament Participant history may not be deleted';
    END IF;

    SELECT * INTO t FROM tournament.tournament WHERE id = NEW.tournament_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament does not exist'; END IF;
    SELECT * INTO u FROM iam.user_account WHERE id = NEW.user_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament Participant User does not exist'; END IF;
    SELECT EXISTS (
        SELECT 1 FROM trust.ban_instance b
         WHERE b.user_id = NEW.user_id AND b.status = 'ACTIVE'
           AND b.activated_at <= v_now AND b.ends_at > v_now
    ) INTO v_banned;

    IF TG_OP='UPDATE' AND OLD.status='INELIGIBLE' AND OLD.ineligible_reason='BAN' AND NEW.status='JOINED' THEN
        IF t.status='WAITING_FOR_PLAYERS' AND v_now >= t.checkpoint_at
           AND NOT EXISTS (
               SELECT 1 FROM trust.ban_instance b
                WHERE b.user_id=NEW.user_id AND b.activated_at <= t.checkpoint_at AND b.ends_at > t.checkpoint_at
           ) THEN
            v_boundary_restore := true;
        ELSIF t.status='CONFIRMED' AND v_now >= t.start_at
           AND NOT EXISTS (
               SELECT 1 FROM trust.ban_instance b
                WHERE b.user_id=NEW.user_id AND b.activated_at <= t.start_at AND b.ends_at > t.start_at
           ) THEN
            v_boundary_restore := true;
        END IF;
    END IF;

    -- Once a due boundary is reached, no participant mutation may change its result.
    -- The only exception is catching up a BAN-only restoration that was already effective at that boundary.
    IF t.status='WAITING_FOR_PLAYERS' AND v_now >= t.checkpoint_at AND NOT v_boundary_restore THEN
        RAISE EXCEPTION 'Tournament checkpoint is overdue; resolve the checkpoint before participant mutation';
    END IF;
    IF t.status='CONFIRMED' AND v_now >= t.start_at AND NOT v_boundary_restore THEN
        RAISE EXCEPTION 'Tournament start is due; resolve startAt before participant mutation';
    END IF;

    IF TG_OP = 'INSERT' THEN
        NEW.joined_at := v_now;
        NEW.status_changed_at := NEW.joined_at;
        NEW.status := 'JOINED';
        NEW.left_at := NULL;
        NEW.removed_at := NULL;
        NEW.ineligible_reason := NULL;

        IF NOT u.phone_verified OR u.anonymised_at IS NOT NULL OR v_banned THEN
            RAISE EXCEPTION 'Tournament join requires an Account-Verified, non-banned active User';
        END IF;
        IF t.status = 'PENDING_VENUE_APPROVAL' THEN
            IF t.host_type <> 'PLAYER' OR NOT t.creator_participates OR NEW.user_id IS DISTINCT FROM t.creator_user_id
               OR NOT tournament.created_in_command(t.id) THEN
                RAISE EXCEPTION 'While PENDING_VENUE_APPROVAL only the participating Player Creator may have a Participant row';
            END IF;
        ELSIF t.status NOT IN ('WAITING_FOR_PLAYERS','CONFIRMED') OR v_now >= t.start_at THEN
            RAISE EXCEPTION 'Users may join only WAITING_FOR_PLAYERS/CONFIRMED before startAt';
        END IF;
        v_occupied := tournament.capacity_occupied_count(t.id);
        IF v_occupied >= t.capacity THEN
            RAISE EXCEPTION 'Tournament participant capacity is full, including BAN-only reserved slots';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.tournament_id IS DISTINCT FROM OLD.tournament_id
       OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.joined_at IS DISTINCT FROM OLD.joined_at THEN
        RAISE EXCEPTION 'Tournament Participant identity/join timestamp is immutable';
    END IF;
    IF OLD.left_at IS NOT NULL AND NEW.left_at IS DISTINCT FROM OLD.left_at THEN
        RAISE EXCEPTION 'left_at is immutable once recorded';
    END IF;
    IF OLD.removed_at IS NOT NULL AND NEW.removed_at IS DISTINCT FROM OLD.removed_at THEN
        RAISE EXCEPTION 'removed_at is immutable once recorded';
    END IF;
    IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
        IF NEW.status_changed_at IS DISTINCT FROM OLD.status_changed_at
           OR NEW.left_at IS DISTINCT FROM OLD.left_at OR NEW.removed_at IS DISTINCT FROM OLD.removed_at
           OR NEW.ineligible_reason IS DISTINCT FROM OLD.ineligible_reason THEN
            RAISE EXCEPTION 'Participant lifecycle facts change only with a status transition';
        END IF;
        RETURN NEW;
    END IF;
    IF t.status IN ('COMPLETED','REJECTED','CANCELLED') THEN
        RAISE EXCEPTION 'Participant state cannot change after Tournament terminal state';
    END IF;

    NEW.status_changed_at := v_now;
    IF NEW.status = 'JOINED' THEN
        IF NOT v_boundary_restore AND (v_now >= t.start_at OR NOT (
               t.status IN ('WAITING_FOR_PLAYERS','CONFIRMED')
               OR (t.status='PENDING_VENUE_APPROVAL' AND t.host_type='PLAYER' AND t.creator_participates AND NEW.user_id=t.creator_user_id)
           )) THEN
            RAISE EXCEPTION 'Participant may return/join only before startAt in an eligible Tournament lifecycle state';
        END IF;
        IF NOT u.phone_verified OR u.anonymised_at IS NOT NULL OR v_banned THEN
            RAISE EXCEPTION 'JOINED participant must be Account-Verified, active and not banned';
        END IF;
        NEW.ineligible_reason := NULL;
        v_occupied := tournament.capacity_occupied_count(t.id);
        -- BAN-only restoration consumes its already-reserved capacity slot, so it must
        -- not be rejected merely because all slots are occupied. Other returns still
        -- require a free slot.
        IF NOT (OLD.status='JOINED' OR (OLD.status='INELIGIBLE' AND OLD.ineligible_reason='BAN'))
           AND v_occupied >= t.capacity THEN
            RAISE EXCEPTION 'Tournament participant capacity is full, including BAN-only reserved slots';
        END IF;
    ELSIF NEW.status = 'LEFT' THEN
        IF v_now >= t.start_at THEN
            RAISE EXCEPTION 'Participant may Leave only before startAt';
        END IF;
        IF NEW.left_at IS NULL THEN NEW.left_at := NEW.status_changed_at; END IF;
    ELSIF NEW.status = 'REMOVED' THEN
        IF v_now >= t.start_at THEN
            RAISE EXCEPTION 'Organizer may Remove a Participant only before startAt';
        END IF;
        IF NEW.removed_at IS NULL THEN NEW.removed_at := NEW.status_changed_at; END IF;
    ELSIF NEW.status = 'INELIGIBLE' THEN
        IF v_banned THEN
            NEW.ineligible_reason := 'BAN';
        ELSIF u.anonymised_at IS NOT NULL THEN
            NEW.ineligible_reason := 'ACCOUNT_DELETED';
        ELSIF NULLIF(BTRIM(NEW.ineligible_reason),'') IS NULL THEN
            RAISE EXCEPTION 'INELIGIBLE requires an explicit reason';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.prepare_tournament_history()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz;
    t tournament.tournament%ROWTYPE;
    v_seq bigint;
    v_prev_status text;
BEGIN
    v_now := tournament.require_command_scope(NEW.tournament_id);
    SELECT * INTO t FROM tournament.tournament WHERE id = NEW.tournament_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament history requires an existing Tournament'; END IF;

    SELECT h.sequence, h.to_status INTO v_seq, v_prev_status
      FROM tournament.tournament_history h
     WHERE h.tournament_id = NEW.tournament_id
     ORDER BY h.sequence DESC LIMIT 1;

    IF v_seq IS NULL THEN
        NEW.sequence := 1;
        NEW.from_status := NULL;
        NEW.occurred_at := t.created_at;
    ELSE
        NEW.sequence := v_seq + 1;
        NEW.from_status := v_prev_status;
        NEW.occurred_at := v_now;
    END IF;
    IF NEW.to_status IS NULL THEN RAISE EXCEPTION 'Tournament history to_status is required'; END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.assert_tournament_history_chain(p_tournament_id uuid)
RETURNS void
LANGUAGE plpgsql
AS $function$
DECLARE
    t tournament.tournament%ROWTYPE;
    h record;
    a audit.audit_event%ROWTYPE;
    v_prev text := NULL;
    v_expected text;
    v_first boolean := true;
BEGIN
    SELECT * INTO t FROM tournament.tournament WHERE id = p_tournament_id;
    IF NOT FOUND THEN RETURN; END IF;

    FOR h IN SELECT * FROM tournament.tournament_history WHERE tournament_id=t.id ORDER BY sequence LOOP
        IF v_first THEN
            IF h.sequence <> 1 OR h.from_status IS NOT NULL OR h.occurred_at IS DISTINCT FROM t.created_at THEN
                RAISE EXCEPTION 'Tournament first history row must be sequence 1, from_status NULL and occur at created_at';
            END IF;
            IF (t.host_type='PLAYER' AND h.to_status <> 'PENDING_VENUE_APPROVAL')
               OR (t.host_type='VENUE' AND h.to_status <> 'WAITING_FOR_PLAYERS') THEN
                RAISE EXCEPTION 'Tournament first history state does not match host type';
            END IF;
            v_first := false;
        ELSE
            IF h.from_status IS DISTINCT FROM v_prev THEN
                RAISE EXCEPTION 'Tournament history chain is not contiguous at sequence %', h.sequence;
            END IF;
        END IF;

        SELECT * INTO a FROM audit.audit_event ae
         WHERE ae.subject_type='TOURNAMENT' AND ae.subject_id=t.id
           AND ae.action='TOURNAMENT_STATUS_TRANSITION'
           AND ae.occurred_at=h.occurred_at
           AND ae.actor_type=h.actor_type
           AND ae.actor_id IS NOT DISTINCT FROM h.actor_id
           AND ae.correlation_id=h.correlation_id
         LIMIT 1;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Tournament history sequence % requires matching audit_event', h.sequence;
        END IF;

        IF h.actor_type='CUSTOMER' AND h.actor_id IS DISTINCT FROM t.creator_user_id THEN
            RAISE EXCEPTION 'Tournament CUSTOMER state actor must be the Player Creator';
        ELSIF h.actor_type='VENUE' AND NOT EXISTS (
            SELECT 1 FROM iam.venue_account va WHERE va.id=h.actor_id AND va.venue_id=t.venue_id
        ) THEN
            RAISE EXCEPTION 'Tournament VENUE actor must belong to the Tournament Venue';
        ELSIF h.actor_type='ADMIN' AND NOT EXISTS (SELECT 1 FROM iam.admin_account ad WHERE ad.id=h.actor_id) THEN
            RAISE EXCEPTION 'Tournament ADMIN actor does not exist';
        END IF;

        IF h.from_status IS NULL THEN
            IF t.host_type='PLAYER' AND (h.actor_type<>'CUSTOMER' OR h.actor_id IS DISTINCT FROM t.creator_user_id) THEN
                RAISE EXCEPTION 'Player-hosted Tournament creation history requires Creator actor';
            ELSIF t.host_type='VENUE' AND h.actor_type<>'VENUE' THEN
                RAISE EXCEPTION 'Venue-hosted Tournament creation history requires Venue actor';
            END IF;
        ELSIF h.from_status='PENDING_VENUE_APPROVAL' AND h.to_status='WAITING_FOR_PLAYERS' THEN
            IF h.actor_type<>'VENUE' OR h.terminal_reason IS NOT NULL OR h.occurred_at >= t.approval_expires_at THEN
                RAISE EXCEPTION 'Venue Accept transition is invalid';
            END IF;
        ELSIF h.from_status='PENDING_VENUE_APPROVAL' AND h.to_status='REJECTED' THEN
            IF h.terminal_reason IS NOT NULL OR NOT (
                (h.actor_type='VENUE' AND h.occurred_at < t.approval_expires_at)
                OR (h.actor_type='SYSTEM' AND h.occurred_at >= t.approval_expires_at)
            ) THEN
                RAISE EXCEPTION 'Rejection requires Venue before expiry or SYSTEM at/after expiry, with no reason';
            END IF;
            v_expected := tournament.highest_current_cancellation_reason(t.id,h.from_status,h.occurred_at);
            IF v_expected IS NOT NULL THEN
                RAISE EXCEPTION 'Rejection cannot bypass a higher-priority cancellation condition: %', v_expected;
            END IF;
        ELSIF h.from_status='PENDING_VENUE_APPROVAL' AND h.to_status='CANCELLED' THEN
            IF h.terminal_reason='CREATOR_CANCELLED' THEN
                IF h.actor_type<>'CUSTOMER' OR h.occurred_at >= t.checkpoint_at THEN RAISE EXCEPTION 'Creator cancellation is invalid'; END IF;
            ELSIF h.terminal_reason IN ('VENUE_ACCOUNT_DISABLED','CREATOR_VERIFIED_STATUS_REVOKED','EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED') THEN
                IF h.actor_type<>'SYSTEM' THEN RAISE EXCEPTION 'System Tournament cascade requires SYSTEM actor'; END IF;
            ELSIF h.terminal_reason='ADMIN_CANCELLED' THEN
                IF h.actor_type<>'ADMIN' THEN RAISE EXCEPTION 'Admin cancellation requires ADMIN actor'; END IF;
            ELSE RAISE EXCEPTION 'Invalid PENDING Tournament cancellation reason %', h.terminal_reason; END IF;
        ELSIF h.from_status='WAITING_FOR_PLAYERS' AND h.to_status='CONFIRMED' THEN
            IF h.actor_type<>'SYSTEM' OR h.terminal_reason IS NOT NULL OR h.occurred_at < t.checkpoint_at THEN
                RAISE EXCEPTION 'Tournament checkpoint confirmation transition is invalid';
            END IF;
        ELSIF h.from_status='WAITING_FOR_PLAYERS' AND h.to_status='CANCELLED' THEN
            IF h.terminal_reason='MINIMUM_PARTICIPANTS_NOT_REACHED' THEN
                IF h.actor_type<>'SYSTEM' OR h.occurred_at < t.checkpoint_at THEN RAISE EXCEPTION 'Minimum-participant cancellation is invalid'; END IF;
            ELSIF h.terminal_reason='CREATOR_CANCELLED' THEN
                IF h.actor_type<>'CUSTOMER' OR h.occurred_at >= t.checkpoint_at THEN RAISE EXCEPTION 'Creator cancellation is invalid'; END IF;
            ELSIF h.terminal_reason='VENUE_CANCELLED' THEN
                IF h.actor_type<>'VENUE' THEN RAISE EXCEPTION 'Venue cancellation requires VENUE actor'; END IF;
            ELSIF h.terminal_reason IN ('CREATOR_VERIFIED_STATUS_REVOKED','EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED') THEN
                IF h.actor_type<>'SYSTEM' THEN RAISE EXCEPTION 'System Tournament cascade requires SYSTEM actor'; END IF;
            ELSIF h.terminal_reason='ADMIN_CANCELLED' THEN
                IF h.actor_type<>'ADMIN' THEN RAISE EXCEPTION 'Admin cancellation requires ADMIN actor'; END IF;
            ELSE RAISE EXCEPTION 'Invalid WAITING Tournament cancellation reason %', h.terminal_reason; END IF;
        ELSIF h.from_status='CONFIRMED' AND h.to_status='ACTIVE' THEN
            IF h.actor_type<>'SYSTEM' OR h.terminal_reason IS NOT NULL OR h.occurred_at < t.start_at THEN
                RAISE EXCEPTION 'Tournament start transition is invalid';
            END IF;
        ELSIF h.from_status='CONFIRMED' AND h.to_status='CANCELLED' THEN
            IF h.terminal_reason='VENUE_CANCELLED' THEN
                IF h.actor_type<>'VENUE' OR NOT a.owner_password_used OR a.owner_password_outcome<>'SUCCESS' THEN
                    RAISE EXCEPTION 'Venue cancellation of CONFIRMED Tournament requires successful Owner Password audit';
                END IF;
            ELSIF h.terminal_reason IN ('EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED') THEN
                IF h.actor_type<>'SYSTEM' THEN RAISE EXCEPTION 'Operational cancellation requires SYSTEM actor'; END IF;
            ELSIF h.terminal_reason='ADMIN_CANCELLED' THEN
                IF h.actor_type<>'ADMIN' THEN RAISE EXCEPTION 'Admin cancellation requires ADMIN actor'; END IF;
            ELSE RAISE EXCEPTION 'Invalid CONFIRMED Tournament cancellation reason %', h.terminal_reason; END IF;
        ELSIF h.from_status='ACTIVE' AND h.to_status='COMPLETED' THEN
            IF h.actor_type<>'SYSTEM' OR h.terminal_reason IS NOT NULL OR h.occurred_at < t.end_at THEN
                RAISE EXCEPTION 'Tournament completion transition is invalid';
            END IF;
        ELSIF h.from_status='ACTIVE' AND h.to_status='CANCELLED' THEN
            IF h.terminal_reason IN ('EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED') THEN
                IF h.actor_type<>'SYSTEM' THEN RAISE EXCEPTION 'Operational ACTIVE cancellation requires SYSTEM actor'; END IF;
            ELSIF h.terminal_reason='TOURNAMENT_OPERATIONAL_TERMINATION' THEN
                IF h.actor_type<>'VENUE' OR NOT a.owner_password_used OR a.owner_password_outcome<>'SUCCESS'
                   OR NULLIF(BTRIM(a.reason),'') IS NULL THEN
                    RAISE EXCEPTION 'Tournament Operational Termination requires Venue actor, Owner Password and mandatory reason';
                END IF;
            ELSIF h.terminal_reason='ADMIN_CANCELLED' THEN
                IF h.actor_type<>'ADMIN' THEN RAISE EXCEPTION 'ACTIVE Admin support cancellation requires ADMIN actor'; END IF;
            ELSE RAISE EXCEPTION 'Invalid ACTIVE Tournament cancellation reason %', h.terminal_reason; END IF;
        ELSE
            RAISE EXCEPTION 'Invalid Tournament state transition % -> %', h.from_status, h.to_status;
        END IF;

        IF h.to_status='CANCELLED' THEN
            v_expected := tournament.highest_current_cancellation_reason(t.id,h.from_status,h.occurred_at);
            IF v_expected IS NOT NULL AND h.terminal_reason IS DISTINCT FROM v_expected THEN
                RAISE EXCEPTION 'Tournament terminal reason % violates frozen priority; expected %', h.terminal_reason, v_expected;
            END IF;
        END IF;
        v_prev := h.to_status;
    END LOOP;

    IF v_first THEN RAISE EXCEPTION 'Tournament requires append-only state history'; END IF;
    IF v_prev IS DISTINCT FROM t.status THEN RAISE EXCEPTION 'Tournament current status does not match latest history state'; END IF;
    SELECT hist.terminal_reason INTO v_expected
      FROM tournament.tournament_history AS hist
     WHERE hist.tournament_id = t.id
     ORDER BY hist.sequence DESC
     LIMIT 1;
    IF v_expected IS DISTINCT FROM t.terminal_reason THEN
        RAISE EXCEPTION 'Tournament terminal_reason does not match latest history transition';
    END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.assert_terminal_reason_provenance()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_expected text;
    t tournament.tournament%ROWTYPE;
BEGIN
    IF NEW.to_status NOT IN ('CANCELLED','REJECTED') THEN RETURN NULL; END IF;
    SELECT * INTO t FROM tournament.tournament WHERE id=NEW.tournament_id;
    v_expected := tournament.highest_current_cancellation_reason(NEW.tournament_id,NEW.from_status,NEW.occurred_at);

    IF NEW.to_status='REJECTED' THEN
        IF NEW.terminal_reason IS NOT NULL OR v_expected IS NOT NULL THEN
            RAISE EXCEPTION 'Request rejection carries no reason and cannot override a higher-priority condition';
        END IF;
        RETURN NULL;
    END IF;

    IF NEW.terminal_reason IN ('RESOURCE_OWNER_REVIEW_REQUIRED','RESOURCE_EMERGENCY_OUTAGE','EMERGENCY_CLOSURE','VENUE_ACCOUNT_DISABLED','MINIMUM_PARTICIPANTS_NOT_REACHED','CREATOR_VERIFIED_STATUS_REVOKED') THEN
        IF v_expected IS NULL OR v_expected IS DISTINCT FROM NEW.terminal_reason THEN
            RAISE EXCEPTION 'Condition-driven Tournament reason % lacks matching highest-priority producer (expected %)', NEW.terminal_reason, v_expected;
        END IF;
    ELSIF NEW.terminal_reason='VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME' THEN
        RAISE EXCEPTION 'Normal Tournament approval expiry uses REJECTED without a terminal reason';
    ELSIF NEW.terminal_reason IN ('CREATOR_CANCELLED','VENUE_CANCELLED','ADMIN_CANCELLED','TOURNAMENT_OPERATIONAL_TERMINATION') THEN
        IF v_expected IS NOT NULL THEN
            RAISE EXCEPTION 'Explicit Tournament cancellation cannot bypass higher frozen reason %', v_expected;
        END IF;
    END IF;
    RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.assert_tournament_aggregate(p_tournament_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz;
    t tournament.tournament%ROWTYPE;
    s venue.operating_session%ROWTYPE;
    v_resources integer;
    v_unremoved integer;
    v_expected_cost numeric(12,2);
    v_participant_eval_at timestamptz;
BEGIN
    SELECT * INTO t FROM tournament.tournament WHERE id=p_tournament_id;
    IF NOT FOUND THEN RETURN; END IF;
    v_now := tournament.require_command_scope(t.id, t.venue_id);

    SELECT * INTO s FROM venue.operating_session WHERE id=t.operating_session_id;
    IF NOT FOUND OR s.venue_id IS DISTINCT FROM t.venue_id
       OR t.start_at < lower(s.session_period) OR t.end_at > upper(s.session_period)
       OR t.business_date IS DISTINCT FROM s.operating_day THEN
        RAISE EXCEPTION 'Tournament must fit completely inside one matching Venue Operating Session and businessDate';
    END IF;

    SELECT COUNT(*)::integer,
           COALESCE(SUM(ROUND(tr.hourly_price_snapshot * t.nominal_minutes / 60.0,2)),0)::numeric(12,2)
      INTO v_resources, v_expected_cost
      FROM tournament.tournament_resource tr WHERE tr.tournament_id=t.id;
    IF v_resources NOT BETWEEN 1 AND 4 THEN RAISE EXCEPTION 'Tournament requires exactly 1 to 4 Resource rows'; END IF;
    IF t.venue_cost_total IS DISTINCT FROM v_expected_cost THEN
        RAISE EXCEPTION 'Tournament venue_cost_total % does not equal immutable Resource snapshot total %', t.venue_cost_total, v_expected_cost;
    END IF;

    IF t.host_type='PLAYER' AND t.creator_participates AND NOT EXISTS (
        SELECT 1 FROM tournament.tournament_participant p WHERE p.tournament_id=t.id AND p.user_id=t.creator_user_id
    ) THEN
        RAISE EXCEPTION 'Participating Player Creator requires a retained Participant row';
    END IF;

    IF t.status='PENDING_VENUE_APPROVAL' THEN
        IF EXISTS (SELECT 1 FROM tournament.tournament_resource tr WHERE tr.tournament_id=t.id AND tr.removed_at IS NOT NULL) THEN
            RAISE EXCEPTION 'Pre-approval Tournament cannot contain removed Resources';
        END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_resource tr
            LEFT JOIN inventory.resource_reservation rr ON rr.id=tr.reservation_id
            WHERE tr.tournament_id=t.id AND (rr.id IS NULL OR rr.reservation_type<>'TOURNAMENT_APPROVAL_HOLD' OR NOT rr.active_flag
                OR rr.tournament_id IS DISTINCT FROM t.id OR rr.resource_id IS DISTINCT FROM tr.resource_id
                OR rr.planned_start IS DISTINCT FROM t.start_at OR rr.planned_end IS DISTINCT FROM t.end_at)
        ) THEN RAISE EXCEPTION 'PENDING_VENUE_APPROVAL requires active Approval Holds for every Resource'; END IF;
    ELSIF t.status IN ('WAITING_FOR_PLAYERS','CONFIRMED') THEN
        IF EXISTS (SELECT 1 FROM tournament.tournament_resource tr WHERE tr.tournament_id=t.id AND tr.removed_at IS NOT NULL) THEN
            RAISE EXCEPTION 'Pre-start Tournament cannot contain removed Resources';
        END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_resource tr
            LEFT JOIN inventory.resource_reservation rr ON rr.id=tr.reservation_id
            WHERE tr.tournament_id=t.id AND (rr.id IS NULL OR rr.reservation_type<>'TOURNAMENT_HOLD' OR NOT rr.active_flag
                OR rr.tournament_id IS DISTINCT FROM t.id OR rr.resource_id IS DISTINCT FROM tr.resource_id
                OR rr.planned_start IS DISTINCT FROM t.start_at OR rr.planned_end IS DISTINCT FROM t.end_at)
        ) THEN RAISE EXCEPTION 'WAITING/CONFIRMED Tournament requires active standard Holds for every Resource'; END IF;
    ELSIF t.status='ACTIVE' THEN
        SELECT COUNT(*)::integer INTO v_unremoved FROM tournament.tournament_resource tr WHERE tr.tournament_id=t.id AND tr.removed_at IS NULL;
        IF v_unremoved < 1 THEN RAISE EXCEPTION 'ACTIVE Tournament requires at least one remaining Resource'; END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_resource tr
            LEFT JOIN inventory.resource_reservation rr ON rr.id=tr.reservation_id
            WHERE tr.tournament_id=t.id AND tr.removed_at IS NULL
              AND (rr.id IS NULL OR rr.reservation_type<>'TOURNAMENT_HOLD' OR NOT rr.active_flag
                   OR rr.tournament_id IS DISTINCT FROM t.id OR rr.resource_id IS DISTINCT FROM tr.resource_id)
        ) THEN RAISE EXCEPTION 'ACTIVE Tournament requires an active standard Hold for each remaining Resource'; END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_resource tr
            JOIN inventory.resource_reservation rr ON rr.id=tr.reservation_id
            WHERE tr.tournament_id=t.id AND tr.removed_at IS NOT NULL
              AND (rr.active_flag OR rr.actual_reservation_release_at IS DISTINCT FROM tr.removed_at)
        ) THEN RAISE EXCEPTION 'Removed ACTIVE Tournament Resource requires its Hold released at removed_at'; END IF;
    ELSE
        IF EXISTS (SELECT 1 FROM inventory.resource_reservation rr WHERE rr.tournament_id=t.id AND rr.active_flag) THEN
            RAISE EXCEPTION 'Terminal Tournament may not retain active Resource Holds';
        END IF;
    END IF;

    -- Capacity safety: JOINED plus BAN-only INELIGIBLE reserved slots may never
    -- exceed the immutable Tournament capacity. Active Participant count remains separate.
    IF tournament.capacity_occupied_count(t.id) > t.capacity THEN
        RAISE EXCEPTION 'Tournament capacity occupancy exceeds capacity';
    END IF;

    -- Ban expiry is deadline-effective. For an overdue checkpoint/start, evaluate participant
    -- restoration at the boundary itself so a late Ban worker cannot change the Product result.
    IF t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED') THEN
        v_participant_eval_at := v_now;
        IF t.status='WAITING_FOR_PLAYERS' AND v_now >= t.checkpoint_at THEN
            v_participant_eval_at := t.checkpoint_at;
        ELSIF t.status='CONFIRMED' AND v_now >= t.start_at THEN
            v_participant_eval_at := t.start_at;
        END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_participant p
             WHERE p.tournament_id=t.id AND p.status='INELIGIBLE' AND p.ineligible_reason='BAN'
               AND NOT EXISTS (
                   SELECT 1 FROM trust.ban_instance b
                    WHERE b.user_id=p.user_id
                      AND b.activated_at <= v_participant_eval_at AND b.ends_at > v_participant_eval_at
               )
        ) THEN
            RAISE EXCEPTION 'Expired Ban requires automatic Tournament Participant restoration before the authoritative boundary can commit';
        END IF;
    END IF;

    -- Canonical scheduler contract from Technical Architecture v1.2. Only live jobs count.
    IF t.status='PENDING_VENUE_APPROVAL' THEN
        IF NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_APPROVAL_EXPIRY' AND j.due_at=t.approval_expires_at AND j.status IN ('PENDING','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_CHECKPOINT' AND j.due_at=t.checkpoint_at AND j.status IN ('PENDING','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_START' AND j.due_at=t.start_at AND j.status IN ('PENDING','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_COMPLETION' AND j.due_at=t.end_at AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'PENDING Tournament requires live approval/checkpoint/start/completion jobs';
        END IF;
    ELSIF t.status='WAITING_FOR_PLAYERS' THEN
        IF EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_APPROVAL_EXPIRY' AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'Approved Tournament may not retain a live approval-expiry job';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_CHECKPOINT' AND j.due_at=t.checkpoint_at AND j.status IN ('PENDING','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_START' AND j.due_at=t.start_at AND j.status IN ('PENDING','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_COMPLETION' AND j.due_at=t.end_at AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'WAITING Tournament requires live checkpoint/start/completion jobs';
        END IF;
    ELSIF t.status='CONFIRMED' THEN
        IF EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type IN ('TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT') AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'CONFIRMED Tournament may not retain live approval/checkpoint jobs';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_START' AND j.due_at=t.start_at AND j.status IN ('PENDING','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_COMPLETION' AND j.due_at=t.end_at AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'CONFIRMED Tournament requires live start/completion jobs';
        END IF;
    ELSIF t.status='ACTIVE' THEN
        IF EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type IN ('TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT','TOURNAMENT_START') AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'ACTIVE Tournament may not retain obsolete live approval/checkpoint/start jobs';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_COMPLETION' AND j.due_at=t.end_at AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'ACTIVE Tournament requires a live completion job';
        END IF;
    ELSE
        IF EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type IN ('TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT','TOURNAMENT_START','TOURNAMENT_COMPLETION') AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'Terminal Tournament may not retain live Tournament scheduler jobs';
        END IF;
    END IF;

    PERFORM tournament.assert_tournament_history_chain(t.id);
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.assert_ban_participant_cascade()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM tournament.tournament_participant p
        JOIN tournament.tournament t ON t.id=p.tournament_id
        WHERE p.user_id=NEW.user_id AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE')
    ) THEN RETURN NULL; END IF;
    v_now := tournament.require_command_scope(NULL, NULL, NULL, NEW.user_id);
    IF NEW.status='ACTIVE' AND NEW.ends_at > v_now THEN
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_participant p
            JOIN tournament.tournament t ON t.id=p.tournament_id
            WHERE p.user_id=NEW.user_id
              AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE')
              AND p.status='JOINED'
        ) THEN
            RAISE EXCEPTION 'Active Ban must mark Tournament participation INELIGIBLE in the same transaction';
        END IF;
    END IF;
    RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.assert_ban_participant_restore()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM tournament.tournament_participant p
        JOIN tournament.tournament t ON t.id=p.tournament_id
        WHERE p.user_id=NEW.user_id AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE')
    ) THEN RETURN NULL; END IF;
    v_now := tournament.require_command_scope(NULL, NULL, NULL, NEW.user_id);
    IF NOT EXISTS (
        SELECT 1 FROM trust.ban_instance b
         WHERE b.user_id=NEW.user_id AND b.status='ACTIVE'
           AND b.activated_at <= v_now AND b.ends_at > v_now
    ) AND EXISTS (
        SELECT 1 FROM tournament.tournament_participant p
        JOIN tournament.tournament t ON t.id=p.tournament_id
        WHERE p.user_id=NEW.user_id AND p.status='INELIGIBLE' AND p.ineligible_reason='BAN'
          AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED')
          AND v_now < t.start_at
    ) THEN
        RAISE EXCEPTION 'Ban expiry/lift requires automatic restoration of BAN-only Tournament Participants before Start';
    END IF;
    RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.guard_tournament_scheduled_job()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_types text[] := ARRAY['TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT','TOURNAMENT_START','TOURNAMENT_COMPLETION'];
BEGIN
    IF NEW.type IN ('TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT','TOURNAMENT_START','TOURNAMENT_COMPLETION') THEN
        PERFORM tournament.require_command_scope(NEW.subject_id);
    END IF;
    IF TG_OP='UPDATE' AND OLD.type IN ('TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT','TOURNAMENT_START','TOURNAMENT_COMPLETION') THEN
        PERFORM tournament.require_command_scope(OLD.subject_id);
    END IF;
    IF NEW.type = ANY(v_types) AND NEW.status='PAUSED' THEN
        RAISE EXCEPTION 'Tournament timers have no Product pause state';
    END IF;
    IF TG_OP='UPDATE' AND (OLD.type = ANY(v_types) OR NEW.type = ANY(v_types)) THEN
        IF NEW.type IS DISTINCT FROM OLD.type
           OR NEW.subject_id IS DISTINCT FROM OLD.subject_id
           OR NEW.due_at IS DISTINCT FROM OLD.due_at
           OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key THEN
            RAISE EXCEPTION 'Tournament scheduled-job type/subject/due/idempotency identity is immutable';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

-- Reservation writes are part of the same prelocked command, never an independent
-- clock or an undeclared Resource that can introduce a wait after capture.
CREATE OR REPLACE FUNCTION tournament.guard_reservation_command_scope()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
BEGIN
    IF TG_OP <> 'INSERT' AND OLD.tournament_id IS NOT NULL THEN
        PERFORM tournament.require_command_scope(OLD.tournament_id, NULL, OLD.resource_id);
    END IF;
    IF TG_OP <> 'DELETE' AND NEW.tournament_id IS NOT NULL THEN
        PERFORM tournament.require_command_scope(NEW.tournament_id, NULL, NEW.resource_id);
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_00_tournament_reservation_command_scope ON inventory.resource_reservation;
CREATE TRIGGER tr_00_tournament_reservation_command_scope
BEFORE INSERT OR UPDATE OR DELETE ON inventory.resource_reservation
FOR EACH ROW EXECUTE FUNCTION tournament.guard_reservation_command_scope();

-- FR-TRN-10 approval/rejection notification contract. This uses the EXISTING
-- TournamentRejected domain event; it introduces no new Product status or reason.
-- Provenance is registered only by an actual INSERT trigger inside the current
-- trusted Tournament command context. Dispatch remains strictly after COMMIT.
CREATE OR REPLACE FUNCTION tournament.register_rejection_outbox_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
BEGIN
    IF NEW.event_type <> 'TournamentRejected' OR NEW.aggregate_type <> 'TOURNAMENT' THEN
        RETURN NEW;
    END IF;
    IF pg_trigger_depth() = 0 THEN
        RAISE EXCEPTION 'Tournament rejection outbox registration is trigger-only';
    END IF;
    PERFORM tournament.require_command_scope(NEW.aggregate_id, NULL, NULL, NULL);
    IF NEW.state <> 'PENDING' OR NEW.attempt <> 0 OR NEW.dispatched_at IS NOT NULL THEN
        RAISE EXCEPTION 'Fresh TournamentRejected outbox event must be PENDING, attempt 0 and not dispatched';
    END IF;
    UPDATE pg_temp.e7gz_tournament_command_context c
       SET rejection_outbox_event_ids = array_append(c.rejection_outbox_event_ids, NEW.id)
     WHERE c.singleton
       AND c.transaction_id = pg_current_xact_id()
       AND NEW.aggregate_id = ANY(c.tournament_ids || c.new_tournament_ids);
    IF NOT FOUND THEN
        RAISE EXCEPTION 'TournamentRejected outbox INSERT is outside the current trusted Tournament command scope';
    END IF;
    RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION tournament.register_rejection_outbox_insert() FROM PUBLIC;
DROP TRIGGER IF EXISTS tr_register_tournament_rejection_outbox_insert ON technical.outbox_event;
CREATE TRIGGER tr_register_tournament_rejection_outbox_insert
AFTER INSERT ON technical.outbox_event
FOR EACH ROW EXECUTE FUNCTION tournament.register_rejection_outbox_insert();

CREATE OR REPLACE FUNCTION tournament.assert_rejection_notification_outbox()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    t tournament.tournament%ROWTYPE;
    c record;
BEGIN
    IF NEW.to_status <> 'REJECTED' THEN RETURN NULL; END IF;
    SELECT * INTO STRICT t FROM tournament.tournament WHERE id=NEW.tournament_id;
    PERFORM tournament.command_now();
    SELECT * INTO STRICT c
      FROM pg_temp.e7gz_tournament_command_context
     WHERE singleton AND transaction_id = pg_current_xact_id();
    IF NOT EXISTS (
        SELECT 1 FROM technical.outbox_event e
         WHERE e.event_type='TournamentRejected'
           AND e.aggregate_type='TOURNAMENT'
           AND e.aggregate_id=t.id
           AND e.correlation_id=NEW.correlation_id
           AND e.state='PENDING'
           AND e.attempt=0
           AND e.dispatched_at IS NULL
           AND e.id = ANY(c.rejection_outbox_event_ids)
           AND e.payload->>'recipientType'='CUSTOMER'
           AND e.payload->>'recipientId'=t.creator_user_id::text
           AND e.payload->>'tournamentId'=t.id::text
           AND e.payload->>'actorType'=NEW.actor_type
           AND e.payload->>'historySequence'=NEW.sequence::text
    ) THEN
        RAISE EXCEPTION 'Tournament rejection requires a fresh PENDING creator notification INSERT in the same trusted command transaction';
    END IF;
    RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_tournament_rejection_notification_outbox ON tournament.tournament_history;
CREATE CONSTRAINT TRIGGER tr_tournament_rejection_notification_outbox
AFTER INSERT ON tournament.tournament_history
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION tournament.assert_rejection_notification_outbox();


-- Final validation: run only after all v1.1.16 definitions are installed.
-- Upgrade preflight prohibits existing Tournament rows; fresh export is empty.
DO $validate$
DECLARE r record;
BEGIN
    FOR r IN SELECT id FROM tournament.tournament LOOP
        PERFORM tournament.assert_tournament_aggregate(r.id);
    END LOOP;
END
$validate$;


-- v1.1.17: Tournament participant-cause finalization: account deletion overrides BAN-only restoration, reserved capacity ends at deletion/start, prior Tournament hardening retained.
-- Contract: ONE command/cascade per transaction, READ COMMITTED. Begin before
-- business DML. Never accept a client/JVM timestamp or a user-settable GUC.
-- The protected temporary relation is owned by the function owner and disappears
-- at COMMIT/ROLLBACK; it adds no permanent domain table to the pgModeler model.
CREATE OR REPLACE FUNCTION tournament.begin_command(
    p_user_ids uuid[],
    p_venue_ids uuid[],
    p_resource_ids uuid[],
    p_tournament_ids uuid[],
    p_new_tournament_ids uuid[] DEFAULT ARRAY[]::uuid[]
)
RETURNS timestamptz
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_users uuid[];
    v_venues uuid[];
    v_resources uuid[];
    v_tournaments uuid[];
    v_new uuid[];
    v_now timestamptz;
    v_grantee record;
BEGIN
    IF current_setting('transaction_isolation') <> 'read committed' THEN
        RAISE EXCEPTION 'Tournament command requires READ COMMITTED and a post-lock re-read';
    END IF;
    IF to_regclass('pg_temp.e7gz_tournament_command_context') IS NOT NULL THEN
        RAISE EXCEPTION 'Exactly one Tournament command per transaction; commit/rollback before beginning another';
    END IF;
    IF array_position(p_user_ids, NULL) IS NOT NULL
       OR array_position(p_venue_ids, NULL) IS NOT NULL
       OR array_position(p_resource_ids, NULL) IS NOT NULL
       OR array_position(p_tournament_ids, NULL) IS NOT NULL
       OR array_position(p_new_tournament_ids, NULL) IS NOT NULL THEN
        RAISE EXCEPTION 'Command scope arrays must not contain NULL identifiers';
    END IF;

    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[])
      INTO v_tournaments FROM unnest(COALESCE(p_tournament_ids, ARRAY[]::uuid[])) x;
    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[])
      INTO v_new FROM unnest(COALESCE(p_new_tournament_ids, ARRAY[]::uuid[])) x;
    IF v_tournaments && v_new THEN
        RAISE EXCEPTION 'Existing and new Tournament scope must be disjoint';
    END IF;
    IF EXISTS (SELECT 1 FROM tournament.tournament t WHERE t.id = ANY(v_new)) THEN
        RAISE EXCEPTION 'A preallocated new Tournament id already exists';
    END IF;

    -- Discover the lock set, then acquire it in the baseline T10 order:
    -- Users/creators (sorted) -> Venues (sorted) -> Resources (sorted)
    -- -> Tournaments (sorted). Re-read/verify the set BEFORE sampling time.
    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[]) INTO v_users
      FROM (
          SELECT unnest(COALESCE(p_user_ids, ARRAY[]::uuid[])) x
          UNION SELECT t.creator_user_id FROM tournament.tournament t WHERE t.id = ANY(v_tournaments)
          UNION SELECT p.user_id FROM tournament.tournament_participant p WHERE p.tournament_id = ANY(v_tournaments)
      ) q WHERE x IS NOT NULL;
    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[]) INTO v_resources
      FROM (
          SELECT unnest(COALESCE(p_resource_ids, ARRAY[]::uuid[])) x
          UNION SELECT r.resource_id FROM tournament.tournament_resource r WHERE r.tournament_id = ANY(v_tournaments)
      ) q WHERE x IS NOT NULL;
    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[]) INTO v_venues
      FROM (
          SELECT unnest(COALESCE(p_venue_ids, ARRAY[]::uuid[])) x
          UNION SELECT t.venue_id FROM tournament.tournament t WHERE t.id = ANY(v_tournaments)
          UNION SELECT r.venue_id FROM resource.resource r WHERE r.id = ANY(v_resources)
      ) q WHERE x IS NOT NULL;

    PERFORM u.id FROM iam.user_account u WHERE u.id = ANY(v_users) ORDER BY u.id FOR UPDATE;
    PERFORM v.id FROM venue.venue v WHERE v.id = ANY(v_venues) ORDER BY v.id FOR UPDATE;
    PERFORM a.id FROM iam.venue_account a WHERE a.venue_id = ANY(v_venues) ORDER BY a.id FOR UPDATE;
    PERFORM r.id FROM resource.resource r WHERE r.id = ANY(v_resources) ORDER BY r.id FOR UPDATE;
    PERFORM t.id FROM tournament.tournament t WHERE t.id = ANY(v_tournaments) ORDER BY t.id FOR UPDATE;

    IF (SELECT count(*) FROM iam.user_account u WHERE u.id = ANY(v_users)) <> cardinality(v_users)
       OR (SELECT count(*) FROM venue.venue v WHERE v.id = ANY(v_venues)) <> cardinality(v_venues)
       OR (SELECT count(*) FROM resource.resource r WHERE r.id = ANY(v_resources)) <> cardinality(v_resources)
       OR (SELECT count(*) FROM tournament.tournament t WHERE t.id = ANY(v_tournaments)) <> cardinality(v_tournaments) THEN
        RAISE EXCEPTION 'Command scope contains a missing authoritative row';
    END IF;
    IF EXISTS (
        SELECT 1 FROM tournament.tournament t WHERE t.id = ANY(v_tournaments)
          AND (NOT (t.venue_id = ANY(v_venues))
               OR (t.creator_user_id IS NOT NULL AND NOT (t.creator_user_id = ANY(v_users))))
    ) OR EXISTS (
        SELECT 1 FROM tournament.tournament_participant p
         WHERE p.tournament_id = ANY(v_tournaments) AND NOT (p.user_id = ANY(v_users))
    ) OR EXISTS (
        SELECT 1 FROM tournament.tournament_resource r
         WHERE r.tournament_id = ANY(v_tournaments) AND NOT (r.resource_id = ANY(v_resources))
    ) OR EXISTS (
        SELECT 1 FROM resource.resource r
         WHERE r.id = ANY(v_resources) AND NOT (r.venue_id = ANY(v_venues))
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Tournament lock set changed while waiting; retry the whole transaction';
    END IF;

    CREATE TEMPORARY TABLE e7gz_tournament_command_context (
        singleton boolean PRIMARY KEY CHECK (singleton),
        transaction_id xid8 NOT NULL,
        captured_at timestamptz NOT NULL,
        user_ids uuid[] NOT NULL,
        venue_ids uuid[] NOT NULL,
        resource_ids uuid[] NOT NULL,
        tournament_ids uuid[] NOT NULL,
        new_tournament_ids uuid[] NOT NULL,
        created_tournament_ids uuid[] NOT NULL,
        rejection_outbox_event_ids bigint[] NOT NULL
    ) ON COMMIT DROP;
    REVOKE ALL ON TABLE pg_temp.e7gz_tournament_command_context FROM PUBLIC;
    -- Owner default privileges may grant newly-created tables to service/group
    -- roles. Remove those grants as well; PUBLIC-only revocation is insufficient.
    FOR v_grantee IN
        SELECT DISTINCT r.rolname
          FROM pg_catalog.pg_class c
          CROSS JOIN LATERAL pg_catalog.aclexplode(c.relacl) a
          JOIN pg_catalog.pg_roles r ON r.oid=a.grantee
         WHERE c.oid='pg_temp.e7gz_tournament_command_context'::regclass
           AND a.grantee <> c.relowner
    LOOP
        EXECUTE format('REVOKE ALL ON TABLE pg_temp.e7gz_tournament_command_context FROM %I', v_grantee.rolname);
    END LOOP;

    -- The ONLY clock read in the new Tournament command implementation.
    -- All authoritative lock waits above have completed at this point.
    v_now := clock_timestamp();
    INSERT INTO pg_temp.e7gz_tournament_command_context
    VALUES (true, pg_current_xact_id(), v_now, v_users, v_venues, v_resources,
            v_tournaments, v_new, ARRAY[]::uuid[], ARRAY[]::bigint[]);
    RETURN v_now;
END;
$function$;
REVOKE ALL ON FUNCTION tournament.begin_command(uuid[],uuid[],uuid[],uuid[],uuid[]) FROM PUBLIC;

CREATE OR REPLACE FUNCTION tournament.command_now()
RETURNS timestamptz
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE v_now timestamptz;
BEGIN
    -- Reject caller-created / spoofed temp tables before reading a single value.
    IF NOT EXISTS (
        SELECT 1 FROM pg_catalog.pg_class c
         WHERE c.oid = to_regclass('pg_temp.e7gz_tournament_command_context')
           AND c.relnamespace = pg_my_temp_schema()
           AND c.relpersistence = 't'
           AND c.relowner = (SELECT r.oid FROM pg_catalog.pg_roles r WHERE r.rolname = current_user)
    ) THEN
        RAISE EXCEPTION 'Missing trusted Tournament command context; call begin_command before business DML';
    END IF;
    SELECT c.captured_at INTO v_now
      FROM pg_temp.e7gz_tournament_command_context c
     WHERE c.singleton AND c.transaction_id = pg_current_xact_id();
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament command context belongs to another transaction or is incomplete'; END IF;
    RETURN v_now;
END;
$function$;
REVOKE ALL ON FUNCTION tournament.command_now() FROM PUBLIC;

CREATE OR REPLACE FUNCTION tournament.require_command_scope(
    p_tournament_id uuid DEFAULT NULL,
    p_venue_id uuid DEFAULT NULL,
    p_resource_id uuid DEFAULT NULL,
    p_user_id uuid DEFAULT NULL
)
RETURNS timestamptz
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE v_now timestamptz; c record;
BEGIN
    v_now := tournament.command_now();
    SELECT * INTO STRICT c FROM pg_temp.e7gz_tournament_command_context WHERE singleton;
    IF (p_tournament_id IS NOT NULL AND NOT (p_tournament_id = ANY(c.tournament_ids || c.new_tournament_ids)))
       OR (p_venue_id IS NOT NULL AND NOT (p_venue_id = ANY(c.venue_ids)))
       OR (p_resource_id IS NOT NULL AND NOT (p_resource_id = ANY(c.resource_ids)))
       OR (p_user_id IS NOT NULL AND NOT (p_user_id = ANY(c.user_ids))) THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Mutation exceeds the prelocked Tournament command scope; retry with the complete lock set';
    END IF;
    RETURN v_now;
END;
$function$;
REVOKE ALL ON FUNCTION tournament.require_command_scope(uuid,uuid,uuid,uuid) FROM PUBLIC;

CREATE OR REPLACE FUNCTION tournament.mark_created_in_command(p_tournament_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
BEGIN
    PERFORM tournament.command_now();
    IF pg_trigger_depth() = 0 THEN RAISE EXCEPTION 'Creation marker is a private trigger operation'; END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_temp.e7gz_tournament_command_context c
         WHERE c.singleton AND p_tournament_id = ANY(c.new_tournament_ids)
           AND NOT (p_tournament_id = ANY(c.created_tournament_ids))
    ) OR EXISTS (SELECT 1 FROM tournament.tournament t WHERE t.id = p_tournament_id) THEN
        RAISE EXCEPTION 'Tournament creation requires a fresh preallocated id in the current command';
    END IF;
    UPDATE pg_temp.e7gz_tournament_command_context
       SET created_tournament_ids = array_append(created_tournament_ids, p_tournament_id)
     WHERE singleton;
END;
$function$;
REVOKE ALL ON FUNCTION tournament.mark_created_in_command(uuid) FROM PUBLIC;

CREATE OR REPLACE FUNCTION tournament.created_in_command(p_tournament_id uuid)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE v_created boolean;
BEGIN
    PERFORM tournament.command_now();
    SELECT p_tournament_id = ANY(c.created_tournament_ids) INTO v_created
      FROM pg_temp.e7gz_tournament_command_context c WHERE c.singleton;
    RETURN COALESCE(v_created, false);
END;
$function$;
REVOKE ALL ON FUNCTION tournament.created_in_command(uuid) FROM PUBLIC;


CREATE OR REPLACE FUNCTION tournament.active_participant_count(p_tournament_id uuid, p_at timestamptz)
RETURNS integer
LANGUAGE sql
STABLE
AS $function$
SELECT COUNT(*)::integer
  FROM tournament.tournament_participant p
  JOIN iam.user_account u ON u.id = p.user_id
 WHERE p.tournament_id = p_tournament_id
   AND p.status = 'JOINED'
   AND u.anonymised_at IS NULL
   AND NOT EXISTS (
       SELECT 1
         FROM trust.ban_instance b
        WHERE b.user_id = p.user_id
          AND b.status = 'ACTIVE'
          AND b.activated_at <= p_at
          AND b.ends_at > p_at
   );
$function$;

CREATE OR REPLACE FUNCTION tournament.active_participant_count(p_tournament_id uuid)
RETURNS integer
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
BEGIN
    RETURN tournament.active_participant_count(p_tournament_id, tournament.require_command_scope(p_tournament_id));
END;
$function$;


-- Capacity occupancy is intentionally different from Active Participant count.
-- A BAN-only INELIGIBLE participant reserves a slot only while the account is active,
-- the Tournament remains pre-start, and p_at is still before startAt. ACCOUNT_DELETED
-- never reserves a BAN-restoration slot. BAN-only INELIGIBLE still does NOT count
-- toward the checkpoint minimum.
CREATE OR REPLACE FUNCTION tournament.capacity_occupied_count(p_tournament_id uuid, p_at timestamptz)
RETURNS integer
LANGUAGE sql
STABLE
AS $function$
SELECT COUNT(*)::integer
  FROM tournament.tournament_participant p
  JOIN tournament.tournament t ON t.id = p.tournament_id
  JOIN iam.user_account u ON u.id = p.user_id
 WHERE p.tournament_id = p_tournament_id
   AND u.anonymised_at IS NULL
   AND (
       p.status = 'JOINED'
       OR (
           p.status = 'INELIGIBLE'
           AND p.ineligible_reason = 'BAN'
           AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED')
           AND p_at < t.start_at
       )
   );
$function$;

CREATE OR REPLACE FUNCTION tournament.capacity_occupied_count(p_tournament_id uuid)
RETURNS integer
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
BEGIN
    RETURN tournament.capacity_occupied_count(
        p_tournament_id,
        tournament.require_command_scope(p_tournament_id)
    );
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.highest_current_cancellation_reason(
    p_tournament_id uuid,
    p_from_status text,
    p_at timestamptz
)
RETURNS text
LANGUAGE plpgsql
STABLE
AS $function$
DECLARE
    t tournament.tournament%ROWTYPE;
    v_creator_status text;
    v_has_owner_review boolean;
    v_has_resource_emergency boolean;
    v_has_venue_emergency boolean;
    v_remaining integer;
    v_eval_at timestamptz;
BEGIN
    IF p_at IS NULL THEN RAISE EXCEPTION 'Cancellation resolver requires an explicit evaluation instant'; END IF;
    SELECT * INTO t FROM tournament.tournament WHERE id = p_tournament_id;
    IF NOT FOUND THEN RETURN NULL; END IF;

    -- A late worker must evaluate the cause set at the Product boundary, not at worker time.
    v_eval_at := p_at;
    IF p_from_status='PENDING_VENUE_APPROVAL' AND p_at >= t.approval_expires_at THEN
        v_eval_at := t.approval_expires_at;
    ELSIF p_from_status='WAITING_FOR_PLAYERS' AND p_at >= t.checkpoint_at THEN
        v_eval_at := t.checkpoint_at;
    ELSIF p_from_status='CONFIRMED' AND p_at >= t.start_at THEN
        v_eval_at := t.start_at;
    ELSIF p_from_status='ACTIVE' AND p_at >= t.end_at THEN
        v_eval_at := t.end_at;
    END IF;

    SELECT EXISTS (
        SELECT 1
          FROM tournament.tournament_resource tr
          JOIN operations.owner_review o ON o.resource_id = tr.resource_id
         WHERE tr.tournament_id = t.id
           AND o.entered_at <= v_eval_at
           AND (o.resolved_at IS NULL OR o.resolved_at > v_eval_at)
    ) INTO v_has_owner_review;

    SELECT EXISTS (
        SELECT 1
          FROM tournament.tournament_resource tr
          JOIN operations.emergency e ON e.resource_id = tr.resource_id AND e.scope = 'RESOURCE'
         WHERE tr.tournament_id = t.id
           AND e.declared_at <= v_eval_at
           AND (e.ended_at IS NULL OR e.ended_at > v_eval_at)
           AND tstzrange(t.start_at,t.end_at,'[)') && e.declared_period
    ) INTO v_has_resource_emergency;

    SELECT EXISTS (
        SELECT 1 FROM operations.emergency e
         WHERE e.scope = 'VENUE'
           AND e.venue_id = t.venue_id
           AND e.declared_at <= v_eval_at
           AND (e.ended_at IS NULL OR e.ended_at > v_eval_at)
           AND tstzrange(t.start_at,t.end_at,'[)') && e.declared_period
    ) INTO v_has_venue_emergency;

    IF p_from_status = 'ACTIVE' THEN
        SELECT COUNT(*)::integer INTO v_remaining
          FROM tournament.tournament_resource tr
         WHERE tr.tournament_id = t.id
           AND (tr.removed_at IS NULL OR tr.removed_at > v_eval_at)
           AND NOT EXISTS (
               SELECT 1 FROM operations.owner_review o
                WHERE o.resource_id = tr.resource_id
                  AND o.entered_at <= v_eval_at
                  AND (o.resolved_at IS NULL OR o.resolved_at > v_eval_at)
           )
           AND NOT EXISTS (
               SELECT 1 FROM operations.emergency e
                WHERE e.scope = 'RESOURCE'
                  AND e.resource_id = tr.resource_id
                  AND e.declared_at <= v_eval_at
                  AND (e.ended_at IS NULL OR e.ended_at > v_eval_at)
                  AND tstzrange(t.start_at,t.end_at,'[)') && e.declared_period
           );
        IF v_remaining > 0 THEN
            v_has_owner_review := false;
            v_has_resource_emergency := false;
        END IF;
    END IF;

    IF v_has_owner_review THEN RETURN 'RESOURCE_OWNER_REVIEW_REQUIRED'; END IF;
    IF v_has_resource_emergency THEN RETURN 'RESOURCE_EMERGENCY_OUTAGE'; END IF;
    IF v_has_venue_emergency THEN RETURN 'EMERGENCY_CLOSURE'; END IF;

    IF p_from_status = 'PENDING_VENUE_APPROVAL' AND EXISTS (
        SELECT 1 FROM iam.venue_account_restriction_interval r
         WHERE r.venue_id = t.venue_id
           AND r.disabled_at <= v_eval_at
           AND (r.reenabled_at IS NULL OR r.reenabled_at > v_eval_at)
    ) THEN
        RETURN 'VENUE_ACCOUNT_DISABLED';
    END IF;

    IF p_from_status = 'WAITING_FOR_PLAYERS'
       AND v_eval_at >= t.checkpoint_at
       AND tournament.active_participant_count(t.id, v_eval_at) < 8 THEN
        RETURN 'MINIMUM_PARTICIPANTS_NOT_REACHED';
    END IF;

    IF p_from_status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS') AND t.creator_user_id IS NOT NULL THEN
        SELECT v.to_status INTO v_creator_status
          FROM trust.verified_player_transition v
         WHERE v.user_id = t.creator_user_id
           AND v.occurred_at <= v_eval_at
         ORDER BY v.occurred_at DESC, v.id DESC
         LIMIT 1;
        IF v_creator_status = 'REVOKED' THEN
            RETURN 'CREATOR_VERIFIED_STATUS_REVOKED';
        END IF;
    END IF;

    RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.prepare_tournament_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz;
    v_marketplace text;
    v_account text;
    v_phone_verified boolean;
    v_anonymised_at timestamptz;
    v_vp_status text;
    v_last_terminal timestamptz;
BEGIN
    v_now := tournament.require_command_scope(NEW.id, NEW.venue_id, NULL, NEW.creator_user_id);
    PERFORM tournament.mark_created_in_command(NEW.id);
    NEW.created_at := v_now;
    NEW.end_at := NEW.start_at + make_interval(mins => NEW.nominal_minutes);
    NEW.checkpoint_at := NEW.start_at - interval '1 hour';
    NEW.version := 0;

    IF NEW.host_type = 'PLAYER' THEN
        NEW.status := 'PENDING_VENUE_APPROVAL';
        NEW.approval_expires_at := NEW.created_at + interval '24 hours';
    ELSIF NEW.host_type = 'VENUE' THEN
        NEW.status := 'WAITING_FOR_PLAYERS';
        NEW.approval_expires_at := NULL;
    END IF;

    SELECT v.marketplace_status INTO v_marketplace
      FROM venue.venue v WHERE v.id = NEW.venue_id FOR UPDATE;
    IF NOT FOUND OR v_marketplace <> 'ACTIVE' THEN
        RAISE EXCEPTION 'New Tournament creation requires Venue Marketplace ACTIVE';
    END IF;

    SELECT va.account_status INTO v_account
      FROM iam.venue_account va WHERE va.venue_id = NEW.venue_id;
    IF v_account IS DISTINCT FROM 'ENABLED' THEN
        RAISE EXCEPTION 'New Tournament creation requires Venue Account ENABLED';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM venue.venue_activity a WHERE a.venue_id = NEW.venue_id AND a.activity = NEW.activity) THEN
        RAISE EXCEPTION 'Tournament activity is not configured for the selected Venue';
    END IF;
    IF EXISTS (SELECT 1 FROM venue.venue_selling_block b WHERE b.venue_id = NEW.venue_id AND b.active) THEN
        RAISE EXCEPTION 'New Tournament creation is blocked by a Venue Operational Selling Block';
    END IF;

    IF NEW.host_type = 'PLAYER' AND NEW.created_at > NEW.checkpoint_at - interval '24 hours' THEN
        RAISE EXCEPTION 'Player Tournament request requires at least 24 hours before checkpointAt (25 hours before startAt)';
    ELSIF NEW.host_type = 'VENUE' AND NEW.created_at > NEW.start_at - interval '2 hours' THEN
        RAISE EXCEPTION 'Venue-hosted Tournament creation cutoff remains startAt - 2 hours';
    END IF;

    IF NEW.host_type = 'PLAYER' THEN
        SELECT u.phone_verified, u.anonymised_at
          INTO v_phone_verified, v_anonymised_at
          FROM iam.user_account u
         WHERE u.id = NEW.creator_user_id
         FOR UPDATE;
        IF NOT FOUND OR NOT v_phone_verified OR v_anonymised_at IS NOT NULL THEN
            RAISE EXCEPTION 'Player-hosted Tournament creator must be an Account-Verified active User';
        END IF;
        SELECT p.vp_operational_status INTO v_vp_status
          FROM trust.trust_projection p WHERE p.user_id = NEW.creator_user_id;
        IF v_vp_status IS DISTINCT FROM 'VERIFIED' THEN
            RAISE EXCEPTION 'Only operational VERIFIED may create a Player-hosted Tournament';
        END IF;
        IF EXISTS (
            SELECT 1 FROM trust.ban_instance b
             WHERE b.user_id = NEW.creator_user_id
               AND b.status = 'ACTIVE'
               AND b.activated_at <= NEW.created_at
               AND b.ends_at > NEW.created_at
        ) THEN
            RAISE EXCEPTION 'Banned User may not create a Tournament';
        END IF;

        SELECT MAX(h.occurred_at) INTO v_last_terminal
          FROM tournament.tournament t0
          JOIN tournament.tournament_history h ON h.tournament_id = t0.id
         WHERE t0.host_type = 'PLAYER'
           AND t0.creator_user_id = NEW.creator_user_id
           AND t0.venue_id = NEW.venue_id
           AND t0.start_at = NEW.start_at
           AND t0.end_at = NEW.end_at
           AND t0.status = 'REJECTED'
           AND h.to_status = 'REJECTED';
        IF v_last_terminal IS NOT NULL AND NEW.created_at < v_last_terminal + interval '5 minutes' THEN
            RAISE EXCEPTION 'Creator must wait 5 minutes before re-requesting the same Venue/time interval';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.guard_tournament_due_boundary()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz;
    v_expected text;
BEGIN
    v_now := tournament.require_command_scope(OLD.id, OLD.venue_id);
    IF OLD.status='PENDING_VENUE_APPROVAL' AND v_now >= OLD.approval_expires_at THEN
        v_expected := tournament.highest_current_cancellation_reason(OLD.id,'PENDING_VENUE_APPROVAL',OLD.approval_expires_at);
        IF v_expected IS NULL THEN
            IF NEW.status <> 'REJECTED' OR NEW.terminal_reason IS NOT NULL THEN
                RAISE EXCEPTION 'Approval deadline owns the next transition; expected REJECTED with no reason';
            END IF;
        ELSIF NEW.status <> 'CANCELLED' OR NEW.terminal_reason IS DISTINCT FROM v_expected THEN
            RAISE EXCEPTION 'A higher-priority condition at approval expiry requires CANCELLED/%', v_expected;
        END IF;

    ELSIF OLD.status='WAITING_FOR_PLAYERS' AND v_now >= OLD.checkpoint_at THEN
        -- A BAN that already expired at checkpoint must be restored first; a later worker cannot make
        -- the participant absent from the exact checkpoint count.
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_participant p
             WHERE p.tournament_id=OLD.id AND p.status='INELIGIBLE' AND p.ineligible_reason='BAN'
               AND NOT EXISTS (
                   SELECT 1 FROM trust.ban_instance b
                    WHERE b.user_id=p.user_id AND b.activated_at <= OLD.checkpoint_at AND b.ends_at > OLD.checkpoint_at
               )
        ) THEN
            RAISE EXCEPTION 'Restore BAN-only Participants whose Ban expired by checkpointAt before resolving the checkpoint';
        END IF;
        v_expected := tournament.highest_current_cancellation_reason(OLD.id,'WAITING_FOR_PLAYERS',OLD.checkpoint_at);
        IF v_expected IS NULL THEN
            IF NEW.status <> 'CONFIRMED' OR NEW.terminal_reason IS NOT NULL THEN
                RAISE EXCEPTION 'Checkpoint owns the next transition; expected CONFIRMED';
            END IF;
        ELSE
            IF NEW.status <> 'CANCELLED' OR NEW.terminal_reason IS DISTINCT FROM v_expected THEN
                RAISE EXCEPTION 'Checkpoint owns the next transition; expected CANCELLED/%', v_expected;
            END IF;
        END IF;

    ELSIF OLD.status='CONFIRMED' AND v_now >= OLD.start_at THEN
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_participant p
             WHERE p.tournament_id=OLD.id AND p.status='INELIGIBLE' AND p.ineligible_reason='BAN'
               AND NOT EXISTS (
                   SELECT 1 FROM trust.ban_instance b
                    WHERE b.user_id=p.user_id AND b.activated_at <= OLD.start_at AND b.ends_at > OLD.start_at
               )
        ) THEN
            RAISE EXCEPTION 'Restore BAN-only Participants whose Ban expired by startAt before resolving Tournament start';
        END IF;
        v_expected := tournament.highest_current_cancellation_reason(OLD.id,'CONFIRMED',OLD.start_at);
        IF v_expected IS NULL THEN
            IF NEW.status <> 'ACTIVE' OR NEW.terminal_reason IS NOT NULL THEN
                RAISE EXCEPTION 'startAt owns the next transition; expected ACTIVE';
            END IF;
        ELSE
            IF NEW.status <> 'CANCELLED' OR NEW.terminal_reason IS DISTINCT FROM v_expected THEN
                RAISE EXCEPTION 'startAt owns the next transition; expected CANCELLED/%', v_expected;
            END IF;
        END IF;

    ELSIF OLD.status='ACTIVE' AND v_now >= OLD.end_at THEN
        IF NEW.status <> 'COMPLETED' OR NEW.terminal_reason IS NOT NULL THEN
            RAISE EXCEPTION 'endAt owns the next transition; expected COMPLETED';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.guard_tournament_update()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz;
    v_count integer;
BEGIN
    v_now := tournament.require_command_scope(OLD.id, OLD.venue_id);
    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.venue_id IS DISTINCT FROM OLD.venue_id
       OR NEW.host_type IS DISTINCT FROM OLD.host_type
       OR NEW.creator_user_id IS DISTINCT FROM OLD.creator_user_id
       OR NEW.creator_participates IS DISTINCT FROM OLD.creator_participates
       OR NEW.activity IS DISTINCT FROM OLD.activity
       OR NEW.play_mode IS DISTINCT FROM OLD.play_mode
       OR NEW.capacity IS DISTINCT FROM OLD.capacity
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.start_at IS DISTINCT FROM OLD.start_at
       OR NEW.end_at IS DISTINCT FROM OLD.end_at
       OR NEW.nominal_minutes IS DISTINCT FROM OLD.nominal_minutes
       OR NEW.checkpoint_at IS DISTINCT FROM OLD.checkpoint_at
       OR NEW.approval_expires_at IS DISTINCT FROM OLD.approval_expires_at
       OR NEW.visibility IS DISTINCT FROM OLD.visibility
       OR NEW.invite_code IS DISTINCT FROM OLD.invite_code
       OR NEW.venue_cost_total IS DISTINCT FROM OLD.venue_cost_total
       OR NEW.creation_fee_snapshot IS DISTINCT FROM OLD.creation_fee_snapshot
       OR NEW.entry_fee IS DISTINCT FROM OLD.entry_fee
       OR NEW.prize IS DISTINCT FROM OLD.prize
       OR NEW.business_date IS DISTINCT FROM OLD.business_date
       OR NEW.operating_session_id IS DISTINCT FROM OLD.operating_session_id THEN
        RAISE EXCEPTION 'Tournament creation/commercial/session snapshots are immutable';
    END IF;

    IF OLD.status IN ('COMPLETED','REJECTED','CANCELLED') THEN
        RAISE EXCEPTION 'Terminal Tournament state is immutable';
    END IF;
    IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
        RAISE EXCEPTION 'Tournament UPDATE must be a semantic state transition';
    END IF;
    IF NEW.version <> OLD.version + 1 THEN
        RAISE EXCEPTION 'Tournament state transition must increment version exactly once';
    END IF;

    IF OLD.status = 'PENDING_VENUE_APPROVAL' AND NEW.status NOT IN ('WAITING_FOR_PLAYERS','REJECTED','CANCELLED') THEN
        RAISE EXCEPTION 'Invalid Tournament transition % -> %', OLD.status, NEW.status;
    ELSIF OLD.status = 'WAITING_FOR_PLAYERS' AND NEW.status NOT IN ('CONFIRMED','CANCELLED') THEN
        RAISE EXCEPTION 'Invalid Tournament transition % -> %', OLD.status, NEW.status;
    ELSIF OLD.status = 'CONFIRMED' AND NEW.status NOT IN ('ACTIVE','CANCELLED') THEN
        RAISE EXCEPTION 'Invalid Tournament transition % -> %', OLD.status, NEW.status;
    ELSIF OLD.status = 'ACTIVE' AND NEW.status NOT IN ('COMPLETED','CANCELLED') THEN
        RAISE EXCEPTION 'Invalid Tournament transition % -> %', OLD.status, NEW.status;
    END IF;

    IF OLD.status = 'PENDING_VENUE_APPROVAL' AND NEW.status = 'WAITING_FOR_PLAYERS' THEN
        IF v_now >= OLD.approval_expires_at THEN
            RAISE EXCEPTION 'Venue approval deadline is owned by expiry at now >= approvalExpiresAt';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM iam.venue_account va WHERE va.venue_id = OLD.venue_id AND va.account_status = 'ENABLED') THEN
            RAISE EXCEPTION 'Venue Accept requires Venue Account ENABLED';
        END IF;
        PERFORM tournament.assert_resources_operational(OLD.id, 'TOURNAMENT_APPROVAL_HOLD');
    ELSIF OLD.status = 'PENDING_VENUE_APPROVAL' AND NEW.status = 'REJECTED' THEN
        IF NEW.terminal_reason IS NOT NULL THEN
            RAISE EXCEPTION 'Tournament request rejection carries no reason';
        END IF;
        -- Venue before deadline; SYSTEM at/after deadline. Actor/timing is checked
        -- against the append-only history and matching audit in this transaction.
    ELSIF OLD.status = 'PENDING_VENUE_APPROVAL' AND NEW.status = 'CANCELLED' THEN
        IF NEW.terminal_reason IN ('VENUE_REJECTED_TOURNAMENT','VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME') THEN
            RAISE EXCEPTION 'Venue rejection and normal approval timeout use REJECTED without a reason';
        END IF;
        IF NEW.terminal_reason = 'CREATOR_CANCELLED' AND v_now >= OLD.checkpoint_at THEN
            RAISE EXCEPTION 'Creator may cancel only before the checkpoint';
        END IF;
    ELSIF OLD.status = 'WAITING_FOR_PLAYERS' AND NEW.status = 'CONFIRMED' THEN
        IF v_now < OLD.checkpoint_at THEN
            RAISE EXCEPTION 'Tournament checkpoint may not confirm before checkpointAt';
        END IF;
        v_count := tournament.active_participant_count(OLD.id, OLD.checkpoint_at);
        IF v_count < 8 THEN
            RAISE EXCEPTION 'Tournament cannot confirm with fewer than 8 Active Participants';
        END IF;
        PERFORM tournament.assert_resources_operational(OLD.id, 'TOURNAMENT_HOLD');
    ELSIF OLD.status = 'WAITING_FOR_PLAYERS' AND NEW.status = 'CANCELLED' THEN
        IF NEW.terminal_reason = 'MINIMUM_PARTICIPANTS_NOT_REACHED' THEN
            IF v_now < OLD.checkpoint_at OR tournament.active_participant_count(OLD.id, OLD.checkpoint_at) >= 8 THEN
                RAISE EXCEPTION 'MINIMUM_PARTICIPANTS_NOT_REACHED requires checkpoint ownership and fewer than 8 Active Participants';
            END IF;
        ELSIF NEW.terminal_reason = 'CREATOR_CANCELLED' AND v_now >= OLD.checkpoint_at THEN
            RAISE EXCEPTION 'Creator may cancel only before the checkpoint';
        END IF;
    ELSIF OLD.status = 'CONFIRMED' AND NEW.status = 'ACTIVE' THEN
        IF v_now < OLD.start_at THEN
            RAISE EXCEPTION 'Tournament may not start before startAt';
        END IF;
        PERFORM tournament.assert_resources_operational(OLD.id, 'TOURNAMENT_HOLD');
    ELSIF OLD.status = 'ACTIVE' AND NEW.status = 'COMPLETED' THEN
        IF v_now < OLD.end_at THEN
            RAISE EXCEPTION 'Tournament may not complete before endAt';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.guard_tournament_resource()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz;
    t tournament.tournament%ROWTYPE;
    r resource.resource%ROWTYPE;
    rr inventory.resource_reservation%ROWTYPE;
    rr_old inventory.resource_reservation%ROWTYPE;
    v_expected_price numeric;
    v_expected_type text;
BEGIN
    v_now := tournament.require_command_scope(COALESCE(NEW.tournament_id, OLD.tournament_id), NULL, COALESCE(NEW.resource_id, OLD.resource_id));
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Tournament Resource assignments are historical and may not be deleted';
    END IF;

    SELECT * INTO t FROM tournament.tournament WHERE id = NEW.tournament_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament does not exist'; END IF;
    SELECT * INTO r FROM resource.resource WHERE id = NEW.resource_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament Resource does not exist'; END IF;

    IF TG_OP = 'INSERT' THEN
        IF NOT tournament.created_in_command(t.id) THEN
            RAISE EXCEPTION 'Tournament Resources may be added only in the Tournament creation transaction';
        END IF;
        IF (SELECT COUNT(*) FROM tournament.tournament_resource x WHERE x.tournament_id = t.id) >= 4 THEN
            RAISE EXCEPTION 'Tournament maximum Resource count is 4';
        END IF;
        IF r.venue_id IS DISTINCT FROM t.venue_id OR r.activity IS DISTINCT FROM t.activity THEN
            RAISE EXCEPTION 'Tournament Resource must belong to the same Venue and Activity';
        END IF;
        IF r.base_state <> 'ACTIVE' OR r.operational_restriction <> 'NONE'
           OR EXISTS (SELECT 1 FROM resource.resource_selling_block b WHERE b.resource_id = r.id AND b.active)
           OR EXISTS (SELECT 1 FROM venue.venue_selling_block b WHERE b.venue_id = t.venue_id AND b.active) THEN
            RAISE EXCEPTION 'Tournament Resource is not operationally eligible at creation';
        END IF;
        IF t.activity = 'PLAYSTATION' THEN
            IF NEW.console_type_snapshot IS DISTINCT FROM r.console_type THEN
                RAISE EXCEPTION 'PlayStation Tournament console snapshot must equal Resource console type';
            END IF;
        ELSIF NEW.console_type_snapshot IS NOT NULL THEN
            RAISE EXCEPTION 'Billiards/Ping Pong Tournament Resource console snapshot must be NULL';
        END IF;
        v_expected_price := tournament.expected_resource_price(r.id, t.activity, t.play_mode);
        IF NEW.hourly_price_snapshot IS DISTINCT FROM v_expected_price THEN
            RAISE EXCEPTION 'Tournament Resource hourly price snapshot % does not equal effective creation price %', NEW.hourly_price_snapshot, v_expected_price;
        END IF;
        v_expected_type := CASE WHEN t.status = 'PENDING_VENUE_APPROVAL' THEN 'TOURNAMENT_APPROVAL_HOLD' ELSE 'TOURNAMENT_HOLD' END;
        SELECT * INTO rr FROM inventory.resource_reservation WHERE id = NEW.reservation_id;
        IF NOT FOUND OR rr.tournament_id IS DISTINCT FROM t.id OR rr.resource_id IS DISTINCT FROM r.id
           OR rr.reservation_type IS DISTINCT FROM v_expected_type OR NOT rr.active_flag
           OR rr.planned_start IS DISTINCT FROM t.start_at OR rr.planned_end IS DISTINCT FROM t.end_at THEN
            RAISE EXCEPTION 'Tournament Resource requires a matching active % reservation', v_expected_type;
        END IF;
        NEW.removed_at := NULL;
        NEW.removal_cause := NULL;
        RETURN NEW;
    END IF;

    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.tournament_id IS DISTINCT FROM OLD.tournament_id
       OR NEW.resource_id IS DISTINCT FROM OLD.resource_id
       OR NEW.console_type_snapshot IS DISTINCT FROM OLD.console_type_snapshot
       OR NEW.hourly_price_snapshot IS DISTINCT FROM OLD.hourly_price_snapshot THEN
        RAISE EXCEPTION 'Tournament Resource identity and historical snapshots are immutable';
    END IF;

    IF OLD.reservation_id IS DISTINCT FROM NEW.reservation_id THEN
        SELECT * INTO rr_old FROM inventory.resource_reservation WHERE id = OLD.reservation_id;
        SELECT * INTO rr FROM inventory.resource_reservation WHERE id = NEW.reservation_id;
        IF NOT FOUND OR rr_old.reservation_type <> 'TOURNAMENT_APPROVAL_HOLD'
           OR rr_old.active_flag OR rr.reservation_type <> 'TOURNAMENT_HOLD' OR NOT rr.active_flag
           OR rr_old.tournament_id IS DISTINCT FROM t.id OR rr.tournament_id IS DISTINCT FROM t.id
           OR rr_old.resource_id IS DISTINCT FROM NEW.resource_id OR rr.resource_id IS DISTINCT FROM NEW.resource_id
           OR rr_old.planned_start IS DISTINCT FROM t.start_at OR rr_old.planned_end IS DISTINCT FROM t.end_at
           OR rr.planned_start IS DISTINCT FROM t.start_at OR rr.planned_end IS DISTINCT FROM t.end_at THEN
            RAISE EXCEPTION 'reservation_id may change once only when an Approval Hold is released and replaced by a standard Tournament Hold';
        END IF;
    END IF;

    IF OLD.removed_at IS NOT NULL THEN
        IF NEW.removed_at IS DISTINCT FROM OLD.removed_at OR NEW.removal_cause IS DISTINCT FROM OLD.removal_cause
           OR NEW.reservation_id IS DISTINCT FROM OLD.reservation_id THEN
            RAISE EXCEPTION 'Removed Tournament Resource history is immutable';
        END IF;
    ELSIF NEW.removed_at IS NOT NULL THEN
        IF t.status <> 'ACTIVE' THEN
            RAISE EXCEPTION 'A Tournament Resource may be removed only while the Tournament is ACTIVE';
        END IF;
        NEW.removed_at := v_now;
        IF NEW.removal_cause NOT IN ('RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED') THEN
            RAISE EXCEPTION 'ACTIVE Tournament Resource removal requires a canonical operational cause';
        END IF;
    ELSIF NEW.removal_cause IS NOT NULL THEN
        RAISE EXCEPTION 'removal_cause requires removed_at';
    END IF;

    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.guard_resource_due_boundary()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz; t tournament.tournament%ROWTYPE;
BEGIN
    v_now := tournament.require_command_scope(OLD.tournament_id, NULL, OLD.resource_id);
    IF TG_OP='UPDATE' AND OLD.removed_at IS NULL AND NEW.removed_at IS NOT NULL THEN
        SELECT * INTO t FROM tournament.tournament WHERE id=OLD.tournament_id;
        IF t.status='ACTIVE' AND v_now >= t.end_at THEN
            RAISE EXCEPTION 'Tournament completion boundary owns the state before ACTIVE Resource removal at/after endAt';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.guard_tournament_participant()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz;
    t tournament.tournament%ROWTYPE;
    u iam.user_account%ROWTYPE;
    v_active integer;
    v_occupied integer;
    v_banned boolean;
    v_boundary_restore boolean := false;
BEGIN
    v_now := tournament.require_command_scope(COALESCE(NEW.tournament_id, OLD.tournament_id), NULL, NULL, COALESCE(NEW.user_id, OLD.user_id));
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Tournament Participant history may not be deleted';
    END IF;

    SELECT * INTO t FROM tournament.tournament WHERE id = NEW.tournament_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament does not exist'; END IF;
    SELECT * INTO u FROM iam.user_account WHERE id = NEW.user_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament Participant User does not exist'; END IF;
    SELECT EXISTS (
        SELECT 1 FROM trust.ban_instance b
         WHERE b.user_id = NEW.user_id AND b.status = 'ACTIVE'
           AND b.activated_at <= v_now AND b.ends_at > v_now
    ) INTO v_banned;

    IF TG_OP='UPDATE' AND OLD.status='INELIGIBLE' AND OLD.ineligible_reason='BAN' AND NEW.status='JOINED' THEN
        IF t.status='WAITING_FOR_PLAYERS' AND v_now >= t.checkpoint_at
           AND NOT EXISTS (
               SELECT 1 FROM trust.ban_instance b
                WHERE b.user_id=NEW.user_id AND b.activated_at <= t.checkpoint_at AND b.ends_at > t.checkpoint_at
           ) THEN
            v_boundary_restore := true;
        ELSIF t.status='CONFIRMED' AND v_now >= t.start_at
           AND NOT EXISTS (
               SELECT 1 FROM trust.ban_instance b
                WHERE b.user_id=NEW.user_id AND b.activated_at <= t.start_at AND b.ends_at > t.start_at
           ) THEN
            v_boundary_restore := true;
        END IF;
    END IF;

    -- Once a due boundary is reached, no participant mutation may change its result.
    -- The only exception is catching up a BAN-only restoration that was already effective at that boundary.
    IF t.status='WAITING_FOR_PLAYERS' AND v_now >= t.checkpoint_at AND NOT v_boundary_restore THEN
        RAISE EXCEPTION 'Tournament checkpoint is overdue; resolve the checkpoint before participant mutation';
    END IF;
    IF t.status='CONFIRMED' AND v_now >= t.start_at AND NOT v_boundary_restore THEN
        RAISE EXCEPTION 'Tournament start is due; resolve startAt before participant mutation';
    END IF;

    IF TG_OP = 'INSERT' THEN
        NEW.joined_at := v_now;
        NEW.status_changed_at := NEW.joined_at;
        NEW.status := 'JOINED';
        NEW.left_at := NULL;
        NEW.removed_at := NULL;
        NEW.ineligible_reason := NULL;

        IF NOT u.phone_verified OR u.anonymised_at IS NOT NULL OR v_banned THEN
            RAISE EXCEPTION 'Tournament join requires an Account-Verified, non-banned active User';
        END IF;
        IF t.status = 'PENDING_VENUE_APPROVAL' THEN
            IF t.host_type <> 'PLAYER' OR NOT t.creator_participates OR NEW.user_id IS DISTINCT FROM t.creator_user_id
               OR NOT tournament.created_in_command(t.id) THEN
                RAISE EXCEPTION 'While PENDING_VENUE_APPROVAL only the participating Player Creator may have a Participant row';
            END IF;
        ELSIF t.status NOT IN ('WAITING_FOR_PLAYERS','CONFIRMED') OR v_now >= t.start_at THEN
            RAISE EXCEPTION 'Users may join only WAITING_FOR_PLAYERS/CONFIRMED before startAt';
        END IF;
        v_occupied := tournament.capacity_occupied_count(t.id);
        IF v_occupied >= t.capacity THEN
            RAISE EXCEPTION 'Tournament participant capacity is full, including BAN-only reserved slots';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.tournament_id IS DISTINCT FROM OLD.tournament_id
       OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.joined_at IS DISTINCT FROM OLD.joined_at THEN
        RAISE EXCEPTION 'Tournament Participant identity/join timestamp is immutable';
    END IF;
    IF OLD.left_at IS NOT NULL AND NEW.left_at IS DISTINCT FROM OLD.left_at THEN
        RAISE EXCEPTION 'left_at is immutable once recorded';
    END IF;
    IF OLD.removed_at IS NOT NULL AND NEW.removed_at IS DISTINCT FROM OLD.removed_at THEN
        RAISE EXCEPTION 'removed_at is immutable once recorded';
    END IF;
    IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
        -- v1.1.17 cause precedence: account deletion permanently defeats BAN-only
        -- restoration eligibility. Permit exactly one reason-only reclassification
        -- while retaining the existing INELIGIBLE status and its status timestamp.
        IF OLD.status='INELIGIBLE' AND OLD.ineligible_reason='BAN' AND u.anonymised_at IS NOT NULL
           AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE') THEN
            IF NEW.status_changed_at IS DISTINCT FROM OLD.status_changed_at
               OR NEW.left_at IS DISTINCT FROM OLD.left_at
               OR NEW.removed_at IS DISTINCT FROM OLD.removed_at THEN
                RAISE EXCEPTION 'BAN to ACCOUNT_DELETED cause reclassification may not mutate other participant lifecycle facts';
            END IF;
            NEW.ineligible_reason := 'ACCOUNT_DELETED';
            RETURN NEW;
        END IF;
        IF NEW.status_changed_at IS DISTINCT FROM OLD.status_changed_at
           OR NEW.left_at IS DISTINCT FROM OLD.left_at OR NEW.removed_at IS DISTINCT FROM OLD.removed_at
           OR NEW.ineligible_reason IS DISTINCT FROM OLD.ineligible_reason THEN
            RAISE EXCEPTION 'Participant lifecycle facts change only with a status transition except BAN to ACCOUNT_DELETED cause precedence';
        END IF;
        RETURN NEW;
    END IF;
    IF t.status IN ('COMPLETED','REJECTED','CANCELLED') THEN
        RAISE EXCEPTION 'Participant state cannot change after Tournament terminal state';
    END IF;

    NEW.status_changed_at := v_now;
    IF NEW.status = 'JOINED' THEN
        IF NOT v_boundary_restore AND (v_now >= t.start_at OR NOT (
               t.status IN ('WAITING_FOR_PLAYERS','CONFIRMED')
               OR (t.status='PENDING_VENUE_APPROVAL' AND t.host_type='PLAYER' AND t.creator_participates AND NEW.user_id=t.creator_user_id)
           )) THEN
            RAISE EXCEPTION 'Participant may return/join only before startAt in an eligible Tournament lifecycle state';
        END IF;
        IF NOT u.phone_verified OR u.anonymised_at IS NOT NULL OR v_banned THEN
            RAISE EXCEPTION 'JOINED participant must be Account-Verified, active and not banned';
        END IF;
        NEW.ineligible_reason := NULL;
        v_occupied := tournament.capacity_occupied_count(t.id);
        -- BAN-only restoration consumes its already-reserved capacity slot, so it must
        -- not be rejected merely because all slots are occupied. Other returns still
        -- require a free slot.
        IF NOT (OLD.status='JOINED' OR (OLD.status='INELIGIBLE' AND OLD.ineligible_reason='BAN'))
           AND v_occupied >= t.capacity THEN
            RAISE EXCEPTION 'Tournament participant capacity is full, including BAN-only reserved slots';
        END IF;
    ELSIF NEW.status = 'LEFT' THEN
        IF v_now >= t.start_at THEN
            RAISE EXCEPTION 'Participant may Leave only before startAt';
        END IF;
        IF NEW.left_at IS NULL THEN NEW.left_at := NEW.status_changed_at; END IF;
    ELSIF NEW.status = 'REMOVED' THEN
        IF v_now >= t.start_at THEN
            RAISE EXCEPTION 'Organizer may Remove a Participant only before startAt';
        END IF;
        IF NEW.removed_at IS NULL THEN NEW.removed_at := NEW.status_changed_at; END IF;
    ELSIF NEW.status = 'INELIGIBLE' THEN
        -- ACCOUNT_DELETED has precedence over BAN because a deleted/anonymised
        -- account can never become JOINED again when a Ban later expires/lifts.
        IF u.anonymised_at IS NOT NULL THEN
            NEW.ineligible_reason := 'ACCOUNT_DELETED';
        ELSIF v_banned THEN
            NEW.ineligible_reason := 'BAN';
        ELSIF NULLIF(BTRIM(NEW.ineligible_reason),'') IS NULL THEN
            RAISE EXCEPTION 'INELIGIBLE requires an explicit reason';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.prepare_tournament_history()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz;
    t tournament.tournament%ROWTYPE;
    v_seq bigint;
    v_prev_status text;
BEGIN
    v_now := tournament.require_command_scope(NEW.tournament_id);
    SELECT * INTO t FROM tournament.tournament WHERE id = NEW.tournament_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament history requires an existing Tournament'; END IF;

    SELECT h.sequence, h.to_status INTO v_seq, v_prev_status
      FROM tournament.tournament_history h
     WHERE h.tournament_id = NEW.tournament_id
     ORDER BY h.sequence DESC LIMIT 1;

    IF v_seq IS NULL THEN
        NEW.sequence := 1;
        NEW.from_status := NULL;
        NEW.occurred_at := t.created_at;
    ELSE
        NEW.sequence := v_seq + 1;
        NEW.from_status := v_prev_status;
        NEW.occurred_at := v_now;
    END IF;
    IF NEW.to_status IS NULL THEN RAISE EXCEPTION 'Tournament history to_status is required'; END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.assert_tournament_history_chain(p_tournament_id uuid)
RETURNS void
LANGUAGE plpgsql
AS $function$
DECLARE
    t tournament.tournament%ROWTYPE;
    h record;
    a audit.audit_event%ROWTYPE;
    v_prev text := NULL;
    v_expected text;
    v_first boolean := true;
BEGIN
    SELECT * INTO t FROM tournament.tournament WHERE id = p_tournament_id;
    IF NOT FOUND THEN RETURN; END IF;

    FOR h IN SELECT * FROM tournament.tournament_history WHERE tournament_id=t.id ORDER BY sequence LOOP
        IF v_first THEN
            IF h.sequence <> 1 OR h.from_status IS NOT NULL OR h.occurred_at IS DISTINCT FROM t.created_at THEN
                RAISE EXCEPTION 'Tournament first history row must be sequence 1, from_status NULL and occur at created_at';
            END IF;
            IF (t.host_type='PLAYER' AND h.to_status <> 'PENDING_VENUE_APPROVAL')
               OR (t.host_type='VENUE' AND h.to_status <> 'WAITING_FOR_PLAYERS') THEN
                RAISE EXCEPTION 'Tournament first history state does not match host type';
            END IF;
            v_first := false;
        ELSE
            IF h.from_status IS DISTINCT FROM v_prev THEN
                RAISE EXCEPTION 'Tournament history chain is not contiguous at sequence %', h.sequence;
            END IF;
        END IF;

        SELECT * INTO a FROM audit.audit_event ae
         WHERE ae.subject_type='TOURNAMENT' AND ae.subject_id=t.id
           AND ae.action='TOURNAMENT_STATUS_TRANSITION'
           AND ae.occurred_at=h.occurred_at
           AND ae.actor_type=h.actor_type
           AND ae.actor_id IS NOT DISTINCT FROM h.actor_id
           AND ae.correlation_id=h.correlation_id
         LIMIT 1;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Tournament history sequence % requires matching audit_event', h.sequence;
        END IF;

        IF h.actor_type='CUSTOMER' AND h.actor_id IS DISTINCT FROM t.creator_user_id THEN
            RAISE EXCEPTION 'Tournament CUSTOMER state actor must be the Player Creator';
        ELSIF h.actor_type='VENUE' AND NOT EXISTS (
            SELECT 1 FROM iam.venue_account va WHERE va.id=h.actor_id AND va.venue_id=t.venue_id
        ) THEN
            RAISE EXCEPTION 'Tournament VENUE actor must belong to the Tournament Venue';
        ELSIF h.actor_type='ADMIN' AND NOT EXISTS (SELECT 1 FROM iam.admin_account ad WHERE ad.id=h.actor_id) THEN
            RAISE EXCEPTION 'Tournament ADMIN actor does not exist';
        END IF;

        IF h.from_status IS NULL THEN
            IF t.host_type='PLAYER' AND (h.actor_type<>'CUSTOMER' OR h.actor_id IS DISTINCT FROM t.creator_user_id) THEN
                RAISE EXCEPTION 'Player-hosted Tournament creation history requires Creator actor';
            ELSIF t.host_type='VENUE' AND h.actor_type<>'VENUE' THEN
                RAISE EXCEPTION 'Venue-hosted Tournament creation history requires Venue actor';
            END IF;
        ELSIF h.from_status='PENDING_VENUE_APPROVAL' AND h.to_status='WAITING_FOR_PLAYERS' THEN
            IF h.actor_type<>'VENUE' OR h.terminal_reason IS NOT NULL OR h.occurred_at >= t.approval_expires_at THEN
                RAISE EXCEPTION 'Venue Accept transition is invalid';
            END IF;
        ELSIF h.from_status='PENDING_VENUE_APPROVAL' AND h.to_status='REJECTED' THEN
            IF h.terminal_reason IS NOT NULL OR NOT (
                (h.actor_type='VENUE' AND h.occurred_at < t.approval_expires_at)
                OR (h.actor_type='SYSTEM' AND h.occurred_at >= t.approval_expires_at)
            ) THEN
                RAISE EXCEPTION 'Rejection requires Venue before expiry or SYSTEM at/after expiry, with no reason';
            END IF;
            v_expected := tournament.highest_current_cancellation_reason(t.id,h.from_status,h.occurred_at);
            IF v_expected IS NOT NULL THEN
                RAISE EXCEPTION 'Rejection cannot bypass a higher-priority cancellation condition: %', v_expected;
            END IF;
        ELSIF h.from_status='PENDING_VENUE_APPROVAL' AND h.to_status='CANCELLED' THEN
            IF h.terminal_reason='CREATOR_CANCELLED' THEN
                IF h.actor_type<>'CUSTOMER' OR h.occurred_at >= t.checkpoint_at THEN RAISE EXCEPTION 'Creator cancellation is invalid'; END IF;
            ELSIF h.terminal_reason IN ('VENUE_ACCOUNT_DISABLED','CREATOR_VERIFIED_STATUS_REVOKED','EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED') THEN
                IF h.actor_type<>'SYSTEM' THEN RAISE EXCEPTION 'System Tournament cascade requires SYSTEM actor'; END IF;
            ELSIF h.terminal_reason='ADMIN_CANCELLED' THEN
                IF h.actor_type<>'ADMIN' THEN RAISE EXCEPTION 'Admin cancellation requires ADMIN actor'; END IF;
            ELSE RAISE EXCEPTION 'Invalid PENDING Tournament cancellation reason %', h.terminal_reason; END IF;
        ELSIF h.from_status='WAITING_FOR_PLAYERS' AND h.to_status='CONFIRMED' THEN
            IF h.actor_type<>'SYSTEM' OR h.terminal_reason IS NOT NULL OR h.occurred_at < t.checkpoint_at THEN
                RAISE EXCEPTION 'Tournament checkpoint confirmation transition is invalid';
            END IF;
        ELSIF h.from_status='WAITING_FOR_PLAYERS' AND h.to_status='CANCELLED' THEN
            IF h.terminal_reason='MINIMUM_PARTICIPANTS_NOT_REACHED' THEN
                IF h.actor_type<>'SYSTEM' OR h.occurred_at < t.checkpoint_at THEN RAISE EXCEPTION 'Minimum-participant cancellation is invalid'; END IF;
            ELSIF h.terminal_reason='CREATOR_CANCELLED' THEN
                IF h.actor_type<>'CUSTOMER' OR h.occurred_at >= t.checkpoint_at THEN RAISE EXCEPTION 'Creator cancellation is invalid'; END IF;
            ELSIF h.terminal_reason='VENUE_CANCELLED' THEN
                IF h.actor_type<>'VENUE' THEN RAISE EXCEPTION 'Venue cancellation requires VENUE actor'; END IF;
            ELSIF h.terminal_reason IN ('CREATOR_VERIFIED_STATUS_REVOKED','EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED') THEN
                IF h.actor_type<>'SYSTEM' THEN RAISE EXCEPTION 'System Tournament cascade requires SYSTEM actor'; END IF;
            ELSIF h.terminal_reason='ADMIN_CANCELLED' THEN
                IF h.actor_type<>'ADMIN' THEN RAISE EXCEPTION 'Admin cancellation requires ADMIN actor'; END IF;
            ELSE RAISE EXCEPTION 'Invalid WAITING Tournament cancellation reason %', h.terminal_reason; END IF;
        ELSIF h.from_status='CONFIRMED' AND h.to_status='ACTIVE' THEN
            IF h.actor_type<>'SYSTEM' OR h.terminal_reason IS NOT NULL OR h.occurred_at < t.start_at THEN
                RAISE EXCEPTION 'Tournament start transition is invalid';
            END IF;
        ELSIF h.from_status='CONFIRMED' AND h.to_status='CANCELLED' THEN
            IF h.terminal_reason='VENUE_CANCELLED' THEN
                IF h.actor_type<>'VENUE' OR NOT a.owner_password_used OR a.owner_password_outcome<>'SUCCESS' THEN
                    RAISE EXCEPTION 'Venue cancellation of CONFIRMED Tournament requires successful Owner Password audit';
                END IF;
            ELSIF h.terminal_reason IN ('EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED') THEN
                IF h.actor_type<>'SYSTEM' THEN RAISE EXCEPTION 'Operational cancellation requires SYSTEM actor'; END IF;
            ELSIF h.terminal_reason='ADMIN_CANCELLED' THEN
                IF h.actor_type<>'ADMIN' THEN RAISE EXCEPTION 'Admin cancellation requires ADMIN actor'; END IF;
            ELSE RAISE EXCEPTION 'Invalid CONFIRMED Tournament cancellation reason %', h.terminal_reason; END IF;
        ELSIF h.from_status='ACTIVE' AND h.to_status='COMPLETED' THEN
            IF h.actor_type<>'SYSTEM' OR h.terminal_reason IS NOT NULL OR h.occurred_at < t.end_at THEN
                RAISE EXCEPTION 'Tournament completion transition is invalid';
            END IF;
        ELSIF h.from_status='ACTIVE' AND h.to_status='CANCELLED' THEN
            IF h.terminal_reason IN ('EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED') THEN
                IF h.actor_type<>'SYSTEM' THEN RAISE EXCEPTION 'Operational ACTIVE cancellation requires SYSTEM actor'; END IF;
            ELSIF h.terminal_reason='TOURNAMENT_OPERATIONAL_TERMINATION' THEN
                IF h.actor_type<>'VENUE' OR NOT a.owner_password_used OR a.owner_password_outcome<>'SUCCESS'
                   OR NULLIF(BTRIM(a.reason),'') IS NULL THEN
                    RAISE EXCEPTION 'Tournament Operational Termination requires Venue actor, Owner Password and mandatory reason';
                END IF;
            ELSIF h.terminal_reason='ADMIN_CANCELLED' THEN
                IF h.actor_type<>'ADMIN' THEN RAISE EXCEPTION 'ACTIVE Admin support cancellation requires ADMIN actor'; END IF;
            ELSE RAISE EXCEPTION 'Invalid ACTIVE Tournament cancellation reason %', h.terminal_reason; END IF;
        ELSE
            RAISE EXCEPTION 'Invalid Tournament state transition % -> %', h.from_status, h.to_status;
        END IF;

        IF h.to_status='CANCELLED' THEN
            v_expected := tournament.highest_current_cancellation_reason(t.id,h.from_status,h.occurred_at);
            IF v_expected IS NOT NULL AND h.terminal_reason IS DISTINCT FROM v_expected THEN
                RAISE EXCEPTION 'Tournament terminal reason % violates frozen priority; expected %', h.terminal_reason, v_expected;
            END IF;
        END IF;
        v_prev := h.to_status;
    END LOOP;

    IF v_first THEN RAISE EXCEPTION 'Tournament requires append-only state history'; END IF;
    IF v_prev IS DISTINCT FROM t.status THEN RAISE EXCEPTION 'Tournament current status does not match latest history state'; END IF;
    SELECT hist.terminal_reason INTO v_expected
      FROM tournament.tournament_history AS hist
     WHERE hist.tournament_id = t.id
     ORDER BY hist.sequence DESC
     LIMIT 1;
    IF v_expected IS DISTINCT FROM t.terminal_reason THEN
        RAISE EXCEPTION 'Tournament terminal_reason does not match latest history transition';
    END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.assert_terminal_reason_provenance()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_expected text;
    t tournament.tournament%ROWTYPE;
BEGIN
    IF NEW.to_status NOT IN ('CANCELLED','REJECTED') THEN RETURN NULL; END IF;
    SELECT * INTO t FROM tournament.tournament WHERE id=NEW.tournament_id;
    v_expected := tournament.highest_current_cancellation_reason(NEW.tournament_id,NEW.from_status,NEW.occurred_at);

    IF NEW.to_status='REJECTED' THEN
        IF NEW.terminal_reason IS NOT NULL OR v_expected IS NOT NULL THEN
            RAISE EXCEPTION 'Request rejection carries no reason and cannot override a higher-priority condition';
        END IF;
        RETURN NULL;
    END IF;

    IF NEW.terminal_reason IN ('RESOURCE_OWNER_REVIEW_REQUIRED','RESOURCE_EMERGENCY_OUTAGE','EMERGENCY_CLOSURE','VENUE_ACCOUNT_DISABLED','MINIMUM_PARTICIPANTS_NOT_REACHED','CREATOR_VERIFIED_STATUS_REVOKED') THEN
        IF v_expected IS NULL OR v_expected IS DISTINCT FROM NEW.terminal_reason THEN
            RAISE EXCEPTION 'Condition-driven Tournament reason % lacks matching highest-priority producer (expected %)', NEW.terminal_reason, v_expected;
        END IF;
    ELSIF NEW.terminal_reason='VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME' THEN
        RAISE EXCEPTION 'Normal Tournament approval expiry uses REJECTED without a terminal reason';
    ELSIF NEW.terminal_reason IN ('CREATOR_CANCELLED','VENUE_CANCELLED','ADMIN_CANCELLED','TOURNAMENT_OPERATIONAL_TERMINATION') THEN
        IF v_expected IS NOT NULL THEN
            RAISE EXCEPTION 'Explicit Tournament cancellation cannot bypass higher frozen reason %', v_expected;
        END IF;
    END IF;
    RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.assert_tournament_aggregate(p_tournament_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz;
    t tournament.tournament%ROWTYPE;
    s venue.operating_session%ROWTYPE;
    v_resources integer;
    v_unremoved integer;
    v_expected_cost numeric(12,2);
    v_participant_eval_at timestamptz;
BEGIN
    SELECT * INTO t FROM tournament.tournament WHERE id=p_tournament_id;
    IF NOT FOUND THEN RETURN; END IF;
    v_now := tournament.require_command_scope(t.id, t.venue_id);

    SELECT * INTO s FROM venue.operating_session WHERE id=t.operating_session_id;
    IF NOT FOUND OR s.venue_id IS DISTINCT FROM t.venue_id
       OR t.start_at < lower(s.session_period) OR t.end_at > upper(s.session_period)
       OR t.business_date IS DISTINCT FROM s.operating_day THEN
        RAISE EXCEPTION 'Tournament must fit completely inside one matching Venue Operating Session and businessDate';
    END IF;

    SELECT COUNT(*)::integer,
           COALESCE(SUM(ROUND(tr.hourly_price_snapshot * t.nominal_minutes / 60.0,2)),0)::numeric(12,2)
      INTO v_resources, v_expected_cost
      FROM tournament.tournament_resource tr WHERE tr.tournament_id=t.id;
    IF v_resources NOT BETWEEN 1 AND 4 THEN RAISE EXCEPTION 'Tournament requires exactly 1 to 4 Resource rows'; END IF;
    IF t.venue_cost_total IS DISTINCT FROM v_expected_cost THEN
        RAISE EXCEPTION 'Tournament venue_cost_total % does not equal immutable Resource snapshot total %', t.venue_cost_total, v_expected_cost;
    END IF;

    IF t.host_type='PLAYER' AND t.creator_participates AND NOT EXISTS (
        SELECT 1 FROM tournament.tournament_participant p WHERE p.tournament_id=t.id AND p.user_id=t.creator_user_id
    ) THEN
        RAISE EXCEPTION 'Participating Player Creator requires a retained Participant row';
    END IF;

    IF t.status='PENDING_VENUE_APPROVAL' THEN
        IF EXISTS (SELECT 1 FROM tournament.tournament_resource tr WHERE tr.tournament_id=t.id AND tr.removed_at IS NOT NULL) THEN
            RAISE EXCEPTION 'Pre-approval Tournament cannot contain removed Resources';
        END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_resource tr
            LEFT JOIN inventory.resource_reservation rr ON rr.id=tr.reservation_id
            WHERE tr.tournament_id=t.id AND (rr.id IS NULL OR rr.reservation_type<>'TOURNAMENT_APPROVAL_HOLD' OR NOT rr.active_flag
                OR rr.tournament_id IS DISTINCT FROM t.id OR rr.resource_id IS DISTINCT FROM tr.resource_id
                OR rr.planned_start IS DISTINCT FROM t.start_at OR rr.planned_end IS DISTINCT FROM t.end_at)
        ) THEN RAISE EXCEPTION 'PENDING_VENUE_APPROVAL requires active Approval Holds for every Resource'; END IF;
    ELSIF t.status IN ('WAITING_FOR_PLAYERS','CONFIRMED') THEN
        IF EXISTS (SELECT 1 FROM tournament.tournament_resource tr WHERE tr.tournament_id=t.id AND tr.removed_at IS NOT NULL) THEN
            RAISE EXCEPTION 'Pre-start Tournament cannot contain removed Resources';
        END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_resource tr
            LEFT JOIN inventory.resource_reservation rr ON rr.id=tr.reservation_id
            WHERE tr.tournament_id=t.id AND (rr.id IS NULL OR rr.reservation_type<>'TOURNAMENT_HOLD' OR NOT rr.active_flag
                OR rr.tournament_id IS DISTINCT FROM t.id OR rr.resource_id IS DISTINCT FROM tr.resource_id
                OR rr.planned_start IS DISTINCT FROM t.start_at OR rr.planned_end IS DISTINCT FROM t.end_at)
        ) THEN RAISE EXCEPTION 'WAITING/CONFIRMED Tournament requires active standard Holds for every Resource'; END IF;
    ELSIF t.status='ACTIVE' THEN
        SELECT COUNT(*)::integer INTO v_unremoved FROM tournament.tournament_resource tr WHERE tr.tournament_id=t.id AND tr.removed_at IS NULL;
        IF v_unremoved < 1 THEN RAISE EXCEPTION 'ACTIVE Tournament requires at least one remaining Resource'; END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_resource tr
            LEFT JOIN inventory.resource_reservation rr ON rr.id=tr.reservation_id
            WHERE tr.tournament_id=t.id AND tr.removed_at IS NULL
              AND (rr.id IS NULL OR rr.reservation_type<>'TOURNAMENT_HOLD' OR NOT rr.active_flag
                   OR rr.tournament_id IS DISTINCT FROM t.id OR rr.resource_id IS DISTINCT FROM tr.resource_id)
        ) THEN RAISE EXCEPTION 'ACTIVE Tournament requires an active standard Hold for each remaining Resource'; END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_resource tr
            JOIN inventory.resource_reservation rr ON rr.id=tr.reservation_id
            WHERE tr.tournament_id=t.id AND tr.removed_at IS NOT NULL
              AND (rr.active_flag OR rr.actual_reservation_release_at IS DISTINCT FROM tr.removed_at)
        ) THEN RAISE EXCEPTION 'Removed ACTIVE Tournament Resource requires its Hold released at removed_at'; END IF;
    ELSE
        IF EXISTS (SELECT 1 FROM inventory.resource_reservation rr WHERE rr.tournament_id=t.id AND rr.active_flag) THEN
            RAISE EXCEPTION 'Terminal Tournament may not retain active Resource Holds';
        END IF;
    END IF;

    -- Capacity safety: JOINED plus BAN-only INELIGIBLE reserved slots may never
    -- exceed the immutable Tournament capacity. Active Participant count remains separate.
    IF tournament.capacity_occupied_count(t.id) > t.capacity THEN
        RAISE EXCEPTION 'Tournament capacity occupancy exceeds capacity';
    END IF;

    -- Ban expiry is deadline-effective. For an overdue checkpoint/start, evaluate participant
    -- restoration at the boundary itself so a late Ban worker cannot change the Product result.
    IF t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED') THEN
        v_participant_eval_at := v_now;
        IF t.status='WAITING_FOR_PLAYERS' AND v_now >= t.checkpoint_at THEN
            v_participant_eval_at := t.checkpoint_at;
        ELSIF t.status='CONFIRMED' AND v_now >= t.start_at THEN
            v_participant_eval_at := t.start_at;
        END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_participant p
            JOIN iam.user_account u ON u.id=p.user_id
             WHERE p.tournament_id=t.id
               AND p.status='INELIGIBLE'
               AND p.ineligible_reason='BAN'
               AND u.anonymised_at IS NOT NULL
        ) THEN
            RAISE EXCEPTION 'Deleted/anonymised Participant cannot retain BAN-only ineligibility or its reserved capacity slot';
        END IF;
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_participant p
            JOIN iam.user_account u ON u.id=p.user_id
             WHERE p.tournament_id=t.id AND p.status='INELIGIBLE' AND p.ineligible_reason='BAN'
               AND u.anonymised_at IS NULL
               AND NOT EXISTS (
                   SELECT 1 FROM trust.ban_instance b
                    WHERE b.user_id=p.user_id
                      AND b.activated_at <= v_participant_eval_at AND b.ends_at > v_participant_eval_at
               )
        ) THEN
            RAISE EXCEPTION 'Expired Ban requires automatic Tournament Participant restoration before the authoritative boundary can commit';
        END IF;
    END IF;

    -- Canonical scheduler contract from Technical Architecture v1.2. Only live jobs count.
    IF t.status='PENDING_VENUE_APPROVAL' THEN
        IF NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_APPROVAL_EXPIRY' AND j.due_at=t.approval_expires_at AND j.status IN ('PENDING','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_CHECKPOINT' AND j.due_at=t.checkpoint_at AND j.status IN ('PENDING','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_START' AND j.due_at=t.start_at AND j.status IN ('PENDING','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_COMPLETION' AND j.due_at=t.end_at AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'PENDING Tournament requires live approval/checkpoint/start/completion jobs';
        END IF;
    ELSIF t.status='WAITING_FOR_PLAYERS' THEN
        IF EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_APPROVAL_EXPIRY' AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'Approved Tournament may not retain a live approval-expiry job';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_CHECKPOINT' AND j.due_at=t.checkpoint_at AND j.status IN ('PENDING','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_START' AND j.due_at=t.start_at AND j.status IN ('PENDING','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_COMPLETION' AND j.due_at=t.end_at AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'WAITING Tournament requires live checkpoint/start/completion jobs';
        END IF;
    ELSIF t.status='CONFIRMED' THEN
        IF EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type IN ('TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT') AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'CONFIRMED Tournament may not retain live approval/checkpoint jobs';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_START' AND j.due_at=t.start_at AND j.status IN ('PENDING','LEASED'))
           OR NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_COMPLETION' AND j.due_at=t.end_at AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'CONFIRMED Tournament requires live start/completion jobs';
        END IF;
    ELSIF t.status='ACTIVE' THEN
        IF EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type IN ('TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT','TOURNAMENT_START') AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'ACTIVE Tournament may not retain obsolete live approval/checkpoint/start jobs';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type='TOURNAMENT_COMPLETION' AND j.due_at=t.end_at AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'ACTIVE Tournament requires a live completion job';
        END IF;
    ELSE
        IF EXISTS (SELECT 1 FROM technical.scheduled_job j WHERE j.subject_id=t.id AND j.type IN ('TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT','TOURNAMENT_START','TOURNAMENT_COMPLETION') AND j.status IN ('PENDING','LEASED')) THEN
            RAISE EXCEPTION 'Terminal Tournament may not retain live Tournament scheduler jobs';
        END IF;
    END IF;

    PERFORM tournament.assert_tournament_history_chain(t.id);
END;
$function$;



-- Cross-module User mutations (Ban/delete) must declare every current non-terminal
-- Tournament containing that User before the DB clock is sampled. User row locking
-- prevents a concurrent join from introducing a new participation while this check runs.
CREATE OR REPLACE FUNCTION tournament.require_user_tournament_scope(p_user_id uuid)
RETURNS timestamptz
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz;
    c record;
BEGIN
    v_now := tournament.require_command_scope(NULL, NULL, NULL, p_user_id);
    SELECT * INTO STRICT c
      FROM pg_temp.e7gz_tournament_command_context
     WHERE singleton AND transaction_id = pg_current_xact_id();
    IF EXISTS (
        SELECT 1
          FROM tournament.tournament_participant p
          JOIN tournament.tournament t ON t.id=p.tournament_id
         WHERE p.user_id=p_user_id
           AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE')
           AND NOT (t.id = ANY(c.tournament_ids || c.new_tournament_ids))
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'User Tournament cascade exceeds the prelocked command scope; retry with every affected Tournament id';
    END IF;
    RETURN v_now;
END;
$function$;
REVOKE ALL ON FUNCTION tournament.require_user_tournament_scope(uuid) FROM PUBLIC;

-- v1.1.17: account deletion outranks BAN-only restoration eligibility. The user
-- deletion command must reclassify an existing INELIGIBLE/BAN row to
-- INELIGIBLE/ACCOUNT_DELETED in the same transaction; otherwise the old BAN
-- cause could later request an impossible auto-restoration and retain capacity.
CREATE OR REPLACE FUNCTION tournament.assert_deleted_user_participant_cascade()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
BEGIN
    IF NEW.anonymised_at IS NOT NULL AND OLD.anonymised_at IS NULL AND EXISTS (
        SELECT 1 FROM tournament.tournament_participant p
        JOIN tournament.tournament t ON t.id=p.tournament_id
        WHERE p.user_id=NEW.id
          AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE')
    ) THEN
        PERFORM tournament.require_user_tournament_scope(NEW.id);
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_participant p
            JOIN tournament.tournament t ON t.id=p.tournament_id
            WHERE p.user_id=NEW.id
              AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE')
              AND (
                  p.status='JOINED'
                  OR (p.status='INELIGIBLE' AND p.ineligible_reason='BAN')
              )
        ) THEN
            RAISE EXCEPTION 'Deleted/anonymised User must leave JOINED and cannot retain BAN-only Tournament ineligibility; reclassify to ACCOUNT_DELETED in the same transaction';
        END IF;
    END IF;
    RETURN NULL;
END;
$function$;


CREATE OR REPLACE FUNCTION tournament.assert_ban_participant_cascade()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM tournament.tournament_participant p
        JOIN tournament.tournament t ON t.id=p.tournament_id
        WHERE p.user_id=NEW.user_id AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE')
    ) THEN RETURN NULL; END IF;
    v_now := tournament.require_user_tournament_scope(NEW.user_id);
    IF NEW.status='ACTIVE' AND NEW.ends_at > v_now THEN
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_participant p
            JOIN tournament.tournament t ON t.id=p.tournament_id
            WHERE p.user_id=NEW.user_id
              AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE')
              AND p.status='JOINED'
        ) THEN
            RAISE EXCEPTION 'Active Ban must mark Tournament participation INELIGIBLE in the same transaction';
        END IF;
    END IF;
    RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.assert_ban_participant_restore()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM tournament.tournament_participant p
        JOIN tournament.tournament t ON t.id=p.tournament_id
        WHERE p.user_id=NEW.user_id AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE')
    ) THEN RETURN NULL; END IF;
    v_now := tournament.require_user_tournament_scope(NEW.user_id);
    IF NOT EXISTS (
        SELECT 1 FROM trust.ban_instance b
         WHERE b.user_id=NEW.user_id AND b.status='ACTIVE'
           AND b.activated_at <= v_now AND b.ends_at > v_now
    ) AND EXISTS (
        SELECT 1 FROM tournament.tournament_participant p
        JOIN tournament.tournament t ON t.id=p.tournament_id
        JOIN iam.user_account u ON u.id=p.user_id
        WHERE p.user_id=NEW.user_id AND p.status='INELIGIBLE' AND p.ineligible_reason='BAN'
          AND u.anonymised_at IS NULL
          AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED')
          AND v_now < t.start_at
    ) THEN
        RAISE EXCEPTION 'Ban expiry/lift requires automatic restoration of BAN-only Tournament Participants before Start';
    END IF;
    RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.guard_tournament_scheduled_job()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_types text[] := ARRAY['TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT','TOURNAMENT_START','TOURNAMENT_COMPLETION'];
BEGIN
    IF NEW.type IN ('TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT','TOURNAMENT_START','TOURNAMENT_COMPLETION') THEN
        PERFORM tournament.require_command_scope(NEW.subject_id);
    END IF;
    IF TG_OP='UPDATE' AND OLD.type IN ('TOURNAMENT_APPROVAL_EXPIRY','TOURNAMENT_CHECKPOINT','TOURNAMENT_START','TOURNAMENT_COMPLETION') THEN
        PERFORM tournament.require_command_scope(OLD.subject_id);
    END IF;
    IF NEW.type = ANY(v_types) AND NEW.status='PAUSED' THEN
        RAISE EXCEPTION 'Tournament timers have no Product pause state';
    END IF;
    IF TG_OP='UPDATE' AND (OLD.type = ANY(v_types) OR NEW.type = ANY(v_types)) THEN
        IF NEW.type IS DISTINCT FROM OLD.type
           OR NEW.subject_id IS DISTINCT FROM OLD.subject_id
           OR NEW.due_at IS DISTINCT FROM OLD.due_at
           OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key THEN
            RAISE EXCEPTION 'Tournament scheduled-job type/subject/due/idempotency identity is immutable';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

-- Reservation writes are part of the same prelocked command, never an independent
-- clock or an undeclared Resource that can introduce a wait after capture.
CREATE OR REPLACE FUNCTION tournament.guard_reservation_command_scope()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
BEGIN
    IF TG_OP <> 'INSERT' AND OLD.tournament_id IS NOT NULL THEN
        PERFORM tournament.require_command_scope(OLD.tournament_id, NULL, OLD.resource_id);
    END IF;
    IF TG_OP <> 'DELETE' AND NEW.tournament_id IS NOT NULL THEN
        PERFORM tournament.require_command_scope(NEW.tournament_id, NULL, NEW.resource_id);
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_00_tournament_reservation_command_scope ON inventory.resource_reservation;
CREATE TRIGGER tr_00_tournament_reservation_command_scope
BEFORE INSERT OR UPDATE OR DELETE ON inventory.resource_reservation
FOR EACH ROW EXECUTE FUNCTION tournament.guard_reservation_command_scope();

-- FR-TRN-10 approval/rejection notification contract. This uses the EXISTING
-- TournamentRejected domain event; it introduces no new Product status or reason.
-- Provenance is registered only by an actual INSERT trigger inside the current
-- trusted Tournament command context. Dispatch remains strictly after COMMIT.
CREATE OR REPLACE FUNCTION tournament.register_rejection_outbox_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
BEGIN
    IF NEW.event_type <> 'TournamentRejected' OR NEW.aggregate_type <> 'TOURNAMENT' THEN
        RETURN NEW;
    END IF;
    IF pg_trigger_depth() = 0 THEN
        RAISE EXCEPTION 'Tournament rejection outbox registration is trigger-only';
    END IF;
    PERFORM tournament.require_command_scope(NEW.aggregate_id, NULL, NULL, NULL);
    IF NEW.state <> 'PENDING' OR NEW.attempt <> 0 OR NEW.dispatched_at IS NOT NULL THEN
        RAISE EXCEPTION 'Fresh TournamentRejected outbox event must be PENDING, attempt 0 and not dispatched';
    END IF;
    UPDATE pg_temp.e7gz_tournament_command_context c
       SET rejection_outbox_event_ids = array_append(c.rejection_outbox_event_ids, NEW.id)
     WHERE c.singleton
       AND c.transaction_id = pg_current_xact_id()
       AND NEW.aggregate_id = ANY(c.tournament_ids || c.new_tournament_ids);
    IF NOT FOUND THEN
        RAISE EXCEPTION 'TournamentRejected outbox INSERT is outside the current trusted Tournament command scope';
    END IF;
    RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION tournament.register_rejection_outbox_insert() FROM PUBLIC;
DROP TRIGGER IF EXISTS tr_register_tournament_rejection_outbox_insert ON technical.outbox_event;
CREATE TRIGGER tr_register_tournament_rejection_outbox_insert
AFTER INSERT ON technical.outbox_event
FOR EACH ROW EXECUTE FUNCTION tournament.register_rejection_outbox_insert();

CREATE OR REPLACE FUNCTION tournament.assert_rejection_notification_outbox()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    t tournament.tournament%ROWTYPE;
    c record;
BEGIN
    IF NEW.to_status <> 'REJECTED' THEN RETURN NULL; END IF;
    SELECT * INTO STRICT t FROM tournament.tournament WHERE id=NEW.tournament_id;
    PERFORM tournament.command_now();
    SELECT * INTO STRICT c
      FROM pg_temp.e7gz_tournament_command_context
     WHERE singleton AND transaction_id = pg_current_xact_id();
    IF NOT EXISTS (
        SELECT 1 FROM technical.outbox_event e
         WHERE e.event_type='TournamentRejected'
           AND e.aggregate_type='TOURNAMENT'
           AND e.aggregate_id=t.id
           AND e.correlation_id=NEW.correlation_id
           AND e.state='PENDING'
           AND e.attempt=0
           AND e.dispatched_at IS NULL
           AND e.id = ANY(c.rejection_outbox_event_ids)
           AND e.payload->>'recipientType'='CUSTOMER'
           AND e.payload->>'recipientId'=t.creator_user_id::text
           AND e.payload->>'tournamentId'=t.id::text
           AND e.payload->>'actorType'=NEW.actor_type
           AND e.payload->>'historySequence'=NEW.sequence::text
    ) THEN
        RAISE EXCEPTION 'Tournament rejection requires a fresh PENDING creator notification INSERT in the same trusted command transaction';
    END IF;
    RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_tournament_rejection_notification_outbox ON tournament.tournament_history;
CREATE CONSTRAINT TRIGGER tr_tournament_rejection_notification_outbox
AFTER INSERT ON tournament.tournament_history
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION tournament.assert_rejection_notification_outbox();


-- Final validation: run only after all v1.1.17 definitions are installed.
-- Upgrade preflight prohibits existing Tournament rows; fresh export is empty.
DO $validate$
DECLARE r record;
BEGIN
    FOR r IN SELECT id FROM tournament.tournament LOOP
        PERFORM tournament.assert_tournament_aggregate(r.id);
    END LOOP;
END
$validate$;


-- ============================================================================
-- E7GZ PS v1.1.18 TRUST HARDENING
-- Source hardening only. Product behaviour remains Product Specification v5.0.
-- PostgreSQL 16+.
-- ============================================================================

-- T18-01. Database-owned global Trust event sequence.
CREATE SEQUENCE IF NOT EXISTS trust.trust_event_sequence_seq AS bigint START WITH 1 INCREMENT BY 1 NO CYCLE;
ALTER SEQUENCE trust.trust_event_sequence_seq OWNED BY trust.trust_event.event_sequence;
DO $trust_seq_sync$
DECLARE v_next bigint;
BEGIN
    SELECT GREATEST(COALESCE(MAX(event_sequence),0) + 1, 1) INTO v_next FROM trust.trust_event;
    PERFORM setval('trust.trust_event_sequence_seq'::regclass, v_next, false);
END
$trust_seq_sync$;

CREATE OR REPLACE FUNCTION trust.prepare_trust_event_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    b booking.booking%ROWTYPE;
BEGIN
    -- Every Trust write serializes on the subject's commitment guard because replay
    -- may activate a Ban or change Verified Player eligibility in the same transaction.
    PERFORM 1
      FROM iam.user_commitment_guard g
     WHERE g.user_id = NEW.subject_user_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Trust event requires the subject User commitment guard';
    END IF;

    -- Caller supplied sequence values are ignored. The database is the sole generator.
    NEW.event_sequence := nextval('trust.trust_event_sequence_seq'::regclass);
    NEW.payload := COALESCE(NEW.payload, '{}'::jsonb);

    IF jsonb_typeof(NEW.payload) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'Trust event payload must be a JSON object';
    END IF;
    IF NEW.occurred_at < NEW.effective_at THEN
        RAISE EXCEPTION 'Trust event occurred_at cannot predate effective_at';
    END IF;

    IF NEW.event_type IN (
        'BOOKING_ATTENDED','BOOKING_ATTENDANCE_UNCONFIRMED',
        'BOOKING_ATTENDED_INTERRUPTED','BOOKING_NO_SHOW'
    ) THEN
        SELECT * INTO b FROM booking.booking WHERE id = NEW.booking_id;
        IF NOT FOUND OR b.source <> 'ONLINE' OR b.customer_id IS NULL THEN
            RAISE EXCEPTION '% requires an Online customer Booking', NEW.event_type;
        END IF;
        IF NEW.subject_user_id IS DISTINCT FROM b.customer_id THEN
            RAISE EXCEPTION '% subject_user_id must equal Booking customer_id', NEW.event_type;
        END IF;
        IF NEW.effective_at IS DISTINCT FROM b.start_at THEN
            RAISE EXCEPTION '% effective_at must equal booking.start_at', NEW.event_type;
        END IF;
    ELSIF NEW.event_type IN (
        'ADMIN_TRUST_ADJUSTMENT','VERIFIED_PLAYER_SUSPENDED',
        'VERIFIED_PLAYER_REVOKED','VERIFIED_PLAYER_RESTORED'
    ) THEN
        IF NEW.effective_at IS DISTINCT FROM NEW.occurred_at THEN
            RAISE EXCEPTION '% effective_at must equal occurred_at', NEW.event_type;
        END IF;
        IF NOT (NEW.payload ? 'adminId') OR NOT (NEW.payload ? 'correlationId') THEN
            RAISE EXCEPTION '% payload requires adminId and correlationId', NEW.event_type;
        END IF;
        BEGIN
            PERFORM (NEW.payload->>'adminId')::uuid;
            PERFORM (NEW.payload->>'correlationId')::uuid;
        EXCEPTION WHEN invalid_text_representation THEN
            RAISE EXCEPTION '% payload adminId/correlationId must be UUID values', NEW.event_type;
        END;
    END IF;

    RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION trust.prepare_trust_event_insert() FROM PUBLIC;
DROP TRIGGER IF EXISTS tr_00_trust_event_prepare ON trust.trust_event;
CREATE TRIGGER tr_00_trust_event_prepare
BEFORE INSERT ON trust.trust_event
FOR EACH ROW EXECUTE FUNCTION trust.prepare_trust_event_insert();

-- T18-02. Canonical Booking outcome events must match the resolved Attendance row.
CREATE OR REPLACE FUNCTION trust.assert_booking_outcome_event()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    b booking.booking%ROWTYPE;
    a attendance.attendance_record%ROWTYPE;
    v_expected_result text;
BEGIN
    IF NEW.event_type NOT IN (
        'BOOKING_ATTENDED','BOOKING_ATTENDANCE_UNCONFIRMED',
        'BOOKING_ATTENDED_INTERRUPTED','BOOKING_NO_SHOW'
    ) THEN
        RETURN NULL;
    END IF;

    SELECT * INTO b FROM booking.booking WHERE id = NEW.booking_id;
    IF NOT FOUND OR b.source <> 'ONLINE' OR b.customer_id IS NULL
       OR NEW.subject_user_id IS DISTINCT FROM b.customer_id
       OR NEW.effective_at IS DISTINCT FROM b.start_at THEN
        RAISE EXCEPTION 'Canonical Booking Trust outcome does not match its Online Booking';
    END IF;

    SELECT * INTO a FROM attendance.attendance_record WHERE booking_id = NEW.booking_id;
    IF NOT FOUND OR a.result IS NULL OR a.resolved_at IS NULL THEN
        RAISE EXCEPTION 'Canonical Booking Trust outcome requires resolved Attendance';
    END IF;

    v_expected_result := CASE NEW.event_type
        WHEN 'BOOKING_ATTENDED' THEN 'ATTENDED'
        WHEN 'BOOKING_ATTENDANCE_UNCONFIRMED' THEN 'ATTENDANCE_UNCONFIRMED'
        WHEN 'BOOKING_ATTENDED_INTERRUPTED' THEN 'ATTENDED_INTERRUPTED'
        WHEN 'BOOKING_NO_SHOW' THEN 'ABSENT_NO_SHOW'
    END;

    IF a.result IS DISTINCT FROM v_expected_result
       OR NEW.occurred_at IS DISTINCT FROM a.resolved_at THEN
        RAISE EXCEPTION 'Canonical Booking Trust outcome must match Attendance result/resolution time';
    END IF;
    RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_trust_booking_outcome_event ON trust.trust_event;
CREATE CONSTRAINT TRIGGER tr_trust_booking_outcome_event
AFTER INSERT ON trust.trust_event
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION trust.assert_booking_outcome_event();

-- T18-03. Admin Trust input events require same-transaction audited Admin evidence.
CREATE OR REPLACE FUNCTION trust.assert_admin_trust_event_audit()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.event_type NOT IN (
        'ADMIN_TRUST_ADJUSTMENT','VERIFIED_PLAYER_SUSPENDED',
        'VERIFIED_PLAYER_REVOKED','VERIFIED_PLAYER_RESTORED'
    ) THEN
        RETURN NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1
          FROM audit.audit_event a
         WHERE a.actor_type = 'ADMIN'
           AND a.actor_id = (NEW.payload->>'adminId')::uuid
           AND a.subject_id = NEW.subject_user_id
           AND a.occurred_at = NEW.occurred_at
           AND a.correlation_id = (NEW.payload->>'correlationId')::uuid
           AND NULLIF(BTRIM(a.reason),'') IS NOT NULL
    ) THEN
        RAISE EXCEPTION '% requires matching Admin audit identity/reason/timestamp', NEW.event_type;
    END IF;
    RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_trust_admin_event_audit ON trust.trust_event;
CREATE CONSTRAINT TRIGGER tr_trust_admin_event_audit
AFTER INSERT ON trust.trust_event
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION trust.assert_admin_trust_event_audit();

-- T18-03b. Every committed Trust input must have been folded into the live
-- projection in the same transaction. For retroactive inputs the final watermark
-- may remain at a later event, so recomputed_at proves that a replay actually ran.
CREATE OR REPLACE FUNCTION trust.assert_trust_event_projection_current()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    p trust.trust_projection%ROWTYPE;
    v_last_effective timestamptz;
    v_last_sequence bigint;
BEGIN
    SELECT * INTO p FROM trust.trust_projection WHERE user_id=NEW.subject_user_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Trust event requires a live Trust Projection by commit';
    END IF;
    SELECT e.effective_at,e.event_sequence INTO v_last_effective,v_last_sequence
      FROM trust.trust_event e
     WHERE e.subject_user_id=NEW.subject_user_id
     ORDER BY e.effective_at DESC,e.event_sequence DESC
     LIMIT 1;
    IF p.last_effective_at IS DISTINCT FROM v_last_effective
       OR p.last_event_sequence IS DISTINCT FROM v_last_sequence THEN
        RAISE EXCEPTION 'Trust Projection watermark must cover the full canonical event stream by commit';
    END IF;
    IF p.recomputed_at IS NULL OR p.recomputed_at < NEW.occurred_at THEN
        RAISE EXCEPTION 'Trust Projection must be recomputed after the inserted Trust event before commit';
    END IF;
    RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_trust_event_projection_current ON trust.trust_event;
CREATE CONSTRAINT TRIGGER tr_trust_event_projection_current
AFTER INSERT ON trust.trust_event
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION trust.assert_trust_event_projection_current();

-- T18-04. Ban Qualification must be the same User and exact Trust replay position
-- as its unique triggering Trust event.
CREATE OR REPLACE FUNCTION trust.guard_ban_qualification()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE e trust.trust_event%ROWTYPE;
BEGIN
    IF TG_OP = 'UPDATE' AND (
        NEW.id IS DISTINCT FROM OLD.id
        OR NEW.user_id IS DISTINCT FROM OLD.user_id
        OR NEW.triggering_event_id IS DISTINCT FROM OLD.triggering_event_id
    ) THEN
        RAISE EXCEPTION 'Ban Qualification identity is immutable';
    END IF;

    IF NEW.penalty_stage < 0 THEN
        RAISE EXCEPTION 'Ban Qualification penalty_stage cannot be negative';
    END IF;

    SELECT * INTO e FROM trust.trust_event WHERE id = NEW.triggering_event_id;
    IF NOT FOUND
       OR e.subject_user_id IS DISTINCT FROM NEW.user_id
       OR e.effective_at IS DISTINCT FROM NEW.qualification_at THEN
        RAISE EXCEPTION 'Ban Qualification must match the triggering Trust event User and effective position';
    END IF;
    RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_ban_qualification_guard ON trust.ban_qualification;
CREATE TRIGGER tr_ban_qualification_guard
BEFORE INSERT OR UPDATE ON trust.ban_qualification
FOR EACH ROW EXECUTE FUNCTION trust.guard_ban_qualification();

-- T18-05. Ban Instance lifecycle/identity and User serialization.
CREATE OR REPLACE FUNCTION trust.guard_ban_instance()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE q trust.ban_qualification%ROWTYPE;
BEGIN
    PERFORM 1 FROM iam.user_commitment_guard g WHERE g.user_id = NEW.user_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ban Instance requires the subject User commitment guard';
    END IF;

    SELECT * INTO q FROM trust.ban_qualification WHERE id = NEW.qualification_id;
    IF NOT FOUND OR q.user_id IS DISTINCT FROM NEW.user_id THEN
        RAISE EXCEPTION 'Ban Instance qualification must belong to the same User';
    END IF;

    IF NEW.penalty_stage < 0 OR NEW.duration <= interval '0' OR NEW.ends_at <= NEW.activated_at
       OR NEW.ends_at IS DISTINCT FROM NEW.activated_at + NEW.duration THEN
        RAISE EXCEPTION 'Ban Instance stage/duration/time arithmetic is invalid';
    END IF;
    IF NEW.activated_at < q.qualification_at THEN
        RAISE EXCEPTION 'Operational Ban activation may not predate its historical qualification';
    END IF;

    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'ACTIVE' THEN
            RAISE EXCEPTION 'A Ban Instance is created ACTIVE; expiry/lift/correction are later transitions';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.user_id IS DISTINCT FROM OLD.user_id
       OR NEW.qualification_id IS DISTINCT FROM OLD.qualification_id
       OR NEW.activated_at IS DISTINCT FROM OLD.activated_at
       OR NEW.activation_reason IS DISTINCT FROM OLD.activation_reason THEN
        RAISE EXCEPTION 'Ban Instance identity/activation facts are immutable';
    END IF;
    IF OLD.cascade_executed_at IS NOT NULL
       AND NEW.cascade_executed_at IS DISTINCT FROM OLD.cascade_executed_at THEN
        RAISE EXCEPTION 'Ban cascade_executed_at is immutable once recorded';
    END IF;
    IF OLD.status <> 'ACTIVE' THEN
        IF NEW IS DISTINCT FROM OLD THEN
            RAISE EXCEPTION 'Terminal Ban Instance is immutable';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.penalty_stage < OLD.penalty_stage THEN
        RAISE EXCEPTION 'Ban penalty stage may not move backwards';
    END IF;

    IF NEW.status = 'ACTIVE' THEN
        IF NEW.penalty_stage > OLD.penalty_stage THEN
            IF NEW.ends_at < OLD.ends_at THEN
                RAISE EXCEPTION 'Ban extension may not shorten the current Ban';
            END IF;
            IF NEW.cascade_executed_at IS DISTINCT FROM OLD.cascade_executed_at THEN
                RAISE EXCEPTION 'Ban extension must not repeat or rewrite the original cancellation cascade';
            END IF;
        ELSIF NEW.ends_at > OLD.ends_at THEN
            RAISE EXCEPTION 'Ban may extend only when a new penalty qualification advances the stage';
        END IF;
    ELSIF NEW.status = 'EXPIRED' THEN
        IF NEW.penalty_stage IS DISTINCT FROM OLD.penalty_stage
           OR NEW.ends_at IS DISTINCT FROM OLD.ends_at
           OR NEW.duration IS DISTINCT FROM OLD.duration THEN
            RAISE EXCEPTION 'Natural Ban expiry may not rewrite stage or planned end';
        END IF;
    ELSIF NEW.status IN ('LIFTED','CORRECTED') THEN
        IF NEW.penalty_stage IS DISTINCT FROM OLD.penalty_stage OR NEW.ends_at > OLD.ends_at THEN
            RAISE EXCEPTION 'Lift/correction may end a Ban early but may not advance stage or extend it';
        END IF;
    ELSE
        RAISE EXCEPTION 'Invalid Ban Instance transition';
    END IF;
    RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_ban_instance_guard ON trust.ban_instance;
CREATE TRIGGER tr_ban_instance_guard
BEFORE INSERT OR UPDATE ON trust.ban_instance
FOR EACH ROW EXECUTE FUNCTION trust.guard_ban_instance();

CREATE OR REPLACE FUNCTION trust.assert_ban_lifecycle_audit()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE q trust.ban_qualification%ROWTYPE;
BEGIN
    IF OLD.status <> 'ACTIVE' THEN RETURN NULL; END IF;

    IF NEW.status = 'ACTIVE' AND NEW.penalty_stage > OLD.penalty_stage THEN
        IF NOT EXISTS (
            SELECT 1
              FROM audit.audit_event a
              JOIN trust.ban_qualification nq
                ON nq.id = (a.payload->>'triggeringQualificationId')::uuid
             WHERE a.action = 'BAN_EXTENDED'
               AND a.subject_id = NEW.user_id
               AND a.payload->>'banInstanceId' = NEW.id::text
               AND a.payload->>'triggeringEventId' = nq.triggering_event_id::text
               AND nq.user_id = NEW.user_id
               AND (a.payload->>'previousPenaltyStage')::smallint = OLD.penalty_stage
               AND (a.payload->>'newPenaltyStage')::smallint = NEW.penalty_stage
               AND (a.payload->>'oldEndsAt')::timestamptz = OLD.ends_at
               AND (a.payload->>'newEndsAt')::timestamptz = NEW.ends_at
        ) THEN
            RAISE EXCEPTION 'Ban extension requires BAN_EXTENDED audit with triggering qualification/event and old/new stage/end';
        END IF;
    ELSIF NEW.status = 'ACTIVE' AND NEW.ends_at < OLD.ends_at THEN
        IF NOT EXISTS (
            SELECT 1 FROM audit.audit_event a
             WHERE a.actor_type = 'ADMIN'
               AND a.subject_id = NEW.user_id
               AND a.action = 'BAN_SHORTENED'
               AND a.payload->>'banInstanceId' = NEW.id::text
               AND (a.payload->>'newEndsAt')::timestamptz = NEW.ends_at
               AND NULLIF(BTRIM(a.reason),'') IS NOT NULL
        ) THEN
            RAISE EXCEPTION 'Admin Ban shortening requires BAN_SHORTENED audit with reason and newEndsAt';
        END IF;
    ELSIF NEW.status = 'LIFTED' THEN
        IF NOT EXISTS (
            SELECT 1 FROM audit.audit_event a
             WHERE a.actor_type = 'ADMIN'
               AND a.subject_id = NEW.user_id
               AND a.action = 'BAN_LIFTED'
               AND a.occurred_at = NEW.ends_at
               AND a.payload->>'banInstanceId' = NEW.id::text
               AND NULLIF(BTRIM(a.reason),'') IS NOT NULL
        ) THEN
            RAISE EXCEPTION 'Admin Ban lift requires BAN_LIFTED audit with reason at the operational end time';
        END IF;
    ELSIF NEW.status = 'CORRECTED' THEN
        IF NOT EXISTS (
            SELECT 1 FROM audit.audit_event a
             WHERE a.subject_id = NEW.user_id
               AND a.action = 'BAN_CORRECTED'
               AND a.occurred_at = NEW.ends_at
               AND a.payload->>'banInstanceId' = NEW.id::text
               AND NULLIF(BTRIM(a.reason),'') IS NOT NULL
        ) THEN
            RAISE EXCEPTION 'Corrected Ban requires BAN_CORRECTED audit with reason at the operational end time';
        END IF;
    END IF;
    RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_ban_lifecycle_audit ON trust.ban_instance;
CREATE CONSTRAINT TRIGGER tr_ban_lifecycle_audit
AFTER UPDATE ON trust.ban_instance
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION trust.assert_ban_lifecycle_audit();

-- T18-06. A live Ban must finish its current Booking cascade before commit, and
-- the once-only proof is physically tied to the Ban Instance source id.
CREATE OR REPLACE FUNCTION trust.assert_ban_booking_cascade()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    b trust.ban_instance%ROWTYPE;
    c trust.cascade_execution%ROWTYPE;
BEGIN
    SELECT * INTO b FROM trust.ban_instance WHERE id = NEW.id;
    IF NOT FOUND OR b.status <> 'ACTIVE' THEN
        RETURN NULL;
    END IF;

    IF EXISTS (
        SELECT 1
          FROM booking.booking x
         WHERE x.source = 'ONLINE'
           AND x.customer_id = b.user_id
           AND (
               x.status IN ('PENDING','AWAITING_CUSTOMER_CONFIRMATION')
               OR (x.status = 'CONFIRMED' AND x.start_at > b.activated_at)
           )
    ) THEN
        RAISE EXCEPTION 'Active Ban must cancel all current future Online Booking commitments before commit';
    END IF;

    SELECT * INTO c
      FROM trust.cascade_execution ce
     WHERE ce.cascade_type = 'BAN' AND ce.source_id = b.id;
    IF NOT FOUND
       OR c.subject_user_id IS DISTINCT FROM b.user_id
       OR b.cascade_executed_at IS NULL
       OR c.executed_at IS DISTINCT FROM b.cascade_executed_at THEN
        RAISE EXCEPTION 'Active Ban requires one matching BAN cascade_execution and cascade_executed_at';
    END IF;
    RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_ban_booking_cascade_complete ON trust.ban_instance;
CREATE CONSTRAINT TRIGGER tr_ban_booking_cascade_complete
AFTER INSERT OR UPDATE OF status, ends_at, penalty_stage, cascade_executed_at ON trust.ban_instance
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION trust.assert_ban_booking_cascade();

-- T18-07. Booking commitment strengthening is physically serialized against Ban
-- activation and fails closed while an effective operational Ban exists.
CREATE OR REPLACE FUNCTION trust.guard_booking_ban_eligibility()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE v_now timestamptz;
BEGIN
    IF NEW.source <> 'ONLINE' OR NEW.customer_id IS NULL THEN
        RETURN NEW;
    END IF;
    IF TG_OP = 'UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status THEN
        RETURN NEW;
    END IF;
    IF NEW.status NOT IN ('PENDING','AWAITING_CUSTOMER_CONFIRMATION','CONFIRMED','ACTIVE') THEN
        RETURN NEW;
    END IF;

    PERFORM 1 FROM iam.user_commitment_guard g WHERE g.user_id = NEW.customer_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Online Booking commitment requires the Customer commitment guard';
    END IF;
    v_now := clock_timestamp();
    IF EXISTS (
        SELECT 1 FROM trust.ban_instance b
         WHERE b.user_id = NEW.customer_id
           AND b.status = 'ACTIVE'
           AND b.activated_at <= v_now
           AND b.ends_at > v_now
    ) THEN
        RAISE EXCEPTION 'Banned User may not create or strengthen an Online Booking commitment';
    END IF;
    RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_05_booking_ban_eligibility ON booking.booking;
CREATE TRIGGER tr_05_booking_ban_eligibility
BEFORE INSERT OR UPDATE OF status ON booking.booking
FOR EACH ROW EXECUTE FUNCTION trust.guard_booking_ban_eligibility();

-- T18-08. Verified Player operational history: complete rows, continuous status
-- chain, protected Admin states, technical cause for normal first qualification,
-- and immutable transition identity/facts.
CREATE OR REPLACE FUNCTION trust.guard_verified_player_transition()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE prev trust.verified_player_transition%ROWTYPE;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF NEW.id IS DISTINCT FROM OLD.id
           OR NEW.user_id IS DISTINCT FROM OLD.user_id
           OR NEW.transition_id IS DISTINCT FROM OLD.transition_id
           OR NEW.from_status IS DISTINCT FROM OLD.from_status
           OR NEW.to_status IS DISTINCT FROM OLD.to_status
           OR NEW.occurred_at IS DISTINCT FROM OLD.occurred_at
           OR NEW.cause IS DISTINCT FROM OLD.cause
           OR NEW.admin_id IS DISTINCT FROM OLD.admin_id THEN
            RAISE EXCEPTION 'Verified Player transition identity/facts are immutable';
        END IF;
        IF OLD.cascade_executed_at IS NOT NULL
           AND NEW.cascade_executed_at IS DISTINCT FROM OLD.cascade_executed_at THEN
            RAISE EXCEPTION 'Verified Player cascade_executed_at is immutable once recorded';
        END IF;
        RETURN NEW;
    END IF;

    PERFORM 1 FROM iam.user_commitment_guard g WHERE g.user_id = NEW.user_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Verified Player transition requires the User commitment guard';
    END IF;

    IF NEW.from_status = NEW.to_status THEN
        RAISE EXCEPTION 'Verified Player transition must change operational status';
    END IF;
    IF NEW.cause = 'ADMIN' AND NEW.admin_id IS NULL THEN
        RAISE EXCEPTION 'Admin Verified Player transition requires admin_id';
    ELSIF NEW.cause <> 'ADMIN' AND NEW.admin_id IS NOT NULL THEN
        RAISE EXCEPTION 'Non-Admin Verified Player transition may not carry admin_id';
    END IF;

    SELECT * INTO prev
      FROM trust.verified_player_transition v
     WHERE v.user_id = NEW.user_id
     ORDER BY v.occurred_at DESC, v.id DESC
     LIMIT 1;
    IF FOUND THEN
        IF prev.to_status IS DISTINCT FROM NEW.from_status THEN
            RAISE EXCEPTION 'Verified Player transition chain must continue from the latest operational status';
        END IF;
        IF NEW.occurred_at <= prev.occurred_at THEN
            RAISE EXCEPTION 'Verified Player transition occurred_at must advance strictly for deterministic operational history';
        END IF;
    ELSIF NEW.from_status <> 'NOT_VERIFIED' THEN
        RAISE EXCEPTION 'First Verified Player transition must start from NOT_VERIFIED';
    END IF;

    IF NEW.cause = 'TRUST_QUALIFICATION' THEN
        IF NEW.from_status <> 'NOT_VERIFIED' OR NEW.to_status <> 'VERIFIED' THEN
            RAISE EXCEPTION 'TRUST_QUALIFICATION is only the normal first NOT_VERIFIED to VERIFIED activation';
        END IF;
    ELSIF NEW.cause = 'TRUST_CORRECTION' THEN
        IF NOT (
            (NEW.from_status = 'NOT_VERIFIED' AND NEW.to_status = 'VERIFIED')
            OR (NEW.from_status = 'VERIFIED' AND NEW.to_status = 'REVOKED')
            OR (NEW.from_status = 'REVOKED' AND NEW.to_status = 'VERIFIED')
        ) THEN
            RAISE EXCEPTION 'Invalid TRUST_CORRECTION Verified Player transition';
        END IF;
        IF NEW.from_status = 'REVOKED' AND NEW.to_status = 'VERIFIED'
           AND (NOT FOUND OR prev.cause <> 'TRUST_CORRECTION' OR prev.to_status <> 'REVOKED') THEN
            RAISE EXCEPTION 'Automatic Verified Player regain is allowed only after TRUST_CORRECTION revocation';
        END IF;
    ELSIF NEW.cause = 'ADMIN' THEN
        IF NOT (
            (NEW.from_status = 'VERIFIED' AND NEW.to_status IN ('SUSPENDED','REVOKED'))
            OR (NEW.from_status = 'SUSPENDED' AND NEW.to_status IN ('VERIFIED','NOT_VERIFIED'))
            OR (NEW.from_status = 'REVOKED' AND NEW.to_status IN ('VERIFIED','NOT_VERIFIED'))
        ) THEN
            RAISE EXCEPTION 'Invalid ADMIN Verified Player transition';
        END IF;
    END IF;

    IF NEW.to_status <> 'REVOKED' AND NEW.cascade_executed_at IS NOT NULL THEN
        RAISE EXCEPTION 'Only REVOKED transition may record a Tournament cancellation cascade';
    END IF;
    RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_verified_player_transition_guard ON trust.verified_player_transition;
CREATE TRIGGER tr_verified_player_transition_guard
BEFORE INSERT OR UPDATE ON trust.verified_player_transition
FOR EACH ROW EXECUTE FUNCTION trust.guard_verified_player_transition();

CREATE OR REPLACE FUNCTION trust.assert_admin_verified_player_transition()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_event_type text;
    v_correlation uuid;
    v_event_count integer;
BEGIN
    IF NEW.cause <> 'ADMIN' THEN RETURN NULL; END IF;
    v_event_type := CASE
        WHEN NEW.to_status = 'SUSPENDED' THEN 'VERIFIED_PLAYER_SUSPENDED'
        WHEN NEW.to_status = 'REVOKED' THEN 'VERIFIED_PLAYER_REVOKED'
        ELSE 'VERIFIED_PLAYER_RESTORED'
    END;

    SELECT COUNT(*) INTO v_event_count
      FROM trust.trust_event e
     WHERE e.subject_user_id = NEW.user_id
       AND e.event_type = v_event_type
       AND e.occurred_at = NEW.occurred_at
       AND e.effective_at = NEW.occurred_at
       AND (e.payload->>'adminId')::uuid = NEW.admin_id;
    IF v_event_count <> 1 THEN
        RAISE EXCEPTION 'Admin Verified Player transition requires exactly one canonical Trust input event';
    END IF;
    SELECT (e.payload->>'correlationId')::uuid INTO STRICT v_correlation
      FROM trust.trust_event e
     WHERE e.subject_user_id = NEW.user_id
       AND e.event_type = v_event_type
       AND e.occurred_at = NEW.occurred_at
       AND e.effective_at = NEW.occurred_at
       AND (e.payload->>'adminId')::uuid = NEW.admin_id;
    IF NOT EXISTS (
        SELECT 1 FROM audit.audit_event a
         WHERE a.actor_type = 'ADMIN'
           AND a.actor_id = NEW.admin_id
           AND a.subject_id = NEW.user_id
           AND a.occurred_at = NEW.occurred_at
           AND a.correlation_id = v_correlation
           AND NULLIF(BTRIM(a.reason),'') IS NOT NULL
    ) THEN
        RAISE EXCEPTION 'Admin Verified Player transition requires matching Admin audit identity/reason/timestamp';
    END IF;
    RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_admin_verified_player_transition ON trust.verified_player_transition;
CREATE CONSTRAINT TRIGGER tr_admin_verified_player_transition
AFTER INSERT ON trust.verified_player_transition
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION trust.assert_admin_verified_player_transition();

CREATE OR REPLACE FUNCTION trust.assert_verified_player_transition_qualification()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE p trust.trust_projection%ROWTYPE;
BEGIN
    SELECT * INTO p FROM trust.trust_projection WHERE user_id = NEW.user_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Verified Player transition requires a Trust Projection for the same User by commit';
    END IF;

    IF NEW.cause IN ('TRUST_QUALIFICATION','TRUST_CORRECTION') THEN
        IF NEW.to_status = 'VERIFIED' AND p.vp_qualification IS DISTINCT FROM 'QUALIFIED' THEN
            RAISE EXCEPTION 'Automatic VERIFIED transition requires QUALIFIED corrected Trust history';
        ELSIF NEW.to_status = 'REVOKED' AND p.vp_qualification IS DISTINCT FROM 'NOT_QUALIFIED' THEN
            RAISE EXCEPTION 'TRUST_CORRECTION revocation requires NOT_QUALIFIED corrected Trust history';
        END IF;
    ELSIF NEW.cause = 'ADMIN' AND NEW.to_status IN ('VERIFIED','NOT_VERIFIED') THEN
        IF (NEW.to_status = 'VERIFIED') IS DISTINCT FROM (p.vp_qualification = 'QUALIFIED') THEN
            RAISE EXCEPTION 'Admin Restore must return VERIFIED iff the User is currently QUALIFIED';
        END IF;
    END IF;
    RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_verified_player_transition_qualification ON trust.verified_player_transition;
CREATE CONSTRAINT TRIGGER tr_verified_player_transition_qualification
AFTER INSERT ON trust.verified_player_transition
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION trust.assert_verified_player_transition_qualification();

-- T18-09. Cascade proofs are immutable and canonical for Ban/Verified Player sources.
CREATE OR REPLACE FUNCTION trust.guard_cascade_execution()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    b trust.ban_instance%ROWTYPE;
    v trust.verified_player_transition%ROWTYPE;
    v_expected_key text;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'cascade_execution is append-only';
    END IF;

    IF NEW.cascade_type = 'BAN' THEN
        IF NEW.source_id IS NULL OR NEW.subject_user_id IS NULL THEN
            RAISE EXCEPTION 'BAN cascade_execution requires source_id and subject_user_id';
        END IF;
        SELECT * INTO b FROM trust.ban_instance WHERE id = NEW.source_id;
        IF NOT FOUND OR b.user_id IS DISTINCT FROM NEW.subject_user_id OR b.status <> 'ACTIVE' THEN
            RAISE EXCEPTION 'BAN cascade_execution source must be the same User ACTIVE Ban Instance';
        END IF;
        v_expected_key := 'BAN_CASCADE:' || b.id::text;
        IF NEW.cascade_key IS DISTINCT FROM v_expected_key THEN
            RAISE EXCEPTION 'BAN cascade_execution key must equal %', v_expected_key;
        END IF;
    ELSIF NEW.cascade_type = 'VERIFIED_PLAYER' THEN
        IF NEW.source_id IS NULL OR NEW.subject_user_id IS NULL THEN
            RAISE EXCEPTION 'VERIFIED_PLAYER cascade_execution requires source_id and subject_user_id';
        END IF;
        SELECT * INTO v FROM trust.verified_player_transition WHERE id = NEW.source_id;
        IF NOT FOUND OR v.user_id IS DISTINCT FROM NEW.subject_user_id
           OR v.from_status <> 'VERIFIED' OR v.to_status <> 'REVOKED' THEN
            RAISE EXCEPTION 'VERIFIED_PLAYER cascade source must be the same User VERIFIED-to-REVOKED transition';
        END IF;
        v_expected_key := 'VP_TOURNAMENT_CASCADE:' || v.transition_id::text;
        IF NEW.cascade_key IS DISTINCT FROM v_expected_key THEN
            RAISE EXCEPTION 'VERIFIED_PLAYER cascade_execution key must equal %', v_expected_key;
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_cascade_execution_guard ON trust.cascade_execution;
CREATE TRIGGER tr_cascade_execution_guard
BEFORE INSERT OR UPDATE OR DELETE ON trust.cascade_execution
FOR EACH ROW EXECUTE FUNCTION trust.guard_cascade_execution();

-- T18-10. Rebuildable projection integrity: composite watermark and same-User pointers.
CREATE OR REPLACE FUNCTION trust.guard_trust_projection()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE b trust.ban_instance%ROWTYPE;
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.user_id IS DISTINCT FROM OLD.user_id THEN
        RAISE EXCEPTION 'Trust Projection user_id is immutable';
    END IF;
    IF (NEW.last_effective_at IS NULL) <> (NEW.last_event_sequence IS NULL) THEN
        RAISE EXCEPTION 'Trust Projection composite watermark must be both NULL or both populated';
    END IF;
    IF NEW.last_event_sequence IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM trust.trust_event e
         WHERE e.subject_user_id = NEW.user_id
           AND e.effective_at = NEW.last_effective_at
           AND e.event_sequence = NEW.last_event_sequence
    ) THEN
        RAISE EXCEPTION 'Trust Projection watermark must reference an exact Trust event position for the same User';
    END IF;
    IF NEW.active_ban_instance_id IS NOT NULL THEN
        SELECT * INTO b FROM trust.ban_instance WHERE id = NEW.active_ban_instance_id;
        IF NOT FOUND OR b.user_id IS DISTINCT FROM NEW.user_id OR b.status <> 'ACTIVE' THEN
            RAISE EXCEPTION 'Trust Projection active Ban pointer must reference an ACTIVE Ban of the same User';
        END IF;
        IF NEW.recomputed_at IS NULL OR NOT (b.activated_at <= NEW.recomputed_at AND b.ends_at > NEW.recomputed_at) THEN
            RAISE EXCEPTION 'Trust Projection active Ban pointer must be operationally in force at recomputed_at';
        END IF;
    ELSIF NEW.recomputed_at IS NOT NULL AND EXISTS (
        SELECT 1 FROM trust.ban_instance x
         WHERE x.user_id=NEW.user_id AND x.status='ACTIVE'
           AND x.activated_at <= NEW.recomputed_at AND x.ends_at > NEW.recomputed_at
    ) THEN
        RAISE EXCEPTION 'Trust Projection must point to the effective ACTIVE Ban at recomputed_at';
    END IF;
    RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_trust_projection_guard ON trust.trust_projection;
CREATE TRIGGER tr_trust_projection_guard
BEFORE INSERT OR UPDATE ON trust.trust_projection
FOR EACH ROW EXECUTE FUNCTION trust.guard_trust_projection();

CREATE OR REPLACE FUNCTION trust.assert_projection_operational_status()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    p trust.trust_projection%ROWTYPE;
    v trust.verified_player_transition%ROWTYPE;
BEGIN
    SELECT * INTO p FROM trust.trust_projection WHERE user_id = NEW.user_id;
    IF NOT FOUND THEN RETURN NULL; END IF;
    SELECT * INTO v
      FROM trust.verified_player_transition x
     WHERE x.user_id = p.user_id
     ORDER BY x.occurred_at DESC, x.id DESC
     LIMIT 1;
    IF FOUND THEN
        IF p.vp_operational_status IS DISTINCT FROM v.to_status THEN
            RAISE EXCEPTION 'Trust Projection VP operational status must equal the latest Verified Player transition';
        END IF;
    ELSE
        IF p.vp_operational_status NOT IN ('NOT_VERIFIED') OR p.vp_qualification = 'QUALIFIED' THEN
            RAISE EXCEPTION 'Trust Projection without transition history must remain unqualified/NOT_VERIFIED';
        END IF;
    END IF;
    IF p.vp_qualification = 'NOT_QUALIFIED' AND p.vp_operational_status = 'VERIFIED' THEN
        RAISE EXCEPTION 'NOT_QUALIFIED Trust Projection may not remain operational VERIFIED';
    END IF;
    IF p.vp_qualification = 'QUALIFIED' AND p.vp_operational_status IN ('NOT_VERIFIED') THEN
        RAISE EXCEPTION 'QUALIFIED Trust Projection must reconcile the operational Verified Player state';
    END IF;
    RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_projection_status_from_transition ON trust.verified_player_transition;
CREATE CONSTRAINT TRIGGER tr_projection_status_from_transition
AFTER INSERT OR UPDATE ON trust.verified_player_transition
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION trust.assert_projection_operational_status();
DROP TRIGGER IF EXISTS tr_projection_status_self ON trust.trust_projection;
CREATE CONSTRAINT TRIGGER tr_projection_status_self
AFTER INSERT OR UPDATE OF vp_qualification,vp_operational_status ON trust.trust_projection
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION trust.assert_projection_operational_status();

-- T18-11. Checkpoints must be real composite replay positions with versioned object snapshots.
CREATE OR REPLACE FUNCTION trust.guard_trust_checkpoint()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    IF jsonb_typeof(NEW.state_snapshot) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'Trust checkpoint state_snapshot must be a JSON object';
    END IF;
    IF NEW.snapshot_version < 1 THEN
        RAISE EXCEPTION 'Trust checkpoint snapshot_version must be positive';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM trust.trust_event e
         WHERE e.subject_user_id = NEW.user_id
           AND e.effective_at = NEW.checkpoint_effective_at
           AND e.event_sequence = NEW.checkpoint_event_sequence
    ) THEN
        RAISE EXCEPTION 'Trust checkpoint must reference an exact Trust event position for the same User';
    END IF;
    RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_trust_checkpoint_guard ON trust.trust_projection_checkpoint;
CREATE TRIGGER tr_trust_checkpoint_guard
BEFORE INSERT OR UPDATE ON trust.trust_projection_checkpoint
FOR EACH ROW EXECUTE FUNCTION trust.guard_trust_checkpoint();


-- ============================================================================
-- E7GZ PS v1.1.19 TRUST ACCEPTANCE CORRECTIONS
-- Closes independent findings AR18-01 through AR18-08.
-- Tournament v1.1.17 source behavior is retained unchanged.
-- PostgreSQL 16+.
-- ============================================================================

-- AR18-02. ADMIN_TRUST_ADJUSTMENT is a versioned, atomic ABSOLUTE override of
-- the two mutable penalty-fold values. It is never a delta and never creates,
-- extends, lifts or corrects an operational Ban by itself.
-- Canonical v1 payload (exact keys):
-- {"schemaVersion":1,"counterAfter":n,"penaltyStageAfter":s,
--  "adminId":"uuid","correlationId":"uuid"}
-- Bounds: stage 0..3, counter >= 0 and counter below the resulting stage's
-- threshold. Any operational Ban remediation uses the dedicated audited path.

CREATE OR REPLACE FUNCTION trust.penalty_threshold(p_stage smallint)
RETURNS smallint
LANGUAGE sql
IMMUTABLE
STRICT
PARALLEL SAFE
AS $function$
    SELECT CASE WHEN p_stage = 0 THEN 3 WHEN p_stage IN (1,2) THEN 2 ELSE 3 END::smallint
$function$;

CREATE OR REPLACE FUNCTION trust.penalty_duration(p_stage smallint)
RETURNS interval
LANGUAGE plpgsql
IMMUTABLE
STRICT
PARALLEL SAFE
AS $function$
BEGIN
    RETURN CASE p_stage
        WHEN 1 THEN interval '7 days'
        WHEN 2 THEN interval '1 month'
        WHEN 3 THEN interval '2 months'
        ELSE NULL
    END;
END;
$function$;

-- One canonical effect stream. Correction chains are collapsed to their single
-- non-superseded leaf; the original contributes only when no correction/reversal
-- exists. Protection is neutralised once an authoritative attendance outcome is
-- present. The optional composite boundary provides the same as-of semantics.
CREATE OR REPLACE FUNCTION trust.canonical_trust_effects(
    p_user_id uuid,
    p_as_of_effective timestamptz DEFAULT NULL,
    p_as_of_sequence bigint DEFAULT NULL
)
RETURNS TABLE(
    effect_event_id uuid,
    effective_at timestamptz,
    event_sequence bigint,
    effect_type text,
    effect_payload jsonb
)
LANGUAGE sql
STABLE
AS $function$
WITH bounded AS (
    SELECT e.*
      FROM trust.trust_event e
     WHERE e.subject_user_id = p_user_id
       AND (
            p_as_of_effective IS NULL
            OR e.effective_at < p_as_of_effective
            OR (e.effective_at = p_as_of_effective AND e.event_sequence <= p_as_of_sequence)
       )
),
originals AS (
    SELECT e.*
      FROM bounded e
     WHERE e.event_type IN (
        'BOOKING_ATTENDED','BOOKING_ATTENDANCE_UNCONFIRMED',
        'BOOKING_ATTENDED_INTERRUPTED','BOOKING_NO_SHOW'
     )
),
leaf_corrections AS (
    SELECT DISTINCT ON (c.booking_id) c.*
      FROM bounded c
     WHERE c.event_type = 'ATTENDANCE_CORRECTED'
       AND NOT EXISTS (
            SELECT 1 FROM bounded s
             WHERE s.event_type = 'ATTENDANCE_CORRECTED'
               AND s.superseded_correction_event_id = c.id
       )
     ORDER BY c.booking_id, c.event_sequence DESC
),
reversals AS (
    SELECT DISTINCT ON (r.booking_id) r.*
      FROM bounded r
     WHERE r.event_type = 'NO_SHOW_REVERSED'
     ORDER BY r.booking_id, r.event_sequence DESC
),
resolved_outcomes AS (
    SELECT
        COALESCE(c.id, r.id, o.id) AS effect_event_id,
        COALESCE(c.effective_at, r.effective_at, o.effective_at) AS effective_at,
        COALESCE(c.event_sequence, r.event_sequence, o.event_sequence) AS event_sequence,
        CASE
            WHEN c.id IS NOT NULL THEN CASE c.corrected_outcome
                WHEN 'ATTENDED' THEN 'BOOKING_ATTENDED'
                WHEN 'ATTENDED_INTERRUPTED' THEN 'BOOKING_ATTENDED_INTERRUPTED'
                WHEN 'ATTENDANCE_UNCONFIRMED' THEN 'BOOKING_ATTENDANCE_UNCONFIRMED'
                WHEN 'ABSENT_NO_SHOW' THEN 'BOOKING_NO_SHOW'
            END
            WHEN r.id IS NOT NULL THEN 'BOOKING_ATTENDANCE_UNCONFIRMED'
            ELSE o.event_type
        END AS effect_type,
        COALESCE(c.payload, r.payload, o.payload) AS effect_payload,
        o.booking_id
      FROM originals o
      LEFT JOIN leaf_corrections c
        ON c.booking_id = o.booking_id AND c.original_outcome_event_id = o.id
      LEFT JOIN reversals r
        ON r.booking_id = o.booking_id AND r.original_outcome_event_id = o.id
       AND c.id IS NULL
),
protection AS (
    SELECT p.id AS effect_event_id, p.effective_at, p.event_sequence,
           p.event_type::text AS effect_type, p.payload AS effect_payload
      FROM bounded p
     WHERE p.event_type = 'BOOKING_ACCOUNT_DISABLE_ATTENDANCE_PROTECTION'
       AND NOT EXISTS (
            SELECT 1 FROM resolved_outcomes ro WHERE ro.booking_id = p.booking_id
       )
),
admin_adjustments AS (
    SELECT a.id AS effect_event_id, a.effective_at, a.event_sequence,
           a.event_type::text AS effect_type, a.payload AS effect_payload
      FROM bounded a
     WHERE a.event_type = 'ADMIN_TRUST_ADJUSTMENT'
),
admin_vp_events AS (
    SELECT v.id AS effect_event_id, v.effective_at, v.event_sequence,
           v.event_type::text AS effect_type, v.payload AS effect_payload
      FROM bounded v
     WHERE v.event_type IN (
        'VERIFIED_PLAYER_SUSPENDED','VERIFIED_PLAYER_REVOKED','VERIFIED_PLAYER_RESTORED'
     )
)
SELECT ro.effect_event_id, ro.effective_at, ro.event_sequence,
       ro.effect_type, ro.effect_payload
  FROM resolved_outcomes ro
UNION ALL
SELECT p.effect_event_id, p.effective_at, p.event_sequence,
       p.effect_type, p.effect_payload
  FROM protection p
UNION ALL
SELECT a.effect_event_id, a.effective_at, a.event_sequence,
       a.effect_type, a.effect_payload
  FROM admin_adjustments a
UNION ALL
SELECT v.effect_event_id, v.effective_at, v.event_sequence,
       v.effect_type, v.effect_payload
  FROM admin_vp_events v
ORDER BY 2,3
$function$;

-- The sole fold implementation used by live-projection validation, rebuild,
-- qualification validation and as-of reads.
CREATE OR REPLACE FUNCTION trust.replay_timeline(
    p_user_id uuid,
    p_as_of_effective timestamptz DEFAULT NULL,
    p_as_of_sequence bigint DEFAULT NULL
)
RETURNS TABLE(
    effect_event_id uuid,
    effective_at timestamptz,
    event_sequence bigint,
    consecutive_no_shows integer,
    penalty_stage smallint,
    current_threshold smallint,
    completed_attended_count integer,
    vp_qualification text,
    qualification_stage smallint
)
LANGUAGE plpgsql
STABLE
AS $function$
DECLARE
    x record;
    v_counter integer := 0;
    v_stage smallint := 0;
    v_completed integer := 0;
    v_threshold smallint := 3;
    v_qualification smallint;
BEGIN
    FOR x IN
        SELECT ce.*
          FROM trust.canonical_trust_effects(
              p_user_id, p_as_of_effective, p_as_of_sequence
          ) ce
         ORDER BY ce.effective_at, ce.event_sequence
    LOOP
        v_qualification := NULL;

        IF x.effect_type = 'ADMIN_TRUST_ADJUSTMENT' THEN
            v_counter := (x.effect_payload->>'counterAfter')::integer;
            v_stage := (x.effect_payload->>'penaltyStageAfter')::smallint;
        ELSIF x.effect_type = 'BOOKING_ATTENDED' THEN
            v_counter := 0;
            v_completed := v_completed + 1;
        ELSIF x.effect_type IN (
            'BOOKING_ATTENDED_INTERRUPTED',
            'BOOKING_ACCOUNT_DISABLE_ATTENDANCE_PROTECTION'
        ) THEN
            v_counter := 0;
        ELSIF x.effect_type = 'BOOKING_NO_SHOW' THEN
            v_threshold := trust.penalty_threshold(v_stage);
            v_counter := v_counter + 1;
            IF v_counter = v_threshold THEN
                v_counter := 0;
                v_stage := LEAST(v_stage + 1, 3)::smallint;
                v_qualification := v_stage;
            END IF;
        END IF;

        v_threshold := trust.penalty_threshold(v_stage);
        effect_event_id := x.effect_event_id;
        effective_at := x.effective_at;
        event_sequence := x.event_sequence;
        consecutive_no_shows := v_counter;
        penalty_stage := v_stage;
        current_threshold := v_threshold;
        completed_attended_count := v_completed;
        vp_qualification := CASE WHEN v_completed >= 10 THEN 'QUALIFIED' ELSE 'NOT_QUALIFIED' END;
        qualification_stage := v_qualification;
        RETURN NEXT;
    END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION trust.replay_state(
    p_user_id uuid,
    p_as_of_effective timestamptz DEFAULT NULL,
    p_as_of_sequence bigint DEFAULT NULL
)
RETURNS TABLE(
    last_effective_at timestamptz,
    last_event_sequence bigint,
    consecutive_no_shows integer,
    penalty_stage smallint,
    current_threshold smallint,
    completed_attended_count integer,
    vp_qualification text
)
LANGUAGE plpgsql
STABLE
AS $function$
DECLARE r record;
BEGIN
    SELECT e.effective_at, e.event_sequence
      INTO last_effective_at, last_event_sequence
      FROM trust.trust_event e
     WHERE e.subject_user_id = p_user_id
       AND (
            p_as_of_effective IS NULL
            OR e.effective_at < p_as_of_effective
            OR (e.effective_at = p_as_of_effective AND e.event_sequence <= p_as_of_sequence)
       )
     ORDER BY e.effective_at DESC, e.event_sequence DESC
     LIMIT 1;

    SELECT t.* INTO r
      FROM trust.replay_timeline(p_user_id, p_as_of_effective, p_as_of_sequence) t
     ORDER BY t.effective_at DESC, t.event_sequence DESC
     LIMIT 1;

    IF NOT FOUND THEN
        consecutive_no_shows := 0;
        penalty_stage := 0;
        current_threshold := 3;
        completed_attended_count := 0;
        vp_qualification := 'NOT_QUALIFIED';
    ELSE
        consecutive_no_shows := r.consecutive_no_shows;
        penalty_stage := r.penalty_stage;
        current_threshold := r.current_threshold;
        completed_attended_count := r.completed_attended_count;
        vp_qualification := r.vp_qualification;
    END IF;
    RETURN NEXT;
END;
$function$;

-- Strengthen event preparation with the frozen v1 adjustment payload.
CREATE OR REPLACE FUNCTION trust.prepare_trust_event_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    b booking.booking%ROWTYPE;
    v_counter integer;
    v_stage smallint;
BEGIN
    PERFORM 1
      FROM iam.user_commitment_guard g
     WHERE g.user_id = NEW.subject_user_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Trust event requires the subject User commitment guard';
    END IF;

    NEW.event_sequence := nextval('trust.trust_event_sequence_seq'::regclass);
    NEW.payload := COALESCE(NEW.payload, '{}'::jsonb);
    IF jsonb_typeof(NEW.payload) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'Trust event payload must be a JSON object';
    END IF;
    IF NEW.occurred_at < NEW.effective_at THEN
        RAISE EXCEPTION 'Trust event occurred_at cannot predate effective_at';
    END IF;

    IF NEW.event_type IN (
        'BOOKING_ATTENDED','BOOKING_ATTENDANCE_UNCONFIRMED',
        'BOOKING_ATTENDED_INTERRUPTED','BOOKING_NO_SHOW'
    ) THEN
        SELECT * INTO b FROM booking.booking WHERE id = NEW.booking_id;
        IF NOT FOUND OR b.source <> 'ONLINE' OR b.customer_id IS NULL THEN
            RAISE EXCEPTION '% requires an Online customer Booking', NEW.event_type;
        END IF;
        IF NEW.subject_user_id IS DISTINCT FROM b.customer_id THEN
            RAISE EXCEPTION '% subject_user_id must equal Booking customer_id', NEW.event_type;
        END IF;
        IF NEW.effective_at IS DISTINCT FROM b.start_at THEN
            RAISE EXCEPTION '% effective_at must equal booking.start_at', NEW.event_type;
        END IF;
    ELSIF NEW.event_type IN (
        'ADMIN_TRUST_ADJUSTMENT','VERIFIED_PLAYER_SUSPENDED',
        'VERIFIED_PLAYER_REVOKED','VERIFIED_PLAYER_RESTORED'
    ) THEN
        IF NEW.effective_at IS DISTINCT FROM NEW.occurred_at THEN
            RAISE EXCEPTION '% effective_at must equal occurred_at', NEW.event_type;
        END IF;
        IF NOT (NEW.payload ? 'adminId') OR NOT (NEW.payload ? 'correlationId') THEN
            RAISE EXCEPTION '% payload requires adminId and correlationId', NEW.event_type;
        END IF;
        BEGIN
            PERFORM (NEW.payload->>'adminId')::uuid;
            PERFORM (NEW.payload->>'correlationId')::uuid;
        EXCEPTION WHEN invalid_text_representation THEN
            RAISE EXCEPTION '% payload adminId/correlationId must be UUID values', NEW.event_type;
        END;
    END IF;

    IF NEW.event_type = 'ADMIN_TRUST_ADJUSTMENT' THEN
        IF jsonb_object_length(NEW.payload) <> 5
           OR NOT (NEW.payload ?& ARRAY[
               'schemaVersion','counterAfter','penaltyStageAfter','adminId','correlationId'
           ])
           OR jsonb_typeof(NEW.payload->'schemaVersion') IS DISTINCT FROM 'number'
           OR jsonb_typeof(NEW.payload->'counterAfter') IS DISTINCT FROM 'number'
           OR jsonb_typeof(NEW.payload->'penaltyStageAfter') IS DISTINCT FROM 'number'
           OR (NEW.payload->>'schemaVersion') !~ '^1$'
           OR (NEW.payload->>'counterAfter') !~ '^[0-9]+$'
           OR (NEW.payload->>'penaltyStageAfter') !~ '^[0-3]$' THEN
            RAISE EXCEPTION 'ADMIN_TRUST_ADJUSTMENT payload must match the exact version-1 absolute schema';
        END IF;
        v_counter := (NEW.payload->>'counterAfter')::integer;
        v_stage := (NEW.payload->>'penaltyStageAfter')::smallint;
        IF v_counter >= trust.penalty_threshold(v_stage) THEN
            RAISE EXCEPTION 'ADMIN_TRUST_ADJUSTMENT counterAfter must be below the resulting stage threshold';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION trust.prepare_trust_event_insert() FROM PUBLIC;

-- AR18-08. Audit provenance is exact and action-specific.
CREATE OR REPLACE FUNCTION trust.assert_admin_trust_event_audit()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE v_count integer;
BEGIN
    IF NEW.event_type NOT IN (
        'ADMIN_TRUST_ADJUSTMENT','VERIFIED_PLAYER_SUSPENDED',
        'VERIFIED_PLAYER_REVOKED','VERIFIED_PLAYER_RESTORED'
    ) THEN
        RETURN NULL;
    END IF;

    SELECT COUNT(*) INTO v_count
      FROM audit.audit_event a
     WHERE a.actor_type = 'ADMIN'
       AND a.actor_id = (NEW.payload->>'adminId')::uuid
       AND a.subject_type = 'USER'
       AND a.subject_id = NEW.subject_user_id
       AND a.action = NEW.event_type
       AND a.occurred_at = NEW.occurred_at
       AND a.correlation_id = (NEW.payload->>'correlationId')::uuid
       AND NULLIF(BTRIM(a.reason),'') IS NOT NULL;
    IF v_count <> 1 THEN
        RAISE EXCEPTION '% requires exactly one action-specific USER Admin audit', NEW.event_type;
    END IF;
    RETURN NULL;
END;
$function$;

-- AR18-01. Commit proves all replay-derived values, not only freshness/watermark.
CREATE OR REPLACE FUNCTION trust.assert_trust_event_projection_current()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    p trust.trust_projection%ROWTYPE;
    r record;
BEGIN
    SELECT * INTO p FROM trust.trust_projection WHERE user_id = NEW.subject_user_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Trust event requires a live Trust Projection by commit';
    END IF;
    SELECT * INTO STRICT r FROM trust.replay_state(NEW.subject_user_id);

    IF p.last_effective_at IS DISTINCT FROM r.last_effective_at
       OR p.last_event_sequence IS DISTINCT FROM r.last_event_sequence
       OR p.consecutive_no_shows IS DISTINCT FROM r.consecutive_no_shows
       OR p.penalty_stage IS DISTINCT FROM r.penalty_stage
       OR p.current_threshold IS DISTINCT FROM r.current_threshold
       OR p.completed_attended_count IS DISTINCT FROM r.completed_attended_count
       OR p.vp_qualification IS DISTINCT FROM r.vp_qualification THEN
        RAISE EXCEPTION 'Trust Projection values must equal canonical full replay by commit';
    END IF;
    IF p.recomputed_at IS NULL OR p.recomputed_at < NEW.occurred_at THEN
        RAISE EXCEPTION 'Trust Projection must be recomputed after the inserted Trust event before commit';
    END IF;
    RETURN NULL;
END;
$function$;

-- AR18-03. A qualification is valid only at a real threshold crossing returned
-- by the same canonical replay timeline.
CREATE OR REPLACE FUNCTION trust.guard_ban_qualification()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE e trust.trust_event%ROWTYPE;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF NEW IS DISTINCT FROM OLD THEN
            RAISE EXCEPTION 'Ban Qualification is immutable derived history';
        END IF;
        RETURN NEW;
    END IF;
    SELECT * INTO e FROM trust.trust_event WHERE id = NEW.triggering_event_id;
    IF NOT FOUND OR e.subject_user_id IS DISTINCT FROM NEW.user_id
       OR e.effective_at IS DISTINCT FROM NEW.qualification_at THEN
        RAISE EXCEPTION 'Ban Qualification must match its Trust event User/effective position';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM trust.replay_timeline(NEW.user_id) t
         WHERE t.effect_event_id = NEW.triggering_event_id
           AND t.effective_at = NEW.qualification_at
           AND t.qualification_stage = NEW.penalty_stage
    ) THEN
        RAISE EXCEPTION 'Ban Qualification must be an authentic canonical replay threshold crossing';
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION trust.reject_ban_qualification_delete()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    RAISE EXCEPTION 'Ban Qualification history cannot be deleted';
END;
$function$;
DROP TRIGGER IF EXISTS tr_ban_qualification_no_delete ON trust.ban_qualification;
CREATE TRIGGER tr_ban_qualification_no_delete
BEFORE DELETE ON trust.ban_qualification
FOR EACH ROW EXECUTE FUNCTION trust.reject_ban_qualification_delete();

-- AR18-03/04/05. DB-authoritative activation, exact stage-duration ladder,
-- exact MAX extension formula, triggering-qualification binding and due expiry.
CREATE OR REPLACE FUNCTION trust.guard_ban_instance()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    q trust.ban_qualification%ROWTYPE;
    v_now timestamptz := transaction_timestamp();
    v_stage_duration interval;
    v_expected_end timestamptz;
BEGIN
    PERFORM 1 FROM iam.user_commitment_guard g WHERE g.user_id = NEW.user_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ban Instance requires the subject User commitment guard';
    END IF;
    SELECT * INTO q FROM trust.ban_qualification WHERE id = NEW.qualification_id;
    IF NOT FOUND OR q.user_id IS DISTINCT FROM NEW.user_id THEN
        RAISE EXCEPTION 'Ban Instance qualification must belong to the same User';
    END IF;
    v_stage_duration := trust.penalty_duration(q.penalty_stage);
    IF v_stage_duration IS NULL THEN
        RAISE EXCEPTION 'Ban qualification stage must be in the frozen 1..3 ladder';
    END IF;

    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'ACTIVE' THEN
            RAISE EXCEPTION 'A Ban Instance is created ACTIVE';
        END IF;
        NEW.penalty_stage := q.penalty_stage;
        NEW.activated_at := v_now;
        NEW.duration := v_stage_duration;
        NEW.ends_at := v_now + v_stage_duration;
        IF NEW.activated_at < q.qualification_at THEN
            RAISE EXCEPTION 'Operational Ban activation may not predate qualification';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.user_id IS DISTINCT FROM OLD.user_id
       OR NEW.activated_at IS DISTINCT FROM OLD.activated_at
       OR NEW.activation_reason IS DISTINCT FROM OLD.activation_reason THEN
        RAISE EXCEPTION 'Ban Instance identity/activation facts are immutable';
    END IF;
    IF OLD.cascade_executed_at IS NOT NULL
       AND NEW.cascade_executed_at IS DISTINCT FROM OLD.cascade_executed_at THEN
        RAISE EXCEPTION 'Ban cascade_executed_at is immutable once recorded';
    END IF;
    IF OLD.status <> 'ACTIVE' THEN
        IF NEW IS DISTINCT FROM OLD THEN
            RAISE EXCEPTION 'Terminal Ban Instance is immutable';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.status = 'ACTIVE' AND NEW.qualification_id IS DISTINCT FROM OLD.qualification_id THEN
        IF q.penalty_stage IS DISTINCT FROM NEW.penalty_stage
           OR NOT (
               NEW.penalty_stage > OLD.penalty_stage
               OR (OLD.penalty_stage = 3 AND NEW.penalty_stage = 3)
           ) THEN
            RAISE EXCEPTION 'Ban extension must bind the new stage to a new matching qualification';
        END IF;
        v_expected_end := GREATEST(OLD.ends_at, v_now + v_stage_duration);
        IF NEW.ends_at IS DISTINCT FROM v_expected_end THEN
            RAISE EXCEPTION 'Ban extension end must equal MAX(currentEndsAt, transaction time + durationForNewStage)';
        END IF;
        NEW.duration := NEW.ends_at - NEW.activated_at;
        IF NEW.cascade_executed_at IS DISTINCT FROM OLD.cascade_executed_at THEN
            RAISE EXCEPTION 'Ban extension must not repeat the original cascade';
        END IF;
    ELSIF NEW.status = 'ACTIVE' THEN
        IF NEW.qualification_id IS DISTINCT FROM OLD.qualification_id
           OR NEW.penalty_stage IS DISTINCT FROM OLD.penalty_stage THEN
            RAISE EXCEPTION 'Ban qualification/stage changes only for a genuine extension';
        END IF;
        IF NEW.ends_at > OLD.ends_at THEN
            RAISE EXCEPTION 'Ban may extend only when a new qualification advances the stage';
        END IF;
        NEW.duration := NEW.ends_at - NEW.activated_at;
    ELSIF NEW.status = 'EXPIRED' THEN
        IF v_now < OLD.ends_at THEN
            RAISE EXCEPTION 'ACTIVE Ban cannot expire before ends_at';
        END IF;
        IF NEW.qualification_id IS DISTINCT FROM OLD.qualification_id
           OR NEW.penalty_stage IS DISTINCT FROM OLD.penalty_stage
           OR NEW.ends_at IS DISTINCT FROM OLD.ends_at
           OR NEW.duration IS DISTINCT FROM OLD.duration THEN
            RAISE EXCEPTION 'Natural Ban expiry may not rewrite qualification, stage or planned end';
        END IF;
    ELSIF NEW.status IN ('LIFTED','CORRECTED') THEN
        IF NEW.qualification_id IS DISTINCT FROM OLD.qualification_id
           OR NEW.penalty_stage IS DISTINCT FROM OLD.penalty_stage
           OR NEW.ends_at > OLD.ends_at THEN
            RAISE EXCEPTION 'Lift/correction may end early but may not rewrite qualification/stage or extend';
        END IF;
        NEW.duration := NEW.ends_at - NEW.activated_at;
    ELSE
        RAISE EXCEPTION 'Invalid Ban Instance transition';
    END IF;

    IF NEW.duration <= interval '0' OR NEW.ends_at <= NEW.activated_at
       OR NEW.ends_at IS DISTINCT FROM NEW.activated_at + NEW.duration THEN
        RAISE EXCEPTION 'Ban Instance duration/time arithmetic is invalid';
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION trust.assert_ban_lifecycle_audit()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE q trust.ban_qualification%ROWTYPE;
BEGIN
    IF OLD.status <> 'ACTIVE' THEN RETURN NULL; END IF;
    IF NEW.status = 'ACTIVE' AND NEW.qualification_id IS DISTINCT FROM OLD.qualification_id THEN
        SELECT * INTO STRICT q FROM trust.ban_qualification WHERE id = NEW.qualification_id;
        IF NOT EXISTS (
            SELECT 1 FROM audit.audit_event a
             WHERE a.action = 'BAN_EXTENDED'
               AND a.subject_type = 'USER'
               AND a.subject_id = NEW.user_id
               AND a.occurred_at = transaction_timestamp()
               AND a.payload->>'banInstanceId' = NEW.id::text
               AND a.payload->>'triggeringQualificationId' = q.id::text
               AND a.payload->>'triggeringEventId' = q.triggering_event_id::text
               AND (a.payload->>'previousPenaltyStage')::smallint = OLD.penalty_stage
               AND (a.payload->>'newPenaltyStage')::smallint = NEW.penalty_stage
               AND (a.payload->>'oldEndsAt')::timestamptz = OLD.ends_at
               AND (a.payload->>'newEndsAt')::timestamptz = NEW.ends_at
        ) THEN
            RAISE EXCEPTION 'Ban extension requires exact qualification-bound BAN_EXTENDED audit';
        END IF;
    ELSIF NEW.status = 'ACTIVE' AND NEW.ends_at < OLD.ends_at THEN
        IF NOT EXISTS (
            SELECT 1 FROM audit.audit_event a
             WHERE a.actor_type='ADMIN' AND a.subject_type='USER'
               AND a.subject_id=NEW.user_id AND a.action='BAN_SHORTENED'
               AND a.payload->>'banInstanceId'=NEW.id::text
               AND (a.payload->>'newEndsAt')::timestamptz=NEW.ends_at
               AND NULLIF(BTRIM(a.reason),'') IS NOT NULL
        ) THEN RAISE EXCEPTION 'Admin Ban shortening requires exact USER audit'; END IF;
    ELSIF NEW.status = 'LIFTED' THEN
        IF NOT EXISTS (
            SELECT 1 FROM audit.audit_event a
             WHERE a.actor_type='ADMIN' AND a.subject_type='USER'
               AND a.subject_id=NEW.user_id AND a.action='BAN_LIFTED'
               AND a.occurred_at=NEW.ends_at
               AND a.payload->>'banInstanceId'=NEW.id::text
               AND NULLIF(BTRIM(a.reason),'') IS NOT NULL
        ) THEN RAISE EXCEPTION 'Admin Ban lift requires exact USER audit'; END IF;
    ELSIF NEW.status = 'CORRECTED' THEN
        IF NOT EXISTS (
            SELECT 1 FROM audit.audit_event a
             WHERE a.subject_type='USER' AND a.subject_id=NEW.user_id
               AND a.action='BAN_CORRECTED' AND a.occurred_at=NEW.ends_at
               AND a.payload->>'banInstanceId'=NEW.id::text
               AND NULLIF(BTRIM(a.reason),'') IS NOT NULL
        ) THEN RAISE EXCEPTION 'Corrected Ban requires exact USER audit'; END IF;
    END IF;
    RETURN NULL;
END;
$function$;

-- AR18-06. The once-only BAN command proves exact USER_BANNED transition
-- provenance and releases every Booking/Late-Confirm reservation.
CREATE OR REPLACE FUNCTION trust.assert_ban_booking_cascade()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    b trust.ban_instance%ROWTYPE;
    c trust.cascade_execution%ROWTYPE;
BEGIN
    SELECT * INTO b FROM trust.ban_instance WHERE id = NEW.id;
    IF NOT FOUND OR b.status <> 'ACTIVE' THEN RETURN NULL; END IF;

    SELECT * INTO c FROM trust.cascade_execution ce
     WHERE ce.cascade_type='BAN' AND ce.source_id=b.id;
    IF NOT FOUND OR c.subject_user_id IS DISTINCT FROM b.user_id
       OR b.cascade_executed_at IS NULL
       OR c.executed_at IS DISTINCT FROM b.cascade_executed_at
       OR c.executed_at IS DISTINCT FROM b.activated_at THEN
        RAISE EXCEPTION 'Active Ban requires one immediate matching BAN cascade command';
    END IF;

    IF EXISTS (
        SELECT 1 FROM booking.booking x
         WHERE x.source='ONLINE' AND x.customer_id=b.user_id
           AND (x.status IN ('PENDING','AWAITING_CUSTOMER_CONFIRMATION')
                OR (x.status='CONFIRMED' AND x.start_at>b.activated_at))
    ) THEN
        RAISE EXCEPTION 'Active Ban left an affected Online Booking live';
    END IF;

    IF EXISTS (
        SELECT 1
          FROM booking.booking_history h
          JOIN booking.booking x ON x.id=h.booking_id
         WHERE x.source='ONLINE' AND x.customer_id=b.user_id
           AND h.occurred_at=b.activated_at
           AND (h.from_status IN ('PENDING','AWAITING_CUSTOMER_CONFIRMATION')
                OR (h.from_status='CONFIRMED' AND x.start_at>b.activated_at))
           AND (h.to_status IS DISTINCT FROM 'CANCELLED'
                OR h.terminal_reason IS DISTINCT FROM 'USER_BANNED'
                OR h.correlation_id IS DISTINCT FROM c.correlation_id
                OR x.status IS DISTINCT FROM 'CANCELLED'
                OR x.terminal_reason IS DISTINCT FROM 'USER_BANNED')
    ) THEN
        RAISE EXCEPTION 'Ban cascade affected Booking must be CANCELLED/USER_BANNED with current-command provenance';
    END IF;

    IF EXISTS (
        SELECT 1
          FROM booking.booking_history h
          JOIN booking.booking x ON x.id=h.booking_id
          JOIN inventory.resource_reservation rr ON rr.booking_id=x.id
         WHERE x.source='ONLINE' AND x.customer_id=b.user_id
           AND h.occurred_at=b.activated_at
           AND h.to_status='CANCELLED' AND h.terminal_reason='USER_BANNED'
           AND h.correlation_id=c.correlation_id
           AND rr.reservation_type IN ('BOOKING','LATE_CONFIRM_HOLD')
           AND rr.active_flag=true
    ) THEN
        RAISE EXCEPTION 'Ban cascade must release Booking and Late Confirmation holds';
    END IF;
    RETURN NULL;
END;
$function$;

-- AR18-07. Reverse event -> transition assertion complements the retained
-- transition -> event assertion.
CREATE OR REPLACE FUNCTION trust.assert_admin_vp_event_transition()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_count integer;
BEGIN
    IF NEW.event_type NOT IN (
        'VERIFIED_PLAYER_SUSPENDED','VERIFIED_PLAYER_REVOKED','VERIFIED_PLAYER_RESTORED'
    ) THEN RETURN NULL; END IF;

    SELECT COUNT(*) INTO v_count
      FROM trust.verified_player_transition v
     WHERE v.user_id=NEW.subject_user_id
       AND v.cause='ADMIN'
       AND v.admin_id=(NEW.payload->>'adminId')::uuid
       AND v.occurred_at=NEW.occurred_at
       AND (
            (NEW.event_type='VERIFIED_PLAYER_SUSPENDED' AND v.to_status='SUSPENDED')
         OR (NEW.event_type='VERIFIED_PLAYER_REVOKED' AND v.to_status='REVOKED')
         OR (NEW.event_type='VERIFIED_PLAYER_RESTORED' AND v.to_status IN ('VERIFIED','NOT_VERIFIED'))
       );
    IF v_count <> 1 THEN
        RAISE EXCEPTION 'Admin Verified Player Trust event requires exactly one matching operational transition';
    END IF;
    RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_admin_vp_event_transition ON trust.trust_event;
CREATE CONSTRAINT TRIGGER tr_admin_vp_event_transition
AFTER INSERT ON trust.trust_event
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION trust.assert_admin_vp_event_transition();

-- Retained transition -> event binding, now also action/subject specific via the
-- event-side audit assertion above.
CREATE OR REPLACE FUNCTION trust.assert_admin_verified_player_transition()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_event_type text;
    v_event_count integer;
BEGIN
    IF NEW.cause <> 'ADMIN' THEN RETURN NULL; END IF;
    v_event_type := CASE
        WHEN NEW.to_status='SUSPENDED' THEN 'VERIFIED_PLAYER_SUSPENDED'
        WHEN NEW.to_status='REVOKED' THEN 'VERIFIED_PLAYER_REVOKED'
        ELSE 'VERIFIED_PLAYER_RESTORED'
    END;
    SELECT COUNT(*) INTO v_event_count
      FROM trust.trust_event e
     WHERE e.subject_user_id=NEW.user_id
       AND e.event_type=v_event_type
       AND e.occurred_at=NEW.occurred_at
       AND e.effective_at=NEW.occurred_at
       AND (e.payload->>'adminId')::uuid=NEW.admin_id;
    IF v_event_count <> 1 THEN
        RAISE EXCEPTION 'Admin VP transition requires exactly one canonical Trust event';
    END IF;
    RETURN NULL;
END;
$function$;


-- ============================================================================
-- E7GZ PS v1.1.20 TRUST REPLAY / BAN EXACT-SET CORRECTIONS
-- Closes v1.1.19 independent findings P1-01..P1-05 and P2-01..P2-02.
-- Tournament v1.1.17 source behavior remains unchanged.
-- PostgreSQL 16+.
-- ============================================================================

-- v1.1.19 was not an accepted production baseline and allowed extension to
-- overwrite qualification_id. Existing rows therefore cannot be backfilled
-- without inventing initial-consumption provenance. Fail closed and require an
-- explicit reviewed reconciliation if a non-empty review database is upgraded.
DO $v119_preflight$
BEGIN
    IF EXISTS (SELECT 1 FROM trust.ban_instance) THEN
        RAISE EXCEPTION 'v1.1.20 requires an empty pre-production ban_instance table or an explicitly reviewed legacy Qualification-consumption reconciliation';
    END IF;
END
$v119_preflight$;

ALTER TABLE trust.ban_instance ADD COLUMN IF NOT EXISTS latest_qualification_id uuid;
ALTER TABLE trust.ban_instance ADD COLUMN IF NOT EXISTS last_command_at timestamptz;
ALTER TABLE trust.ban_instance ADD COLUMN IF NOT EXISTS cascade_targets_registered_at timestamptz;
UPDATE trust.ban_instance
   SET latest_qualification_id = COALESCE(latest_qualification_id, qualification_id),
       last_command_at = COALESCE(last_command_at, activated_at);
ALTER TABLE trust.ban_instance ALTER COLUMN latest_qualification_id SET NOT NULL;
ALTER TABLE trust.ban_instance ALTER COLUMN last_command_at SET NOT NULL;

CREATE TABLE IF NOT EXISTS trust.ban_qualification_consumption (
    qualification_id uuid PRIMARY KEY,
    ban_instance_id uuid NOT NULL,
    consequence_type varchar(80) NOT NULL CHECK (consequence_type IN ('CREATE','EXTEND')),
    consumed_at timestamptz NOT NULL,
    correlation_id uuid NOT NULL
);
CREATE TABLE IF NOT EXISTS trust.ban_cascade_booking_target (
    ban_instance_id uuid NOT NULL,
    booking_id uuid NOT NULL,
    from_status varchar(80) NOT NULL CHECK (from_status IN ('PENDING','AWAITING_CUSTOMER_CONFIRMATION','CONFIRMED')),
    registered_at timestamptz NOT NULL,
    correlation_id uuid NOT NULL,
    PRIMARY KEY (ban_instance_id, booking_id)
);
CREATE TABLE IF NOT EXISTS trust.ban_cascade_reservation_target (
    ban_instance_id uuid NOT NULL,
    reservation_id uuid NOT NULL,
    booking_id uuid NOT NULL,
    registered_at timestamptz NOT NULL,
    PRIMARY KEY (ban_instance_id, reservation_id)
);

-- pgModeler load hotfix: the eight Trust FKs formerly created here are native XML constraint objects.
-- They are exported once by pgModeler; the standalone upgrade migration is unchanged.

-- P1-01 / P2-01. Protection remains effective with an authoritative
-- ATTENDANCE_UNCONFIRMED result. A composite as-of boundary is all-or-nothing.
CREATE OR REPLACE FUNCTION trust.canonical_trust_effects(
    p_user_id uuid,
    p_as_of_effective timestamptz DEFAULT NULL,
    p_as_of_sequence bigint DEFAULT NULL
)
RETURNS TABLE(
    effect_event_id uuid,
    effective_at timestamptz,
    event_sequence bigint,
    effect_type text,
    effect_payload jsonb
)
LANGUAGE plpgsql
STABLE
AS $function$
BEGIN
    IF (p_as_of_effective IS NULL) <> (p_as_of_sequence IS NULL) THEN
        RAISE EXCEPTION 'Trust as-of boundary requires both effective_at and event_sequence, or neither';
    END IF;

    RETURN QUERY
    WITH bounded AS (
        SELECT e.* FROM trust.trust_event e
         WHERE e.subject_user_id=p_user_id
           AND (p_as_of_effective IS NULL OR e.effective_at<p_as_of_effective
                OR (e.effective_at=p_as_of_effective AND e.event_sequence<=p_as_of_sequence))
    ),
    originals AS (
        SELECT e.* FROM bounded e WHERE e.event_type IN (
            'BOOKING_ATTENDED','BOOKING_ATTENDANCE_UNCONFIRMED',
            'BOOKING_ATTENDED_INTERRUPTED','BOOKING_NO_SHOW'
        )
    ),
    leaf_corrections AS (
        SELECT DISTINCT ON (c.booking_id) c.* FROM bounded c
         WHERE c.event_type='ATTENDANCE_CORRECTED'
           AND NOT EXISTS (
               SELECT 1 FROM bounded s
                WHERE s.event_type='ATTENDANCE_CORRECTED'
                  AND s.superseded_correction_event_id=c.id
           )
         ORDER BY c.booking_id,c.event_sequence DESC
    ),
    reversals AS (
        SELECT DISTINCT ON (r.booking_id) r.* FROM bounded r
         WHERE r.event_type='NO_SHOW_REVERSED'
         ORDER BY r.booking_id,r.event_sequence DESC
    ),
    resolved_outcomes AS (
        SELECT COALESCE(c.id,r.id,o.id) AS effect_event_id,
               COALESCE(c.effective_at,r.effective_at,o.effective_at) AS effective_at,
               COALESCE(c.event_sequence,r.event_sequence,o.event_sequence) AS event_sequence,
               CASE WHEN c.id IS NOT NULL THEN CASE c.corrected_outcome
                    WHEN 'ATTENDED' THEN 'BOOKING_ATTENDED'
                    WHEN 'ATTENDED_INTERRUPTED' THEN 'BOOKING_ATTENDED_INTERRUPTED'
                    WHEN 'ATTENDANCE_UNCONFIRMED' THEN 'BOOKING_ATTENDANCE_UNCONFIRMED'
                    WHEN 'ABSENT_NO_SHOW' THEN 'BOOKING_NO_SHOW' END
                    WHEN r.id IS NOT NULL THEN 'BOOKING_ATTENDANCE_UNCONFIRMED'
                    ELSE o.event_type END::text AS effect_type,
               COALESCE(c.payload,r.payload,o.payload) AS effect_payload,
               o.booking_id
          FROM originals o
          LEFT JOIN leaf_corrections c ON c.booking_id=o.booking_id AND c.original_outcome_event_id=o.id
          LEFT JOIN reversals r ON r.booking_id=o.booking_id AND r.original_outcome_event_id=o.id AND c.id IS NULL
    ),
    protection AS (
        SELECT p.id AS effect_event_id,p.effective_at,p.event_sequence,
               p.event_type::text AS effect_type,p.payload AS effect_payload
          FROM bounded p
         WHERE p.event_type='BOOKING_ACCOUNT_DISABLE_ATTENDANCE_PROTECTION'
           AND NOT EXISTS (
               SELECT 1 FROM resolved_outcomes ro
                WHERE ro.booking_id=p.booking_id
                  AND ro.effect_type IN ('BOOKING_ATTENDED','BOOKING_ATTENDED_INTERRUPTED','BOOKING_NO_SHOW')
           )
    ),
    administrative AS (
        SELECT a.id AS effect_event_id,a.effective_at,a.event_sequence,
               a.event_type::text AS effect_type,a.payload AS effect_payload
          FROM bounded a
         WHERE a.event_type IN (
            'ADMIN_TRUST_ADJUSTMENT','VERIFIED_PLAYER_SUSPENDED',
            'VERIFIED_PLAYER_REVOKED','VERIFIED_PLAYER_RESTORED'
         )
    )
    SELECT ro.effect_event_id,ro.effective_at,ro.event_sequence,ro.effect_type,ro.effect_payload FROM resolved_outcomes ro
    UNION ALL
    SELECT p.effect_event_id,p.effective_at,p.event_sequence,p.effect_type,p.effect_payload FROM protection p
    UNION ALL
    SELECT a.effect_event_id,a.effective_at,a.event_sequence,a.effect_type,a.effect_payload FROM administrative a
    ORDER BY 2,3;
END;
$function$;

-- P1-03. A Qualification can be consumed once only and must still be a real
-- crossing in the current corrected replay at the moment of consumption.
CREATE OR REPLACE FUNCTION trust.guard_ban_qualification_consumption()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    b trust.ban_instance%ROWTYPE;
    q trust.ban_qualification%ROWTYPE;
BEGIN
    IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'Ban Qualification consumption is append-only'; END IF;
    SELECT * INTO STRICT b FROM trust.ban_instance WHERE id=NEW.ban_instance_id;
    PERFORM 1 FROM iam.user_commitment_guard g WHERE g.user_id=b.user_id FOR UPDATE;
    SELECT * INTO STRICT q FROM trust.ban_qualification WHERE id=NEW.qualification_id;
    IF q.user_id IS DISTINCT FROM b.user_id OR NOT EXISTS (
        SELECT 1 FROM trust.replay_timeline(q.user_id) t
         WHERE t.effect_event_id=q.triggering_event_id
           AND t.effective_at=q.qualification_at
           AND t.qualification_stage=q.penalty_stage
    ) THEN
        RAISE EXCEPTION 'Consumed Ban Qualification must remain valid in current corrected replay';
    END IF;
    IF NEW.consequence_type='CREATE' THEN
        IF NEW.qualification_id IS DISTINCT FROM b.qualification_id
           OR b.latest_qualification_id IS DISTINCT FROM b.qualification_id
           OR NEW.consumed_at IS DISTINCT FROM b.activated_at THEN
            RAISE EXCEPTION 'CREATE consumption must bind the immutable initial qualification and activation time';
        END IF;
    ELSE
        IF NEW.qualification_id IS DISTINCT FROM b.latest_qualification_id
           OR NEW.qualification_id IS NOT DISTINCT FROM b.qualification_id
           OR NEW.consumed_at IS DISTINCT FROM b.last_command_at THEN
            RAISE EXCEPTION 'EXTEND consumption must bind the latest non-initial qualification and post-lock command time';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_ban_qualification_consumption_guard ON trust.ban_qualification_consumption;
CREATE TRIGGER tr_ban_qualification_consumption_guard
BEFORE INSERT OR UPDATE OR DELETE ON trust.ban_qualification_consumption
FOR EACH ROW EXECUTE FUNCTION trust.guard_ban_qualification_consumption();

CREATE OR REPLACE FUNCTION trust.assert_ban_qualification_consumed()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE v_type text;
BEGIN
    v_type := CASE WHEN TG_OP='INSERT' THEN 'CREATE' ELSE 'EXTEND' END;
    IF TG_OP='UPDATE' AND NEW.latest_qualification_id IS NOT DISTINCT FROM OLD.latest_qualification_id THEN
        RETURN NULL;
    END IF;
    IF (SELECT COUNT(*) FROM trust.ban_qualification_consumption c
         WHERE c.qualification_id=NEW.latest_qualification_id
           AND c.ban_instance_id=NEW.id AND c.consequence_type=v_type
           AND c.consumed_at=CASE WHEN v_type='CREATE' THEN NEW.activated_at ELSE NEW.last_command_at END
           AND (v_type<>'CREATE' OR EXISTS (
               SELECT 1 FROM trust.cascade_execution ce
                WHERE ce.cascade_type='BAN' AND ce.source_id=NEW.id
                  AND ce.correlation_id=c.correlation_id
           ))) <> 1 THEN
        RAISE EXCEPTION 'Ban create/extension requires exactly one matching Qualification consumption by commit';
    END IF;
    RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_ban_qualification_consumed ON trust.ban_instance;
CREATE CONSTRAINT TRIGGER tr_ban_qualification_consumed
AFTER INSERT OR UPDATE ON trust.ban_instance
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION trust.assert_ban_qualification_consumed();

CREATE OR REPLACE FUNCTION trust.consume_ban_qualification(
    p_ban_instance_id uuid,p_qualification_id uuid,p_consequence_type text,p_correlation_id uuid
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=pg_catalog,pg_temp
AS $function$
DECLARE b trust.ban_instance%ROWTYPE; v_consumed_at timestamptz;
BEGIN
    SELECT * INTO STRICT b FROM trust.ban_instance WHERE id=p_ban_instance_id FOR UPDATE;
    PERFORM 1 FROM iam.user_commitment_guard g WHERE g.user_id=b.user_id FOR UPDATE;
    IF p_consequence_type='CREATE' THEN v_consumed_at:=b.activated_at;
    ELSIF p_consequence_type='EXTEND' THEN v_consumed_at:=b.last_command_at;
    ELSE RAISE EXCEPTION 'Invalid Ban Qualification consequence type'; END IF;
    INSERT INTO trust.ban_qualification_consumption(
        qualification_id,ban_instance_id,consequence_type,consumed_at,correlation_id
    ) VALUES (p_qualification_id,p_ban_instance_id,p_consequence_type,v_consumed_at,p_correlation_id);
END;
$function$;
REVOKE ALL ON FUNCTION trust.consume_ban_qualification(uuid,uuid,text,uuid) FROM PUBLIC;

-- P1-02/P1-03/P1-05. Acquire the User lock first, then capture one real wall
-- clock instant. Initial provenance is immutable; extensions use latest_qualification_id.
CREATE OR REPLACE FUNCTION trust.guard_ban_instance()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    q trust.ban_qualification%ROWTYPE;
    old_q trust.ban_qualification%ROWTYPE;
    v_now timestamptz;
    v_stage_duration interval;
    v_expected_end timestamptz;
    v_lifecycle_change boolean := false;
BEGIN
    PERFORM 1 FROM iam.user_commitment_guard g WHERE g.user_id=NEW.user_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Ban Instance requires the subject User commitment guard'; END IF;
    v_now := clock_timestamp();

    IF TG_OP='INSERT' THEN
        SELECT * INTO STRICT q FROM trust.ban_qualification WHERE id=NEW.qualification_id;
        IF q.user_id IS DISTINCT FROM NEW.user_id OR NOT EXISTS (
            SELECT 1 FROM trust.replay_timeline(q.user_id) t
             WHERE t.effect_event_id=q.triggering_event_id AND t.effective_at=q.qualification_at
               AND t.qualification_stage=q.penalty_stage
        ) OR EXISTS (
            SELECT 1 FROM trust.ban_qualification_consumption c WHERE c.qualification_id=q.id
        ) THEN RAISE EXCEPTION 'Initial Ban Qualification must be current-replay-valid and unused'; END IF;
        IF NEW.status<>'ACTIVE' THEN RAISE EXCEPTION 'A Ban Instance is created ACTIVE'; END IF;
        v_stage_duration := trust.penalty_duration(q.penalty_stage);
        IF v_stage_duration IS NULL THEN RAISE EXCEPTION 'Invalid frozen Ban stage'; END IF;
        NEW.latest_qualification_id := q.id;
        NEW.penalty_stage := q.penalty_stage;
        NEW.activated_at := v_now;
        NEW.last_command_at := v_now;
        NEW.duration := v_stage_duration;
        NEW.ends_at := v_now+v_stage_duration;
        NEW.cascade_targets_registered_at := NULL;
        RETURN NEW;
    END IF;

    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.user_id IS DISTINCT FROM OLD.user_id
       OR NEW.qualification_id IS DISTINCT FROM OLD.qualification_id
       OR NEW.activated_at IS DISTINCT FROM OLD.activated_at
       OR NEW.activation_reason IS DISTINCT FROM OLD.activation_reason THEN
        RAISE EXCEPTION 'Ban identity, initial qualification and activation facts are immutable';
    END IF;
    IF OLD.status<>'ACTIVE' THEN
        IF NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'Terminal Ban Instance is immutable'; END IF;
        RETURN NEW;
    END IF;
    IF OLD.cascade_executed_at IS NOT NULL AND NEW.cascade_executed_at IS DISTINCT FROM OLD.cascade_executed_at THEN
        RAISE EXCEPTION 'Ban cascade marker is immutable once recorded';
    END IF;
    IF OLD.cascade_targets_registered_at IS NOT NULL
       AND NEW.cascade_targets_registered_at IS DISTINCT FROM OLD.cascade_targets_registered_at THEN
        RAISE EXCEPTION 'Ban exact-target registration marker is immutable once recorded';
    END IF;

    -- Technical marker updates remain part of the original activation command.
    IF NEW.status IS NOT DISTINCT FROM OLD.status
       AND NEW.latest_qualification_id IS NOT DISTINCT FROM OLD.latest_qualification_id
       AND NEW.penalty_stage IS NOT DISTINCT FROM OLD.penalty_stage
       AND NEW.ends_at IS NOT DISTINCT FROM OLD.ends_at
       AND NEW.duration IS NOT DISTINCT FROM OLD.duration THEN
        NEW.last_command_at := OLD.last_command_at;
        RETURN NEW;
    END IF;

    IF NEW.status='ACTIVE' AND NEW.latest_qualification_id IS DISTINCT FROM OLD.latest_qualification_id THEN
        SELECT * INTO STRICT q FROM trust.ban_qualification WHERE id=NEW.latest_qualification_id;
        SELECT * INTO STRICT old_q FROM trust.ban_qualification WHERE id=OLD.latest_qualification_id;
        IF q.user_id IS DISTINCT FROM NEW.user_id OR EXISTS (
            SELECT 1 FROM trust.ban_qualification_consumption c WHERE c.qualification_id=q.id
        ) OR NOT EXISTS (
            SELECT 1 FROM trust.replay_timeline(q.user_id) t
             WHERE t.effect_event_id=q.triggering_event_id AND t.effective_at=q.qualification_at
               AND t.qualification_stage=q.penalty_stage
        ) THEN RAISE EXCEPTION 'Extension Qualification must be current-replay-valid and unused'; END IF;
        IF q.penalty_stage IS DISTINCT FROM NEW.penalty_stage
           OR NEW.penalty_stage IS DISTINCT FROM LEAST(OLD.penalty_stage+1,3)::smallint
           OR NOT (
               q.qualification_at>old_q.qualification_at
               OR (q.qualification_at=old_q.qualification_at AND
                   (SELECT event_sequence FROM trust.trust_event WHERE id=q.triggering_event_id)>
                   (SELECT event_sequence FROM trust.trust_event WHERE id=old_q.triggering_event_id))
           ) THEN RAISE EXCEPTION 'Extension must consume the next-stage Qualification after the prior consumed position'; END IF;
        v_stage_duration := trust.penalty_duration(q.penalty_stage);
        v_expected_end := GREATEST(OLD.ends_at,v_now+v_stage_duration);
        NEW.ends_at := v_expected_end;
        NEW.last_command_at := v_now;
        NEW.duration := NEW.ends_at-NEW.activated_at;
    ELSIF NEW.status='ACTIVE' AND NEW.ends_at<OLD.ends_at THEN
        IF NEW.latest_qualification_id IS DISTINCT FROM OLD.latest_qualification_id
           OR NEW.penalty_stage IS DISTINCT FROM OLD.penalty_stage OR NEW.ends_at<=v_now THEN
            RAISE EXCEPTION 'Ban shortening cannot rewrite qualification/stage or backdate the operational end';
        END IF;
        NEW.last_command_at := v_now;
        NEW.duration := NEW.ends_at-NEW.activated_at;
    ELSIF NEW.status='EXPIRED' THEN
        IF v_now<OLD.ends_at THEN RAISE EXCEPTION 'ACTIVE Ban cannot expire before ends_at at post-lock wall-clock time'; END IF;
        IF NEW.latest_qualification_id IS DISTINCT FROM OLD.latest_qualification_id
           OR NEW.penalty_stage IS DISTINCT FROM OLD.penalty_stage
           OR NEW.ends_at IS DISTINCT FROM OLD.ends_at OR NEW.duration IS DISTINCT FROM OLD.duration THEN
            RAISE EXCEPTION 'Natural expiry may not rewrite Ban history';
        END IF;
        NEW.last_command_at := v_now;
    ELSIF NEW.status IN ('LIFTED','CORRECTED') THEN
        IF v_now>=OLD.ends_at THEN RAISE EXCEPTION 'Ended Ban must use natural EXPIRED transition, not lift/correction'; END IF;
        IF NEW.latest_qualification_id IS DISTINCT FROM OLD.latest_qualification_id
           OR NEW.penalty_stage IS DISTINCT FROM OLD.penalty_stage THEN
            RAISE EXCEPTION 'Lift/correction may not rewrite qualification or stage';
        END IF;
        NEW.last_command_at := v_now;
        NEW.ends_at := v_now;
        NEW.duration := NEW.ends_at-NEW.activated_at;
    ELSE
        RAISE EXCEPTION 'Invalid Ban Instance lifecycle transition';
    END IF;

    IF NEW.duration<=interval '0' OR NEW.ends_at<=NEW.activated_at
       OR NEW.ends_at IS DISTINCT FROM NEW.activated_at+NEW.duration THEN
        RAISE EXCEPTION 'Ban duration/time arithmetic is invalid';
    END IF;
    RETURN NEW;
END;
$function$;

-- Exact target registration is one database operation after activation and
-- before any affected Booking mutation. It records an explicit zero-set marker.
CREATE OR REPLACE FUNCTION trust.register_ban_cascade_targets(p_ban_id uuid,p_correlation_id uuid)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=pg_catalog,pg_temp
AS $function$
DECLARE b trust.ban_instance%ROWTYPE; v_count integer;
BEGIN
    SELECT * INTO STRICT b FROM trust.ban_instance WHERE id=p_ban_id FOR UPDATE;
    PERFORM 1 FROM iam.user_commitment_guard g WHERE g.user_id=b.user_id FOR UPDATE;
    IF b.status<>'ACTIVE' OR b.cascade_executed_at IS NOT NULL OR b.cascade_targets_registered_at IS NOT NULL THEN
        RAISE EXCEPTION 'Ban target set can be registered exactly once before cascade execution';
    END IF;
    INSERT INTO trust.ban_cascade_booking_target(
        ban_instance_id,booking_id,from_status,registered_at,correlation_id
    )
    SELECT b.id,x.id,x.status,b.activated_at,p_correlation_id
      FROM booking.booking x
     WHERE x.source='ONLINE' AND x.customer_id=b.user_id
       AND (x.status IN ('PENDING','AWAITING_CUSTOMER_CONFIRMATION')
            OR (x.status='CONFIRMED' AND x.start_at>b.activated_at));
    GET DIAGNOSTICS v_count=ROW_COUNT;
    INSERT INTO trust.ban_cascade_reservation_target(
        ban_instance_id,reservation_id,booking_id,registered_at
    )
    SELECT b.id,rr.id,rr.booking_id,b.activated_at
      FROM inventory.resource_reservation rr
      JOIN trust.ban_cascade_booking_target t
        ON t.ban_instance_id=b.id AND t.booking_id=rr.booking_id
     WHERE rr.active_flag=true AND rr.reservation_type IN ('BOOKING','LATE_CONFIRM_HOLD');
    UPDATE trust.ban_instance SET cascade_targets_registered_at=b.activated_at WHERE id=b.id;
    RETURN v_count;
END;
$function$;
REVOKE ALL ON FUNCTION trust.register_ban_cascade_targets(uuid,uuid) FROM PUBLIC;

DO $runtime_grants$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='e7gz_app_runtime') THEN
        REVOKE INSERT,UPDATE,DELETE ON trust.ban_qualification_consumption,
            trust.ban_cascade_booking_target,trust.ban_cascade_reservation_target FROM e7gz_app_runtime;
        GRANT SELECT ON trust.ban_qualification_consumption,
            trust.ban_cascade_booking_target,trust.ban_cascade_reservation_target TO e7gz_app_runtime;
        GRANT EXECUTE ON FUNCTION trust.consume_ban_qualification(uuid,uuid,text,uuid) TO e7gz_app_runtime;
        GRANT EXECUTE ON FUNCTION trust.register_ban_cascade_targets(uuid,uuid) TO e7gz_app_runtime;
    END IF;
END
$runtime_grants$;

CREATE OR REPLACE FUNCTION trust.guard_ban_cascade_registry()
RETURNS trigger LANGUAGE plpgsql AS $function$
DECLARE b trust.ban_instance%ROWTYPE; x booking.booking%ROWTYPE; rr inventory.resource_reservation%ROWTYPE;
BEGIN
    IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Ban cascade target registries are append-only'; END IF;
    SELECT * INTO STRICT b FROM trust.ban_instance WHERE id=NEW.ban_instance_id;
    IF b.status<>'ACTIVE' OR b.cascade_executed_at IS NOT NULL OR b.cascade_targets_registered_at IS NOT NULL
       OR NEW.registered_at IS DISTINCT FROM b.activated_at THEN
        RAISE EXCEPTION 'Ban cascade target must be captured before execution at activation time';
    END IF;
    IF TG_TABLE_NAME='ban_cascade_booking_target' THEN
        SELECT * INTO STRICT x FROM booking.booking WHERE id=NEW.booking_id;
        IF x.source<>'ONLINE' OR x.customer_id IS DISTINCT FROM b.user_id
           OR NEW.from_status IS DISTINCT FROM x.status
           OR NOT (x.status IN ('PENDING','AWAITING_CUSTOMER_CONFIRMATION')
                   OR (x.status='CONFIRMED' AND x.start_at>b.activated_at)) THEN
            RAISE EXCEPTION 'Ban Booking target must be currently affected when captured';
        END IF;
    ELSE
        SELECT * INTO STRICT rr FROM inventory.resource_reservation WHERE id=NEW.reservation_id;
        IF rr.booking_id IS DISTINCT FROM NEW.booking_id OR NOT rr.active_flag
           OR rr.reservation_type NOT IN ('BOOKING','LATE_CONFIRM_HOLD')
           OR NOT EXISTS (SELECT 1 FROM trust.ban_cascade_booking_target t
                           WHERE t.ban_instance_id=b.id AND t.booking_id=NEW.booking_id) THEN
            RAISE EXCEPTION 'Ban reservation target must be an active commitment of a captured Booking';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_ban_cascade_booking_target_immutable ON trust.ban_cascade_booking_target;
CREATE TRIGGER tr_ban_cascade_booking_target_immutable BEFORE INSERT OR UPDATE OR DELETE ON trust.ban_cascade_booking_target
FOR EACH ROW EXECUTE FUNCTION trust.guard_ban_cascade_registry();
DROP TRIGGER IF EXISTS tr_ban_cascade_reservation_target_immutable ON trust.ban_cascade_reservation_target;
CREATE TRIGGER tr_ban_cascade_reservation_target_immutable BEFORE INSERT OR UPDATE OR DELETE ON trust.ban_cascade_reservation_target
FOR EACH ROW EXECUTE FUNCTION trust.guard_ban_cascade_registry();

-- An open Ban cascade owns every affected transition. Registration must precede mutation.
CREATE OR REPLACE FUNCTION trust.guard_booking_open_ban_cascade()
RETURNS trigger LANGUAGE plpgsql AS $function$
DECLARE b trust.ban_instance%ROWTYPE;
BEGIN
    IF NEW.source<>'ONLINE' OR NEW.customer_id IS NULL OR NEW.status IS NOT DISTINCT FROM OLD.status THEN RETURN NEW; END IF;
    SELECT * INTO b FROM trust.ban_instance x
     WHERE x.user_id=NEW.customer_id AND x.status='ACTIVE'
       AND x.cascade_executed_at IS NULL
       AND (OLD.status IN ('PENDING','AWAITING_CUSTOMER_CONFIRMATION')
            OR (OLD.status='CONFIRMED' AND NEW.start_at>x.activated_at))
     ORDER BY x.activated_at DESC LIMIT 1;
    IF FOUND THEN
        IF b.cascade_targets_registered_at IS NULL OR NEW.status<>'CANCELLED'
           OR NEW.terminal_reason IS DISTINCT FROM 'USER_BANNED'
           OR NOT EXISTS (
               SELECT 1 FROM trust.ban_cascade_booking_target t
                WHERE t.ban_instance_id=b.id AND t.booking_id=NEW.id
                  AND t.from_status=OLD.status AND t.registered_at=b.activated_at
           ) THEN RAISE EXCEPTION 'Open Ban cascade requires a pre-registered CANCELLED/USER_BANNED target'; END IF;
    END IF;
    RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_04_booking_open_ban_cascade ON booking.booking;
CREATE TRIGGER tr_04_booking_open_ban_cascade BEFORE UPDATE OF status ON booking.booking
FOR EACH ROW EXECUTE FUNCTION trust.guard_booking_open_ban_cascade();

CREATE OR REPLACE FUNCTION trust.guard_cascade_execution()
RETURNS trigger LANGUAGE plpgsql AS $function$
DECLARE b trust.ban_instance%ROWTYPE; v trust.verified_player_transition%ROWTYPE; v_key text;
BEGIN
    IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'cascade_execution is append-only'; END IF;
    IF NEW.cascade_type='BAN' THEN
        SELECT * INTO b FROM trust.ban_instance WHERE id=NEW.source_id;
        IF NOT FOUND OR b.user_id IS DISTINCT FROM NEW.subject_user_id OR b.status<>'ACTIVE'
           OR b.cascade_targets_registered_at IS DISTINCT FROM b.activated_at
           OR NEW.executed_at IS DISTINCT FROM b.activated_at THEN
            RAISE EXCEPTION 'BAN cascade must bind the registered exact set and activation command instant';
        END IF;
        v_key:='BAN_CASCADE:'||b.id::text;
    ELSIF NEW.cascade_type='VERIFIED_PLAYER' THEN
        SELECT * INTO v FROM trust.verified_player_transition WHERE id=NEW.source_id;
        IF NOT FOUND OR v.user_id IS DISTINCT FROM NEW.subject_user_id
           OR v.from_status<>'VERIFIED' OR v.to_status<>'REVOKED' THEN
            RAISE EXCEPTION 'Invalid VERIFIED_PLAYER cascade source';
        END IF;
        v_key:='VP_TOURNAMENT_CASCADE:'||v.transition_id::text;
    ELSE RETURN NEW;
    END IF;
    IF NEW.cascade_key IS DISTINCT FROM v_key THEN RAISE EXCEPTION 'Invalid cascade key; expected %',v_key; END IF;
    RETURN NEW;
END;
$function$;

-- P1-04. Commit compares the captured expected Booking and reservation sets to
-- exact USER_BANNED histories, current rows, Late Confirmation closure and releases.
CREATE OR REPLACE FUNCTION trust.assert_ban_booking_cascade()
RETURNS trigger LANGUAGE plpgsql AS $function$
DECLARE b trust.ban_instance%ROWTYPE; c trust.cascade_execution%ROWTYPE;
BEGIN
    SELECT * INTO b FROM trust.ban_instance WHERE id=NEW.id;
    IF NOT FOUND OR b.status<>'ACTIVE' THEN RETURN NULL; END IF;
    SELECT * INTO c FROM trust.cascade_execution ce WHERE ce.cascade_type='BAN' AND ce.source_id=b.id;
    IF NOT FOUND OR c.subject_user_id IS DISTINCT FROM b.user_id
       OR b.cascade_targets_registered_at IS DISTINCT FROM b.activated_at
       OR b.cascade_executed_at IS DISTINCT FROM b.activated_at
       OR c.executed_at IS DISTINCT FROM b.activated_at THEN
        RAISE EXCEPTION 'Active Ban requires registered and executed exact cascade at activation instant';
    END IF;
    IF EXISTS (
        SELECT 1 FROM booking.booking x WHERE x.source='ONLINE' AND x.customer_id=b.user_id
         AND (x.status IN ('PENDING','AWAITING_CUSTOMER_CONFIRMATION') OR (x.status='CONFIRMED' AND x.start_at>b.activated_at))
    ) THEN RAISE EXCEPTION 'Active Ban left an expected Booking live'; END IF;
    IF EXISTS (
        SELECT 1 FROM trust.ban_cascade_booking_target t
        JOIN booking.booking x ON x.id=t.booking_id
        LEFT JOIN booking.booking_history h ON h.booking_id=t.booking_id
          AND h.occurred_at=b.activated_at AND h.from_status=t.from_status
          AND h.to_status='CANCELLED' AND h.terminal_reason='USER_BANNED'
          AND h.correlation_id=t.correlation_id
        WHERE t.ban_instance_id=b.id AND (
            t.registered_at IS DISTINCT FROM b.activated_at OR t.correlation_id IS DISTINCT FROM c.correlation_id
            OR h.id IS NULL OR x.status<>'CANCELLED' OR x.terminal_reason IS DISTINCT FROM 'USER_BANNED'
        )
    ) THEN RAISE EXCEPTION 'Every captured Ban Booking target requires exact CANCELLED/USER_BANNED history and provenance'; END IF;
    IF EXISTS (
        SELECT 1 FROM booking.booking_history h JOIN booking.booking x ON x.id=h.booking_id
         WHERE x.customer_id=b.user_id AND h.occurred_at=b.activated_at
           AND h.to_status='CANCELLED' AND h.terminal_reason='USER_BANNED'
           AND h.correlation_id=c.correlation_id
           AND NOT EXISTS (SELECT 1 FROM trust.ban_cascade_booking_target t WHERE t.ban_instance_id=b.id AND t.booking_id=h.booking_id)
    ) THEN RAISE EXCEPTION 'Actual USER_BANNED transition set exceeds captured target set'; END IF;
    IF EXISTS (
        SELECT 1 FROM trust.ban_cascade_reservation_target t
        JOIN inventory.resource_reservation rr ON rr.id=t.reservation_id
         WHERE t.ban_instance_id=b.id AND (
            rr.booking_id IS DISTINCT FROM t.booking_id OR rr.active_flag
            OR rr.actual_reservation_release_at IS NULL OR rr.actual_reservation_release_at<b.activated_at
         )
    ) THEN RAISE EXCEPTION 'Every captured Ban reservation/Hold target must be released by the command'; END IF;
    IF EXISTS (
        SELECT 1 FROM trust.ban_cascade_booking_target t
        JOIN booking.late_confirmation lc ON lc.booking_id=t.booking_id
         WHERE t.ban_instance_id=b.id AND t.from_status='AWAITING_CUSTOMER_CONFIRMATION' AND lc.closed_at IS NULL
    ) THEN RAISE EXCEPTION 'Ban cascade must close every captured Late Confirmation attempt'; END IF;
    RETURN NULL;
END;
$function$;

-- Command-time-specific audit bindings.
CREATE OR REPLACE FUNCTION trust.assert_ban_lifecycle_audit()
RETURNS trigger LANGUAGE plpgsql AS $function$
DECLARE q trust.ban_qualification%ROWTYPE;
BEGIN
    IF OLD.status<>'ACTIVE' THEN RETURN NULL; END IF;
    IF NEW.status='ACTIVE' AND NEW.latest_qualification_id IS DISTINCT FROM OLD.latest_qualification_id THEN
        SELECT * INTO STRICT q FROM trust.ban_qualification WHERE id=NEW.latest_qualification_id;
        IF NOT EXISTS (SELECT 1 FROM audit.audit_event a
          JOIN trust.ban_qualification_consumption qc ON qc.qualification_id=q.id AND qc.ban_instance_id=NEW.id
          WHERE a.action='BAN_EXTENDED' AND a.subject_type='USER' AND a.subject_id=NEW.user_id
            AND a.occurred_at=NEW.last_command_at
            AND a.correlation_id=qc.correlation_id
            AND a.payload->>'banInstanceId'=NEW.id::text
            AND a.payload->>'triggeringQualificationId'=q.id::text
            AND a.payload->>'triggeringEventId'=q.triggering_event_id::text
            AND (a.payload->>'previousPenaltyStage')::smallint=OLD.penalty_stage
            AND (a.payload->>'newPenaltyStage')::smallint=NEW.penalty_stage
            AND (a.payload->>'oldEndsAt')::timestamptz=OLD.ends_at
            AND (a.payload->>'newEndsAt')::timestamptz=NEW.ends_at)
        THEN RAISE EXCEPTION 'Ban extension requires exact post-lock qualification-bound audit'; END IF;
    ELSIF NEW.status='ACTIVE' AND NEW.ends_at<OLD.ends_at THEN
        IF NOT EXISTS (SELECT 1 FROM audit.audit_event a WHERE a.actor_type='ADMIN' AND a.subject_type='USER'
          AND a.subject_id=NEW.user_id AND a.action='BAN_SHORTENED' AND a.occurred_at=NEW.last_command_at
          AND a.payload->>'banInstanceId'=NEW.id::text AND (a.payload->>'newEndsAt')::timestamptz=NEW.ends_at
          AND NULLIF(BTRIM(a.reason),'') IS NOT NULL)
        THEN RAISE EXCEPTION 'Ban shortening requires post-lock command-time audit'; END IF;
    ELSIF NEW.status='LIFTED' THEN
        IF NOT EXISTS (SELECT 1 FROM audit.audit_event a WHERE a.actor_type='ADMIN' AND a.subject_type='USER'
          AND a.subject_id=NEW.user_id AND a.action='BAN_LIFTED' AND a.occurred_at=NEW.last_command_at
          AND a.occurred_at=NEW.ends_at AND a.payload->>'banInstanceId'=NEW.id::text
          AND NULLIF(BTRIM(a.reason),'') IS NOT NULL)
        THEN RAISE EXCEPTION 'Ban lift requires now-effective audit'; END IF;
    ELSIF NEW.status='CORRECTED' THEN
        IF NOT EXISTS (SELECT 1 FROM audit.audit_event a WHERE a.subject_type='USER'
          AND a.subject_id=NEW.user_id AND a.action='BAN_CORRECTED' AND a.occurred_at=NEW.last_command_at
          AND a.occurred_at=NEW.ends_at AND a.payload->>'banInstanceId'=NEW.id::text
          AND NULLIF(BTRIM(a.reason),'') IS NOT NULL)
        THEN RAISE EXCEPTION 'Ban correction requires now-effective audit'; END IF;
    END IF;
    RETURN NULL;
END;
$function$;

-- P2-02. Projection recomputation time is captured by the database only after
-- serializing on the User guard; caller-supplied future/past values are ignored.
CREATE OR REPLACE FUNCTION trust.guard_trust_projection()
RETURNS trigger LANGUAGE plpgsql AS $function$
DECLARE b trust.ban_instance%ROWTYPE; v_now timestamptz;
BEGIN
    PERFORM 1 FROM iam.user_commitment_guard g WHERE g.user_id=NEW.user_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Trust Projection requires the User commitment guard'; END IF;
    v_now:=clock_timestamp();
    NEW.recomputed_at:=v_now;
    IF TG_OP='UPDATE' AND NEW.user_id IS DISTINCT FROM OLD.user_id THEN RAISE EXCEPTION 'Trust Projection user_id is immutable'; END IF;
    IF (NEW.last_effective_at IS NULL)<>(NEW.last_event_sequence IS NULL) THEN RAISE EXCEPTION 'Projection watermark must be a complete pair'; END IF;
    IF NEW.last_event_sequence IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM trust.trust_event e WHERE e.subject_user_id=NEW.user_id
          AND e.effective_at=NEW.last_effective_at AND e.event_sequence=NEW.last_event_sequence
    ) THEN RAISE EXCEPTION 'Projection watermark must reference an exact same-User event'; END IF;
    IF NEW.active_ban_instance_id IS NOT NULL THEN
        SELECT * INTO b FROM trust.ban_instance WHERE id=NEW.active_ban_instance_id;
        IF NOT FOUND OR b.user_id IS DISTINCT FROM NEW.user_id OR b.status<>'ACTIVE'
           OR NOT (b.activated_at<=v_now AND b.ends_at>v_now) THEN
            RAISE EXCEPTION 'Projection active Ban pointer must be effective at DB recomputation time';
        END IF;
    ELSIF EXISTS (SELECT 1 FROM trust.ban_instance x WHERE x.user_id=NEW.user_id AND x.status='ACTIVE'
                    AND x.activated_at<=v_now AND x.ends_at>v_now) THEN
        RAISE EXCEPTION 'Projection must point to the effective ACTIVE Ban at DB recomputation time';
    END IF;
    RETURN NEW;
END;
$function$;


-- E7GZ PS v1.1.21 - TRUST SHARED-COMMAND / RECONCILIATION CORRECTED
-- Review candidate, not production acceptance. Base: supplied v1.1.20 DBM.
-- ONE logical authoritative command per transaction, READ COMMITTED.
-- Required entry: trust.begin_command(user_id), or tournament.begin_command(...).
-- All statements must use its returned time. Deadline-effective instants remain
-- explicit parameters; do not replace historical boundary instants with wall time.
-- All existing Product enums and penalty durations are retained.


CREATE OR REPLACE FUNCTION tournament.begin_command(
    p_user_ids uuid[],
    p_venue_ids uuid[],
    p_resource_ids uuid[],
    p_tournament_ids uuid[],
    p_new_tournament_ids uuid[] DEFAULT ARRAY[]::uuid[]
)
RETURNS timestamptz
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_users uuid[];
    v_venues uuid[];
    v_resources uuid[];
    v_tournaments uuid[];
    v_new uuid[];
    v_now timestamptz;
    v_grantee record;
    v_bookings uuid[];
    v_bans uuid[];
    v_reservations uuid[];
    v_guard_count integer;
BEGIN
    IF current_setting('transaction_isolation') <> 'read committed' THEN
        RAISE EXCEPTION 'Tournament command requires READ COMMITTED and a post-lock re-read';
    END IF;
    IF to_regclass('pg_temp.e7gz_tournament_command_context') IS NOT NULL THEN
        RAISE EXCEPTION 'Exactly one Tournament command per transaction; commit/rollback before beginning another';
    END IF;
    IF array_position(p_user_ids, NULL) IS NOT NULL
       OR array_position(p_venue_ids, NULL) IS NOT NULL
       OR array_position(p_resource_ids, NULL) IS NOT NULL
       OR array_position(p_tournament_ids, NULL) IS NOT NULL
       OR array_position(p_new_tournament_ids, NULL) IS NOT NULL THEN
        RAISE EXCEPTION 'Command scope arrays must not contain NULL identifiers';
    END IF;

    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[])
      INTO v_tournaments FROM unnest(COALESCE(p_tournament_ids, ARRAY[]::uuid[])) x;
    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[])
      INTO v_new FROM unnest(COALESCE(p_new_tournament_ids, ARRAY[]::uuid[])) x;
    IF v_tournaments && v_new THEN
        RAISE EXCEPTION 'Existing and new Tournament scope must be disjoint';
    END IF;
    IF EXISTS (SELECT 1 FROM tournament.tournament t WHERE t.id = ANY(v_new)) THEN
        RAISE EXCEPTION 'A preallocated new Tournament id already exists';
    END IF;

    -- v1.1.21: discover every live Tournament for explicitly named Trust subjects.
    -- Expansion is NOT recursive through every participant's unrelated Tournaments.
    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[]) INTO v_tournaments
      FROM (
        SELECT unnest(v_tournaments) x
        UNION SELECT t.id FROM tournament.tournament t
          WHERE t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE')
            AND (t.creator_user_id=ANY(COALESCE(p_user_ids,ARRAY[]::uuid[])) OR EXISTS (
              SELECT 1 FROM tournament.tournament_participant p WHERE p.tournament_id=t.id
                AND p.user_id=ANY(COALESCE(p_user_ids,ARRAY[]::uuid[]))))
      ) q;
    -- Discover the lock set, then acquire it in the baseline T10 order:
    -- Users/creators (sorted) -> Venues (sorted) -> Resources (sorted)
    -- -> Tournaments (sorted). Re-read/verify the set BEFORE sampling time.
    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[]) INTO v_users
      FROM (
          SELECT unnest(COALESCE(p_user_ids, ARRAY[]::uuid[])) x
          UNION SELECT t.creator_user_id FROM tournament.tournament t WHERE t.id = ANY(v_tournaments)
          UNION SELECT p.user_id FROM tournament.tournament_participant p WHERE p.tournament_id = ANY(v_tournaments)
      ) q WHERE x IS NOT NULL;
    -- Conservative baseline: include historical bookings for the named users so
    -- Attendance correction never waits on an undiscovered Booking after capture.
    SELECT COALESCE(array_agg(b.id ORDER BY b.id),ARRAY[]::uuid[]) INTO v_bookings
      FROM booking.booking b WHERE b.customer_id=ANY(v_users);
    SELECT COALESCE(array_agg(b.id ORDER BY b.id),ARRAY[]::uuid[]) INTO v_bans
      FROM trust.ban_instance b WHERE b.user_id=ANY(v_users);
    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[]) INTO v_resources
      FROM (
          SELECT unnest(COALESCE(p_resource_ids, ARRAY[]::uuid[])) x
          UNION SELECT r.resource_id FROM tournament.tournament_resource r WHERE r.tournament_id = ANY(v_tournaments)
          UNION SELECT b.resource_id FROM booking.booking b WHERE b.id=ANY(v_bookings)
      ) q WHERE x IS NOT NULL;
    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[]) INTO v_venues
      FROM (
          SELECT unnest(COALESCE(p_venue_ids, ARRAY[]::uuid[])) x
          UNION SELECT t.venue_id FROM tournament.tournament t WHERE t.id = ANY(v_tournaments)
          UNION SELECT b.venue_id FROM booking.booking b WHERE b.id=ANY(v_bookings)
          UNION SELECT r.venue_id FROM resource.resource r WHERE r.id = ANY(v_resources)
      ) q WHERE x IS NOT NULL;

    PERFORM u.id FROM iam.user_account u WHERE u.id = ANY(v_users) ORDER BY u.id FOR UPDATE;
    PERFORM g.user_id FROM iam.user_commitment_guard g
      WHERE g.user_id=ANY(v_users) ORDER BY g.user_id FOR UPDATE;
    SELECT count(*) INTO v_guard_count FROM iam.user_commitment_guard g WHERE g.user_id=ANY(v_users);
    IF v_guard_count<>cardinality(v_users) THEN
      RAISE EXCEPTION 'Every command User requires an initialized user_commitment_guard';
    END IF;
    PERFORM v.id FROM venue.venue v WHERE v.id = ANY(v_venues) ORDER BY v.id FOR UPDATE;
    PERFORM a.id FROM iam.venue_account a WHERE a.venue_id = ANY(v_venues) ORDER BY a.id FOR UPDATE;
    PERFORM r.id FROM resource.resource r WHERE r.id = ANY(v_resources) ORDER BY r.id FOR UPDATE;
    PERFORM t.id FROM tournament.tournament t WHERE t.id = ANY(v_tournaments) ORDER BY t.id FOR UPDATE;

    PERFORM b.id FROM booking.booking b WHERE b.id=ANY(v_bookings) ORDER BY b.id FOR UPDATE;
    PERFORM a.id FROM attendance.attendance_record a WHERE a.booking_id=ANY(v_bookings) ORDER BY a.id FOR UPDATE;
    PERFORM l.id FROM booking.late_confirmation l WHERE l.booking_id=ANY(v_bookings) ORDER BY l.id FOR UPDATE;
    SELECT COALESCE(array_agg(rr.id ORDER BY rr.id),ARRAY[]::uuid[]) INTO v_reservations
      FROM inventory.resource_reservation rr
     WHERE rr.booking_id=ANY(v_bookings) OR rr.tournament_id=ANY(v_tournaments);
    PERFORM rr.id FROM inventory.resource_reservation rr WHERE rr.id=ANY(v_reservations) ORDER BY rr.id FOR UPDATE;
    PERFORM b.id FROM trust.ban_instance b WHERE b.id=ANY(v_bans) ORDER BY b.id FOR UPDATE;
    PERFORM p.user_id FROM trust.trust_projection p WHERE p.user_id=ANY(v_users) ORDER BY p.user_id FOR UPDATE;
    -- If an earlier writer changed discovery while we waited, retry before sampling.
    IF EXISTS (SELECT 1 FROM booking.booking b WHERE b.customer_id=ANY(v_users) AND NOT b.id=ANY(v_bookings))
       OR EXISTS (SELECT 1 FROM trust.ban_instance b WHERE b.user_id=ANY(v_users) AND NOT b.id=ANY(v_bans))
       OR EXISTS (SELECT 1 FROM inventory.resource_reservation rr
          WHERE (rr.booking_id=ANY(v_bookings) OR rr.tournament_id=ANY(v_tournaments)) AND NOT rr.id=ANY(v_reservations))
       OR EXISTS (SELECT 1 FROM tournament.tournament t
          WHERE t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE')
            AND NOT t.id=ANY(v_tournaments)
            AND (t.creator_user_id=ANY(COALESCE(p_user_ids,ARRAY[]::uuid[])) OR EXISTS (
              SELECT 1 FROM tournament.tournament_participant p WHERE p.tournament_id=t.id
                AND p.user_id=ANY(COALESCE(p_user_ids,ARRAY[]::uuid[]))))) THEN
       RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='Shared command scope changed while waiting; retry whole transaction';
    END IF;

    IF (SELECT count(*) FROM iam.user_account u WHERE u.id = ANY(v_users)) <> cardinality(v_users)
       OR (SELECT count(*) FROM venue.venue v WHERE v.id = ANY(v_venues)) <> cardinality(v_venues)
       OR (SELECT count(*) FROM resource.resource r WHERE r.id = ANY(v_resources)) <> cardinality(v_resources)
       OR (SELECT count(*) FROM tournament.tournament t WHERE t.id = ANY(v_tournaments)) <> cardinality(v_tournaments) THEN
        RAISE EXCEPTION 'Command scope contains a missing authoritative row';
    END IF;
    IF EXISTS (
        SELECT 1 FROM tournament.tournament t WHERE t.id = ANY(v_tournaments)
          AND (NOT (t.venue_id = ANY(v_venues))
               OR (t.creator_user_id IS NOT NULL AND NOT (t.creator_user_id = ANY(v_users))))
    ) OR EXISTS (
        SELECT 1 FROM tournament.tournament_participant p
         WHERE p.tournament_id = ANY(v_tournaments) AND NOT (p.user_id = ANY(v_users))
    ) OR EXISTS (
        SELECT 1 FROM tournament.tournament_resource r
         WHERE r.tournament_id = ANY(v_tournaments) AND NOT (r.resource_id = ANY(v_resources))
    ) OR EXISTS (
        SELECT 1 FROM resource.resource r
         WHERE r.id = ANY(v_resources) AND NOT (r.venue_id = ANY(v_venues))
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Tournament lock set changed while waiting; retry the whole transaction';
    END IF;

    CREATE TEMPORARY TABLE e7gz_tournament_command_context (
        singleton boolean PRIMARY KEY CHECK (singleton),
        transaction_id xid8 NOT NULL,
        captured_at timestamptz NOT NULL,
        user_ids uuid[] NOT NULL,
        venue_ids uuid[] NOT NULL,
        resource_ids uuid[] NOT NULL,
        tournament_ids uuid[] NOT NULL,
        new_tournament_ids uuid[] NOT NULL,
        created_tournament_ids uuid[] NOT NULL,
        rejection_outbox_event_ids bigint[] NOT NULL,
        booking_ids uuid[] NOT NULL,
        created_ban_ids uuid[] NOT NULL,
        registry_ban_id uuid,
        registry_mode text
    ) ON COMMIT DROP;
    REVOKE ALL ON TABLE pg_temp.e7gz_tournament_command_context FROM PUBLIC;
    -- Owner default privileges may grant newly-created tables to service/group
    -- roles. Remove those grants as well; PUBLIC-only revocation is insufficient.
    FOR v_grantee IN
        SELECT DISTINCT r.rolname
          FROM pg_catalog.pg_class c
          CROSS JOIN LATERAL pg_catalog.aclexplode(c.relacl) a
          JOIN pg_catalog.pg_roles r ON r.oid=a.grantee
         WHERE c.oid='pg_temp.e7gz_tournament_command_context'::regclass
           AND a.grantee <> c.relowner
    LOOP
        EXECUTE format('REVOKE ALL ON TABLE pg_temp.e7gz_tournament_command_context FROM %I', v_grantee.rolname);
    END LOOP;

    -- The ONLY clock read in the new Tournament command implementation.
    -- All authoritative lock waits above have completed at this point.
    v_now := clock_timestamp();
    INSERT INTO pg_temp.e7gz_tournament_command_context
    VALUES (true, pg_current_xact_id(), v_now, v_users, v_venues, v_resources,
            v_tournaments, v_new, ARRAY[]::uuid[], ARRAY[]::bigint[], v_bookings, ARRAY[]::uuid[], NULL, NULL);
    RETURN v_now;
END;
$function$;


CREATE OR REPLACE FUNCTION trust.begin_command(p_user_id uuid)
RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER
SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF p_user_id IS NULL THEN RAISE EXCEPTION 'Trust command requires a User'; END IF;
 RETURN tournament.begin_command(ARRAY[p_user_id],ARRAY[]::uuid[],ARRAY[]::uuid[],ARRAY[]::uuid[]);
END;
$function$;

CREATE OR REPLACE FUNCTION trust.command_now(p_user_id uuid)
RETURNS timestamptz LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_now timestamptz; c record;
BEGIN
 v_now:=tournament.require_user_tournament_scope(p_user_id);
 SELECT * INTO STRICT c FROM pg_temp.e7gz_tournament_command_context
  WHERE singleton AND transaction_id=pg_current_xact_id();
 IF EXISTS(SELECT 1 FROM booking.booking b WHERE b.customer_id=p_user_id AND NOT b.id=ANY(c.booking_ids)) THEN
   RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='Trust command has an unprelocked Booking; begin again with full scope';
 END IF;
 RETURN v_now;
END;
$function$;

-- Stable original attendance identity avoids punishing an equivalent replacement
-- correction twice. Stage is part of a qualification revision, not an input enum.
CREATE OR REPLACE FUNCTION trust.qualification_anchor(p_event_id uuid)
RETURNS uuid LANGUAGE sql STABLE STRICT SECURITY DEFINER
SET search_path=pg_catalog,pg_temp AS $function$
 SELECT COALESCE(e.original_outcome_event_id,e.id) FROM trust.trust_event e WHERE e.id=p_event_id
$function$;

CREATE OR REPLACE FUNCTION trust.current_qualifications(p_user_id uuid)
RETURNS TABLE(effect_event_id uuid,anchor_id uuid,effective_at timestamptz,event_sequence bigint,qualification_stage smallint)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
 SELECT t.effect_event_id,trust.qualification_anchor(t.effect_event_id),t.effective_at,t.event_sequence,t.qualification_stage
 FROM trust.replay_timeline(p_user_id) t WHERE t.qualification_stage IS NOT NULL
$function$;

-- A retroactive correction can change a crossing stage for the same source
-- event. Keep the old immutable qualification; materialize a distinct revision.
ALTER TABLE trust.ban_qualification DROP CONSTRAINT IF EXISTS uq_ban_qualification_trigger;
ALTER TABLE trust.ban_qualification ADD CONSTRAINT uq_ban_qualification_trigger
 UNIQUE(triggering_event_id,penalty_stage);


CREATE OR REPLACE FUNCTION trust.prepare_trust_event_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    b booking.booking%ROWTYPE;
    v_counter integer;
    v_stage smallint;
BEGIN
    -- Shared context must already have acquired ALL locks before this trigger.
    IF NEW.occurred_at IS DISTINCT FROM trust.command_now(NEW.subject_user_id) THEN
        RAISE EXCEPTION 'Trust occurred_at must equal the shared DB command instant';
    END IF;

    NEW.event_sequence := nextval('trust.trust_event_sequence_seq'::regclass);
    NEW.payload := COALESCE(NEW.payload, '{}'::jsonb);
    IF jsonb_typeof(NEW.payload) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'Trust event payload must be a JSON object';
    END IF;
    IF NEW.occurred_at < NEW.effective_at THEN
        RAISE EXCEPTION 'Trust event occurred_at cannot predate effective_at';
    END IF;

    IF NEW.event_type IN (
        'BOOKING_ATTENDED','BOOKING_ATTENDANCE_UNCONFIRMED',
        'BOOKING_ATTENDED_INTERRUPTED','BOOKING_NO_SHOW'
    ) THEN
        SELECT * INTO b FROM booking.booking WHERE id = NEW.booking_id;
        IF NOT FOUND OR b.source <> 'ONLINE' OR b.customer_id IS NULL THEN
            RAISE EXCEPTION '% requires an Online customer Booking', NEW.event_type;
        END IF;
        IF NEW.subject_user_id IS DISTINCT FROM b.customer_id THEN
            RAISE EXCEPTION '% subject_user_id must equal Booking customer_id', NEW.event_type;
        END IF;
        IF NEW.effective_at IS DISTINCT FROM b.start_at THEN
            RAISE EXCEPTION '% effective_at must equal booking.start_at', NEW.event_type;
        END IF;
    ELSIF NEW.event_type IN (
        'ADMIN_TRUST_ADJUSTMENT','VERIFIED_PLAYER_SUSPENDED',
        'VERIFIED_PLAYER_REVOKED','VERIFIED_PLAYER_RESTORED'
    ) THEN
        IF NEW.effective_at IS DISTINCT FROM NEW.occurred_at THEN
            RAISE EXCEPTION '% effective_at must equal occurred_at', NEW.event_type;
        END IF;
        IF NOT (NEW.payload ? 'adminId') OR NOT (NEW.payload ? 'correlationId') THEN
            RAISE EXCEPTION '% payload requires adminId and correlationId', NEW.event_type;
        END IF;
        BEGIN
            PERFORM (NEW.payload->>'adminId')::uuid;
            PERFORM (NEW.payload->>'correlationId')::uuid;
        EXCEPTION WHEN invalid_text_representation THEN
            RAISE EXCEPTION '% payload adminId/correlationId must be UUID values', NEW.event_type;
        END;
    END IF;

    IF NEW.event_type = 'ADMIN_TRUST_ADJUSTMENT' THEN
        IF (SELECT count(*) FROM jsonb_object_keys(NEW.payload)) <> 5
           OR NOT (NEW.payload ?& ARRAY[
               'schemaVersion','counterAfter','penaltyStageAfter','adminId','correlationId'
           ])
           OR jsonb_typeof(NEW.payload->'schemaVersion') IS DISTINCT FROM 'number'
           OR jsonb_typeof(NEW.payload->'counterAfter') IS DISTINCT FROM 'number'
           OR jsonb_typeof(NEW.payload->'penaltyStageAfter') IS DISTINCT FROM 'number'
           OR (NEW.payload->>'schemaVersion') !~ '^1$'
           OR (NEW.payload->>'counterAfter') !~ '^[0-9]+$'
           OR (NEW.payload->>'penaltyStageAfter') !~ '^[0-3]$' THEN
            RAISE EXCEPTION 'ADMIN_TRUST_ADJUSTMENT payload must match the exact version-1 absolute schema';
        END IF;
        v_counter := (NEW.payload->>'counterAfter')::integer;
        v_stage := (NEW.payload->>'penaltyStageAfter')::smallint;
        IF v_counter >= trust.penalty_threshold(v_stage) THEN
            RAISE EXCEPTION 'ADMIN_TRUST_ADJUSTMENT counterAfter must be below the resulting stage threshold';
        END IF;
    END IF;
    IF NEW.event_type='ATTENDANCE_CORRECTED' AND NEW.corrected_outcome IS NULL THEN
        RAISE EXCEPTION 'ATTENDANCE_CORRECTED requires a non-null corrected_outcome';
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION trust.guard_ban_qualification()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE e trust.trust_event%ROWTYPE;
BEGIN
    PERFORM trust.command_now(NEW.user_id);
    IF TG_OP = 'UPDATE' THEN
        IF NEW IS DISTINCT FROM OLD THEN
            RAISE EXCEPTION 'Ban Qualification is immutable derived history';
        END IF;
        RETURN NEW;
    END IF;
    SELECT * INTO e FROM trust.trust_event WHERE id = NEW.triggering_event_id;
    IF NOT FOUND OR e.subject_user_id IS DISTINCT FROM NEW.user_id
       OR e.effective_at IS DISTINCT FROM NEW.qualification_at THEN
        RAISE EXCEPTION 'Ban Qualification must match its Trust event User/effective position';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM trust.replay_timeline(NEW.user_id) t
         WHERE t.effect_event_id = NEW.triggering_event_id
           AND t.effective_at = NEW.qualification_at
           AND t.qualification_stage = NEW.penalty_stage
    ) THEN
        RAISE EXCEPTION 'Ban Qualification must be an authentic canonical replay threshold crossing';
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION trust.guard_ban_instance()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    q trust.ban_qualification%ROWTYPE;
    old_q trust.ban_qualification%ROWTYPE;
    v_now timestamptz;
    v_stage_duration interval;
    v_expected_end timestamptz;
    v_lifecycle_change boolean := false;
BEGIN
    v_now := trust.command_now(NEW.user_id);

    IF TG_OP='INSERT' THEN
        SELECT * INTO STRICT q FROM trust.ban_qualification WHERE id=NEW.qualification_id;
        IF q.user_id IS DISTINCT FROM NEW.user_id OR NOT EXISTS (
            SELECT 1 FROM trust.replay_timeline(q.user_id) t
             WHERE trust.qualification_anchor(t.effect_event_id)=trust.qualification_anchor(q.triggering_event_id) AND t.effective_at=q.qualification_at
               AND t.qualification_stage=q.penalty_stage
        ) OR EXISTS (
            SELECT 1 FROM trust.ban_qualification_consumption c JOIN trust.ban_qualification usedq ON usedq.id=c.qualification_id
            WHERE c.qualification_id=q.id OR (usedq.user_id=q.user_id AND usedq.penalty_stage=q.penalty_stage
              AND trust.qualification_anchor(usedq.triggering_event_id)=trust.qualification_anchor(q.triggering_event_id))
        ) THEN RAISE EXCEPTION 'Initial Ban Qualification must be current-replay-valid and unused'; END IF;
        IF NEW.status<>'ACTIVE' THEN RAISE EXCEPTION 'A Ban Instance is created ACTIVE'; END IF;
        PERFORM trust.require_next_qualification(q.id);
        v_stage_duration := trust.penalty_duration(q.penalty_stage);
        IF v_stage_duration IS NULL THEN RAISE EXCEPTION 'Invalid frozen Ban stage'; END IF;
        NEW.latest_qualification_id := q.id;
        NEW.penalty_stage := q.penalty_stage;
        NEW.activated_at := v_now;
        NEW.last_command_at := v_now;
        NEW.duration := v_stage_duration;
        NEW.ends_at := v_now+v_stage_duration;
        IF NEW.cascade_executed_at IS NOT NULL THEN RAISE EXCEPTION 'New Ban has not executed its cascade'; END IF;
        NEW.cascade_targets_registered_at := NULL;
        RETURN NEW;
    END IF;

    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.user_id IS DISTINCT FROM OLD.user_id
       OR NEW.qualification_id IS DISTINCT FROM OLD.qualification_id
       OR NEW.activated_at IS DISTINCT FROM OLD.activated_at
       OR NEW.activation_reason IS DISTINCT FROM OLD.activation_reason THEN
        RAISE EXCEPTION 'Ban identity, initial qualification and activation facts are immutable';
    END IF;
    IF OLD.status<>'ACTIVE' THEN
        IF NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'Terminal Ban Instance is immutable'; END IF;
        RETURN NEW;
    END IF;
    IF OLD.cascade_executed_at IS NOT NULL AND NEW.cascade_executed_at IS DISTINCT FROM OLD.cascade_executed_at THEN
        RAISE EXCEPTION 'Ban cascade marker is immutable once recorded';
    END IF;
    IF OLD.cascade_targets_registered_at IS NOT NULL
       AND NEW.cascade_targets_registered_at IS DISTINCT FROM OLD.cascade_targets_registered_at THEN
        RAISE EXCEPTION 'Ban exact-target registration marker is immutable once recorded';
    END IF;

    IF NEW.cascade_targets_registered_at IS DISTINCT FROM OLD.cascade_targets_registered_at
       AND NOT trust.registry_write_allowed(NEW.id,'REGISTER') THEN
        RAISE EXCEPTION 'Target-registration marker is written only by register_ban_cascade_targets';
    END IF;
    IF NEW.cascade_executed_at IS DISTINCT FROM OLD.cascade_executed_at
       AND NOT trust.registry_write_allowed(NEW.id,'COMPLETE') THEN
        RAISE EXCEPTION 'Cascade-completion marker is written only by complete_ban_cascade';
    END IF;
    -- Technical marker updates remain part of the original activation command.
    IF NEW.status IS NOT DISTINCT FROM OLD.status
       AND NEW.latest_qualification_id IS NOT DISTINCT FROM OLD.latest_qualification_id
       AND NEW.penalty_stage IS NOT DISTINCT FROM OLD.penalty_stage
       AND NEW.ends_at IS NOT DISTINCT FROM OLD.ends_at
       AND NEW.duration IS NOT DISTINCT FROM OLD.duration THEN
        NEW.last_command_at := OLD.last_command_at;
        RETURN NEW;
    END IF;

    -- Natural end owns the old interval; do NOT resurrect it across an unbanned gap.
    IF OLD.ends_at<=v_now AND NEW.status<>'EXPIRED' THEN
        RAISE EXCEPTION 'Due Ban expiry must be reconciled before another lifecycle action';
    END IF;
    IF NEW.status='ACTIVE' AND NEW.latest_qualification_id IS DISTINCT FROM OLD.latest_qualification_id THEN
        SELECT * INTO STRICT q FROM trust.ban_qualification WHERE id=NEW.latest_qualification_id;
        SELECT * INTO STRICT old_q FROM trust.ban_qualification WHERE id=OLD.latest_qualification_id;
        IF q.user_id IS DISTINCT FROM NEW.user_id OR EXISTS (
            SELECT 1 FROM trust.ban_qualification_consumption c JOIN trust.ban_qualification usedq ON usedq.id=c.qualification_id
            WHERE c.qualification_id=q.id OR (usedq.user_id=q.user_id AND usedq.penalty_stage=q.penalty_stage
              AND trust.qualification_anchor(usedq.triggering_event_id)=trust.qualification_anchor(q.triggering_event_id))
        ) OR NOT EXISTS (
            SELECT 1 FROM trust.replay_timeline(q.user_id) t
             WHERE trust.qualification_anchor(t.effect_event_id)=trust.qualification_anchor(q.triggering_event_id) AND t.effective_at=q.qualification_at
               AND t.qualification_stage=q.penalty_stage
        ) THEN RAISE EXCEPTION 'Extension Qualification must be current-replay-valid and unused'; END IF;
        IF q.penalty_stage IS DISTINCT FROM NEW.penalty_stage THEN RAISE EXCEPTION 'Extension stage must equal current corrected replay qualification'; END IF;
        PERFORM trust.require_next_qualification(q.id);
        v_stage_duration := trust.penalty_duration(q.penalty_stage);
        v_expected_end := GREATEST(OLD.ends_at,v_now+v_stage_duration);
        NEW.ends_at := v_expected_end;
        NEW.last_command_at := v_now;
        NEW.duration := NEW.ends_at-NEW.activated_at;
    ELSIF NEW.status='ACTIVE' AND NEW.ends_at<OLD.ends_at THEN
        IF NEW.latest_qualification_id IS DISTINCT FROM OLD.latest_qualification_id
           OR NEW.penalty_stage IS DISTINCT FROM OLD.penalty_stage OR NEW.ends_at<=v_now THEN
            RAISE EXCEPTION 'Ban shortening cannot rewrite qualification/stage or backdate the operational end';
        END IF;
        NEW.last_command_at := v_now;
        NEW.duration := NEW.ends_at-NEW.activated_at;
    ELSIF NEW.status='EXPIRED' THEN
        IF v_now<OLD.ends_at THEN RAISE EXCEPTION 'ACTIVE Ban cannot expire before ends_at at post-lock wall-clock time'; END IF;
        IF NEW.latest_qualification_id IS DISTINCT FROM OLD.latest_qualification_id
           OR NEW.penalty_stage IS DISTINCT FROM OLD.penalty_stage
           OR NEW.ends_at IS DISTINCT FROM OLD.ends_at OR NEW.duration IS DISTINCT FROM OLD.duration THEN
            RAISE EXCEPTION 'Natural expiry may not rewrite Ban history';
        END IF;
        NEW.last_command_at := v_now;
    ELSIF NEW.status IN ('LIFTED','CORRECTED') THEN
        IF v_now>=OLD.ends_at THEN RAISE EXCEPTION 'Ended Ban must use natural EXPIRED transition, not lift/correction'; END IF;
        IF NEW.latest_qualification_id IS DISTINCT FROM OLD.latest_qualification_id
           OR NEW.penalty_stage IS DISTINCT FROM OLD.penalty_stage THEN
            RAISE EXCEPTION 'Lift/correction may not rewrite qualification or stage';
        END IF;
        NEW.last_command_at := v_now;
        NEW.ends_at := v_now;
        NEW.duration := NEW.ends_at-NEW.activated_at;
    ELSE
        RAISE EXCEPTION 'Invalid Ban Instance lifecycle transition';
    END IF;

    IF NEW.duration<=interval '0' OR NEW.ends_at<=NEW.activated_at
       OR NEW.ends_at IS DISTINCT FROM NEW.activated_at+NEW.duration THEN
        RAISE EXCEPTION 'Ban duration/time arithmetic is invalid';
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION trust.guard_ban_qualification_consumption()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    b trust.ban_instance%ROWTYPE;
    q trust.ban_qualification%ROWTYPE;
BEGIN
    IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'Ban Qualification consumption is append-only'; END IF;
    SELECT * INTO STRICT b FROM trust.ban_instance WHERE id=NEW.ban_instance_id;
    PERFORM trust.command_now(b.user_id);
    SELECT * INTO STRICT q FROM trust.ban_qualification WHERE id=NEW.qualification_id;
    IF q.user_id IS DISTINCT FROM b.user_id OR NOT EXISTS (
        SELECT 1 FROM trust.replay_timeline(q.user_id) t
         WHERE trust.qualification_anchor(t.effect_event_id)=trust.qualification_anchor(q.triggering_event_id)
           AND t.effective_at=q.qualification_at
           AND t.qualification_stage=q.penalty_stage
    ) THEN
        RAISE EXCEPTION 'Consumed Ban Qualification must remain valid in current corrected replay';
    END IF;
    IF EXISTS (SELECT 1 FROM trust.ban_qualification_consumption used
      JOIN trust.ban_qualification uq ON uq.id=used.qualification_id
      WHERE uq.user_id=q.user_id AND uq.penalty_stage=q.penalty_stage
        AND trust.qualification_anchor(uq.triggering_event_id)=trust.qualification_anchor(q.triggering_event_id)) THEN
      RAISE EXCEPTION 'This logical qualification/stage has already been consumed';
    END IF;
    IF NEW.consumed_at IS DISTINCT FROM trust.command_now(b.user_id) THEN
      RAISE EXCEPTION 'Qualification consumption belongs to the shared command instant';
    END IF;
    IF NEW.consequence_type='CREATE' THEN
        IF NEW.qualification_id IS DISTINCT FROM b.qualification_id
           OR b.latest_qualification_id IS DISTINCT FROM b.qualification_id
           OR NEW.consumed_at IS DISTINCT FROM b.activated_at THEN
            RAISE EXCEPTION 'CREATE consumption must bind the immutable initial qualification and activation time';
        END IF;
    ELSE
        IF NEW.qualification_id IS DISTINCT FROM b.latest_qualification_id
           OR NEW.qualification_id IS NOT DISTINCT FROM b.qualification_id
           OR NEW.consumed_at IS DISTINCT FROM b.last_command_at THEN
            RAISE EXCEPTION 'EXTEND consumption must bind the latest non-initial qualification and post-lock command time';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION trust.guard_verified_player_transition()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE prev trust.verified_player_transition%ROWTYPE;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF NEW.id IS DISTINCT FROM OLD.id
           OR NEW.user_id IS DISTINCT FROM OLD.user_id
           OR NEW.transition_id IS DISTINCT FROM OLD.transition_id
           OR NEW.from_status IS DISTINCT FROM OLD.from_status
           OR NEW.to_status IS DISTINCT FROM OLD.to_status
           OR NEW.occurred_at IS DISTINCT FROM OLD.occurred_at
           OR NEW.cause IS DISTINCT FROM OLD.cause
           OR NEW.admin_id IS DISTINCT FROM OLD.admin_id THEN
            RAISE EXCEPTION 'Verified Player transition identity/facts are immutable';
        END IF;
        IF OLD.cascade_executed_at IS NOT NULL
           AND NEW.cascade_executed_at IS DISTINCT FROM OLD.cascade_executed_at THEN
            RAISE EXCEPTION 'Verified Player cascade_executed_at is immutable once recorded';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.occurred_at IS DISTINCT FROM trust.command_now(NEW.user_id) THEN
        RAISE EXCEPTION 'Verified Player transition must use the shared command instant';
    END IF;

    IF NEW.from_status = NEW.to_status THEN
        RAISE EXCEPTION 'Verified Player transition must change operational status';
    END IF;
    IF NEW.cause = 'ADMIN' AND NEW.admin_id IS NULL THEN
        RAISE EXCEPTION 'Admin Verified Player transition requires admin_id';
    ELSIF NEW.cause <> 'ADMIN' AND NEW.admin_id IS NOT NULL THEN
        RAISE EXCEPTION 'Non-Admin Verified Player transition may not carry admin_id';
    END IF;

    SELECT * INTO prev
      FROM trust.verified_player_transition v
     WHERE v.user_id = NEW.user_id
     ORDER BY v.occurred_at DESC, v.id DESC
     LIMIT 1;
    IF FOUND THEN
        IF prev.to_status IS DISTINCT FROM NEW.from_status THEN
            RAISE EXCEPTION 'Verified Player transition chain must continue from the latest operational status';
        END IF;
        IF NEW.occurred_at <= prev.occurred_at THEN
            RAISE EXCEPTION 'Verified Player transition occurred_at must advance strictly for deterministic operational history';
        END IF;
    ELSIF NEW.from_status <> 'NOT_VERIFIED' THEN
        RAISE EXCEPTION 'First Verified Player transition must start from NOT_VERIFIED';
    END IF;

    IF NEW.cause = 'TRUST_QUALIFICATION' THEN
        IF NEW.from_status <> 'NOT_VERIFIED' OR NEW.to_status <> 'VERIFIED' THEN
            RAISE EXCEPTION 'TRUST_QUALIFICATION is only the normal first NOT_VERIFIED to VERIFIED activation';
        END IF;
    ELSIF NEW.cause = 'TRUST_CORRECTION' THEN
        IF NOT (
            (NEW.from_status = 'NOT_VERIFIED' AND NEW.to_status = 'VERIFIED')
            OR (NEW.from_status = 'VERIFIED' AND NEW.to_status = 'REVOKED')
            OR (NEW.from_status = 'REVOKED' AND NEW.to_status = 'VERIFIED')
        ) THEN
            RAISE EXCEPTION 'Invalid TRUST_CORRECTION Verified Player transition';
        END IF;
        IF NEW.from_status = 'REVOKED' AND NEW.to_status = 'VERIFIED'
           AND (NOT FOUND OR prev.cause <> 'TRUST_CORRECTION' OR prev.to_status <> 'REVOKED') THEN
            RAISE EXCEPTION 'Automatic Verified Player regain is allowed only after TRUST_CORRECTION revocation';
        END IF;
    ELSIF NEW.cause = 'ADMIN' THEN
        IF NOT (
            (NEW.from_status = 'VERIFIED' AND NEW.to_status IN ('SUSPENDED','REVOKED'))
            OR (NEW.from_status = 'SUSPENDED' AND NEW.to_status IN ('VERIFIED','NOT_VERIFIED'))
            OR (NEW.from_status = 'REVOKED' AND NEW.to_status IN ('VERIFIED','NOT_VERIFIED'))
        ) THEN
            RAISE EXCEPTION 'Invalid ADMIN Verified Player transition';
        END IF;
    END IF;

    IF NEW.to_status <> 'REVOKED' AND NEW.cascade_executed_at IS NOT NULL THEN
        RAISE EXCEPTION 'Only REVOKED transition may record a Tournament cancellation cascade';
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION trust.guard_trust_projection()
RETURNS trigger LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp AS $function$
DECLARE b trust.ban_instance%ROWTYPE; v_now timestamptz;
BEGIN
    v_now:=trust.command_now(NEW.user_id);
    NEW.recomputed_at:=v_now;
    IF TG_OP='UPDATE' AND NEW.user_id IS DISTINCT FROM OLD.user_id THEN RAISE EXCEPTION 'Trust Projection user_id is immutable'; END IF;
    IF (NEW.last_effective_at IS NULL)<>(NEW.last_event_sequence IS NULL) THEN RAISE EXCEPTION 'Projection watermark must be a complete pair'; END IF;
    IF NEW.last_event_sequence IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM trust.trust_event e WHERE e.subject_user_id=NEW.user_id
          AND e.effective_at=NEW.last_effective_at AND e.event_sequence=NEW.last_event_sequence
    ) THEN RAISE EXCEPTION 'Projection watermark must reference an exact same-User event'; END IF;
    IF NEW.active_ban_instance_id IS NOT NULL THEN
        SELECT * INTO b FROM trust.ban_instance WHERE id=NEW.active_ban_instance_id;
        IF NOT FOUND OR b.user_id IS DISTINCT FROM NEW.user_id OR b.status<>'ACTIVE'
           OR NOT (b.activated_at<=v_now AND b.ends_at>v_now) THEN
            RAISE EXCEPTION 'Projection active Ban pointer must be effective at DB recomputation time';
        END IF;
    ELSIF EXISTS (SELECT 1 FROM trust.ban_instance x WHERE x.user_id=NEW.user_id AND x.status='ACTIVE'
                    AND x.activated_at<=v_now AND x.ends_at>v_now) THEN
        RAISE EXCEPTION 'Projection must point to the effective ACTIVE Ban at DB recomputation time';
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION trust.guard_booking_ban_eligibility()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE v_now timestamptz;
BEGIN
    IF NEW.source <> 'ONLINE' OR NEW.customer_id IS NULL THEN
        RETURN NEW;
    END IF;
    IF TG_OP = 'UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status THEN
        RETURN NEW;
    END IF;
    IF NEW.status NOT IN ('PENDING','AWAITING_CUSTOMER_CONFIRMATION','CONFIRMED','ACTIVE') THEN
        RETURN NEW;
    END IF;

    PERFORM 1 FROM iam.user_commitment_guard g WHERE g.user_id = NEW.customer_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Online Booking commitment requires the Customer commitment guard';
    END IF;
    IF to_regclass('pg_temp.e7gz_tournament_command_context') IS NOT NULL THEN
        v_now:=trust.command_now(NEW.customer_id);
    ELSE
        -- Booking-only writer: it must obey its existing root-lock contract.
        v_now:=clock_timestamp();
    END IF;
    IF EXISTS (
        SELECT 1 FROM trust.ban_instance b
         WHERE b.user_id = NEW.customer_id
           AND b.status = 'ACTIVE'
           AND b.activated_at <= v_now
           AND b.ends_at > v_now
    ) THEN
        RAISE EXCEPTION 'Banned User may not create or strengthen an Online Booking commitment';
    END IF;
    RETURN NEW;
END;
$function$;

-- AR20-06: registration and completion markers are private producer operations.
CREATE OR REPLACE FUNCTION trust.registry_write_allowed(p_ban_id uuid,p_mode text)
RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_allowed boolean;
BEGIN
 PERFORM tournament.command_now();
 SELECT c.registry_ban_id=p_ban_id AND c.registry_mode=p_mode INTO v_allowed
 FROM pg_temp.e7gz_tournament_command_context c WHERE c.singleton AND c.transaction_id=pg_current_xact_id();
 RETURN COALESCE(v_allowed,false);
END;
$function$;

CREATE OR REPLACE FUNCTION trust.capture_created_ban()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 PERFORM trust.command_now(NEW.user_id);
 UPDATE pg_temp.e7gz_tournament_command_context
 SET created_ban_ids=array_append(created_ban_ids,NEW.id) WHERE singleton;
 RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_00_capture_created_ban ON trust.ban_instance;
CREATE TRIGGER tr_00_capture_created_ban AFTER INSERT ON trust.ban_instance
FOR EACH ROW EXECUTE FUNCTION trust.capture_created_ban();

CREATE OR REPLACE FUNCTION trust.register_ban_cascade_targets(p_ban_id uuid,p_correlation_id uuid)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE b trust.ban_instance%ROWTYPE; v_count integer; v_now timestamptz;
BEGIN
 SELECT * INTO STRICT b FROM trust.ban_instance WHERE id=p_ban_id;
 v_now:=trust.command_now(b.user_id);
 IF p_correlation_id IS NULL OR b.status<>'ACTIVE' OR b.activated_at IS DISTINCT FROM v_now
    OR b.cascade_executed_at IS NOT NULL OR b.cascade_targets_registered_at IS NOT NULL
    OR NOT EXISTS (SELECT 1 FROM pg_temp.e7gz_tournament_command_context c
       WHERE c.singleton AND b.id=ANY(c.created_ban_ids)) THEN
    RAISE EXCEPTION 'Only a newly created current-command Ban can register targets once';
 END IF;
 UPDATE pg_temp.e7gz_tournament_command_context SET registry_ban_id=b.id,registry_mode='REGISTER' WHERE singleton;
 INSERT INTO trust.ban_cascade_booking_target(ban_instance_id,booking_id,from_status,registered_at,correlation_id)
 SELECT b.id,x.id,x.status,v_now,p_correlation_id FROM booking.booking x
 WHERE x.source='ONLINE' AND x.customer_id=b.user_id
   AND (x.status IN ('PENDING','AWAITING_CUSTOMER_CONFIRMATION') OR (x.status='CONFIRMED' AND x.start_at>v_now));
 GET DIAGNOSTICS v_count=ROW_COUNT;
 INSERT INTO trust.ban_cascade_reservation_target(ban_instance_id,reservation_id,booking_id,registered_at)
 SELECT b.id,rr.id,rr.booking_id,v_now FROM inventory.resource_reservation rr
 JOIN trust.ban_cascade_booking_target t ON t.ban_instance_id=b.id AND t.booking_id=rr.booking_id
 WHERE rr.active_flag AND rr.reservation_type IN ('BOOKING','LATE_CONFIRM_HOLD');
 UPDATE trust.ban_instance SET cascade_targets_registered_at=v_now WHERE id=b.id;
 UPDATE pg_temp.e7gz_tournament_command_context SET registry_ban_id=NULL,registry_mode=NULL WHERE singleton;
 RETURN v_count;
END;
$function$;

-- Validate the obligation created by activation, even when final status is terminal.
-- require_marker=false is private to the completion producer before it sets marker.
CREATE OR REPLACE FUNCTION trust.assert_ban_target_completion(p_ban_id uuid,p_require_marker boolean DEFAULT true)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE b trust.ban_instance%ROWTYPE; ce trust.cascade_execution%ROWTYPE;
BEGIN
 SELECT * INTO STRICT b FROM trust.ban_instance WHERE id=p_ban_id;
 SELECT * INTO ce FROM trust.cascade_execution x WHERE x.cascade_type='BAN' AND x.source_id=b.id;
 IF NOT FOUND OR ce.subject_user_id IS DISTINCT FROM b.user_id
    OR b.cascade_targets_registered_at IS DISTINCT FROM b.activated_at
    OR ce.executed_at IS DISTINCT FROM b.activated_at
    OR (p_require_marker AND b.cascade_executed_at IS DISTINCT FROM b.activated_at) THEN
   RAISE EXCEPTION 'Every Ban activation requires registered and completed exact cascade proof';
 END IF;
 IF EXISTS (
   SELECT 1 FROM trust.ban_cascade_booking_target t
   JOIN booking.booking bk ON bk.id=t.booking_id
   WHERE t.ban_instance_id=b.id AND (
    t.registered_at IS DISTINCT FROM b.activated_at OR t.correlation_id IS DISTINCT FROM ce.correlation_id
    OR bk.status<>'CANCELLED' OR bk.terminal_reason IS DISTINCT FROM 'USER_BANNED'
    OR (SELECT count(*) FROM booking.booking_history h WHERE h.booking_id=t.booking_id
        AND h.occurred_at=b.activated_at AND h.from_status=t.from_status
        AND h.to_status='CANCELLED' AND h.terminal_reason='USER_BANNED'
        AND h.correlation_id=t.correlation_id)<>1
   )) THEN RAISE EXCEPTION 'Captured Ban targets must each have exactly one matching USER_BANNED transition'; END IF;
 IF EXISTS (
   SELECT 1 FROM booking.booking_history h JOIN booking.booking bk ON bk.id=h.booking_id
   WHERE bk.customer_id=b.user_id AND h.occurred_at=b.activated_at AND h.to_status='CANCELLED'
     AND h.terminal_reason='USER_BANNED' AND h.correlation_id=ce.correlation_id
     AND NOT EXISTS(SELECT 1 FROM trust.ban_cascade_booking_target t
        WHERE t.ban_instance_id=b.id AND t.booking_id=bk.id)
 ) THEN RAISE EXCEPTION 'Actual Ban transition set exceeds captured target set'; END IF;
 IF EXISTS (
   SELECT 1 FROM trust.ban_cascade_reservation_target t
   JOIN inventory.resource_reservation rr ON rr.id=t.reservation_id
   WHERE t.ban_instance_id=b.id AND (rr.booking_id IS DISTINCT FROM t.booking_id OR rr.active_flag
     OR rr.actual_reservation_release_at IS DISTINCT FROM b.activated_at)
 ) THEN RAISE EXCEPTION 'Captured Holds must be released at the shared activation instant'; END IF;
 IF EXISTS (
   SELECT 1 FROM trust.ban_cascade_booking_target t JOIN booking.late_confirmation lc ON lc.booking_id=t.booking_id
   WHERE t.ban_instance_id=b.id AND t.from_status='AWAITING_CUSTOMER_CONFIRMATION' AND lc.closed_at IS NULL
 ) THEN RAISE EXCEPTION 'Captured Late Confirmation attempts must be closed'; END IF;
 -- During activation, current live rows are a completeness cross-check. During
 -- a later lift/expiry, bookings legitimately created after natural end are not targets.
 IF b.activated_at=trust.command_now(b.user_id) AND EXISTS (
   SELECT 1 FROM booking.booking bk WHERE bk.source='ONLINE' AND bk.customer_id=b.user_id
   AND (bk.status IN ('PENDING','AWAITING_CUSTOMER_CONFIRMATION')
       OR (bk.status='CONFIRMED' AND bk.start_at>b.activated_at))
 ) THEN RAISE EXCEPTION 'Activation left an affected Booking live'; END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION trust.complete_ban_cascade(p_ban_id uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE b trust.ban_instance%ROWTYPE; v_now timestamptz;
BEGIN
 SELECT * INTO STRICT b FROM trust.ban_instance WHERE id=p_ban_id;
 v_now:=trust.command_now(b.user_id);
 IF b.activated_at IS DISTINCT FROM v_now OR b.cascade_executed_at IS NOT NULL
    OR NOT EXISTS(SELECT 1 FROM pg_temp.e7gz_tournament_command_context c
      WHERE c.singleton AND b.id=ANY(c.created_ban_ids)) THEN
    RAISE EXCEPTION 'Only this command can complete its new Ban cascade once';
 END IF;
 PERFORM trust.assert_ban_target_completion(b.id,false);
 UPDATE pg_temp.e7gz_tournament_command_context SET registry_ban_id=b.id,registry_mode='COMPLETE' WHERE singleton;
 UPDATE trust.ban_instance SET cascade_executed_at=v_now WHERE id=b.id;
 UPDATE pg_temp.e7gz_tournament_command_context SET registry_ban_id=NULL,registry_mode=NULL WHERE singleton;
END;
$function$;

CREATE OR REPLACE FUNCTION trust.assert_ban_booking_cascade()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 -- NEVER skip because the final state is LIFTED/CORRECTED/EXPIRED.
 PERFORM trust.assert_ban_target_completion(NEW.id,true);
 RETURN NULL;
END;
$function$;

-- AR20-03 / AR20-04: the final committed User aggregate, not just event watermark.
CREATE OR REPLACE FUNCTION trust.assert_user_integrity(p_user_id uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE
 p trust.trust_projection%ROWTYPE; r record; vp trust.verified_player_transition%ROWTYPE;
 cq record; b trust.ban_instance%ROWTYPE; v_now timestamptz; v_valid_until timestamptz;
 v_status text; v_cause text; v_has_transition boolean;
BEGIN
 v_now:=trust.command_now(p_user_id);
 SELECT * INTO p FROM trust.trust_projection WHERE user_id=p_user_id;
 IF NOT FOUND THEN
   IF EXISTS(SELECT 1 FROM trust.trust_event e WHERE e.subject_user_id=p_user_id)
      OR EXISTS(SELECT 1 FROM trust.verified_player_transition x WHERE x.user_id=p_user_id)
      OR EXISTS(SELECT 1 FROM trust.ban_instance x WHERE x.user_id=p_user_id) THEN
      RAISE EXCEPTION 'Trust state requires its final projection';
   END IF;
   RETURN;
 END IF;
 SELECT * INTO STRICT r FROM trust.replay_state(p_user_id);
 IF p.last_effective_at IS DISTINCT FROM r.last_effective_at
    OR p.last_event_sequence IS DISTINCT FROM r.last_event_sequence
    OR p.consecutive_no_shows IS DISTINCT FROM r.consecutive_no_shows
    OR p.penalty_stage IS DISTINCT FROM r.penalty_stage
    OR p.current_threshold IS DISTINCT FROM r.current_threshold
    OR p.completed_attended_count IS DISTINCT FROM r.completed_attended_count
    OR p.vp_qualification IS DISTINCT FROM r.vp_qualification THEN
    RAISE EXCEPTION 'Every projection write must equal final canonical replay values';
 END IF;
 -- A direct DELETE of projection cannot erase enforcement; trigger covers OLD user.
 -- Existing unchanged projections can be read without changing historical timestamps.
 IF p.recomputed_at IS NULL OR EXISTS(SELECT 1 FROM trust.trust_event e
    WHERE e.subject_user_id=p_user_id AND e.occurred_at>p.recomputed_at) THEN
    RAISE EXCEPTION 'Projection has not been recomputed after its current ledger';
 END IF;
 FOR cq IN SELECT * FROM trust.current_qualifications(p_user_id) LOOP
   IF NOT EXISTS (
      SELECT 1 FROM trust.ban_qualification_consumption c
      JOIN trust.ban_qualification q ON q.id=c.qualification_id
      JOIN trust.ban_instance bi ON bi.id=c.ban_instance_id
      WHERE q.user_id=p_user_id AND bi.user_id=p_user_id AND q.penalty_stage=cq.qualification_stage
        AND q.qualification_at=cq.effective_at
        AND trust.qualification_anchor(q.triggering_event_id)=cq.anchor_id
   ) THEN
     RAISE EXCEPTION 'Replay crossing % stage % has no exactly-once operational consequence',cq.effect_event_id,cq.qualification_stage;
   END IF;
 END LOOP;
 -- Historical consumptions remain after reversal. They cannot produce a second
 -- punishment if a replacement correction yields the same logical crossing/stage.
 -- A current restriction, however, must still have current valid support.
 FOR b IN SELECT * FROM trust.ban_instance x WHERE x.user_id=p_user_id
          AND x.status='ACTIVE' AND x.activated_at<=v_now AND x.ends_at>v_now LOOP
   SELECT max(c.consumed_at+trust.penalty_duration(q.penalty_stage)) INTO v_valid_until
   FROM trust.ban_qualification_consumption c JOIN trust.ban_qualification q ON q.id=c.qualification_id
   WHERE c.ban_instance_id=b.id AND EXISTS (
     SELECT 1 FROM trust.current_qualifications(p_user_id) curr
     WHERE curr.anchor_id=trust.qualification_anchor(q.triggering_event_id)
       AND curr.effective_at=q.qualification_at AND curr.qualification_stage=q.penalty_stage);
   IF v_valid_until IS NULL OR v_valid_until<=v_now THEN
     RAISE EXCEPTION 'Active Ban % lost its replay-valid qualification; reconcile CORRECTED now',b.id;
   END IF;
   IF b.ends_at>v_valid_until THEN
     RAISE EXCEPTION 'Active Ban % exceeds its remaining replay-valid qualifications; reconcile its end',b.id;
   END IF;
 END LOOP;
 -- The final pointer is checked at the SAME command instant, not at commit wall time.
 SELECT * INTO b FROM trust.ban_instance x WHERE x.user_id=p_user_id AND x.status='ACTIVE'
   AND x.activated_at<=v_now AND x.ends_at>v_now;
 IF p.active_ban_instance_id IS DISTINCT FROM (CASE WHEN FOUND THEN b.id ELSE NULL END) THEN
   RAISE EXCEPTION 'Projection Ban pointer does not match final current operational Ban';
 END IF;
 SELECT * INTO vp FROM trust.verified_player_transition x WHERE x.user_id=p_user_id
 ORDER BY x.occurred_at DESC,x.id DESC LIMIT 1;
 v_has_transition:=FOUND;
 v_status:=CASE WHEN v_has_transition THEN vp.to_status ELSE 'NOT_VERIFIED' END;
 v_cause:=CASE WHEN v_has_transition THEN vp.cause ELSE NULL END;
 IF p.vp_operational_status IS DISTINCT FROM v_status THEN
   RAISE EXCEPTION 'Projection VP status must match immutable transition history';
 END IF;
 IF r.vp_qualification='NOT_QUALIFIED' AND v_status='VERIFIED' THEN
   RAISE EXCEPTION 'Lost qualification requires synchronous TRUST_CORRECTION revocation';
 END IF;
 IF r.vp_qualification='QUALIFIED' AND
    (v_status='NOT_VERIFIED' OR (v_status='REVOKED' AND v_cause='TRUST_CORRECTION')) THEN
   RAISE EXCEPTION 'Qualified User requires initial VERIFIED or automatic correction regain before commit';
 END IF;
 -- Admin SUSPENDED/REVOKED deliberately remain protected. They are not auto-restored.
END;
$function$;

CREATE OR REPLACE FUNCTION trust.assert_user_integrity_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_user uuid; v_ban uuid;
BEGIN
 IF TG_TABLE_NAME='trust_event' THEN v_user:=NEW.subject_user_id;
 ELSIF TG_TABLE_NAME IN ('trust_projection','ban_qualification','ban_instance','verified_player_transition','trust_projection_checkpoint') THEN
   IF TG_OP='DELETE' THEN v_user:=OLD.user_id; ELSE v_user:=NEW.user_id; END IF;
 ELSIF TG_TABLE_NAME='cascade_execution' THEN v_user:=NEW.subject_user_id;
   IF NEW.cascade_type NOT IN ('BAN','VERIFIED_PLAYER') THEN RETURN NULL; END IF;
 ELSE
   IF TG_OP='DELETE' THEN v_ban:=OLD.ban_instance_id; ELSE v_ban:=NEW.ban_instance_id; END IF;
   SELECT user_id INTO v_user FROM trust.ban_instance WHERE id=v_ban;
 END IF;
 IF v_user IS NOT NULL THEN PERFORM trust.assert_user_integrity(v_user); END IF;
 RETURN NULL;
END;
$function$;

-- Every write surface queues the same final-value/consequence validator. Repeated
-- invocation is intentionally conservative; no unsafe per-transaction memoization.
DO $attach$
DECLARE nm text;
BEGIN
 FOREACH nm IN ARRAY ARRAY['trust_event','trust_projection','ban_qualification','ban_instance',
   'verified_player_transition','ban_qualification_consumption','cascade_execution',
   'ban_cascade_booking_target','ban_cascade_reservation_target','trust_projection_checkpoint'] LOOP
   EXECUTE format('DROP TRIGGER IF EXISTS tr_121_final_user_integrity ON trust.%I',nm);
   EXECUTE format('CREATE CONSTRAINT TRIGGER tr_121_final_user_integrity AFTER INSERT OR UPDATE OR DELETE ON trust.%I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION trust.assert_user_integrity_trigger()',nm);
 END LOOP;
END;
$attach$;

CREATE OR REPLACE FUNCTION trust.assert_trust_event_projection_current()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 PERFORM trust.assert_user_integrity(NEW.subject_user_id);
 RETURN NULL;
END;
$function$;

-- Controlled rebuild entry point. This does not create effects or bypass them:
-- the final aggregate validator still requires every operational consequence.
CREATE OR REPLACE FUNCTION trust.refresh_projection(p_user_id uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE r record; v_status text; v_ban uuid; v_now timestamptz;
BEGIN
 v_now:=trust.command_now(p_user_id);
 SELECT * INTO STRICT r FROM trust.replay_state(p_user_id);
 SELECT x.to_status INTO v_status FROM trust.verified_player_transition x WHERE x.user_id=p_user_id
 ORDER BY x.occurred_at DESC,x.id DESC LIMIT 1;
 SELECT x.id INTO v_ban FROM trust.ban_instance x WHERE x.user_id=p_user_id
 AND x.status='ACTIVE' AND x.activated_at<=v_now AND x.ends_at>v_now;
 INSERT INTO trust.trust_projection AS dst(user_id,last_effective_at,last_event_sequence,consecutive_no_shows,
   penalty_stage,current_threshold,completed_attended_count,vp_qualification,vp_operational_status,
   active_ban_instance_id,recomputed_at,projection_version)
 VALUES(p_user_id,r.last_effective_at,r.last_event_sequence,r.consecutive_no_shows,r.penalty_stage,
   r.current_threshold,r.completed_attended_count,r.vp_qualification,COALESCE(v_status,'NOT_VERIFIED'),v_ban,v_now,1)
 ON CONFLICT(user_id) DO UPDATE SET last_effective_at=EXCLUDED.last_effective_at,last_event_sequence=EXCLUDED.last_event_sequence,
   consecutive_no_shows=EXCLUDED.consecutive_no_shows,penalty_stage=EXCLUDED.penalty_stage,
   current_threshold=EXCLUDED.current_threshold,completed_attended_count=EXCLUDED.completed_attended_count,
   vp_qualification=EXCLUDED.vp_qualification,vp_operational_status=EXCLUDED.vp_operational_status,
   active_ban_instance_id=EXCLUDED.active_ban_instance_id,recomputed_at=EXCLUDED.recomputed_at,
   projection_version=dst.projection_version+1;
END;
$function$;

CREATE OR REPLACE FUNCTION trust.reject_ledger_truncate()
RETURNS trigger LANGUAGE plpgsql AS $function$
BEGIN RAISE EXCEPTION 'TRUNCATE cannot erase Trust source/provenance'; END;
$function$;
DO $truncate_guards$
DECLARE nm text;
BEGIN
 FOREACH nm IN ARRAY ARRAY['trust_event','ban_qualification','ban_instance','verified_player_transition',
   'ban_qualification_consumption','cascade_execution','ban_cascade_booking_target','ban_cascade_reservation_target'] LOOP
   EXECUTE format('DROP TRIGGER IF EXISTS tr_121_no_truncate ON trust.%I',nm);
   EXECUTE format('CREATE TRIGGER tr_121_no_truncate BEFORE TRUNCATE ON trust.%I FOR EACH STATEMENT EXECUTE FUNCTION trust.reject_ledger_truncate()',nm);
 END LOOP;
END;
$truncate_guards$;

CREATE OR REPLACE FUNCTION trust.guard_ban_cascade_registry()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE b trust.ban_instance%ROWTYPE; x booking.booking%ROWTYPE; rr inventory.resource_reservation%ROWTYPE;
BEGIN
    IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Ban cascade target registries are append-only'; END IF;
    IF NOT trust.registry_write_allowed(NEW.ban_instance_id,'REGISTER') THEN
      RAISE EXCEPTION 'Exact targets can only be inserted by the trusted registration producer';
    END IF;
    SELECT * INTO STRICT b FROM trust.ban_instance WHERE id=NEW.ban_instance_id;
    IF b.status<>'ACTIVE' OR b.cascade_executed_at IS NOT NULL OR b.cascade_targets_registered_at IS NOT NULL
       OR NEW.registered_at IS DISTINCT FROM b.activated_at THEN
        RAISE EXCEPTION 'Ban cascade target must be captured before execution at activation time';
    END IF;
    IF TG_TABLE_NAME='ban_cascade_booking_target' THEN
        SELECT * INTO STRICT x FROM booking.booking WHERE id=NEW.booking_id;
        IF x.source<>'ONLINE' OR x.customer_id IS DISTINCT FROM b.user_id
           OR NEW.from_status IS DISTINCT FROM x.status
           OR NOT (x.status IN ('PENDING','AWAITING_CUSTOMER_CONFIRMATION')
                   OR (x.status='CONFIRMED' AND x.start_at>b.activated_at)) THEN
            RAISE EXCEPTION 'Ban Booking target must be currently affected when captured';
        END IF;
    ELSE
        SELECT * INTO STRICT rr FROM inventory.resource_reservation WHERE id=NEW.reservation_id;
        IF rr.booking_id IS DISTINCT FROM NEW.booking_id OR NOT rr.active_flag
           OR rr.reservation_type NOT IN ('BOOKING','LATE_CONFIRM_HOLD')
           OR NOT EXISTS (SELECT 1 FROM trust.ban_cascade_booking_target t
                           WHERE t.ban_instance_id=b.id AND t.booking_id=NEW.booking_id) THEN
            RAISE EXCEPTION 'Ban reservation target must be an active commitment of a captured Booking';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION trust.require_next_qualification(p_qualification_id uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE q trust.ban_qualification%ROWTYPE; first_due record;
BEGIN
 SELECT * INTO STRICT q FROM trust.ban_qualification WHERE id=p_qualification_id;
 PERFORM trust.command_now(q.user_id);
 SELECT curr.* INTO first_due FROM trust.current_qualifications(q.user_id) curr
 WHERE NOT EXISTS (SELECT 1 FROM trust.ban_qualification_consumption c
  JOIN trust.ban_qualification used ON used.id=c.qualification_id
  WHERE used.user_id=q.user_id AND used.penalty_stage=curr.qualification_stage
    AND trust.qualification_anchor(used.triggering_event_id)=curr.anchor_id)
 ORDER BY curr.effective_at,curr.event_sequence LIMIT 1;
 IF NOT FOUND OR first_due.anchor_id IS DISTINCT FROM trust.qualification_anchor(q.triggering_event_id)
    OR first_due.effective_at IS DISTINCT FROM q.qualification_at
    OR first_due.qualification_stage IS DISTINCT FROM q.penalty_stage THEN
    RAISE EXCEPTION 'Operational qualifications must consume the first outstanding canonical crossing';
 END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION trust.consume_ban_qualification(
    p_ban_instance_id uuid,p_qualification_id uuid,p_consequence_type text,p_correlation_id uuid
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=pg_catalog,pg_temp
AS $function$
DECLARE b trust.ban_instance%ROWTYPE; v_consumed_at timestamptz;
BEGIN
    SELECT * INTO STRICT b FROM trust.ban_instance WHERE id=p_ban_instance_id;
    PERFORM trust.command_now(b.user_id);
    IF p_consequence_type='CREATE' THEN v_consumed_at:=b.activated_at;
    ELSIF p_consequence_type='EXTEND' THEN v_consumed_at:=b.last_command_at;
    ELSE RAISE EXCEPTION 'Invalid Ban Qualification consequence type'; END IF;
    INSERT INTO trust.ban_qualification_consumption(
        qualification_id,ban_instance_id,consequence_type,consumed_at,correlation_id
    ) VALUES (p_qualification_id,p_ban_instance_id,p_consequence_type,v_consumed_at,p_correlation_id);
END;
$function$;

CREATE OR REPLACE FUNCTION trust.guard_trust_checkpoint()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=pg_catalog,pg_temp
AS $function$
BEGIN
    PERFORM trust.command_now(NEW.user_id);
    IF jsonb_typeof(NEW.state_snapshot) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'Trust checkpoint state_snapshot must be a JSON object';
    END IF;
    IF NEW.snapshot_version < 1 THEN
        RAISE EXCEPTION 'Trust checkpoint snapshot_version must be positive';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM trust.trust_event e
         WHERE e.subject_user_id = NEW.user_id
           AND e.effective_at = NEW.checkpoint_effective_at
           AND e.event_sequence = NEW.checkpoint_event_sequence
    ) THEN
        RAISE EXCEPTION 'Trust checkpoint must reference an exact Trust event position for the same User';
    END IF;
    RETURN NEW;
END;
$function$;

