-- v1.1.22 focused Trust acceptance corrections (AR21-01/02/03 only).
-- Tournament semantics and all previously frozen Trust replay rules are unchanged.

CREATE OR REPLACE FUNCTION trust.begin_admin_command(p_user_id uuid, p_admin_id uuid)
RETURNS timestamptz
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=pg_catalog,pg_temp
AS $function$
DECLARE
    v_now timestamptz;
    v_existing record;
    v_grantee record;
BEGIN
    IF p_admin_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM iam.admin_account a WHERE a.id=p_admin_id AND a.is_active
    ) THEN
        RAISE EXCEPTION 'Trust Admin command requires an active Admin identity';
    END IF;

    v_now := trust.begin_command(p_user_id);
    CREATE TEMP TABLE IF NOT EXISTS pg_temp.e7gz_trust_admin_command_context (
        transaction_id xid8 PRIMARY KEY,
        user_id uuid NOT NULL,
        admin_id uuid NOT NULL,
        command_now timestamptz NOT NULL
    ) ON COMMIT DROP;
    REVOKE ALL ON TABLE pg_temp.e7gz_trust_admin_command_context FROM PUBLIC;
    FOR v_grantee IN
        SELECT DISTINCT r.rolname
          FROM pg_catalog.pg_class c
          CROSS JOIN LATERAL pg_catalog.aclexplode(c.relacl) x
          JOIN pg_catalog.pg_roles r ON r.oid=x.grantee
         WHERE c.oid='pg_temp.e7gz_trust_admin_command_context'::regclass
           AND x.grantee<>c.relowner
    LOOP
        EXECUTE format(
            'REVOKE ALL ON TABLE pg_temp.e7gz_trust_admin_command_context FROM %I',
            v_grantee.rolname
        );
    END LOOP;

    SELECT * INTO v_existing
      FROM pg_temp.e7gz_trust_admin_command_context
     WHERE transaction_id=pg_current_xact_id();
    IF FOUND THEN
        IF v_existing.user_id IS DISTINCT FROM p_user_id
           OR v_existing.admin_id IS DISTINCT FROM p_admin_id
           OR v_existing.command_now IS DISTINCT FROM v_now THEN
            RAISE EXCEPTION 'Trust Admin command context is immutable within a transaction';
        END IF;
        RETURN v_now;
    END IF;

    INSERT INTO pg_temp.e7gz_trust_admin_command_context(
        transaction_id,user_id,admin_id,command_now
    ) VALUES (pg_current_xact_id(),p_user_id,p_admin_id,v_now);
    RETURN v_now;
END;
$function$;

CREATE OR REPLACE FUNCTION trust.require_admin_command(p_user_id uuid)
RETURNS uuid
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path=pg_catalog,pg_temp
AS $function$
DECLARE
    v_admin_id uuid;
    v_context_now timestamptz;
BEGIN
    IF to_regclass('pg_temp.e7gz_trust_admin_command_context') IS NULL THEN
        RAISE EXCEPTION 'Ban Admin lifecycle command requires trust.begin_admin_command';
    END IF;
    SELECT c.admin_id,c.command_now
      INTO v_admin_id,v_context_now
      FROM pg_temp.e7gz_trust_admin_command_context c
     WHERE c.transaction_id=pg_current_xact_id()
       AND c.user_id=p_user_id;
    IF NOT FOUND OR v_context_now IS DISTINCT FROM trust.command_now(p_user_id)
       OR NOT EXISTS (SELECT 1 FROM iam.admin_account a WHERE a.id=v_admin_id AND a.is_active) THEN
        RAISE EXCEPTION 'Missing, stale, or inactive Trust Admin command identity';
    END IF;
    RETURN v_admin_id;
END;
$function$;

-- Administrative shortening/lifting must enter through an identity-bound command.
CREATE OR REPLACE FUNCTION trust.guard_ban_admin_command()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=pg_catalog,pg_temp
AS $function$
BEGIN
    IF OLD.status='ACTIVE' AND (
        NEW.status='LIFTED'
        OR (NEW.status='ACTIVE' AND NEW.ends_at<OLD.ends_at)
    ) THEN
        PERFORM trust.require_admin_command(NEW.user_id);
    END IF;
    RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS tr_01_ban_admin_command ON trust.ban_instance;
CREATE TRIGGER tr_01_ban_admin_command
BEFORE UPDATE ON trust.ban_instance
FOR EACH ROW EXECUTE FUNCTION trust.guard_ban_admin_command();

-- A CORRECTED terminal state is not an administrative synonym for LIFTED.
-- It is accepted only when the final canonical replay no longer supports any
-- still-effective qualification consumed by this Ban, and the audit binds the
-- exact authoritative correction event created by the same command.
CREATE OR REPLACE FUNCTION trust.assert_ban_lifecycle_audit()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=pg_catalog,pg_temp
AS $function$
DECLARE
    q trust.ban_qualification%ROWTYPE;
    v_admin_id uuid;
BEGIN
    IF OLD.status<>'ACTIVE' THEN RETURN NULL; END IF;

    IF NEW.status='ACTIVE' AND NEW.latest_qualification_id IS DISTINCT FROM OLD.latest_qualification_id THEN
        SELECT * INTO STRICT q FROM trust.ban_qualification WHERE id=NEW.latest_qualification_id;
        IF NOT EXISTS (SELECT 1 FROM audit.audit_event a
          JOIN trust.ban_qualification_consumption qc ON qc.qualification_id=q.id AND qc.ban_instance_id=NEW.id
          WHERE a.action='BAN_EXTENDED' AND a.subject_type='USER' AND a.subject_id=NEW.user_id
            AND a.occurred_at=NEW.last_command_at
            AND a.correlation_id=qc.correlation_id
            AND a.payload->>'banInstanceId'=NEW.id::text
            AND a.payload->>'triggeringQualificationId'=q.id::text
            AND a.payload->>'triggeringEventId'=q.triggering_event_id::text
            AND (a.payload->>'previousPenaltyStage')::smallint=OLD.penalty_stage
            AND (a.payload->>'newPenaltyStage')::smallint=NEW.penalty_stage
            AND (a.payload->>'oldEndsAt')::timestamptz=OLD.ends_at
            AND (a.payload->>'newEndsAt')::timestamptz=NEW.ends_at)
        THEN RAISE EXCEPTION 'Ban extension requires exact post-lock qualification-bound audit'; END IF;

    ELSIF NEW.status='ACTIVE' AND NEW.ends_at<OLD.ends_at THEN
        v_admin_id:=trust.require_admin_command(NEW.user_id);
        IF NOT EXISTS (SELECT 1 FROM audit.audit_event a
          WHERE a.actor_type='ADMIN' AND a.actor_id=v_admin_id
            AND EXISTS (SELECT 1 FROM iam.admin_account ia WHERE ia.id=a.actor_id AND ia.is_active)
            AND a.subject_type='USER' AND a.subject_id=NEW.user_id
            AND a.action='BAN_SHORTENED' AND a.occurred_at=NEW.last_command_at
            AND a.payload->>'banInstanceId'=NEW.id::text
            AND (a.payload->>'newEndsAt')::timestamptz=NEW.ends_at
            AND NULLIF(BTRIM(a.reason),'') IS NOT NULL)
        THEN RAISE EXCEPTION 'Ban shortening requires exact current-Admin command audit'; END IF;

    ELSIF NEW.status='LIFTED' THEN
        v_admin_id:=trust.require_admin_command(NEW.user_id);
        IF NOT EXISTS (SELECT 1 FROM audit.audit_event a
          WHERE a.actor_type='ADMIN' AND a.actor_id=v_admin_id
            AND EXISTS (SELECT 1 FROM iam.admin_account ia WHERE ia.id=a.actor_id AND ia.is_active)
            AND a.subject_type='USER' AND a.subject_id=NEW.user_id
            AND a.action='BAN_LIFTED' AND a.occurred_at=NEW.last_command_at
            AND a.occurred_at=NEW.ends_at
            AND a.payload->>'banInstanceId'=NEW.id::text
            AND NULLIF(BTRIM(a.reason),'') IS NOT NULL)
        THEN RAISE EXCEPTION 'Ban lift requires exact current-Admin command audit'; END IF;

    ELSIF NEW.status='CORRECTED' THEN
        IF EXISTS (
            SELECT 1
              FROM trust.ban_qualification_consumption c
              JOIN trust.ban_qualification usedq ON usedq.id=c.qualification_id
             WHERE c.ban_instance_id=NEW.id
               AND c.consumed_at+trust.penalty_duration(usedq.penalty_stage)>NEW.last_command_at
               AND EXISTS (
                   SELECT 1 FROM trust.current_qualifications(NEW.user_id) curr
                    WHERE curr.anchor_id=trust.qualification_anchor(usedq.triggering_event_id)
                      AND curr.effective_at=usedq.qualification_at
                      AND curr.qualification_stage=usedq.penalty_stage
               )
        ) THEN
            RAISE EXCEPTION 'CORRECTED cannot terminate a Ban that still has replay-valid effective support';
        END IF;

        IF NOT EXISTS (
            SELECT 1
              FROM audit.audit_event a
              JOIN trust.trust_event e
                ON e.id=CASE
                    WHEN (a.payload->>'correctionEventId') ~
                         '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                    THEN (a.payload->>'correctionEventId')::uuid
                    ELSE NULL
                END
               AND e.subject_user_id=NEW.user_id
               AND e.occurred_at=NEW.last_command_at
               AND e.event_type IN ('ATTENDANCE_CORRECTED','NO_SHOW_REVERSED','ADMIN_TRUST_ADJUSTMENT')
             WHERE a.subject_type='USER' AND a.subject_id=NEW.user_id
               AND a.action='BAN_CORRECTED'
               AND a.occurred_at=NEW.last_command_at AND a.occurred_at=NEW.ends_at
               AND a.payload->>'banInstanceId'=NEW.id::text
               AND NULLIF(BTRIM(a.reason),'') IS NOT NULL
               AND CASE
                   WHEN a.actor_type='SYSTEM' THEN
                       a.actor_id IS NULL
                       AND e.event_type IN ('ATTENDANCE_CORRECTED','NO_SHOW_REVERSED')
                   WHEN a.actor_type='ADMIN' THEN
                       a.actor_id=trust.require_admin_command(NEW.user_id)
                       AND EXISTS (SELECT 1 FROM iam.admin_account ia WHERE ia.id=a.actor_id AND ia.is_active)
                       AND (e.event_type<>'ADMIN_TRUST_ADJUSTMENT'
                            OR (e.payload->>'adminId')::uuid=a.actor_id)
                       AND (e.event_type<>'ADMIN_TRUST_ADJUSTMENT'
                            OR (e.payload->>'correlationId')::uuid=a.correlation_id)
                   ELSE false
               END
        ) THEN
            RAISE EXCEPTION 'Ban correction requires exact replay-invalidating event provenance and command actor';
        END IF;
    END IF;
    RETURN NULL;
END;
$function$;

-- Version 1 checkpoint contract. Checkpoints remain a validated, non-authoritative
-- optimization: canonical replay does not consume them until a separately accepted
-- snapshot-assisted implementation is delivered.
CREATE OR REPLACE FUNCTION trust.guard_trust_checkpoint()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=pg_catalog,pg_temp
AS $function$
DECLARE
    r record;
    v_keys text[];
BEGIN
    PERFORM trust.command_now(NEW.user_id);
    IF NEW.snapshot_version IS DISTINCT FROM 1 THEN
        RAISE EXCEPTION 'Unsupported Trust checkpoint snapshot_version; only version 1 is accepted';
    END IF;
    IF jsonb_typeof(NEW.state_snapshot) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'Trust checkpoint state_snapshot must be a JSON object';
    END IF;
    SELECT array_agg(k ORDER BY k) INTO v_keys FROM jsonb_object_keys(NEW.state_snapshot) k;
    IF v_keys IS DISTINCT FROM ARRAY[
        'completedAttendedCount','consecutiveNoShows','currentThreshold',
        'lastEffectiveAt','lastEventSequence','penaltyStage','vpQualification'
    ]::text[] THEN
        RAISE EXCEPTION 'Trust checkpoint version 1 must contain exactly the canonical seven state fields';
    END IF;
    IF jsonb_typeof(NEW.state_snapshot->'lastEffectiveAt') IS DISTINCT FROM 'string'
       OR jsonb_typeof(NEW.state_snapshot->'lastEventSequence') IS DISTINCT FROM 'number'
       OR jsonb_typeof(NEW.state_snapshot->'consecutiveNoShows') IS DISTINCT FROM 'number'
       OR jsonb_typeof(NEW.state_snapshot->'penaltyStage') IS DISTINCT FROM 'number'
       OR jsonb_typeof(NEW.state_snapshot->'currentThreshold') IS DISTINCT FROM 'number'
       OR jsonb_typeof(NEW.state_snapshot->'completedAttendedCount') IS DISTINCT FROM 'number'
       OR jsonb_typeof(NEW.state_snapshot->'vpQualification') IS DISTINCT FROM 'string'
       OR (NEW.state_snapshot->>'lastEventSequence') !~ '^[0-9]+$'
       OR (NEW.state_snapshot->>'consecutiveNoShows') !~ '^[0-9]+$'
       OR (NEW.state_snapshot->>'penaltyStage') !~ '^[0-3]$'
       OR (NEW.state_snapshot->>'currentThreshold') !~ '^[23]$'
       OR (NEW.state_snapshot->>'completedAttendedCount') !~ '^[0-9]+$'
       OR (NEW.state_snapshot->>'vpQualification') NOT IN ('QUALIFIED','NOT_QUALIFIED') THEN
        RAISE EXCEPTION 'Trust checkpoint version-1 field types or closed values are invalid';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM trust.trust_event e
         WHERE e.subject_user_id=NEW.user_id
           AND e.effective_at=NEW.checkpoint_effective_at
           AND e.event_sequence=NEW.checkpoint_event_sequence
    ) THEN
        RAISE EXCEPTION 'Trust checkpoint must reference an exact Trust event position for the same User';
    END IF;

    SELECT * INTO STRICT r FROM trust.replay_state(
        NEW.user_id,NEW.checkpoint_effective_at,NEW.checkpoint_event_sequence
    );
    IF (NEW.state_snapshot->>'lastEffectiveAt')::timestamptz IS DISTINCT FROM r.last_effective_at
       OR (NEW.state_snapshot->>'lastEventSequence')::bigint IS DISTINCT FROM r.last_event_sequence
       OR (NEW.state_snapshot->>'consecutiveNoShows')::integer IS DISTINCT FROM r.consecutive_no_shows
       OR (NEW.state_snapshot->>'penaltyStage')::smallint IS DISTINCT FROM r.penalty_stage
       OR (NEW.state_snapshot->>'currentThreshold')::smallint IS DISTINCT FROM r.current_threshold
       OR (NEW.state_snapshot->>'completedAttendedCount')::integer IS DISTINCT FROM r.completed_attended_count
       OR NEW.state_snapshot->>'vpQualification' IS DISTINCT FROM r.vp_qualification THEN
        RAISE EXCEPTION 'Trust checkpoint snapshot must equal canonical replay at its exact composite position';
    END IF;
    RETURN NEW;
EXCEPTION
    WHEN invalid_text_representation OR invalid_datetime_format
         OR datetime_field_overflow OR numeric_value_out_of_range THEN
        RAISE EXCEPTION 'Trust checkpoint version-1 field encoding is invalid';
END;
$function$;

COMMENT ON TABLE trust.trust_projection_checkpoint IS
'Validated rebuild checkpoint at an exact composite Trust position. Version 1 stores the canonical seven-field replay state. It is non-authoritative and is not consumed by canonical replay until a separately accepted snapshot-assisted implementation exists.';

REVOKE ALL ON FUNCTION trust.begin_admin_command(uuid,uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION trust.require_admin_command(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION trust.guard_ban_admin_command() FROM PUBLIC;
REVOKE ALL ON FUNCTION trust.assert_ban_lifecycle_audit() FROM PUBLIC;
REVOKE ALL ON FUNCTION trust.guard_trust_checkpoint() FROM PUBLIC;


-- v1.1.23: Loyalty launch-complete source hardening + AR21-02 / AR22-01.
-- The caller is a trusted backend, NOT a customer database connection.
-- Native tables/constraints/indexes are exported before this final override block.

CREATE OR REPLACE FUNCTION tournament.begin_command(
    p_user_ids uuid[],
    p_venue_ids uuid[],
    p_resource_ids uuid[],
    p_tournament_ids uuid[],
    p_new_tournament_ids uuid[] DEFAULT ARRAY[]::uuid[]
)
RETURNS timestamptz
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_users uuid[];
    v_venues uuid[];
    v_resources uuid[];
    v_tournaments uuid[];
    v_new uuid[];
    v_now timestamptz;
    v_grantee record;
    v_bookings uuid[];
    v_bans uuid[];
    v_reservations uuid[];
    v_guard_count integer;
BEGIN
    -- Loyalty configuration is immutable for this command; writers serialize before this lock.
    PERFORM pg_advisory_xact_lock_shared(1123,1);
    IF current_setting('transaction_isolation') <> 'read committed' THEN
        RAISE EXCEPTION 'Tournament command requires READ COMMITTED and a post-lock re-read';
    END IF;
    IF to_regclass('pg_temp.e7gz_tournament_command_context') IS NOT NULL THEN
        RAISE EXCEPTION 'Exactly one Tournament command per transaction; commit/rollback before beginning another';
    END IF;
    IF array_position(p_user_ids, NULL) IS NOT NULL
       OR array_position(p_venue_ids, NULL) IS NOT NULL
       OR array_position(p_resource_ids, NULL) IS NOT NULL
       OR array_position(p_tournament_ids, NULL) IS NOT NULL
       OR array_position(p_new_tournament_ids, NULL) IS NOT NULL THEN
        RAISE EXCEPTION 'Command scope arrays must not contain NULL identifiers';
    END IF;

    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[])
      INTO v_tournaments FROM unnest(COALESCE(p_tournament_ids, ARRAY[]::uuid[])) x;
    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[])
      INTO v_new FROM unnest(COALESCE(p_new_tournament_ids, ARRAY[]::uuid[])) x;
    IF v_tournaments && v_new THEN
        RAISE EXCEPTION 'Existing and new Tournament scope must be disjoint';
    END IF;
    IF EXISTS (SELECT 1 FROM tournament.tournament t WHERE t.id = ANY(v_new)) THEN
        RAISE EXCEPTION 'A preallocated new Tournament id already exists';
    END IF;

    -- v1.1.21: discover every live Tournament for explicitly named Trust subjects.
    -- Expansion is NOT recursive through every participant's unrelated Tournaments.
    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[]) INTO v_tournaments
      FROM (
        SELECT unnest(v_tournaments) x
        UNION SELECT t.id FROM tournament.tournament t
          WHERE t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE')
            AND (t.creator_user_id=ANY(COALESCE(p_user_ids,ARRAY[]::uuid[])) OR EXISTS (
              SELECT 1 FROM tournament.tournament_participant p WHERE p.tournament_id=t.id
                AND p.user_id=ANY(COALESCE(p_user_ids,ARRAY[]::uuid[]))))
      ) q;
    -- Discover the lock set, then acquire it in the baseline T10 order:
    -- Users/creators (sorted) -> Venues (sorted) -> Resources (sorted)
    -- -> Tournaments (sorted). Re-read/verify the set BEFORE sampling time.
    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[]) INTO v_users
      FROM (
          SELECT unnest(COALESCE(p_user_ids, ARRAY[]::uuid[])) x
          UNION SELECT t.creator_user_id FROM tournament.tournament t WHERE t.id = ANY(v_tournaments)
          UNION SELECT p.user_id FROM tournament.tournament_participant p WHERE p.tournament_id = ANY(v_tournaments)
      ) q WHERE x IS NOT NULL;
    -- Conservative baseline: include historical bookings for the named users so
    -- Attendance correction never waits on an undiscovered Booking after capture.
    SELECT COALESCE(array_agg(b.id ORDER BY b.id),ARRAY[]::uuid[]) INTO v_bookings
      FROM booking.booking b WHERE b.customer_id=ANY(v_users);
    SELECT COALESCE(array_agg(b.id ORDER BY b.id),ARRAY[]::uuid[]) INTO v_bans
      FROM trust.ban_instance b WHERE b.user_id=ANY(v_users);
    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[]) INTO v_resources
      FROM (
          SELECT unnest(COALESCE(p_resource_ids, ARRAY[]::uuid[])) x
          UNION SELECT r.resource_id FROM tournament.tournament_resource r WHERE r.tournament_id = ANY(v_tournaments)
          UNION SELECT b.resource_id FROM booking.booking b WHERE b.id=ANY(v_bookings)
      ) q WHERE x IS NOT NULL;
    SELECT COALESCE(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[]) INTO v_venues
      FROM (
          SELECT unnest(COALESCE(p_venue_ids, ARRAY[]::uuid[])) x
          UNION SELECT t.venue_id FROM tournament.tournament t WHERE t.id = ANY(v_tournaments)
          UNION SELECT b.venue_id FROM booking.booking b WHERE b.id=ANY(v_bookings)
          UNION SELECT r.venue_id FROM resource.resource r WHERE r.id = ANY(v_resources)
      ) q WHERE x IS NOT NULL;

    PERFORM u.id FROM iam.user_account u WHERE u.id = ANY(v_users) ORDER BY u.id FOR UPDATE;
    PERFORM g.user_id FROM iam.user_commitment_guard g
      WHERE g.user_id=ANY(v_users) ORDER BY g.user_id FOR UPDATE;
    SELECT count(*) INTO v_guard_count FROM iam.user_commitment_guard g WHERE g.user_id=ANY(v_users);
    IF v_guard_count<>cardinality(v_users) THEN
      RAISE EXCEPTION 'Every command User requires an initialized user_commitment_guard';
    END IF;
    PERFORM v.id FROM venue.venue v WHERE v.id = ANY(v_venues) ORDER BY v.id FOR UPDATE;
    PERFORM a.id FROM iam.venue_account a WHERE a.venue_id = ANY(v_venues) ORDER BY a.id FOR UPDATE;
    PERFORM r.id FROM resource.resource r WHERE r.id = ANY(v_resources) ORDER BY r.id FOR UPDATE;
    PERFORM t.id FROM tournament.tournament t WHERE t.id = ANY(v_tournaments) ORDER BY t.id FOR UPDATE;

    PERFORM b.id FROM booking.booking b WHERE b.id=ANY(v_bookings) ORDER BY b.id FOR UPDATE;
    PERFORM a.id FROM attendance.attendance_record a WHERE a.booking_id=ANY(v_bookings) ORDER BY a.id FOR UPDATE;
    PERFORM l.id FROM booking.late_confirmation l WHERE l.booking_id=ANY(v_bookings) ORDER BY l.id FOR UPDATE;
    SELECT COALESCE(array_agg(rr.id ORDER BY rr.id),ARRAY[]::uuid[]) INTO v_reservations
      FROM inventory.resource_reservation rr
     WHERE rr.booking_id=ANY(v_bookings) OR rr.tournament_id=ANY(v_tournaments);
    PERFORM rr.id FROM inventory.resource_reservation rr WHERE rr.id=ANY(v_reservations) ORDER BY rr.id FOR UPDATE;
    PERFORM b.id FROM trust.ban_instance b WHERE b.id=ANY(v_bans) ORDER BY b.id FOR UPDATE;
    PERFORM p.user_id FROM trust.trust_projection p WHERE p.user_id=ANY(v_users) ORDER BY p.user_id FOR UPDATE;
    -- If an earlier writer changed discovery while we waited, retry before sampling.
    IF EXISTS (SELECT 1 FROM booking.booking b WHERE b.customer_id=ANY(v_users) AND NOT b.id=ANY(v_bookings))
       OR EXISTS (SELECT 1 FROM trust.ban_instance b WHERE b.user_id=ANY(v_users) AND NOT b.id=ANY(v_bans))
       OR EXISTS (SELECT 1 FROM inventory.resource_reservation rr
          WHERE (rr.booking_id=ANY(v_bookings) OR rr.tournament_id=ANY(v_tournaments)) AND NOT rr.id=ANY(v_reservations))
       OR EXISTS (SELECT 1 FROM tournament.tournament t
          WHERE t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE')
            AND NOT t.id=ANY(v_tournaments)
            AND (t.creator_user_id=ANY(COALESCE(p_user_ids,ARRAY[]::uuid[])) OR EXISTS (
              SELECT 1 FROM tournament.tournament_participant p WHERE p.tournament_id=t.id
                AND p.user_id=ANY(COALESCE(p_user_ids,ARRAY[]::uuid[]))))) THEN
       RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='Shared command scope changed while waiting; retry whole transaction';
    END IF;

    IF (SELECT count(*) FROM iam.user_account u WHERE u.id = ANY(v_users)) <> cardinality(v_users)
       OR (SELECT count(*) FROM venue.venue v WHERE v.id = ANY(v_venues)) <> cardinality(v_venues)
       OR (SELECT count(*) FROM resource.resource r WHERE r.id = ANY(v_resources)) <> cardinality(v_resources)
       OR (SELECT count(*) FROM tournament.tournament t WHERE t.id = ANY(v_tournaments)) <> cardinality(v_tournaments) THEN
        RAISE EXCEPTION 'Command scope contains a missing authoritative row';
    END IF;
    IF EXISTS (
        SELECT 1 FROM tournament.tournament t WHERE t.id = ANY(v_tournaments)
          AND (NOT (t.venue_id = ANY(v_venues))
               OR (t.creator_user_id IS NOT NULL AND NOT (t.creator_user_id = ANY(v_users))))
    ) OR EXISTS (
        SELECT 1 FROM tournament.tournament_participant p
         WHERE p.tournament_id = ANY(v_tournaments) AND NOT (p.user_id = ANY(v_users))
    ) OR EXISTS (
        SELECT 1 FROM tournament.tournament_resource r
         WHERE r.tournament_id = ANY(v_tournaments) AND NOT (r.resource_id = ANY(v_resources))
    ) OR EXISTS (
        SELECT 1 FROM resource.resource r
         WHERE r.id = ANY(v_resources) AND NOT (r.venue_id = ANY(v_venues))
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Tournament lock set changed while waiting; retry the whole transaction';
    END IF;

    CREATE TEMPORARY TABLE e7gz_tournament_command_context (
        singleton boolean PRIMARY KEY CHECK (singleton),
        transaction_id xid8 NOT NULL,
        captured_at timestamptz NOT NULL,
        user_ids uuid[] NOT NULL,
        venue_ids uuid[] NOT NULL,
        resource_ids uuid[] NOT NULL,
        tournament_ids uuid[] NOT NULL,
        new_tournament_ids uuid[] NOT NULL,
        created_tournament_ids uuid[] NOT NULL,
        rejection_outbox_event_ids bigint[] NOT NULL,
        booking_ids uuid[] NOT NULL,
        created_ban_ids uuid[] NOT NULL,
        registry_ban_id uuid,
        registry_mode text
    ) ON COMMIT DROP;
    REVOKE ALL ON TABLE pg_temp.e7gz_tournament_command_context FROM PUBLIC;
    -- Owner default privileges may grant newly-created tables to service/group
    -- roles. Remove those grants as well; PUBLIC-only revocation is insufficient.
    FOR v_grantee IN
        SELECT DISTINCT r.rolname
          FROM pg_catalog.pg_class c
          CROSS JOIN LATERAL pg_catalog.aclexplode(c.relacl) a
          JOIN pg_catalog.pg_roles r ON r.oid=a.grantee
         WHERE c.oid='pg_temp.e7gz_tournament_command_context'::regclass
           AND a.grantee <> c.relowner
    LOOP
        EXECUTE format('REVOKE ALL ON TABLE pg_temp.e7gz_tournament_command_context FROM %I', v_grantee.rolname);
    END LOOP;

    -- v1.1.23: all money/Referral rows are locked before the shared clock sample.
    PERFORM pa.user_id FROM loyalty.points_account pa WHERE pa.user_id=ANY(v_users) ORDER BY pa.user_id FOR UPDATE;
    PERFORM wa.user_id FROM loyalty.wallet_account wa WHERE wa.user_id=ANY(v_users) ORDER BY wa.user_id FOR UPDATE;
    PERFORM lr.id FROM loyalty.referral lr WHERE lr.referrer_user_id=ANY(v_users) OR lr.referred_user_id=ANY(v_users) ORDER BY lr.id FOR UPDATE;
    -- The ONLY clock read in the new Tournament command implementation.
    -- All authoritative lock waits above have completed at this point.
    v_now := clock_timestamp();
    INSERT INTO pg_temp.e7gz_tournament_command_context
    VALUES (true, pg_current_xact_id(), v_now, v_users, v_venues, v_resources,
            v_tournaments, v_new, ARRAY[]::uuid[], ARRAY[]::bigint[], v_bookings, ARRAY[]::uuid[], NULL, NULL);
    RETURN v_now;
END;
$function$;

-- Shared trusted-owner primitive: never read caller-created temp objects.
CREATE OR REPLACE FUNCTION trust.assert_owned_context(p_name text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_oid oid;
BEGIN
 IF p_name IS NULL OR p_name NOT IN ('e7gz_trust_admin_command_context','e7gz_loyalty_command_context','e7gz_loyalty_write_context') THEN
   RAISE EXCEPTION 'Unknown protected context';
 END IF;
 v_oid:=to_regclass(format('pg_temp.%I',p_name));
 IF NOT EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=v_oid AND c.relnamespace=pg_my_temp_schema()
   AND c.relpersistence='t' AND c.relkind='r' AND NOT c.relrowsecurity
   AND c.relowner=(SELECT r.oid FROM pg_roles r WHERE r.rolname=current_user)) THEN
   RAISE EXCEPTION 'Missing or caller-owned protected context: %',p_name;
 END IF;
 IF EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(COALESCE(c.relacl,acldefault('r',c.relowner))) a
   WHERE c.oid=v_oid AND a.grantee<>c.relowner) THEN
   RAISE EXCEPTION 'Protected context has non-owner privileges: %',p_name;
 END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION trust.secure_created_context(p_name text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_oid oid; gr record;
BEGIN
 IF p_name IS NULL OR p_name NOT IN ('e7gz_trust_admin_command_context','e7gz_loyalty_command_context','e7gz_loyalty_write_context') THEN RAISE EXCEPTION 'Unknown context'; END IF;
 v_oid:=to_regclass(format('pg_temp.%I',p_name));
 IF NOT EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=v_oid AND c.relnamespace=pg_my_temp_schema() AND c.relpersistence='t' AND c.relkind='r'
   AND c.relowner=(SELECT oid FROM pg_roles WHERE rolname=current_user)) THEN RAISE EXCEPTION 'Cannot adopt a caller-owned context'; END IF;
 EXECUTE format('REVOKE ALL ON pg_temp.%I FROM PUBLIC',p_name);
 FOR gr IN SELECT DISTINCT r.rolname FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a JOIN pg_roles r ON r.oid=a.grantee
   WHERE c.oid=v_oid AND a.grantee<>c.relowner LOOP
   EXECUTE format('REVOKE ALL ON pg_temp.%I FROM %I',p_name,gr.rolname);
 END LOOP;
 PERFORM trust.assert_owned_context(p_name);
END;
$function$;

CREATE OR REPLACE FUNCTION trust.begin_admin_command(p_user_id uuid,p_admin_id uuid)
RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_now timestamptz; v_ctx record;
BEGIN
 IF p_user_id IS NULL OR p_admin_id IS NULL THEN RAISE EXCEPTION 'User and Admin are required'; END IF;
 -- Reject spoofed/precreated relations BEFORE invoking any DML on them.
 IF to_regclass('pg_temp.e7gz_trust_admin_command_context') IS NOT NULL THEN
   PERFORM trust.assert_owned_context('e7gz_trust_admin_command_context');
 END IF;
 PERFORM a.id FROM iam.admin_account a WHERE a.id=p_admin_id AND a.is_active FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Active Admin identity required'; END IF;
 IF to_regclass('pg_temp.e7gz_tournament_command_context') IS NULL THEN
   v_now:=trust.begin_command(p_user_id);
 ELSE
   v_now:=trust.command_now(p_user_id);
 END IF;
 IF to_regclass('pg_temp.e7gz_trust_admin_command_context') IS NULL THEN
   CREATE TEMP TABLE pg_temp.e7gz_trust_admin_command_context(
     transaction_id xid8 PRIMARY KEY,user_id uuid NOT NULL,admin_id uuid NOT NULL,command_now timestamptz NOT NULL
   ) ON COMMIT DROP;
   PERFORM trust.secure_created_context('e7gz_trust_admin_command_context');
 END IF;
 PERFORM trust.assert_owned_context('e7gz_trust_admin_command_context');
 SELECT * INTO v_ctx FROM pg_temp.e7gz_trust_admin_command_context WHERE transaction_id=pg_current_xact_id();
 IF FOUND THEN
   IF v_ctx.user_id IS DISTINCT FROM p_user_id OR v_ctx.admin_id IS DISTINCT FROM p_admin_id OR v_ctx.command_now IS DISTINCT FROM v_now THEN
     RAISE EXCEPTION 'Admin command identity cannot be rebound';
   END IF;
 ELSE
   INSERT INTO pg_temp.e7gz_trust_admin_command_context VALUES(pg_current_xact_id(),p_user_id,p_admin_id,v_now);
 END IF;
 RETURN v_now;
END;
$function$;

CREATE OR REPLACE FUNCTION trust.require_admin_command(p_user_id uuid)
RETURNS uuid LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_ctx record;
BEGIN
 PERFORM trust.assert_owned_context('e7gz_trust_admin_command_context');
 SELECT * INTO v_ctx FROM pg_temp.e7gz_trust_admin_command_context
 WHERE transaction_id=pg_current_xact_id() AND user_id=p_user_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Missing current User/Admin command'; END IF;
 IF v_ctx.command_now IS DISTINCT FROM trust.command_now(p_user_id) THEN RAISE EXCEPTION 'Stale Admin command time'; END IF;
 PERFORM a.id FROM iam.admin_account a WHERE a.id=v_ctx.admin_id AND a.is_active FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Inactive Admin'; END IF;
 RETURN v_ctx.admin_id;
END;
$function$;

CREATE SEQUENCE IF NOT EXISTS loyalty.ledger_sequence_seq AS bigint;
CREATE SEQUENCE IF NOT EXISTS loyalty.application_sequence_seq AS bigint;
-- Canonical Outbox identity allocation. All new writes use RETURNING id.
CREATE SEQUENCE IF NOT EXISTS technical.outbox_event_id_seq AS bigint;
DO $outbox_sequence$
DECLARE v_max bigint; v_seq bigint;
BEGIN
 LOCK TABLE technical.outbox_event IN ACCESS EXCLUSIVE MODE;
 SELECT COALESCE(max(id),0) INTO v_max FROM technical.outbox_event;
 SELECT last_value INTO v_seq FROM technical.outbox_event_id_seq;
 PERFORM setval('technical.outbox_event_id_seq',GREATEST(v_max,v_seq,1),true);
END;
$outbox_sequence$;
CREATE OR REPLACE FUNCTION technical.assign_outbox_id()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN NEW.id:=nextval('technical.outbox_event_id_seq'); RETURN NEW; END;
$function$;
DROP TRIGGER IF EXISTS tr_00_outbox_db_identity ON technical.outbox_event;
CREATE TRIGGER tr_00_outbox_db_identity BEFORE INSERT ON technical.outbox_event FOR EACH ROW EXECUTE FUNCTION technical.assign_outbox_id();

-- Private write capability, owner-checked on EVERY read; never granted to service roles.
CREATE OR REPLACE FUNCTION loyalty.enter_write(p_table text,p_key text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_token uuid:=gen_random_uuid();
BEGIN
 IF to_regclass('pg_temp.e7gz_loyalty_write_context') IS NULL THEN
   CREATE TEMP TABLE pg_temp.e7gz_loyalty_write_context(token uuid PRIMARY KEY,transaction_id xid8 NOT NULL,table_name text NOT NULL,row_key text NOT NULL) ON COMMIT DROP;
   PERFORM trust.secure_created_context('e7gz_loyalty_write_context');
 END IF;
 PERFORM trust.assert_owned_context('e7gz_loyalty_write_context');
 INSERT INTO pg_temp.e7gz_loyalty_write_context VALUES(v_token,pg_current_xact_id(),p_table,p_key);
 RETURN v_token;
END;
$function$;
CREATE OR REPLACE FUNCTION loyalty.leave_write(p_token uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 PERFORM trust.assert_owned_context('e7gz_loyalty_write_context');
 DELETE FROM pg_temp.e7gz_loyalty_write_context WHERE token=p_token AND transaction_id=pg_current_xact_id();
END;
$function$;
CREATE OR REPLACE FUNCTION loyalty.require_write(p_table text,p_key text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 PERFORM trust.assert_owned_context('e7gz_loyalty_write_context');
 IF NOT EXISTS(SELECT 1 FROM pg_temp.e7gz_loyalty_write_context c WHERE c.transaction_id=pg_current_xact_id() AND c.table_name=p_table AND c.row_key=p_key) THEN
   RAISE EXCEPTION 'Loyalty mutation requires the private producer: %',p_table;
 END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION loyalty.command_context(p_user_id uuid DEFAULT NULL)
RETURNS TABLE(command_at timestamptz,admin_id uuid,correlation_id uuid,user_ids uuid[])
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_ctx record; v_now timestamptz;
BEGIN
 PERFORM trust.assert_owned_context('e7gz_loyalty_command_context');
 SELECT * INTO v_ctx FROM pg_temp.e7gz_loyalty_command_context c WHERE c.transaction_id=pg_current_xact_id();
 IF NOT FOUND THEN RAISE EXCEPTION 'Missing Loyalty command'; END IF;
 v_now:=tournament.command_now();
 IF v_ctx.command_at IS DISTINCT FROM v_now OR (p_user_id IS NOT NULL AND NOT p_user_id=ANY(v_ctx.user_ids)) THEN
   RAISE EXCEPTION 'Loyalty command User/time mismatch';
 END IF;
 IF v_ctx.admin_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM iam.admin_account a WHERE a.id=v_ctx.admin_id AND a.is_active) THEN
   RAISE EXCEPTION 'Loyalty command Admin is inactive';
 END IF;
 RETURN QUERY SELECT v_ctx.command_at,v_ctx.admin_id,v_ctx.correlation_id,v_ctx.user_ids;
END;
$function$;

CREATE OR REPLACE FUNCTION loyalty.start_command(p_user_ids uuid[],p_admin_id uuid,p_correlation_id uuid)
RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_ids uuid[]; v_now timestamptz; v_ctx record; v_shared record;
BEGIN
 IF p_correlation_id IS NULL OR p_user_ids IS NULL OR array_position(p_user_ids,NULL) IS NOT NULL THEN
   RAISE EXCEPTION 'Loyalty command requires an explicit non-null scope and correlation';
 END IF;
 SELECT COALESCE(array_agg(DISTINCT x ORDER BY x),ARRAY[]::uuid[]) INTO v_ids FROM unnest(p_user_ids) x;
 IF p_admin_id IS NOT NULL THEN
   PERFORM a.id FROM iam.admin_account a WHERE a.id=p_admin_id AND a.is_active FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Active Admin required'; END IF;
 END IF;
 IF to_regclass('pg_temp.e7gz_loyalty_command_context') IS NOT NULL THEN
   PERFORM trust.assert_owned_context('e7gz_loyalty_command_context');
   SELECT * INTO v_ctx FROM loyalty.command_context(NULL);
   IF v_ctx.user_ids IS DISTINCT FROM v_ids OR v_ctx.admin_id IS DISTINCT FROM p_admin_id OR v_ctx.correlation_id IS DISTINCT FROM p_correlation_id THEN
     RAISE EXCEPTION 'One immutable Loyalty command context per transaction';
   END IF;
   RETURN v_ctx.command_at;
 END IF;
 IF to_regclass('pg_temp.e7gz_tournament_command_context') IS NULL THEN
   -- Config writers take the exclusive lock, before stamping effective_from.
   PERFORM pg_advisory_xact_lock_shared(1123,1);
   v_now:=tournament.begin_command(v_ids,ARRAY[]::uuid[],ARRAY[]::uuid[],ARRAY[]::uuid[]);
 ELSE
   v_now:=tournament.command_now();
   IF NOT pg_try_advisory_xact_lock_shared(1123,1) THEN
     RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Configuration writer in flight; retry the whole shared command';
   END IF;
 END IF;
 SELECT * INTO STRICT v_shared FROM pg_temp.e7gz_tournament_command_context WHERE singleton AND transaction_id=pg_current_xact_id();
 IF NOT v_ids<@v_shared.user_ids THEN RAISE EXCEPTION 'All Loyalty Users must be prelocked in the shared scope'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(v_ids) u WHERE NOT EXISTS(SELECT 1 FROM loyalty.points_account a WHERE a.user_id=u)
    OR NOT EXISTS(SELECT 1 FROM loyalty.wallet_account a WHERE a.user_id=u)) THEN
   RAISE EXCEPTION 'User Loyalty accounts must be initialized';
 END IF;
 -- User roots serialize account writes; every Loyalty writer uses the same roots.
 PERFORM a.user_id FROM loyalty.points_account a WHERE a.user_id=ANY(v_ids) ORDER BY a.user_id FOR UPDATE;
 PERFORM a.user_id FROM loyalty.wallet_account a WHERE a.user_id=ANY(v_ids) ORDER BY a.user_id FOR UPDATE;
 CREATE TEMP TABLE pg_temp.e7gz_loyalty_command_context(transaction_id xid8 PRIMARY KEY,user_ids uuid[] NOT NULL,admin_id uuid,correlation_id uuid NOT NULL,command_at timestamptz NOT NULL) ON COMMIT DROP;
 PERFORM trust.secure_created_context('e7gz_loyalty_command_context');
 PERFORM trust.assert_owned_context('e7gz_loyalty_command_context');
 INSERT INTO pg_temp.e7gz_loyalty_command_context VALUES(pg_current_xact_id(),v_ids,p_admin_id,p_correlation_id,v_now);
 RETURN v_now;
END;
$function$;
CREATE OR REPLACE FUNCTION loyalty.begin_command(p_user_ids uuid[],p_correlation_id uuid)
RETURNS timestamptz LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
 SELECT loyalty.start_command(p_user_ids,NULL,p_correlation_id);
$function$;
CREATE OR REPLACE FUNCTION loyalty.begin_admin_command(p_user_ids uuid[],p_admin_id uuid,p_correlation_id uuid)
RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF p_admin_id IS NULL THEN RAISE EXCEPTION 'Admin is required'; END IF;
 RETURN loyalty.start_command(p_user_ids,p_admin_id,p_correlation_id);
END;
$function$;

CREATE OR REPLACE FUNCTION loyalty.write_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_key text; v_ctx record;
BEGIN
 IF TG_OP IN ('DELETE','TRUNCATE') THEN RAISE EXCEPTION 'Loyalty rows cannot be deleted/truncated'; END IF;
 IF TG_OP='UPDATE' AND TG_TABLE_NAME IN ('points_transaction','wallet_transaction','reward_application','booking_fee_receipt') THEN
   RAISE EXCEPTION 'Loyalty ledger/provenance is append-only';
 END IF;
 IF TG_TABLE_NAME IN ('points_account','wallet_account') THEN v_key:=NEW.user_id::text; ELSE v_key:=NEW.id::text; END IF;
 PERFORM loyalty.require_write(TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME,v_key);
 IF TG_OP='UPDATE' AND TG_TABLE_NAME IN ('points_account','wallet_account') AND NEW.user_id IS DISTINCT FROM OLD.user_id THEN
   RAISE EXCEPTION 'Account identity is immutable';
 END IF;
 RETURN NEW;
END;
$function$;

-- Exact historical config resolution; no current-value shortcut for corrections.
CREATE OR REPLACE FUNCTION loyalty.configuration_at(p_key text,p_at timestamptz)
RETURNS TABLE(version_id uuid,value jsonb)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF p_at IS NULL OR p_key NOT IN ('loyalty.attended_points','loyalty.referral_points','loyalty.wallet_refunds_enabled') THEN RAISE EXCEPTION 'Invalid config lookup'; END IF;
 RETURN QUERY SELECT c.id,c.new_value FROM config.configuration_version c WHERE c.key=p_key AND c.effective_from<=p_at ORDER BY c.effective_from DESC,c.id DESC LIMIT 1;
 IF NOT FOUND THEN RAISE EXCEPTION 'No historical configuration for % at %',p_key,p_at; END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION loyalty.config_integer(p_key text,p_at timestamptz)
RETURNS integer LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v jsonb;
BEGIN
 SELECT c.value INTO STRICT v FROM loyalty.configuration_at(p_key,p_at) c;
 IF jsonb_typeof(v)<>'number' OR v::text !~ '^[0-9]+$' THEN RAISE EXCEPTION 'Reward configuration must be a nonnegative integer'; END IF;
 RETURN v::text::integer;
END;
$function$;
CREATE OR REPLACE FUNCTION loyalty.wallet_enabled(p_at timestamptz)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v jsonb;
BEGIN
 SELECT c.value INTO STRICT v FROM loyalty.configuration_at('loyalty.wallet_refunds_enabled',p_at) c;
 IF jsonb_typeof(v)<>'boolean' THEN RAISE EXCEPTION 'Invalid Wallet flag'; END IF;
 RETURN v::text::boolean;
END;
$function$;

CREATE OR REPLACE FUNCTION loyalty.write_audit(p_user_id uuid,p_action text,p_reason text,p_payload jsonb)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_ctx record; v_id uuid:=gen_random_uuid(); v_tok uuid;
BEGIN
 SELECT * INTO STRICT v_ctx FROM loyalty.command_context(p_user_id);
 IF v_ctx.admin_id IS NOT NULL AND NULLIF(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'Admin reason required'; END IF;
 v_tok:=loyalty.enter_write('audit.audit_event',v_id::text);
 INSERT INTO audit.audit_event(id,occurred_at,actor_type,actor_id,action,subject_type,subject_id,reason,correlation_id,payload)
 VALUES(v_id,v_ctx.command_at,CASE WHEN v_ctx.admin_id IS NULL THEN 'SYSTEM' ELSE 'ADMIN' END,v_ctx.admin_id,p_action,'USER',p_user_id,p_reason,v_ctx.correlation_id,COALESCE(p_payload,'{}'::jsonb));
 PERFORM loyalty.leave_write(v_tok);
 RETURN v_id;
END;
$function$;
CREATE OR REPLACE FUNCTION loyalty.write_outbox(p_user_id uuid,p_type text,p_aggregate_id uuid,p_payload jsonb)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_ctx record; v_id bigint; v_token uuid;
BEGIN
 SELECT * INTO STRICT v_ctx FROM loyalty.command_context(p_user_id);
 v_token:=loyalty.enter_write('technical.outbox_event',p_aggregate_id::text);
 INSERT INTO technical.outbox_event(event_type,aggregate_type,aggregate_id,payload,correlation_id,state,attempt,next_attempt_at)
 VALUES(p_type,'LOYALTY',p_aggregate_id,COALESCE(p_payload,'{}'::jsonb)||jsonb_build_object('recipientUserId',p_user_id,'occurredAt',v_ctx.command_at),v_ctx.correlation_id,'PENDING',0,v_ctx.command_at)
 RETURNING id INTO v_id;
 PERFORM loyalty.leave_write(v_token);
 RETURN v_id;
END;
$function$;

CREATE OR REPLACE FUNCTION loyalty.post_points(
 p_user uuid,p_requested integer,p_cause text,p_key text,p_booking uuid,p_referral uuid,
 p_event uuid,p_compensates uuid,p_snapshot integer,p_config uuid,p_config_at timestamptz,p_reason text
)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE
 v_ctx record; v_existing loyalty.points_transaction%ROWTYPE; v_original loyalty.points_transaction%ROWTYPE;
 v_balance integer; v_amount integer; v_shortfall integer; v_after bigint;
 v_id uuid:=gen_random_uuid(); v_audit uuid; v_outbox bigint; v_token uuid; v_payload jsonb;
BEGIN
 SELECT * INTO STRICT v_ctx FROM loyalty.command_context(p_user);
 IF p_requested IS NULL OR p_requested=-2147483648 OR NULLIF(btrim(p_key),'') IS NULL THEN RAISE EXCEPTION 'Invalid Points request'; END IF;
 SELECT * INTO v_existing FROM loyalty.points_transaction x WHERE x.operation_key=p_key;
 IF FOUND THEN
   IF v_existing.points_account_id IS DISTINCT FROM p_user OR v_existing.requested_amount IS DISTINCT FROM p_requested
      OR v_existing.cause IS DISTINCT FROM p_cause OR v_existing.booking_id IS DISTINCT FROM p_booking
      OR v_existing.referral_id IS DISTINCT FROM p_referral OR v_existing.source_trust_event_id IS DISTINCT FROM p_event
      OR v_existing.compensates_transaction_id IS DISTINCT FROM p_compensates
      OR v_existing.admin_id IS DISTINCT FROM v_ctx.admin_id OR v_existing.reason IS DISTINCT FROM p_reason
      OR v_existing.granted_value_snapshot IS DISTINCT FROM p_snapshot
      OR v_existing.configuration_version_id IS DISTINCT FROM p_config OR v_existing.configuration_as_of IS DISTINCT FROM p_config_at THEN
     RAISE EXCEPTION 'Idempotency key reused with a different Points request';
   END IF;
   RETURN v_existing.id;
 END IF;
 IF p_cause='ADMIN' AND v_ctx.admin_id IS NULL THEN RAISE EXCEPTION 'Points Admin adjustment requires Admin command'; END IF;
 IF p_compensates IS NOT NULL THEN
   SELECT * INTO STRICT v_original FROM loyalty.points_transaction WHERE id=p_compensates;
   IF v_original.points_account_id IS DISTINCT FROM p_user OR v_original.booking_id IS DISTINCT FROM p_booking
      OR v_original.referral_id IS DISTINCT FROM p_referral OR v_original.amount<0 THEN
     RAISE EXCEPTION 'Compensation must reference the same-account original positive reward';
   END IF;
 END IF;
 SELECT a.balance INTO STRICT v_balance FROM loyalty.points_account a WHERE a.user_id=p_user FOR UPDATE;
 v_amount:=CASE WHEN p_requested<0 THEN GREATEST(p_requested,-v_balance) ELSE p_requested END;
 v_shortfall:=CASE WHEN p_requested<0 THEN (v_amount::bigint-p_requested::bigint)::integer ELSE 0 END;
 v_after:=v_balance::bigint+v_amount::bigint;
 IF v_after NOT BETWEEN 0 AND 2147483647 THEN RAISE EXCEPTION 'Points balance outside supported integer range'; END IF;
 v_payload:=jsonb_build_object('transactionId',v_id,'operationKey',p_key,'cause',p_cause,
   'bookingId',p_booking,'referralId',p_referral,'sourceEventId',p_event,'compensatesTransactionId',p_compensates,
   'historicalValue',p_snapshot,'configurationVersionId',p_config,'configurationAsOf',p_config_at,
   'requestedAmount',p_requested,'appliedAmount',v_amount,'unrecoveredAmount',v_shortfall,
   'balanceBefore',v_balance,'balanceAfter',v_after);
 v_audit:=loyalty.write_audit(p_user,'POINTS_TRANSACTION_POSTED',p_reason,v_payload);
 IF v_shortfall>0 THEN
   PERFORM loyalty.write_audit(p_user,'UNRECOVERED_REVERSAL_AMOUNT',p_reason,v_payload);
 END IF;
 v_outbox:=loyalty.write_outbox(p_user,'LOYALTY_POINTS_LEDGER_COMMITTED',v_id,v_payload);
 v_token:=loyalty.enter_write('loyalty.points_transaction',v_id::text);
 INSERT INTO loyalty.points_transaction(id,points_account_id,amount,cause,booking_id,referral_id,granted_value_snapshot,
   compensates_transaction_id,unrecovered_reversal_amount,admin_id,reason,occurred_at,ledger_sequence,operation_key,
   requested_amount,balance_before,balance_after,source_trust_event_id,configuration_as_of,configuration_version_id,
   correlation_id,audit_event_id,outbox_event_id)
 VALUES(v_id,p_user,v_amount,p_cause,p_booking,p_referral,COALESCE(p_snapshot,0),p_compensates,v_shortfall,
   v_ctx.admin_id,p_reason,v_ctx.command_at,nextval('loyalty.ledger_sequence_seq'),p_key,p_requested,v_balance,v_after::integer,
   p_event,p_config_at,p_config,v_ctx.correlation_id,v_audit,v_outbox);
 PERFORM loyalty.leave_write(v_token);
 v_token:=loyalty.enter_write('loyalty.points_account',p_user::text);
 UPDATE loyalty.points_account SET balance=v_after::integer,updated_at=v_ctx.command_at WHERE user_id=p_user;
 PERFORM loyalty.leave_write(v_token);
 RETURN v_id;
END;
$function$;

-- One source mapping, reusing Trust's canonical outcome resolver rather than a second correction algorithm.
-- Prefer the immutable successful-completion history. A non-completed original
-- outcome has no such row; its original final-resolution instant is retained as
-- the explicit source-mapping fallback (documented in SOURCE-DECISIONS.md).
CREATE OR REPLACE FUNCTION loyalty.booking_completion_anchor(p_booking uuid)
RETURNS timestamptz LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE t timestamptz;
BEGIN
 SELECT h.occurred_at INTO t FROM booking.booking_history h
 WHERE h.booking_id=p_booking AND h.entry_kind='STATUS_TRANSITION' AND h.to_status='COMPLETED'
 ORDER BY h.sequence,h.id LIMIT 1;
 IF FOUND THEN RETURN t; END IF;
 SELECT e.occurred_at INTO t FROM trust.trust_event e WHERE e.booking_id=p_booking AND e.event_type IN
 ('BOOKING_ATTENDED','BOOKING_ATTENDANCE_UNCONFIRMED','BOOKING_ATTENDED_INTERRUPTED','BOOKING_NO_SHOW');
 IF NOT FOUND THEN RAISE EXCEPTION 'Original outcome/completion source is missing'; END IF;
 RETURN t;
END;
$function$;

CREATE OR REPLACE FUNCTION loyalty.booking_reward_basis(p_booking uuid)
RETURNS TABLE(user_id uuid,original_event_id uuid,current_event_id uuid,current_type text,
 configuration_as_of timestamptz,configuration_version_id uuid,reward_value integer)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE b booking.booking%ROWTYPE; orig trust.trust_event%ROWTYPE; eff record; cfg record; origin_at timestamptz;
BEGIN
 SELECT * INTO b FROM booking.booking WHERE id=p_booking;
 IF NOT FOUND OR b.source<>'ONLINE' OR b.customer_id IS NULL THEN RAISE EXCEPTION 'Only Online customer Bookings can earn Points'; END IF;
 SELECT * INTO orig FROM trust.trust_event e WHERE e.booking_id=p_booking AND e.event_type IN
  ('BOOKING_ATTENDED','BOOKING_ATTENDANCE_UNCONFIRMED','BOOKING_ATTENDED_INTERRUPTED','BOOKING_NO_SHOW');
 IF NOT FOUND THEN RETURN; END IF;
 SELECT ce.* INTO STRICT eff FROM trust.canonical_trust_effects(b.customer_id) ce
 JOIN trust.trust_event te ON te.id=ce.effect_event_id
 WHERE te.booking_id=p_booking AND ce.effect_type IN
  ('BOOKING_ATTENDED','BOOKING_ATTENDANCE_UNCONFIRMED','BOOKING_ATTENDED_INTERRUPTED','BOOKING_NO_SHOW');
 origin_at:=loyalty.booking_completion_anchor(p_booking);
 SELECT * INTO STRICT cfg FROM loyalty.configuration_at('loyalty.attended_points',origin_at);
 RETURN QUERY SELECT b.customer_id,orig.id,eff.effect_event_id,eff.effect_type,origin_at,cfg.version_id,
  loyalty.config_integer('loyalty.attended_points',origin_at);
END;
$function$;

CREATE OR REPLACE FUNCTION loyalty.reconcile_booking(p_booking uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE
 basis record; ctx record; prev loyalty.reward_application%ROWTYPE; oldgrant loyalty.points_transaction%ROWTYPE;
 ev trust.trust_event%ROWTYPE; cfg record; desired integer; prior integer; paid bigint;
 req integer:=0; tranche integer:=0; tx uuid; app uuid:=gen_random_uuid(); tok uuid; ky text; why text; source_admin uuid;
BEGIN
 SELECT * INTO basis FROM loyalty.booking_reward_basis(p_booking);
 IF NOT FOUND THEN RAISE EXCEPTION 'Canonical Booking outcome is not yet available'; END IF;
 SELECT * INTO STRICT ctx FROM loyalty.command_context(basis.user_id);
 PERFORM trust.command_now(basis.user_id);
 ky:='BOOKING:'||basis.current_event_id::text;
 SELECT a.id INTO app FROM loyalty.reward_application a WHERE a.operation_key=ky;
 IF FOUND THEN RETURN app; END IF;
 app:=gen_random_uuid();
 SELECT * INTO prev FROM loyalty.reward_application a WHERE a.booking_id=p_booking ORDER BY a.application_sequence DESC LIMIT 1;
 prior:=CASE WHEN FOUND THEN prev.entitlement_after ELSE 0 END;
 desired:=CASE WHEN basis.current_type='BOOKING_ATTENDED' THEN basis.reward_value ELSE 0 END;
 SELECT * INTO STRICT ev FROM trust.trust_event WHERE id=basis.current_event_id;
 IF ev.occurred_at>ctx.command_at THEN RAISE EXCEPTION 'Cannot reconcile a future source'; END IF;
 IF ev.event_type IN ('ATTENDANCE_CORRECTED','NO_SHOW_REVERSED') THEN
   SELECT a.actor_id,a.reason INTO source_admin,why FROM audit.audit_event a
    WHERE a.subject_type='BOOKING' AND a.subject_id=p_booking AND a.actor_type='ADMIN'
      AND a.action=ev.event_type AND a.occurred_at=ev.occurred_at AND a.correlation_id=ctx.correlation_id
      AND ev.occurred_at=ctx.command_at AND NULLIF(btrim(a.reason),'') IS NOT NULL
    ORDER BY a.id LIMIT 1;
   IF source_admin IS NULL OR ctx.admin_id IS DISTINCT FROM source_admin THEN
     RAISE EXCEPTION 'Attendance reward correction requires its audited Admin identity in the Loyalty command';
   END IF;
 ELSE why:='Canonical attended-outcome reward reconciliation'; END IF;
 SELECT * INTO oldgrant FROM loyalty.points_transaction t WHERE t.booking_id=p_booking AND t.cause='ATTENDED_COMPLETION';
 SELECT COALESCE(sum(t.amount::bigint),0) INTO paid FROM loyalty.points_transaction t WHERE t.booking_id=p_booking;
 IF paid<0 OR paid>basis.reward_value THEN RAISE EXCEPTION 'Booking reward monetary history is inconsistent'; END IF;
 IF desired>prior THEN req:=GREATEST(desired-paid,0)::integer;
 ELSIF desired<prior THEN
   -- A written-off shortfall never becomes collectible debt on a later toggle.
   -- Only the actually credited tranche of the last eligibility restoration is reversible.
   SELECT COALESCE(pt.amount,0) INTO tranche FROM loyalty.reward_application ra
     LEFT JOIN loyalty.points_transaction pt ON pt.id=ra.points_transaction_id
    WHERE ra.booking_id=p_booking AND ra.entitlement_before=0 AND ra.entitlement_after>0
    ORDER BY ra.application_sequence DESC LIMIT 1;
   req:=-COALESCE(tranche,0);
 END IF;
 -- No-op source corrections are still recorded as applications, not duplicate rewards.
 IF req<>0 OR (desired>0 AND oldgrant.id IS NULL) THEN
   tx:=loyalty.post_points(basis.user_id,req,CASE WHEN oldgrant.id IS NULL THEN 'ATTENDED_COMPLETION' ELSE 'COMPENSATION' END,
     ky,p_booking,NULL,basis.current_event_id,oldgrant.id,basis.reward_value,basis.configuration_version_id,basis.configuration_as_of,why);
 END IF;
 tok:=loyalty.enter_write('loyalty.reward_application',app::text);
 INSERT INTO loyalty.reward_application(id,application_sequence,source_kind,booking_id,source_event_id,user_id,operation_key,
  previous_application_id,entitlement_before,entitlement_after,reward_value,configuration_as_of,configuration_version_id,
  points_transaction_id,applied_at,correlation_id)
 VALUES(app,nextval('loyalty.application_sequence_seq'),'BOOKING',p_booking,basis.current_event_id,basis.user_id,ky,
   prev.id,prior,desired,basis.reward_value,basis.configuration_as_of,basis.configuration_version_id,tx,ctx.command_at,ctx.correlation_id);
 PERFORM loyalty.leave_write(tok);
 RETURN app;
END;
$function$;

CREATE OR REPLACE FUNCTION loyalty.adjust_points(p_user uuid,p_amount integer,p_request_id uuid,p_reason text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE ctx record;
BEGIN
 SELECT * INTO STRICT ctx FROM loyalty.command_context(p_user);
 IF ctx.admin_id IS NULL OR p_request_id IS NULL OR p_amount IS NULL OR p_amount=0 OR NULLIF(btrim(p_reason),'') IS NULL THEN
   RAISE EXCEPTION 'Points adjustment requires current Admin, nonzero amount, request ID and reason';
 END IF;
 RETURN loyalty.post_points(p_user,p_amount,'ADMIN','ADMIN:'||ctx.admin_id::text||':'||p_request_id::text,
  NULL,NULL,NULL,NULL,0,NULL,NULL,p_reason);
END;
$function$;

CREATE OR REPLACE FUNCTION loyalty.initialize_user()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE tok uuid; inv iam.user_account%ROWTYPE; rid uuid:=gen_random_uuid(); v_code text;
BEGIN
 tok:=loyalty.enter_write('loyalty.points_account',NEW.id::text);
 INSERT INTO loyalty.points_account(user_id,balance,updated_at) VALUES(NEW.id,0,clock_timestamp());
 PERFORM loyalty.leave_write(tok);
 tok:=loyalty.enter_write('loyalty.wallet_account',NEW.id::text);
 INSERT INTO loyalty.wallet_account(user_id,balance,updated_at) VALUES(NEW.id,0,clock_timestamp());
 PERFORM loyalty.leave_write(tok);
 v_code:=NULLIF(btrim(NEW.referred_by_code),'');
 IF v_code IS NOT NULL THEN
   SELECT * INTO inv FROM iam.user_account u WHERE u.referral_code=v_code;
   tok:=loyalty.enter_write('loyalty.referral',rid::text);
   IF inv.id IS NULL THEN
     INSERT INTO loyalty.referral(id,referred_user_id,code,status,created_at,invalidated_at,invalidation_kind,invalidation_reason,fraud_signals)
     VALUES(rid,NEW.id,v_code,'INVALID',clock_timestamp(),clock_timestamp(),'INVALID_CODE','Unrecognized referral code','{}');
   ELSIF inv.id=NEW.id OR inv.phone_e164=NEW.phone_e164 OR lower(btrim(inv.email))=lower(btrim(NEW.email)) THEN
     INSERT INTO loyalty.referral(id,referrer_user_id,referred_user_id,code,status,created_at,invalidated_at,invalidation_kind,invalidation_reason,fraud_signals)
     VALUES(rid,inv.id,NEW.id,v_code,'INVALID',clock_timestamp(),clock_timestamp(),'SELF_REFERRAL','Self-referral identity match','{}');
   ELSE
     INSERT INTO loyalty.referral(id,referrer_user_id,referred_user_id,code,status,created_at,fraud_signals)
     VALUES(rid,inv.id,NEW.id,v_code,'PENDING',clock_timestamp(),'{}');
   END IF;
   PERFORM loyalty.leave_write(tok);
 END IF;
 RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION loyalty.reward_referral(p_referral uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE r loyalty.referral%ROWTYPE; u iam.user_account%ROWTYPE; inv iam.user_account%ROWTYPE;
 ctx record; cfg record; amt integer; tx uuid; app uuid:=gen_random_uuid(); tok uuid; aid uuid;
BEGIN
 SELECT * INTO STRICT r FROM loyalty.referral WHERE id=p_referral;
 IF r.referrer_user_id IS NULL OR r.status='INVALID' THEN RETURN NULL; END IF;
 SELECT * INTO STRICT ctx FROM loyalty.command_context(r.referrer_user_id);
 PERFORM loyalty.command_context(r.referred_user_id);
 SELECT * INTO STRICT r FROM loyalty.referral WHERE id=p_referral FOR UPDATE;
 IF r.status='REWARDED' THEN SELECT id INTO app FROM loyalty.reward_application WHERE operation_key='REFERRAL_REWARD:'||r.id::text; RETURN app; END IF;
 SELECT * INTO STRICT u FROM iam.user_account WHERE id=r.referred_user_id;
 SELECT * INTO STRICT inv FROM iam.user_account WHERE id=r.referrer_user_id;
 IF NOT u.phone_verified OR u.phone_verified_at IS NULL THEN RAISE EXCEPTION 'OTP account verification is required before referral reward'; END IF;
 IF u.phone_verified_at>ctx.command_at THEN RAISE EXCEPTION 'Future verification instant'; END IF;
 IF inv.referral_code IS DISTINCT FROM r.code OR NULLIF(btrim(u.referred_by_code),'') IS DISTINCT FROM r.code THEN RAISE EXCEPTION 'Referral code/owner mismatch'; END IF;
 IF inv.id=u.id OR inv.phone_e164=u.phone_e164 OR lower(btrim(inv.email))=lower(btrim(u.email)) THEN
   tok:=loyalty.enter_write('loyalty.referral',r.id::text);
   UPDATE loyalty.referral SET status='INVALID',invalidated_at=ctx.command_at,invalidation_kind='SELF_REFERRAL',invalidation_reason='Self-referral identity match at OTP verification',correlation_id=ctx.correlation_id WHERE id=r.id;
   PERFORM loyalty.leave_write(tok);
   RETURN NULL;
 END IF;
 SELECT * INTO STRICT cfg FROM loyalty.configuration_at('loyalty.referral_points',u.phone_verified_at);
 amt:=loyalty.config_integer('loyalty.referral_points',u.phone_verified_at);
 tx:=loyalty.post_points(r.referrer_user_id,amt,'REFERRAL_SIGNUP','REFERRAL_REWARD:'||r.id::text,
  NULL,r.id,NULL,NULL,amt,cfg.version_id,u.phone_verified_at,'Referral became eligible at Account OTP verification');
 tok:=loyalty.enter_write('loyalty.referral',r.id::text);
 UPDATE loyalty.referral SET status='REWARDED',reward_value_applied=amt,rewarded_at=ctx.command_at,
  verified_at_snapshot=u.phone_verified_at,configuration_version_id=cfg.version_id,correlation_id=ctx.correlation_id WHERE id=r.id;
 PERFORM loyalty.leave_write(tok);
 tok:=loyalty.enter_write('loyalty.reward_application',app::text);
 INSERT INTO loyalty.reward_application(id,application_sequence,source_kind,referral_id,user_id,operation_key,entitlement_before,
  entitlement_after,reward_value,configuration_as_of,configuration_version_id,points_transaction_id,applied_at,correlation_id)
 VALUES(app,nextval('loyalty.application_sequence_seq'),'REFERRAL',r.id,r.referrer_user_id,'REFERRAL_REWARD:'||r.id::text,
  0,amt,amt,u.phone_verified_at,cfg.version_id,tx,ctx.command_at,ctx.correlation_id);
 PERFORM loyalty.leave_write(tok);
 RETURN app;
END;
$function$;

CREATE OR REPLACE FUNCTION loyalty.invalidate_referral(p_referral uuid,p_reason text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE r loyalty.referral%ROWTYPE; ctx record; prev loyalty.reward_application%ROWTYPE; orig loyalty.points_transaction%ROWTYPE;
 tx uuid; app uuid:=gen_random_uuid(); tok uuid; aud uuid;
BEGIN
 SELECT * INTO STRICT r FROM loyalty.referral WHERE id=p_referral;
 IF r.referrer_user_id IS NULL THEN RAISE EXCEPTION 'Unknown-code referral is already invalid'; END IF;
 SELECT * INTO STRICT ctx FROM loyalty.command_context(r.referrer_user_id);
 PERFORM loyalty.command_context(r.referred_user_id);
 IF ctx.admin_id IS NULL OR NULLIF(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'Referral invalidation requires an Admin and reason'; END IF;
 SELECT * INTO STRICT r FROM loyalty.referral WHERE id=p_referral FOR UPDATE;
 IF r.status='INVALID' THEN
   IF r.invalidated_by_admin_id IS DISTINCT FROM ctx.admin_id OR r.invalidation_reason IS DISTINCT FROM p_reason THEN RAISE EXCEPTION 'Referral already invalidated with different provenance'; END IF;
   SELECT id INTO app FROM loyalty.reward_application WHERE operation_key='REFERRAL_INVALIDATE:'||r.id::text;
   RETURN app;
 END IF;
 aud:=loyalty.write_audit(r.referrer_user_id,'REFERRAL_INVALIDATED',p_reason,jsonb_build_object('referralId',r.id,'priorStatus',r.status));
 IF r.status='REWARDED' THEN
   SELECT * INTO STRICT orig FROM loyalty.points_transaction WHERE referral_id=r.id AND cause='REFERRAL_SIGNUP';
   SELECT * INTO STRICT prev FROM loyalty.reward_application WHERE referral_id=r.id ORDER BY application_sequence DESC LIMIT 1;
   tx:=loyalty.post_points(r.referrer_user_id,-r.reward_value_applied,'COMPENSATION','REFERRAL_INVALIDATE:'||r.id::text,
      NULL,r.id,NULL,orig.id,r.reward_value_applied,r.configuration_version_id,r.verified_at_snapshot,p_reason);
   tok:=loyalty.enter_write('loyalty.reward_application',app::text);
   INSERT INTO loyalty.reward_application(id,application_sequence,source_kind,referral_id,user_id,operation_key,
    previous_application_id,entitlement_before,entitlement_after,reward_value,configuration_as_of,configuration_version_id,
    points_transaction_id,applied_at,correlation_id)
   VALUES(app,nextval('loyalty.application_sequence_seq'),'REFERRAL',r.id,r.referrer_user_id,'REFERRAL_INVALIDATE:'||r.id::text,
    prev.id,r.reward_value_applied,0,r.reward_value_applied,r.verified_at_snapshot,r.configuration_version_id,tx,ctx.command_at,ctx.correlation_id);
   PERFORM loyalty.leave_write(tok);
 ELSE app:=NULL;
 END IF;
 tok:=loyalty.enter_write('loyalty.referral',r.id::text);
 UPDATE loyalty.referral SET status='INVALID',invalidated_at=ctx.command_at,invalidated_by_admin_id=ctx.admin_id,
   invalidation_kind='ADMIN_FRAUD',invalidation_reason=p_reason,invalidation_audit_id=aud,correlation_id=ctx.correlation_id WHERE id=r.id;
 PERFORM loyalty.leave_write(tok);
 RETURN app;
END;
$function$;

-- Existing reason mapping is retained. The monetary decision additionally checks
-- the immutable fee, exact history record, time window and Admin service-loss attestation.
CREATE OR REPLACE FUNCTION loyalty.refund_basis(p_booking uuid,p_history uuid,p_loss_audit uuid DEFAULT NULL)
RETURNS TABLE(user_id uuid,treatment text,terminal_reason text,fee_snapshot numeric,decision_at timestamptz,refund_amount numeric)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE b booking.booking%ROWTYPE; h booking.booking_history%ROWTYPE; tr text; rs text; am numeric;
BEGIN
 SELECT * INTO STRICT b FROM booking.booking WHERE id=p_booking;
 IF b.source<>'ONLINE' OR b.customer_id IS NULL THEN RAISE EXCEPTION 'Manual Booking has no customer refund ledger'; END IF;
 SELECT * INTO STRICT h FROM booking.booking_history WHERE id=p_history;
 IF h.booking_id IS DISTINCT FROM b.id THEN RAISE EXCEPTION 'Refund history belongs to another Booking'; END IF;
 IF h.entry_kind='STATUS_TRANSITION' AND h.to_status IN ('CANCELLED','REJECTED') THEN
   IF b.status IS DISTINCT FROM h.to_status OR b.terminal_reason IS DISTINCT FROM h.terminal_reason THEN RAISE EXCEPTION 'Refund requires the current immutable terminal outcome'; END IF;
   rs:=h.terminal_reason;
 ELSIF h.entry_kind='BOOKING_EVENT' AND h.event_type='NO_SHOW_REVERSED' THEN
   rs:='ADMIN_NO_SHOW_REVERSAL';
 ELSE RAISE EXCEPTION 'Attendance reclassification is not a refund trigger';
 END IF;
 tr:=booking.expected_fee_treatment(rs);
 IF tr IS NULL THEN RAISE EXCEPTION 'Unknown fee treatment'; END IF;
 IF rs IN ('ADMIN_CANCELLED','ADMIN_CORRECTION','ADMIN_NO_SHOW_REVERSAL') THEN
   IF p_loss_audit IS NULL OR NOT EXISTS(
    SELECT 1 FROM audit.audit_event a JOIN iam.admin_account adm ON adm.id=a.actor_id
     WHERE a.id=p_loss_audit AND a.subject_type='BOOKING' AND a.subject_id=b.id
       AND a.actor_type='ADMIN' AND a.action='BOOKING_SERVICE_LOSS_CONFIRMED'
       AND a.payload->>'bookingHistoryId'=h.id::text
       AND a.payload->'customerAtFault'='false'::jsonb AND a.payload->'serviceLoss'='true'::jsonb
       AND NULLIF(btrim(a.reason),'') IS NOT NULL
   ) THEN RAISE EXCEPTION 'Admin refund requires audited non-customer-fault service loss; reclassification alone is insufficient'; END IF;
 ELSIF p_loss_audit IS NOT NULL THEN RAISE EXCEPTION 'Unnecessary Admin service-loss override';
 END IF;
 am:=CASE WHEN tr='FULL_REFUND' THEN b.booking_fee_snapshot
      WHEN tr='CUSTOMER_POLICY' AND h.occurred_at<=b.created_at+interval '15 minutes' AND h.occurred_at<b.start_at THEN b.booking_fee_snapshot
      ELSE 0 END;
 IF am<0 OR am>b.booking_fee_snapshot OR am='NaN'::numeric THEN RAISE EXCEPTION 'Invalid fee amount'; END IF;
 RETURN QUERY SELECT b.customer_id,tr,rs,b.booking_fee_snapshot,h.occurred_at,am;
END;
$function$;

CREATE OR REPLACE FUNCTION loyalty.confirm_service_loss(p_booking uuid,p_history uuid,p_reason text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE b booking.booking%ROWTYPE; h booking.booking_history%ROWTYPE; ctx record; v_id uuid:=gen_random_uuid(); v_tok uuid;
BEGIN
 SELECT * INTO STRICT b FROM booking.booking WHERE id=p_booking;
 SELECT * INTO STRICT ctx FROM loyalty.command_context(b.customer_id);
 IF ctx.admin_id IS NULL OR NULLIF(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'Service-loss assessment requires Admin and reason'; END IF;
 SELECT * INTO STRICT h FROM booking.booking_history WHERE id=p_history AND booking_id=p_booking;
 IF NOT ((h.entry_kind='STATUS_TRANSITION' AND h.terminal_reason IN ('ADMIN_CANCELLED','ADMIN_CORRECTION','ADMIN_NO_SHOW_REVERSAL'))
      OR (h.entry_kind='BOOKING_EVENT' AND h.event_type='NO_SHOW_REVERSED')) THEN RAISE EXCEPTION 'Not an eligible Admin service-loss history'; END IF;
 SELECT au.id INTO v_id FROM audit.audit_event au WHERE au.action='BOOKING_SERVICE_LOSS_CONFIRMED'
   AND au.subject_type='BOOKING' AND au.subject_id=b.id AND au.actor_type='ADMIN' AND au.actor_id=ctx.admin_id
   AND au.reason=p_reason AND au.payload->>'bookingHistoryId'=h.id::text
   AND au.payload->'serviceLoss'='true'::jsonb AND au.payload->'customerAtFault'='false'::jsonb
   ORDER BY au.occurred_at,au.id LIMIT 1;
 IF FOUND THEN RETURN v_id; END IF;
 v_id:=gen_random_uuid();
 v_tok:=loyalty.enter_write('audit.audit_event',v_id::text);
 INSERT INTO audit.audit_event(id,occurred_at,actor_type,actor_id,action,subject_type,subject_id,reason,correlation_id,payload)
 VALUES(v_id,ctx.command_at,'ADMIN',ctx.admin_id,'BOOKING_SERVICE_LOSS_CONFIRMED','BOOKING',b.id,p_reason,ctx.correlation_id,
  jsonb_build_object('bookingHistoryId',h.id,'serviceLoss',true,'customerAtFault',false));
 PERFORM loyalty.leave_write(v_tok);
 RETURN v_id;
END;
$function$;

CREATE OR REPLACE FUNCTION loyalty.settle_refund(p_refund uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE f loyalty.booking_fee_refund%ROWTYPE; rec loyalty.booking_fee_receipt%ROWTYPE;
 ctx record; bal numeric; wid uuid:=gen_random_uuid(); aid uuid; oid bigint; tok uuid; py jsonb;
BEGIN
 SELECT * INTO STRICT f FROM loyalty.booking_fee_refund WHERE id=p_refund;
 SELECT * INTO STRICT ctx FROM loyalty.command_context(f.user_id);
 SELECT * INTO STRICT f FROM loyalty.booking_fee_refund WHERE id=p_refund FOR UPDATE;
 IF f.wallet_transaction_id IS NOT NULL THEN RETURN f.wallet_transaction_id; END IF;
 IF f.amount=0 THEN RETURN NULL; END IF;
 SELECT * INTO rec FROM loyalty.booking_fee_receipt WHERE booking_id=f.booking_id;
 -- A refund obligation may wait for a verified collection receipt; it is not a fabricated Wallet credit.
 IF NOT FOUND THEN RETURN NULL; END IF;
 -- An already-collected fee remains refundable even if NEW collection is subsequently disabled.
 IF rec.user_id IS DISTINCT FROM f.user_id OR rec.amount<>f.fee_snapshot OR f.amount>rec.amount THEN RAISE EXCEPTION 'Refund collection proof mismatch'; END IF;
 SELECT a.balance INTO STRICT bal FROM loyalty.wallet_account a WHERE a.user_id=f.user_id FOR UPDATE;
 py:=jsonb_build_object('walletTransactionId',wid,'refundId',f.id,'receiptId',rec.id,'bookingId',f.booking_id,'amount',f.amount,'balanceBefore',bal,'balanceAfter',bal+f.amount);
 aid:=loyalty.write_audit(f.user_id,'BOOKING_FEE_REFUND_CREDITED','Audited Booking Fee refund',py);
 oid:=loyalty.write_outbox(f.user_id,'LOYALTY_WALLET_LEDGER_COMMITTED',wid,py);
 tok:=loyalty.enter_write('loyalty.wallet_transaction',wid::text);
 INSERT INTO loyalty.wallet_transaction(id,wallet_account_id,amount,cause,booking_id,occurred_at,ledger_sequence,operation_key,
  refund_id,receipt_id,balance_before,balance_after,correlation_id,audit_event_id,outbox_event_id)
 VALUES(wid,f.user_id,f.amount,'BOOKING_FEE_REFUND',f.booking_id,ctx.command_at,nextval('loyalty.ledger_sequence_seq'),
  'FEE_REFUND:'||f.id::text,f.id,rec.id,bal,bal+f.amount,ctx.correlation_id,aid,oid);
 PERFORM loyalty.leave_write(tok);
 tok:=loyalty.enter_write('loyalty.wallet_account',f.user_id::text);
 UPDATE loyalty.wallet_account SET balance=bal+f.amount,updated_at=ctx.command_at WHERE user_id=f.user_id;
 PERFORM loyalty.leave_write(tok);
 tok:=loyalty.enter_write('loyalty.booking_fee_refund',f.id::text);
 UPDATE loyalty.booking_fee_refund SET receipt_id=rec.id,wallet_transaction_id=wid,settled_at=ctx.command_at WHERE id=f.id;
 PERFORM loyalty.leave_write(tok);
 RETURN wid;
END;
$function$;

CREATE OR REPLACE FUNCTION loyalty.record_refund(p_booking uuid,p_history uuid,p_loss_audit uuid DEFAULT NULL)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE bas record; ctx record; f loyalty.booking_fee_refund%ROWTYPE; tok uuid; fid uuid:=gen_random_uuid(); aid uuid;
BEGIN
 SELECT * INTO STRICT bas FROM loyalty.refund_basis(p_booking,p_history,p_loss_audit);
 SELECT * INTO STRICT ctx FROM loyalty.command_context(bas.user_id);
 SELECT * INTO f FROM loyalty.booking_fee_refund WHERE booking_id=p_booking;
 IF FOUND THEN
   IF f.booking_history_id IS DISTINCT FROM p_history OR f.service_loss_audit_id IS DISTINCT FROM p_loss_audit
      OR f.amount IS DISTINCT FROM bas.refund_amount THEN RAISE EXCEPTION 'One refund decision per Booking; changed evidence is not a retry'; END IF;
   PERFORM loyalty.settle_refund(f.id);
   RETURN f.id;
 END IF;
 aid:=loyalty.write_audit(bas.user_id,'BOOKING_FEE_REFUND_DECIDED','Canonical Booking Fee policy',
   jsonb_build_object('refundId',fid,'bookingId',p_booking,'bookingHistoryId',p_history,'serviceLossAuditId',p_loss_audit,
     'feeSnapshot',bas.fee_snapshot,'treatment',bas.treatment,'amount',bas.refund_amount));
 tok:=loyalty.enter_write('loyalty.booking_fee_refund',fid::text);
 INSERT INTO loyalty.booking_fee_refund(id,booking_id,treatment,amount,terminal_reason,occurred_at,user_id,booking_history_id,
   service_loss_audit_id,fee_snapshot,decision_at,correlation_id,audit_event_id)
 VALUES(fid,p_booking,bas.treatment,bas.refund_amount,bas.terminal_reason,ctx.command_at,bas.user_id,p_history,p_loss_audit,
   bas.fee_snapshot,bas.decision_at,ctx.correlation_id,aid);
 PERFORM loyalty.leave_write(tok);
 PERFORM loyalty.settle_refund(fid);
 RETURN fid;
END;
$function$;

-- This API is granted ONLY to the authenticated settlement adapter role.
CREATE OR REPLACE FUNCTION loyalty.record_fee_receipt(p_booking uuid,p_amount numeric,p_provider text,p_reference text,p_provider_at timestamptz)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE b booking.booking%ROWTYPE; ctx record; oldr loyalty.booking_fee_receipt%ROWTYPE;
 rid uuid:=gen_random_uuid(); tok uuid; aid uuid; fid uuid;
BEGIN
 SELECT * INTO STRICT b FROM booking.booking WHERE id=p_booking;
 SELECT * INTO STRICT ctx FROM loyalty.command_context(b.customer_id);
 IF b.source<>'ONLINE' OR p_amount IS NULL OR p_amount<>b.booking_fee_snapshot OR p_amount<=0 OR p_amount='NaN'::numeric
   OR p_amount<>round(p_amount,2) OR p_provider_at IS NULL OR p_provider_at<b.created_at OR p_provider_at>ctx.command_at
   OR NULLIF(btrim(p_provider),'') IS NULL OR NULLIF(btrim(p_reference),'') IS NULL THEN RAISE EXCEPTION 'Invalid verified fee receipt'; END IF;
 SELECT * INTO oldr FROM loyalty.booking_fee_receipt WHERE booking_id=p_booking;
 IF FOUND THEN
  IF oldr.amount IS DISTINCT FROM p_amount OR oldr.provider IS DISTINCT FROM p_provider
     OR oldr.provider_reference IS DISTINCT FROM p_reference OR oldr.provider_occurred_at IS DISTINCT FROM p_provider_at THEN
    RAISE EXCEPTION 'Booking fee receipt is immutable; different payment is not an idempotent retry';
  END IF;
  RETURN oldr.id;
 END IF;
 IF NOT loyalty.wallet_enabled(ctx.command_at) THEN RAISE EXCEPTION 'Payment/refund integration is disabled at Launch'; END IF;
 aid:=loyalty.write_audit(b.customer_id,'BOOKING_FEE_COLLECTION_RECORDED','Verified settlement adapter receipt',
  jsonb_build_object('receiptId',rid,'bookingId',b.id,'amount',p_amount,'provider',p_provider,'providerReference',p_reference,'providerOccurredAt',p_provider_at));
 tok:=loyalty.enter_write('loyalty.booking_fee_receipt',rid::text);
 INSERT INTO loyalty.booking_fee_receipt(id,booking_id,user_id,amount,currency,provider,provider_reference,provider_occurred_at,received_at,correlation_id,audit_event_id)
 VALUES(rid,b.id,b.customer_id,p_amount,'EGP',p_provider,p_reference,p_provider_at,ctx.command_at,ctx.correlation_id,aid);
 PERFORM loyalty.leave_write(tok);
 SELECT id INTO fid FROM loyalty.booking_fee_refund WHERE booking_id=b.id;
 IF FOUND THEN PERFORM loyalty.settle_refund(fid); END IF;
 RETURN rid;
END;
$function$;

CREATE OR REPLACE FUNCTION loyalty.referral_mutation_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF OLD.status='INVALID' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'INVALID Referral is terminal'; END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.referrer_user_id IS DISTINCT FROM OLD.referrer_user_id
    OR NEW.referred_user_id IS DISTINCT FROM OLD.referred_user_id OR NEW.code IS DISTINCT FROM OLD.code
    OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN RAISE EXCEPTION 'Referral identity cannot be rewritten'; END IF;
  IF OLD.rewarded_at IS NOT NULL AND (NEW.rewarded_at IS DISTINCT FROM OLD.rewarded_at
    OR NEW.reward_value_applied IS DISTINCT FROM OLD.reward_value_applied OR NEW.verified_at_snapshot IS DISTINCT FROM OLD.verified_at_snapshot
    OR NEW.configuration_version_id IS DISTINCT FROM OLD.configuration_version_id) THEN RAISE EXCEPTION 'Historical referral grant cannot be rewritten'; END IF;
  IF NOT ((OLD.status='PENDING' AND NEW.status IN ('REWARDED','INVALID')) OR (OLD.status='REWARDED' AND NEW.status='INVALID') OR NEW IS NOT DISTINCT FROM OLD) THEN
    RAISE EXCEPTION 'Invalid Referral transition'; END IF;
 END IF;
 RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION loyalty.refund_mutation_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF OLD.wallet_transaction_id IS NOT NULL OR
   (to_jsonb(NEW)-ARRAY['receipt_id','wallet_transaction_id','settled_at']) IS DISTINCT FROM
   (to_jsonb(OLD)-ARRAY['receipt_id','wallet_transaction_id','settled_at']) OR
   NEW.wallet_transaction_id IS NULL OR NEW.receipt_id IS NULL OR NEW.settled_at IS NULL THEN
    RAISE EXCEPTION 'Refund decision is immutable; only a one-time verified settlement is permitted';
  END IF;
 END IF;
 RETURN NEW;
END;
$function$;

-- Loyalty config writes are serialized and apply to future events only.
CREATE OR REPLACE FUNCTION loyalty.configure(p_key text,p_value jsonb,p_admin uuid,p_request uuid,p_reason text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE now_at timestamptz; existing config.configuration_version%ROWTYPE; oldv jsonb; tok uuid; aid uuid:=gen_random_uuid();
BEGIN
 IF p_key IS NULL OR p_key NOT IN ('loyalty.attended_points','loyalty.referral_points','loyalty.wallet_refunds_enabled')
    OR p_request IS NULL OR NULLIF(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'Invalid configuration command'; END IF;
 PERFORM a.id FROM iam.admin_account a WHERE a.id=p_admin AND a.is_active FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Active Admin required'; END IF;
 IF p_key='loyalty.wallet_refunds_enabled' THEN
   IF jsonb_typeof(p_value) IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Expected Boolean feature flag'; END IF;
 ELSE
   IF jsonb_typeof(p_value) IS DISTINCT FROM 'number' OR p_value::text !~ '^[0-9]+$' OR p_value::text::numeric>2147483647 THEN RAISE EXCEPTION 'Expected nonnegative bounded integer'; END IF;
 END IF;
 IF to_regclass('pg_temp.e7gz_tournament_command_context') IS NOT NULL THEN RAISE EXCEPTION 'Configuration is a separate Admin transaction, not a mid-business-command change'; END IF;
 PERFORM pg_advisory_xact_lock(1123,1);
 SELECT * INTO existing FROM config.configuration_version WHERE id=p_request;
 IF FOUND THEN
  IF existing.key IS DISTINCT FROM p_key OR existing.new_value IS DISTINCT FROM p_value OR existing.admin_id IS DISTINCT FROM p_admin OR existing.reason IS DISTINCT FROM p_reason THEN RAISE EXCEPTION 'Config request ID reused'; END IF;
  RETURN existing.id;
 END IF;
 now_at:=clock_timestamp();
 SELECT value INTO oldv FROM config.system_configuration WHERE key=p_key;
 tok:=loyalty.enter_write('config.configuration_version',p_request::text);
 INSERT INTO config.configuration_version(id,key,old_value,new_value,effective_from,admin_id,reason)
 VALUES(p_request,p_key,oldv,p_value,now_at,p_admin,p_reason);
 PERFORM loyalty.leave_write(tok);
 tok:=loyalty.enter_write('config.system_configuration',p_key);
 INSERT INTO config.system_configuration(key,value,updated_at) VALUES(p_key,p_value,now_at)
 ON CONFLICT(key) DO UPDATE SET value=EXCLUDED.value,updated_at=EXCLUDED.updated_at;
 PERFORM loyalty.leave_write(tok);
 tok:=loyalty.enter_write('audit.audit_event',aid::text);
 INSERT INTO audit.audit_event(id,occurred_at,actor_type,actor_id,action,subject_type,subject_id,reason,correlation_id,payload)
 VALUES(aid,now_at,'ADMIN',p_admin,'LOYALTY_CONFIGURATION_CHANGED','CONFIGURATION',p_request,p_reason,p_request,
   jsonb_build_object('key',p_key,'oldValue',oldv,'newValue',p_value));
 PERFORM loyalty.leave_write(tok);
 RETURN p_request;
END;
$function$;
CREATE OR REPLACE FUNCTION loyalty.config_write_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE k text;
BEGIN
 IF TG_OP='DELETE' THEN k:=OLD.key; ELSE k:=NEW.key; END IF;
 IF k IN ('loyalty.attended_points','loyalty.referral_points','loyalty.wallet_refunds_enabled') OR
    (TG_OP='UPDATE' AND OLD.key IN ('loyalty.attended_points','loyalty.referral_points','loyalty.wallet_refunds_enabled')) THEN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Loyalty config history cannot be removed'; END IF;
  IF TG_TABLE_NAME='configuration_version' THEN PERFORM loyalty.require_write('config.configuration_version',NEW.id::text);
  ELSE PERFORM loyalty.require_write('config.system_configuration',NEW.key); END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION loyalty.assert_booking(p_booking uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE b booking.booking%ROWTYPE; bas record; a loyalty.reward_application%ROWTYPE;
 f loyalty.booking_fee_refund%ROWTYPE; fb record; last_h uuid; total_paid bigint;
BEGIN
 SELECT * INTO b FROM booking.booking WHERE id=p_booking;
 IF NOT FOUND OR b.source<>'ONLINE' THEN RETURN; END IF;
 SELECT * INTO bas FROM loyalty.booking_reward_basis(p_booking);
 IF FOUND THEN
   SELECT * INTO a FROM loyalty.reward_application x WHERE x.booking_id=p_booking ORDER BY x.application_sequence DESC LIMIT 1;
   IF NOT FOUND OR a.source_event_id IS DISTINCT FROM bas.current_event_id OR a.user_id IS DISTINCT FROM bas.user_id
      OR a.reward_value IS DISTINCT FROM bas.reward_value OR a.configuration_as_of IS DISTINCT FROM bas.configuration_as_of
      OR a.configuration_version_id IS DISTINCT FROM bas.configuration_version_id
      OR a.entitlement_after IS DISTINCT FROM (CASE WHEN bas.current_type='BOOKING_ATTENDED' THEN bas.reward_value ELSE 0 END) THEN
     RAISE EXCEPTION 'Canonical Booking outcome/correction requires final Loyalty reconciliation in the same transaction';
   END IF;
   SELECT COALESCE(sum(t.amount::bigint),0) INTO total_paid FROM loyalty.points_transaction t WHERE t.booking_id=p_booking;
   IF total_paid<0 OR total_paid>bas.reward_value OR (bas.current_type='BOOKING_ATTENDED' AND total_paid<>bas.reward_value) THEN
     RAISE EXCEPTION 'Booking reward is omitted or duplicated';
   END IF;
 ELSIF EXISTS(SELECT 1 FROM loyalty.points_transaction t WHERE t.booking_id=p_booking) OR EXISTS(SELECT 1 FROM loyalty.reward_application x WHERE x.booking_id=p_booking) THEN
   RAISE EXCEPTION 'Booking reward exists without its canonical source';
 END IF;
 -- Every reason-coded terminal Online Booking has an explicit decision, including zero-fee decisions.
 SELECT * INTO f FROM loyalty.booking_fee_refund WHERE booking_id=p_booking;
 IF b.status IN ('CANCELLED','REJECTED') AND f.id IS NULL THEN RAISE EXCEPTION 'Terminal Booking fee decision omitted'; END IF;
 IF f.id IS NOT NULL THEN
   SELECT * INTO STRICT fb FROM loyalty.refund_basis(b.id,f.booking_history_id,f.service_loss_audit_id);
   IF f.user_id IS DISTINCT FROM fb.user_id OR f.treatment IS DISTINCT FROM fb.treatment
      OR f.terminal_reason IS DISTINCT FROM fb.terminal_reason OR f.fee_snapshot IS DISTINCT FROM fb.fee_snapshot
      OR f.amount IS DISTINCT FROM fb.refund_amount OR f.decision_at IS DISTINCT FROM fb.decision_at THEN
     RAISE EXCEPTION 'Stored refund decision differs from the canonical policy';
   END IF;
   IF f.wallet_transaction_id IS NOT NULL AND NOT EXISTS(
      SELECT 1 FROM loyalty.wallet_transaction w JOIN loyalty.booking_fee_receipt rc ON rc.id=w.receipt_id
       WHERE w.id=f.wallet_transaction_id AND w.refund_id=f.id AND w.receipt_id=f.receipt_id
         AND w.wallet_account_id=f.user_id AND w.booking_id=b.id AND w.amount=f.amount AND w.occurred_at=f.settled_at
         AND rc.booking_id=b.id AND rc.user_id=f.user_id AND rc.amount=f.fee_snapshot
   ) THEN RAISE EXCEPTION 'Refund settlement marker lacks its exact verified receipt/Wallet credit'; END IF;
   IF f.amount>0 AND EXISTS(SELECT 1 FROM loyalty.booking_fee_receipt rc WHERE rc.booking_id=b.id)
      AND f.wallet_transaction_id IS NULL THEN RAISE EXCEPTION 'Collected eligible fee has an unfulfilled refund obligation'; END IF;
 END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION loyalty.assert_referral(p_referral uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE r loyalty.referral%ROWTYPE; u iam.user_account%ROWTYPE; a loyalty.reward_application%ROWTYPE;
 tx loyalty.points_transaction%ROWTYPE; cfg record;
BEGIN
 SELECT * INTO r FROM loyalty.referral WHERE id=p_referral;
 IF NOT FOUND THEN RETURN; END IF;
 SELECT * INTO STRICT u FROM iam.user_account WHERE id=r.referred_user_id;
 IF r.status='PENDING' THEN
   IF u.phone_verified THEN RAISE EXCEPTION 'OTP success must reconcile referral reward/invalidity before commit'; END IF;
   IF EXISTS(SELECT 1 FROM loyalty.points_transaction p WHERE p.referral_id=r.id) THEN RAISE EXCEPTION 'Pending referral cannot carry a reward'; END IF;
 END IF;
 IF r.rewarded_at IS NOT NULL THEN
   SELECT * INTO STRICT cfg FROM loyalty.configuration_at('loyalty.referral_points',r.verified_at_snapshot);
   SELECT * INTO tx FROM loyalty.points_transaction t WHERE t.referral_id=r.id AND t.cause='REFERRAL_SIGNUP';
   IF NOT FOUND OR tx.points_account_id IS DISTINCT FROM r.referrer_user_id OR tx.amount IS DISTINCT FROM r.reward_value_applied
      OR tx.granted_value_snapshot IS DISTINCT FROM r.reward_value_applied OR tx.configuration_version_id IS DISTINCT FROM cfg.version_id
      OR tx.configuration_as_of IS DISTINCT FROM r.verified_at_snapshot
      OR r.configuration_version_id IS DISTINCT FROM cfg.version_id
      OR r.reward_value_applied IS DISTINCT FROM loyalty.config_integer('loyalty.referral_points',r.verified_at_snapshot) THEN
     RAISE EXCEPTION 'Referral grant lacks the exact once-only verification-time reward';
   END IF;
   SELECT * INTO a FROM loyalty.reward_application x WHERE x.referral_id=r.id ORDER BY x.application_sequence DESC LIMIT 1;
   IF NOT FOUND OR a.entitlement_after IS DISTINCT FROM (CASE WHEN r.status='REWARDED' THEN r.reward_value_applied ELSE 0 END) THEN
     RAISE EXCEPTION 'Referral state and reward application differ'; END IF;
   IF r.status='INVALID' AND NOT EXISTS(
     SELECT 1 FROM loyalty.points_transaction rev WHERE rev.referral_id=r.id AND rev.cause='COMPENSATION'
       AND rev.compensates_transaction_id=tx.id AND rev.requested_amount=-r.reward_value_applied
       AND rev.admin_id=r.invalidated_by_admin_id AND rev.reason=r.invalidation_reason
   ) THEN RAISE EXCEPTION 'Rewarded referral invalidation must include its historical-value compensation'; END IF;
 ELSIF EXISTS(SELECT 1 FROM loyalty.points_transaction t WHERE t.referral_id=r.id) THEN
   RAISE EXCEPTION 'Unrewarded referral has monetary history';
 END IF;
 IF r.invalidation_kind='ADMIN_FRAUD' AND NOT EXISTS(
  SELECT 1 FROM audit.audit_event au WHERE au.id=r.invalidation_audit_id AND au.actor_type='ADMIN'
    AND au.actor_id=r.invalidated_by_admin_id AND au.action='REFERRAL_INVALIDATED' AND au.subject_type='USER'
    AND au.subject_id=r.referrer_user_id AND au.occurred_at=r.invalidated_at AND au.reason=r.invalidation_reason
    AND au.correlation_id=r.correlation_id AND au.payload->>'referralId'=r.id::text
 ) THEN RAISE EXCEPTION 'Referral invalidation Admin audit mismatch'; END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION loyalty.assert_user(p_user uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE pb integer; wb numeric; ps bigint; ws numeric; rr record; ap record; pt loyalty.points_transaction%ROWTYPE;
BEGIN
 IF p_user IS NULL THEN RETURN; END IF;
 SELECT balance INTO pb FROM loyalty.points_account WHERE user_id=p_user;
 IF NOT FOUND THEN RAISE EXCEPTION 'User is missing Points account'; END IF;
 SELECT balance INTO wb FROM loyalty.wallet_account WHERE user_id=p_user;
 IF NOT FOUND THEN RAISE EXCEPTION 'User is missing Wallet account'; END IF;
 SELECT COALESCE(sum(amount::bigint),0) INTO ps FROM loyalty.points_transaction WHERE points_account_id=p_user;
 SELECT COALESCE(sum(amount),0) INTO ws FROM loyalty.wallet_transaction WHERE wallet_account_id=p_user;
 IF pb IS DISTINCT FROM ps OR wb IS DISTINCT FROM ws THEN RAISE EXCEPTION 'Loyalty account balances must equal physical ledger sums'; END IF;
 IF EXISTS(SELECT 1 FROM (
    SELECT t.*,sum(amount::bigint) OVER(ORDER BY ledger_sequence ROWS UNBOUNDED PRECEDING) run
    FROM loyalty.points_transaction t WHERE t.points_account_id=p_user
  ) q WHERE q.balance_after IS DISTINCT FROM q.run OR q.balance_before::bigint IS DISTINCT FROM q.run-q.amount) THEN
   RAISE EXCEPTION 'Points ledger before/after chain mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM (
    SELECT t.*,sum(amount) OVER(ORDER BY ledger_sequence ROWS UNBOUNDED PRECEDING) run
    FROM loyalty.wallet_transaction t WHERE t.wallet_account_id=p_user
  ) q WHERE q.balance_after IS DISTINCT FROM q.run OR q.balance_before IS DISTINCT FROM q.run-q.amount) THEN
   RAISE EXCEPTION 'Wallet ledger before/after chain mismatch'; END IF;
 FOR pt IN SELECT * FROM loyalty.points_transaction WHERE points_account_id=p_user LOOP
   IF NOT EXISTS(SELECT 1 FROM audit.audit_event a WHERE a.id=pt.audit_event_id AND a.subject_type='USER'
     AND a.subject_id=p_user AND a.action='POINTS_TRANSACTION_POSTED' AND a.occurred_at=pt.occurred_at
     AND a.correlation_id=pt.correlation_id AND a.payload->>'transactionId'=pt.id::text
     AND a.payload->>'appliedAmount'=pt.amount::text AND a.payload->>'requestedAmount'=pt.requested_amount::text
     AND a.payload->>'unrecoveredAmount'=pt.unrecovered_reversal_amount::text
     AND ((pt.admin_id IS NULL AND a.actor_type='SYSTEM' AND a.actor_id IS NULL) OR
          (pt.admin_id IS NOT NULL AND a.actor_type='ADMIN' AND a.actor_id=pt.admin_id AND NULLIF(btrim(a.reason),'') IS NOT NULL))) THEN
     RAISE EXCEPTION 'Points ledger audit is not exact'; END IF;
   IF NOT EXISTS(SELECT 1 FROM technical.outbox_event o WHERE o.id=pt.outbox_event_id
     AND o.event_type='LOYALTY_POINTS_LEDGER_COMMITTED' AND o.aggregate_type='LOYALTY' AND o.aggregate_id=pt.id
     AND o.correlation_id=pt.correlation_id AND o.payload->>'recipientUserId'=p_user::text
     AND o.payload->>'appliedAmount'=pt.amount::text) THEN RAISE EXCEPTION 'Points ledger notification envelope missing'; END IF;
   IF pt.cause<>'ADMIN' AND NOT EXISTS(SELECT 1 FROM loyalty.reward_application a WHERE a.points_transaction_id=pt.id
      AND a.user_id=p_user AND a.booking_id IS NOT DISTINCT FROM pt.booking_id AND a.referral_id IS NOT DISTINCT FROM pt.referral_id
      AND a.source_event_id IS NOT DISTINCT FROM pt.source_trust_event_id) THEN
     RAISE EXCEPTION 'Reward movement has no exact source application'; END IF;
   IF pt.unrecovered_reversal_amount>0 AND NOT EXISTS(SELECT 1 FROM audit.audit_event a WHERE a.action='UNRECOVERED_REVERSAL_AMOUNT'
      AND a.subject_type='USER' AND a.subject_id=p_user AND a.correlation_id=pt.correlation_id
      AND a.payload->>'transactionId'=pt.id::text AND a.payload->>'unrecoveredAmount'=pt.unrecovered_reversal_amount::text) THEN
      RAISE EXCEPTION 'Unrecovered amount audit omitted'; END IF;
 END LOOP;
 FOR rr IN SELECT w.* FROM loyalty.wallet_transaction w WHERE w.wallet_account_id=p_user LOOP
   IF NOT EXISTS(SELECT 1 FROM loyalty.booking_fee_refund f JOIN loyalty.booking_fee_receipt rc ON rc.id=rr.receipt_id
     WHERE f.id=rr.refund_id AND f.wallet_transaction_id=rr.id AND f.booking_id=rr.booking_id AND f.user_id=p_user
       AND f.amount=rr.amount AND rc.booking_id=rr.booking_id AND rc.user_id=p_user AND rc.amount>=rr.amount) THEN
     RAISE EXCEPTION 'Wallet credit is not bound to collected eligible fee'; END IF;
   IF NOT EXISTS(SELECT 1 FROM audit.audit_event a WHERE a.id=rr.audit_event_id AND a.action='BOOKING_FEE_REFUND_CREDITED'
      AND a.subject_type='USER' AND a.subject_id=p_user AND a.payload->>'walletTransactionId'=rr.id::text
      AND a.correlation_id=rr.correlation_id AND a.occurred_at=rr.occurred_at) THEN RAISE EXCEPTION 'Wallet audit omitted'; END IF;
   IF NOT EXISTS(SELECT 1 FROM technical.outbox_event o WHERE o.id=rr.outbox_event_id AND o.aggregate_type='LOYALTY'
      AND o.aggregate_id=rr.id AND o.event_type='LOYALTY_WALLET_LEDGER_COMMITTED'
      AND o.payload->>'recipientUserId'=p_user::text AND o.correlation_id=rr.correlation_id) THEN RAISE EXCEPTION 'Wallet outbox omitted'; END IF;
 END LOOP;
 FOR ap IN SELECT a.*,lag(a.id) OVER(PARTITION BY source_kind,booking_id,referral_id ORDER BY application_sequence) prev_id,
   lag(a.entitlement_after,1,0) OVER(PARTITION BY source_kind,booking_id,referral_id ORDER BY application_sequence) prev_ent
   FROM loyalty.reward_application a WHERE a.user_id=p_user LOOP
   IF ap.previous_application_id IS DISTINCT FROM ap.prev_id OR ap.entitlement_before IS DISTINCT FROM ap.prev_ent THEN RAISE EXCEPTION 'Reward application chain is branched or discontinuous'; END IF;
 END LOOP;
 PERFORM loyalty.assert_application_history(p_user);
 FOR rr IN SELECT id FROM booking.booking WHERE customer_id=p_user LOOP PERFORM loyalty.assert_booking(rr.id); END LOOP;
 FOR rr IN SELECT id FROM loyalty.referral WHERE referred_user_id=p_user OR referrer_user_id=p_user LOOP PERFORM loyalty.assert_referral(rr.id); END LOOP;
 IF EXISTS(SELECT 1 FROM iam.user_account u WHERE u.id=p_user AND NULLIF(btrim(u.referred_by_code),'') IS NOT NULL
   AND NOT EXISTS(SELECT 1 FROM loyalty.referral r WHERE r.referred_user_id=u.id AND r.code=btrim(u.referred_by_code))) THEN
    RAISE EXCEPTION 'Referral affiliation requires its source record'; END IF;
END;
$function$;


CREATE OR REPLACE FUNCTION loyalty.assert_application_history(p_user uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE a loyalty.reward_application%ROWTYPE; prev loyalty.reward_application%ROWTYPE;
 tx loyalty.points_transaction%ROWTYPE; ev trust.trust_event%ROWTYPE; orig trust.trust_event%ROWTYPE;
 r loyalty.referral%ROWTYPE; prior_net bigint; req integer; tranche integer; has_grant boolean; cfg record; expected integer;
BEGIN
 FOR a IN SELECT * FROM loyalty.reward_application ra WHERE ra.user_id=p_user ORDER BY ra.application_sequence LOOP
   IF a.previous_application_id IS NOT NULL THEN
    SELECT * INTO STRICT prev FROM loyalty.reward_application WHERE id=a.previous_application_id;
    IF prev.user_id<>a.user_id OR prev.source_kind<>a.source_kind OR prev.booking_id IS DISTINCT FROM a.booking_id
       OR prev.referral_id IS DISTINCT FROM a.referral_id OR prev.entitlement_after<>a.entitlement_before
       OR prev.application_sequence>=a.application_sequence OR prev.reward_value<>a.reward_value
       OR prev.configuration_version_id<>a.configuration_version_id OR prev.configuration_as_of<>a.configuration_as_of THEN
      RAISE EXCEPTION 'Reward application predecessor/configuration mismatch'; END IF;
   ELSIF a.entitlement_before<>0 THEN RAISE EXCEPTION 'First application begins with zero entitlement'; END IF;
   IF a.source_kind='BOOKING' THEN
    SELECT * INTO STRICT ev FROM trust.trust_event WHERE id=a.source_event_id;
    SELECT * INTO STRICT orig FROM trust.trust_event te WHERE te.booking_id=a.booking_id AND te.event_type IN
      ('BOOKING_ATTENDED','BOOKING_ATTENDANCE_UNCONFIRMED','BOOKING_ATTENDED_INTERRUPTED','BOOKING_NO_SHOW');
    IF ev.booking_id IS DISTINCT FROM a.booking_id OR ev.subject_user_id<>a.user_id OR a.configuration_as_of<>loyalty.booking_completion_anchor(a.booking_id) THEN
      RAISE EXCEPTION 'Application does not belong to original Booking outcome'; END IF;
    expected:=CASE WHEN ev.event_type='BOOKING_ATTENDED' OR (ev.event_type='ATTENDANCE_CORRECTED' AND ev.corrected_outcome='ATTENDED') THEN a.reward_value ELSE 0 END;
    SELECT * INTO STRICT cfg FROM loyalty.configuration_at('loyalty.attended_points',a.configuration_as_of);
    IF a.entitlement_after<>expected OR a.configuration_version_id<>cfg.version_id OR a.reward_value<>loyalty.config_integer('loyalty.attended_points',a.configuration_as_of) THEN
      RAISE EXCEPTION 'Historical application outcome/value differs from source'; END IF;
   ELSE
    SELECT * INTO STRICT r FROM loyalty.referral WHERE id=a.referral_id;
    IF a.user_id<>r.referrer_user_id OR a.reward_value IS DISTINCT FROM r.reward_value_applied
      OR a.configuration_as_of IS DISTINCT FROM r.verified_at_snapshot OR a.configuration_version_id IS DISTINCT FROM r.configuration_version_id THEN
      RAISE EXCEPTION 'Historical referral application mismatch'; END IF;
    IF a.operation_key='REFERRAL_REWARD:'||r.id::text THEN expected:=r.reward_value_applied;
    ELSIF a.operation_key='REFERRAL_INVALIDATE:'||r.id::text THEN expected:=0;
    ELSE RAISE EXCEPTION 'Unknown referral application identity'; END IF;
    IF a.entitlement_after<>expected THEN RAISE EXCEPTION 'Referral application entitlement mismatch'; END IF;
   END IF;
   SELECT COALESCE(sum(t.amount::bigint),0),COALESCE(bool_or(t.cause IN ('ATTENDED_COMPLETION','REFERRAL_SIGNUP')),false)
    INTO prior_net,has_grant FROM loyalty.reward_application pa JOIN loyalty.points_transaction t ON t.id=pa.points_transaction_id
    WHERE pa.user_id=p_user AND pa.source_kind=a.source_kind AND pa.booking_id IS NOT DISTINCT FROM a.booking_id
      AND pa.referral_id IS NOT DISTINCT FROM a.referral_id AND pa.application_sequence<a.application_sequence;
   req:=CASE WHEN a.entitlement_after>a.entitlement_before THEN GREATEST(a.entitlement_after-prior_net,0)::integer
             WHEN a.entitlement_after<a.entitlement_before THEN -a.entitlement_before ELSE 0 END;
   IF a.source_kind='BOOKING' AND a.entitlement_after<a.entitlement_before THEN
     SELECT COALESCE(t.amount,0) INTO tranche FROM loyalty.reward_application ra
      LEFT JOIN loyalty.points_transaction t ON t.id=ra.points_transaction_id
      WHERE ra.booking_id=a.booking_id AND ra.application_sequence<a.application_sequence
        AND ra.entitlement_before=0 AND ra.entitlement_after>0
      ORDER BY ra.application_sequence DESC LIMIT 1;
     req:=-COALESCE(tranche,0);
   END IF;
   IF a.points_transaction_id IS NULL THEN
     IF req<>0 OR (a.source_kind='REFERRAL') OR (a.entitlement_after>0 AND NOT has_grant) THEN
       RAISE EXCEPTION 'Reward application omitted a required ledger movement'; END IF;
   ELSE
     SELECT * INTO STRICT tx FROM loyalty.points_transaction WHERE id=a.points_transaction_id;
     IF tx.points_account_id<>p_user OR tx.booking_id IS DISTINCT FROM a.booking_id OR tx.referral_id IS DISTINCT FROM a.referral_id
        OR tx.source_trust_event_id IS DISTINCT FROM a.source_event_id OR tx.requested_amount<>req
        OR tx.granted_value_snapshot<>a.reward_value OR tx.configuration_version_id IS DISTINCT FROM a.configuration_version_id
        OR tx.configuration_as_of IS DISTINCT FROM a.configuration_as_of OR tx.operation_key<>a.operation_key
        OR tx.occurred_at<>a.applied_at OR tx.correlation_id<>a.correlation_id THEN
       RAISE EXCEPTION 'Reward application/ledger pair is not exact'; END IF;
   END IF;
 END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION loyalty.final_integrity_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE row_data jsonb; uid uuid; bid uuid;
BEGIN
 row_data:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
 IF TG_TABLE_SCHEMA='iam' THEN uid:=(row_data->>'id')::uuid;
 ELSIF TG_TABLE_SCHEMA='trust' THEN uid:=(row_data->>'subject_user_id')::uuid;
 ELSIF TG_TABLE_SCHEMA='booking' THEN uid:=(row_data->>'customer_id')::uuid;
 ELSIF TG_TABLE_NAME='points_transaction' THEN uid:=(row_data->>'points_account_id')::uuid;
 ELSIF TG_TABLE_NAME='wallet_transaction' THEN uid:=(row_data->>'wallet_account_id')::uuid;
 ELSIF TG_TABLE_NAME='referral' THEN
   PERFORM loyalty.assert_referral((row_data->>'id')::uuid);
   PERFORM loyalty.assert_user((row_data->>'referred_user_id')::uuid);
   uid:=(row_data->>'referrer_user_id')::uuid;
 ELSE uid:=(row_data->>'user_id')::uuid;
 END IF;
 PERFORM loyalty.assert_user(uid);
 RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION loyalty.immutable_referral_affiliation()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF NEW.referral_code IS DISTINCT FROM OLD.referral_code OR NEW.referred_by_code IS DISTINCT FROM OLD.referred_by_code THEN
    RAISE EXCEPTION 'Signup referral affiliation/code is immutable; never rewrite reward provenance'; END IF;
 RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION loyalty.guard_outbox_envelope()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.aggregate_type='LOYALTY' THEN PERFORM loyalty.require_write('technical.outbox_event',NEW.aggregate_id::text); END IF;
  RETURN NEW;
 END IF;
 IF OLD.aggregate_type='LOYALTY' OR (TG_OP='UPDATE' AND NEW.aggregate_type='LOYALTY') THEN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Referenced Loyalty Outbox history is retained'; END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.event_type IS DISTINCT FROM OLD.event_type OR NEW.aggregate_type IS DISTINCT FROM OLD.aggregate_type
    OR NEW.aggregate_id IS DISTINCT FROM OLD.aggregate_id OR NEW.payload IS DISTINCT FROM OLD.payload OR NEW.correlation_id IS DISTINCT FROM OLD.correlation_id THEN
   RAISE EXCEPTION 'Loyalty Outbox envelope is immutable; delivery fields only'; END IF;
 END IF;
 RETURN NEW;
END;
$function$;

-- Backfill is deliberately NOT synthesized. This bootstrap only initializes zero-balance empty accounts.
INSERT INTO loyalty.points_account(user_id,balance,updated_at)
 SELECT u.id,0,clock_timestamp() FROM iam.user_account u ON CONFLICT(user_id) DO NOTHING;
INSERT INTO loyalty.wallet_account(user_id,balance,updated_at)
 SELECT u.id,0,clock_timestamp() FROM iam.user_account u ON CONFLICT(user_id) DO NOTHING;
-- Seed documented launch defaults as the initial technical configuration history.
DO $seed_loyalty_config$
DECLARE k text; val jsonb; cid uuid;
BEGIN
 FOREACH k IN ARRAY ARRAY['loyalty.attended_points','loyalty.referral_points','loyalty.wallet_refunds_enabled'] LOOP
   IF NOT EXISTS(SELECT 1 FROM config.configuration_version WHERE key=k) THEN
     IF EXISTS(SELECT 1 FROM config.system_configuration WHERE key=k) THEN
       RAISE EXCEPTION 'Existing Loyalty current config lacks historical provenance: %',k;
     END IF;
     val:=CASE k WHEN 'loyalty.attended_points' THEN '200'::jsonb WHEN 'loyalty.referral_points' THEN '1000'::jsonb ELSE 'false'::jsonb END;
     cid:=gen_random_uuid();
     INSERT INTO config.configuration_version(id,key,new_value,effective_from,reason)
       VALUES(cid,k,val,'-infinity','Initial launch configuration from Product v5.0; technical bootstrap');
     INSERT INTO config.system_configuration(key,value,updated_at) VALUES(k,val,clock_timestamp()) ON CONFLICT(key) DO NOTHING;
   END IF;
 END LOOP;
END;
$seed_loyalty_config$;

DO $attach_loyalty$
DECLARE n text;
BEGIN
 FOREACH n IN ARRAY ARRAY['points_account','points_transaction','wallet_account','wallet_transaction','referral','booking_fee_refund','reward_application','booking_fee_receipt'] LOOP
   EXECUTE format('DROP TRIGGER IF EXISTS tr_123_write_guard ON loyalty.%I',n);
   EXECUTE format('CREATE TRIGGER tr_123_write_guard BEFORE INSERT OR UPDATE OR DELETE ON loyalty.%I FOR EACH ROW EXECUTE FUNCTION loyalty.write_guard()',n);
   EXECUTE format('DROP TRIGGER IF EXISTS tr_123_no_truncate ON loyalty.%I',n);
   EXECUTE format('CREATE TRIGGER tr_123_no_truncate BEFORE TRUNCATE ON loyalty.%I FOR EACH STATEMENT EXECUTE FUNCTION technical.reject_append_only_mutation()',n);
   EXECUTE format('DROP TRIGGER IF EXISTS tr_123_final_integrity ON loyalty.%I',n);
   EXECUTE format('CREATE CONSTRAINT TRIGGER tr_123_final_integrity AFTER INSERT OR UPDATE OR DELETE ON loyalty.%I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION loyalty.final_integrity_trigger()',n);
 END LOOP;
END;
$attach_loyalty$;
DROP TRIGGER IF EXISTS tr_123_referral_lifecycle ON loyalty.referral;
CREATE TRIGGER tr_123_referral_lifecycle BEFORE UPDATE ON loyalty.referral FOR EACH ROW EXECUTE FUNCTION loyalty.referral_mutation_guard();
DROP TRIGGER IF EXISTS tr_123_refund_lifecycle ON loyalty.booking_fee_refund;
CREATE TRIGGER tr_123_refund_lifecycle BEFORE UPDATE ON loyalty.booking_fee_refund FOR EACH ROW EXECUTE FUNCTION loyalty.refund_mutation_guard();
DROP TRIGGER IF EXISTS tr_123_loyalty_accounts ON iam.user_account;
CREATE TRIGGER tr_123_loyalty_accounts AFTER INSERT ON iam.user_account FOR EACH ROW EXECUTE FUNCTION loyalty.initialize_user();
DROP TRIGGER IF EXISTS tr_123_referral_identity ON iam.user_account;
CREATE TRIGGER tr_123_referral_identity BEFORE UPDATE ON iam.user_account FOR EACH ROW EXECUTE FUNCTION loyalty.immutable_referral_affiliation();
DROP TRIGGER IF EXISTS tr_123_loyalty_user_source ON iam.user_account;
CREATE CONSTRAINT TRIGGER tr_123_loyalty_user_source AFTER INSERT OR UPDATE ON iam.user_account DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION loyalty.final_integrity_trigger();
DROP TRIGGER IF EXISTS tr_123_loyalty_trust_source ON trust.trust_event;
CREATE CONSTRAINT TRIGGER tr_123_loyalty_trust_source AFTER INSERT ON trust.trust_event DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION loyalty.final_integrity_trigger();
DROP TRIGGER IF EXISTS tr_123_loyalty_booking_source ON booking.booking;
CREATE CONSTRAINT TRIGGER tr_123_loyalty_booking_source AFTER INSERT OR UPDATE ON booking.booking DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION loyalty.final_integrity_trigger();
DROP TRIGGER IF EXISTS tr_123_loyalty_outbox_envelope ON technical.outbox_event;
CREATE TRIGGER tr_123_loyalty_outbox_envelope BEFORE INSERT OR UPDATE OR DELETE ON technical.outbox_event FOR EACH ROW EXECUTE FUNCTION loyalty.guard_outbox_envelope();
DROP TRIGGER IF EXISTS tr_123_loyalty_config_history ON config.configuration_version;
CREATE TRIGGER tr_123_loyalty_config_history BEFORE INSERT OR UPDATE OR DELETE ON config.configuration_version FOR EACH ROW EXECUTE FUNCTION loyalty.config_write_guard();
DROP TRIGGER IF EXISTS tr_123_loyalty_config_current ON config.system_configuration;
CREATE TRIGGER tr_123_loyalty_config_current BEFORE INSERT OR UPDATE OR DELETE ON config.system_configuration FOR EACH ROW EXECUTE FUNCTION loyalty.config_write_guard();


CREATE OR REPLACE FUNCTION loyalty.guard_audit_origin()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF NEW.action IN ('POINTS_TRANSACTION_POSTED','UNRECOVERED_REVERSAL_AMOUNT','REFERRAL_INVALIDATED',
   'BOOKING_SERVICE_LOSS_CONFIRMED','BOOKING_FEE_REFUND_DECIDED','BOOKING_FEE_REFUND_CREDITED',
   'BOOKING_FEE_COLLECTION_RECORDED','LOYALTY_CONFIGURATION_CHANGED') THEN
   PERFORM loyalty.require_write('audit.audit_event',NEW.id::text);
 END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_123_loyalty_audit_origin ON audit.audit_event;
CREATE TRIGGER tr_123_loyalty_audit_origin BEFORE INSERT ON audit.audit_event FOR EACH ROW EXECUTE FUNCTION loyalty.guard_audit_origin();

CREATE OR REPLACE FUNCTION loyalty.rebuild_balances(p_user uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE ctx record; pb bigint; wb numeric; tok uuid;
BEGIN
 SELECT * INTO STRICT ctx FROM loyalty.command_context(p_user);
 SELECT COALESCE(sum(amount::bigint),0) INTO pb FROM loyalty.points_transaction WHERE points_account_id=p_user;
 SELECT COALESCE(sum(amount),0) INTO wb FROM loyalty.wallet_transaction WHERE wallet_account_id=p_user;
 IF pb NOT BETWEEN 0 AND 2147483647 THEN RAISE EXCEPTION 'Invalid Points ledger balance'; END IF;
 tok:=loyalty.enter_write('loyalty.points_account',p_user::text);
 UPDATE loyalty.points_account SET balance=pb::integer,updated_at=ctx.command_at WHERE user_id=p_user;
 PERFORM loyalty.leave_write(tok);
 tok:=loyalty.enter_write('loyalty.wallet_account',p_user::text);
 UPDATE loyalty.wallet_account SET balance=wb,updated_at=ctx.command_at WHERE user_id=p_user;
 PERFORM loyalty.leave_write(tok);
 PERFORM loyalty.assert_user(p_user);
END;
$function$;

DROP TRIGGER IF EXISTS tr_123_no_config_history_truncate ON config.configuration_version;
CREATE TRIGGER tr_123_no_config_history_truncate BEFORE TRUNCATE ON config.configuration_version FOR EACH STATEMENT EXECUTE FUNCTION technical.reject_append_only_mutation();
DROP TRIGGER IF EXISTS tr_123_no_config_current_truncate ON config.system_configuration;
CREATE TRIGGER tr_123_no_config_current_truncate BEFORE TRUNCATE ON config.system_configuration FOR EACH STATEMENT EXECUTE FUNCTION technical.reject_append_only_mutation();


-- Default deny every new implementation function. The companion security script grants named producers only.
DO $private_helpers$
DECLARE f record;
BEGIN
 FOR f IN SELECT p.oid::regprocedure sig FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
   WHERE n.nspname='loyalty' OR (n.nspname='trust' AND p.proname IN ('assert_owned_context','secure_created_context','begin_admin_command','require_admin_command'))
   OR (n.nspname='technical' AND p.proname='assign_outbox_id') LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.sig);
 END LOOP;
END;
$private_helpers$;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA loyalty FROM PUBLIC;
REVOKE ALL ON SEQUENCE technical.outbox_event_id_seq FROM PUBLIC;



-- v1.1.24: focused correction of AR23-01 and AR23-02 (Independent Acceptance Review of v1.1.23).
-- Scope: Loyalty reward-anchor provenance (LOY-001) + Admin fee-decision assessment.
-- Everything else in v1.1.23 (Admin context origin, grants, Points/Wallet invariants) is retained unchanged.
-- No native table, column, constraint, index, Product state, reason code or permission is added.

-- ---------------------------------------------------------------------------
-- AR24-X01 (found by first real PostgreSQL 16 execution, not listed in the v1.1.23 review):
-- v1.1.23 write_guard evaluated NEW.user_id inside one boolean expression. PL/pgSQL resolves every
-- record field of an expression before evaluating it, so every INSERT into a table WITHOUT a user_id
-- column (points_transaction, wallet_transaction, referral) raised 'record "new" has no field "user_id"'.
-- Effect: no Points grant, Wallet credit or referral row could ever be written. Same rules, split IFs.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION loyalty.write_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_key text;
BEGIN
 IF TG_OP IN ('DELETE','TRUNCATE') THEN RAISE EXCEPTION 'Loyalty rows cannot be deleted/truncated'; END IF;
 IF TG_OP='UPDATE' AND TG_TABLE_NAME IN ('points_transaction','wallet_transaction','reward_application','booking_fee_receipt') THEN
   RAISE EXCEPTION 'Loyalty ledger/provenance is append-only';
 END IF;
 IF TG_TABLE_NAME IN ('points_account','wallet_account') THEN v_key:=NEW.user_id::text; ELSE v_key:=NEW.id::text; END IF;
 PERFORM loyalty.require_write(TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME,v_key);
 IF TG_OP='UPDATE' AND TG_TABLE_NAME IN ('points_account','wallet_account') THEN
   IF NEW.user_id IS DISTINCT FROM OLD.user_id THEN RAISE EXCEPTION 'Account identity is immutable'; END IF;
 END IF;
 RETURN NEW;
END;
$function$;

-- ---------------------------------------------------------------------------
-- AR23-01 / LOY-001: immutable original reward anchor.
-- The anchor is resolved deterministically from immutable facts and cannot drift
-- when later history (e.g. the COMPLETED transition of a post-end No-show
-- reversal) is appended.
--   * original BOOKING_NO_SHOW / BOOKING_ATTENDED_INTERRUPTED: no original completion
--     exists by construction -> original canonical outcome occurred_at.
--   * original BOOKING_ATTENDED / BOOKING_ATTENDANCE_UNCONFIRMED: the COMPLETED
--     transition that belongs to that outcome processing (at or before the outcome
--     instant); if the outcome did not come from a completion (e.g. ACTIVE
--     interruption with Late Present only) -> original outcome occurred_at.
--   * missing/contradictory source evidence is rejected, never synthesized (AC07).
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION loyalty.booking_reward_anchor(p_booking uuid)
RETURNS TABLE(original_event_id uuid,original_event_type text,original_completion_history_id uuid,anchor_at timestamptz,anchor_kind text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE orig trust.trust_event%ROWTYPE; rev trust.trust_event%ROWTYPE; h booking.booking_history%ROWTYPE; n integer;
BEGIN
 SELECT count(*) INTO n FROM trust.trust_event e WHERE e.booking_id=p_booking AND e.event_type IN
  ('BOOKING_ATTENDED','BOOKING_ATTENDANCE_UNCONFIRMED','BOOKING_ATTENDED_INTERRUPTED','BOOKING_NO_SHOW');
 IF n<>1 THEN RAISE EXCEPTION 'LOY-001: exactly one original canonical Booking outcome is required (found %)',n; END IF;
 SELECT * INTO STRICT orig FROM trust.trust_event e WHERE e.booking_id=p_booking AND e.event_type IN
  ('BOOKING_ATTENDED','BOOKING_ATTENDANCE_UNCONFIRMED','BOOKING_ATTENDED_INTERRUPTED','BOOKING_NO_SHOW');
 SELECT * INTO rev FROM trust.trust_event e WHERE e.booking_id=p_booking AND e.event_type='NO_SHOW_REVERSED';

 IF orig.event_type IN ('BOOKING_NO_SHOW','BOOKING_ATTENDED_INTERRUPTED') THEN
   -- A COMPLETED row here can only be the consequence of a post-end No-show reversal.
   IF EXISTS(SELECT 1 FROM booking.booking_history x
      WHERE x.booking_id=p_booking AND x.entry_kind='STATUS_TRANSITION' AND x.to_status='COMPLETED'
        AND (orig.event_type<>'BOOKING_NO_SHOW' OR rev.id IS NULL OR x.occurred_at<rev.occurred_at)) THEN
     RAISE EXCEPTION 'LOY-001: COMPLETED history contradicts the original % outcome',orig.event_type;
   END IF;
   RETURN QUERY SELECT orig.id,orig.event_type::text,NULL::uuid,orig.occurred_at,'ORIGINAL_OUTCOME'::text;
   RETURN;
 END IF;

 IF rev.id IS NOT NULL THEN
   RAISE EXCEPTION 'LOY-001: NO_SHOW_REVERSED contradicts original % outcome',orig.event_type;
 END IF;
 SELECT * INTO h FROM booking.booking_history x
  WHERE x.booking_id=p_booking AND x.entry_kind='STATUS_TRANSITION' AND x.to_status='COMPLETED' AND x.occurred_at<=orig.occurred_at
  ORDER BY x.sequence,x.id LIMIT 1;
 IF FOUND THEN
   RETURN QUERY SELECT orig.id,orig.event_type::text,h.id,h.occurred_at,'ORIGINAL_COMPLETION'::text;
   RETURN;
 END IF;
 IF EXISTS(SELECT 1 FROM booking.booking_history x WHERE x.booking_id=p_booking AND x.entry_kind='STATUS_TRANSITION' AND x.to_status='COMPLETED') THEN
   RAISE EXCEPTION 'LOY-001: COMPLETED history does not belong to the original % outcome',orig.event_type;
 END IF;
 RETURN QUERY SELECT orig.id,orig.event_type::text,NULL::uuid,orig.occurred_at,'ORIGINAL_OUTCOME'::text;
END;
$function$;

-- Same name/signature as v1.1.23 so every caller (booking_reward_basis, assert_application_history)
-- now uses the fixed original anchor; no caller keeps a second resolver.
CREATE OR REPLACE FUNCTION loyalty.booking_completion_anchor(p_booking uuid)
RETURNS timestamptz LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE t timestamptz;
BEGIN
 SELECT a.anchor_at INTO STRICT t FROM loyalty.booking_reward_anchor(p_booking) a;
 RETURN t;
END;
$function$;

-- ---------------------------------------------------------------------------
-- AR23-02: separate the fee DECISION from positive refund ENTITLEMENT.
-- For the three Admin reasons whose refund depends on service loss
-- (ADMIN_CANCELLED, ADMIN_CORRECTION, ADMIN_NO_SHOW_REVERSAL) the decision
-- references exactly one explicit audited Admin assessment:
--   BOOKING_SERVICE_LOSS_CONFIRMED      serviceLoss=true, customerAtFault=false -> reason-map refund
--   BOOKING_SERVICE_LOSS_NOT_ESTABLISHED serviceLoss=false                     -> amount 0, no Wallet
-- The NOT_ESTABLISHED record is a technical assessment record; it asserts no fact,
-- creates no customer-visible state and does not change the frozen reason->treatment map.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION loyalty.assess_service_loss(p_booking uuid,p_history uuid,p_service_loss boolean,p_reason text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE b booking.booking%ROWTYPE; h booking.booking_history%ROWTYPE; ctx record; v_id uuid; v_tok uuid;
 v_action text; v_other text; v_payload jsonb;
BEGIN
 IF p_service_loss IS NULL THEN RAISE EXCEPTION 'Service-loss assessment must be explicit'; END IF;
 SELECT * INTO STRICT b FROM booking.booking WHERE id=p_booking;
 SELECT * INTO STRICT ctx FROM loyalty.command_context(b.customer_id);
 IF ctx.admin_id IS NULL OR NULLIF(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'Service-loss assessment requires Admin and reason'; END IF;
 SELECT * INTO STRICT h FROM booking.booking_history WHERE id=p_history AND booking_id=p_booking;
 IF NOT ((h.entry_kind='STATUS_TRANSITION' AND h.terminal_reason IN ('ADMIN_CANCELLED','ADMIN_CORRECTION','ADMIN_NO_SHOW_REVERSAL'))
      OR (h.entry_kind='BOOKING_EVENT' AND h.event_type='NO_SHOW_REVERSED')) THEN RAISE EXCEPTION 'Not an eligible Admin service-loss history'; END IF;
 v_action:=CASE WHEN p_service_loss THEN 'BOOKING_SERVICE_LOSS_CONFIRMED' ELSE 'BOOKING_SERVICE_LOSS_NOT_ESTABLISHED' END;
 v_other:=CASE WHEN p_service_loss THEN 'BOOKING_SERVICE_LOSS_NOT_ESTABLISHED' ELSE 'BOOKING_SERVICE_LOSS_CONFIRMED' END;
 v_payload:=CASE WHEN p_service_loss
   THEN jsonb_build_object('bookingHistoryId',h.id,'serviceLoss',true,'customerAtFault',false)
   ELSE jsonb_build_object('bookingHistoryId',h.id,'serviceLoss',false,'assessment','NOT_ESTABLISHED') END;
 IF EXISTS(SELECT 1 FROM audit.audit_event au WHERE au.action=v_other AND au.subject_type='BOOKING' AND au.subject_id=b.id
    AND au.payload->>'bookingHistoryId'=h.id::text) THEN
   RAISE EXCEPTION 'Contradictory service-loss assessment for the same Booking history; assessments are immutable';
 END IF;
 SELECT au.id INTO v_id FROM audit.audit_event au WHERE au.action=v_action
   AND au.subject_type='BOOKING' AND au.subject_id=b.id AND au.actor_type='ADMIN' AND au.actor_id=ctx.admin_id
   AND au.reason=p_reason AND au.payload=v_payload
   ORDER BY au.occurred_at,au.id LIMIT 1;
 IF FOUND THEN RETURN v_id; END IF;
 v_id:=gen_random_uuid();
 v_tok:=loyalty.enter_write('audit.audit_event',v_id::text);
 INSERT INTO audit.audit_event(id,occurred_at,actor_type,actor_id,action,subject_type,subject_id,reason,correlation_id,payload)
 VALUES(v_id,ctx.command_at,'ADMIN',ctx.admin_id,v_action,'BOOKING',b.id,p_reason,ctx.correlation_id,v_payload);
 PERFORM loyalty.leave_write(v_tok);
 RETURN v_id;
END;
$function$;

-- Retained v1.1.23 entrypoint; now also refuses to contradict a NOT_ESTABLISHED assessment.
CREATE OR REPLACE FUNCTION loyalty.confirm_service_loss(p_booking uuid,p_history uuid,p_reason text)
RETURNS uuid LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
 SELECT loyalty.assess_service_loss(p_booking,p_history,true,p_reason);
$function$;

-- New Admin entrypoint for the honest penalty-only / no-entitlement path.
CREATE OR REPLACE FUNCTION loyalty.record_service_loss_not_established(p_booking uuid,p_history uuid,p_reason text)
RETURNS uuid LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
 SELECT loyalty.assess_service_loss(p_booking,p_history,false,p_reason);
$function$;

CREATE OR REPLACE FUNCTION loyalty.refund_basis(p_booking uuid,p_history uuid,p_loss_audit uuid DEFAULT NULL)
RETURNS TABLE(user_id uuid,treatment text,terminal_reason text,fee_snapshot numeric,decision_at timestamptz,refund_amount numeric)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE b booking.booking%ROWTYPE; h booking.booking_history%ROWTYPE; la audit.audit_event%ROWTYPE;
 tr text; rs text; am numeric; v_loss boolean:=NULL;
BEGIN
 SELECT * INTO STRICT b FROM booking.booking WHERE id=p_booking;
 IF b.source<>'ONLINE' OR b.customer_id IS NULL THEN RAISE EXCEPTION 'Manual Booking has no customer refund ledger'; END IF;
 SELECT * INTO STRICT h FROM booking.booking_history WHERE id=p_history;
 IF h.booking_id IS DISTINCT FROM b.id THEN RAISE EXCEPTION 'Refund history belongs to another Booking'; END IF;
 IF h.entry_kind='STATUS_TRANSITION' AND h.to_status IN ('CANCELLED','REJECTED') THEN
   IF b.status IS DISTINCT FROM h.to_status OR b.terminal_reason IS DISTINCT FROM h.terminal_reason THEN RAISE EXCEPTION 'Refund requires the current immutable terminal outcome'; END IF;
   rs:=h.terminal_reason;
 ELSIF h.entry_kind='BOOKING_EVENT' AND h.event_type='NO_SHOW_REVERSED' THEN
   rs:='ADMIN_NO_SHOW_REVERSAL';
 ELSE RAISE EXCEPTION 'Attendance reclassification is not a refund trigger';
 END IF;
 tr:=booking.expected_fee_treatment(rs);
 IF tr IS NULL THEN RAISE EXCEPTION 'Unknown fee treatment'; END IF;
 IF rs IN ('ADMIN_CANCELLED','ADMIN_CORRECTION','ADMIN_NO_SHOW_REVERSAL') THEN
   IF p_loss_audit IS NULL THEN
     RAISE EXCEPTION 'Admin-reason fee decision requires an explicit audited service-loss assessment (confirmed or not established)';
   END IF;
   SELECT a.* INTO la FROM audit.audit_event a JOIN iam.admin_account adm ON adm.id=a.actor_id
    WHERE a.id=p_loss_audit AND a.subject_type='BOOKING' AND a.subject_id=b.id AND a.actor_type='ADMIN'
      AND a.action IN ('BOOKING_SERVICE_LOSS_CONFIRMED','BOOKING_SERVICE_LOSS_NOT_ESTABLISHED')
      AND a.payload->>'bookingHistoryId'=h.id::text AND NULLIF(btrim(a.reason),'') IS NOT NULL;
   IF NOT FOUND THEN RAISE EXCEPTION 'Service-loss assessment does not belong to this Admin Booking history'; END IF;
   IF la.action='BOOKING_SERVICE_LOSS_CONFIRMED'
      AND la.payload->'serviceLoss'='true'::jsonb AND la.payload->'customerAtFault'='false'::jsonb THEN
     v_loss:=true;
   ELSIF la.action='BOOKING_SERVICE_LOSS_NOT_ESTABLISHED'
      AND la.payload->'serviceLoss'='false'::jsonb AND la.payload->>'assessment'='NOT_ESTABLISHED' THEN
     v_loss:=false;
   ELSE RAISE EXCEPTION 'Malformed service-loss assessment';
   END IF;
   IF EXISTS(SELECT 1 FROM audit.audit_event o WHERE o.subject_type='BOOKING' AND o.subject_id=b.id
      AND o.action IN ('BOOKING_SERVICE_LOSS_CONFIRMED','BOOKING_SERVICE_LOSS_NOT_ESTABLISHED') AND o.action<>la.action
      AND o.payload->>'bookingHistoryId'=h.id::text) THEN
     RAISE EXCEPTION 'Contradictory service-loss assessments for the same Booking history';
   END IF;
 ELSIF p_loss_audit IS NOT NULL THEN RAISE EXCEPTION 'Unnecessary Admin service-loss override';
 END IF;
 am:=CASE WHEN v_loss IS FALSE THEN 0
      WHEN tr='FULL_REFUND' THEN b.booking_fee_snapshot
      WHEN tr='CUSTOMER_POLICY' AND h.occurred_at<=b.created_at+interval '15 minutes' AND h.occurred_at<b.start_at THEN b.booking_fee_snapshot
      ELSE 0 END;
 IF am<0 OR am>b.booking_fee_snapshot OR am='NaN'::numeric THEN RAISE EXCEPTION 'Invalid fee amount'; END IF;
 RETURN QUERY SELECT b.customer_id,tr,rs,b.booking_fee_snapshot,h.occurred_at,am;
END;
$function$;

-- Decision audit now records which assessment the entitlement rests on.
CREATE OR REPLACE FUNCTION loyalty.record_refund(p_booking uuid,p_history uuid,p_loss_audit uuid DEFAULT NULL)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE bas record; ctx record; f loyalty.booking_fee_refund%ROWTYPE; tok uuid; fid uuid:=gen_random_uuid(); aid uuid; v_assess text;
BEGIN
 SELECT * INTO STRICT bas FROM loyalty.refund_basis(p_booking,p_history,p_loss_audit);
 SELECT * INTO STRICT ctx FROM loyalty.command_context(bas.user_id);
 SELECT * INTO f FROM loyalty.booking_fee_refund WHERE booking_id=p_booking;
 IF FOUND THEN
   IF f.booking_history_id IS DISTINCT FROM p_history OR f.service_loss_audit_id IS DISTINCT FROM p_loss_audit
      OR f.amount IS DISTINCT FROM bas.refund_amount THEN RAISE EXCEPTION 'One refund decision per Booking; changed evidence is not a retry'; END IF;
   PERFORM loyalty.settle_refund(f.id);
   RETURN f.id;
 END IF;
 SELECT a.action INTO v_assess FROM audit.audit_event a WHERE a.id=p_loss_audit;
 aid:=loyalty.write_audit(bas.user_id,'BOOKING_FEE_REFUND_DECIDED','Canonical Booking Fee policy',
   jsonb_build_object('refundId',fid,'bookingId',p_booking,'bookingHistoryId',p_history,'serviceLossAuditId',p_loss_audit,
     'serviceLossAssessment',v_assess,'feeSnapshot',bas.fee_snapshot,'treatment',bas.treatment,'amount',bas.refund_amount));
 tok:=loyalty.enter_write('loyalty.booking_fee_refund',fid::text);
 INSERT INTO loyalty.booking_fee_refund(id,booking_id,treatment,amount,terminal_reason,occurred_at,user_id,booking_history_id,
   service_loss_audit_id,fee_snapshot,decision_at,correlation_id,audit_event_id)
 VALUES(fid,p_booking,bas.treatment,bas.refund_amount,bas.terminal_reason,ctx.command_at,bas.user_id,p_history,p_loss_audit,
   bas.fee_snapshot,bas.decision_at,ctx.correlation_id,aid);
 PERFORM loyalty.leave_write(tok);
 PERFORM loyalty.settle_refund(fid);
 RETURN fid;
END;
$function$;

-- Both assessment actions are private-producer only.
CREATE OR REPLACE FUNCTION loyalty.guard_audit_origin()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF NEW.action IN ('POINTS_TRANSACTION_POSTED','UNRECOVERED_REVERSAL_AMOUNT','REFERRAL_INVALIDATED',
   'BOOKING_SERVICE_LOSS_CONFIRMED','BOOKING_SERVICE_LOSS_NOT_ESTABLISHED','BOOKING_FEE_REFUND_DECIDED','BOOKING_FEE_REFUND_CREDITED',
   'BOOKING_FEE_COLLECTION_RECORDED','LOYALTY_CONFIGURATION_CHANGED') THEN
   PERFORM loyalty.require_write('audit.audit_event',NEW.id::text);
 END IF;
 RETURN NEW;
END;
$function$;

-- Default deny for the new/replaced functions; the v1.1.24 security delta grants named entrypoints only.
DO $private_helpers_124$
DECLARE f record;
BEGIN
 FOR f IN SELECT p.oid::regprocedure sig FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='loyalty' LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.sig);
 END LOOP;
END;
$private_helpers_124$;

-- Upgrade preflight: existing data must already satisfy the corrected rules.
-- Nothing is rewritten; a mismatch stops the migration for explicit reconciliation.
DO $preflight_124$
DECLARE r record;
BEGIN
 FOR r IN SELECT a.id,a.booking_id,a.configuration_as_of FROM loyalty.reward_application a WHERE a.source_kind='BOOKING' LOOP
   IF r.configuration_as_of IS DISTINCT FROM loyalty.booking_completion_anchor(r.booking_id) THEN
     RAISE EXCEPTION 'v1.1.24 preflight: reward application % does not match the LOY-001 original anchor',r.id;
   END IF;
 END LOOP;
 FOR r IN SELECT f.id,f.booking_id,f.booking_history_id,f.service_loss_audit_id,f.amount FROM loyalty.booking_fee_refund f LOOP
   IF r.amount IS DISTINCT FROM (SELECT x.refund_amount FROM loyalty.refund_basis(r.booking_id,r.booking_history_id,r.service_loss_audit_id) x) THEN
     RAISE EXCEPTION 'v1.1.24 preflight: refund decision % differs from the corrected policy',r.id;
   END IF;
 END LOOP;
END;
$preflight_124$;


-- v1.1.25: platform hardening (consolidated review: REV-01..06, NTF-01..06, CFG-01..05, TEC-01..05,
-- ADM-01..03, AUD-01..05). Implementation-level integrity only: no Product state, reason code,
-- customer permission or Product value is introduced. Where a Product fact is needed (notification
-- catalogue content, non-Loyalty configuration keys) the database fails closed until the documented
-- source registers it.

-- ===========================================================================
-- ADM-01: ONE shared trusted Admin command context.
-- Trust and Loyalty keep their existing per-module tables, but both now bind to this single
-- context: one active Admin identity, one correlation and one command instant per transaction.
-- Reviews, Configuration, Notification recovery and Admin Alerts use it directly.
-- ===========================================================================
CREATE OR REPLACE FUNCTION trust.assert_owned_context(p_name text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_oid oid;
BEGIN
 IF p_name IS NULL OR p_name NOT IN ('e7gz_trust_admin_command_context','e7gz_loyalty_command_context','e7gz_loyalty_write_context',
                                      'e7gz_admin_command_context','e7gz_platform_write_context') THEN
   RAISE EXCEPTION 'Unknown protected context';
 END IF;
 v_oid:=to_regclass(format('pg_temp.%I',p_name));
 IF NOT EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=v_oid AND c.relnamespace=pg_my_temp_schema()
   AND c.relpersistence='t' AND c.relkind='r' AND NOT c.relrowsecurity
   AND c.relowner=(SELECT r.oid FROM pg_roles r WHERE r.rolname=current_user)) THEN
   RAISE EXCEPTION 'Missing or caller-owned protected context: %',p_name;
 END IF;
 IF EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(COALESCE(c.relacl,acldefault('r',c.relowner))) a
   WHERE c.oid=v_oid AND a.grantee<>c.relowner) THEN
   RAISE EXCEPTION 'Protected context has non-owner privileges: %',p_name;
 END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION trust.secure_created_context(p_name text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_oid oid; gr record;
BEGIN
 IF p_name IS NULL OR p_name NOT IN ('e7gz_trust_admin_command_context','e7gz_loyalty_command_context','e7gz_loyalty_write_context',
                                      'e7gz_admin_command_context','e7gz_platform_write_context') THEN RAISE EXCEPTION 'Unknown context'; END IF;
 v_oid:=to_regclass(format('pg_temp.%I',p_name));
 IF NOT EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=v_oid AND c.relnamespace=pg_my_temp_schema() AND c.relpersistence='t' AND c.relkind='r'
   AND c.relowner=(SELECT oid FROM pg_roles WHERE rolname=current_user)) THEN RAISE EXCEPTION 'Cannot adopt a caller-owned context'; END IF;
 EXECUTE format('REVOKE ALL ON pg_temp.%I FROM PUBLIC',p_name);
 FOR gr IN SELECT DISTINCT r.rolname FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a JOIN pg_roles r ON r.oid=a.grantee
   WHERE c.oid=v_oid AND a.grantee<>c.relowner LOOP
   EXECUTE format('REVOKE ALL ON pg_temp.%I FROM %I',p_name,gr.rolname);
 END LOOP;
 PERFORM trust.assert_owned_context(p_name);
END;
$function$;

-- Binds (or re-validates) the transaction's single Admin identity. A NULL correlation means
-- "not fixed yet" (Trust entry point); the first explicit correlation fixes it for the transaction.
CREATE OR REPLACE FUNCTION admin.bind_admin(p_admin_id uuid,p_correlation_id uuid)
RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_ctx record; v_now timestamptz;
BEGIN
 IF p_admin_id IS NULL THEN RAISE EXCEPTION 'Admin is required'; END IF;
 v_now:=tournament.command_now();
 PERFORM a.id FROM iam.admin_account a WHERE a.id=p_admin_id AND a.is_active FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Active Admin identity required'; END IF;
 IF to_regclass('pg_temp.e7gz_admin_command_context') IS NOT NULL THEN
   PERFORM trust.assert_owned_context('e7gz_admin_command_context');
   SELECT * INTO v_ctx FROM pg_temp.e7gz_admin_command_context c WHERE c.transaction_id=pg_current_xact_id();
   IF FOUND THEN
     IF v_ctx.admin_id IS DISTINCT FROM p_admin_id OR v_ctx.command_at IS DISTINCT FROM v_now THEN
       RAISE EXCEPTION 'Admin command identity cannot be rebound';
     END IF;
     IF p_correlation_id IS NOT NULL THEN
       IF v_ctx.correlation_id IS NULL THEN
         UPDATE pg_temp.e7gz_admin_command_context SET correlation_id=p_correlation_id WHERE transaction_id=pg_current_xact_id();
       ELSIF v_ctx.correlation_id IS DISTINCT FROM p_correlation_id THEN
         RAISE EXCEPTION 'One correlation per Admin command transaction';
       END IF;
     END IF;
     RETURN v_now;
   END IF;
 ELSE
   CREATE TEMP TABLE pg_temp.e7gz_admin_command_context(
     transaction_id xid8 PRIMARY KEY,admin_id uuid NOT NULL,correlation_id uuid,command_at timestamptz NOT NULL) ON COMMIT DROP;
   PERFORM trust.secure_created_context('e7gz_admin_command_context');
 END IF;
 INSERT INTO pg_temp.e7gz_admin_command_context VALUES(pg_current_xact_id(),p_admin_id,p_correlation_id,v_now);
 RETURN v_now;
END;
$function$;

-- Entry point for Admin commands outside Trust/Loyalty. Locks the named Users/Venues through the
-- existing shared command (lock order, command instant) before binding the Admin.
CREATE OR REPLACE FUNCTION admin.begin_command(p_admin_id uuid,p_correlation_id uuid,
  p_user_ids uuid[] DEFAULT ARRAY[]::uuid[],p_venue_ids uuid[] DEFAULT ARRAY[]::uuid[])
RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_shared record;
BEGIN
 IF p_admin_id IS NULL OR p_correlation_id IS NULL THEN RAISE EXCEPTION 'Admin command requires Admin and correlation'; END IF;
 IF to_regclass('pg_temp.e7gz_tournament_command_context') IS NULL THEN
   PERFORM tournament.begin_command(COALESCE(p_user_ids,ARRAY[]::uuid[]),COALESCE(p_venue_ids,ARRAY[]::uuid[]),ARRAY[]::uuid[],ARRAY[]::uuid[]);
 ELSE
   PERFORM tournament.command_now();
 END IF;
 SELECT * INTO STRICT v_shared FROM pg_temp.e7gz_tournament_command_context WHERE singleton AND transaction_id=pg_current_xact_id();
 IF NOT COALESCE(p_user_ids,ARRAY[]::uuid[]) <@ v_shared.user_ids OR NOT COALESCE(p_venue_ids,ARRAY[]::uuid[]) <@ v_shared.venue_ids THEN
   RAISE EXCEPTION 'Admin command Users/Venues must be inside the shared command lock scope';
 END IF;
 RETURN admin.bind_admin(p_admin_id,p_correlation_id);
END;
$function$;

CREATE OR REPLACE FUNCTION admin.command_context()
RETURNS TABLE(admin_id uuid,correlation_id uuid,command_at timestamptz)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_ctx record;
BEGIN
 PERFORM trust.assert_owned_context('e7gz_admin_command_context');
 SELECT * INTO v_ctx FROM pg_temp.e7gz_admin_command_context c WHERE c.transaction_id=pg_current_xact_id();
 IF NOT FOUND THEN RAISE EXCEPTION 'Missing trusted Admin command'; END IF;
 IF v_ctx.correlation_id IS NULL THEN RAISE EXCEPTION 'Admin command correlation is not fixed'; END IF;
 IF v_ctx.command_at IS DISTINCT FROM tournament.command_now() THEN RAISE EXCEPTION 'Stale Admin command time'; END IF;
 PERFORM a.id FROM iam.admin_account a WHERE a.id=v_ctx.admin_id AND a.is_active FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Inactive Admin'; END IF;
 RETURN QUERY SELECT v_ctx.admin_id,v_ctx.correlation_id,v_ctx.command_at;
END;
$function$;

-- v1.1.23 trust.begin_admin_command, unchanged except the final shared-context bind.
CREATE OR REPLACE FUNCTION trust.begin_admin_command(p_user_id uuid,p_admin_id uuid)
RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_now timestamptz; v_ctx record;
BEGIN
 IF p_user_id IS NULL OR p_admin_id IS NULL THEN RAISE EXCEPTION 'User and Admin are required'; END IF;
 -- Reject spoofed/precreated relations BEFORE invoking any DML on them.
 IF to_regclass('pg_temp.e7gz_trust_admin_command_context') IS NOT NULL THEN
   PERFORM trust.assert_owned_context('e7gz_trust_admin_command_context');
 END IF;
 PERFORM a.id FROM iam.admin_account a WHERE a.id=p_admin_id AND a.is_active FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Active Admin identity required'; END IF;
 IF to_regclass('pg_temp.e7gz_tournament_command_context') IS NULL THEN
   v_now:=trust.begin_command(p_user_id);
 ELSE
   v_now:=trust.command_now(p_user_id);
 END IF;
 IF to_regclass('pg_temp.e7gz_trust_admin_command_context') IS NULL THEN
   CREATE TEMP TABLE pg_temp.e7gz_trust_admin_command_context(
     transaction_id xid8 PRIMARY KEY,user_id uuid NOT NULL,admin_id uuid NOT NULL,command_now timestamptz NOT NULL
   ) ON COMMIT DROP;
   PERFORM trust.secure_created_context('e7gz_trust_admin_command_context');
 END IF;
 PERFORM trust.assert_owned_context('e7gz_trust_admin_command_context');
 SELECT * INTO v_ctx FROM pg_temp.e7gz_trust_admin_command_context WHERE transaction_id=pg_current_xact_id();
 IF FOUND THEN
   IF v_ctx.user_id IS DISTINCT FROM p_user_id OR v_ctx.admin_id IS DISTINCT FROM p_admin_id OR v_ctx.command_now IS DISTINCT FROM v_now THEN
     RAISE EXCEPTION 'Admin command identity cannot be rebound';
   END IF;
 ELSE
   INSERT INTO pg_temp.e7gz_trust_admin_command_context VALUES(pg_current_xact_id(),p_user_id,p_admin_id,v_now);
 END IF;
 -- v1.1.25 ADM-01: bind to the single shared Admin command identity.
 PERFORM admin.bind_admin(p_admin_id,NULL);
 RETURN v_now;
END;
$function$;

-- v1.1.23 loyalty.start_command, unchanged except the shared-context bind.
CREATE OR REPLACE FUNCTION loyalty.start_command(p_user_ids uuid[],p_admin_id uuid,p_correlation_id uuid)
RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_ids uuid[]; v_now timestamptz; v_ctx record; v_shared record;
BEGIN
 IF p_correlation_id IS NULL OR p_user_ids IS NULL OR array_position(p_user_ids,NULL) IS NOT NULL THEN
   RAISE EXCEPTION 'Loyalty command requires an explicit non-null scope and correlation';
 END IF;
 SELECT COALESCE(array_agg(DISTINCT x ORDER BY x),ARRAY[]::uuid[]) INTO v_ids FROM unnest(p_user_ids) x;
 IF p_admin_id IS NOT NULL THEN
   PERFORM a.id FROM iam.admin_account a WHERE a.id=p_admin_id AND a.is_active FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Active Admin required'; END IF;
 END IF;
 IF to_regclass('pg_temp.e7gz_loyalty_command_context') IS NOT NULL THEN
   PERFORM trust.assert_owned_context('e7gz_loyalty_command_context');
   SELECT * INTO v_ctx FROM loyalty.command_context(NULL);
   IF v_ctx.user_ids IS DISTINCT FROM v_ids OR v_ctx.admin_id IS DISTINCT FROM p_admin_id OR v_ctx.correlation_id IS DISTINCT FROM p_correlation_id THEN
     RAISE EXCEPTION 'One immutable Loyalty command context per transaction';
   END IF;
   RETURN v_ctx.command_at;
 END IF;
 IF to_regclass('pg_temp.e7gz_tournament_command_context') IS NULL THEN
   -- Config writers take the exclusive lock, before stamping effective_from.
   PERFORM pg_advisory_xact_lock_shared(1123,1);
   v_now:=tournament.begin_command(v_ids,ARRAY[]::uuid[],ARRAY[]::uuid[],ARRAY[]::uuid[]);
 ELSE
   v_now:=tournament.command_now();
   IF NOT pg_try_advisory_xact_lock_shared(1123,1) THEN
     RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Configuration writer in flight; retry the whole shared command';
   END IF;
 END IF;
 SELECT * INTO STRICT v_shared FROM pg_temp.e7gz_tournament_command_context WHERE singleton AND transaction_id=pg_current_xact_id();
 IF NOT v_ids<@v_shared.user_ids THEN RAISE EXCEPTION 'All Loyalty Users must be prelocked in the shared scope'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(v_ids) u WHERE NOT EXISTS(SELECT 1 FROM loyalty.points_account a WHERE a.user_id=u)
    OR NOT EXISTS(SELECT 1 FROM loyalty.wallet_account a WHERE a.user_id=u)) THEN
   RAISE EXCEPTION 'User Loyalty accounts must be initialized';
 END IF;
 -- User roots serialize account writes; every Loyalty writer uses the same roots.
 PERFORM a.user_id FROM loyalty.points_account a WHERE a.user_id=ANY(v_ids) ORDER BY a.user_id FOR UPDATE;
 PERFORM a.user_id FROM loyalty.wallet_account a WHERE a.user_id=ANY(v_ids) ORDER BY a.user_id FOR UPDATE;
 CREATE TEMP TABLE pg_temp.e7gz_loyalty_command_context(transaction_id xid8 PRIMARY KEY,user_ids uuid[] NOT NULL,admin_id uuid,correlation_id uuid NOT NULL,command_at timestamptz NOT NULL) ON COMMIT DROP;
 PERFORM trust.secure_created_context('e7gz_loyalty_command_context');
 PERFORM trust.assert_owned_context('e7gz_loyalty_command_context');
 INSERT INTO pg_temp.e7gz_loyalty_command_context VALUES(pg_current_xact_id(),v_ids,p_admin_id,p_correlation_id,v_now);
 -- v1.1.25 ADM-01: an Admin Loyalty command binds the shared Admin identity and fixes its correlation.
 IF p_admin_id IS NOT NULL THEN PERFORM admin.bind_admin(p_admin_id,p_correlation_id); END IF;
 RETURN v_now;
END;
$function$;

-- ===========================================================================
-- Private producer token for platform tables (same pattern as Loyalty's write token).
-- ===========================================================================
CREATE OR REPLACE FUNCTION technical.enter_write(p_table text,p_key text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_token uuid:=gen_random_uuid();
BEGIN
 IF to_regclass('pg_temp.e7gz_platform_write_context') IS NULL THEN
   CREATE TEMP TABLE pg_temp.e7gz_platform_write_context(token uuid PRIMARY KEY,transaction_id xid8 NOT NULL,table_name text NOT NULL,row_key text NOT NULL) ON COMMIT DROP;
   PERFORM trust.secure_created_context('e7gz_platform_write_context');
 END IF;
 PERFORM trust.assert_owned_context('e7gz_platform_write_context');
 INSERT INTO pg_temp.e7gz_platform_write_context VALUES(v_token,pg_current_xact_id(),p_table,p_key);
 RETURN v_token;
END;
$function$;
CREATE OR REPLACE FUNCTION technical.leave_write(p_token uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 PERFORM trust.assert_owned_context('e7gz_platform_write_context');
 DELETE FROM pg_temp.e7gz_platform_write_context WHERE token=p_token AND transaction_id=pg_current_xact_id();
END;
$function$;
CREATE OR REPLACE FUNCTION technical.has_write(p_table text,p_key text)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF to_regclass('pg_temp.e7gz_platform_write_context') IS NULL THEN RETURN false; END IF;
 PERFORM trust.assert_owned_context('e7gz_platform_write_context');
 RETURN EXISTS(SELECT 1 FROM pg_temp.e7gz_platform_write_context c
   WHERE c.transaction_id=pg_current_xact_id() AND c.table_name=p_table AND c.row_key=p_key);
END;
$function$;
CREATE OR REPLACE FUNCTION technical.require_write(p_table text,p_key text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF NOT technical.has_write(p_table,p_key) THEN
   RAISE EXCEPTION 'Mutation of % requires its private producer',p_table;
 END IF;
END;
$function$;

-- ===========================================================================
-- AUD-01 / AUD-02: actor provenance + fail-closed secret detection.
-- ===========================================================================
-- Returns the first forbidden key path, or NULL. Keys are normalised (lower-case, alphanumerics only)
-- and matched at every depth, including inside arrays.
CREATE OR REPLACE FUNCTION technical.forbidden_payload_key(p_payload jsonb,p_path text DEFAULT '')
RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $function$
DECLARE k text; v jsonb; n text; r text; i integer:=0;
BEGIN
 IF p_payload IS NULL THEN RETURN NULL; END IF;
 IF jsonb_typeof(p_payload)='object' THEN
   FOR k,v IN SELECT * FROM jsonb_each(p_payload) LOOP
     n:=lower(regexp_replace(k,'[^A-Za-z0-9]','','g'));
     IF n ~ '(password|passwd|passcode|passphrase|secret|otp|otpcode|token|apikey|privatekey|authorization|cookie|cvv|cvc|cardnumber|pan)$'
        OR n IN ('pin','hash','salt') THEN
       RETURN p_path||'/'||k;
     END IF;
     r:=technical.forbidden_payload_key(v,p_path||'/'||k);
     IF r IS NOT NULL THEN RETURN r; END IF;
   END LOOP;
 ELSIF jsonb_typeof(p_payload)='array' THEN
   FOR v IN SELECT * FROM jsonb_array_elements(p_payload) LOOP
     r:=technical.forbidden_payload_key(v,p_path||'['||i||']');
     IF r IS NOT NULL THEN RETURN r; END IF;
     i:=i+1;
   END LOOP;
 END IF;
 RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION technical.assert_principal(p_type text,p_id uuid,p_require_active_admin boolean DEFAULT true)
RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF p_type='ADMIN' THEN
   IF p_id IS NULL OR NOT EXISTS(SELECT 1 FROM iam.admin_account a WHERE a.id=p_id AND (a.is_active OR NOT p_require_active_admin)) THEN
     RAISE EXCEPTION 'ADMIN actor must be an active Admin account';
   END IF;
 ELSIF p_type='CUSTOMER' THEN
   IF p_id IS NULL OR NOT EXISTS(SELECT 1 FROM iam.user_account u WHERE u.id=p_id) THEN RAISE EXCEPTION 'CUSTOMER actor must be a real User'; END IF;
 ELSIF p_type='VENUE' THEN
   IF p_id IS NULL OR NOT EXISTS(SELECT 1 FROM iam.venue_account v WHERE v.id=p_id) THEN RAISE EXCEPTION 'VENUE actor must be a real Venue Account'; END IF;
 ELSIF p_type='SYSTEM' THEN
   IF p_id IS NOT NULL THEN RAISE EXCEPTION 'SYSTEM actor has no actor id'; END IF;
 ELSE RAISE EXCEPTION 'Unknown actor type %',p_type;
 END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION audit.guard_audit_insert()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE k text;
BEGIN
 PERFORM technical.assert_principal(NEW.actor_type,NEW.actor_id,true);
 k:=technical.forbidden_payload_key(NEW.payload);
 IF k IS NOT NULL THEN RAISE EXCEPTION 'Audit payload contains a forbidden credential/secret field: %',k; END IF;
 IF NEW.occurred_at>clock_timestamp() THEN RAISE EXCEPTION 'Audit occurred_at cannot be in the future'; END IF;
 IF NEW.reason IS NOT NULL AND length(btrim(NEW.reason))=0 THEN RAISE EXCEPTION 'Audit reason cannot be blank'; END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_125_audit_provenance ON audit.audit_event;
CREATE TRIGGER tr_125_audit_provenance BEFORE INSERT ON audit.audit_event FOR EACH ROW EXECUTE FUNCTION audit.guard_audit_insert();

-- AUD-04: TRUNCATE is also a mutation of an immutable store.
CREATE OR REPLACE FUNCTION technical.reject_truncate()
RETURNS trigger LANGUAGE plpgsql AS $function$
BEGIN
 RAISE EXCEPTION '%.% is append-only; TRUNCATE is rejected',TG_TABLE_SCHEMA,TG_TABLE_NAME;
END;
$function$;
DROP TRIGGER IF EXISTS tr_125_audit_no_truncate ON audit.audit_event;
CREATE TRIGGER tr_125_audit_no_truncate BEFORE TRUNCATE ON audit.audit_event FOR EACH STATEMENT EXECUTE FUNCTION technical.reject_truncate();

-- ===========================================================================
-- ADM-03: Admin Alerts - immutable source facts, one audited acknowledgement.
-- ===========================================================================
CREATE OR REPLACE FUNCTION admin.guard_admin_alert()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE k text;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Admin Alerts are retained; DELETE is rejected'; END IF;
 IF TG_OP='INSERT' THEN
   IF NEW.acknowledged_at IS NOT NULL OR NEW.acknowledged_by_admin_id IS NOT NULL THEN RAISE EXCEPTION 'A new Admin Alert cannot be pre-acknowledged'; END IF;
   IF NEW.created_at>clock_timestamp() THEN RAISE EXCEPTION 'Admin Alert created_at cannot be in the future'; END IF;
   k:=technical.forbidden_payload_key(NEW.payload);
   IF k IS NOT NULL THEN RAISE EXCEPTION 'Admin Alert payload contains a forbidden credential/secret field: %',k; END IF;
   RETURN NEW;
 END IF;
 PERFORM technical.require_write('admin.admin_alert',NEW.id::text);
 IF (to_jsonb(NEW)-ARRAY['acknowledged_at','acknowledged_by_admin_id']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['acknowledged_at','acknowledged_by_admin_id'])
    OR OLD.acknowledged_at IS NOT NULL OR NEW.acknowledged_at IS NULL THEN
   RAISE EXCEPTION 'Admin Alert source facts are immutable; only one acknowledgement is allowed';
 END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_125_admin_alert_guard ON admin.admin_alert;
CREATE TRIGGER tr_125_admin_alert_guard BEFORE INSERT OR UPDATE OR DELETE ON admin.admin_alert FOR EACH ROW EXECUTE FUNCTION admin.guard_admin_alert();
DROP TRIGGER IF EXISTS tr_125_admin_alert_no_truncate ON admin.admin_alert;
CREATE TRIGGER tr_125_admin_alert_no_truncate BEFORE TRUNCATE ON admin.admin_alert FOR EACH STATEMENT EXECUTE FUNCTION technical.reject_truncate();

CREATE OR REPLACE FUNCTION admin.acknowledge_alert(p_alert_id uuid,p_reason text DEFAULT NULL)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE ctx record; a admin.admin_alert%ROWTYPE; tok uuid; aid uuid:=gen_random_uuid();
BEGIN
 SELECT * INTO STRICT ctx FROM admin.command_context();
 SELECT * INTO a FROM admin.admin_alert WHERE id=p_alert_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Unknown Admin Alert'; END IF;
 IF a.acknowledged_at IS NOT NULL THEN
   IF a.acknowledged_by_admin_id=ctx.admin_id THEN RETURN a.id; END IF;
   RAISE EXCEPTION 'Admin Alert is already acknowledged';
 END IF;
 INSERT INTO audit.audit_event(id,occurred_at,actor_type,actor_id,action,subject_type,subject_id,reason,correlation_id,payload,previous_state,new_state)
 VALUES(aid,ctx.command_at,'ADMIN',ctx.admin_id,'ADMIN_ALERT_ACKNOWLEDGED','ADMIN_ALERT',a.id,NULLIF(btrim(p_reason),''),ctx.correlation_id,
   jsonb_build_object('kind',a.kind,'severity',a.severity),'OPEN','ACKNOWLEDGED');
 tok:=technical.enter_write('admin.admin_alert',a.id::text);
 UPDATE admin.admin_alert SET acknowledged_at=ctx.command_at,acknowledged_by_admin_id=ctx.admin_id WHERE id=a.id;
 PERFORM technical.leave_write(tok);
 RETURN a.id;
END;
$function$;

-- ===========================================================================
-- REV-01..06 / ADM-02: Review lifecycle, eligibility, cooldown, moderation ledger, projection.
-- ===========================================================================
CREATE OR REPLACE FUNCTION review.guard_review()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Reviews are never deleted; use REMOVED'; END IF;
 PERFORM technical.require_write('review.review',NEW.id::text);
 IF TG_OP='INSERT' THEN
   IF NEW.status NOT IN ('ACTIVE','PENDING_MODERATION') OR NEW.author_deleted_at IS NOT NULL OR NEW.updated_at<>NEW.created_at THEN
     RAISE EXCEPTION 'A Review is created ACTIVE or PENDING_MODERATION only';
   END IF;
   RETURN NEW;
 END IF;
 IF NEW.id<>OLD.id OR NEW.user_id<>OLD.user_id OR NEW.venue_id<>OLD.venue_id OR NEW.created_at<>OLD.created_at THEN
   RAISE EXCEPTION 'Review identity and created_at are immutable';
 END IF;
 IF OLD.status='REMOVED' THEN RAISE EXCEPTION 'REMOVED Review is terminal'; END IF;
 IF NEW.updated_at<OLD.updated_at THEN RAISE EXCEPTION 'Review updated_at cannot move backwards'; END IF;
 IF NEW.status=OLD.status THEN
   -- author edit: content may change, status is preserved (a HIDDEN edit stays HIDDEN)
   IF NEW.author_deleted_at IS NOT NULL THEN RAISE EXCEPTION 'Invalid author deletion shape'; END IF;
   RETURN NEW;
 END IF;
 IF NEW.rating<>OLD.rating OR NEW.comment<>OLD.comment THEN RAISE EXCEPTION 'Content edit and status change are separate commands'; END IF;
 IF NOT ((OLD.status='PENDING_MODERATION' AND NEW.status='ACTIVE') OR (OLD.status='ACTIVE' AND NEW.status='HIDDEN')
      OR (OLD.status='HIDDEN' AND NEW.status='ACTIVE') OR NEW.status='REMOVED') THEN
   RAISE EXCEPTION 'Invalid Review transition % -> %',OLD.status,NEW.status;
 END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_125_review_lifecycle ON review.review;
CREATE TRIGGER tr_125_review_lifecycle BEFORE INSERT OR UPDATE OR DELETE ON review.review FOR EACH ROW EXECUTE FUNCTION review.guard_review();
DROP TRIGGER IF EXISTS tr_125_review_no_truncate ON review.review;
CREATE TRIGGER tr_125_review_no_truncate BEFORE TRUNCATE ON review.review FOR EACH STATEMENT EXECUTE FUNCTION technical.reject_truncate();

CREATE OR REPLACE FUNCTION review.guard_private_insert()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION '%.% is append-only',TG_TABLE_SCHEMA,TG_TABLE_NAME; END IF;
 PERFORM technical.require_write(TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME,NEW.id::text);
 RETURN NEW;
END;
$function$;
DO $review_ledgers$
DECLARE n text;
BEGIN
 FOREACH n IN ARRAY ARRAY['review_moderation_event','review_cooldown'] LOOP
   EXECUTE format('DROP TRIGGER IF EXISTS tr_125_private_append ON review.%I',n);
   EXECUTE format('CREATE TRIGGER tr_125_private_append BEFORE INSERT OR UPDATE OR DELETE ON review.%I FOR EACH ROW EXECUTE FUNCTION review.guard_private_insert()',n);
   EXECUTE format('DROP TRIGGER IF EXISTS tr_125_no_truncate ON review.%I',n);
   EXECUTE format('CREATE TRIGGER tr_125_no_truncate BEFORE TRUNCATE ON review.%I FOR EACH STATEMENT EXECUTE FUNCTION technical.reject_truncate()',n);
 END LOOP;
END;
$review_ledgers$;

CREATE OR REPLACE FUNCTION review.guard_rating_stats()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Rating projection rows are rebuilt, not deleted'; END IF;
 PERFORM technical.require_write('review.venue_rating_stats',NEW.venue_id::text);
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_125_rating_stats_guard ON review.venue_rating_stats;
CREATE TRIGGER tr_125_rating_stats_guard BEFORE INSERT OR UPDATE OR DELETE ON review.venue_rating_stats FOR EACH ROW EXECUTE FUNCTION review.guard_rating_stats();

-- Canonical projection derivation, shared by the refresher and the deferred check.
CREATE OR REPLACE FUNCTION review.expected_rating(p_venue uuid)
RETURNS TABLE(review_count integer,average_rating numeric,d1 integer,d2 integer,d3 integer,d4 integer,d5 integer)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
 SELECT count(*)::integer,
        CASE WHEN count(*)=0 THEN NULL ELSE round(avg(r.rating)::numeric,2) END,
        count(*) FILTER (WHERE r.rating=1)::integer,count(*) FILTER (WHERE r.rating=2)::integer,
        count(*) FILTER (WHERE r.rating=3)::integer,count(*) FILTER (WHERE r.rating=4)::integer,
        count(*) FILTER (WHERE r.rating=5)::integer
   FROM review.review r WHERE r.venue_id=p_venue AND r.status='ACTIVE';
$function$;

CREATE OR REPLACE FUNCTION review.refresh_venue_rating(p_venue uuid,p_at timestamptz)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE e record; tok uuid;
BEGIN
 SELECT * INTO STRICT e FROM review.expected_rating(p_venue);
 tok:=technical.enter_write('review.venue_rating_stats',p_venue::text);
 INSERT INTO review.venue_rating_stats(venue_id,average_rating,review_count,distribution_1,distribution_2,distribution_3,distribution_4,distribution_5,updated_at)
 VALUES(p_venue,e.average_rating,e.review_count,e.d1,e.d2,e.d3,e.d4,e.d5,p_at)
 ON CONFLICT(venue_id) DO UPDATE SET average_rating=EXCLUDED.average_rating,review_count=EXCLUDED.review_count,
   distribution_1=EXCLUDED.distribution_1,distribution_2=EXCLUDED.distribution_2,distribution_3=EXCLUDED.distribution_3,
   distribution_4=EXCLUDED.distribution_4,distribution_5=EXCLUDED.distribution_5,updated_at=EXCLUDED.updated_at;
 PERFORM technical.leave_write(tok);
END;
$function$;

CREATE OR REPLACE FUNCTION review.assert_venue_rating(p_venue uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE e record; s review.venue_rating_stats%ROWTYPE;
BEGIN
 SELECT * INTO STRICT e FROM review.expected_rating(p_venue);
 SELECT * INTO s FROM review.venue_rating_stats WHERE venue_id=p_venue;
 IF NOT FOUND THEN
   IF e.review_count>0 THEN RAISE EXCEPTION 'Venue % has ACTIVE Reviews but no rating projection',p_venue; END IF;
   RETURN;
 END IF;
 IF s.review_count<>e.review_count OR s.average_rating IS DISTINCT FROM e.average_rating OR s.distribution_1<>e.d1 OR s.distribution_2<>e.d2
    OR s.distribution_3<>e.d3 OR s.distribution_4<>e.d4 OR s.distribution_5<>e.d5 THEN
   RAISE EXCEPTION 'Venue % rating projection differs from canonical ACTIVE Reviews',p_venue;
 END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION review.assert_rating_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 PERFORM review.assert_venue_rating(CASE WHEN TG_OP='DELETE' THEN OLD.venue_id ELSE NEW.venue_id END);
 RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_125_review_rating_final ON review.review;
CREATE CONSTRAINT TRIGGER tr_125_review_rating_final AFTER INSERT OR UPDATE ON review.review DEFERRABLE INITIALLY DEFERRED
 FOR EACH ROW EXECUTE FUNCTION review.assert_rating_trigger();
DROP TRIGGER IF EXISTS tr_125_rating_stats_final ON review.venue_rating_stats;
CREATE CONSTRAINT TRIGGER tr_125_rating_stats_final AFTER INSERT OR UPDATE ON review.venue_rating_stats DEFERRABLE INITIALLY DEFERRED
 FOR EACH ROW EXECUTE FUNCTION review.assert_rating_trigger();

-- Every Admin status change carries its exact moderation event (and every REMOVE its cooldown).
CREATE OR REPLACE FUNCTION review.assert_review_row()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE r review.review%ROWTYPE; ev review.review_moderation_event%ROWTYPE;
BEGIN
 SELECT * INTO STRICT r FROM review.review WHERE id=NEW.id;
 SELECT * INTO ev FROM review.review_moderation_event e WHERE e.review_id=r.id ORDER BY e.occurred_at DESC,e.id DESC LIMIT 1;
 IF r.status='HIDDEN' OR (r.status='REMOVED' AND r.author_deleted_at IS NULL)
    OR (r.status='ACTIVE' AND ev.id IS NOT NULL) THEN
   IF ev.id IS NULL OR ev.new_status<>r.status THEN
     RAISE EXCEPTION 'Review % status % lacks its matching moderation event',r.id,r.status;
   END IF;
 END IF;
 IF r.status='REMOVED' AND r.author_deleted_at IS NULL AND NOT EXISTS(
    SELECT 1 FROM review.review_cooldown c WHERE c.moderation_event_id=ev.id AND c.review_id=r.id
      AND c.user_id=r.user_id AND c.venue_id=r.venue_id AND c.removed_at=ev.occurred_at) THEN
   RAISE EXCEPTION 'Admin removal of Review % must create its cooldown atomically',r.id;
 END IF;
 RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_125_review_final ON review.review;
CREATE CONSTRAINT TRIGGER tr_125_review_final AFTER INSERT OR UPDATE ON review.review DEFERRABLE INITIALLY DEFERRED
 FOR EACH ROW EXECUTE FUNCTION review.assert_review_row();

CREATE OR REPLACE FUNCTION review.write_audit(p_actor_type text,p_actor uuid,p_action text,p_review uuid,p_reason text,
  p_corr uuid,p_at timestamptz,p_prev text,p_new text,p_user uuid,p_venue uuid,p_payload jsonb)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_id uuid:=gen_random_uuid();
BEGIN
 INSERT INTO audit.audit_event(id,occurred_at,actor_type,actor_id,action,subject_type,subject_id,reason,correlation_id,payload,
   previous_state,new_state,context_user_id,context_venue_id)
 VALUES(v_id,p_at,p_actor_type,p_actor,p_action,'REVIEW',p_review,p_reason,p_corr,COALESCE(p_payload,'{}'::jsonb),p_prev,p_new,p_user,p_venue);
 RETURN v_id;
END;
$function$;

CREATE OR REPLACE FUNCTION review.customer_command(p_user uuid,p_venue uuid)
RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_shared record;
BEGIN
 IF to_regclass('pg_temp.e7gz_tournament_command_context') IS NULL THEN
   PERFORM tournament.begin_command(ARRAY[p_user],ARRAY[p_venue],ARRAY[]::uuid[],ARRAY[]::uuid[]);
 END IF;
 SELECT * INTO STRICT v_shared FROM pg_temp.e7gz_tournament_command_context WHERE singleton AND transaction_id=pg_current_xact_id();
 IF NOT p_user=ANY(v_shared.user_ids) OR NOT p_venue=ANY(v_shared.venue_ids) THEN
   RAISE EXCEPTION 'Review command User/Venue must be inside the shared command lock scope';
 END IF;
 RETURN tournament.command_now();
END;
$function$;

-- REV-03: eligibility + cooldown. Customer identity comes from the authenticated backend session.
CREATE OR REPLACE FUNCTION review.create_review(p_user uuid,p_venue uuid,p_rating smallint,p_comment text,p_correlation uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_now timestamptz; u iam.user_account%ROWTYPE; v_status text; v_id uuid:=gen_random_uuid(); tok uuid; c review.review_cooldown%ROWTYPE;
BEGIN
 IF p_correlation IS NULL THEN RAISE EXCEPTION 'Correlation is required'; END IF;
 v_now:=review.customer_command(p_user,p_venue);
 SELECT * INTO u FROM iam.user_account WHERE id=p_user;
 IF NOT FOUND OR NOT u.phone_verified OR u.anonymised_at IS NOT NULL THEN
   RAISE EXCEPTION 'Only a phone-verified, non-anonymised User can create a Review';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM venue.venue v WHERE v.id=p_venue) THEN RAISE EXCEPTION 'Unknown Venue'; END IF;
 IF EXISTS(SELECT 1 FROM review.review r WHERE r.user_id=p_user AND r.venue_id=p_venue AND r.status<>'REMOVED') THEN
   RAISE EXCEPTION 'User already has a current Review for this Venue; edit it instead';
 END IF;
 SELECT * INTO c FROM review.review_cooldown x WHERE x.user_id=p_user AND x.venue_id=p_venue ORDER BY x.cooldown_until DESC LIMIT 1;
 IF FOUND AND v_now<c.cooldown_until THEN
   RAISE EXCEPTION 'Review cooldown after Admin removal is active until %',c.cooldown_until;
 END IF;
 v_status:=CASE WHEN FOUND THEN 'PENDING_MODERATION' ELSE 'ACTIVE' END;
 tok:=technical.enter_write('review.review',v_id::text);
 INSERT INTO review.review(id,user_id,venue_id,rating,comment,status,created_at,updated_at)
 VALUES(v_id,p_user,p_venue,p_rating,p_comment,v_status,v_now,v_now);
 PERFORM technical.leave_write(tok);
 PERFORM review.write_audit('CUSTOMER',p_user,'REVIEW_CREATED',v_id,NULL,p_correlation,v_now,NULL,v_status,p_user,p_venue,
   jsonb_build_object('rating',p_rating));
 PERFORM review.refresh_venue_rating(p_venue,v_now);
 RETURN v_id;
END;
$function$;

CREATE OR REPLACE FUNCTION review.edit_review(p_review uuid,p_user uuid,p_rating smallint,p_comment text,p_correlation uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE r review.review%ROWTYPE; v_now timestamptz; tok uuid;
BEGIN
 IF p_correlation IS NULL THEN RAISE EXCEPTION 'Correlation is required'; END IF;
 SELECT * INTO r FROM review.review WHERE id=p_review;
 IF NOT FOUND OR r.user_id<>p_user THEN RAISE EXCEPTION 'Only the author can edit a Review'; END IF;
 v_now:=review.customer_command(r.user_id,r.venue_id);
 SELECT * INTO STRICT r FROM review.review WHERE id=p_review FOR UPDATE;
 IF r.status='REMOVED' THEN RAISE EXCEPTION 'REMOVED Review is terminal'; END IF;
 tok:=technical.enter_write('review.review',r.id::text);
 UPDATE review.review SET rating=p_rating,comment=p_comment,updated_at=v_now WHERE id=r.id;
 PERFORM technical.leave_write(tok);
 PERFORM review.write_audit('CUSTOMER',p_user,'REVIEW_EDITED',r.id,NULL,p_correlation,v_now,r.status,r.status,r.user_id,r.venue_id,
   jsonb_build_object('previousRating',r.rating,'rating',p_rating));
 PERFORM review.refresh_venue_rating(r.venue_id,v_now);
 RETURN r.id;
END;
$function$;

-- Author deletion (author_deleted_at, existing column): REMOVED without a moderation event or cooldown.
CREATE OR REPLACE FUNCTION review.delete_own_review(p_review uuid,p_user uuid,p_correlation uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE r review.review%ROWTYPE; v_now timestamptz; tok uuid;
BEGIN
 IF p_correlation IS NULL THEN RAISE EXCEPTION 'Correlation is required'; END IF;
 SELECT * INTO r FROM review.review WHERE id=p_review;
 IF NOT FOUND OR r.user_id<>p_user THEN RAISE EXCEPTION 'Only the author can delete a Review'; END IF;
 v_now:=review.customer_command(r.user_id,r.venue_id);
 SELECT * INTO STRICT r FROM review.review WHERE id=p_review FOR UPDATE;
 IF r.status='REMOVED' THEN RAISE EXCEPTION 'REMOVED Review is terminal'; END IF;
 tok:=technical.enter_write('review.review',r.id::text);
 UPDATE review.review SET status='REMOVED',author_deleted_at=v_now,updated_at=v_now WHERE id=r.id;
 PERFORM technical.leave_write(tok);
 PERFORM review.write_audit('CUSTOMER',p_user,'REVIEW_DELETED_BY_AUTHOR',r.id,NULL,p_correlation,v_now,r.status,'REMOVED',r.user_id,r.venue_id,NULL);
 PERFORM review.refresh_venue_rating(r.venue_id,v_now);
 RETURN r.id;
END;
$function$;

-- ADM-02: one atomic Admin moderation command.
CREATE OR REPLACE FUNCTION review.moderate(p_review uuid,p_action text,p_reason text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE ctx record; r review.review%ROWTYPE; v_new text; ev uuid:=gen_random_uuid(); cid uuid:=gen_random_uuid(); aid uuid; tok uuid; v_users uuid[]; v_venues uuid[];
BEGIN
 SELECT * INTO STRICT ctx FROM admin.command_context();
 IF NULLIF(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'Moderation reason is required'; END IF;
 SELECT * INTO r FROM review.review WHERE id=p_review;
 IF NOT FOUND THEN RAISE EXCEPTION 'Unknown Review'; END IF;
 SELECT c.user_ids,c.venue_ids INTO STRICT v_users,v_venues FROM pg_temp.e7gz_tournament_command_context c
  WHERE c.singleton AND c.transaction_id=pg_current_xact_id();
 IF NOT r.user_id=ANY(v_users) OR NOT r.venue_id=ANY(v_venues) THEN
   RAISE EXCEPTION 'Moderation requires the Review author and Venue in the Admin command scope';
 END IF;
 SELECT * INTO STRICT r FROM review.review WHERE id=p_review FOR UPDATE;
 v_new:=CASE WHEN p_action='APPROVE' AND r.status='PENDING_MODERATION' THEN 'ACTIVE'
             WHEN p_action='HIDE' AND r.status='ACTIVE' THEN 'HIDDEN'
             WHEN p_action='RESTORE' AND r.status='HIDDEN' THEN 'ACTIVE'
             WHEN p_action='REMOVE' AND r.status IN ('ACTIVE','HIDDEN','PENDING_MODERATION') THEN 'REMOVED' END;
 IF v_new IS NULL THEN RAISE EXCEPTION 'Moderation action % is not valid from %',p_action,r.status; END IF;
 tok:=technical.enter_write('review.review',r.id::text);
 UPDATE review.review SET status=v_new,updated_at=ctx.command_at WHERE id=r.id;
 PERFORM technical.leave_write(tok);
 aid:=review.write_audit('ADMIN',ctx.admin_id,'REVIEW_'||p_action,r.id,p_reason,ctx.correlation_id,ctx.command_at,r.status,v_new,r.user_id,r.venue_id,
   jsonb_build_object('moderationEventId',ev));
 tok:=technical.enter_write('review.review_moderation_event',ev::text);
 INSERT INTO review.review_moderation_event(id,review_id,action,previous_status,new_status,admin_id,reason,occurred_at,correlation_id,audit_event_id)
 VALUES(ev,r.id,p_action,r.status,v_new,ctx.admin_id,p_reason,ctx.command_at,ctx.correlation_id,aid);
 PERFORM technical.leave_write(tok);
 IF p_action='REMOVE' THEN
   tok:=technical.enter_write('review.review_cooldown',cid::text);
   INSERT INTO review.review_cooldown(id,user_id,venue_id,removed_at,cooldown_until,review_id,moderation_event_id)
   VALUES(cid,r.user_id,r.venue_id,ctx.command_at,ctx.command_at+interval '30 days',r.id,ev);
   PERFORM technical.leave_write(tok);
 END IF;
 PERFORM review.refresh_venue_rating(r.venue_id,ctx.command_at);
 -- Author notification is emitted through the Outbox in the same transaction (dispatched after commit).
 INSERT INTO technical.outbox_event(event_type,aggregate_type,aggregate_id,payload,correlation_id,state,attempt,next_attempt_at)
 VALUES('ReviewModerated','REVIEW',r.id,jsonb_build_object('reviewId',r.id,'moderationEventId',ev,'action',p_action,
   'previousStatus',r.status,'newStatus',v_new,'recipientType','CUSTOMER','recipientId',r.user_id,'venueId',r.venue_id,'occurredAt',ctx.command_at),
   ctx.correlation_id,'PENDING',0,ctx.command_at);
 RETURN ev;
END;
$function$;

-- ===========================================================================
-- NTF-01..06: recipient integrity, catalogue-driven reference/channel policy,
-- required channel set, worker-only delivery lifecycle, device token lifecycle.
-- ===========================================================================
CREATE OR REPLACE FUNCTION notification.guard_catalogue()
RETURNS trigger LANGUAGE plpgsql AS $function$
BEGIN
 RAISE EXCEPTION 'notification_catalogue is append-only (register a new code instead)';
END;
$function$;
DROP TRIGGER IF EXISTS tr_125_catalogue_append_only ON notification.notification_catalogue;
CREATE TRIGGER tr_125_catalogue_append_only BEFORE UPDATE OR DELETE ON notification.notification_catalogue FOR EACH ROW EXECUTE FUNCTION notification.guard_catalogue();
DROP TRIGGER IF EXISTS tr_125_catalogue_no_truncate ON notification.notification_catalogue;
CREATE TRIGGER tr_125_catalogue_no_truncate BEFORE TRUNCATE ON notification.notification_catalogue FOR EACH STATEMENT EXECUTE FUNCTION technical.reject_truncate();

CREATE OR REPLACE FUNCTION notification.assert_recipient(p_type text,p_id uuid,c notification.notification_catalogue,p_booking uuid,p_tournament uuid)
RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE b booking.booking%ROWTYPE; t tournament.tournament%ROWTYPE;
BEGIN
 IF NOT p_type=ANY(c.recipient_types) THEN RAISE EXCEPTION 'Recipient type % is not allowed for notification %',p_type,c.code; END IF;
 IF p_type='CUSTOMER' AND NOT EXISTS(SELECT 1 FROM iam.user_account u WHERE u.id=p_id) THEN RAISE EXCEPTION 'CUSTOMER recipient must be a User'; END IF;
 IF p_type='VENUE' AND NOT EXISTS(SELECT 1 FROM venue.venue v WHERE v.id=p_id) THEN RAISE EXCEPTION 'VENUE recipient must be a Venue'; END IF;
 IF p_type='ADMIN' AND NOT EXISTS(SELECT 1 FROM iam.admin_account a WHERE a.id=p_id AND a.is_active) THEN RAISE EXCEPTION 'ADMIN recipient must be an active Admin'; END IF;
 IF c.reference_type='BOOKING' THEN
   IF p_booking IS NULL OR p_tournament IS NOT NULL THEN RAISE EXCEPTION 'Booking notification % requires exactly its Booking reference',c.code; END IF;
   SELECT * INTO STRICT b FROM booking.booking WHERE id=p_booking;
   IF (p_type='CUSTOMER' AND b.customer_id IS DISTINCT FROM p_id) OR (p_type='VENUE' AND b.venue_id<>p_id) THEN
     RAISE EXCEPTION 'Notification recipient is not a party of Booking %',p_booking;
   END IF;
 ELSIF c.reference_type='TOURNAMENT' THEN
   IF p_tournament IS NULL OR p_booking IS NOT NULL THEN RAISE EXCEPTION 'Tournament notification % requires exactly its Tournament reference',c.code; END IF;
   SELECT * INTO STRICT t FROM tournament.tournament WHERE id=p_tournament;
   IF (p_type='CUSTOMER' AND t.creator_user_id IS DISTINCT FROM p_id
         AND NOT EXISTS(SELECT 1 FROM tournament.tournament_participant tp WHERE tp.tournament_id=t.id AND tp.user_id=p_id))
      OR (p_type='VENUE' AND t.venue_id<>p_id) THEN
     RAISE EXCEPTION 'Notification recipient is not a party of Tournament %',p_tournament;
   END IF;
 ELSIF p_booking IS NOT NULL OR p_tournament IS NOT NULL THEN
   RAISE EXCEPTION 'Notification % carries no Booking/Tournament reference',c.code;
 END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION notification.guard_notification()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE c notification.notification_catalogue%ROWTYPE; k text;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Notifications are retained; DELETE is rejected'; END IF;
 IF TG_OP='INSERT' THEN
   SELECT * INTO c FROM notification.notification_catalogue WHERE code=NEW.code;
   IF NOT FOUND THEN RAISE EXCEPTION 'Notification code % is not registered in the catalogue',NEW.code; END IF;
   PERFORM notification.assert_recipient(NEW.recipient_type,NEW.recipient_id,c,NEW.booking_id,NEW.tournament_id);
   IF NEW.read_at IS NOT NULL THEN RAISE EXCEPTION 'A new notification cannot be pre-read'; END IF;
   IF NEW.created_at>clock_timestamp() THEN RAISE EXCEPTION 'Notification created_at cannot be in the future'; END IF;
   k:=technical.forbidden_payload_key(NEW.params);
   IF k IS NOT NULL THEN RAISE EXCEPTION 'Notification params contain a forbidden secret field: %',k; END IF;
   RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-'read_at') IS DISTINCT FROM (to_jsonb(OLD)-'read_at') OR OLD.read_at IS NOT NULL OR NEW.read_at IS NULL THEN
   RAISE EXCEPTION 'Notification is immutable except a single read_at mark';
 END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_125_notification_guard ON notification.notification;
CREATE TRIGGER tr_125_notification_guard BEFORE INSERT OR UPDATE OR DELETE ON notification.notification FOR EACH ROW EXECUTE FUNCTION notification.guard_notification();
DROP TRIGGER IF EXISTS tr_125_notification_no_truncate ON notification.notification;
CREATE TRIGGER tr_125_notification_no_truncate BEFORE TRUNCATE ON notification.notification FOR EACH STATEMENT EXECUTE FUNCTION technical.reject_truncate();

-- NTF-03: every required channel has a delivery row by COMMIT.
CREATE OR REPLACE FUNCTION notification.assert_required_channels()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE missing text[];
BEGIN
 SELECT array_agg(ch) INTO missing FROM notification.notification n JOIN notification.notification_catalogue c ON c.code=n.code
   CROSS JOIN LATERAL unnest(c.required_channels) ch
  WHERE n.id=NEW.id AND NOT EXISTS(SELECT 1 FROM notification.notification_delivery d WHERE d.notification_id=n.id AND d.channel=ch);
 IF missing IS NOT NULL THEN RAISE EXCEPTION 'Notification % lacks required delivery channel(s) %',NEW.id,missing; END IF;
 RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_125_notification_required_channels ON notification.notification;
CREATE CONSTRAINT TRIGGER tr_125_notification_required_channels AFTER INSERT ON notification.notification DEFERRABLE INITIALLY DEFERRED
 FOR EACH ROW EXECUTE FUNCTION notification.assert_required_channels();

-- NTF-02 / NTF-05: channel policy + worker-only lifecycle.
CREATE OR REPLACE FUNCTION notification.guard_delivery()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE c notification.notification_catalogue%ROWTYPE; v_recovery boolean;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Delivery attempts are retained; DELETE is rejected'; END IF;
 IF TG_OP='INSERT' THEN
   SELECT c2.* INTO STRICT c FROM notification.notification n JOIN notification.notification_catalogue c2 ON c2.code=n.code WHERE n.id=NEW.notification_id;
   IF NOT NEW.channel=ANY(c.allowed_channels) THEN
     RAISE EXCEPTION 'Channel % is not allowed for notification % %',NEW.channel,c.code,
       CASE WHEN NEW.channel='SMS' THEN ' (SMS is OTP-only at launch)' ELSE '' END;
   END IF;
   IF NEW.status<>'PENDING' OR NEW.attempt<>0 OR NEW.provider_message_id IS NOT NULL OR NEW.error_code IS NOT NULL OR NEW.last_attempt_at IS NOT NULL THEN
     RAISE EXCEPTION 'A new delivery starts PENDING with no attempt';
   END IF;
   RETURN NEW;
 END IF;
 PERFORM technical.require_write('notification.notification_delivery',NEW.id::text);
 IF NEW.id<>OLD.id OR NEW.notification_id<>OLD.notification_id OR NEW.channel<>OLD.channel OR NEW.created_at<>OLD.created_at THEN
   RAISE EXCEPTION 'Delivery identity is immutable';
 END IF;
 v_recovery:=technical.has_write('notification.notification_delivery.recovery',NEW.id::text);
 IF OLD.status='DEAD_LETTER' THEN
   IF NOT v_recovery OR NEW.status<>'PENDING' OR NEW.attempt<>OLD.attempt OR NEW.last_attempt_at IS DISTINCT FROM OLD.last_attempt_at THEN
     RAISE EXCEPTION 'DEAD_LETTER is terminal except the explicit audited Admin recovery';
   END IF;
   RETURN NEW;
 END IF;
 IF OLD.status='SENT' THEN RAISE EXCEPTION 'SENT delivery is terminal'; END IF;
 IF v_recovery THEN RAISE EXCEPTION 'Recovery applies to DEAD_LETTER only'; END IF;
 -- OLD is PENDING or FAILED: every change is exactly one recorded attempt.
 IF NEW.status NOT IN ('SENT','FAILED','DEAD_LETTER') OR NEW.attempt<>OLD.attempt+1
    OR NEW.last_attempt_at IS NULL OR (OLD.last_attempt_at IS NOT NULL AND NEW.last_attempt_at<OLD.last_attempt_at) THEN
   RAISE EXCEPTION 'Delivery attempt must move PENDING/FAILED to SENT/FAILED/DEAD_LETTER with attempt+1';
 END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_125_delivery_guard ON notification.notification_delivery;
CREATE TRIGGER tr_125_delivery_guard BEFORE INSERT OR UPDATE OR DELETE ON notification.notification_delivery FOR EACH ROW EXECUTE FUNCTION notification.guard_delivery();
DROP TRIGGER IF EXISTS tr_125_delivery_no_truncate ON notification.notification_delivery;
CREATE TRIGGER tr_125_delivery_no_truncate BEFORE TRUNCATE ON notification.notification_delivery FOR EACH STATEMENT EXECUTE FUNCTION technical.reject_truncate();

-- Worker entry point: record one provider attempt.
CREATE OR REPLACE FUNCTION notification.record_delivery_attempt(p_delivery uuid,p_outcome text,p_provider_message_id text,p_error_code text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE d notification.notification_delivery%ROWTYPE; tok uuid;
BEGIN
 SELECT * INTO d FROM notification.notification_delivery WHERE id=p_delivery FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Unknown delivery'; END IF;
 IF p_outcome NOT IN ('SENT','FAILED','DEAD_LETTER') THEN RAISE EXCEPTION 'Invalid delivery outcome'; END IF;
 tok:=technical.enter_write('notification.notification_delivery',d.id::text);
 UPDATE notification.notification_delivery
    SET status=p_outcome,attempt=d.attempt+1,last_attempt_at=clock_timestamp(),
        provider_message_id=CASE WHEN p_outcome='SENT' THEN p_provider_message_id END,
        error_code=CASE WHEN p_outcome='SENT' THEN NULL ELSE p_error_code END
  WHERE id=d.id;
 PERFORM technical.leave_write(tok);
END;
$function$;

-- Explicit audited Admin recovery of a DEAD_LETTER delivery.
CREATE OR REPLACE FUNCTION notification.recover_dead_letter(p_delivery uuid,p_reason text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE ctx record; d notification.notification_delivery%ROWTYPE; t1 uuid; t2 uuid;
BEGIN
 SELECT * INTO STRICT ctx FROM admin.command_context();
 IF NULLIF(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'Recovery reason is required'; END IF;
 SELECT * INTO d FROM notification.notification_delivery WHERE id=p_delivery FOR UPDATE;
 IF NOT FOUND OR d.status<>'DEAD_LETTER' THEN RAISE EXCEPTION 'Only a DEAD_LETTER delivery can be recovered'; END IF;
 INSERT INTO audit.audit_event(id,occurred_at,actor_type,actor_id,action,subject_type,subject_id,reason,correlation_id,payload,previous_state,new_state)
 VALUES(gen_random_uuid(),ctx.command_at,'ADMIN',ctx.admin_id,'NOTIFICATION_DELIVERY_RECOVERED','NOTIFICATION_DELIVERY',d.id,p_reason,ctx.correlation_id,
   jsonb_build_object('notificationId',d.notification_id,'channel',d.channel,'attempt',d.attempt),'DEAD_LETTER','PENDING');
 t1:=technical.enter_write('notification.notification_delivery',d.id::text);
 t2:=technical.enter_write('notification.notification_delivery.recovery',d.id::text);
 UPDATE notification.notification_delivery SET status='PENDING',provider_message_id=NULL,error_code=NULL WHERE id=d.id;
 PERFORM technical.leave_write(t2); PERFORM technical.leave_write(t1);
END;
$function$;

-- NTF-06: device token lifecycle.
CREATE OR REPLACE FUNCTION notification.guard_device_token()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Device tokens are revoked, not deleted'; END IF;
 IF TG_OP='INSERT' THEN
   IF NEW.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'A new device token cannot be pre-revoked'; END IF;
   IF NEW.created_at>clock_timestamp() THEN RAISE EXCEPTION 'Device token created_at cannot be in the future'; END IF;
   RETURN NEW;
 END IF;
 IF NEW.id<>OLD.id OR NEW.user_id<>OLD.user_id OR NEW.token<>OLD.token OR NEW.platform<>OLD.platform OR NEW.created_at<>OLD.created_at THEN
   RAISE EXCEPTION 'Device token identity (user, token, platform) is immutable; register a new row';
 END IF;
 IF OLD.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'Revoked device token is terminal'; END IF;
 IF NEW.last_seen_at<OLD.last_seen_at THEN RAISE EXCEPTION 'last_seen_at cannot move backwards'; END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_125_device_token_guard ON notification.device_token;
CREATE TRIGGER tr_125_device_token_guard BEFORE INSERT OR UPDATE OR DELETE ON notification.device_token FOR EACH ROW EXECUTE FUNCTION notification.guard_device_token();

-- ===========================================================================
-- CFG-01..05: registry-validated, deterministic, future-only configuration with one producer.
-- ===========================================================================
CREATE OR REPLACE FUNCTION config.guard_registry()
RETURNS trigger LANGUAGE plpgsql AS $function$
BEGIN
 RAISE EXCEPTION 'config.configuration_key is append-only';
END;
$function$;
DROP TRIGGER IF EXISTS tr_125_registry_append_only ON config.configuration_key;
CREATE TRIGGER tr_125_registry_append_only BEFORE UPDATE OR DELETE ON config.configuration_key FOR EACH ROW EXECUTE FUNCTION config.guard_registry();
DROP TRIGGER IF EXISTS tr_125_registry_no_truncate ON config.configuration_key;
CREATE TRIGGER tr_125_registry_no_truncate BEFORE TRUNCATE ON config.configuration_key FOR EACH STATEMENT EXECUTE FUNCTION technical.reject_truncate();

-- Registry rows restate documented values/ranges only (Loyalty keys as already implemented in v1.1.23).
INSERT INTO config.configuration_key(key,value_type,min_value,max_value,units,allowed_values,owner_module,source_reference)
VALUES
 ('loyalty.attended_points','INTEGER',0,2147483647,'points',NULL,'loyalty','Product v5.0 s45 / PRD FR-PTS; launch value 200 (v1.1.23 seed)'),
 ('loyalty.referral_points','INTEGER',0,2147483647,'points',NULL,'loyalty','Product v5.0 s46 / PRD FR-PTS; launch value 1000 (v1.1.23 seed)'),
 ('loyalty.wallet_refunds_enabled','BOOLEAN',NULL,NULL,NULL,NULL,'loyalty','Product v5.0 s47 Wallet launch exclusion; launch value false (v1.1.23 seed)')
ON CONFLICT(key) DO NOTHING;

CREATE OR REPLACE FUNCTION config.validate_value(p_key text,p_value jsonb)
RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE k config.configuration_key%ROWTYPE; n numeric;
BEGIN
 SELECT * INTO k FROM config.configuration_key WHERE key=p_key;
 IF NOT FOUND THEN RAISE EXCEPTION 'Configuration key % is not registered',p_key; END IF;
 IF p_value IS NULL THEN RAISE EXCEPTION 'Configuration value is required for %',p_key; END IF;
 IF k.value_type IN ('INTEGER','NUMERIC') THEN
   IF jsonb_typeof(p_value)<>'number' THEN RAISE EXCEPTION 'Configuration % expects a number',p_key; END IF;
   n:=p_value::text::numeric;
   IF k.value_type='INTEGER' AND n<>trunc(n) THEN RAISE EXCEPTION 'Configuration % expects an integer',p_key; END IF;
   IF (k.min_value IS NOT NULL AND n<k.min_value) OR (k.max_value IS NOT NULL AND n>k.max_value) THEN
     RAISE EXCEPTION 'Configuration % value % outside [%, %] %',p_key,n,k.min_value,k.max_value,COALESCE(k.units,'');
   END IF;
 ELSIF k.value_type='BOOLEAN' AND jsonb_typeof(p_value)<>'boolean' THEN RAISE EXCEPTION 'Configuration % expects a boolean',p_key;
 ELSIF k.value_type='TEXT' AND jsonb_typeof(p_value)<>'string' THEN RAISE EXCEPTION 'Configuration % expects text',p_key;
 END IF;
 IF k.allowed_values IS NOT NULL AND NOT (k.allowed_values @> jsonb_build_array(p_value)) THEN
   RAISE EXCEPTION 'Configuration % value is not an allowed value',p_key;
 END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION config.is_loyalty_key(p_key text)
RETURNS boolean LANGUAGE sql IMMUTABLE AS $function$
 SELECT p_key IN ('loyalty.attended_points','loyalty.referral_points','loyalty.wallet_refunds_enabled');
$function$;

CREATE OR REPLACE FUNCTION config.guard_version()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_last timestamptz;
BEGIN
 PERFORM config.validate_value(NEW.key,NEW.new_value);
 IF NOT config.is_loyalty_key(NEW.key) THEN PERFORM technical.require_write('config.configuration_version',NEW.id::text); END IF;
 IF NEW.changed_at>clock_timestamp() THEN RAISE EXCEPTION 'Configuration changed_at cannot be in the future'; END IF;
 SELECT max(effective_from) INTO v_last FROM config.configuration_version WHERE key=NEW.key;
 IF NEW.effective_from='-infinity'::timestamptz THEN
   IF v_last IS NOT NULL THEN RAISE EXCEPTION 'Only the first version of % may be the technical bootstrap',NEW.key; END IF;
 ELSIF v_last IS NOT NULL AND NEW.effective_from<=v_last THEN
   RAISE EXCEPTION 'Configuration history is future-only: % must follow %',NEW.effective_from,v_last;
 END IF;
 IF NEW.admin_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM iam.admin_account a WHERE a.id=NEW.admin_id AND a.is_active) THEN
   RAISE EXCEPTION 'Configuration change requires an active Admin';
 END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_125_config_version_guard ON config.configuration_version;
CREATE TRIGGER tr_125_config_version_guard BEFORE INSERT ON config.configuration_version FOR EACH ROW EXECUTE FUNCTION config.guard_version();

CREATE OR REPLACE FUNCTION config.guard_current()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Current configuration values cannot be deleted'; END IF;
 IF TG_OP='UPDATE' AND NEW.key<>OLD.key THEN RAISE EXCEPTION 'Configuration key is immutable'; END IF;
 PERFORM config.validate_value(NEW.key,NEW.value);
 IF NOT config.is_loyalty_key(NEW.key) THEN PERFORM technical.require_write('config.system_configuration',NEW.key); END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_125_config_current_guard ON config.system_configuration;
CREATE TRIGGER tr_125_config_current_guard BEFORE INSERT OR UPDATE OR DELETE ON config.system_configuration FOR EACH ROW EXECUTE FUNCTION config.guard_current();

-- CFG-02: current value == latest version, checked at COMMIT for every touched key.
CREATE OR REPLACE FUNCTION config.assert_key(p_key text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v config.configuration_version%ROWTYPE; c config.system_configuration%ROWTYPE;
BEGIN
 SELECT * INTO v FROM config.configuration_version x WHERE x.key=p_key ORDER BY x.version_position DESC LIMIT 1;
 SELECT * INTO c FROM config.system_configuration x WHERE x.key=p_key;
 IF v.id IS NULL AND c.key IS NULL THEN RETURN; END IF;
 IF v.id IS NULL THEN RAISE EXCEPTION 'Current configuration % has no version history',p_key; END IF;
 IF c.key IS NULL OR c.value IS DISTINCT FROM v.new_value THEN
   RAISE EXCEPTION 'Current configuration % differs from its latest version',p_key;
 END IF;
 IF EXISTS(SELECT 1 FROM config.configuration_version a JOIN config.configuration_version b ON b.key=a.key
   AND b.version_position>a.version_position AND b.effective_from<=a.effective_from WHERE a.key=p_key) THEN
   RAISE EXCEPTION 'Configuration % history order and effective order diverge',p_key;
 END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION config.assert_key_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 PERFORM config.assert_key(NEW.key);
 RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_125_config_version_final ON config.configuration_version;
CREATE CONSTRAINT TRIGGER tr_125_config_version_final AFTER INSERT ON config.configuration_version DEFERRABLE INITIALLY DEFERRED
 FOR EACH ROW EXECUTE FUNCTION config.assert_key_trigger();
DROP TRIGGER IF EXISTS tr_125_config_current_final ON config.system_configuration;
CREATE CONSTRAINT TRIGGER tr_125_config_current_final AFTER INSERT OR UPDATE ON config.system_configuration DEFERRABLE INITIALLY DEFERRED
 FOR EACH ROW EXECUTE FUNCTION config.assert_key_trigger();

-- The general controlled producer (Loyalty keys keep loyalty.configure, which now fills the new metadata).
CREATE OR REPLACE FUNCTION config.change_configuration(p_key text,p_value jsonb,p_reason text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE ctx record; k config.configuration_key%ROWTYPE; oldv jsonb; vid uuid:=gen_random_uuid(); tok uuid;
BEGIN
 SELECT * INTO STRICT ctx FROM admin.command_context();
 IF NULLIF(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'Configuration reason is required'; END IF;
 SELECT * INTO k FROM config.configuration_key WHERE key=p_key;
 IF NOT FOUND THEN RAISE EXCEPTION 'Configuration key % is not registered',p_key; END IF;
 IF k.owner_module='loyalty' THEN RAISE EXCEPTION 'Loyalty configuration is changed only by loyalty.configure'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('e7gz.config:'||p_key,0));
 PERFORM config.validate_value(p_key,p_value);
 SELECT value INTO oldv FROM config.system_configuration WHERE key=p_key FOR UPDATE;
 IF oldv IS NOT DISTINCT FROM p_value THEN RAISE EXCEPTION 'Configuration % already has this value',p_key; END IF;
 tok:=technical.enter_write('config.configuration_version',vid::text);
 INSERT INTO config.configuration_version(id,key,old_value,new_value,effective_from,admin_id,reason,changed_at,correlation_id)
 VALUES(vid,p_key,oldv,p_value,ctx.command_at,ctx.admin_id,p_reason,ctx.command_at,ctx.correlation_id);
 PERFORM technical.leave_write(tok);
 tok:=technical.enter_write('config.system_configuration',p_key);
 INSERT INTO config.system_configuration(key,value,updated_at) VALUES(p_key,p_value,ctx.command_at)
 ON CONFLICT(key) DO UPDATE SET value=EXCLUDED.value,updated_at=EXCLUDED.updated_at;
 PERFORM technical.leave_write(tok);
 INSERT INTO audit.audit_event(id,occurred_at,actor_type,actor_id,action,subject_type,subject_id,reason,correlation_id,payload)
 VALUES(gen_random_uuid(),ctx.command_at,'ADMIN',ctx.admin_id,'CONFIGURATION_CHANGED','CONFIGURATION',vid,p_reason,ctx.correlation_id,
   jsonb_build_object('key',p_key,'oldValue',oldv,'newValue',p_value,'effectiveFrom',ctx.command_at));
 INSERT INTO technical.outbox_event(event_type,aggregate_type,aggregate_id,payload,correlation_id,state,attempt,next_attempt_at)
 VALUES('ConfigurationChanged','CONFIGURATION',vid,jsonb_build_object('key',p_key,'versionId',vid,'effectiveFrom',ctx.command_at),
   ctx.correlation_id,'PENDING',0,ctx.command_at);
 RETURN vid;
END;
$function$;

-- v1.1.23 loyalty.configure, unchanged except the CFG-05 metadata.
CREATE OR REPLACE FUNCTION loyalty.configure(p_key text,p_value jsonb,p_admin uuid,p_request uuid,p_reason text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE now_at timestamptz; existing config.configuration_version%ROWTYPE; oldv jsonb; tok uuid; aid uuid:=gen_random_uuid();
BEGIN
 IF p_key IS NULL OR p_key NOT IN ('loyalty.attended_points','loyalty.referral_points','loyalty.wallet_refunds_enabled')
    OR p_request IS NULL OR NULLIF(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'Invalid configuration command'; END IF;
 PERFORM a.id FROM iam.admin_account a WHERE a.id=p_admin AND a.is_active FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Active Admin required'; END IF;
 IF p_key='loyalty.wallet_refunds_enabled' THEN
   IF jsonb_typeof(p_value) IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Expected Boolean feature flag'; END IF;
 ELSE
   IF jsonb_typeof(p_value) IS DISTINCT FROM 'number' OR p_value::text !~ '^[0-9]+$' OR p_value::text::numeric>2147483647 THEN RAISE EXCEPTION 'Expected nonnegative bounded integer'; END IF;
 END IF;
 IF to_regclass('pg_temp.e7gz_tournament_command_context') IS NOT NULL THEN RAISE EXCEPTION 'Configuration is a separate Admin transaction, not a mid-business-command change'; END IF;
 PERFORM pg_advisory_xact_lock(1123,1);
 SELECT * INTO existing FROM config.configuration_version WHERE id=p_request;
 IF FOUND THEN
  IF existing.key IS DISTINCT FROM p_key OR existing.new_value IS DISTINCT FROM p_value OR existing.admin_id IS DISTINCT FROM p_admin OR existing.reason IS DISTINCT FROM p_reason THEN RAISE EXCEPTION 'Config request ID reused'; END IF;
  RETURN existing.id;
 END IF;
 now_at:=clock_timestamp();
 SELECT value INTO oldv FROM config.system_configuration WHERE key=p_key;
 tok:=loyalty.enter_write('config.configuration_version',p_request::text);
 -- v1.1.25 CFG-05: explicit server change time and correlation (= request id, as used by its audit).
 INSERT INTO config.configuration_version(id,key,old_value,new_value,effective_from,admin_id,reason,changed_at,correlation_id)
 VALUES(p_request,p_key,oldv,p_value,now_at,p_admin,p_reason,now_at,p_request);
 PERFORM loyalty.leave_write(tok);
 tok:=loyalty.enter_write('config.system_configuration',p_key);
 INSERT INTO config.system_configuration(key,value,updated_at) VALUES(p_key,p_value,now_at)
 ON CONFLICT(key) DO UPDATE SET value=EXCLUDED.value,updated_at=EXCLUDED.updated_at;
 PERFORM loyalty.leave_write(tok);
 tok:=loyalty.enter_write('audit.audit_event',aid::text);
 INSERT INTO audit.audit_event(id,occurred_at,actor_type,actor_id,action,subject_type,subject_id,reason,correlation_id,payload)
 VALUES(aid,now_at,'ADMIN',p_admin,'LOYALTY_CONFIGURATION_CHANGED','CONFIGURATION',p_request,p_reason,p_request,
   jsonb_build_object('key',p_key,'oldValue',oldv,'newValue',p_value));
 PERFORM loyalty.leave_write(tok);
 RETURN p_request;
END;
$function$;

-- ===========================================================================
-- TEC-01: persistent idempotency.
-- ===========================================================================
CREATE OR REPLACE FUNCTION technical.idempotency_row_key(p_type text,p_id uuid,p_endpoint text,p_key text)
RETURNS text LANGUAGE sql IMMUTABLE AS $function$
 SELECT p_type||'|'||p_id::text||'|'||md5(p_endpoint)||'|'||md5(p_key);
$function$;

CREATE OR REPLACE FUNCTION technical.guard_idempotency()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE r technical.idempotency_record;
BEGIN
 IF TG_OP='DELETE' THEN r:=OLD; ELSE r:=NEW; END IF;
 PERFORM technical.require_write('technical.idempotency_record',technical.idempotency_row_key(r.principal_type,r.principal_id,r.endpoint,r.idempotency_key));
 IF TG_OP='DELETE' THEN
   IF OLD.expires_at>clock_timestamp() THEN RAISE EXCEPTION 'Only an expired idempotency record can be removed'; END IF;
   RETURN OLD;
 END IF;
 IF TG_OP='INSERT' THEN
   IF NEW.state<>'IN_PROGRESS' THEN RAISE EXCEPTION 'Idempotency record starts IN_PROGRESS'; END IF;
   RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['state','response_status','response_body','result_aggregate_type','result_aggregate_id','completed_at'])
    IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','response_status','response_body','result_aggregate_type','result_aggregate_id','completed_at'])
    OR OLD.state<>'IN_PROGRESS' OR NEW.state<>'COMPLETED' THEN
   RAISE EXCEPTION 'Idempotency identity/fingerprint are immutable; only IN_PROGRESS -> COMPLETED once';
 END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_125_idempotency_guard ON technical.idempotency_record;
CREATE TRIGGER tr_125_idempotency_guard BEFORE INSERT OR UPDATE OR DELETE ON technical.idempotency_record FOR EACH ROW EXECUTE FUNCTION technical.guard_idempotency();
DROP TRIGGER IF EXISTS tr_125_idempotency_no_truncate ON technical.idempotency_record;
CREATE TRIGGER tr_125_idempotency_no_truncate BEFORE TRUNCATE ON technical.idempotency_record FOR EACH STATEMENT EXECUTE FUNCTION technical.reject_truncate();

-- Call at the start of the business transaction. NEW = execute the command; REPLAY = return the stored result.
CREATE OR REPLACE FUNCTION technical.idempotency_begin(p_principal_type text,p_principal_id uuid,p_endpoint text,p_key text,
  p_fingerprint text,p_expires_at timestamptz,p_correlation uuid)
RETURNS TABLE(outcome text,response_status smallint,response_body jsonb,result_aggregate_type text,result_aggregate_id uuid)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_now timestamptz:=clock_timestamp(); ex technical.idempotency_record%ROWTYPE; tok uuid; n integer; rk text;
BEGIN
 IF p_principal_type IN ('ADMIN','CUSTOMER','VENUE') THEN PERFORM technical.assert_principal(p_principal_type,p_principal_id,true);
 ELSIF p_principal_type<>'SYSTEM' OR p_principal_id IS NULL THEN RAISE EXCEPTION 'Invalid idempotency principal';
 END IF;
 IF p_expires_at IS NULL OR p_expires_at<=v_now OR p_correlation IS NULL THEN RAISE EXCEPTION 'Idempotency requires future expiry and correlation'; END IF;
 rk:=technical.idempotency_row_key(p_principal_type,p_principal_id,p_endpoint,p_key);
 tok:=technical.enter_write('technical.idempotency_record',rk);
 INSERT INTO technical.idempotency_record(principal_type,principal_id,endpoint,idempotency_key,request_fingerprint,state,correlation_id,created_at,expires_at)
 VALUES(p_principal_type,p_principal_id,p_endpoint,p_key,p_fingerprint,'IN_PROGRESS',p_correlation,v_now,p_expires_at)
 ON CONFLICT ON CONSTRAINT idempotency_record_pk DO NOTHING;
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n=1 THEN PERFORM technical.leave_write(tok); RETURN QUERY SELECT 'NEW'::text,NULL::smallint,NULL::jsonb,NULL::text,NULL::uuid; RETURN; END IF;
 SELECT * INTO STRICT ex FROM technical.idempotency_record x WHERE x.principal_type=p_principal_type AND x.principal_id=p_principal_id
   AND x.endpoint=p_endpoint AND x.idempotency_key=p_key FOR UPDATE;
 IF ex.expires_at<=v_now THEN
   DELETE FROM technical.idempotency_record x WHERE x.principal_type=p_principal_type AND x.principal_id=p_principal_id
     AND x.endpoint=p_endpoint AND x.idempotency_key=p_key;
   INSERT INTO technical.idempotency_record(principal_type,principal_id,endpoint,idempotency_key,request_fingerprint,state,correlation_id,created_at,expires_at)
   VALUES(p_principal_type,p_principal_id,p_endpoint,p_key,p_fingerprint,'IN_PROGRESS',p_correlation,v_now,p_expires_at);
   PERFORM technical.leave_write(tok);
   RETURN QUERY SELECT 'NEW'::text,NULL::smallint,NULL::jsonb,NULL::text,NULL::uuid; RETURN;
 END IF;
 PERFORM technical.leave_write(tok);
 IF ex.request_fingerprint<>p_fingerprint THEN RAISE EXCEPTION 'Idempotency key reused with a different request'; END IF;
 IF ex.state='COMPLETED' THEN
   RETURN QUERY SELECT 'REPLAY'::text,ex.response_status,ex.response_body,ex.result_aggregate_type,ex.result_aggregate_id; RETURN;
 END IF;
 RAISE EXCEPTION 'Idempotent request is already in progress in this transaction';
END;
$function$;

CREATE OR REPLACE FUNCTION technical.idempotency_complete(p_principal_type text,p_principal_id uuid,p_endpoint text,p_key text,
  p_response_status smallint,p_response_body jsonb,p_aggregate_type text,p_aggregate_id uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE tok uuid; k text; n integer;
BEGIN
 k:=technical.forbidden_payload_key(p_response_body);
 IF k IS NOT NULL THEN RAISE EXCEPTION 'Idempotency response summary contains a forbidden secret field: %',k; END IF;
 tok:=technical.enter_write('technical.idempotency_record',technical.idempotency_row_key(p_principal_type,p_principal_id,p_endpoint,p_key));
 UPDATE technical.idempotency_record x SET state='COMPLETED',response_status=p_response_status,response_body=p_response_body,
   result_aggregate_type=p_aggregate_type,result_aggregate_id=p_aggregate_id,completed_at=clock_timestamp()
  WHERE x.principal_type=p_principal_type AND x.principal_id=p_principal_id AND x.endpoint=p_endpoint AND x.idempotency_key=p_key AND x.state='IN_PROGRESS';
 GET DIAGNOSTICS n=ROW_COUNT;
 PERFORM technical.leave_write(tok);
 IF n<>1 THEN RAISE EXCEPTION 'No IN_PROGRESS idempotency record to complete'; END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION technical.idempotency_purge_expired(p_limit integer DEFAULT 1000)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE r record; tok uuid; n integer:=0;
BEGIN
 FOR r IN SELECT * FROM technical.idempotency_record x WHERE x.expires_at<=clock_timestamp() ORDER BY x.expires_at LIMIT p_limit FOR UPDATE SKIP LOCKED LOOP
   tok:=technical.enter_write('technical.idempotency_record',technical.idempotency_row_key(r.principal_type,r.principal_id,r.endpoint,r.idempotency_key));
   DELETE FROM technical.idempotency_record x WHERE x.principal_type=r.principal_type AND x.principal_id=r.principal_id
     AND x.endpoint=r.endpoint AND x.idempotency_key=r.idempotency_key;
   PERFORM technical.leave_write(tok); n:=n+1;
 END LOOP;
 RETURN n;
END;
$function$;

-- ===========================================================================
-- Found while testing TEC-02: the v1.1.23 loyalty.guard_outbox_envelope() returned NEW (= NULL) for a
-- DELETE of a non-Loyalty Outbox row. A BEFORE trigger returning NULL silently SKIPS the row operation and
-- every later trigger, so "DELETE FROM technical.outbox_event" reported success without failing closed.
-- Same rules; DELETE now returns OLD so the generic guard below rejects it explicitly.
-- ===========================================================================
CREATE OR REPLACE FUNCTION loyalty.guard_outbox_envelope()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.aggregate_type='LOYALTY' THEN PERFORM loyalty.require_write('technical.outbox_event',NEW.aggregate_id::text); END IF;
  RETURN NEW;
 END IF;
 IF OLD.aggregate_type='LOYALTY' OR (TG_OP='UPDATE' AND NEW.aggregate_type='LOYALTY') THEN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Referenced Loyalty Outbox history is retained'; END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.event_type IS DISTINCT FROM OLD.event_type OR NEW.aggregate_type IS DISTINCT FROM OLD.aggregate_type
    OR NEW.aggregate_id IS DISTINCT FROM OLD.aggregate_id OR NEW.payload IS DISTINCT FROM OLD.payload OR NEW.correlation_id IS DISTINCT FROM OLD.correlation_id THEN
   RAISE EXCEPTION 'Loyalty Outbox envelope is immutable; delivery fields only'; END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;
$function$;

-- ===========================================================================
-- TEC-02 / TEC-03: generic Outbox envelope + dispatch lifecycle.
-- ===========================================================================
CREATE OR REPLACE FUNCTION technical.guard_outbox()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Outbox events are retained; DELETE is rejected'; END IF;
 IF TG_OP='INSERT' THEN
   NEW.next_attempt_at:=COALESCE(NEW.next_attempt_at,clock_timestamp());
   IF NEW.state<>'PENDING' OR NEW.attempt<>0 OR NEW.dispatched_at IS NOT NULL OR NEW.last_error IS NOT NULL THEN
     RAISE EXCEPTION 'A new Outbox event starts PENDING, attempt 0, undispatched';
   END IF;
   IF jsonb_typeof(NEW.payload)<>'object' THEN RAISE EXCEPTION 'Outbox payload must be a JSON object'; END IF;
   IF NEW.created_at>clock_timestamp() THEN RAISE EXCEPTION 'Outbox created_at cannot be in the future'; END IF;
   RETURN NEW;
 END IF;
 PERFORM technical.require_write('technical.outbox_event',NEW.id::text);
 IF NEW.id<>OLD.id OR NEW.event_type<>OLD.event_type OR NEW.aggregate_type<>OLD.aggregate_type OR NEW.aggregate_id<>OLD.aggregate_id
    OR NEW.payload<>OLD.payload OR NEW.correlation_id<>OLD.correlation_id OR NEW.created_at<>OLD.created_at THEN
   RAISE EXCEPTION 'Outbox envelope is immutable';
 END IF;
 IF OLD.state<>'PENDING' THEN RAISE EXCEPTION 'Outbox % is terminal',OLD.state; END IF;
 IF NEW.attempt<>OLD.attempt+1 THEN RAISE EXCEPTION 'Each Outbox dispatch transition records exactly one attempt'; END IF;
 IF NEW.state='PENDING' AND (NEW.last_error IS NULL OR NEW.next_attempt_at<=OLD.next_attempt_at) THEN
   RAISE EXCEPTION 'Outbox retry requires an error and a later next_attempt_at';
 END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_125_outbox_guard ON technical.outbox_event;
CREATE TRIGGER tr_125_outbox_guard BEFORE INSERT OR UPDATE OR DELETE ON technical.outbox_event FOR EACH ROW EXECUTE FUNCTION technical.guard_outbox();
DROP TRIGGER IF EXISTS tr_125_outbox_no_truncate ON technical.outbox_event;
CREATE TRIGGER tr_125_outbox_no_truncate BEFORE TRUNCATE ON technical.outbox_event FOR EACH STATEMENT EXECUTE FUNCTION technical.reject_truncate();

CREATE OR REPLACE FUNCTION technical.outbox_transition(p_id bigint,p_state text,p_next timestamptz,p_error text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE o technical.outbox_event%ROWTYPE; tok uuid;
BEGIN
 SELECT * INTO o FROM technical.outbox_event WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Unknown Outbox event'; END IF;
 tok:=technical.enter_write('technical.outbox_event',o.id::text);
 UPDATE technical.outbox_event SET state=p_state,attempt=o.attempt+1,
   dispatched_at=CASE WHEN p_state='DISPATCHED' THEN clock_timestamp() END,
   next_attempt_at=CASE WHEN p_state='PENDING' THEN p_next ELSE o.next_attempt_at END,
   last_error=CASE WHEN p_state='DISPATCHED' THEN o.last_error ELSE p_error END
  WHERE id=o.id;
 PERFORM technical.leave_write(tok);
END;
$function$;
CREATE OR REPLACE FUNCTION technical.outbox_mark_dispatched(p_id bigint) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
 SELECT technical.outbox_transition(p_id,'DISPATCHED',NULL,NULL);
$function$;
CREATE OR REPLACE FUNCTION technical.outbox_mark_retry(p_id bigint,p_next_attempt_at timestamptz,p_error text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
 SELECT technical.outbox_transition(p_id,'PENDING',p_next_attempt_at,p_error);
$function$;
CREATE OR REPLACE FUNCTION technical.outbox_mark_dead_letter(p_id bigint,p_error text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
 SELECT technical.outbox_transition(p_id,'DEAD_LETTER',NULL,p_error);
$function$;

-- ===========================================================================
-- TEC-04: generic scheduler lifecycle for every job type (Tournament guards still apply on top).
-- ===========================================================================
CREATE OR REPLACE FUNCTION technical.guard_scheduled_job()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE ok boolean;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Scheduled jobs are SUPERSEDED, not deleted'; END IF;
 IF TG_OP='INSERT' THEN
   IF NEW.status NOT IN ('PENDING','PAUSED') OR NEW.attempt<>0 OR NEW.completed_at IS NOT NULL OR NEW.last_error IS NOT NULL THEN
     RAISE EXCEPTION 'A new job starts PENDING or PAUSED with no attempt';
   END IF;
   IF NEW.created_at>clock_timestamp() THEN RAISE EXCEPTION 'Job created_at cannot be in the future'; END IF;
   RETURN NEW;
 END IF;
 IF NEW.id<>OLD.id OR NEW.type<>OLD.type OR NEW.subject_type<>OLD.subject_type OR NEW.subject_id<>OLD.subject_id
    OR NEW.idempotency_key<>OLD.idempotency_key OR NEW.created_at<>OLD.created_at THEN
   RAISE EXCEPTION 'Job type/subject/idempotency identity is immutable';
 END IF;
 IF OLD.status IN ('DONE','SUPERSEDED') THEN RAISE EXCEPTION 'Job is % and can never fire again',OLD.status; END IF;
 ok:=(OLD.status='PENDING' AND NEW.status IN ('LEASED','PAUSED','DONE','SUPERSEDED'))
   OR (OLD.status='PAUSED' AND NEW.status IN ('PENDING','SUPERSEDED'))
   OR (OLD.status='LEASED' AND NEW.status IN ('DONE','FAILED','PENDING','SUPERSEDED'))
   OR (OLD.status='LEASED' AND NEW.status='LEASED' AND OLD.leased_until<=clock_timestamp())
   OR (OLD.status='FAILED' AND NEW.status IN ('PENDING','SUPERSEDED'));
 IF NOT ok THEN RAISE EXCEPTION 'Invalid job transition % -> %',OLD.status,NEW.status; END IF;
 IF NEW.status='LEASED' THEN
   IF NEW.attempt<>OLD.attempt+1 THEN RAISE EXCEPTION 'A lease records exactly one attempt'; END IF;
 ELSIF NEW.attempt<>OLD.attempt THEN RAISE EXCEPTION 'attempt changes only when a lease is taken';
 END IF;
 IF NEW.due_at<>OLD.due_at AND NOT (NEW.status='PENDING' AND OLD.status IN ('PAUSED','FAILED')) THEN
   RAISE EXCEPTION 'due_at changes only through the explicit pause/re-arm path';
 END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_125_scheduled_job_guard ON technical.scheduled_job;
CREATE TRIGGER tr_125_scheduled_job_guard BEFORE INSERT OR UPDATE OR DELETE ON technical.scheduled_job FOR EACH ROW EXECUTE FUNCTION technical.guard_scheduled_job();
DROP TRIGGER IF EXISTS tr_125_scheduled_job_no_truncate ON technical.scheduled_job;
CREATE TRIGGER tr_125_scheduled_job_no_truncate BEFORE TRUNCATE ON technical.scheduled_job FOR EACH STATEMENT EXECUTE FUNCTION technical.reject_truncate();

CREATE OR REPLACE FUNCTION technical.job_lease(p_job uuid,p_worker text,p_lease interval)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE j technical.scheduled_job%ROWTYPE; v_now timestamptz:=clock_timestamp();
BEGIN
 IF NULLIF(btrim(p_worker),'') IS NULL OR p_lease IS NULL OR p_lease<=interval '0' THEN RAISE EXCEPTION 'Worker and positive lease are required'; END IF;
 SELECT * INTO j FROM technical.scheduled_job WHERE id=p_job FOR UPDATE SKIP LOCKED;
 IF NOT FOUND OR j.due_at>v_now OR NOT (j.status='PENDING' OR (j.status='LEASED' AND j.leased_until<=v_now)) THEN RETURN false; END IF;
 UPDATE technical.scheduled_job SET status='LEASED',attempt=j.attempt+1,leased_at=v_now,leased_until=v_now+p_lease,leased_by=p_worker WHERE id=j.id;
 RETURN true;
END;
$function$;
CREATE OR REPLACE FUNCTION technical.job_finish(p_job uuid,p_worker text,p_status text,p_error text DEFAULT NULL)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE j technical.scheduled_job%ROWTYPE;
BEGIN
 SELECT * INTO j FROM technical.scheduled_job WHERE id=p_job FOR UPDATE;
 IF NOT FOUND OR j.status<>'LEASED' OR j.leased_by IS DISTINCT FROM p_worker OR j.leased_until<=clock_timestamp() THEN
   RAISE EXCEPTION 'Only the current lease holder can finish this job';
 END IF;
 IF p_status NOT IN ('DONE','FAILED','PENDING') THEN RAISE EXCEPTION 'Invalid job outcome'; END IF;
 UPDATE technical.scheduled_job SET status=p_status,leased_at=NULL,leased_until=NULL,leased_by=NULL,
   completed_at=CASE WHEN p_status IN ('DONE','FAILED') THEN clock_timestamp() END,
   last_error=CASE WHEN p_status='DONE' THEN j.last_error ELSE p_error END
  WHERE id=j.id;
END;
$function$;
CREATE OR REPLACE FUNCTION technical.job_rearm(p_job uuid,p_due_at timestamptz)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 UPDATE technical.scheduled_job SET status='PENDING',due_at=COALESCE(p_due_at,due_at),completed_at=NULL
  WHERE id=p_job AND status IN ('PAUSED','FAILED');
 IF NOT FOUND THEN RAISE EXCEPTION 'Only a PAUSED or FAILED job can be re-armed'; END IF;
END;
$function$;

-- ===========================================================================
-- Default deny + integrity validation of existing data (upgrade preflight; nothing is rewritten).
-- ===========================================================================
DO $private_helpers_125$
DECLARE f record;
BEGIN
 FOR f IN SELECT p.oid::regprocedure sig FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
   WHERE n.nspname IN ('review','notification','admin','config','audit','loyalty')
      OR (n.nspname='technical' AND p.proname IN ('enter_write','leave_write','has_write','require_write','forbidden_payload_key','assert_principal',
          'reject_truncate','idempotency_row_key','guard_idempotency','idempotency_begin','idempotency_complete','idempotency_purge_expired',
          'guard_outbox','outbox_transition','outbox_mark_dispatched','outbox_mark_retry','outbox_mark_dead_letter','guard_scheduled_job',
          'job_lease','job_finish','job_rearm'))
      OR (n.nspname='trust' AND p.proname IN ('assert_owned_context','secure_created_context','begin_admin_command')) LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.sig);
 END LOOP;
END;
$private_helpers_125$;

DO $validate_125$
DECLARE r record; k text;
BEGIN
 FOR r IN SELECT key,new_value v FROM config.configuration_version UNION ALL SELECT key,value FROM config.system_configuration LOOP
   PERFORM config.validate_value(r.key,r.v);
 END LOOP;
 FOR r IN SELECT DISTINCT key FROM (SELECT key FROM config.configuration_version UNION SELECT key FROM config.system_configuration) x LOOP
   PERFORM config.assert_key(r.key);
 END LOOP;
 FOR r IN SELECT id,payload FROM audit.audit_event WHERE payload IS NOT NULL LOOP
   k:=technical.forbidden_payload_key(r.payload);
   IF k IS NOT NULL THEN RAISE EXCEPTION 'v1.1.25 preflight: audit % contains forbidden field %',r.id,k; END IF;
 END LOOP;
 FOR r IN SELECT DISTINCT venue_id FROM (SELECT venue_id FROM review.review UNION SELECT venue_id FROM review.venue_rating_stats) x LOOP
   PERFORM review.assert_venue_rating(r.venue_id);
 END LOOP;
 IF EXISTS(SELECT 1 FROM notification.notification n WHERE NOT EXISTS(SELECT 1 FROM notification.notification_catalogue c WHERE c.code=n.code)) THEN
   RAISE EXCEPTION 'v1.1.25 preflight: notifications with unregistered codes exist';
 END IF;
END;
$validate_125$;


-- v1.1.26: PCR-001..003 alignment. No Product-visible state is added beyond the incorporated PCRs.
-- A) exact Tournament Participant cause domain; B) Customer Account Deletion request; C) Customer Review reporting.

CREATE OR REPLACE FUNCTION tournament.guard_tournament_participant()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $function$
DECLARE
    v_now timestamptz;
    t tournament.tournament%ROWTYPE;
    u iam.user_account%ROWTYPE;
    v_active integer;
    v_occupied integer;
    v_banned boolean;
    v_boundary_restore boolean := false;
BEGIN
    v_now := tournament.require_command_scope(COALESCE(NEW.tournament_id, OLD.tournament_id), NULL, NULL, COALESCE(NEW.user_id, OLD.user_id));
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Tournament Participant history may not be deleted';
    END IF;

    SELECT * INTO t FROM tournament.tournament WHERE id = NEW.tournament_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament does not exist'; END IF;
    SELECT * INTO u FROM iam.user_account WHERE id = NEW.user_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament Participant User does not exist'; END IF;
    SELECT EXISTS (
        SELECT 1 FROM trust.ban_instance b
         WHERE b.user_id = NEW.user_id AND b.status = 'ACTIVE'
           AND b.activated_at <= v_now AND b.ends_at > v_now
    ) INTO v_banned;

    IF TG_OP='UPDATE' AND OLD.status='INELIGIBLE' AND OLD.ineligible_reason='BAN' AND NEW.status='JOINED' THEN
        IF t.status='WAITING_FOR_PLAYERS' AND v_now >= t.checkpoint_at
           AND NOT EXISTS (
               SELECT 1 FROM trust.ban_instance b
                WHERE b.user_id=NEW.user_id AND b.activated_at <= t.checkpoint_at AND b.ends_at > t.checkpoint_at
           ) THEN
            v_boundary_restore := true;
        ELSIF t.status='CONFIRMED' AND v_now >= t.start_at
           AND NOT EXISTS (
               SELECT 1 FROM trust.ban_instance b
                WHERE b.user_id=NEW.user_id AND b.activated_at <= t.start_at AND b.ends_at > t.start_at
           ) THEN
            v_boundary_restore := true;
        END IF;
    END IF;

    -- Once a due boundary is reached, no participant mutation may change its result.
    -- The only exception is catching up a BAN-only restoration that was already effective at that boundary.
    IF t.status='WAITING_FOR_PLAYERS' AND v_now >= t.checkpoint_at AND NOT v_boundary_restore THEN
        RAISE EXCEPTION 'Tournament checkpoint is overdue; resolve the checkpoint before participant mutation';
    END IF;
    IF t.status='CONFIRMED' AND v_now >= t.start_at AND NOT v_boundary_restore THEN
        RAISE EXCEPTION 'Tournament start is due; resolve startAt before participant mutation';
    END IF;

    IF TG_OP = 'INSERT' THEN
        NEW.joined_at := v_now;
        NEW.status_changed_at := NEW.joined_at;
        NEW.status := 'JOINED';
        NEW.left_at := NULL;
        NEW.removed_at := NULL;
        NEW.ineligible_reason := NULL;

        IF NOT u.phone_verified OR u.anonymised_at IS NOT NULL OR v_banned THEN
            RAISE EXCEPTION 'Tournament join requires an Account-Verified, non-banned active User';
        END IF;
        IF t.status = 'PENDING_VENUE_APPROVAL' THEN
            IF t.host_type <> 'PLAYER' OR NOT t.creator_participates OR NEW.user_id IS DISTINCT FROM t.creator_user_id
               OR NOT tournament.created_in_command(t.id) THEN
                RAISE EXCEPTION 'While PENDING_VENUE_APPROVAL only the participating Player Creator may have a Participant row';
            END IF;
        ELSIF t.status NOT IN ('WAITING_FOR_PLAYERS','CONFIRMED') OR v_now >= t.start_at THEN
            RAISE EXCEPTION 'Users may join only WAITING_FOR_PLAYERS/CONFIRMED before startAt';
        END IF;
        v_occupied := tournament.capacity_occupied_count(t.id);
        IF v_occupied >= t.capacity THEN
            RAISE EXCEPTION 'Tournament participant capacity is full, including BAN-only reserved slots';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.tournament_id IS DISTINCT FROM OLD.tournament_id
       OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.joined_at IS DISTINCT FROM OLD.joined_at THEN
        RAISE EXCEPTION 'Tournament Participant identity/join timestamp is immutable';
    END IF;
    IF OLD.left_at IS NOT NULL AND NEW.left_at IS DISTINCT FROM OLD.left_at THEN
        RAISE EXCEPTION 'left_at is immutable once recorded';
    END IF;
    IF OLD.removed_at IS NOT NULL AND NEW.removed_at IS DISTINCT FROM OLD.removed_at THEN
        RAISE EXCEPTION 'removed_at is immutable once recorded';
    END IF;
    IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
        -- v1.1.17 cause precedence: account deletion permanently defeats BAN-only
        -- restoration eligibility. Permit exactly one reason-only reclassification
        -- while retaining the existing INELIGIBLE status and its status timestamp.
        IF OLD.status='INELIGIBLE' AND OLD.ineligible_reason='BAN' AND u.anonymised_at IS NOT NULL
           AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE') THEN
            IF NEW.status_changed_at IS DISTINCT FROM OLD.status_changed_at
               OR NEW.left_at IS DISTINCT FROM OLD.left_at
               OR NEW.removed_at IS DISTINCT FROM OLD.removed_at THEN
                RAISE EXCEPTION 'BAN to ACCOUNT_DELETED cause reclassification may not mutate other participant lifecycle facts';
            END IF;
            NEW.ineligible_reason := 'ACCOUNT_DELETED';
            RETURN NEW;
        END IF;
        IF NEW.status_changed_at IS DISTINCT FROM OLD.status_changed_at
           OR NEW.left_at IS DISTINCT FROM OLD.left_at OR NEW.removed_at IS DISTINCT FROM OLD.removed_at
           OR NEW.ineligible_reason IS DISTINCT FROM OLD.ineligible_reason THEN
            RAISE EXCEPTION 'Participant lifecycle facts change only with a status transition except BAN to ACCOUNT_DELETED cause precedence';
        END IF;
        RETURN NEW;
    END IF;
    IF t.status IN ('COMPLETED','REJECTED','CANCELLED') THEN
        RAISE EXCEPTION 'Participant state cannot change after Tournament terminal state';
    END IF;

    NEW.status_changed_at := v_now;
    IF NEW.status = 'JOINED' THEN
        IF NOT v_boundary_restore AND (v_now >= t.start_at OR NOT (
               t.status IN ('WAITING_FOR_PLAYERS','CONFIRMED')
               OR (t.status='PENDING_VENUE_APPROVAL' AND t.host_type='PLAYER' AND t.creator_participates AND NEW.user_id=t.creator_user_id)
           )) THEN
            RAISE EXCEPTION 'Participant may return/join only before startAt in an eligible Tournament lifecycle state';
        END IF;
        IF NOT u.phone_verified OR u.anonymised_at IS NOT NULL OR v_banned THEN
            RAISE EXCEPTION 'JOINED participant must be Account-Verified, active and not banned';
        END IF;
        NEW.ineligible_reason := NULL;
        v_occupied := tournament.capacity_occupied_count(t.id);
        -- BAN-only restoration consumes its already-reserved capacity slot, so it must
        -- not be rejected merely because all slots are occupied. Other returns still
        -- require a free slot.
        IF NOT (OLD.status='JOINED' OR (OLD.status='INELIGIBLE' AND OLD.ineligible_reason='BAN'))
           AND v_occupied >= t.capacity THEN
            RAISE EXCEPTION 'Tournament participant capacity is full, including BAN-only reserved slots';
        END IF;
    ELSIF NEW.status = 'LEFT' THEN
        IF v_now >= t.start_at THEN
            RAISE EXCEPTION 'Participant may Leave only before startAt';
        END IF;
        IF NEW.left_at IS NULL THEN NEW.left_at := NEW.status_changed_at; END IF;
    ELSIF NEW.status = 'REMOVED' THEN
        IF v_now >= t.start_at THEN
            RAISE EXCEPTION 'Organizer may Remove a Participant only before startAt';
        END IF;
        IF NEW.removed_at IS NULL THEN NEW.removed_at := NEW.status_changed_at; END IF;
    ELSIF NEW.status = 'INELIGIBLE' THEN
        -- ACCOUNT_DELETED has precedence over BAN because a deleted/anonymised
        -- account can never become JOINED again when a Ban later expires/lifts.
        IF u.anonymised_at IS NOT NULL THEN
            NEW.ineligible_reason := 'ACCOUNT_DELETED';
        ELSIF v_banned THEN
            NEW.ineligible_reason := 'BAN';
        ELSE
            RAISE EXCEPTION 'INELIGIBLE is valid only for BAN or ACCOUNT_DELETED';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION iam.guard_account_deletion_request()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Account Deletion Requests are retained; DELETE is rejected'; END IF;
 PERFORM technical.require_write('iam.account_deletion_request',NEW.id::text);
 IF TG_OP='INSERT' THEN
   IF NEW.completed_at IS NOT NULL OR NEW.completed_by_admin_id IS NOT NULL OR NEW.anonymisation_id IS NOT NULL THEN
     RAISE EXCEPTION 'New Account Deletion Request must be unresolved';
   END IF;
   RETURN NEW;
 END IF;
 IF NEW.id<>OLD.id OR NEW.user_id<>OLD.user_id OR NEW.requested_at<>OLD.requested_at OR NEW.correlation_id<>OLD.correlation_id THEN
   RAISE EXCEPTION 'Account Deletion Request identity/source facts are immutable';
 END IF;
 IF OLD.completed_at IS NOT NULL THEN RAISE EXCEPTION 'Completed Account Deletion Request is immutable'; END IF;
 IF NEW.completed_at IS NULL OR NEW.completed_by_admin_id IS NULL OR NEW.anonymisation_id IS NULL THEN
   RAISE EXCEPTION 'Account Deletion Request completion is one atomic close';
 END IF;
 RETURN NEW;
END;
$function$;
CREATE TRIGGER tr_126_account_deletion_request_guard BEFORE INSERT OR UPDATE OR DELETE ON iam.account_deletion_request FOR EACH ROW EXECUTE FUNCTION iam.guard_account_deletion_request();
CREATE TRIGGER tr_126_account_deletion_request_no_truncate BEFORE TRUNCATE ON iam.account_deletion_request FOR EACH STATEMENT EXECUTE FUNCTION technical.reject_truncate();

CREATE OR REPLACE FUNCTION iam.request_account_deletion(p_user uuid,p_correlation uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_now timestamptz; v_id uuid; tok uuid; aid uuid:=gen_random_uuid();
BEGIN
 IF p_user IS NULL OR p_correlation IS NULL THEN RAISE EXCEPTION 'User and correlation are required'; END IF;
 IF to_regclass('pg_temp.e7gz_tournament_command_context') IS NULL THEN
   PERFORM tournament.begin_command(ARRAY[p_user],ARRAY[]::uuid[],ARRAY[]::uuid[],ARRAY[]::uuid[]);
 END IF;
 v_now:=tournament.command_now();
 PERFORM u.id FROM iam.user_account u WHERE u.id=p_user AND u.anonymised_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Active Customer account required'; END IF;
 SELECT r.id INTO v_id FROM iam.account_deletion_request r WHERE r.user_id=p_user AND r.completed_at IS NULL FOR UPDATE;
 IF FOUND THEN RETURN v_id; END IF;
 v_id:=gen_random_uuid(); tok:=technical.enter_write('iam.account_deletion_request',v_id::text);
 INSERT INTO iam.account_deletion_request(id,user_id,requested_at,correlation_id) VALUES(v_id,p_user,v_now,p_correlation);
 PERFORM technical.leave_write(tok);
 INSERT INTO audit.audit_event(id,occurred_at,actor_type,actor_id,action,subject_type,subject_id,reason,correlation_id,payload,context_user_id)
 VALUES(aid,v_now,'CUSTOMER',p_user,'ACCOUNT_DELETION_REQUESTED','USER',p_user,NULL,p_correlation,jsonb_build_object('deletionRequestId',v_id),p_user);
 RETURN v_id;
END;
$function$;

-- Completes only after the existing O19 anonymisation process has created its authoritative account_anonymisation row.
CREATE OR REPLACE FUNCTION iam.complete_account_deletion_request(p_request uuid,p_anonymisation uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE ctx record; r iam.account_deletion_request%ROWTYPE; a iam.account_anonymisation%ROWTYPE; tok uuid; aid uuid:=gen_random_uuid();
BEGIN
 SELECT * INTO STRICT ctx FROM admin.command_context();
 SELECT * INTO r FROM iam.account_deletion_request WHERE id=p_request FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Unknown Account Deletion Request'; END IF;
 IF r.completed_at IS NOT NULL THEN
   IF r.anonymisation_id=p_anonymisation AND r.completed_by_admin_id=ctx.admin_id THEN RETURN r.id; END IF;
   RAISE EXCEPTION 'Account Deletion Request already completed';
 END IF;
 SELECT * INTO a FROM iam.account_anonymisation WHERE id=p_anonymisation AND user_id=r.user_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Anonymisation does not belong to the requested User'; END IF;
 IF a.admin_id IS DISTINCT FROM ctx.admin_id THEN RAISE EXCEPTION 'Completion Admin must own the anonymisation action'; END IF;
 IF NOT EXISTS(SELECT 1 FROM iam.user_account u WHERE u.id=r.user_id AND u.anonymised_at IS NOT NULL) THEN
   RAISE EXCEPTION 'User must already be anonymised by the existing O19 process before request completion';
 END IF;
 tok:=technical.enter_write('iam.account_deletion_request',r.id::text);
 UPDATE iam.account_deletion_request SET completed_at=ctx.command_at,completed_by_admin_id=ctx.admin_id,anonymisation_id=a.id WHERE id=r.id;
 PERFORM technical.leave_write(tok);
 INSERT INTO audit.audit_event(id,occurred_at,actor_type,actor_id,action,subject_type,subject_id,reason,correlation_id,payload,context_user_id)
 VALUES(aid,ctx.command_at,'ADMIN',ctx.admin_id,'ACCOUNT_DELETION_REQUEST_COMPLETED','USER',r.user_id,a.reason,ctx.correlation_id,jsonb_build_object('deletionRequestId',r.id,'anonymisationId',a.id),r.user_id);
 RETURN r.id;
END;
$function$;

CREATE OR REPLACE FUNCTION review.guard_review_report()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Review Reports are retained; DELETE is rejected'; END IF;
 PERFORM technical.require_write('review.review_report',NEW.id::text);
 IF TG_OP='INSERT' THEN
   IF NEW.resolved_at IS NOT NULL OR NEW.resolved_by_admin_id IS NOT NULL OR NEW.resolution_note IS NOT NULL OR NEW.moderation_event_id IS NOT NULL THEN
     RAISE EXCEPTION 'New Review Report must be unresolved';
   END IF;
   RETURN NEW;
 END IF;
 IF NEW.id<>OLD.id OR NEW.review_id<>OLD.review_id OR NEW.reporter_user_id<>OLD.reporter_user_id OR NEW.reason<>OLD.reason
    OR NEW.details IS DISTINCT FROM OLD.details OR NEW.created_at<>OLD.created_at OR NEW.correlation_id<>OLD.correlation_id THEN
   RAISE EXCEPTION 'Review Report source facts are immutable';
 END IF;
 IF OLD.resolved_at IS NOT NULL THEN RAISE EXCEPTION 'Resolved Review Report is immutable'; END IF;
 IF NEW.resolved_at IS NULL OR NEW.resolved_by_admin_id IS NULL OR NULLIF(btrim(NEW.resolution_note),'') IS NULL THEN
   RAISE EXCEPTION 'Review Report resolution is one atomic close';
 END IF;
 RETURN NEW;
END;
$function$;
CREATE TRIGGER tr_126_review_report_guard BEFORE INSERT OR UPDATE OR DELETE ON review.review_report FOR EACH ROW EXECUTE FUNCTION review.guard_review_report();
CREATE TRIGGER tr_126_review_report_no_truncate BEFORE TRUNCATE ON review.review_report FOR EACH STATEMENT EXECUTE FUNCTION technical.reject_truncate();

CREATE OR REPLACE FUNCTION review.report_review(p_review uuid,p_reporter uuid,p_reason text,p_details text,p_correlation uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE r review.review%ROWTYPE; v_now timestamptz; v_id uuid:=gen_random_uuid(); tok uuid; aid uuid:=gen_random_uuid();
BEGIN
 IF p_reporter IS NULL OR p_correlation IS NULL OR NULLIF(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'Reporter, correlation and reason are required'; END IF;
 SELECT * INTO r FROM review.review WHERE id=p_review;
 IF NOT FOUND OR r.status<>'ACTIVE' OR r.author_deleted_at IS NOT NULL THEN RAISE EXCEPTION 'Only an ACTIVE public Review can be reported'; END IF;
 v_now:=review.customer_command(p_reporter,r.venue_id);
 IF NOT EXISTS(SELECT 1 FROM iam.user_account u WHERE u.id=p_reporter AND u.anonymised_at IS NULL) THEN RAISE EXCEPTION 'Signed-in active Customer required'; END IF;
 tok:=technical.enter_write('review.review_report',v_id::text);
 INSERT INTO review.review_report(id,review_id,reporter_user_id,reason,details,created_at,correlation_id)
 VALUES(v_id,p_review,p_reporter,btrim(p_reason),NULLIF(btrim(p_details),''),v_now,p_correlation);
 PERFORM technical.leave_write(tok);
 INSERT INTO audit.audit_event(id,occurred_at,actor_type,actor_id,action,subject_type,subject_id,reason,correlation_id,payload,context_user_id,context_venue_id)
 VALUES(aid,v_now,'CUSTOMER',p_reporter,'REVIEW_REPORTED','REVIEW',p_review,btrim(p_reason),p_correlation,jsonb_build_object('reviewReportId',v_id),p_reporter,r.venue_id);
 RETURN v_id;
END;
$function$;

CREATE OR REPLACE FUNCTION review.resolve_report(p_report uuid,p_resolution_note text,p_moderation_event uuid DEFAULT NULL)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE ctx record; rr review.review_report%ROWTYPE; ev review.review_moderation_event%ROWTYPE; tok uuid; aid uuid:=gen_random_uuid(); v_user uuid; v_venue uuid;
BEGIN
 SELECT * INTO STRICT ctx FROM admin.command_context();
 IF NULLIF(btrim(p_resolution_note),'') IS NULL THEN RAISE EXCEPTION 'Resolution note is required'; END IF;
 SELECT * INTO rr FROM review.review_report WHERE id=p_report FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Unknown Review Report'; END IF;
 IF rr.resolved_at IS NOT NULL THEN
   IF rr.resolved_by_admin_id=ctx.admin_id AND rr.moderation_event_id IS NOT DISTINCT FROM p_moderation_event THEN RETURN rr.id; END IF;
   RAISE EXCEPTION 'Review Report already resolved';
 END IF;
 IF p_moderation_event IS NOT NULL THEN
   SELECT * INTO ev FROM review.review_moderation_event WHERE id=p_moderation_event AND review_id=rr.review_id;
   IF NOT FOUND THEN RAISE EXCEPTION 'Moderation event must belong to the reported Review'; END IF;
 END IF;
 SELECT r.user_id,r.venue_id INTO v_user,v_venue FROM review.review r WHERE r.id=rr.review_id;
 tok:=technical.enter_write('review.review_report',rr.id::text);
 UPDATE review.review_report SET resolved_at=ctx.command_at,resolved_by_admin_id=ctx.admin_id,resolution_note=btrim(p_resolution_note),moderation_event_id=p_moderation_event WHERE id=rr.id;
 PERFORM technical.leave_write(tok);
 INSERT INTO audit.audit_event(id,occurred_at,actor_type,actor_id,action,subject_type,subject_id,reason,correlation_id,payload,context_user_id,context_venue_id)
 VALUES(aid,ctx.command_at,'ADMIN',ctx.admin_id,'REVIEW_REPORT_RESOLVED','REVIEW',rr.review_id,btrim(p_resolution_note),ctx.correlation_id,jsonb_build_object('reviewReportId',rr.id,'moderationEventId',p_moderation_event),v_user,v_venue);
 RETURN rr.id;
END;
$function$;

REVOKE ALL ON FUNCTION iam.guard_account_deletion_request() FROM PUBLIC;
REVOKE ALL ON FUNCTION review.guard_review_report() FROM PUBLIC;


-- =====================================================================================================
-- v1.1.27 — Review fixes (DB vs Product Spec v5.0 / FRS v1.1 / Architecture pack).
-- Scope: only the defects listed in the v1.1.27 change report. Every other object is unchanged.
--   F01 user_commitment_guard created automatically for every User
--   F02 Ban ending exactly at startAt does not restore a BAN-only participant (Product §37.11)
--   F03 SECURITY DEFINER functions are no longer executable by PUBLIC
--   F04 Review reports: one unresolved report per reporter per Review; deleted-account Reviews not reportable
--   F05 Inventory cross-class guard refuses REPEATABLE READ (race safety)
--   F06 Account deletion / O19 anonymisation producer + guards; deleted-account Reviews removed (PCR-002)
--   F07 Global Booking Fee and Tournament Creation Fee are versioned configuration (Product §5.1, §5.3, FR-ADM-10)
--   F08 Username 30-day change cooldown + append-only username history (Product §7.5)
--   F09 Area deactivation / assignment invariant (Product §12, predicate item 7 of §22)
--   F10 OTP rules: 5 min validity, 5 attempts, 60 s resend, 5 sends/hour/destination, supersede (Product §7.3)
--   F11 Online Booking creation: 15-min lead, 10-min response deadline, intake window & 10-min cutoff, Area ACTIVE (§21-§23)
--   F12 Operating Session snapshot immutable once referenced; Owner Password secret never deleted (§14.6, §10.2)
--   F14 Booking state machine: FRS §2.1 transition graph, reasons per source state, terminal immutability
--   F15 Booking creation: Venue Account ENABLED; Online needs Marketplace ACTIVE; Manual never ONBOARDING, never back-dated
--   F16 Architecture-required access paths (native indexes)
--   F17 Venue Marketplace Status never returns to ONBOARDING (Product Owner decision 26 Sep 2026)
--   F18 Venue Web Push subscriptions (Product Owner decision A6) + launch notification catalogue (Product §52)
--   F13 Player-hosted Tournament approval: MIN(created+10 min, checkpoint), cutoff startAt-2h, REJECTED carries
--       VENUE_REJECTED_TOURNAMENT, timeout -> CANCELLED/VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME (FR-TRN-10, §36.3, §37.2-37.3)
-- =====================================================================================================

-- ---------- F07 configuration: fee keys and effective-value helper ----------
INSERT INTO config.configuration_key(key,value_type,min_value,max_value,units,allowed_values,owner_module,source_reference)
VALUES
 ('booking.fee','NUMERIC',0,NULL,'EGP',NULL,'booking','Product v5.0 s5.1 / FR-ADM-10 Global Booking Fee; launch value EGP 0 (v1.1.27 seed)'),
 ('tournament.creation_fee','NUMERIC',0,NULL,'EGP',NULL,'tournament','Product v5.0 s5.3, s36.3 / FR-ADM-10 Tournament Creation Fee; launch value EGP 0 (v1.1.27 seed)')
ON CONFLICT(key) DO NOTHING;

DO $seed_fee_config$
DECLARE k text; vid uuid; tok uuid;
BEGIN
 FOREACH k IN ARRAY ARRAY['booking.fee','tournament.creation_fee'] LOOP
   IF NOT EXISTS(SELECT 1 FROM config.configuration_version WHERE key=k) THEN
     IF EXISTS(SELECT 1 FROM config.system_configuration WHERE key=k) THEN
       RAISE EXCEPTION 'Existing current config % lacks historical provenance',k;
     END IF;
     vid:=gen_random_uuid();
     tok:=technical.enter_write('config.configuration_version',vid::text);
     INSERT INTO config.configuration_version(id,key,new_value,effective_from,reason)
       VALUES(vid,k,'0'::jsonb,'-infinity','Initial launch configuration from Product v5.0 (EGP 0); technical bootstrap');
     PERFORM technical.leave_write(tok);
     tok:=technical.enter_write('config.system_configuration',k);
     INSERT INTO config.system_configuration(key,value,updated_at) VALUES(k,'0'::jsonb,clock_timestamp());
     PERFORM technical.leave_write(tok);
   END IF;
 END LOOP;
END;
$seed_fee_config$;

CREATE OR REPLACE FUNCTION config.effective_numeric(p_key text,p_at timestamptz)
RETURNS numeric LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v jsonb;
BEGIN
 IF p_at IS NULL THEN RAISE EXCEPTION 'Configuration lookup requires an instant'; END IF;
 SELECT c.new_value INTO v FROM config.configuration_version c
  WHERE c.key=p_key AND c.effective_from<=p_at ORDER BY c.effective_from DESC,c.version_position DESC LIMIT 1;
 IF v IS NULL OR jsonb_typeof(v)<>'number' THEN RAISE EXCEPTION 'No numeric configuration % effective at %',p_key,p_at; END IF;
 RETURN (v #>> '{}')::numeric;
END;
$function$;

-- ---------- F01 user_commitment_guard for every User ----------
CREATE OR REPLACE FUNCTION iam.initialize_commitment_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 INSERT INTO iam.user_commitment_guard(user_id,version) VALUES(NEW.id,0) ON CONFLICT(user_id) DO NOTHING;
 RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_127_user_commitment_guard_init ON iam.user_account;
CREATE TRIGGER tr_127_user_commitment_guard_init AFTER INSERT ON iam.user_account
 FOR EACH ROW EXECUTE FUNCTION iam.initialize_commitment_guard();
INSERT INTO iam.user_commitment_guard(user_id,version) SELECT u.id,0 FROM iam.user_account u ON CONFLICT(user_id) DO NOTHING;

-- ---------- F06 / F08 user_account guard: anonymisation path + username cooldown ----------
CREATE OR REPLACE FUNCTION iam.guard_user_account_update()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_last timestamptz;
BEGIN
 IF NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'User ID is immutable'; END IF;
 IF OLD.anonymised_at IS NOT NULL THEN
   IF to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD) THEN
     RAISE EXCEPTION 'An anonymised (deleted) account is immutable';
   END IF;
   RETURN NEW;
 END IF;
 IF NEW.anonymised_at IS NOT NULL THEN
   -- PCR-002 / O19: only the audited anonymisation producer may complete deletion.
   IF NOT technical.has_write('iam.user_account',NEW.id::text) THEN
     RAISE EXCEPTION 'Account anonymisation requires iam.anonymise_user (O19)';
   END IF;
   IF NOT EXISTS(SELECT 1 FROM iam.account_anonymisation a WHERE a.user_id=NEW.id AND a.performed_at=NEW.anonymised_at) THEN
     RAISE EXCEPTION 'Account anonymisation requires its account_anonymisation record';
   END IF;
   RETURN NEW;
 END IF;
 -- Product §7.5: Username editable, unique, 30-day change cooldown.
 IF NEW.username IS DISTINCT FROM OLD.username THEN
   PERFORM 1 FROM iam.user_commitment_guard g WHERE g.user_id=NEW.id FOR UPDATE;
   SELECT max(c.changed_at) INTO v_last FROM iam.username_change c WHERE c.user_id=NEW.id;
   IF v_last IS NOT NULL AND now() < v_last + interval '30 days' THEN
     RAISE EXCEPTION 'Username change cooldown is active until %',v_last + interval '30 days';
   END IF;
 END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_127_user_account_guard ON iam.user_account;
CREATE TRIGGER tr_127_user_account_guard BEFORE UPDATE ON iam.user_account
 FOR EACH ROW EXECUTE FUNCTION iam.guard_user_account_update();

CREATE OR REPLACE FUNCTION iam.record_username_change()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_id uuid:=gen_random_uuid(); tok uuid;
BEGIN
 IF NEW.username IS DISTINCT FROM OLD.username AND NEW.anonymised_at IS NULL THEN
   tok:=technical.enter_write('iam.username_change',v_id::text);
   INSERT INTO iam.username_change(id,user_id,old_username,new_username,changed_at) VALUES(v_id,NEW.id,OLD.username,NEW.username,now());
   PERFORM technical.leave_write(tok);
 END IF;
 RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_127_username_change_record ON iam.user_account;
CREATE TRIGGER tr_127_username_change_record AFTER UPDATE OF username ON iam.user_account
 FOR EACH ROW EXECUTE FUNCTION iam.record_username_change();

CREATE OR REPLACE FUNCTION iam.guard_username_change()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'iam.username_change is append-only history'; END IF;
 PERFORM technical.require_write('iam.username_change',NEW.id::text);
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_127_username_change_guard ON iam.username_change;
CREATE TRIGGER tr_127_username_change_guard BEFORE INSERT OR UPDATE OR DELETE ON iam.username_change
 FOR EACH ROW EXECUTE FUNCTION iam.guard_username_change();
DROP TRIGGER IF EXISTS tr_127_username_change_no_truncate ON iam.username_change;
CREATE TRIGGER tr_127_username_change_no_truncate BEFORE TRUNCATE ON iam.username_change
 FOR EACH STATEMENT EXECUTE FUNCTION technical.reject_truncate();

-- ---------- F06 account_anonymisation guard ----------
CREATE OR REPLACE FUNCTION iam.guard_account_anonymisation()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'iam.account_anonymisation is append-only audit history'; END IF;
 PERFORM technical.require_write('iam.account_anonymisation',NEW.id::text);
 IF NEW.performed_at>clock_timestamp() THEN RAISE EXCEPTION 'Anonymisation performed_at cannot be in the future'; END IF;
 IF NOT EXISTS(SELECT 1 FROM iam.admin_account a WHERE a.id=NEW.admin_id AND a.is_active) THEN
   RAISE EXCEPTION 'Anonymisation requires an active Admin';
 END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_127_account_anonymisation_guard ON iam.account_anonymisation;
CREATE TRIGGER tr_127_account_anonymisation_guard BEFORE INSERT OR UPDATE OR DELETE ON iam.account_anonymisation
 FOR EACH ROW EXECUTE FUNCTION iam.guard_account_anonymisation();
DROP TRIGGER IF EXISTS tr_127_account_anonymisation_no_truncate ON iam.account_anonymisation;
CREATE TRIGGER tr_127_account_anonymisation_no_truncate BEFORE TRUNCATE ON iam.account_anonymisation
 FOR EACH STATEMENT EXECUTE FUNCTION technical.reject_truncate();

-- ---------- F06 deleted-account Reviews leave public display (PCR-002) ----------
CREATE OR REPLACE FUNCTION review.remove_reviews_of_deleted_account(p_user uuid)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE ctx record; r review.review%ROWTYPE; tok uuid; n integer:=0;
BEGIN
 SELECT * INTO STRICT ctx FROM admin.command_context();
 IF NOT EXISTS(SELECT 1 FROM iam.user_account u WHERE u.id=p_user AND u.anonymised_at IS NOT NULL) THEN
   RAISE EXCEPTION 'Reviews are removed for account deletion only after O19 anonymisation';
 END IF;
 FOR r IN SELECT * FROM review.review x WHERE x.user_id=p_user AND x.status IN ('ACTIVE','HIDDEN','PENDING_MODERATION') ORDER BY x.id FOR UPDATE LOOP
   tok:=technical.enter_write('review.review',r.id::text);
   UPDATE review.review SET status='REMOVED',author_deleted_at=ctx.command_at,updated_at=GREATEST(ctx.command_at,r.updated_at) WHERE id=r.id;
   PERFORM technical.leave_write(tok);
   PERFORM review.write_audit('ADMIN',ctx.admin_id,'REVIEW_REMOVED_ACCOUNT_DELETED',r.id,'Account deletion (PCR-002)',ctx.correlation_id,
     ctx.command_at,r.status,'REMOVED',r.user_id,r.venue_id,NULL);
   PERFORM review.refresh_venue_rating(r.venue_id,ctx.command_at);
   n:=n+1;
 END LOOP;
 RETURN n;
END;
$function$;

-- ---------- F06 O19 anonymisation producer ----------
-- Tournament participant reclassification to INELIGIBLE/ACCOUNT_DELETED stays with the Tournament module in the
-- same transaction (already enforced by tr_deleted_user_tournament_participant_cascade).
CREATE OR REPLACE FUNCTION iam.anonymise_user(p_user uuid,p_reason text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE ctx record; u iam.user_account%ROWTYPE; v_anon uuid:=gen_random_uuid(); tok uuid; v_req uuid;
BEGIN
 SELECT * INTO STRICT ctx FROM admin.command_context();
 IF p_user IS NULL OR NULLIF(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'User and anonymisation reason are required'; END IF;
 SELECT * INTO u FROM iam.user_account WHERE id=p_user FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Unknown User'; END IF;
 IF u.anonymised_at IS NOT NULL THEN RAISE EXCEPTION 'User is already anonymised'; END IF;
 tok:=technical.enter_write('iam.account_anonymisation',v_anon::text);
 INSERT INTO iam.account_anonymisation(id,user_id,admin_id,reason,performed_at) VALUES(v_anon,p_user,ctx.admin_id,btrim(p_reason),ctx.command_at);
 PERFORM technical.leave_write(tok);
 tok:=technical.enter_write('iam.user_account',p_user::text);
 UPDATE iam.user_account
    SET anonymised_at=ctx.command_at,full_name='',email='',password_hash='',phone_e164='anonymised:'||p_user::text
  WHERE id=p_user;
 PERFORM technical.leave_write(tok);
 -- Login disabled: every Customer refresh token is revoked.
 UPDATE iam.auth_refresh_token SET revoked_at=ctx.command_at
  WHERE subject_type='CUSTOMER' AND subject_id=p_user AND revoked_at IS NULL;
 PERFORM review.remove_reviews_of_deleted_account(p_user);
 SELECT r.id INTO v_req FROM iam.account_deletion_request r WHERE r.user_id=p_user AND r.completed_at IS NULL FOR UPDATE;
 IF FOUND THEN PERFORM iam.complete_account_deletion_request(v_req,v_anon); END IF;
 INSERT INTO audit.audit_event(id,occurred_at,actor_type,actor_id,action,subject_type,subject_id,reason,correlation_id,payload,context_user_id)
 VALUES(gen_random_uuid(),ctx.command_at,'ADMIN',ctx.admin_id,'ACCOUNT_ANONYMISED','USER',p_user,btrim(p_reason),ctx.correlation_id,
   jsonb_build_object('anonymisationId',v_anon,'deletionRequestId',v_req),p_user);
 RETURN v_anon;
END;
$function$;

-- Commit-time completeness of an anonymised account (PCR-002, Product §53.5).
CREATE OR REPLACE FUNCTION iam.assert_anonymised_account_complete()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF NEW.anonymised_at IS NULL OR OLD.anonymised_at IS NOT NULL THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM iam.account_anonymisation a WHERE a.user_id=NEW.id AND a.performed_at=NEW.anonymised_at) THEN
   RAISE EXCEPTION 'Anonymised User % lacks its anonymisation record',NEW.id;
 END IF;
 IF EXISTS(SELECT 1 FROM review.review r WHERE r.user_id=NEW.id AND r.status IN ('ACTIVE','HIDDEN','PENDING_MODERATION')) THEN
   RAISE EXCEPTION 'Deleted account % still has Reviews that can be publicly displayed',NEW.id;
 END IF;
 IF EXISTS(SELECT 1 FROM iam.account_deletion_request r WHERE r.user_id=NEW.id AND r.completed_at IS NULL) THEN
   RAISE EXCEPTION 'Deleted account % has an uncompleted Account Deletion Request',NEW.id;
 END IF;
 IF EXISTS(SELECT 1 FROM iam.auth_refresh_token t WHERE t.subject_type='CUSTOMER' AND t.subject_id=NEW.id AND t.revoked_at IS NULL) THEN
   RAISE EXCEPTION 'Deleted account % still has an unrevoked login token',NEW.id;
 END IF;
 RETURN NULL;
END;
$function$;
DROP TRIGGER IF EXISTS tr_127_anonymised_account_complete ON iam.user_account;
CREATE CONSTRAINT TRIGGER tr_127_anonymised_account_complete AFTER UPDATE OF anonymised_at ON iam.user_account
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION iam.assert_anonymised_account_complete();

-- ---------- F09 Areas ----------
CREATE OR REPLACE FUNCTION geo.guard_area_deactivation()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Areas are deactivated, never deleted; historical references remain'; END IF;
 IF OLD.is_active AND NOT NEW.is_active AND EXISTS(
    SELECT 1 FROM venue.venue v WHERE v.area_id=NEW.id AND v.marketplace_status IN ('ACTIVE','SUSPENDED')) THEN
   RAISE EXCEPTION 'Area cannot be deactivated while a Venue in it is ACTIVE or SUSPENDED';
 END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_127_area_deactivation_guard ON geo.area;
CREATE TRIGGER tr_127_area_deactivation_guard BEFORE UPDATE OR DELETE ON geo.area
 FOR EACH ROW EXECUTE FUNCTION geo.guard_area_deactivation();

CREATE OR REPLACE FUNCTION venue.guard_venue_area()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_active boolean;
BEGIN
 SELECT a.is_active INTO v_active FROM geo.area a WHERE a.id=NEW.area_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Venue Area does not exist'; END IF;
 IF NOT v_active AND (TG_OP='INSERT' OR NEW.area_id IS DISTINCT FROM OLD.area_id) THEN
   RAISE EXCEPTION 'Only an ACTIVE Area is available for new Venue assignment';
 END IF;
 IF NOT v_active AND NEW.marketplace_status IN ('ACTIVE','SUSPENDED')
    AND (TG_OP='INSERT' OR NEW.marketplace_status IS DISTINCT FROM OLD.marketplace_status OR NEW.area_id IS DISTINCT FROM OLD.area_id) THEN
   RAISE EXCEPTION 'A Venue in an inactive Area cannot be ACTIVE or SUSPENDED';
 END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_127_venue_area_guard ON venue.venue;
CREATE TRIGGER tr_127_venue_area_guard BEFORE INSERT OR UPDATE OF area_id, marketplace_status ON venue.venue
 FOR EACH ROW EXECUTE FUNCTION venue.guard_venue_area();

-- ---------- F10 OTP ----------
CREATE OR REPLACE FUNCTION iam.guard_otp_challenge()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_count integer;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'OTP challenges are retained for rate limiting and audit'; END IF;
 IF TG_OP='INSERT' THEN
   IF NEW.issued_at>clock_timestamp() THEN RAISE EXCEPTION 'OTP issued_at cannot be in the future'; END IF;
   IF NEW.attempts<>0 OR NEW.consumed_at IS NOT NULL OR NEW.superseded_at IS NOT NULL THEN
     RAISE EXCEPTION 'A new OTP starts unused';
   END IF;
   PERFORM pg_advisory_xact_lock(hashtextextended('e7gz.otp:'||NEW.destination,0));
   IF EXISTS(SELECT 1 FROM iam.otp_challenge o WHERE o.destination=NEW.destination AND o.purpose=NEW.purpose
             AND o.issued_at > NEW.issued_at - interval '60 seconds') THEN
     RAISE EXCEPTION 'OTP resend is available 60 seconds after the previous send';
   END IF;
   SELECT count(*) INTO v_count FROM iam.otp_challenge o
    WHERE o.destination=NEW.destination AND o.issued_at > NEW.issued_at - interval '1 hour';
   IF v_count>=5 THEN RAISE EXCEPTION 'Maximum 5 OTP sends per hour per destination'; END IF;
   -- A new OTP invalidates the previous OTP.
   UPDATE iam.otp_challenge SET superseded_at=NEW.issued_at
    WHERE destination=NEW.destination AND purpose=NEW.purpose AND consumed_at IS NULL AND superseded_at IS NULL;
   RETURN NEW;
 END IF;
 IF NEW.id<>OLD.id OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.purpose<>OLD.purpose OR NEW.destination<>OLD.destination
    OR NEW.code_hash<>OLD.code_hash OR NEW.expires_at<>OLD.expires_at OR NEW.issued_at<>OLD.issued_at THEN
   RAISE EXCEPTION 'OTP challenge identity, code and validity are immutable';
 END IF;
 IF (OLD.consumed_at IS NOT NULL AND NEW.consumed_at IS DISTINCT FROM OLD.consumed_at)
    OR (OLD.superseded_at IS NOT NULL AND NEW.superseded_at IS DISTINCT FROM OLD.superseded_at) THEN
   RAISE EXCEPTION 'OTP consumption/supersession is recorded once';
 END IF;
 IF NEW.attempts<OLD.attempts OR NEW.attempts>OLD.attempts+1 THEN RAISE EXCEPTION 'OTP attempts increase by one per verification'; END IF;
 IF (NEW.attempts>OLD.attempts OR (OLD.consumed_at IS NULL AND NEW.consumed_at IS NOT NULL))
    AND (OLD.consumed_at IS NOT NULL OR OLD.superseded_at IS NOT NULL OR now()>=OLD.expires_at OR OLD.attempts>=5) THEN
   RAISE EXCEPTION 'OTP is no longer usable (expired, superseded, consumed or out of attempts)';
 END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_127_otp_challenge_guard ON iam.otp_challenge;
CREATE TRIGGER tr_127_otp_challenge_guard BEFORE INSERT OR UPDATE OR DELETE ON iam.otp_challenge
 FOR EACH ROW EXECUTE FUNCTION iam.guard_otp_challenge();
DROP TRIGGER IF EXISTS tr_127_otp_challenge_no_truncate ON iam.otp_challenge;
CREATE TRIGGER tr_127_otp_challenge_no_truncate BEFORE TRUNCATE ON iam.otp_challenge
 FOR EACH STATEMENT EXECUTE FUNCTION technical.reject_truncate();

-- ---------- F11 / F07 Online Booking creation predicate items the database can prove ----------
CREATE OR REPLACE FUNCTION booking.validate_online_booking_intake()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_area_active boolean;
BEGIN
 IF NEW.source<>'ONLINE' THEN RETURN NEW; END IF;
 IF NEW.created_at IS NULL OR NEW.created_at>clock_timestamp() THEN
   RAISE EXCEPTION 'Online Booking created_at must be the server creation instant';
 END IF;
 -- §22 item 11: requested Start at least 15 minutes in the future.
 IF NEW.start_at < NEW.created_at + interval '15 minutes' THEN
   RAISE EXCEPTION 'Online Booking Start must be at least 15 minutes after creation';
 END IF;
 -- §23.1: the Venue has 10 minutes to respond.
 IF NEW.status='PENDING' AND NEW.venue_response_expires_at IS DISTINCT FROM NEW.created_at + interval '10 minutes' THEN
   RAISE EXCEPTION 'venueResponseExpiresAt must be creation + 10 minutes';
 END IF;
 -- §21 / §22 items 8-9: created inside a current Operating Session and at least 10 minutes before it ends.
 IF NOT EXISTS(SELECT 1 FROM venue.operating_session s
                WHERE s.venue_id=NEW.venue_id AND s.session_period @> NEW.created_at
                  AND NEW.created_at < upper(s.session_period) - interval '10 minutes') THEN
   RAISE EXCEPTION 'Online Booking intake requires a current Operating Session and stops 10 minutes before it ends';
 END IF;
 -- §22 item 7: Area ACTIVE.
 SELECT a.is_active INTO v_area_active FROM venue.venue v JOIN geo.area a ON a.id=v.area_id WHERE v.id=NEW.venue_id FOR SHARE OF a;
 IF NOT COALESCE(v_area_active,false) THEN RAISE EXCEPTION 'Online Booking requires the Venue Area to be ACTIVE'; END IF;
 -- §5.1: the stored fee is the global Booking Fee at creation.
 IF NEW.booking_fee_snapshot IS DISTINCT FROM config.effective_numeric('booking.fee',NEW.created_at) THEN
   RAISE EXCEPTION 'booking_fee_snapshot must equal the Global Booking Fee at creation';
 END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_21_booking_online_intake ON booking.booking;
CREATE TRIGGER tr_21_booking_online_intake BEFORE INSERT ON booking.booking
 FOR EACH ROW EXECUTE FUNCTION booking.validate_online_booking_intake();

-- ---------- F12 venue setup history ----------
CREATE OR REPLACE FUNCTION venue.guard_operating_session()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_referenced boolean;
BEGIN
 SELECT EXISTS(SELECT 1 FROM booking.booking b WHERE b.operating_session_id=OLD.id)
     OR EXISTS(SELECT 1 FROM tournament.tournament t WHERE t.operating_session_id=OLD.id) INTO v_referenced;
 IF NOT v_referenced THEN
   IF TG_OP='DELETE' THEN RETURN OLD; END IF;
   RETURN NEW;
 END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'A referenced Operating Session is a historical snapshot and cannot be deleted'; END IF;
 IF NEW.venue_id<>OLD.venue_id OR NEW.operating_day<>OLD.operating_day OR NEW.local_start<>OLD.local_start OR NEW.local_end<>OLD.local_end
    OR NEW.session_period<>OLD.session_period OR NEW.timezone<>OLD.timezone OR NEW.opening_template_id<>OLD.opening_template_id THEN
   RAISE EXCEPTION 'A referenced Operating Session is a historical snapshot; Opening Hours changes never rewrite it';
 END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_127_operating_session_history ON venue.operating_session;
CREATE TRIGGER tr_127_operating_session_history BEFORE UPDATE OR DELETE ON venue.operating_session
 FOR EACH ROW EXECUTE FUNCTION venue.guard_operating_session();

CREATE OR REPLACE FUNCTION iam.guard_venue_owner_secret()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'The Owner Password secret is replaced, never deleted'; END IF;
 IF TG_OP='INSERT' THEN
   IF NEW.changed_at>clock_timestamp() THEN RAISE EXCEPTION 'Owner Password changed_at cannot be in the future'; END IF;
   RETURN NEW;
 END IF;
 IF NEW.venue_account_id<>OLD.venue_account_id THEN RAISE EXCEPTION 'Owner Password secret belongs to one Venue Account'; END IF;
 IF NEW.owner_password_hash IS DISTINCT FROM OLD.owner_password_hash THEN
   IF NEW.changed_at<=OLD.changed_at OR NEW.changed_at>clock_timestamp() OR NEW.version<>OLD.version+1 THEN
     RAISE EXCEPTION 'Owner Password change must advance changed_at and version';
   END IF;
 ELSIF NEW.changed_at<>OLD.changed_at OR NEW.version<>OLD.version THEN
   RAISE EXCEPTION 'Owner Password metadata changes only with the secret';
 END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_127_venue_owner_secret_guard ON iam.venue_owner_secret;
CREATE TRIGGER tr_127_venue_owner_secret_guard BEFORE INSERT OR UPDATE OR DELETE ON iam.venue_owner_secret
 FOR EACH ROW EXECUTE FUNCTION iam.guard_venue_owner_secret();
DROP TRIGGER IF EXISTS tr_127_venue_owner_secret_no_truncate ON iam.venue_owner_secret;
CREATE TRIGGER tr_127_venue_owner_secret_no_truncate BEFORE TRUNCATE ON iam.venue_owner_secret
 FOR EACH STATEMENT EXECUTE FUNCTION technical.reject_truncate();

-- ---------- F14 Booking state machine (FRS §2.1; Product §23-§32) ----------
-- The database owns the transition graph and terminal immutability, as it already does for Tournaments.
-- Eligibility and reason-priority decisions stay in the application's single predicate / lifecycle engine.
CREATE OR REPLACE FUNCTION booking.guard_booking_transition()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE r text := NEW.terminal_reason; ok boolean := false;
BEGIN
 IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
   IF OLD.status IN ('COMPLETED','REJECTED','CANCELLED') AND NEW.terminal_reason IS DISTINCT FROM OLD.terminal_reason THEN
     RAISE EXCEPTION 'Terminal Booking reason is immutable';
   END IF;
   RETURN NEW;
 END IF;
 IF OLD.status IN ('COMPLETED','REJECTED','CANCELLED') THEN
   RAISE EXCEPTION 'Terminal Booking state % is immutable',OLD.status;
 END IF;
 ok := CASE
  WHEN OLD.status='PENDING' AND NEW.status IN ('CONFIRMED','VENUE_RESPONSE_EXPIRED') THEN true
  WHEN OLD.status='PENDING' AND NEW.status='REJECTED' THEN r='VENUE_REJECTED'
  WHEN OLD.status='PENDING' AND NEW.status='CANCELLED' THEN r IN ('CUSTOMER_CANCELLED','USER_BANNED','VENUE_OPENING_HOURS_CHANGED','VENUE_CLOSURE',
       'VENUE_EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED','VENUE_RESPONSE_INTERRUPTED_BY_EMERGENCY',
       'RESOURCE_RESPONSE_INTERRUPTED_BY_EMERGENCY','ADMIN_CANCELLED','ADMIN_CORRECTION')
  WHEN OLD.status='VENUE_RESPONSE_EXPIRED' AND NEW.status='AWAITING_CUSTOMER_CONFIRMATION' THEN true
  WHEN OLD.status='VENUE_RESPONSE_EXPIRED' AND NEW.status='REJECTED' THEN r='REJECTED_AFTER_EXPIRY'
  WHEN OLD.status='VENUE_RESPONSE_EXPIRED' AND NEW.status='CANCELLED' THEN r IN ('RESOURCE_OWNER_REVIEW_REQUIRED','RESOURCE_EMERGENCY_OUTAGE',
       'VENUE_EMERGENCY_CLOSURE','VENUE_ACCOUNT_DISABLED','VENUE_DID_NOT_RESPOND_IN_TIME','ADMIN_CANCELLED','ADMIN_CORRECTION')
  WHEN OLD.status='AWAITING_CUSTOMER_CONFIRMATION' AND NEW.status='CONFIRMED' THEN true
  WHEN OLD.status='AWAITING_CUSTOMER_CONFIRMATION' AND NEW.status='CANCELLED' THEN r IN ('CUSTOMER_DECLINED_LATE_CONFIRM','CUSTOMER_RECONFIRM_TIMEOUT',
       'VENUE_ACCOUNT_DISABLED','USER_BANNED','VENUE_OPENING_HOURS_CHANGED','VENUE_CLOSURE','VENUE_EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE',
       'RESOURCE_OWNER_REVIEW_REQUIRED','LATE_CONFIRM_INTERRUPTED_BY_EMERGENCY','ADMIN_CANCELLED','ADMIN_CORRECTION')
  WHEN OLD.status='CONFIRMED' AND NEW.status IN ('ACTIVE','NO_SHOW') THEN NOT (NEW.status='NO_SHOW' AND NEW.source='MANUAL')
  WHEN OLD.status='CONFIRMED' AND NEW.status='CANCELLED' THEN
       (NEW.source='ONLINE' AND r IN ('CUSTOMER_CANCELLED','VENUE_CANCELLED_CONFIRMED_BOOKING','USER_BANNED'))
    OR (NEW.source='MANUAL' AND r='VENUE_CANCELLED_MANUAL_BOOKING')
    OR r IN ('VENUE_OPENING_HOURS_CHANGED','VENUE_CLOSURE','VENUE_EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED',
             'SYSTEM_RESOURCE_STATE_INTEGRITY_ERROR','ADMIN_CANCELLED','ADMIN_CORRECTION')
  WHEN OLD.status='ACTIVE' AND NEW.status='COMPLETED' THEN true
  WHEN OLD.status='ACTIVE' AND NEW.status='NO_SHOW' THEN NEW.source='ONLINE'
  WHEN OLD.status='ACTIVE' AND NEW.status='CANCELLED' THEN r IN ('VENUE_EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED',
       'ADMIN_CANCELLED','ADMIN_CORRECTION')
  WHEN OLD.status='NO_SHOW' AND NEW.status='CANCELLED' THEN r='ADMIN_NO_SHOW_REVERSAL'
  WHEN OLD.status='NO_SHOW' AND NEW.status='COMPLETED' THEN true
  ELSE false END;
 IF NOT COALESCE(ok,false) THEN
   RAISE EXCEPTION 'Invalid Booking transition % -> % (reason %)',OLD.status,NEW.status,COALESCE(r,'none');
 END IF;
 -- Product §29.1: Customer cancellation only while now < startAt.
 IF r='CUSTOMER_CANCELLED' AND now() >= OLD.start_at THEN
   RAISE EXCEPTION 'Customer cancellation is disabled at/after Start Time';
 END IF;
 -- FRS §2.1: NO_SHOW reversal -> CANCELLED before original endAt, -> COMPLETED after it.
 IF OLD.status='NO_SHOW' AND NEW.status='CANCELLED' AND now() >= OLD.end_at THEN
   RAISE EXCEPTION 'No-show reversal after original endAt resolves to COMPLETED';
 END IF;
 IF OLD.status='NO_SHOW' AND NEW.status='COMPLETED' AND now() < OLD.end_at THEN
   RAISE EXCEPTION 'No-show reversal before original endAt resolves to CANCELLED/ADMIN_NO_SHOW_REVERSAL';
 END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_03_booking_transition_guard ON booking.booking;
CREATE TRIGGER tr_03_booking_transition_guard BEFORE UPDATE OF status, terminal_reason ON booking.booking
 FOR EACH ROW EXECUTE FUNCTION booking.guard_booking_transition();

-- ---------- F15 Booking creation: Venue eligibility and no back-dating (Product §22 items 5-6, §30.2, §30.5) ----------
CREATE OR REPLACE FUNCTION booking.validate_booking_creation_venue()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
DECLARE v_market text; v_account text;
BEGIN
 SELECT v.marketplace_status INTO v_market FROM venue.venue v WHERE v.id=NEW.venue_id FOR SHARE;
 SELECT va.account_status INTO v_account FROM iam.venue_account va WHERE va.venue_id=NEW.venue_id FOR SHARE;
 IF v_account IS DISTINCT FROM 'ENABLED' THEN RAISE EXCEPTION 'Booking creation requires Venue Account ENABLED'; END IF;
 IF NEW.source='ONLINE' THEN
   IF NEW.status<>'PENDING' THEN RAISE EXCEPTION 'An Online Booking is created PENDING'; END IF;
   IF v_market IS DISTINCT FROM 'ACTIVE' THEN RAISE EXCEPTION 'New Online Booking requires Venue Marketplace ACTIVE'; END IF;
 ELSE
   IF v_market IS NULL OR v_market='ONBOARDING' THEN RAISE EXCEPTION 'Manual Booking is not allowed for an ONBOARDING Venue'; END IF;
   IF NEW.created_at IS NULL OR NEW.created_at>clock_timestamp() OR NEW.start_at < NEW.created_at THEN
     RAISE EXCEPTION 'Manual Booking Start is now or future, never retroactive';
   END IF;
   IF (NEW.status='ACTIVE') <> (NEW.start_at = NEW.created_at) OR NEW.status NOT IN ('CONFIRMED','ACTIVE') THEN
     RAISE EXCEPTION 'Manual Booking is created CONFIRMED (future) or ACTIVE (current walk-in, startAt = creation)';
   END IF;
 END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_22_booking_creation_venue ON booking.booking;
CREATE TRIGGER tr_22_booking_creation_venue BEFORE INSERT ON booking.booking
 FOR EACH ROW EXECUTE FUNCTION booking.validate_booking_creation_venue();

-- ---------- F17 Venue Marketplace Status transitions (Product Owner decision 26 Sep 2026) ----------
-- ONBOARDING -> ACTIVE | INACTIVE | SUSPENDED; ACTIVE, INACTIVE and SUSPENDED switch freely; never back to ONBOARDING.
CREATE OR REPLACE FUNCTION venue.guard_venue_marketplace_transition()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF NEW.marketplace_status IS DISTINCT FROM OLD.marketplace_status AND NEW.marketplace_status='ONBOARDING' THEN
   RAISE EXCEPTION 'A Venue never returns to ONBOARDING';
 END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_127_venue_marketplace_transition ON venue.venue;
CREATE TRIGGER tr_127_venue_marketplace_transition BEFORE UPDATE OF marketplace_status ON venue.venue
 FOR EACH ROW EXECUTE FUNCTION venue.guard_venue_marketplace_transition();

-- ---------- F02 / F04 / F05 patched existing functions ----------
CREATE OR REPLACE FUNCTION tournament.guard_tournament_participant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    v_now timestamptz;
    t tournament.tournament%ROWTYPE;
    u iam.user_account%ROWTYPE;
    v_active integer;
    v_occupied integer;
    v_banned boolean;
    v_boundary_restore boolean := false;
BEGIN
    v_now := tournament.require_command_scope(COALESCE(NEW.tournament_id, OLD.tournament_id), NULL, NULL, COALESCE(NEW.user_id, OLD.user_id));
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Tournament Participant history may not be deleted';
    END IF;

    SELECT * INTO t FROM tournament.tournament WHERE id = NEW.tournament_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament does not exist'; END IF;
    SELECT * INTO u FROM iam.user_account WHERE id = NEW.user_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament Participant User does not exist'; END IF;
    SELECT EXISTS (
        SELECT 1 FROM trust.ban_instance b
         WHERE b.user_id = NEW.user_id AND b.status = 'ACTIVE'
           AND b.activated_at <= v_now AND b.ends_at > v_now
    ) INTO v_banned;

    IF TG_OP='UPDATE' AND OLD.status='INELIGIBLE' AND OLD.ineligible_reason='BAN' AND NEW.status='JOINED' THEN
        IF t.status='WAITING_FOR_PLAYERS' AND v_now >= t.checkpoint_at
           AND NOT EXISTS (
               SELECT 1 FROM trust.ban_instance b
                WHERE b.user_id=NEW.user_id AND b.activated_at <= t.checkpoint_at AND b.ends_at > t.checkpoint_at
           ) THEN
            v_boundary_restore := true;
        ELSIF t.status='CONFIRMED' AND v_now >= t.start_at
           AND NOT EXISTS (
               SELECT 1 FROM trust.ban_instance b
                WHERE b.user_id=NEW.user_id AND b.activated_at <= t.start_at AND b.ends_at >= t.start_at  -- v1.1.27: a Ban ending exactly at startAt does not restore (Product §37.11)
           ) THEN
            v_boundary_restore := true;
        END IF;
    END IF;

    -- Once a due boundary is reached, no participant mutation may change its result.
    -- The only exception is catching up a BAN-only restoration that was already effective at that boundary.
    IF t.status='WAITING_FOR_PLAYERS' AND v_now >= t.checkpoint_at AND NOT v_boundary_restore THEN
        RAISE EXCEPTION 'Tournament checkpoint is overdue; resolve the checkpoint before participant mutation';
    END IF;
    IF t.status='CONFIRMED' AND v_now >= t.start_at AND NOT v_boundary_restore THEN
        RAISE EXCEPTION 'Tournament start is due; resolve startAt before participant mutation';
    END IF;

    IF TG_OP = 'INSERT' THEN
        NEW.joined_at := v_now;
        NEW.status_changed_at := NEW.joined_at;
        NEW.status := 'JOINED';
        NEW.left_at := NULL;
        NEW.removed_at := NULL;
        NEW.ineligible_reason := NULL;

        IF NOT u.phone_verified OR u.anonymised_at IS NOT NULL OR v_banned THEN
            RAISE EXCEPTION 'Tournament join requires an Account-Verified, non-banned active User';
        END IF;
        IF t.status = 'PENDING_VENUE_APPROVAL' THEN
            IF t.host_type <> 'PLAYER' OR NOT t.creator_participates OR NEW.user_id IS DISTINCT FROM t.creator_user_id
               OR NOT tournament.created_in_command(t.id) THEN
                RAISE EXCEPTION 'While PENDING_VENUE_APPROVAL only the participating Player Creator may have a Participant row';
            END IF;
        ELSIF t.status NOT IN ('WAITING_FOR_PLAYERS','CONFIRMED') OR v_now >= t.start_at THEN
            RAISE EXCEPTION 'Users may join only WAITING_FOR_PLAYERS/CONFIRMED before startAt';
        END IF;
        v_occupied := tournament.capacity_occupied_count(t.id);
        IF v_occupied >= t.capacity THEN
            RAISE EXCEPTION 'Tournament participant capacity is full, including BAN-only reserved slots';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.tournament_id IS DISTINCT FROM OLD.tournament_id
       OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.joined_at IS DISTINCT FROM OLD.joined_at THEN
        RAISE EXCEPTION 'Tournament Participant identity/join timestamp is immutable';
    END IF;
    IF OLD.left_at IS NOT NULL AND NEW.left_at IS DISTINCT FROM OLD.left_at THEN
        RAISE EXCEPTION 'left_at is immutable once recorded';
    END IF;
    IF OLD.removed_at IS NOT NULL AND NEW.removed_at IS DISTINCT FROM OLD.removed_at THEN
        RAISE EXCEPTION 'removed_at is immutable once recorded';
    END IF;
    IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
        -- v1.1.17 cause precedence: account deletion permanently defeats BAN-only
        -- restoration eligibility. Permit exactly one reason-only reclassification
        -- while retaining the existing INELIGIBLE status and its status timestamp.
        IF OLD.status='INELIGIBLE' AND OLD.ineligible_reason='BAN' AND u.anonymised_at IS NOT NULL
           AND t.status IN ('PENDING_VENUE_APPROVAL','WAITING_FOR_PLAYERS','CONFIRMED','ACTIVE') THEN
            IF NEW.status_changed_at IS DISTINCT FROM OLD.status_changed_at
               OR NEW.left_at IS DISTINCT FROM OLD.left_at
               OR NEW.removed_at IS DISTINCT FROM OLD.removed_at THEN
                RAISE EXCEPTION 'BAN to ACCOUNT_DELETED cause reclassification may not mutate other participant lifecycle facts';
            END IF;
            NEW.ineligible_reason := 'ACCOUNT_DELETED';
            RETURN NEW;
        END IF;
        IF NEW.status_changed_at IS DISTINCT FROM OLD.status_changed_at
           OR NEW.left_at IS DISTINCT FROM OLD.left_at OR NEW.removed_at IS DISTINCT FROM OLD.removed_at
           OR NEW.ineligible_reason IS DISTINCT FROM OLD.ineligible_reason THEN
            RAISE EXCEPTION 'Participant lifecycle facts change only with a status transition except BAN to ACCOUNT_DELETED cause precedence';
        END IF;
        RETURN NEW;
    END IF;
    IF t.status IN ('COMPLETED','REJECTED','CANCELLED') THEN
        RAISE EXCEPTION 'Participant state cannot change after Tournament terminal state';
    END IF;

    NEW.status_changed_at := v_now;
    IF NEW.status = 'JOINED' THEN
        IF NOT v_boundary_restore AND (v_now >= t.start_at OR NOT (
               t.status IN ('WAITING_FOR_PLAYERS','CONFIRMED')
               OR (t.status='PENDING_VENUE_APPROVAL' AND t.host_type='PLAYER' AND t.creator_participates AND NEW.user_id=t.creator_user_id)
           )) THEN
            RAISE EXCEPTION 'Participant may return/join only before startAt in an eligible Tournament lifecycle state';
        END IF;
        IF NOT u.phone_verified OR u.anonymised_at IS NOT NULL OR v_banned THEN
            RAISE EXCEPTION 'JOINED participant must be Account-Verified, active and not banned';
        END IF;
        NEW.ineligible_reason := NULL;
        v_occupied := tournament.capacity_occupied_count(t.id);
        -- BAN-only restoration consumes its already-reserved capacity slot, so it must
        -- not be rejected merely because all slots are occupied. Other returns still
        -- require a free slot.
        IF NOT (OLD.status='JOINED' OR (OLD.status='INELIGIBLE' AND OLD.ineligible_reason='BAN'))
           AND v_occupied >= t.capacity THEN
            RAISE EXCEPTION 'Tournament participant capacity is full, including BAN-only reserved slots';
        END IF;
    ELSIF NEW.status = 'LEFT' THEN
        IF v_now >= t.start_at THEN
            RAISE EXCEPTION 'Participant may Leave only before startAt';
        END IF;
        IF NEW.left_at IS NULL THEN NEW.left_at := NEW.status_changed_at; END IF;
    ELSIF NEW.status = 'REMOVED' THEN
        IF v_now >= t.start_at THEN
            RAISE EXCEPTION 'Organizer may Remove a Participant only before startAt';
        END IF;
        IF NEW.removed_at IS NULL THEN NEW.removed_at := NEW.status_changed_at; END IF;
    ELSIF NEW.status = 'INELIGIBLE' THEN
        -- ACCOUNT_DELETED has precedence over BAN because a deleted/anonymised
        -- account can never become JOINED again when a Ban later expires/lifts.
        IF u.anonymised_at IS NOT NULL THEN
            NEW.ineligible_reason := 'ACCOUNT_DELETED';
        ELSIF v_banned THEN
            NEW.ineligible_reason := 'BAN';
        ELSE
            RAISE EXCEPTION 'INELIGIBLE is valid only for BAN or ACCOUNT_DELETED';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION inventory.guard_resource_reservation_cross_class()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_conflict boolean;
BEGIN
    IF NOT NEW.active_flag THEN
        RETURN NEW;
    END IF;

    -- v1.1.27: this cross-class check re-reads committed rows after the Resource lock. That is race-safe under
    -- READ COMMITTED (fresh snapshot per statement) and SERIALIZABLE (SSI), but not under REPEATABLE READ.
    IF current_setting('transaction_isolation') = 'repeatable read' THEN
        RAISE EXCEPTION 'Inventory writes must not run under REPEATABLE READ; use READ COMMITTED';
    END IF;

    -- Serialize all cross-class decisions for the Resource.
    PERFORM 1 FROM resource.resource WHERE id = NEW.resource_id FOR UPDATE;

    IF NEW.reservation_type = 'MAINTENANCE' THEN
        -- New Maintenance may overlap Maintenance only; it may not overlap Closure or commitments.
        SELECT EXISTS (
            SELECT 1
              FROM inventory.resource_reservation r
             WHERE r.resource_id = NEW.resource_id
               AND r.id IS DISTINCT FROM NEW.id
               AND r.active_flag
               AND r.planned_range && NEW.planned_range
               AND r.reservation_type <> 'MAINTENANCE'
        ) INTO v_conflict;
    ELSIF NEW.reservation_type = 'CLOSURE' THEN
        -- Closure may overlap existing Maintenance, but never commitments or another active Closure.
        SELECT EXISTS (
            SELECT 1
              FROM inventory.resource_reservation r
             WHERE r.resource_id = NEW.resource_id
               AND r.id IS DISTINCT FROM NEW.id
               AND r.active_flag
               AND r.planned_range && NEW.planned_range
               AND r.reservation_type <> 'MAINTENANCE'
        ) INTO v_conflict;
    ELSE
        -- Booking / Late Confirm / Tournament commitments may overlap nothing active, including Maintenance.
        SELECT EXISTS (
            SELECT 1
              FROM inventory.resource_reservation r
             WHERE r.resource_id = NEW.resource_id
               AND r.id IS DISTINCT FROM NEW.id
               AND r.active_flag
               AND r.planned_range && NEW.planned_range
        ) INTO v_conflict;
    END IF;

    IF v_conflict THEN
        RAISE EXCEPTION 'resource reservation conflict for resource % in interval %', NEW.resource_id, NEW.planned_range;
    END IF;

    RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION review.report_review(p_review uuid, p_reporter uuid, p_reason text, p_details text, p_correlation uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE r review.review%ROWTYPE; v_now timestamptz; v_id uuid:=gen_random_uuid(); tok uuid; aid uuid:=gen_random_uuid();
BEGIN
 IF p_reporter IS NULL OR p_correlation IS NULL OR NULLIF(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'Reporter, correlation and reason are required'; END IF;
 SELECT * INTO r FROM review.review WHERE id=p_review;
 IF NOT FOUND OR r.status<>'ACTIVE' OR r.author_deleted_at IS NOT NULL THEN RAISE EXCEPTION 'Only an ACTIVE public Review can be reported'; END IF;
 v_now:=review.customer_command(p_reporter,r.venue_id);
 -- v1.1.27: a Review of a deleted/anonymised account is no longer public (PCR-002).
 IF EXISTS(SELECT 1 FROM iam.user_account ua WHERE ua.id=r.user_id AND ua.anonymised_at IS NOT NULL) THEN
   RAISE EXCEPTION 'Only an ACTIVE public Review can be reported';
 END IF;
 -- v1.1.27: one unresolved report per reporter per Review (duplicate reports rejected).
 PERFORM pg_advisory_xact_lock(hashtextextended('e7gz.review_report:'||p_review::text||':'||p_reporter::text,0));
 IF EXISTS(SELECT 1 FROM review.review_report x WHERE x.review_id=p_review AND x.reporter_user_id=p_reporter AND x.resolved_at IS NULL) THEN
   RAISE EXCEPTION 'This User already has an unresolved report for this Review';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM iam.user_account u WHERE u.id=p_reporter AND u.anonymised_at IS NULL) THEN RAISE EXCEPTION 'Signed-in active Customer required'; END IF;
 tok:=technical.enter_write('review.review_report',v_id::text);
 INSERT INTO review.review_report(id,review_id,reporter_user_id,reason,details,created_at,correlation_id)
 VALUES(v_id,p_review,p_reporter,btrim(p_reason),NULLIF(btrim(p_details),''),v_now,p_correlation);
 PERFORM technical.leave_write(tok);
 INSERT INTO audit.audit_event(id,occurred_at,actor_type,actor_id,action,subject_type,subject_id,reason,correlation_id,payload,context_user_id,context_venue_id)
 VALUES(aid,v_now,'CUSTOMER',p_reporter,'REVIEW_REPORTED','REVIEW',p_review,btrim(p_reason),p_correlation,jsonb_build_object('reviewReportId',v_id),p_reporter,r.venue_id);
 RETURN v_id;
END;
$function$;

-- ---------- F13 Player-hosted Tournament approval (FR-TRN-10) ----------
CREATE OR REPLACE FUNCTION tournament.prepare_tournament_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    v_now timestamptz;
    v_marketplace text;
    v_account text;
    v_phone_verified boolean;
    v_anonymised_at timestamptz;
    v_vp_status text;
    v_last_terminal timestamptz;
BEGIN
    v_now := tournament.require_command_scope(NEW.id, NEW.venue_id, NULL, NEW.creator_user_id);
    PERFORM tournament.mark_created_in_command(NEW.id);
    NEW.created_at := v_now;
    NEW.end_at := NEW.start_at + make_interval(mins => NEW.nominal_minutes);
    NEW.checkpoint_at := NEW.start_at - interval '1 hour';
    NEW.version := 0;

    IF NEW.host_type = 'PLAYER' THEN
        NEW.status := 'PENDING_VENUE_APPROVAL';
        NEW.approval_expires_at := LEAST(NEW.created_at + interval '10 minutes', NEW.checkpoint_at);  -- v1.1.27: FR-TRN-10 / Product §37.2
    ELSIF NEW.host_type = 'VENUE' THEN
        NEW.status := 'WAITING_FOR_PLAYERS';
        NEW.approval_expires_at := NULL;
    END IF;

    SELECT v.marketplace_status INTO v_marketplace
      FROM venue.venue v WHERE v.id = NEW.venue_id FOR UPDATE;
    IF NOT FOUND OR v_marketplace <> 'ACTIVE' THEN
        RAISE EXCEPTION 'New Tournament creation requires Venue Marketplace ACTIVE';
    END IF;

    SELECT va.account_status INTO v_account
      FROM iam.venue_account va WHERE va.venue_id = NEW.venue_id;
    IF v_account IS DISTINCT FROM 'ENABLED' THEN
        RAISE EXCEPTION 'New Tournament creation requires Venue Account ENABLED';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM venue.venue_activity a WHERE a.venue_id = NEW.venue_id AND a.activity = NEW.activity) THEN
        RAISE EXCEPTION 'Tournament activity is not configured for the selected Venue';
    END IF;
    IF EXISTS (SELECT 1 FROM venue.venue_selling_block b WHERE b.venue_id = NEW.venue_id AND b.active) THEN
        RAISE EXCEPTION 'New Tournament creation is blocked by a Venue Operational Selling Block';
    END IF;

    -- v1.1.27: Product §36.3 creation cutoff requestTime <= startAt - 2 hours for BOTH host types.
    IF NEW.created_at > NEW.start_at - interval '2 hours' THEN
        RAISE EXCEPTION 'Tournament creation cutoff is startAt - 2 hours';
    END IF;
    -- v1.1.27: Tournament Creation Fee snapshot must equal the configured fee effective at creation (Product §5.3, FR-ADM-10).
    IF NEW.creation_fee_snapshot IS DISTINCT FROM config.effective_numeric('tournament.creation_fee', NEW.created_at) THEN
        RAISE EXCEPTION 'Tournament creation_fee_snapshot must equal the configured Tournament Creation Fee at creation';
    END IF;

    IF NEW.host_type = 'PLAYER' THEN
        SELECT u.phone_verified, u.anonymised_at
          INTO v_phone_verified, v_anonymised_at
          FROM iam.user_account u
         WHERE u.id = NEW.creator_user_id
         FOR UPDATE;
        IF NOT FOUND OR NOT v_phone_verified OR v_anonymised_at IS NOT NULL THEN
            RAISE EXCEPTION 'Player-hosted Tournament creator must be an Account-Verified active User';
        END IF;
        SELECT p.vp_operational_status INTO v_vp_status
          FROM trust.trust_projection p WHERE p.user_id = NEW.creator_user_id;
        IF v_vp_status IS DISTINCT FROM 'VERIFIED' THEN
            RAISE EXCEPTION 'Only operational VERIFIED may create a Player-hosted Tournament';
        END IF;
        IF EXISTS (
            SELECT 1 FROM trust.ban_instance b
             WHERE b.user_id = NEW.creator_user_id
               AND b.status = 'ACTIVE'
               AND b.activated_at <= NEW.created_at
               AND b.ends_at > NEW.created_at
        ) THEN
            RAISE EXCEPTION 'Banned User may not create a Tournament';
        END IF;

        SELECT MAX(h.occurred_at) INTO v_last_terminal
          FROM tournament.tournament t0
          JOIN tournament.tournament_history h ON h.tournament_id = t0.id
         WHERE t0.host_type = 'PLAYER'
           AND t0.creator_user_id = NEW.creator_user_id
           AND t0.venue_id = NEW.venue_id
           AND t0.start_at = NEW.start_at
           AND t0.end_at = NEW.end_at
           AND (   (t0.status = 'REJECTED' AND h.to_status = 'REJECTED')
                OR (t0.status = 'CANCELLED' AND h.to_status = 'CANCELLED'
                    AND h.terminal_reason = 'VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME'));  -- v1.1.27: Product §37.3 REJECTED or EXPIRED
        IF v_last_terminal IS NOT NULL AND NEW.created_at < v_last_terminal + interval '5 minutes' THEN
            RAISE EXCEPTION 'Creator must wait 5 minutes before re-requesting the same Venue/time interval';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.guard_tournament_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    v_now timestamptz;
    v_count integer;
BEGIN
    v_now := tournament.require_command_scope(OLD.id, OLD.venue_id);
    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.venue_id IS DISTINCT FROM OLD.venue_id
       OR NEW.host_type IS DISTINCT FROM OLD.host_type
       OR NEW.creator_user_id IS DISTINCT FROM OLD.creator_user_id
       OR NEW.creator_participates IS DISTINCT FROM OLD.creator_participates
       OR NEW.activity IS DISTINCT FROM OLD.activity
       OR NEW.play_mode IS DISTINCT FROM OLD.play_mode
       OR NEW.capacity IS DISTINCT FROM OLD.capacity
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.start_at IS DISTINCT FROM OLD.start_at
       OR NEW.end_at IS DISTINCT FROM OLD.end_at
       OR NEW.nominal_minutes IS DISTINCT FROM OLD.nominal_minutes
       OR NEW.checkpoint_at IS DISTINCT FROM OLD.checkpoint_at
       OR NEW.approval_expires_at IS DISTINCT FROM OLD.approval_expires_at
       OR NEW.visibility IS DISTINCT FROM OLD.visibility
       OR NEW.invite_code IS DISTINCT FROM OLD.invite_code
       OR NEW.venue_cost_total IS DISTINCT FROM OLD.venue_cost_total
       OR NEW.creation_fee_snapshot IS DISTINCT FROM OLD.creation_fee_snapshot
       OR NEW.entry_fee IS DISTINCT FROM OLD.entry_fee
       OR NEW.prize IS DISTINCT FROM OLD.prize
       OR NEW.business_date IS DISTINCT FROM OLD.business_date
       OR NEW.operating_session_id IS DISTINCT FROM OLD.operating_session_id THEN
        RAISE EXCEPTION 'Tournament creation/commercial/session snapshots are immutable';
    END IF;

    IF OLD.status IN ('COMPLETED','REJECTED','CANCELLED') THEN
        RAISE EXCEPTION 'Terminal Tournament state is immutable';
    END IF;
    IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
        RAISE EXCEPTION 'Tournament UPDATE must be a semantic state transition';
    END IF;
    IF NEW.version <> OLD.version + 1 THEN
        RAISE EXCEPTION 'Tournament state transition must increment version exactly once';
    END IF;

    IF OLD.status = 'PENDING_VENUE_APPROVAL' AND NEW.status NOT IN ('WAITING_FOR_PLAYERS','REJECTED','CANCELLED') THEN
        RAISE EXCEPTION 'Invalid Tournament transition % -> %', OLD.status, NEW.status;
    ELSIF OLD.status = 'WAITING_FOR_PLAYERS' AND NEW.status NOT IN ('CONFIRMED','CANCELLED') THEN
        RAISE EXCEPTION 'Invalid Tournament transition % -> %', OLD.status, NEW.status;
    ELSIF OLD.status = 'CONFIRMED' AND NEW.status NOT IN ('ACTIVE','CANCELLED') THEN
        RAISE EXCEPTION 'Invalid Tournament transition % -> %', OLD.status, NEW.status;
    ELSIF OLD.status = 'ACTIVE' AND NEW.status NOT IN ('COMPLETED','CANCELLED') THEN
        RAISE EXCEPTION 'Invalid Tournament transition % -> %', OLD.status, NEW.status;
    END IF;

    IF OLD.status = 'PENDING_VENUE_APPROVAL' AND NEW.status = 'WAITING_FOR_PLAYERS' THEN
        IF v_now >= OLD.approval_expires_at THEN
            RAISE EXCEPTION 'Venue approval deadline is owned by expiry at now >= approvalExpiresAt';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM iam.venue_account va WHERE va.venue_id = OLD.venue_id AND va.account_status = 'ENABLED') THEN
            RAISE EXCEPTION 'Venue Accept requires Venue Account ENABLED';
        END IF;
        PERFORM tournament.assert_resources_operational(OLD.id, 'TOURNAMENT_APPROVAL_HOLD');
    ELSIF OLD.status = 'PENDING_VENUE_APPROVAL' AND NEW.status = 'REJECTED' THEN
        -- v1.1.27: FR-TRN-10 — Venue Reject -> REJECTED with VENUE_REJECTED_TOURNAMENT, only before approvalExpiresAt.
        IF NEW.terminal_reason IS DISTINCT FROM 'VENUE_REJECTED_TOURNAMENT' THEN
            RAISE EXCEPTION 'Tournament request rejection carries VENUE_REJECTED_TOURNAMENT';
        END IF;
        IF v_now >= OLD.approval_expires_at THEN
            RAISE EXCEPTION 'Venue approval deadline is owned by expiry at now >= approvalExpiresAt';
        END IF;
    ELSIF OLD.status = 'PENDING_VENUE_APPROVAL' AND NEW.status = 'CANCELLED' THEN
        -- v1.1.27: FR-TRN-10 — no Venue response -> CANCELLED with VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME at/after approvalExpiresAt.
        IF NEW.terminal_reason = 'VENUE_REJECTED_TOURNAMENT' THEN
            RAISE EXCEPTION 'VENUE_REJECTED_TOURNAMENT is the REJECTED reason, not a cancellation reason';
        END IF;
        IF NEW.terminal_reason = 'VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME' AND v_now < OLD.approval_expires_at THEN
            RAISE EXCEPTION 'VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME is valid only at/after approvalExpiresAt';
        END IF;
        IF NEW.terminal_reason = 'CREATOR_CANCELLED' AND v_now >= OLD.checkpoint_at THEN
            RAISE EXCEPTION 'Creator may cancel only before the checkpoint';
        END IF;
    ELSIF OLD.status = 'WAITING_FOR_PLAYERS' AND NEW.status = 'CONFIRMED' THEN
        IF v_now < OLD.checkpoint_at THEN
            RAISE EXCEPTION 'Tournament checkpoint may not confirm before checkpointAt';
        END IF;
        v_count := tournament.active_participant_count(OLD.id, OLD.checkpoint_at);
        IF v_count < 8 THEN
            RAISE EXCEPTION 'Tournament cannot confirm with fewer than 8 Active Participants';
        END IF;
        PERFORM tournament.assert_resources_operational(OLD.id, 'TOURNAMENT_HOLD');
    ELSIF OLD.status = 'WAITING_FOR_PLAYERS' AND NEW.status = 'CANCELLED' THEN
        IF NEW.terminal_reason = 'MINIMUM_PARTICIPANTS_NOT_REACHED' THEN
            IF v_now < OLD.checkpoint_at OR tournament.active_participant_count(OLD.id, OLD.checkpoint_at) >= 8 THEN
                RAISE EXCEPTION 'MINIMUM_PARTICIPANTS_NOT_REACHED requires checkpoint ownership and fewer than 8 Active Participants';
            END IF;
        ELSIF NEW.terminal_reason = 'CREATOR_CANCELLED' AND v_now >= OLD.checkpoint_at THEN
            RAISE EXCEPTION 'Creator may cancel only before the checkpoint';
        END IF;
    ELSIF OLD.status = 'CONFIRMED' AND NEW.status = 'ACTIVE' THEN
        IF v_now < OLD.start_at THEN
            RAISE EXCEPTION 'Tournament may not start before startAt';
        END IF;
        PERFORM tournament.assert_resources_operational(OLD.id, 'TOURNAMENT_HOLD');
    ELSIF OLD.status = 'ACTIVE' AND NEW.status = 'COMPLETED' THEN
        IF v_now < OLD.end_at THEN
            RAISE EXCEPTION 'Tournament may not complete before endAt';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.guard_tournament_due_boundary()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    v_now timestamptz;
    v_expected text;
BEGIN
    v_now := tournament.require_command_scope(OLD.id, OLD.venue_id);
    IF OLD.status='PENDING_VENUE_APPROVAL' AND v_now >= OLD.approval_expires_at THEN
        v_expected := tournament.highest_current_cancellation_reason(OLD.id,'PENDING_VENUE_APPROVAL',OLD.approval_expires_at);
        IF v_expected IS NULL THEN
            -- v1.1.27: FR-TRN-10 — normal approval timeout is CANCELLED / VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME.
            IF NEW.status <> 'CANCELLED' OR NEW.terminal_reason IS DISTINCT FROM 'VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME' THEN
                RAISE EXCEPTION 'Approval deadline owns the next transition; expected CANCELLED/VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME';
            END IF;
        ELSIF NEW.status <> 'CANCELLED' OR NEW.terminal_reason IS DISTINCT FROM v_expected THEN
            RAISE EXCEPTION 'A higher-priority condition at approval expiry requires CANCELLED/%', v_expected;
        END IF;

    ELSIF OLD.status='WAITING_FOR_PLAYERS' AND v_now >= OLD.checkpoint_at THEN
        -- A BAN that already expired at checkpoint must be restored first; a later worker cannot make
        -- the participant absent from the exact checkpoint count.
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_participant p
             WHERE p.tournament_id=OLD.id AND p.status='INELIGIBLE' AND p.ineligible_reason='BAN'
               AND NOT EXISTS (
                   SELECT 1 FROM trust.ban_instance b
                    WHERE b.user_id=p.user_id AND b.activated_at <= OLD.checkpoint_at AND b.ends_at > OLD.checkpoint_at
               )
        ) THEN
            RAISE EXCEPTION 'Restore BAN-only Participants whose Ban expired by checkpointAt before resolving the checkpoint';
        END IF;
        v_expected := tournament.highest_current_cancellation_reason(OLD.id,'WAITING_FOR_PLAYERS',OLD.checkpoint_at);
        IF v_expected IS NULL THEN
            IF NEW.status <> 'CONFIRMED' OR NEW.terminal_reason IS NOT NULL THEN
                RAISE EXCEPTION 'Checkpoint owns the next transition; expected CONFIRMED';
            END IF;
        ELSE
            IF NEW.status <> 'CANCELLED' OR NEW.terminal_reason IS DISTINCT FROM v_expected THEN
                RAISE EXCEPTION 'Checkpoint owns the next transition; expected CANCELLED/%', v_expected;
            END IF;
        END IF;

    ELSIF OLD.status='CONFIRMED' AND v_now >= OLD.start_at THEN
        IF EXISTS (
            SELECT 1 FROM tournament.tournament_participant p
             WHERE p.tournament_id=OLD.id AND p.status='INELIGIBLE' AND p.ineligible_reason='BAN'
               AND NOT EXISTS (
                   SELECT 1 FROM trust.ban_instance b
                    WHERE b.user_id=p.user_id AND b.activated_at <= OLD.start_at AND b.ends_at >= OLD.start_at  -- v1.1.27: expiry/lift at startAt is not a restoration (Product §37.11)
               )
        ) THEN
            RAISE EXCEPTION 'Restore BAN-only Participants whose Ban expired by startAt before resolving Tournament start';
        END IF;
        v_expected := tournament.highest_current_cancellation_reason(OLD.id,'CONFIRMED',OLD.start_at);
        IF v_expected IS NULL THEN
            IF NEW.status <> 'ACTIVE' OR NEW.terminal_reason IS NOT NULL THEN
                RAISE EXCEPTION 'startAt owns the next transition; expected ACTIVE';
            END IF;
        ELSE
            IF NEW.status <> 'CANCELLED' OR NEW.terminal_reason IS DISTINCT FROM v_expected THEN
                RAISE EXCEPTION 'startAt owns the next transition; expected CANCELLED/%', v_expected;
            END IF;
        END IF;

    ELSIF OLD.status='ACTIVE' AND v_now >= OLD.end_at THEN
        IF NEW.status <> 'COMPLETED' OR NEW.terminal_reason IS NOT NULL THEN
            RAISE EXCEPTION 'endAt owns the next transition; expected COMPLETED';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.assert_tournament_history_chain(p_tournament_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    t tournament.tournament%ROWTYPE;
    h record;
    a audit.audit_event%ROWTYPE;
    v_prev text := NULL;
    v_expected text;
    v_first boolean := true;
BEGIN
    SELECT * INTO t FROM tournament.tournament WHERE id = p_tournament_id;
    IF NOT FOUND THEN RETURN; END IF;

    FOR h IN SELECT * FROM tournament.tournament_history WHERE tournament_id=t.id ORDER BY sequence LOOP
        IF v_first THEN
            IF h.sequence <> 1 OR h.from_status IS NOT NULL OR h.occurred_at IS DISTINCT FROM t.created_at THEN
                RAISE EXCEPTION 'Tournament first history row must be sequence 1, from_status NULL and occur at created_at';
            END IF;
            IF (t.host_type='PLAYER' AND h.to_status <> 'PENDING_VENUE_APPROVAL')
               OR (t.host_type='VENUE' AND h.to_status <> 'WAITING_FOR_PLAYERS') THEN
                RAISE EXCEPTION 'Tournament first history state does not match host type';
            END IF;
            v_first := false;
        ELSE
            IF h.from_status IS DISTINCT FROM v_prev THEN
                RAISE EXCEPTION 'Tournament history chain is not contiguous at sequence %', h.sequence;
            END IF;
        END IF;

        SELECT * INTO a FROM audit.audit_event ae
         WHERE ae.subject_type='TOURNAMENT' AND ae.subject_id=t.id
           AND ae.action='TOURNAMENT_STATUS_TRANSITION'
           AND ae.occurred_at=h.occurred_at
           AND ae.actor_type=h.actor_type
           AND ae.actor_id IS NOT DISTINCT FROM h.actor_id
           AND ae.correlation_id=h.correlation_id
         LIMIT 1;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Tournament history sequence % requires matching audit_event', h.sequence;
        END IF;

        IF h.actor_type='CUSTOMER' AND h.actor_id IS DISTINCT FROM t.creator_user_id THEN
            RAISE EXCEPTION 'Tournament CUSTOMER state actor must be the Player Creator';
        ELSIF h.actor_type='VENUE' AND NOT EXISTS (
            SELECT 1 FROM iam.venue_account va WHERE va.id=h.actor_id AND va.venue_id=t.venue_id
        ) THEN
            RAISE EXCEPTION 'Tournament VENUE actor must belong to the Tournament Venue';
        ELSIF h.actor_type='ADMIN' AND NOT EXISTS (SELECT 1 FROM iam.admin_account ad WHERE ad.id=h.actor_id) THEN
            RAISE EXCEPTION 'Tournament ADMIN actor does not exist';
        END IF;

        IF h.from_status IS NULL THEN
            IF t.host_type='PLAYER' AND (h.actor_type<>'CUSTOMER' OR h.actor_id IS DISTINCT FROM t.creator_user_id) THEN
                RAISE EXCEPTION 'Player-hosted Tournament creation history requires Creator actor';
            ELSIF t.host_type='VENUE' AND h.actor_type<>'VENUE' THEN
                RAISE EXCEPTION 'Venue-hosted Tournament creation history requires Venue actor';
            END IF;
        ELSIF h.from_status='PENDING_VENUE_APPROVAL' AND h.to_status='WAITING_FOR_PLAYERS' THEN
            IF h.actor_type<>'VENUE' OR h.terminal_reason IS NOT NULL OR h.occurred_at >= t.approval_expires_at THEN
                RAISE EXCEPTION 'Venue Accept transition is invalid';
            END IF;
        ELSIF h.from_status='PENDING_VENUE_APPROVAL' AND h.to_status='REJECTED' THEN
            -- v1.1.27: FR-TRN-10 — only the Venue rejects, before expiry, with VENUE_REJECTED_TOURNAMENT.
            IF h.terminal_reason IS DISTINCT FROM 'VENUE_REJECTED_TOURNAMENT' OR h.actor_type<>'VENUE' OR h.occurred_at >= t.approval_expires_at THEN
                RAISE EXCEPTION 'Rejection requires the Venue before approval expiry with VENUE_REJECTED_TOURNAMENT';
            END IF;
            v_expected := tournament.highest_current_cancellation_reason(t.id,h.from_status,h.occurred_at);
            IF v_expected IS NOT NULL THEN
                RAISE EXCEPTION 'Rejection cannot bypass a higher-priority cancellation condition: %', v_expected;
            END IF;
        ELSIF h.from_status='PENDING_VENUE_APPROVAL' AND h.to_status='CANCELLED' THEN
            IF h.terminal_reason='CREATOR_CANCELLED' THEN
                IF h.actor_type<>'CUSTOMER' OR h.occurred_at >= t.checkpoint_at THEN RAISE EXCEPTION 'Creator cancellation is invalid'; END IF;
            ELSIF h.terminal_reason IN ('VENUE_ACCOUNT_DISABLED','CREATOR_VERIFIED_STATUS_REVOKED','EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED') THEN
                IF h.actor_type<>'SYSTEM' THEN RAISE EXCEPTION 'System Tournament cascade requires SYSTEM actor'; END IF;
            ELSIF h.terminal_reason='ADMIN_CANCELLED' THEN
                IF h.actor_type<>'ADMIN' THEN RAISE EXCEPTION 'Admin cancellation requires ADMIN actor'; END IF;
            ELSIF h.terminal_reason='VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME' THEN  -- v1.1.27: FR-TRN-10 timeout
                IF h.actor_type<>'SYSTEM' OR h.occurred_at < t.approval_expires_at THEN RAISE EXCEPTION 'Approval timeout cancellation is invalid'; END IF;
            ELSE RAISE EXCEPTION 'Invalid PENDING Tournament cancellation reason %', h.terminal_reason; END IF;
        ELSIF h.from_status='WAITING_FOR_PLAYERS' AND h.to_status='CONFIRMED' THEN
            IF h.actor_type<>'SYSTEM' OR h.terminal_reason IS NOT NULL OR h.occurred_at < t.checkpoint_at THEN
                RAISE EXCEPTION 'Tournament checkpoint confirmation transition is invalid';
            END IF;
        ELSIF h.from_status='WAITING_FOR_PLAYERS' AND h.to_status='CANCELLED' THEN
            IF h.terminal_reason='MINIMUM_PARTICIPANTS_NOT_REACHED' THEN
                IF h.actor_type<>'SYSTEM' OR h.occurred_at < t.checkpoint_at THEN RAISE EXCEPTION 'Minimum-participant cancellation is invalid'; END IF;
            ELSIF h.terminal_reason='CREATOR_CANCELLED' THEN
                IF h.actor_type<>'CUSTOMER' OR h.occurred_at >= t.checkpoint_at THEN RAISE EXCEPTION 'Creator cancellation is invalid'; END IF;
            ELSIF h.terminal_reason='VENUE_CANCELLED' THEN
                IF h.actor_type<>'VENUE' THEN RAISE EXCEPTION 'Venue cancellation requires VENUE actor'; END IF;
            ELSIF h.terminal_reason IN ('CREATOR_VERIFIED_STATUS_REVOKED','EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED') THEN
                IF h.actor_type<>'SYSTEM' THEN RAISE EXCEPTION 'System Tournament cascade requires SYSTEM actor'; END IF;
            ELSIF h.terminal_reason='ADMIN_CANCELLED' THEN
                IF h.actor_type<>'ADMIN' THEN RAISE EXCEPTION 'Admin cancellation requires ADMIN actor'; END IF;
            ELSE RAISE EXCEPTION 'Invalid WAITING Tournament cancellation reason %', h.terminal_reason; END IF;
        ELSIF h.from_status='CONFIRMED' AND h.to_status='ACTIVE' THEN
            IF h.actor_type<>'SYSTEM' OR h.terminal_reason IS NOT NULL OR h.occurred_at < t.start_at THEN
                RAISE EXCEPTION 'Tournament start transition is invalid';
            END IF;
        ELSIF h.from_status='CONFIRMED' AND h.to_status='CANCELLED' THEN
            IF h.terminal_reason='VENUE_CANCELLED' THEN
                IF h.actor_type<>'VENUE' OR NOT a.owner_password_used OR a.owner_password_outcome<>'SUCCESS' THEN
                    RAISE EXCEPTION 'Venue cancellation of CONFIRMED Tournament requires successful Owner Password audit';
                END IF;
            ELSIF h.terminal_reason IN ('EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED') THEN
                IF h.actor_type<>'SYSTEM' THEN RAISE EXCEPTION 'Operational cancellation requires SYSTEM actor'; END IF;
            ELSIF h.terminal_reason='ADMIN_CANCELLED' THEN
                IF h.actor_type<>'ADMIN' THEN RAISE EXCEPTION 'Admin cancellation requires ADMIN actor'; END IF;
            ELSE RAISE EXCEPTION 'Invalid CONFIRMED Tournament cancellation reason %', h.terminal_reason; END IF;
        ELSIF h.from_status='ACTIVE' AND h.to_status='COMPLETED' THEN
            IF h.actor_type<>'SYSTEM' OR h.terminal_reason IS NOT NULL OR h.occurred_at < t.end_at THEN
                RAISE EXCEPTION 'Tournament completion transition is invalid';
            END IF;
        ELSIF h.from_status='ACTIVE' AND h.to_status='CANCELLED' THEN
            IF h.terminal_reason IN ('EMERGENCY_CLOSURE','RESOURCE_EMERGENCY_OUTAGE','RESOURCE_OWNER_REVIEW_REQUIRED') THEN
                IF h.actor_type<>'SYSTEM' THEN RAISE EXCEPTION 'Operational ACTIVE cancellation requires SYSTEM actor'; END IF;
            ELSIF h.terminal_reason='TOURNAMENT_OPERATIONAL_TERMINATION' THEN
                IF h.actor_type<>'VENUE' OR NOT a.owner_password_used OR a.owner_password_outcome<>'SUCCESS'
                   OR NULLIF(BTRIM(a.reason),'') IS NULL THEN
                    RAISE EXCEPTION 'Tournament Operational Termination requires Venue actor, Owner Password and mandatory reason';
                END IF;
            ELSIF h.terminal_reason='ADMIN_CANCELLED' THEN
                IF h.actor_type<>'ADMIN' THEN RAISE EXCEPTION 'ACTIVE Admin support cancellation requires ADMIN actor'; END IF;
            ELSE RAISE EXCEPTION 'Invalid ACTIVE Tournament cancellation reason %', h.terminal_reason; END IF;
        ELSE
            RAISE EXCEPTION 'Invalid Tournament state transition % -> %', h.from_status, h.to_status;
        END IF;

        IF h.to_status='CANCELLED' THEN
            v_expected := tournament.highest_current_cancellation_reason(t.id,h.from_status,h.occurred_at);
            IF v_expected IS NOT NULL AND h.terminal_reason IS DISTINCT FROM v_expected THEN
                RAISE EXCEPTION 'Tournament terminal reason % violates frozen priority; expected %', h.terminal_reason, v_expected;
            END IF;
        END IF;
        v_prev := h.to_status;
    END LOOP;

    IF v_first THEN RAISE EXCEPTION 'Tournament requires append-only state history'; END IF;
    IF v_prev IS DISTINCT FROM t.status THEN RAISE EXCEPTION 'Tournament current status does not match latest history state'; END IF;
    SELECT hist.terminal_reason INTO v_expected
      FROM tournament.tournament_history AS hist
     WHERE hist.tournament_id = t.id
     ORDER BY hist.sequence DESC
     LIMIT 1;
    IF v_expected IS DISTINCT FROM t.terminal_reason THEN
        RAISE EXCEPTION 'Tournament terminal_reason does not match latest history transition';
    END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION tournament.assert_terminal_reason_provenance()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_expected text;
    t tournament.tournament%ROWTYPE;
BEGIN
    IF NEW.to_status NOT IN ('CANCELLED','REJECTED') THEN RETURN NULL; END IF;
    SELECT * INTO t FROM tournament.tournament WHERE id=NEW.tournament_id;
    v_expected := tournament.highest_current_cancellation_reason(NEW.tournament_id,NEW.from_status,NEW.occurred_at);

    IF NEW.to_status='REJECTED' THEN
        IF NEW.terminal_reason IS DISTINCT FROM 'VENUE_REJECTED_TOURNAMENT' OR v_expected IS NOT NULL THEN
            RAISE EXCEPTION 'Request rejection carries VENUE_REJECTED_TOURNAMENT and cannot override a higher-priority condition';
        END IF;
        RETURN NULL;
    END IF;

    IF NEW.terminal_reason IN ('RESOURCE_OWNER_REVIEW_REQUIRED','RESOURCE_EMERGENCY_OUTAGE','EMERGENCY_CLOSURE','VENUE_ACCOUNT_DISABLED','MINIMUM_PARTICIPANTS_NOT_REACHED','CREATOR_VERIFIED_STATUS_REVOKED') THEN
        IF v_expected IS NULL OR v_expected IS DISTINCT FROM NEW.terminal_reason THEN
            RAISE EXCEPTION 'Condition-driven Tournament reason % lacks matching highest-priority producer (expected %)', NEW.terminal_reason, v_expected;
        END IF;
    ELSIF NEW.terminal_reason='VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME' THEN
        -- v1.1.27: FR-TRN-10 normal approval timeout; a higher-priority condition wins (Product §37.14).
        IF NEW.from_status IS DISTINCT FROM 'PENDING_VENUE_APPROVAL' OR NEW.occurred_at < t.approval_expires_at OR v_expected IS NOT NULL THEN
            RAISE EXCEPTION 'VENUE_DID_NOT_APPROVE_TOURNAMENT_IN_TIME requires PENDING_VENUE_APPROVAL at/after approvalExpiresAt with no higher-priority condition';
        END IF;
    ELSIF NEW.terminal_reason='VENUE_REJECTED_TOURNAMENT' THEN
        RAISE EXCEPTION 'VENUE_REJECTED_TOURNAMENT is the REJECTED reason, not a cancellation reason';
    ELSIF NEW.terminal_reason IN ('CREATOR_CANCELLED','VENUE_CANCELLED','ADMIN_CANCELLED','TOURNAMENT_OPERATIONAL_TERMINATION') THEN
        IF v_expected IS NOT NULL THEN
            RAISE EXCEPTION 'Explicit Tournament cancellation cannot bypass higher frozen reason %', v_expected;
        END IF;
    END IF;
    RETURN NULL;
END;
$function$;

-- ---------- F18 Venue Web Push subscriptions + notification catalogue (Product Owner decision A6; Product §52) ----------
CREATE OR REPLACE FUNCTION notification.guard_venue_push_subscription()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Push subscriptions are revoked, not deleted'; END IF;
 IF TG_OP='INSERT' THEN
   IF NEW.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'A new push subscription cannot be pre-revoked'; END IF;
   IF NEW.created_at>clock_timestamp() THEN RAISE EXCEPTION 'Push subscription created_at cannot be in the future'; END IF;
   RETURN NEW;
 END IF;
 IF NEW.id<>OLD.id OR NEW.venue_account_id<>OLD.venue_account_id OR NEW.endpoint<>OLD.endpoint OR NEW.p256dh_key<>OLD.p256dh_key
    OR NEW.auth_key<>OLD.auth_key OR NEW.created_at<>OLD.created_at THEN
   RAISE EXCEPTION 'Push subscription identity and keys are immutable; register a new row';
 END IF;
 IF OLD.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'Revoked push subscription is terminal'; END IF;
 IF NEW.last_seen_at<OLD.last_seen_at THEN RAISE EXCEPTION 'last_seen_at cannot move backwards'; END IF;
 RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_127_venue_push_subscription_guard ON notification.venue_push_subscription;
CREATE TRIGGER tr_127_venue_push_subscription_guard BEFORE INSERT OR UPDATE OR DELETE ON notification.venue_push_subscription
 FOR EACH ROW EXECUTE FUNCTION notification.guard_venue_push_subscription();
DROP TRIGGER IF EXISTS tr_127_venue_push_subscription_no_truncate ON notification.venue_push_subscription;
CREATE TRIGGER tr_127_venue_push_subscription_no_truncate BEFORE TRUNCATE ON notification.venue_push_subscription
 FOR EACH STATEMENT EXECUTE FUNCTION technical.reject_truncate();

