-- ---------- F03 no SECURITY DEFINER function is executable by PUBLIC ----------
DO $revoke_public_definer$
DECLARE f regprocedure;
BEGIN
 FOR f IN
   SELECT p.oid::regprocedure FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
    WHERE p.prosecdef
      AND n.nspname IN ('iam','geo','venue','resource','pricing','inventory','operations','booking','attendance',
                        'tournament','trust','loyalty','review','notification','config','audit','admin','technical')
      AND (p.proacl IS NULL OR EXISTS(SELECT 1 FROM aclexplode(p.proacl) a WHERE a.grantee=0 AND a.privilege_type='EXECUTE'))
 LOOP
   EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM PUBLIC',f);
 END LOOP;
END;
$revoke_public_definer$;

-- Callable entry points keep their intended callers (roles are created by the deployment-security SQL).
DO $grant_entrypoints$
BEGIN
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='e7gz_app_runtime') THEN
   GRANT EXECUTE ON FUNCTION iam.request_account_deletion(uuid,uuid) TO e7gz_app_runtime;
   GRANT EXECUTE ON FUNCTION review.report_review(uuid,uuid,text,text,uuid) TO e7gz_app_runtime;
   GRANT EXECUTE ON FUNCTION tournament.active_participant_count(uuid) TO e7gz_app_runtime;
   GRANT EXECUTE ON FUNCTION tournament.capacity_occupied_count(uuid) TO e7gz_app_runtime;
   GRANT EXECUTE ON FUNCTION tournament.assert_tournament_aggregate(uuid) TO e7gz_app_runtime;
   GRANT EXECUTE ON FUNCTION config.effective_numeric(text,timestamptz) TO e7gz_app_runtime;
 END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='e7gz_admin_runtime') THEN
   GRANT EXECUTE ON FUNCTION iam.complete_account_deletion_request(uuid,uuid) TO e7gz_admin_runtime;
   GRANT EXECUTE ON FUNCTION review.resolve_report(uuid,text,uuid) TO e7gz_admin_runtime;
   GRANT EXECUTE ON FUNCTION iam.anonymise_user(uuid,text) TO e7gz_admin_runtime;
   GRANT EXECUTE ON FUNCTION config.change_configuration(text,jsonb,text) TO e7gz_admin_runtime;
   GRANT EXECUTE ON FUNCTION tournament.active_participant_count(uuid) TO e7gz_admin_runtime;
   GRANT EXECUTE ON FUNCTION tournament.capacity_occupied_count(uuid) TO e7gz_admin_runtime;
   GRANT EXECUTE ON FUNCTION tournament.assert_tournament_aggregate(uuid) TO e7gz_admin_runtime;
   GRANT EXECUTE ON FUNCTION config.effective_numeric(text,timestamptz) TO e7gz_admin_runtime;
 END IF;
END;
$grant_entrypoints$;

